def _fixture_path(name: str) -> Path:
    return TEST_FIXTURE_DIR / name


def _load_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def _resolve_harness_path(raw_path: str | Path) -> Path:
    path = Path(raw_path)
    if path.is_absolute():
        return path
    harness_candidate = HARNESS_DIR / path
    if harness_candidate.exists():
        return harness_candidate
    repo_candidate = REPO_HARNESS_DIR / path
    if repo_candidate.exists():
        return repo_candidate
    repository_candidate = REPO_ROOT / path
    if repository_candidate.exists():
        return repository_candidate
    return harness_candidate


def _source_type_for(path: Path) -> str:
    suffix = path.suffix.lower()
    if suffix == ".pdf":
        return "pdf"
    if suffix in {".tex", ".latex"}:
        return "latex"
    if suffix in {".md", ".markdown"}:
        return "markdown"
    if suffix in {".html", ".htm"}:
        return "html"
    return "unknown"


def _markdown_sections(text: str, source_name: str) -> list[dict[str, str]]:
    sections: list[dict[str, str]] = []
    current: dict[str, Any] | None = None
    body: list[str] = []
    for line in text.splitlines():
        if line.startswith("## "):
            if current:
                current["text"] = "\n".join(body).strip()
                sections.append(current)
            title = line[3:].strip()
            section_id = title.lower().replace(" ", "-") or f"section-{len(sections) + 1}"
            current = {
                "section_id": section_id,
                "title": title,
                "source_anchor": f"{source_name}#{section_id}",
            }
            body = []
        elif current:
            body.append(line)
    if current:
        current["text"] = "\n".join(body).strip()
        sections.append(current)
    if not sections:
        sections.append({
            "section_id": "body",
            "title": "Body",
            "text": text.strip(),
            "source_anchor": f"{source_name}#body",
        })
    return sections


def _sentences(text: str) -> list[str]:
    normalized = " ".join(text.split())
    if not normalized:
        return []
    return [
        item.strip()
        for item in re.split(r"(?<=[.!?])\s+", normalized)
        if item.strip()
    ]


def _slug(value: str) -> str:
    slug = re.sub(r"[^a-z0-9]+", "-", value.lower()).strip("-")
    return slug or "item"


def _claim_testability(text: str) -> tuple[str, str | None]:
    lowered = text.lower()
    testable_markers = {
        "empirical",
        "evaluate",
        "improve",
        "metric",
        "produce",
        "regression",
        "result",
        "verify",
        "without introducing",
        "write",
    }
    if any(marker in lowered for marker in testable_markers):
        return "testable", None
    return "not_testable", "The sentence is descriptive and does not state a direct test condition."


def _paper_claims_raw(envelope: dict[str, Any]) -> dict[str, Any]:
    paper = _read_sample_paper(envelope)
    sections = list(paper.get("sections") or [])
    paper_id = str(paper.get("paper_id") or "paper-autosci-fixture")
    claims: list[dict[str, Any]] = []
    def section_rank(section: dict[str, Any]) -> int:
        title = str(section.get("title") or section.get("section_id") or "").lower()
        if any(keyword in title for keyword in ("result", "finding", "evidence")):
            return 0
        if "abstract" in title:
            return 1
        return 2

    claim_sections = sorted(
        [section for section in sections if isinstance(section, dict)],
        key=section_rank,
    )
    for section in claim_sections:
        if not isinstance(section, dict):
            continue
        title = str(section.get("title") or section.get("section_id") or "")
        if "method" in title.lower() or "procedure" in title.lower():
            continue
        anchor = str(section.get("source_anchor") or paper.get("source_ref") or paper_id)
        for sentence in _sentences(str(section.get("text") or ""))[:2]:
            testability, reason = _claim_testability(sentence)
            claim: dict[str, Any] = {
                "claim_id": f"claim-{len(claims) + 1:03d}",
                "text": sentence,
                "claim_type": "result" if testability == "testable" else "background",
                "source_anchor": anchor,
                "testability": testability,
                "evidence_ids": [paper_id, anchor],
            }
            if reason:
                claim["non_testable_reason"] = reason
            claims.append(claim)
            if len(claims) >= 3:
                break
        if len(claims) >= 3:
            break
    if not claims:
        anchor = str(paper.get("source_ref") or paper_id)
        claims.append({
            "claim_id": "claim-001",
            "text": "No grounded claim candidate was found in the input paper.",
            "claim_type": "background",
            "source_anchor": anchor,
            "testability": "not_testable",
            "non_testable_reason": "The input paper did not contain a usable claim sentence.",
            "evidence_ids": [paper_id, anchor],
        })
    return {
        "claims": claims,
        "limitations": [
            "Claim extraction is deterministic and section-based; claims remain unverified until a verifier runs.",
        ],
    }


def _method_steps(text: str) -> list[str]:
    sentences = _sentences(text)
    if not sentences:
        return ["No explicit procedure text was found in the input paper."]
    first = sentences[0]
    parts = [
        part.strip(" .")
        for part in re.split(r",\s+and\s+|,\s+|\s+and\s+", first)
        if part.strip(" .")
    ]
    if len(parts) >= 2:
        return [part[0].upper() + part[1:] if len(part) > 1 else part.upper() for part in parts[:5]]
    return sentences[:5]


def _paper_methods_raw(envelope: dict[str, Any]) -> dict[str, Any]:
    paper = _read_sample_paper(envelope)
    sections = [section for section in list(paper.get("sections") or []) if isinstance(section, dict)]
    method_sections = [
        section
        for section in sections
        if any(
            keyword in str(section.get("title") or section.get("section_id") or "").lower()
            for keyword in ("method", "approach", "workflow", "procedure")
        )
    ]
    if not method_sections and sections:
        method_sections = [sections[0]]
    paper_id = str(paper.get("paper_id") or "paper-autosci-fixture")
    methods: list[dict[str, Any]] = []
    for section in method_sections[:2]:
        text = str(section.get("text") or "")
        anchor = str(section.get("source_anchor") or paper.get("source_ref") or paper_id)
        title = str(section.get("title") or "Method")
        summary = (_sentences(text) or ["No explicit method summary was found in the input paper."])[0]
        methods.append({
            "method_id": f"method-{len(methods) + 1:03d}",
            "name": f"{title} protocol",
            "summary": summary,
            "procedure": _method_steps(text),
            "source_papers": [paper_id],
            "evidence_ids": [paper_id, anchor],
            "source_anchor": anchor,
        })
    if not methods:
        anchor = str(paper.get("source_ref") or paper_id)
        methods.append({
            "method_id": "method-001",
            "name": "No explicit method found",
            "summary": "The input paper did not contain a method section.",
            "procedure": ["Mark method extraction as incomplete for this paper."],
            "source_papers": [paper_id],
            "evidence_ids": [paper_id, anchor],
            "source_anchor": anchor,
        })
    return {
        "methods": methods,
        "limitations": [
            "Method extraction is deterministic and section-based; it does not infer hidden procedure steps.",
        ],
    }


def _read_sample_paper(envelope: dict[str, Any] | None = None, *, analyzed: bool = False) -> dict[str, Any]:
    inputs = dict((envelope or {}).get("inputs") or {})
    raw_path = inputs.get("paper_path") or _fixture_path("sample_paper.md")
    raw_path_text = str(raw_path)
    is_remote_source = raw_path_text.startswith(("http://", "https://"))
    paper_path = Path(raw_path_text) if is_remote_source else _resolve_harness_path(raw_path)
    if not is_remote_source and not paper_path.exists():
        return {
            "paper_id": "paper-missing",
            "title": "Missing paper source",
            "source_type": "unknown",
            "source_ref": str(raw_path),
            "identifiers": {"fixture": "autosci-phase9"},
            "abstract": "",
            "parse_status": "failed",
            "sections": [],
            "status": "failed",
            "limitations": [f"Paper source not found: {raw_path}"],
        }
    raw_root_raw = Path(str(inputs.get("raw_root") or "artifacts/autosci/workspace/raw"))
    raw_root = raw_root_raw if raw_root_raw.is_absolute() else HARNESS_DIR / raw_root_raw
    allow_network_fetch = str(inputs.get("allow_network_fetch", "true")).lower() not in {"0", "false", "no"}
    if os.environ.get("AUTOSCI_DISABLE_NETWORK_FETCH", "").lower() in {"1", "true", "yes"}:
        allow_network_fetch = False
    native_prepare = (
        _native_prepare_paper_source(envelope or {}, paper_path, raw_root, allow_network_fetch=allow_network_fetch)
        if not is_remote_source
        else {}
    )
    paper = read_paper_source(
        paper_path,
        raw_root=raw_root,
        workspace_root=HARNESS_DIR,
        repository_root=REPO_HARNESS_DIR,
        paper_id=str(inputs.get("paper_id") or f"paper-{paper_path.stem.replace('_', '-')}"),
        title=str(inputs.get("paper_title") or inputs.get("title") or inputs.get("pdf_title") or ""),
        arxiv_id=str(inputs.get("arxiv_id") or ""),
        allow_network_fetch=allow_network_fetch,
        analyzed=analyzed,
    )
    if native_prepare:
        payload = native_prepare.get("payload") if isinstance(native_prepare.get("payload"), dict) else {}
        preparation = paper.setdefault("preparation", {})
        preparation["native_prepare_paper_source"] = {
            "schema": str(payload.get("schema") or "autosci_prepare_paper_source_cli.v1"),
            "status": str(payload.get("status") or "unknown"),
            "ok": bool(payload.get("ok")),
            "canonical_ingest_path": str(payload.get("canonical_ingest_path") or ""),
            "prepared_path": payload.get("prepared_path"),
            "source_path": str(payload.get("source_path") or ""),
            "raw_root": str(payload.get("raw_root") or ""),
            "allow_network_fetch": payload.get("allow_network_fetch"),
        }
        identifiers = paper.setdefault("identifiers", {})
        identifiers["native_prepare_status"] = str(payload.get("status") or "unknown")
        paper.setdefault("artifacts", []).extend(native_prepare.get("artifacts") or [])
        if int(native_prepare.get("returncode") or 0) != 0:
            paper.setdefault("limitations", []).append(
                "Native prepare_paper_source.py did not complete; parser fallback evidence was retained."
            )
    return paper


def _native_prepare_paper_source(
    envelope: dict[str, Any],
    source_path: Path,
    raw_root: Path,
    *,
    allow_network_fetch: bool,
) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    output_dir = _output_dir(envelope, "ingest_paper")
    args = [
        "--raw-root",
        str(raw_root),
        "--source",
        str(source_path),
        "--workspace-root",
        str(HARNESS_DIR),
        "--repository-root",
        str(REPO_HARNESS_DIR),
    ]
    title = str(inputs.get("paper_title") or inputs.get("title") or inputs.get("pdf_title") or "").strip()
    if title:
        args.extend(["--title", title])
    arxiv_id = str(inputs.get("arxiv_id") or "").strip()
    if arxiv_id:
        args.extend(["--arxiv-id", arxiv_id])
    if not allow_network_fetch:
        args.append("--no-network-fetch")
    run = _run_root_tool_json(
        "prepare_paper_source.py",
        args,
        output_dir=output_dir,
        artifact_prefix="prepare_paper_source_native",
        timeout_env="AUTOSCI_PREPARE_PAPER_SOURCE_TIMEOUT_SECONDS",
    )
    payload = run.get("payload") if isinstance(run.get("payload"), dict) else {}
    payload_path = output_dir / "prepare_paper_source_native_payload.json"
    payload_artifact = _artifact("prepare_paper_source_native_payload_json", payload_path)
    _write_json_sidecar(payload_path, payload)
    run.setdefault("artifacts", []).append(payload_artifact)
    return run


def _rel(path: Path) -> str:
    """Relativize a resolved path for evidence.

    _resolve_harness_path also accepts REPO_ROOT-relative inputs, so this must
    try REPO_ROOT too or those paths fall through to an absolute machine path
    and leak local directory layout into committed evidence artifacts.
    """
    resolved = path.resolve()
    for root in (HARNESS_DIR, REPO_HARNESS_DIR, REPO_ROOT):
        try:
            return resolved.relative_to(Path(root).resolve()).as_posix()
        except (ValueError, OSError):
            continue
    return Path(path).as_posix()


def _output_dir(envelope: dict[str, Any], action: str) -> Path:
    configured = envelope.get("output_dir")
    if configured:
        out = Path(str(configured))
        if not out.is_absolute():
            out = HARNESS_DIR / out
        return out
    return HARNESS_DIR / "artifacts" / "autosci" / action


def _configured_output_path(
    envelope: dict[str, Any],
    key: str,
    default_path: Path,
    *,
    legacy_key: str | None = None,
    legacy_suffix: str | None = None,
) -> Path:
    outputs = envelope.get("outputs") if isinstance(envelope.get("outputs"), dict) else {}
    raw = outputs.get(key) if isinstance(outputs, dict) else None
    if not raw and legacy_key and isinstance(outputs, dict):
        legacy = str(outputs.get(legacy_key) or "")
        if legacy and (legacy_suffix is None or legacy.endswith(legacy_suffix)):
            raw = legacy
    if not raw:
        return default_path
    path = Path(str(raw))
    if not path.is_absolute():
        path = HARNESS_DIR / path
    return path


def _approval_path_entries(raw_values: Any) -> list[dict[str, Any]]:
    values = raw_values if isinstance(raw_values, list) else ([raw_values] if raw_values else [])
    entries: list[dict[str, Any]] = []
    for raw in values:
        raw_text = str(raw or "").strip()
        if not raw_text:
            continue
        if raw_text.startswith(("http://", "https://")):
            entries.append({
                "path": raw_text,
                "artifact_path": raw_text,
                "exists": False,
                "kind": "external_ref",
                "verifiable": False,
            })
            continue
        path = _resolve_harness_path(raw_text)
        entries.append({
            "path": raw_text,
            "artifact_path": _rel(path),
            "exists": path.exists(),
            "kind": "directory" if path.is_dir() else ("file" if path.is_file() else "missing"),
            "verifiable": True,
        })
    return entries


def _all_existing(entries: list[dict[str, Any]]) -> bool:
    return bool(entries) and all(bool(item.get("exists")) for item in entries)


def _missing_contract_items(label: str, entries: list[dict[str, Any]]) -> list[str]:
    if not entries:
        return [label]
    return [
        f"{label}:{item.get('path')}"
        for item in entries
        if not bool(item.get("exists"))
    ]


def _approval_authorization_request(
    *,
    action: str,
    side_effects: list[str],
    missing: list[str],
    inputs: dict[str, Any],
    approval_state: str,
) -> dict[str, Any]:
    stable_inputs = {
        key: value
        for key, value in sorted(inputs.items())
        if key
        not in {
            "approval_ref",
            "allowlist_evidence",
            "before_artifacts",
            "runtime_evidence",
            "after_artifacts",
            "execute_approved_side_effect",
            "policy_auto_execute_side_effect",
            "gate_mode",
            "autosci_mode",
        }
    }
    fingerprint = hashlib.sha256(
        json.dumps(
            {
                "action": action,
                "side_effects": side_effects,
                "missing": missing,
                "inputs": stable_inputs,
            },
            sort_keys=True,
            default=str,
        ).encode("utf-8")
    ).hexdigest()
    requested = {
        "approval_ref": "approval_ref" in missing,
        "allowlist_evidence": any(str(item).startswith("allowlist_evidence") for item in missing),
        "before_artifacts": any(str(item).startswith("before_artifacts") for item in missing),
        "runtime_evidence": any(str(item).startswith("runtime_evidence") for item in missing),
        "after_artifacts": any(str(item).startswith("after_artifacts") for item in missing),
    }
    return {
        "schema": "autosci_gate_authorization_request.v1",
        "status": "authorized" if not missing else "awaiting_authorization",
        "action": action,
        "approval_state": approval_state,
        "requested_side_effects": side_effects,
        "missing": missing,
        "requested_access": requested,
        "prompt": (
            "Grant approval and provide the missing approval/runtime artifacts, "
            "then rerun the same action with the supplied access patch."
        ),
        "continuation": {
            "schema": "autosci_gate_continuation.v1",
            "status": "ready" if not missing else "awaiting_authorization",
            "retriable": bool(missing),
            "same_envelope_supported": True,
            "request_fingerprint": fingerprint,
            "resume_strategy": "rerun_same_action_with_approval_patch",
            "access_patch": {
                "approval_ref": "<approval-ref>" if requested["approval_ref"] else "",
                "allowlist_evidence": ["<allowlist-evidence.json>"] if requested["allowlist_evidence"] else [],
                "before_artifacts": ["<before-artifact>"] if requested["before_artifacts"] else [],
                "runtime_evidence": ["<runtime-evidence.json>"] if requested["runtime_evidence"] else [],
                "after_artifacts": ["<after-artifact>"] if requested["after_artifacts"] else [],
                "execute_approved_side_effect": True,
            },
        },
        "non_error_contract": {
            "blocked_runs_exit_successfully": True,
            "evidence_status": "inconclusive",
            "approval_state": approval_state,
        },
    }


def _approval_contract(envelope: dict[str, Any], action: str, side_effects: list[str]) -> dict[str, Any]:
    inputs = envelope.get("inputs") if isinstance(envelope.get("inputs"), dict) else {}
    approval_ref = str(inputs.get("approval_ref") or "").strip()
    allowlist_entries = _approval_path_entries(inputs.get("allowlist_evidence"))
    runtime_entries = _approval_path_entries(inputs.get("runtime_evidence"))
    before_entries = _approval_path_entries(inputs.get("before_artifacts"))
    after_entries = _approval_path_entries(inputs.get("after_artifacts"))
    approved = bool(approval_ref and approval_ref.upper() != "N/A")
    allowlist_ready = _all_existing(allowlist_entries)
    before_ready = _all_existing(before_entries)
    runtime_ready = _all_existing(runtime_entries)
    after_ready = _all_existing(after_entries)
    ready_for_execution = approved and allowlist_ready and before_ready
    execution_verified = ready_for_execution and runtime_ready and after_ready
    missing: list[str] = []
    if not approved:
        missing.append("approval_ref")
    missing.extend(_missing_contract_items("allowlist_evidence", allowlist_entries))
    missing.extend(_missing_contract_items("before_artifacts", before_entries))
    missing.extend(_missing_contract_items("runtime_evidence", runtime_entries))
    missing.extend(_missing_contract_items("after_artifacts", after_entries))
    if execution_verified:
        approval_state = "verified"
    elif ready_for_execution:
        approval_state = "approved_pending_runtime"
    elif approved:
        approval_state = "approved_missing_preflight"
    else:
        approval_state = "approval_required"
    contract = {
        "schema": "autosci_approval_contract.v1",
        "action": action,
        "side_effects": side_effects,
        "approval_ref": approval_ref,
        "approval_state": approval_state,
        "approved": approved,
        "allowlist_ready": allowlist_ready,
        "before_ready": before_ready,
        "ready_for_execution": ready_for_execution,
        "runtime_ready": runtime_ready,
        "after_ready": after_ready,
        "execution_verified": execution_verified,
        "allowlist_evidence": allowlist_entries,
        "runtime_evidence": runtime_entries,
        "before_artifacts": before_entries,
        "after_artifacts": after_entries,
        "missing": missing,
    }
    contract["authorization_request"] = _approval_authorization_request(
        action=action,
        side_effects=side_effects,
        missing=missing,
        inputs=dict(inputs),
        approval_state=approval_state,
    )
    return contract


def _approval_contract_limitations(contract: dict[str, Any]) -> list[str]:
    if contract.get("execution_verified") is True:
        return []
    missing = contract.get("missing") if isinstance(contract.get("missing"), list) else []
    suffix = f": {', '.join(str(item) for item in missing)}" if missing else "."
    return [f"Approval/runtime evidence contract is not fully verified{suffix}"]


def _refresh_approval_contract(contract: dict[str, Any]) -> dict[str, Any]:
    allowlist_entries = contract.get("allowlist_evidence") if isinstance(contract.get("allowlist_evidence"), list) else []
    runtime_entries = contract.get("runtime_evidence") if isinstance(contract.get("runtime_evidence"), list) else []
    before_entries = contract.get("before_artifacts") if isinstance(contract.get("before_artifacts"), list) else []
    after_entries = contract.get("after_artifacts") if isinstance(contract.get("after_artifacts"), list) else []
    for entries in (allowlist_entries, runtime_entries, before_entries, after_entries):
        for entry in entries:
            if not isinstance(entry, dict):
                continue
            raw_path = str(entry.get("artifact_path") or entry.get("path") or "").strip()
            if not raw_path:
                continue
            candidate = _resolve_harness_path(raw_path)
            exists = candidate.exists()
            entry.update(
                {
                    "exists": exists,
                    "kind": "directory" if exists and candidate.is_dir() else "file",
                    "verifiable": exists,
                }
            )
    approved = bool(str(contract.get("approval_ref") or "").strip())
    allowlist_ready = _all_existing(allowlist_entries)
    before_ready = _all_existing(before_entries)
    runtime_ready = _all_existing(runtime_entries)
    after_ready = _all_existing(after_entries)
    ready_for_execution = approved and allowlist_ready and before_ready
    execution_verified = ready_for_execution and runtime_ready and after_ready
    missing: list[str] = []
    if not approved:
        missing.append("approval_ref")
    missing.extend(_missing_contract_items("allowlist_evidence", allowlist_entries))
    missing.extend(_missing_contract_items("before_artifacts", before_entries))
    missing.extend(_missing_contract_items("runtime_evidence", runtime_entries))
    missing.extend(_missing_contract_items("after_artifacts", after_entries))
    contract.update({
        "approved": approved,
        "allowlist_ready": allowlist_ready,
        "before_ready": before_ready,
        "ready_for_execution": ready_for_execution,
        "runtime_ready": runtime_ready,
        "after_ready": after_ready,
        "execution_verified": execution_verified,
        "missing": missing,
        "approval_state": "verified"
        if execution_verified
            else ("approved_pending_runtime" if ready_for_execution else ("approved_missing_preflight" if approved else "approval_required")),
    })
    contract["authorization_request"] = _approval_authorization_request(
        action=str(contract.get("action") or "unknown"),
        side_effects=[str(item) for item in contract.get("side_effects") or []],
        missing=missing,
        inputs={},
        approval_state=str(contract.get("approval_state") or "approval_required"),
    )
    return contract


def _contract_existing_artifacts(contract: dict[str, Any], key: str, artifact_type: str) -> list[dict[str, str]]:
    entries = contract.get(key) if isinstance(contract.get(key), list) else []
    artifacts: list[dict[str, str]] = []
    for entry in entries:
        if not isinstance(entry, dict) or not entry.get("exists"):
            continue
        path = str(entry.get("artifact_path") or entry.get("path") or "").strip()
        if path:
            artifacts.append({"type": artifact_type, "path": path})
    return artifacts


def _write_approval_contract_sidecar(envelope: dict[str, Any], action: str, contract: dict[str, Any]) -> dict[str, str]:
    output_dir = _output_dir(envelope, action)
    path = _configured_output_path(
        envelope,
        "approval_contract_path",
        output_dir / f"{action}_approval_contract.json",
    )
    return {"type": "approval_contract_json", "path": _write_json_sidecar(path, contract)}


def _decision_payload(decision: GateDecision | dict[str, Any]) -> dict[str, Any]:
    if isinstance(decision, GateDecision):
        return decision.to_dict()
    return dict(decision)


def _gate_decision(envelope: dict[str, Any], action: str, side_effects: list[str]) -> dict[str, Any]:
    return decide_gate(action, side_effects, envelope=envelope).to_dict()


def _policy_execute_side_effect(decision: dict[str, Any], inputs: dict[str, Any]) -> bool:
    if bool(decision.get("execute_side_effects")):
        return True
    return bool(inputs.get("execute_approved_side_effect"))


def _write_policy_decision_sidecar(
    envelope: dict[str, Any],
    action: str,
    decision: GateDecision | dict[str, Any],
) -> dict[str, str]:
    output_dir = _output_dir(envelope, action)
    path = output_dir / f"{action}_gate_policy_decision.json"
    return {"type": "gate_policy_decision_json", "path": _write_json_sidecar(path, _decision_payload(decision))}


def _side_effect_access_required(decision: dict[str, Any]) -> bool:
    if not decision:
        return False
    side_effects = [str(item) for item in decision.get("side_effects") or [] if str(item).strip()]
    material = [item for item in side_effects if item not in {"read_local", "write_artifact"}]
    return bool(material and not decision.get("execute_side_effects"))


def _side_effect_access_continuation(
    envelope: dict[str, Any],
    action: str,
    decision: dict[str, Any],
    side_effects: list[str],
) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    stable_inputs = {
        key: value
        for key, value in sorted(inputs.items())
        if key not in {"approval_ref", "gate_mode", "autosci_mode", "execute_approved_side_effect", "policy_auto_execute_side_effect"}
    }
    fingerprint = hashlib.sha256(
        json.dumps(
            {
                "action": action,
                "side_effects": side_effects,
                "inputs": stable_inputs,
            },
            sort_keys=True,
            default=str,
        ).encode("utf-8")
    ).hexdigest()
    env_opt_ins = [
        hint
        for effect, hint in _SIDE_EFFECT_ACCESS_ENV_HINTS.items()
        if effect in side_effects
    ]
    return {
        "schema": "autosci_side_effect_continuation.v1",
        "status": "awaiting_side_effect_access",
        "retriable": True,
        "action": action,
        "request_fingerprint": fingerprint,
        "same_envelope_supported": True,
        "resume_strategy": "rerun_same_action_with_access_patch",
        "access_patch_options": [
            {
                "name": "bounded_policy_mode",
                "inputs": {"gate_mode": "parity_demo"},
                "env": env_opt_ins,
                "limitations": [
                    "Use only for bounded local parity side effects. Network still requires SOLAR_AUTOSCI_ALLOW_NETWORK=1."
                ],
            },
            {
                "name": "native_policy_mode",
                "inputs": {"gate_mode": "autosci_native"},
                "env": [],
                "limitations": [
                    "Bypasses Solar gate blocking; runtime evidence remains required before claiming full parity."
                ],
            },
            {
                "name": "hitl_approval",
                "inputs": {
                    "approval_ref": "<approval-ref>",
                    "execute_approved_side_effect": True,
                },
                "env": env_opt_ins,
                "required_artifacts": [
                    "allowlist_evidence",
                    "before_artifact",
                    "runtime_evidence",
                    "after_artifact",
                ],
                "limitations": [
                    "Strict HITL resume must provide enough typed artifacts for the action approval contract to verify."
                ],
            },
        ],
        "non_error_contract": {
            "blocked_runs_exit_successfully": True,
            "evidence_status": "inconclusive",
            "side_effect_access_status": SIDE_EFFECT_ACCESS_REQUIRED_STATUS,
        },
    }


def _side_effect_access_request(
    envelope: dict[str, Any],
    action: str,
    native_skill: str,
    decision: dict[str, Any],
    *,
    requested_side_effects: list[str] | None = None,
    blockers: list[str] | None = None,
    required_inputs: list[str] | None = None,
) -> tuple[dict[str, Any], dict[str, str]]:
    decision_payload = _decision_payload(decision)
    side_effects = [
        str(item)
        for item in (requested_side_effects or decision_payload.get("side_effects") or [])
        if str(item).strip()
    ]
    risky_hints = [
        hint
        for effect, hint in _SIDE_EFFECT_ACCESS_ENV_HINTS.items()
        if effect in side_effects
    ]
    payload = {
        "schema": "autosci_side_effect_access_request.v1",
        "generated_at": datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        "action": action,
        "native_skill": native_skill,
        "status": SIDE_EFFECT_ACCESS_REQUIRED_STATUS,
        "requested_side_effects": side_effects,
        "gate_policy": {
            "mode": decision_payload.get("mode"),
            "allowed": bool(decision_payload.get("allowed")),
            "blocked": bool(decision_payload.get("blocked")),
            "execute_side_effects": bool(decision_payload.get("execute_side_effects")),
            "require_hitl": bool(decision_payload.get("require_hitl")),
            "require_approval_ref": bool(decision_payload.get("require_approval_ref")),
            "synthetic_approval_ref": str(decision_payload.get("synthetic_approval_ref") or ""),
        },
        "blocking_reasons": [
            *[str(item) for item in decision_payload.get("reasons") or [] if str(item).strip()],
            *[str(item) for item in decision_payload.get("warnings") or [] if str(item).strip()],
            *[str(item) for item in blockers or [] if str(item).strip()],
        ],
        "requested_access": {
            "approval_ref": bool(decision_payload.get("require_approval_ref")),
            "runtime_evidence": bool(decision_payload.get("require_runtime_evidence")),
            "before_after_artifacts": bool(decision_payload.get("require_before_after_artifacts")),
            "environment_opt_ins": risky_hints,
            "allowed_write_roots": list(decision_payload.get("allowed_write_roots") or []),
        },
        "required_inputs": [str(item) for item in required_inputs or [] if str(item).strip()],
        "continuation": _side_effect_access_continuation(
            envelope,
            action,
            decision_payload,
            side_effects,
        ),
        "how_to_allow": [
            "Re-run with an AutoSci gate mode that may execute the requested side effects, such as `--gate-mode parity_demo`, `--gate-mode unsafe_native`, or `--gate-mode autosci_native`, depending on risk.",
            "For risky native side effects, set the explicit SOLAR_AUTOSCI_ALLOW_* opt-in variables listed in requested_access.environment_opt_ins.",
            "When strict HITL is required, provide approval_ref plus before/allowlist/runtime/after evidence artifacts instead of relying on a silent dry run.",
        ],
        "limitations": [
            "Protected native side effects were not executed for this action.",
            "This request is an access boundary, not proof that the side effects completed.",
        ],
    }
    path = _output_dir(envelope, action) / f"{action}_side_effect_access_request.json"
    artifact = {"type": "side_effect_access_request_json", "path": _write_json_sidecar(path, payload)}
    return payload, artifact


def _append_unique_artifact(artifacts: list[dict[str, Any]], artifact: dict[str, Any]) -> None:
    artifact_path = str(artifact.get("path") or "").strip()
    artifact_type = str(artifact.get("type") or "").strip()
    if not artifact_path or not artifact_type:
        return
    if any(
        isinstance(item, dict)
        and str(item.get("path") or "") == artifact_path
        and str(item.get("type") or "") == artifact_type
        for item in artifacts
    ):
        return
    artifacts.append(artifact)


def _attach_side_effect_access_request(
    evidence: dict[str, Any],
    payload: dict[str, Any],
    artifact: dict[str, str],
    *,
    mark_inconclusive: bool = True,
) -> dict[str, Any]:
    if mark_inconclusive:
        evidence["status"] = "inconclusive"
    outputs = evidence.setdefault("outputs", {})
    outputs["side_effect_access_required"] = True
    outputs["side_effect_access_status"] = SIDE_EFFECT_ACCESS_REQUIRED_STATUS
    outputs["side_effect_access_request"] = payload
    outputs.setdefault("blocking_reasons", [])
    if isinstance(outputs["blocking_reasons"], list):
        outputs["blocking_reasons"].extend(str(item) for item in payload.get("blocking_reasons") or [])
    artifacts = evidence.setdefault("artifacts", [])
    if isinstance(artifacts, list):
        _append_unique_artifact(artifacts, artifact)
    limitations = evidence.setdefault("limitations", [])
    if isinstance(limitations, list):
        limitations.append("Side-effect access is required; no protected native side effects were executed.")
    return evidence


def _write_policy_allowlist_sidecar(
    envelope: dict[str, Any],
    action: str,
    decision: GateDecision | dict[str, Any],
    payload: dict[str, Any],
) -> dict[str, str]:
    output_dir = _output_dir(envelope, action)
    decision_payload = _decision_payload(decision)
    body = {
        "schema": "autosci_gate_policy_allowlist.v1",
        "action": action,
        "mode": decision_payload.get("mode"),
        "synthetic_approval_ref": decision_payload.get("synthetic_approval_ref"),
        **payload,
        "limitations": [
            f"Synthetic allowlist generated by AutoSci gate policy mode `{decision_payload.get('mode')}`.",
            "This is not a human approval artifact.",
            *[str(item) for item in payload.get("limitations") or [] if str(item).strip()],
        ],
    }
    path = output_dir / f"{action}_gate_policy_allowlist.json"
    return {"type": "gate_policy_allowlist_json", "path": _write_json_sidecar(path, body)}


def _policy_contract_entry(artifact: dict[str, str]) -> dict[str, Any]:
    path = str(artifact.get("path") or "").strip()
    return {
        "path": path,
        "artifact_path": path,
        "exists": bool(path),
        "kind": "file",
        "verifiable": bool(path),
    }


def _apply_policy_approval_to_contract(
    contract: dict[str, Any],
    decision: dict[str, Any],
    policy_artifact: dict[str, str],
    allowlist_artifact: dict[str, str] | None = None,
) -> dict[str, Any]:
    synthetic_ref = str(decision.get("synthetic_approval_ref") or "").strip()
    if not synthetic_ref:
        return contract
    contract["approval_ref"] = synthetic_ref
    contract["policy_auto_approved"] = True
    contract["policy_decision"] = decision
    policy_entry = _policy_contract_entry(policy_artifact)
    allowlist_entry = _policy_contract_entry(allowlist_artifact or policy_artifact)
    if allowlist_entry["exists"]:
        entries = contract.setdefault("allowlist_evidence", [])
        if not any(isinstance(item, dict) and item.get("artifact_path") == allowlist_entry["artifact_path"] for item in entries):
            entries.append(dict(allowlist_entry))
    if policy_entry["exists"]:
        entries = contract.setdefault("before_artifacts", [])
        if not any(isinstance(item, dict) and item.get("artifact_path") == policy_entry["artifact_path"] for item in entries):
            entries.append(dict(policy_entry))
    contract = _refresh_approval_contract(contract)
    if contract.get("ready_for_execution") is True and contract.get("execution_verified") is not True:
        contract["approval_state"] = "policy_auto_approved_pending_runtime"
    elif contract.get("execution_verified") is True:
        contract["approval_state"] = "policy_auto_verified"
    return contract


def _policy_prepare_auto_contract(
    envelope: dict[str, Any],
    action: str,
    side_effects: list[str],
    contract: dict[str, Any],
    *,
    allowlist_payload: dict[str, Any] | None = None,
) -> tuple[dict[str, Any], dict[str, Any], list[dict[str, str]]]:
    decision = _gate_decision(envelope, action, side_effects)
    artifacts = [_write_policy_decision_sidecar(envelope, action, decision)]
    if decision.get("execute_side_effects"):
        allowlist_artifact: dict[str, str] | None = None
        if allowlist_payload is not None:
            allowlist_artifact = _write_policy_allowlist_sidecar(envelope, action, decision, allowlist_payload)
            artifacts.append(allowlist_artifact)
        contract = _apply_policy_approval_to_contract(
            contract,
            decision,
            artifacts[0],
            allowlist_artifact=allowlist_artifact,
        )
        inputs = envelope.setdefault("inputs", {})
        inputs["execute_approved_side_effect"] = True
        inputs["policy_auto_execute_side_effect"] = True
        if decision.get("synthetic_approval_ref") and not str(inputs.get("approval_ref") or "").strip():
            inputs["approval_ref"] = str(decision.get("synthetic_approval_ref") or "")
    return contract, decision, artifacts


def _policy_gate_requested(envelope: dict[str, Any]) -> bool:
    inputs = envelope.get("inputs") if isinstance(envelope.get("inputs"), dict) else {}
    return bool(
        str(inputs.get("gate_mode") or inputs.get("autosci_mode") or "").strip()
        or str(os.environ.get("SOLAR_AUTOSCI_GATE_MODE") or "").strip()
    )


def _policy_prepare_auto_contract_if_needed(
    envelope: dict[str, Any],
    action: str,
    side_effects: list[str],
    contract: dict[str, Any],
    *,
    allowlist_payload: dict[str, Any] | None = None,
) -> tuple[dict[str, Any], dict[str, Any], list[dict[str, str]]]:
    if not _policy_gate_requested(envelope) or _local_mutation_requested(envelope):
        return contract, {}, []
    return _policy_prepare_auto_contract(
        envelope,
        action,
        side_effects,
        contract,
        allowlist_payload=allowlist_payload,
    )


def _attach_policy_decision(evidence: dict[str, Any], decision: GateDecision | dict[str, Any]) -> dict[str, Any]:
    payload = _decision_payload(decision)
    evidence.setdefault("outputs", {})["policy_decision"] = payload
    provenance = evidence.setdefault("provenance", {})
    provenance["gate_policy"] = {
        "mode": payload.get("mode"),
        "action": payload.get("action"),
        "allowed": payload.get("allowed"),
        "execute_side_effects": payload.get("execute_side_effects"),
        "proof_required": payload.get("proof_required"),
        "proof_best_effort": payload.get("proof_best_effort"),
        "synthetic_approval_ref": payload.get("synthetic_approval_ref"),
    }
    return evidence


def _attach_policy_decision_if_present(evidence: dict[str, Any], decision: dict[str, Any]) -> dict[str, Any]:
    if not decision:
        return evidence
    return _attach_policy_decision(evidence, decision)


def _contract_entry_from_path(path: str | Path) -> dict[str, Any]:
    path_text = _rel(path) if isinstance(path, Path) else str(path or "").strip()
    candidate = _resolve_harness_path(path_text) if path_text else Path()
    exists = bool(path_text and candidate.exists())
    return {
        "path": path_text,
        "artifact_path": path_text,
        "exists": exists,
        "kind": "directory" if exists and candidate.is_dir() else "file",
        "verifiable": exists,
    }


def _append_contract_entry(contract: dict[str, Any], key: str, path: str | Path) -> None:
    entry = _contract_entry_from_path(path)
    if not entry.get("artifact_path") or not entry.get("exists"):
        return
    entries = contract.setdefault(key, [])
    if not isinstance(entries, list):
        contract[key] = entries = []
    for item in entries:
        if not isinstance(item, dict):
            continue
        if str(item.get("artifact_path") or item.get("path") or "") == str(entry["artifact_path"]):
            item.update(entry)
            return
    entries.append(entry)


def _append_local_mutation_runtime_to_contract(
    envelope: dict[str, Any],
    action: str,
    contract: dict[str, Any],
    *,
    command_run: str,
    evidence_ids: list[str],
    after_refs: list[str | Path],
    runtime_fields: dict[str, Any] | None = None,
    limitations: list[str] | None = None,
) -> dict[str, str]:
    existing_after_refs = [
        ref
        for ref in after_refs
        if str(ref or "").strip()
        and _contract_entry_from_path(ref).get("exists")
    ]
    payload = _runtime_evidence_payload(
        envelope,
        action=action,
        status="completed",
        approval_ref=str(contract.get("approval_ref") or ""),
        command_run=command_run,
        exit_code=0,
        evidence_ids=_unique_strings(evidence_ids),
        checks=[
            {
                "check": "local_mutation_applied",
                "status": "ok",
                "detail": f"{len(existing_after_refs)} after artifact(s) recorded.",
            }
        ],
        runtime_fields={
            "mutation_applied": True,
            "after_refs": [
                str(_contract_entry_from_path(ref).get("artifact_path") or "")
                for ref in existing_after_refs
            ],
            **dict(runtime_fields or {}),
        },
        artifacts=[
            {"type": "local_mutation_after_artifact", "path": str(_contract_entry_from_path(ref).get("artifact_path") or "")}
            for ref in existing_after_refs
        ],
        limitations=limitations or ["Local writeback executed through the approved AutoSci side-effect path."],
    )
    runtime_rel = _write_json_sidecar(
        _output_dir(envelope, action) / f"{action}_local_mutation_runtime_evidence.json",
        payload,
    )
    _append_contract_entry(contract, "runtime_evidence", runtime_rel)
    _append_contract_entry(contract, "after_artifacts", runtime_rel)
    for ref in existing_after_refs:
        _append_contract_entry(contract, "after_artifacts", ref)
    _refresh_approval_contract(contract)
    return {"type": f"{action}_local_mutation_runtime_evidence_json", "path": runtime_rel}


def _runtime_records(contract: dict[str, Any]) -> tuple[list[dict[str, Any]], list[str]]:
    records: list[dict[str, Any]] = []
    errors: list[str] = []
    entries = contract.get("runtime_evidence") if isinstance(contract.get("runtime_evidence"), list) else []
    for entry in entries:
        if not isinstance(entry, dict) or not entry.get("exists"):
            continue
        raw_path = str(entry.get("path") or entry.get("artifact_path") or "").strip()
        if not raw_path:
            continue
        path = _resolve_harness_path(raw_path)
        if path.is_dir():
            errors.append(f"runtime evidence is a directory: {_rel(path)}")
            continue
        try:
            text = path.read_text(encoding="utf-8", errors="replace")
        except OSError as exc:
            errors.append(f"runtime evidence unreadable: {_rel(path)}: {exc}")
            continue
        try:
            payload = json.loads(text)
        except json.JSONDecodeError:
            records.append({"text": text, "source_path": _rel(path)})
            continue
        if isinstance(payload, dict):
            payload.setdefault("source_path", _rel(path))
            records.append(payload)
        elif isinstance(payload, list):
            for item in payload:
                if isinstance(item, dict):
                    item.setdefault("source_path", _rel(path))
                    records.append(item)
                else:
                    records.append({"value": item, "source_path": _rel(path)})
        else:
            records.append({"value": payload, "source_path": _rel(path)})
    return records, errors


def _truthy(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return value != 0
    return str(value or "").strip().lower() in {"1", "true", "yes", "ok", "pass", "passed", "success", "completed"}


def _status_ok(value: Any) -> bool:
    return str(value or "").strip().lower() in {"ok", "pass", "passed", "success", "completed", "succeeded"}


def _field(record: dict[str, Any], *keys: str) -> Any:
    for key in keys:
        if key in record:
            return record[key]
    outputs = record.get("outputs") if isinstance(record.get("outputs"), dict) else {}
    for key in keys:
        if key in outputs:
            return outputs[key]
    runtime = outputs.get("runtime") if isinstance(outputs.get("runtime"), dict) else {}
    for key in keys:
        if key in runtime:
            return runtime[key]
    result = outputs.get("result") if isinstance(outputs.get("result"), dict) else {}
    for key in keys:
        if key in result:
            return result[key]
    return None


def _runtime_exit_ok(record: dict[str, Any]) -> bool:
    exit_code = _field(record, "exit_code", "returncode", "compile_exit_code")
    if exit_code is not None:
        try:
            return int(exit_code) == 0
        except (TypeError, ValueError):
            return False
    return _truthy(_field(record, "success", "ok", "completed")) or _status_ok(_field(record, "status"))


def _record_path_exists(record: dict[str, Any], *keys: str) -> bool:
    for key in keys:
        raw = _field(record, key)
        values = raw if isinstance(raw, list) else ([raw] if raw else [])
        for value in values:
            if not isinstance(value, str) or not value.strip():
                continue
            if _resolve_harness_path(value).exists():
                return True
    return False


def _candidate_from_runtime(raw: dict[str, Any], index: int) -> dict[str, Any] | None:
    title = str(raw.get("title") or raw.get("paper_title") or "").strip()
    if not title:
        return None
    source_ref = str(raw.get("source_ref") or raw.get("url") or raw.get("pdf_url") or raw.get("arxiv_id") or "").strip()
    channels = raw.get("source_channels") if isinstance(raw.get("source_channels"), list) else []
    if not channels:
        channels = ["arxiv"] if raw.get("arxiv_id") or "arxiv" in source_ref.lower() else ["approved_runtime"]
    normalized_channels = ["search_s2" if str(item).strip() == "s2_search" else str(item).strip() for item in channels]
    try:
        score = float(raw.get("ranking_score", 1.0))
    except (TypeError, ValueError):
        score = 1.0
    candidate = {
        "candidate_id": str(raw.get("candidate_id") or raw.get("paper_id") or raw.get("arxiv_id") or f"runtime-candidate-{index:03d}"),
        "title": title,
        "source_channels": [item for item in normalized_channels if item],
        "ranking_score": score,
        "ranking_rationale": str(raw.get("ranking_rationale") or "Approved runtime evidence supplied this discovery candidate."),
        "dedup_status": str(raw.get("dedup_status") or "unknown"),
        "fetch_status": str(raw.get("fetch_status") or "fetched"),
    }
    year = raw.get("year") or raw.get("published_year") or raw.get("publication_year")
    if year:
        candidate["year"] = str(year)
    if source_ref:
        candidate["source_ref"] = source_ref
    if raw.get("abstract"):
        candidate["abstract"] = str(raw["abstract"])
    for key in ("relevance_gate", "relevance_evidence"):
        if isinstance(raw.get(key), dict):
            candidate[key] = dict(raw[key])
    return candidate


def _runtime_candidates(records: list[dict[str, Any]], *, limit: int) -> list[dict[str, Any]]:
    candidates: list[dict[str, Any]] = []
    for record in records:
        raw_candidates = _field(record, "candidates", "papers", "items")
        if isinstance(raw_candidates, dict):
            raw_candidates = [raw_candidates]
        if not isinstance(raw_candidates, list):
            raw_candidates = [record] if record.get("title") else []
        for raw in raw_candidates:
            if not isinstance(raw, dict):
                continue
            candidate = _candidate_from_runtime(raw, len(candidates) + 1)
            if candidate:
                candidates.append(candidate)
            if len(candidates) >= limit:
                return candidates
    return candidates


GENERIC_SOURCE_CHANNELS = {
    "approved_runtime",
    "fixture",
    "local_fixture",
    "runtime",
    "unknown",
}

LOCAL_WIKI_SOURCE_CHANNELS = {
    "local_wiki",
    "wiki",
    "wiki_source",
    "workspace_wiki",
}


def _source_provider_collection_mode(provider_channels: list[str]) -> str:
    normalized = {
        channel.strip().lower()
        for channel in provider_channels
        if channel.strip()
    }
    if normalized and normalized.issubset(LOCAL_WIKI_SOURCE_CHANNELS):
        return "native_autosci_replay"
    return "live_provider"


def _source_provider_runtime_description(native_skill: str, collection_mode: str) -> str:
    if collection_mode == "native_autosci_replay":
        return f"Completed non-fixture local wiki/source evidence for AutoSci `{native_skill}` parity."
    return f"Completed provider-backed source evidence for AutoSci `{native_skill}` parity."


def _resolve_root_tool(tool_name: str) -> tuple[Path | None, Path | None]:
    """Resolve a helper without escaping an installed runtime."""

    if Path(tool_name).name != tool_name:
        return None, None
    runtime_tool = (HARNESS_DIR / "tools" / tool_name).resolve()
    if runtime_tool.is_file():
        return runtime_tool, HARNESS_DIR
    source_root = REPO_HARNESS_DIR.parent.resolve()
    source_tool = source_root / "tools" / tool_name
    if (source_root / ".git").is_dir() and source_tool.is_file():
        return source_tool, source_root
    return None, None


def _run_root_tool_json(
    tool_name: str,
    args: list[str],
    *,
    output_dir: Path,
    artifact_prefix: str,
    timeout_env: str,
    timeout_default: int = 60,
) -> dict[str, Any]:
    _mkdir_path_long_path(output_dir)
    tool_path, tool_cwd = _resolve_root_tool(tool_name)
    command = [sys.executable, str(tool_path), *args] if tool_path is not None else []
    timeout = int(os.environ.get(timeout_env, str(timeout_default)))
    env = dict(os.environ)
    env["HARNESS_DIR"] = str(HARNESS_DIR)
    env["SOLAR_AUTOSCI_OUTPUT_HARNESS"] = str(HARNESS_DIR)
    if tool_path is None or tool_cwd is None:
        returncode = 1
        stdout = ""
        stderr = (
            f"Native helper {tool_name!r} is unavailable inside the selected runtime; "
            "the provider-backed runtime path remains eligible."
        )
    else:
        try:
            proc = subprocess.run(
                command,
                cwd=tool_cwd,
                env=env,
                text=True,
                encoding="utf-8",
                errors="replace",
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                check=False,
                timeout=timeout,
            )
            returncode = proc.returncode
            stdout = proc.stdout
            stderr = proc.stderr
        except (OSError, subprocess.TimeoutExpired) as exc:
            returncode = 1
            stdout = ""
            stderr = str(exc)
    stdout_path = _write_text_sidecar(output_dir / f"{artifact_prefix}_stdout.json", stdout)
    stderr_path = _write_text_sidecar(output_dir / f"{artifact_prefix}_stderr.txt", stderr)
    payload: dict[str, Any] = {}
    if stdout.strip():
        try:
            parsed = json.loads(stdout)
            if isinstance(parsed, dict):
                payload = parsed
            else:
                payload = {"status": "failed", "error": "Native tool stdout JSON was not an object."}
        except json.JSONDecodeError as exc:
            payload = {
                "status": "failed",
                "error": f"Native tool stdout was not JSON: {exc}",
                "stdout_preview": stdout[:1000],
            }
    return {
        "returncode": returncode,
        "payload": payload,
        "stdout": stdout,
        "stderr": stderr,
        "command": command,
        "artifacts": [
            {"type": f"{artifact_prefix}_stdout_json", "path": stdout_path},
            {"type": f"{artifact_prefix}_stderr", "path": stderr_path},
        ],
    }


def _source_provider_boundary(
    records: list[dict[str, Any]],
    candidates: list[dict[str, Any]],
    *,
    action: str,
) -> dict[str, Any]:
    channels = _unique_strings([
        str(channel)
        for candidate in candidates
        if isinstance(candidate, dict)
        for channel in (candidate.get("source_channels") if isinstance(candidate.get("source_channels"), list) else [])
        if str(channel).strip()
    ])
    provider_channels = [channel for channel in channels if channel.strip().lower() not in GENERIC_SOURCE_CHANNELS]
    candidate_ids = _unique_strings([
        str(candidate.get("candidate_id") or candidate.get("paperId") or candidate.get("title") or "")
        for candidate in candidates
        if isinstance(candidate, dict)
    ])
    runtime_sources = _unique_strings([
        str(record.get("source_path") or "")
        for record in records
        if isinstance(record, dict) and str(record.get("source_path") or "").strip()
    ])
    invalid_reasons: list[str] = []
    if not candidates:
        invalid_reasons.append("no source candidates were present")
    if not provider_channels:
        invalid_reasons.append("no non-fixture provider source channel was present")
    completed = bool(candidates and provider_channels)
    return {
        "schema": "autosci_source_provider_boundary.v1",
        "action": action,
        "status": "completed" if completed else "incomplete",
        "completed": completed,
        "candidate_count": len(candidates),
        "candidate_ids": candidate_ids,
        "source_channels": channels,
        "provider_channels": provider_channels,
        "generic_channels": [channel for channel in channels if channel.strip().lower() in GENERIC_SOURCE_CHANNELS],
        "runtime_record_sources": runtime_sources,
        "invalid_reasons": invalid_reasons,
        "limitations": [] if completed else ["Source runtime evidence did not prove a non-fixture provider channel."],
    }


def _discover_requirement_values(raw: Any) -> list[str]:
    values: list[str] = []
    if isinstance(raw, str):
        text = raw.strip()
        if not text:
            return []
        parts = re.split(r"[;\n]|,\s+(?=[A-Za-z0-9])", text)
        return _unique_strings([
            re.sub(r"^(?:and|or)\s+", "", part.strip(" -:\t"), flags=re.IGNORECASE)
            for part in parts
            if part.strip(" -:\t")
        ])
    if isinstance(raw, dict):
        for key in ("text", "question", "criterion", "name", "label", "requirement", "topic"):
            if str(raw.get(key) or "").strip():
                values.extend(_discover_requirement_values(str(raw[key])))
        return _unique_strings(values)
    if isinstance(raw, list):
        for item in raw:
            values.extend(_discover_requirement_values(item))
    return _unique_strings(values)


def _discover_declared_scope(envelope: dict[str, Any], raw: dict[str, Any]) -> dict[str, Any]:
    inputs = envelope.get("inputs") if isinstance(envelope.get("inputs"), dict) else {}
    query = str(raw.get("query") or inputs.get("query") or inputs.get("topic") or "")
    criteria: list[str] = []
    questions: list[str] = []
    scope_topics: list[str] = []
    for key in (
        "required_criteria",
        "criteria",
        "must_cover",
        "required_coverage",
        "coverage_requirements",
        "evaluation_criteria",
    ):
        criteria.extend(_discover_requirement_values(inputs.get(key) or raw.get(key)))
    for key in ("framing_questions", "questions", "open_questions", "unresolved_framing_questions"):
        questions.extend(_discover_requirement_values(inputs.get(key) or raw.get(key)))
    for line in query.splitlines():
        lowered = line.lower()
        if any(marker in lowered for marker in ("required criteria:", "must cover:", "coverage requirements:")):
            criteria.extend(_discover_requirement_values(line.split(":", 1)[1] if ":" in line else line))
        if any(marker in lowered for marker in ("framing questions:", "open questions:", "unresolved questions:")):
            questions.extend(_discover_requirement_values(line.split(":", 1)[1] if ":" in line else line))
        criteria_match = re.search(
            r"(?:preserve\s+the\s+exact\s+comparison\s+criteria|comparison\s+criteria(?:\s+are)?)\s+(.+?)(?:,\s+and\s+capture\b|[.;]|$)",
            line,
            flags=re.IGNORECASE,
        )
        if criteria_match:
            criteria.extend(_discover_requirement_values(criteria_match.group(1)))
        questions_match = re.search(
            r"(?:capture\s+the\s+)?(?:unresolved\s+)?framing\s+questions\s+about\s+(.+?)(?:[.;]|$)",
            line,
            flags=re.IGNORECASE,
        )
        if questions_match:
            questions.extend(_discover_requirement_values(questions_match.group(1)))
        scope_line = re.sub(r"^-\s*\[[^\]]+\]\s*", "", line).split("Required coverage:", 1)[0].strip(" .")
        topic_match = re.search(
            r"(?:is\s+limited\s+to(?:\s+the)?(?:\s+named)?(?:\s+chemistr(?:y|ies))?|compare)\s+(.+?)(?:\s+battery\s+technologies|\s+batteries)\s+for\s+grid\s+storage",
            scope_line,
            flags=re.IGNORECASE,
        )
        if topic_match:
            scope_topics.extend(_discover_requirement_values(topic_match.group(1)))
        criterion_scope_match = re.search(
            r"(?:must\s+)?evaluate\s+(.+?)(?:[.;]|$)",
            scope_line,
            flags=re.IGNORECASE,
        )
        if criterion_scope_match:
            criteria.extend(_discover_requirement_values(criterion_scope_match.group(1)))
    return {
        "criteria": _unique_strings(criteria),
        "framing_questions": _unique_strings(questions),
        "scope_topics": _unique_strings(scope_topics),
        "declared": bool(criteria or questions or scope_topics),
    }


def _discover_candidate_text(candidate: dict[str, Any]) -> str:
    pieces: list[str] = []
    # Coverage must be proved by source metadata/content, not by a rationale
    # that was itself derived from the query.
    for key in ("title", "abstract", "summary", "content_summary"):
        value = candidate.get(key)
        if value not in (None, "", []):
            pieces.append(str(value))
    return " ".join(pieces).lower()


def _discover_term_matches(term: str, candidates: list[dict[str, Any]]) -> list[str]:
    tokens = [token for token in re.findall(r"[a-z0-9]+", term.lower()) if len(token) > 2]
    if not tokens:
        return []
    matches: list[str] = []
    for candidate in candidates:
        if not isinstance(candidate, dict):
            continue
        text = _discover_candidate_text(candidate)
        if all(token in text for token in tokens):
            matches.append(str(candidate.get("candidate_id") or candidate.get("title") or "candidate"))
    return _unique_strings(matches)


def _discover_ranking_audit(candidates: list[dict[str, Any]]) -> dict[str, Any]:
    scores: list[float] = []
    missing: list[str] = []
    default_like: list[str] = []
    for candidate in candidates:
        if not isinstance(candidate, dict):
            continue
        candidate_id = str(candidate.get("candidate_id") or candidate.get("title") or "candidate")
        try:
            score = float(candidate.get("ranking_score"))
            scores.append(score)
        except (TypeError, ValueError):
            missing.append(candidate_id)
            continue
        rationale = str(candidate.get("ranking_rationale") or "").strip().lower()
        if not rationale:
            missing.append(candidate_id)
        relevance_evidence = candidate.get("relevance_evidence") if isinstance(candidate.get("relevance_evidence"), dict) else {}
        matched_terms = relevance_evidence.get("matched_query_terms") if isinstance(relevance_evidence.get("matched_query_terms"), list) else []
        evidence_grounded = bool(matched_terms) or rationale.startswith("lexical relevance:")
        if not evidence_grounded or rationale.startswith((
            "approved runtime evidence supplied",
            "production public-provider fallback supplied",
            "native discover.py selected",
        )):
            default_like.append(candidate_id)
    all_default_one = bool(candidates) and len(scores) == len(candidates) and all(score == 1.0 for score in scores)
    ready = bool(candidates) and not missing and not all_default_one and not default_like
    return {
        "ranking_ready": ready,
        "score_count": len(scores),
        "distinct_scores": sorted({score for score in scores}, reverse=True),
        "missing_ranking_evidence": _unique_strings(missing),
        "default_like_ranking_candidates": _unique_strings(default_like),
        "all_scores_default_one": all_default_one,
    }


def _discover_requested_coverage_audit(
    envelope: dict[str, Any],
    raw: dict[str, Any],
    candidates: list[dict[str, Any]],
) -> dict[str, Any]:
    scope = _discover_declared_scope(envelope, raw)
    topic_entries = []
    missing_topics: list[str] = []
    for topic in scope["scope_topics"]:
        matches = _discover_term_matches(topic, candidates)
        topic_entries.append({"topic": topic, "status": "covered" if matches else "missing", "candidate_ids": matches})
        if not matches:
            missing_topics.append(topic)
    criteria_entries = []
    missing_criteria: list[str] = []
    for criterion in scope["criteria"]:
        matches = _discover_term_matches(criterion, candidates)
        criteria_entries.append({"criterion": criterion, "status": "covered" if matches else "missing", "candidate_ids": matches})
        if not matches:
            missing_criteria.append(criterion)
    framing_entries = []
    unresolved: list[str] = []
    for question in scope["framing_questions"]:
        matches = _discover_term_matches(question, candidates)
        framing_entries.append({"question": question, "status": "resolved" if matches else "unresolved", "candidate_ids": matches})
        if not matches:
            unresolved.append(question)
    return {
        "schema": "autosci_discover_requested_coverage_audit.v1",
        "declared_scope": scope["declared"],
        "scope_topics": topic_entries,
        "criteria": criteria_entries,
        "framing_questions": framing_entries,
        "missing_scope_topics": missing_topics,
        "missing_criteria": missing_criteria,
        "unresolved_framing_questions": unresolved,
        "coverage_ready": not scope["declared"] or (not missing_topics and not missing_criteria),
    }


def _discover_final_shortlist_boundary(
    source_boundary: dict[str, Any],
    candidates: list[dict[str, Any]],
    *,
    envelope: dict[str, Any],
    raw: dict[str, Any],
    mode: str,
) -> dict[str, Any]:
    provider_channels = list(source_boundary.get("provider_channels") or []) if isinstance(source_boundary, dict) else []
    invalid_reasons = list(source_boundary.get("invalid_reasons") or []) if isinstance(source_boundary, dict) else []
    ranking_audit = _discover_ranking_audit(candidates)
    coverage_audit = _discover_requested_coverage_audit(envelope, raw, candidates)
    blocking_reasons: list[str] = []
    if not candidates:
        blocking_reasons.append("discovery shortlist is empty")
    if not provider_channels:
        blocking_reasons.append("provider-backed source channel is missing")
    if coverage_audit["declared_scope"] and not ranking_audit["ranking_ready"]:
        blocking_reasons.append("declared-scope discovery requires non-default ranking scores and rationales")
    if coverage_audit["declared_scope"] and not coverage_audit["coverage_ready"]:
        blocking_reasons.append("declared discovery criteria or framing questions are not covered by candidate evidence")
    if invalid_reasons:
        blocking_reasons.extend(str(item) for item in invalid_reasons)
    final_shortlist_ready = not blocking_reasons
    return {
        "schema": "autosci_discover_final_shortlist_boundary.v1",
        "status": "final_shortlist_ready" if final_shortlist_ready else "discover_shortlist_incomplete",
        "final_shortlist_ready": final_shortlist_ready,
        "mode": mode,
        "candidate_count": len(candidates),
        "ranking_audit": ranking_audit,
        "requested_coverage_audit": coverage_audit,
        "candidate_ids": _unique_strings([
            str(candidate.get("candidate_id") or candidate.get("paperId") or candidate.get("title") or "")
            for candidate in candidates
            if isinstance(candidate, dict)
        ]),
        "provider_channels": provider_channels,
        "source_provider_boundary_status": str(source_boundary.get("status") or "missing") if isinstance(source_boundary, dict) else "missing",
        "blocking_reasons": _unique_strings(blocking_reasons),
        "limitations": [] if final_shortlist_ready else [
            "Final discovery shortlist requires non-empty candidates backed by non-fixture provider source channels, plus declared criteria/framing coverage when the request states them."
        ],
    }


def _attach_discover_final_shortlist_boundary(
    envelope: dict[str, Any],
    raw: dict[str, Any],
    *,
    mode: str,
) -> dict[str, Any]:
    candidates = raw.get("candidates") if isinstance(raw.get("candidates"), list) else []
    source_boundary = raw.get("source_provider_boundary") if isinstance(raw.get("source_provider_boundary"), dict) else {}
    final_boundary = _discover_final_shortlist_boundary(source_boundary, candidates, envelope=envelope, raw=raw, mode=mode)
    source_boundary = dict(source_boundary)
    source_boundary["final_shortlist_boundary"] = final_boundary
    raw["source_provider_boundary"] = source_boundary
    boundary_path = _output_dir(envelope, "discover_literature") / "discover_final_shortlist_boundary.json"
    boundary_artifact = _write_json_sidecar(boundary_path, final_boundary)
    artifacts = list(raw.get("artifacts") or [])
    artifacts.append({"type": "discover_final_shortlist_boundary_json", "path": boundary_artifact})
    raw["artifacts"] = artifacts
    if not final_boundary.get("final_shortlist_ready"):
        raw["status"] = "inconclusive" if str(raw.get("status") or "") == "completed" else str(raw.get("status") or "inconclusive")
        raw["limitations"] = [
            *list(raw.get("limitations") or []),
            *list(final_boundary.get("limitations") or []),
        ]
    return raw


def _runtime_metrics(record: dict[str, Any]) -> list[dict[str, Any]]:
    raw_metrics = _field(record, "metrics")
    if not isinstance(raw_metrics, list):
        return []
    metrics: list[dict[str, Any]] = []
    for item in raw_metrics:
        if isinstance(item, dict) and str(item.get("name") or "").strip():
            metrics.append(item)
    return metrics


def _runtime_evidence_ids(records: list[dict[str, Any]]) -> list[str]:
    evidence_ids: list[str] = []
    for record in records:
        raw = _field(record, "evidence_ids")
        values = raw if isinstance(raw, list) else ([raw] if raw else [])
        evidence_ids.extend(str(item) for item in values if str(item).strip())
        for key in ("task_id", "node_id", "source_path"):
            value = record.get(key)
            if str(value or "").strip():
                evidence_ids.append(str(value))
    return _unique_strings(evidence_ids)


def _runtime_logs(records: list[dict[str, Any]]) -> list[str]:
    logs: list[str] = []
    for record in records:
        raw = _field(record, "logs", "log", "stdout", "stderr")
        values = raw if isinstance(raw, list) else ([raw] if raw else [])
        for value in values:
            text = str(value).strip()
            if text:
                logs.append(text[:1000])
    return logs


def _pdf_integrity(path: Path) -> dict[str, Any]:
    result: dict[str, Any] = {
        "path": _rel(path),
        "exists": path.exists(),
        "size_bytes": 0,
        "header_ok": False,
        "eof_ok": False,
        "startxref_ok": False,
        "valid": False,
        "detail": "",
    }
    if not path.exists() or not path.is_file():
        result["detail"] = "PDF artifact does not exist."
        return result
    try:
        size = path.stat().st_size
        with path.open("rb") as handle:
            head = handle.read(1024)
            if size > 4096:
                handle.seek(max(size - 4096, 0))
                tail = handle.read()
            else:
                tail = head
    except OSError as exc:
        result["detail"] = f"PDF artifact could not be read: {exc}"
        return result
    header_ok = head.startswith(b"%PDF-")
    eof_ok = b"%%EOF" in tail
    startxref_ok = b"startxref" in tail
    valid = bool(size > 32 and header_ok and eof_ok and startxref_ok)
    result.update({
        "size_bytes": size,
        "header_ok": header_ok,
        "eof_ok": eof_ok,
        "startxref_ok": startxref_ok,
        "valid": valid,
        "detail": "PDF artifact has a readable PDF header, xref trailer, and EOF marker."
        if valid
        else "PDF artifact is present but missing required structural markers.",
    })
    return result


def _compile_runtime_pdf_integrity(contract: dict[str, Any]) -> list[dict[str, Any]]:
    paths: list[Path] = []
    records, _errors = _runtime_records(contract)
    for record in records:
        for key in ("pdf_path", "output_pdf", "compiled_pdf"):
            raw = _field(record, key)
            if not str(raw or "").strip():
                continue
            path = _resolve_harness_path(str(raw))
            if path.suffix.lower() == ".pdf":
                paths.append(path)
    after_entries = contract.get("after_artifacts") if isinstance(contract.get("after_artifacts"), list) else []
    for entry in after_entries:
        if not isinstance(entry, dict) or not entry.get("exists"):
            continue
        raw = str(entry.get("artifact_path") or entry.get("path") or "").strip()
        if not raw:
            continue
        path = _resolve_harness_path(raw)
        if path.suffix.lower() == ".pdf":
            paths.append(path)
    seen: set[str] = set()
    inspections: list[dict[str, Any]] = []
    for path in paths:
        key = str(path.resolve())
        if key in seen:
            continue
        seen.add(key)
        inspections.append(_pdf_integrity(path))
    return inspections


def _approval_semantic_runtime(contract: dict[str, Any], action: str, *, limit: int = 10) -> dict[str, Any]:
    records, errors = _runtime_records(contract)
    checks: list[dict[str, Any]] = [
        {
            "check": "approval_contract_execution_verified",
            "status": "ok" if contract.get("execution_verified") else "error",
            "detail": "Approval, allowlist, runtime, and before/after artifact paths are present."
            if contract.get("execution_verified")
            else "Approval contract path-level verification is incomplete.",
        },
        {
            "check": "runtime_records_loaded",
            "status": "ok" if records else "error",
            "detail": f"{len(records)} runtime record(s) loaded.",
        },
    ]
    if errors:
        checks.append({"check": "runtime_read_errors", "status": "error", "detail": "; ".join(errors)})
    verified = bool(contract.get("execution_verified")) and bool(records) and not errors
    detail: dict[str, Any] = {
        "records_loaded": len(records),
        "errors": errors,
        "evidence_ids": _runtime_evidence_ids(records),
    }

    if action == "build_poster":
        browser_rendered = any(_truthy(_field(record, "browser_rendered", "rendered")) for record in records)
        overflow_passed = any(
            _truthy(_field(record, "overflow_ok", "overflow_passed"))
            or str(_field(record, "overflow_probe") or "").strip().lower() in {"ok", "pass", "passed", "none", "no_overflow"}
            for record in records
        )
        png_exported = any(
            _truthy(_field(record, "png_exported", "image_exported"))
            or _record_path_exists(record, "png_path", "png_artifact", "image_path")
            for record in records
        )
        checks.extend([
            {"check": "browser_rendered", "status": "ok" if browser_rendered else "error", "detail": str(browser_rendered)},
            {"check": "overflow_probe_passed", "status": "ok" if overflow_passed else "error", "detail": str(overflow_passed)},
            {"check": "png_exported", "status": "ok" if png_exported else "error", "detail": str(png_exported)},
        ])
        verified = verified and browser_rendered and overflow_passed and png_exported
        detail.update({
            "browser_rendered": browser_rendered,
            "overflow_probe_passed": overflow_passed,
            "png_exported": png_exported,
        })
    elif action == "compile_paper":
        exit_ok = any(_runtime_exit_ok(record) for record in records)
        pdf_integrity = _compile_runtime_pdf_integrity(contract)
        pdf_ready = any(bool(item.get("valid")) for item in pdf_integrity)
        checks.extend([
            {"check": "compile_exit_ok", "status": "ok" if exit_ok else "error", "detail": str(exit_ok)},
            {
                "check": "compiled_pdf_verified",
                "status": "ok" if pdf_ready else "error",
                "detail": "At least one compiled PDF artifact passed structural integrity checks."
                if pdf_ready
                else "No compiled PDF artifact passed structural integrity checks.",
            },
        ])
        verified = verified and exit_ok and pdf_ready
        detail.update({
            "compile_exit_ok": exit_ok,
            "compiled_pdf_verified": pdf_ready,
            "pdf_integrity": pdf_integrity,
        })
    elif action == "run_pilot_experiment":
        exit_ok = any(_runtime_exit_ok(record) for record in records)
        metrics = [metric for record in records for metric in _runtime_metrics(record)]
        result_collected = bool(metrics) or any(_truthy(_field(record, "result_collected")) for record in records)
        allowed_outcomes = {"supports", "partially_supports", "refutes", "inconclusive", "failed"}
        outcome = next(
            (
                str(_field(record, "outcome")).strip()
                for record in records
                if str(_field(record, "outcome") or "").strip() in allowed_outcomes
            ),
            "supports" if exit_ok and result_collected else "inconclusive",
        )
        command_run = next(
            (
                str(_field(record, "command_run", "command")).strip()
                for record in records
                if str(_field(record, "command_run", "command") or "").strip()
            ),
            "approved-runtime-evidence",
        )
        checks.extend([
            {"check": "pilot_exit_ok", "status": "ok" if exit_ok else "error", "detail": str(exit_ok)},
            {"check": "pilot_result_collected", "status": "ok" if result_collected else "error", "detail": str(result_collected)},
        ])
        verified = verified and exit_ok and result_collected
        detail.update({
            "pilot_exit_ok": exit_ok,
            "metrics": metrics,
            "result_collected": result_collected,
            "outcome": outcome,
            "command_run": command_run,
            "logs": _runtime_logs(records),
        })
    elif action == "run_experiment":
        exit_ok = any(_runtime_exit_ok(record) for record in records)
        metrics = [metric for record in records for metric in _runtime_metrics(record)]
        metric_aggregates = [
            aggregate
            for record in records
            for aggregate in (_field(record, "metric_aggregates") if isinstance(_field(record, "metric_aggregates"), list) else [])
            if isinstance(aggregate, dict)
        ]
        result_collected = bool(metrics) or any(
            _truthy(_field(record, "result_collected", "experiment_result_collected"))
            or _record_path_exists(record, "result_path", "experiment_result_path", "output_json")
            for record in records
        )
        allowed_outcomes = {"supports", "partially_supports", "refutes", "inconclusive", "failed"}
        outcome = next(
            (
                str(_field(record, "outcome", "experiment_outcome")).strip()
                for record in records
                if str(_field(record, "outcome", "experiment_outcome") or "").strip() in allowed_outcomes
            ),
            "supports" if exit_ok and result_collected else "inconclusive",
        )
        command_run = next(
            (
                str(_field(record, "command_run", "command")).strip()
                for record in records
                if str(_field(record, "command_run", "command") or "").strip()
            ),
            "approved-runtime-evidence",
        )
        checks.extend([
            {"check": "experiment_exit_ok", "status": "ok" if exit_ok else "error", "detail": str(exit_ok)},
            {"check": "experiment_result_collected", "status": "ok" if result_collected else "error", "detail": str(result_collected)},
        ])
        verified = verified and exit_ok and result_collected
        detail.update({
            "experiment_exit_ok": exit_ok,
            "metrics": metrics,
            "metric_aggregates": metric_aggregates,
            "result_collected": result_collected,
            "outcome": outcome,
            "command_run": command_run,
            "logs": _runtime_logs(records),
        })
    elif action in {"daily_arxiv_prepare_finalize", "init_sources", "discover_literature"}:
        candidates = _runtime_candidates(records, limit=limit)
        fetch_ok = bool(candidates) and any(_runtime_exit_ok(record) for record in records)
        provider_boundary = _source_provider_boundary(records, candidates, action=action)
        checks.extend([
            {"check": "source_fetch_ok", "status": "ok" if fetch_ok else "error", "detail": str(fetch_ok)},
            {"check": "candidates_present", "status": "ok" if candidates else "error", "detail": str(len(candidates))},
            {
                "check": "source_provider_boundary",
                "status": "ok" if provider_boundary.get("completed") else "error",
                "detail": ",".join(provider_boundary.get("invalid_reasons") or []),
            },
        ])
        verified = verified and fetch_ok and bool(candidates) and bool(provider_boundary.get("completed"))
        detail.update({
            "candidates": candidates,
            "source_fetch_ok": fetch_ok,
            "source_provider_boundary": provider_boundary,
        })

    status = "verified" if verified else "incomplete"
    return {
        "schema": "autosci_runtime_semantic_verification.v1",
        "action": action,
        "status": status,
        "verified": verified,
        "checks": checks,
        "detail": detail,
    }


def _write_evidence_payload(path: Path, evidence: dict[str, Any]) -> str:
    path = _shortened_artifact_path(path)
    artifact_path = _rel(path)
    artifacts = evidence.setdefault("artifacts", [])
    if not any(isinstance(item, dict) and item.get("path") == artifact_path for item in artifacts):
        artifacts.append({"type": "solar_evidence_json", "path": artifact_path})
    return _write_json_sidecar(path, evidence)


def _configured_handoff_path(envelope: dict[str, Any]) -> Path | None:
    outputs = envelope.get("outputs") if isinstance(envelope.get("outputs"), dict) else {}
    raw = envelope.get("handoff_path") or outputs.get("handoff_path") or os.environ.get("HANDOFF")
    if not raw:
        return None
    path = Path(str(raw))
    if not path.is_absolute():
        path = HARNESS_DIR / path
    return path


def _handoff_lines(action: str, evidence: dict[str, Any], result: dict[str, Any]) -> list[str]:
    lines = [
        "# AutoSci Phase 10 Handoff",
        "",
        f"- Action: `{action}`",
        f"- Schema: `{evidence.get('schema')}`",
        f"- Status: `{evidence.get('status')}`",
        f"- Result: `{result.get('result_path')}`",
        f"- Evidence: `{result.get('evidence_path')}`",
        f"- Evidence ledger: `{result.get('evidence_jsonl')}`",
        "",
    ]
    payloads: list[dict[str, Any]] = []
    inputs = evidence.get("inputs") if isinstance(evidence.get("inputs"), dict) else {}
    if inputs.get("paper_path") and not inputs.get("source_evidence"):
        payloads.append({
            "schema": "research_paper.v1",
            "outputs": {"paper": _read_sample_paper({"inputs": inputs})},
        })
    for key in ("source_evidence", "claims_evidence", "method_evidence"):
        related = _load_optional_evidence(inputs.get(key))
        if related and related.get("schema") != evidence.get("schema"):
            payloads.append(related)
    payloads.append(evidence)
    seen_sections: set[str] = set()
    for payload in payloads:
        outputs = payload.get("outputs") if isinstance(payload.get("outputs"), dict) else {}
        paper = outputs.get("paper") if isinstance(outputs, dict) else None
        if isinstance(paper, dict) and "paper" not in seen_sections:
            seen_sections.add("paper")
            lines.extend(["## Paper", ""])
            lines.append(f"- {paper.get('paper_id')}: {paper.get('title')} ({paper.get('source_ref')})")
            lines.append("")
        claims = outputs.get("claims") if isinstance(outputs, dict) else None
        if isinstance(claims, list) and "claims" not in seen_sections:
            seen_sections.add("claims")
            lines.extend(["## Claims", ""])
            for claim in claims:
                if not isinstance(claim, dict):
                    continue
                lines.append(
                    "- "
                    f"{claim.get('claim_id')}: {claim.get('testability')} at "
                    f"{claim.get('source_anchor')} - {claim.get('text')}"
                )
            lines.append("")
        methods = outputs.get("methods") if isinstance(outputs, dict) else None
        if isinstance(methods, list) and "methods" not in seen_sections:
            seen_sections.add("methods")
            lines.extend(["## Methods", ""])
            for method in methods:
                if not isinstance(method, dict):
                    continue
                lines.append(
                    "- "
                    f"{method.get('method_id')}: {method.get('name')} at "
                    f"{method.get('source_anchor', 'N/A')}"
                )
            lines.append("")
        mappings = outputs.get("mappings") if isinstance(outputs, dict) else None
        if isinstance(mappings, list) and "mappings" not in seen_sections:
            seen_sections.add("mappings")
            lines.extend(["## Code Evidence", ""])
            for mapping in mappings:
                if not isinstance(mapping, dict):
                    continue
                files = ", ".join(str(item) for item in mapping.get("files", []))
                lines.append(
                    "- "
                    f"{mapping.get('mapping_id')}: {mapping.get('relevance_label')} "
                    f"for {mapping.get('claim_id')} in {files}"
                )
                if mapping.get("relevance_reason"):
                    lines.append(f"  Reason: {mapping.get('relevance_reason')}")
                if mapping.get("unknown_reason"):
                    lines.append(f"  Unknown: {mapping.get('unknown_reason')}")
            lines.append("")
    limitations = evidence.get("limitations")
    if isinstance(limitations, list) and limitations:
        lines.extend(["## Limitations", ""])
        for limitation in limitations:
            lines.append(f"- {limitation}")
    return lines


def _write_handoff(path: Path, action: str, evidence: dict[str, Any], result: dict[str, Any]) -> str:
    return _write_text_sidecar(path, "\n".join(_handoff_lines(action, evidence, result)).rstrip() + "\n")


def _write_result(
    action: str,
    envelope: dict[str, Any],
    evidence: dict[str, Any],
    *,
    extra_result_fields: dict[str, Any] | None = None,
) -> dict[str, Any]:
    output_dir = _output_dir(envelope, action)
    os.makedirs(_windows_long_path(output_dir), exist_ok=True)
    evidence_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        output_dir / f"{action}.evidence.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    result_path = _configured_output_path(envelope, "result_path", output_dir / "result.json")
    ledger_path = _configured_output_path(
        envelope,
        "evidence_jsonl",
        output_dir / "evidence.jsonl",
        legacy_key="evidence_path",
        legacy_suffix=".jsonl",
    )
    handoff_path = _configured_handoff_path(envelope)
    if handoff_path:
        handoff_artifact_path = _rel(handoff_path)
        artifacts = evidence.setdefault("artifacts", [])
        if not any(isinstance(item, dict) and item.get("path") == handoff_artifact_path for item in artifacts):
            artifacts.append({"type": "handoff_markdown", "path": handoff_artifact_path})
    evidence_artifact_path = _write_evidence_payload(evidence_path, evidence)
    _mkdir_parent_long_path(ledger_path)
    with open(_windows_long_path(ledger_path), "a", encoding="utf-8") as f:
        f.write(json.dumps(evidence, sort_keys=True) + "\n")
    result = {
        "ok": True,
        "action": action,
        "status": evidence["status"],
        "schema": evidence["schema"],
        "result_path": _rel(result_path),
        "evidence_path": evidence_artifact_path,
        "evidence_jsonl": _rel(ledger_path),
        "evidence": evidence,
    }
    if extra_result_fields:
        result.update(extra_result_fields)
    if handoff_path:
        result["handoff_path"] = _write_handoff(handoff_path, action, evidence, result)
    _write_json_sidecar(result_path, result)
    return result


