def _memory_target(envelope: dict[str, Any], fallback: str) -> str:
    inputs = dict(envelope.get("inputs") or {})
    return str(inputs.get("target") or inputs.get("topic") or inputs.get("title") or fallback)


def _hash_text(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def _hash_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _local_mutation_requested(envelope: dict[str, Any]) -> bool:
    inputs = dict(envelope.get("inputs") or {})
    approval_ref = str(inputs.get("approval_ref") or "").strip()
    return bool(approval_ref and inputs.get("execute_approved_side_effect"))


def _wiki_page_rel_for_target(target: str, default_dir: str, default_prefix: str = "") -> Path:
    raw = Path(str(target or "").strip())
    if raw.suffix.lower() in {".md", ".markdown"}:
        if raw.is_absolute():
            return Path(raw.name)
        parts = raw.parts
        if parts and parts[0] == "wiki":
            return Path(*parts[1:])
        return raw
    slug = _slug(target or default_prefix or "page")
    name = f"{default_prefix}-{slug}.md" if default_prefix and not slug.startswith(default_prefix) else f"{slug}.md"
    return Path(default_dir) / name


def _edit_raw_target(target: str) -> tuple[Path | None, bool]:
    text = str(target or "").strip()
    inferred_delete = False
    parts = text.split(maxsplit=1)
    if len(parts) == 2 and parts[0].lower() in {"delete", "remove", "rm"}:
        inferred_delete = True
        text = parts[1].strip()
    normalized = text.replace("\\", "/")
    path = Path(normalized)
    if path.is_absolute() or not normalized.startswith("raw/"):
        return None, inferred_delete
    rel_parts = path.parts[1:]
    if not rel_parts or any(part in {"", ".", ".."} for part in rel_parts):
        return None, inferred_delete
    return Path(*rel_parts), inferred_delete


def _raw_root_for_wiki_root(wiki_root: Path) -> Path:
    return wiki_root.parent / "raw"


def _write_generic_wiki_log(root: Path, event: str, target_path: Path, evidence_ids: list[str], summary: str) -> Path:
    log_path = root / "log.md"
    log_path.parent.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    log_path.open("a", encoding="utf-8").write(
        "\n".join(
            [
                "",
                f"## {event}",
                "",
                f"- Timestamp: `{timestamp}`",
                f"- Target: `{_rel(target_path)}`",
                f"- Evidence ids: {', '.join(evidence_ids) if evidence_ids else 'N/A'}",
                f"- Summary: {summary}",
                "",
            ]
        )
    )
    return log_path


def _rebuild_generic_wiki_views(root: Path, run_id: str, target_path: Path, evidence_ids: list[str]) -> list[Path]:
    updated: list[Path] = []
    index_path = root / "index.md"
    lines = [
        "# Solar AutoSci Wiki\n\n",
        "Human-facing research memory projected from Solar-managed evidence and approved wiki mutations.\n\n",
        f"Last mutation run: `{run_id}`\n\n",
    ]
    for subdir in ["papers", "foundations", "concepts", "methods", "people", "topics", "ideas", "experiments", "outputs"]:
        lines.append(f"## {subdir.title()}\n\n")
        pages = sorted((root / subdir).glob("*.md"))
        if not pages:
            lines.append("- N/A\n\n")
            continue
        for page in pages:
            lines.append(f"- [{page.stem}]({subdir}/{page.name})\n")
        lines.append("\n")
    if _write_text_if_changed_bridge(index_path, "".join(lines)):
        updated.append(index_path)

    context_path = root / "graph" / "context_brief.md"
    context = "\n".join(
        [
            "# Solar AutoSci Context Brief",
            "",
            f"Last mutation run: `{run_id}`",
            f"Updated at: `{datetime.now(UTC).replace(microsecond=0).isoformat().replace('+00:00', 'Z')}`",
            f"Mutation target: `{_rel(target_path)}`",
            f"Evidence ids: {', '.join(evidence_ids) if evidence_ids else 'N/A'}",
            "",
            "Use `wiki/graph/edges.jsonl` for structured mutation edges.",
            "Use `artifacts/autosci/runs/` for Solar-managed execution evidence.",
            "",
        ]
    )
    if _write_text_if_changed_bridge(context_path, context):
        updated.append(context_path)
    return updated


PREFILL_DOMAIN_ALIASES = {
    "general": "general",
    "nlp": "NLP",
    "natural-language-processing": "NLP",
    "cv": "CV",
    "computer-vision": "CV",
    "ml-systems": "ML Systems",
    "ml systems": "ML Systems",
    "robotics": "Robotics",
}


def _prefill_catalog_path() -> Path:
    return REPO_HARNESS_DIR.parent / ".agents" / "skills" / "prefill" / "foundations-catalog.yaml"


def _parse_prefill_catalog(path: Path) -> dict[str, Any]:
    catalog: dict[str, list[dict[str, str]]] = {}
    if not path.exists():
        return {"status": "missing", "path": _rel(path), "domains": catalog}
    current_domain = ""
    current_seed: dict[str, str] | None = None
    for raw_line in path.read_text(encoding="utf-8", errors="replace").splitlines():
        line = raw_line.rstrip()
        stripped = line.strip()
        if not stripped or stripped.startswith("#") or stripped == "domains:":
            continue
        if raw_line.startswith("  ") and not raw_line.startswith("    ") and stripped.endswith(":"):
            current_domain = stripped[:-1].strip().strip("\"'")
            catalog.setdefault(current_domain, [])
            current_seed = None
            continue
        if raw_line.startswith("    - "):
            if not current_domain:
                continue
            current_seed = {}
            catalog.setdefault(current_domain, []).append(current_seed)
            stripped = stripped[2:].strip()
        if current_seed is not None and ":" in stripped:
            key, value = stripped.split(":", 1)
            current_seed[key.strip()] = value.strip().strip("\"'")
    return {"status": "completed", "path": _rel(path), "domains": catalog}


def _prefill_canonical_domain(value: str) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    return PREFILL_DOMAIN_ALIASES.get(raw.lower(), raw)


def _prefill_infer_domain(wiki_root: Path) -> dict[str, Any]:
    topics_dir = wiki_root / "topics"
    candidates: list[str] = []
    if topics_dir.exists():
        for path in sorted(topics_dir.glob("*.md")):
            try:
                text = path.read_text(encoding="utf-8", errors="replace").lower()
            except OSError:
                continue
            for raw, canonical in PREFILL_DOMAIN_ALIASES.items():
                if raw in text:
                    candidates.append(canonical)
    unique = _unique_strings(candidates)
    if len(unique) == 1:
        return {"status": "inferred", "domain": unique[0], "source": _rel(topics_dir)}
    if not unique:
        return {"status": "defaulted", "domain": "general", "source": _rel(topics_dir)}
    return {"status": "ambiguous", "domain": "general", "candidates": unique, "source": _rel(topics_dir)}


def _prefill_seed_from_add(raw: str, domain: str) -> dict[str, str]:
    title = str(raw or "").strip()
    if title.startswith("foundation:"):
        title = title.split(":", 1)[1].strip()
    slug = _slug(title or "foundation")
    return {"slug": slug, "title": title or slug, "summary": "", "domain": domain or "general", "source": "add"}


def _prefill_source_evidence(inputs: dict[str, Any]) -> list[dict[str, Any]]:
    evidence: list[dict[str, Any]] = []
    for raw_path in _input_path_values(inputs, "source_evidence", "wikipedia_evidence"):
        path = _resolve_harness_path(raw_path)
        payload = _load_optional_evidence(raw_path)
        if not payload:
            continue
        outputs = payload.get("outputs") if isinstance(payload.get("outputs"), dict) else {}
        source = {
            "schema": str(payload.get("schema") or ""),
            "status": str(payload.get("status") or outputs.get("status") or "completed"),
            "path": _rel(path),
            "title": str(outputs.get("title") or payload.get("title") or ""),
            "source_url": str(outputs.get("source_url") or outputs.get("url") or payload.get("source_url") or payload.get("url") or ""),
            "summary": str(outputs.get("summary") or outputs.get("extract") or payload.get("summary") or payload.get("extract") or ""),
            "sections": outputs.get("sections") if isinstance(outputs.get("sections"), list) else payload.get("sections") if isinstance(payload.get("sections"), list) else [],
        }
        evidence.append(source)
    return evidence


def _prefill_match_source(seed: dict[str, Any], sources: list[dict[str, Any]]) -> dict[str, Any]:
    seed_terms = {_slug(seed.get("title") or ""), _slug(seed.get("seed_slug") or ""), _slug(seed.get("foundation_id") or "")}
    for source in sources:
        source_terms = {_slug(source.get("title") or ""), _slug(Path(str(source.get("path") or "")).stem)}
        if seed_terms & source_terms:
            return source
    return sources[0] if sources else {}


def _prefill_fetch_wikipedia_sources(envelope: dict[str, Any], seeds: list[dict[str, Any]]) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    output_dir = _output_dir(envelope, "prefill_foundations")
    tool = REPO_HARNESS_DIR.parent / "tools" / "fetch_wikipedia.py"
    fetched: list[dict[str, Any]] = []
    attempts: list[dict[str, Any]] = []
    disabled = os.environ.get("AUTOSCI_WIKIPEDIA_FETCH_DISABLED") == "1"
    for seed in seeds[:5]:
        title = str(seed.get("title") or seed.get("slug") or "").strip()
        slug = _slug(title or "foundation")
        sidecar = output_dir / f"prefill_wikipedia_{slug}_summary.json"
        if disabled:
            payload = {
                "schema": "autosci_wikipedia_fetch.v1",
                "command": "summary",
                "status": "fetch_disabled",
                "title": title,
                "error": "AUTOSCI_WIKIPEDIA_FETCH_DISABLED=1",
            }
            _write_json_sidecar(sidecar, payload)
            attempts.append({"title": title, "status": "fetch_disabled", "path": _rel(sidecar)})
            continue
        command = [sys.executable, str(tool), "--timeout", "10", "summary", title]
        try:
            proc = subprocess.run(command, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=20, check=False)
        except (OSError, subprocess.TimeoutExpired) as exc:
            payload = {"schema": "autosci_wikipedia_fetch.v1", "command": "summary", "status": "fetch_failed", "title": title, "error": str(exc)}
            _write_json_sidecar(sidecar, payload)
            attempts.append({"title": title, "status": "fetch_failed", "path": _rel(sidecar), "error": str(exc)})
            continue
        _write_text_sidecar(sidecar, proc.stdout or "{}")
        try:
            payload = json.loads(proc.stdout or "{}")
        except json.JSONDecodeError:
            payload = {"schema": "autosci_wikipedia_fetch.v1", "command": "summary", "status": "invalid_json", "title": title, "stderr": proc.stderr[:500]}
            _write_json_sidecar(sidecar, payload)
        status = str(payload.get("status") or "unknown")
        attempts.append({"title": title, "status": status, "path": _rel(sidecar), "returncode": proc.returncode})
        if status == "completed":
            fetched.append(
                {
                    "schema": str(payload.get("schema") or ""),
                    "status": "completed",
                    "path": _rel(sidecar),
                    "title": str(payload.get("title") or title),
                    "source_url": str(payload.get("source_url") or ""),
                    "summary": str(payload.get("summary") or ""),
                    "sections": [],
                }
            )
    return fetched, attempts


def _prefill_source_section(source: dict[str, Any], names: tuple[str, ...]) -> str:
    for section in source.get("sections") or []:
        if not isinstance(section, dict):
            continue
        title = str(section.get("title") or section.get("line") or "").strip().lower()
        if any(name.lower() in title for name in names):
            return str(section.get("content") or section.get("text") or section.get("summary") or "").strip()
    return ""


def _prefill_plan(envelope: dict[str, Any], wiki_root: Path) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    target = str(inputs.get("target") or "").strip()
    add_value = str(inputs.get("add") or "").strip()
    catalog = _parse_prefill_catalog(_prefill_catalog_path())
    source_evidence = _prefill_source_evidence(inputs)
    domain_resolution = _prefill_infer_domain(wiki_root)
    if inputs.get("domain"):
        domain_resolution = {"status": "explicit", "domain": _prefill_canonical_domain(str(inputs.get("domain"))), "source": "input.domain"}
    elif target and not add_value and not target.startswith("foundation:"):
        domain_resolution = {"status": "explicit", "domain": _prefill_canonical_domain(target), "source": "target"}
    domain = str(domain_resolution.get("domain") or "general")
    mode = "add" if add_value or target.startswith("foundation:") else "catalog"
    if mode == "add":
        seeds = [_prefill_seed_from_add(add_value or target, domain)]
    else:
        domains = catalog.get("domains") if isinstance(catalog.get("domains"), dict) else {}
        seeds = [
            {**seed, "domain": "general", "source": "catalog"}
            for seed in domains.get("general", [])
            if isinstance(seed, dict)
        ]
        if domain != "general":
            seeds.extend(
                {**seed, "domain": domain, "source": "catalog"}
                for seed in domains.get(domain, [])
                if isinstance(seed, dict)
            )
    fetch_attempts: list[dict[str, Any]] = []
    if bool(inputs.get("online_novelty") or inputs.get("online")) and not source_evidence:
        fetched_sources, fetch_attempts = _prefill_fetch_wikipedia_sources(envelope, seeds)
        source_evidence.extend(fetched_sources)
    dedup: list[dict[str, Any]] = []
    selected: list[dict[str, Any]] = []
    for seed in seeds:
        slug = _slug(seed.get("slug") or seed.get("title") or "foundation")
        foundation_id = slug if slug.startswith("foundation-") else f"foundation-{slug}"
        page = wiki_root / "foundations" / f"{foundation_id}.md"
        entry = {
            "seed_slug": slug,
            "foundation_id": foundation_id,
            "title": str(seed.get("title") or slug),
            "domain": str(seed.get("domain") or domain or "general"),
            "path": _rel(page),
            "exists": page.exists(),
        }
        matched_source = _prefill_match_source(entry, source_evidence)
        entry["source_status"] = str(matched_source.get("status") or "fallback_llm_analysis")
        entry["source_evidence_path"] = str(matched_source.get("path") or "")
        entry["source_url"] = str(matched_source.get("source_url") or "")
        dedup.append(entry)
        if not page.exists():
            selected.append({**seed, **entry, "source_evidence": matched_source})
    return {
        "schema": "autosci_prefill_plan.v1",
        "status": "completed" if seeds else "incomplete",
        "mode": mode,
        "domain": domain,
        "domain_resolution": domain_resolution,
        "catalog": {k: v for k, v in catalog.items() if k != "domains"},
        "catalog_domain_count": len(catalog.get("domains") or {}),
        "source_evidence_count": len(source_evidence),
        "source_evidence_refs": [str(item.get("path") or "") for item in source_evidence],
        "fetch_attempts": fetch_attempts,
        "seed_count": len(seeds),
        "selected_count": len(selected),
        "skipped_existing_count": len([item for item in dedup if item.get("exists")]),
        "dedup": dedup,
        "selected_seeds": selected,
        "limitations": [] if seeds else ["No prefill seeds were selected; supply --add or a catalog domain."],
    }


def _prefill_foundation_body(seed: dict[str, Any], *, approval_ref: str) -> str:
    title = str(seed.get("title") or seed.get("foundation_id") or "Foundation")
    foundation_id = str(seed.get("foundation_id") or f"foundation-{_slug(title)}")
    domain = str(seed.get("domain") or "general")
    source = seed.get("source_evidence") if isinstance(seed.get("source_evidence"), dict) else {}
    source_backed = bool(source.get("summary") or source.get("source_url"))
    source_url = str(source.get("source_url") or "")
    summary = (
        str(source.get("summary") or "").strip()
        or str(seed.get("summary") or "").strip()
        or "Approved foundation scaffold created for AutoSci research memory."
    )
    variants = _prefill_source_section(source, ("variants", "types", "architecture"))
    limitations = _prefill_source_section(source, ("limitations",))
    source_suffix = "" if source_backed else " (LLM analysis)"
    return "\n".join(
        [
            "---",
            'entity_type: "foundation"',
            f'entity_id: {json.dumps(foundation_id)}',
            f'title: {json.dumps(title)}',
            f'slug: {json.dumps(foundation_id)}',
            f'domain: {json.dumps(domain)}',
            'status: "mainstream"',
            "aliases: []",
            'first_introduced: ""',
            f'source_url: {json.dumps(source_url)}',
            f'source_status: {json.dumps("source_backed" if source_backed else "fallback_llm_analysis")}',
            f'source_evidence_path: {json.dumps(str(source.get("path") or ""))}',
            f'approval_ref: {json.dumps(approval_ref)}',
            'managed_by: "solar-autosci-research-wiki"',
            "---",
            "",
            f"# {title}",
            "",
            "## Definition",
            "",
            f"{summary}{source_suffix}",
            "",
            "## Intuition",
            "",
            "Pending source-backed expansion. (LLM analysis)",
            "",
            "## Formal notation",
            "",
            "N/A (LLM analysis)",
            "",
            "## Key variants",
            "",
            variants or "- N/A (LLM analysis)",
            "",
            "## Known limitations",
            "",
            limitations or "- N/A (LLM analysis)",
            "",
            "## Open problems",
            "",
            "- N/A (LLM analysis)",
            "",
            "## Relevance to active research",
            "",
            "This foundation page is terminal and contains no outbound relationship fields. (LLM analysis)",
            "",
        ]
    )


def _action_prefill_foundations(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    target = _memory_target(envelope, "foundation")
    contract = _approval_contract(envelope, "prefill_foundations", ["wiki_foundation_write", "wiki_navigation_rebuild"])
    contract, policy_decision, policy_artifacts = _policy_prepare_auto_contract_if_needed(
        envelope,
        "prefill_foundations",
        ["read_local", "write_artifact", "wiki_mutation"],
        contract,
        allowlist_payload={
            "native_surface": "$prefill",
            "allowed_side_effects": ["wiki_foundation_write", "wiki_navigation_rebuild"],
            "limitations": [
                "Policy approval applies only to local foundation-page writeback and wiki navigation rebuild.",
                "Policy approval does not execute provider fetches or remote work.",
            ],
        },
    )
    inputs = dict(envelope.get("inputs") or {})
    wiki_root_for_plan = _wiki_roots_for_write(envelope)[0] if _local_mutation_requested(envelope) else _wiki_roots_for_read(envelope)[0]
    plan = _prefill_plan(envelope, wiki_root_for_plan)
    plan_path = _write_json_sidecar(_output_dir(envelope, "prefill_foundations") / "prefill_plan.json", plan)
    selected = list(plan.get("selected_seeds") or [])
    first_seed = selected[0] if selected else {
        "foundation_id": f"foundation-{_slug(target)}",
        "title": target,
        "path": f"knowledge/research/foundations/{_slug(target)}.md",
        "domain": str(plan.get("domain") or "general"),
    }
    slug = _slug(first_seed.get("foundation_id") or first_seed.get("title") or target)
    evidence_ids = [f"prefill:{slug}"]
    if _local_mutation_requested(envelope):
        side_effects = ["wiki_foundation_write", "wiki_navigation_rebuild"]
        wiki_root = wiki_root_for_plan
        changes: list[dict[str, Any]] = []
        page_paths: list[Path] = []
        changed_paths: list[Path] = []
        for seed in selected:
            foundation_id = str(seed.get("foundation_id") or f"foundation-{_slug(seed.get('title') or target)}")
            page = wiki_root / "foundations" / f"{foundation_id}.md"
            body = _prefill_foundation_body(seed, approval_ref=str(inputs.get("approval_ref") or ""))
            before = page.read_text(encoding="utf-8", errors="replace") if page.exists() else ""
            changed = False if before else _write_text_if_changed_bridge(page, body)
            after = page.read_text(encoding="utf-8", errors="replace") if page.exists() else ""
            operation = "no_op" if before else "create"
            page_paths.append(page)
            if changed:
                changed_paths.append(page)
            changes.append(
                {
                    "entity_type": "foundation",
                    "entity_id": foundation_id,
                    "operation": operation,
                    "path": _rel(page),
                    "evidence_ids": [f"prefill:{foundation_id}"],
                    "confidence": 0.82,
                    "summary": "Skipped existing foundation page without overwriting." if before else "Created approved terminal foundation scaffold.",
                    "changed": changed,
                    "before_sha256": _hash_text(before),
                    "after_sha256": _hash_text(after),
                }
            )
        if not changes:
            changes.append(
                {
                    "entity_type": "foundation",
                    "entity_id": str(first_seed.get("foundation_id") or f"foundation-{_slug(target)}"),
                    "operation": "no_op",
                    "path": str(first_seed.get("path") or f"knowledge/research/foundations/{_slug(target)}.md"),
                    "evidence_ids": evidence_ids,
                    "confidence": 0.45,
                    "summary": "No new foundation seeds were selected.",
                    "changed": False,
                    "before_sha256": "",
                    "after_sha256": "",
                }
            )
        target_page = page_paths[0] if page_paths else wiki_root / "foundations" / f"{slug}.md"
        log_summary = f"Prefill selected {len(selected)} seed(s), created {len(changed_paths)} new terminal foundation page(s)."
        log_path = _write_generic_wiki_log(wiki_root, "Prefill Foundation", target_page, evidence_ids, log_summary)
        rebuilt = _rebuild_generic_wiki_views(wiki_root, str(envelope.get("sprint_id") or "sprint-autosci"), target_page, evidence_ids)
        runtime_artifact = _append_local_mutation_runtime_to_contract(
            envelope,
            "prefill_foundations",
            contract,
            command_run="prefill_foundations:local_wiki_writeback",
            evidence_ids=evidence_ids,
            after_refs=[*page_paths, log_path, *rebuilt],
            runtime_fields={
                "selected_count": len(selected),
                "changed_count": len(changed_paths),
                "side_effects": side_effects,
            },
        )
        contract_artifact = _write_approval_contract_sidecar(envelope, "prefill_foundations", contract)
        raw = {
            "changes": changes,
            "artifacts": [
                {"type": "prefill_plan_json", "path": plan_path},
                *policy_artifacts,
                runtime_artifact,
                contract_artifact,
                *[{"type": "wiki_foundation_page", "path": _rel(page)} for page in page_paths],
                {"type": "wiki_log", "path": _rel(log_path)},
                *[{"type": "wiki_rebuild", "path": _rel(path)} for path in rebuilt],
            ],
            "status": "completed",
            "limitations": [
                "Prefill mutation was applied only because approval_ref and execute_approved_side_effect were supplied.",
                *_approval_contract_limitations(contract),
            ],
        }
        evidence = convert_research_memory_update(raw, envelope)
        evidence_payload_path = _configured_output_path(
            envelope,
            "evidence_payload_path",
            _output_dir(envelope, "prefill_foundations") / "prefill_foundations.evidence.json",
            legacy_key="evidence_path",
            legacy_suffix=".json",
        )
        evidence.setdefault("artifacts", []).extend(
            _write_approved_mutation_runtime_proof_manifests(
                envelope,
                action="prefill_foundations",
                native_skill="prefill",
                evidence_path=evidence_payload_path,
                applied=True,
                contract=contract,
                contract_artifact=contract_artifact,
                source_refs=[str(ref) for ref in plan.get("source_evidence_refs") or [] if str(ref).strip()],
                mutation_refs=[*[_rel(path) for path in page_paths], _rel(log_path), *[_rel(path) for path in rebuilt]],
                include_wiki_mutation=True,
                include_provider_source=bool(plan.get("source_evidence_refs")),
                source_label="approved_prefill_foundation",
                artifact_kind="wiki_foundation_prefill",
            )
        )
        return _attach_policy_decision_if_present(evidence, policy_decision)
    evidence = convert_research_memory_update({
        "changes": [
            {
                "entity_type": "foundation",
                "entity_id": str(first_seed.get("foundation_id") or f"foundation-{slug}"),
                "operation": "propose",
                "path": str(first_seed.get("path") or f"knowledge/research/foundations/{slug}.md"),
                "evidence_ids": evidence_ids,
                "confidence": 0.45,
                "summary": f"Propose {len(selected) or 1} foundation page scaffold(s); no wiki mutation is applied.",
            }
        ],
        "artifacts": [{"type": "prefill_plan_json", "path": plan_path}],
        "limitations": [
            "Prefill creates proposed memory-update evidence only; it does not create or modify wiki files.",
            "Deduplication is limited to the provided target text unless wiki source evidence is supplied.",
        ],
    }, envelope)
    if policy_artifacts:
        evidence.setdefault("artifacts", []).extend(policy_artifacts)
    return _attach_policy_decision_if_present(evidence, policy_decision)


def _action_edit_raw_source(envelope: dict[str, Any], *, target: str, raw_rel: Path, delete_requested: bool) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    evidence_ids = [f"edit-raw:{_slug(str(raw_rel))}"]
    wiki_root = _wiki_roots_for_write(envelope)[0]
    raw_root = _raw_root_for_wiki_root(wiki_root)
    raw_path = raw_root / raw_rel
    display_path = Path("raw") / raw_rel
    if not _path_is_under(raw_path, raw_root):
        return convert_research_memory_update({
            "changes": [
                {
                    "entity_type": "raw_source",
                    "entity_id": f"raw-{_slug(str(raw_rel))}",
                    "operation": "blocked",
                    "path": str(display_path),
                    "evidence_ids": evidence_ids,
                    "confidence": 0.0,
                    "summary": "Approved raw edit was blocked because the target escapes the raw root.",
                }
            ],
            "status": "inconclusive",
            "limitations": ["Raw edit targets must resolve under the configured Solar workspace raw root."],
        }, envelope)
    after_artifacts = inputs.get("after_artifacts") if isinstance(inputs.get("after_artifacts"), list) else []
    before_artifacts = inputs.get("before_artifacts") if isinstance(inputs.get("before_artifacts"), list) else []
    raw_side_effects = (
        ["raw_source_delete", "wiki_log_update", "navigation_rebuild"]
        if delete_requested
        else ["raw_source_add", "source_materialization", "wiki_log_update", "navigation_rebuild"]
    )
    contract = _approval_contract(envelope, "edit_wiki_plan", raw_side_effects)
    contract, policy_decision, policy_artifacts = _policy_prepare_auto_contract_if_needed(
        envelope,
        "edit_wiki_plan",
        ["read_local", "write_artifact", "wiki_mutation"],
        contract,
        allowlist_payload={
            "native_surface": "$edit",
            "allowed_side_effects": raw_side_effects,
            "limitations": [
                "Policy approval applies only to local raw/wiki mutation targets inside the configured workspace.",
                "Raw add still requires an after_artifact with the desired contents.",
            ],
        },
    )
    inputs = dict(envelope.get("inputs") or {})
    approval_ref = str(inputs.get("approval_ref") or "").strip()
    if not _local_mutation_requested(envelope):
        operation = "delete" if delete_requested else "create"
        evidence = convert_research_memory_update({
            "changes": [
                {
                    "entity_type": "raw_source",
                    "entity_id": f"raw-{_slug(str(raw_rel))}",
                    "operation": "propose",
                    "path": str(display_path),
                    "evidence_ids": evidence_ids,
                    "confidence": 0.35,
                    "summary": f"Propose approved raw source {operation}; no raw or wiki mutation is applied.",
                }
            ],
            "status": "completed",
            "limitations": [
                "Raw add/delete is proposal-only without explicit approval.",
                "Approved raw add requires after_artifact evidence; approved raw delete requires an existing raw source target.",
            ],
        }, envelope)
        if policy_artifacts:
            evidence.setdefault("artifacts", []).extend(policy_artifacts)
        return _attach_policy_decision_if_present(evidence, policy_decision)
    if delete_requested:
        if not raw_path.exists() or raw_path.is_dir():
            evidence = convert_research_memory_update({
                "changes": [
                    {
                        "entity_type": "raw_source",
                        "entity_id": f"raw-{_slug(str(raw_rel))}",
                        "operation": "blocked",
                        "path": str(display_path),
                        "evidence_ids": evidence_ids,
                        "confidence": 0.0,
                        "summary": "Approved raw delete was blocked because the raw source target is missing or is a directory.",
                    }
                ],
                "status": "inconclusive",
                "limitations": ["Approved raw delete requires an existing raw source file target."],
            }, envelope)
            if policy_artifacts:
                evidence.setdefault("artifacts", []).extend(policy_artifacts)
            return _attach_policy_decision_if_present(evidence, policy_decision)
        before_bytes = raw_path.read_bytes()
        raw_path.unlink()
        after_bytes = b""
        log_path = _write_generic_wiki_log(wiki_root, "Approved Raw Source Delete", raw_path, evidence_ids, "Deleted approved raw source target.")
        rebuilt = _rebuild_generic_wiki_views(wiki_root, str(envelope.get("sprint_id") or "sprint-autosci"), raw_path, evidence_ids)
        runtime_artifact = _append_local_mutation_runtime_to_contract(
            envelope,
            "edit_wiki_plan",
            contract,
            command_run="edit_wiki_plan:local_raw_delete",
            evidence_ids=evidence_ids,
            after_refs=[log_path, *rebuilt],
            runtime_fields={
                "deleted_path": str(display_path),
                "side_effects": raw_side_effects,
            },
        )
        contract_artifact = _write_approval_contract_sidecar(envelope, "edit_wiki_plan", contract)
        raw = {
            "changes": [
                {
                    "entity_type": "raw_source",
                    "entity_id": f"raw-{_slug(str(raw_rel))}",
                    "operation": "delete",
                    "path": str(display_path),
                    "evidence_ids": evidence_ids,
                    "confidence": 0.84,
                    "summary": "Approved raw source delete applied.",
                    "changed": True,
                    "approval_ref": approval_ref,
                    "before_sha256": _hash_bytes(before_bytes),
                    "after_sha256": _hash_bytes(after_bytes),
                    "before_artifacts": [_rel(_resolve_harness_path(str(path))) for path in before_artifacts],
                }
            ],
            "artifacts": [
                *policy_artifacts,
                runtime_artifact,
                contract_artifact,
                {"type": "wiki_log", "path": _rel(log_path)},
                *[{"type": "wiki_rebuild", "path": _rel(path)} for path in rebuilt],
            ],
            "status": "completed",
            "limitations": [
                "Raw source deletion was applied only because approval_ref and execute_approved_side_effect were supplied.",
                *_approval_contract_limitations(contract),
            ],
        }
        evidence = convert_research_memory_update(raw, envelope)
        evidence_payload_path = _configured_output_path(
            envelope,
            "evidence_payload_path",
            _output_dir(envelope, "edit_wiki_plan") / "edit_wiki_plan.evidence.json",
            legacy_key="evidence_path",
            legacy_suffix=".json",
        )
        evidence.setdefault("artifacts", []).extend(
            _write_approved_mutation_runtime_proof_manifests(
                envelope,
                action="edit_wiki_plan",
                native_skill="edit",
                evidence_path=evidence_payload_path,
                applied=True,
                contract=contract,
                contract_artifact=contract_artifact,
                source_refs=[*[_rel(_resolve_harness_path(str(path))) for path in before_artifacts], *[_rel(_resolve_harness_path(str(path))) for path in after_artifacts]],
                mutation_refs=[_rel(log_path), *[_rel(path) for path in rebuilt]],
                include_wiki_mutation=True,
                source_label="approved_raw_source_delete",
                artifact_kind="raw_source_delete",
            )
        )
        return _attach_policy_decision_if_present(evidence, policy_decision)
    if not after_artifacts:
        evidence = convert_research_memory_update({
            "changes": [
                {
                    "entity_type": "raw_source",
                    "entity_id": f"raw-{_slug(str(raw_rel))}",
                    "operation": "blocked",
                    "path": str(display_path),
                    "evidence_ids": evidence_ids,
                    "confidence": 0.0,
                    "summary": "Approved raw add was blocked because after_artifact evidence is missing.",
                }
            ],
            "status": "inconclusive",
            "limitations": ["Approved raw add requires an existing after_artifact file containing the desired raw source contents."],
        }, envelope)
        if policy_artifacts:
            evidence.setdefault("artifacts", []).extend(policy_artifacts)
        return _attach_policy_decision_if_present(evidence, policy_decision)
    if raw_path.exists():
        evidence = convert_research_memory_update({
            "changes": [
                {
                    "entity_type": "raw_source",
                    "entity_id": f"raw-{_slug(str(raw_rel))}",
                    "operation": "blocked",
                    "path": str(display_path),
                    "evidence_ids": evidence_ids,
                    "confidence": 0.0,
                    "summary": "Approved raw add was blocked because existing raw sources are read-only.",
                }
            ],
            "status": "inconclusive",
            "limitations": ["Existing raw sources are read-only; use an explicit approved delete or a new raw target path."],
        }, envelope)
        if policy_artifacts:
            evidence.setdefault("artifacts", []).extend(policy_artifacts)
        return _attach_policy_decision_if_present(evidence, policy_decision)
    after_path = _resolve_harness_path(str(after_artifacts[0]))
    if not after_path.exists() or after_path.is_dir():
        evidence = convert_research_memory_update({
            "changes": [
                {
                    "entity_type": "raw_source",
                    "entity_id": f"raw-{_slug(str(raw_rel))}",
                    "operation": "blocked",
                    "path": str(display_path),
                    "evidence_ids": evidence_ids,
                    "confidence": 0.0,
                    "summary": "Approved raw add was blocked because after_artifact evidence is missing.",
                }
            ],
            "status": "inconclusive",
            "limitations": ["Approved raw add requires an existing after_artifact file containing the desired raw source contents."],
        }, envelope)
        if policy_artifacts:
            evidence.setdefault("artifacts", []).extend(policy_artifacts)
        return _attach_policy_decision_if_present(evidence, policy_decision)
    raw_path.parent.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(after_path, raw_path)
    after_bytes = raw_path.read_bytes()
    log_path = _write_generic_wiki_log(wiki_root, "Approved Raw Source Add", raw_path, evidence_ids, "Added approved raw source target; run /ingest to register it into the wiki.")
    rebuilt = _rebuild_generic_wiki_views(wiki_root, str(envelope.get("sprint_id") or "sprint-autosci"), raw_path, evidence_ids)
    runtime_artifact = _append_local_mutation_runtime_to_contract(
        envelope,
        "edit_wiki_plan",
        contract,
        command_run="edit_wiki_plan:local_raw_add",
        evidence_ids=evidence_ids,
        after_refs=[raw_path, log_path, *rebuilt],
        runtime_fields={
            "raw_path": str(display_path),
            "side_effects": raw_side_effects,
        },
    )
    contract_artifact = _write_approval_contract_sidecar(envelope, "edit_wiki_plan", contract)
    raw = {
        "changes": [
            {
                "entity_type": "raw_source",
                "entity_id": f"raw-{_slug(str(raw_rel))}",
                "operation": "create",
                "path": str(display_path),
                "evidence_ids": evidence_ids,
                "confidence": 0.84,
                "summary": "Approved raw source add applied from after_artifact evidence.",
                "changed": True,
                "approval_ref": approval_ref,
                "before_sha256": _hash_bytes(b""),
                "after_sha256": _hash_bytes(after_bytes),
                "after_artifact": _rel(after_path),
                "follow_up": "Run /ingest on this raw source to register it in the research wiki.",
            }
        ],
        "artifacts": [
            *policy_artifacts,
            runtime_artifact,
            contract_artifact,
            {"type": "raw_source", "path": str(display_path)},
            {"type": "wiki_log", "path": _rel(log_path)},
            *[{"type": "wiki_rebuild", "path": _rel(path)} for path in rebuilt],
        ],
        "status": "completed",
        "limitations": [
            "Raw source add was applied only because approval_ref, execute_approved_side_effect, and after_artifact evidence were supplied.",
            "New raw sources still require /ingest before becoming registered wiki paper/source nodes.",
            *_approval_contract_limitations(contract),
        ],
    }
    evidence = convert_research_memory_update(raw, envelope)
    evidence_payload_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        _output_dir(envelope, "edit_wiki_plan") / "edit_wiki_plan.evidence.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    evidence.setdefault("artifacts", []).extend(
        _write_approved_mutation_runtime_proof_manifests(
            envelope,
            action="edit_wiki_plan",
            native_skill="edit",
            evidence_path=evidence_payload_path,
            applied=True,
                contract=contract,
                contract_artifact=contract_artifact,
                source_refs=[_rel(after_path), _rel(raw_path)],
                mutation_refs=[_rel(raw_path), _rel(log_path), *[_rel(path) for path in rebuilt]],
                include_wiki_mutation=True,
                source_label="approved_raw_source_add",
                artifact_kind="raw_source_add",
        )
    )
    return _attach_policy_decision_if_present(evidence, policy_decision)


def _action_edit_wiki_plan(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    target = _memory_target(envelope, "wiki-edit")
    slug = _slug(target)
    evidence_ids = [f"edit-plan:{slug}"]
    after_artifacts = inputs.get("after_artifacts") if isinstance(inputs.get("after_artifacts"), list) else []
    raw_rel, inferred_delete = _edit_raw_target(target)
    if raw_rel is not None:
        return _action_edit_raw_source(envelope, target=target, raw_rel=raw_rel, delete_requested=bool(inputs.get("delete") or inferred_delete))
    contract = _approval_contract(
        envelope,
        "edit_wiki_plan",
        ["wiki_page_mutation", "source_rewrite", "navigation_rebuild"],
    )
    contract, policy_decision, policy_artifacts = _policy_prepare_auto_contract_if_needed(
        envelope,
        "edit_wiki_plan",
        ["read_local", "write_artifact", "wiki_mutation"],
        contract,
        allowlist_payload={
            "native_surface": "$edit",
            "allowed_side_effects": ["wiki_page_mutation", "source_rewrite", "navigation_rebuild"],
            "limitations": [
                "Policy approval applies only to local wiki page mutation targets inside the configured wiki root.",
                "Wiki edits still require an after_artifact with the desired page contents.",
            ],
        },
    )
    inputs = dict(envelope.get("inputs") or {})
    if _local_mutation_requested(envelope) and after_artifacts:
        wiki_root = _wiki_roots_for_write(envelope)[0]
        rel_page = _wiki_page_rel_for_target(target, "outputs", "edit")
        page = wiki_root / rel_page
        if not _path_is_under(page, wiki_root):
            evidence = convert_research_memory_update({
                "changes": [
                    {
                        "entity_type": "wiki_page",
                        "entity_id": f"wiki-edit-{slug}",
                        "operation": "blocked",
                        "path": str(rel_page),
                        "evidence_ids": evidence_ids,
                        "confidence": 0.0,
                        "summary": "Approved wiki edit was blocked because the target escapes the wiki root.",
                    }
                ],
                "status": "inconclusive",
                "limitations": ["Approved wiki edit target must resolve inside the configured wiki root."],
            }, envelope)
            if policy_artifacts:
                evidence.setdefault("artifacts", []).extend(policy_artifacts)
            return _attach_policy_decision_if_present(evidence, policy_decision)
        after_path = _resolve_harness_path(str(after_artifacts[0]))
        if not after_path.exists() or after_path.is_dir():
            evidence = convert_research_memory_update({
                "changes": [
                    {
                        "entity_type": "wiki_page",
                        "entity_id": f"wiki-edit-{slug}",
                        "operation": "blocked",
                        "path": _rel(page),
                        "evidence_ids": evidence_ids,
                        "confidence": 0.0,
                        "summary": "Approved wiki edit was blocked because after_artifact evidence is missing.",
                    }
                ],
                "status": "inconclusive",
                "limitations": ["Approved wiki edit requires an existing after_artifact file containing the desired page contents."],
            }, envelope)
            if policy_artifacts:
                evidence.setdefault("artifacts", []).extend(policy_artifacts)
            return _attach_policy_decision_if_present(evidence, policy_decision)
        before = page.read_text(encoding="utf-8", errors="replace") if page.exists() else ""
        desired = after_path.read_text(encoding="utf-8", errors="replace")
        changed = _write_text_if_changed_bridge(page, desired)
        after = page.read_text(encoding="utf-8", errors="replace")
        log_path = _write_generic_wiki_log(wiki_root, "Approved Wiki Edit", page, evidence_ids, "Applied approved after_artifact contents to wiki page.")
        rebuilt = _rebuild_generic_wiki_views(wiki_root, str(envelope.get("sprint_id") or "sprint-autosci"), page, evidence_ids)
        runtime_artifact = _append_local_mutation_runtime_to_contract(
            envelope,
            "edit_wiki_plan",
            contract,
            command_run="edit_wiki_plan:local_wiki_edit",
            evidence_ids=evidence_ids,
            after_refs=[page, log_path, *rebuilt],
            runtime_fields={
                "wiki_page": _rel(page),
                "changed": changed,
            },
        )
        contract_artifact = _write_approval_contract_sidecar(envelope, "edit_wiki_plan", contract)
        raw = {
            "changes": [
                {
                    "entity_type": "wiki_page",
                    "entity_id": f"wiki-edit-{slug}",
                    "operation": "update" if before else "create",
                    "path": _rel(page),
                    "evidence_ids": evidence_ids,
                    "confidence": 0.84,
                    "summary": "Approved wiki edit applied from after_artifact evidence.",
                    "changed": changed,
                    "before_sha256": _hash_text(before),
                    "after_sha256": _hash_text(after),
                    "after_artifact": _rel(after_path),
                }
            ],
            "artifacts": [
                *policy_artifacts,
                runtime_artifact,
                contract_artifact,
                {"type": "wiki_page", "path": _rel(page)},
                {"type": "wiki_log", "path": _rel(log_path)},
                *[{"type": "wiki_rebuild", "path": _rel(path)} for path in rebuilt],
            ],
            "status": "completed",
            "limitations": [
                "Wiki edit mutation was applied only because approval_ref, execute_approved_side_effect, and after_artifact evidence were supplied.",
                *_approval_contract_limitations(contract),
            ],
        }
        evidence = convert_research_memory_update(raw, envelope)
        evidence_payload_path = _configured_output_path(
            envelope,
            "evidence_payload_path",
            _output_dir(envelope, "edit_wiki_plan") / "edit_wiki_plan.evidence.json",
            legacy_key="evidence_path",
            legacy_suffix=".json",
        )
        evidence.setdefault("artifacts", []).extend(
            _write_approved_mutation_runtime_proof_manifests(
                envelope,
                action="edit_wiki_plan",
                native_skill="edit",
                evidence_path=evidence_payload_path,
                applied=True,
                contract=contract,
                contract_artifact=contract_artifact,
                source_refs=[_rel(after_path), _rel(page)],
                mutation_refs=[_rel(page), _rel(log_path), *[_rel(path) for path in rebuilt]],
                include_wiki_mutation=True,
                source_label="approved_wiki_edit",
                artifact_kind="wiki_edit_writeback",
            )
        )
        return _attach_policy_decision_if_present(evidence, policy_decision)
    evidence = convert_research_memory_update({
        "changes": [
            {
                "entity_type": "wiki_page",
                "entity_id": f"wiki-edit-{slug}",
                "operation": "propose",
                "path": f"knowledge/research/proposed-edits/{slug}.md",
                "evidence_ids": [f"edit-plan:{slug}"],
                "confidence": 0.35,
                "summary": "Propose a bounded wiki edit plan; no set-meta/add-edge mutation is applied.",
            }
        ],
        "limitations": [
            "Wiki edit is proposal-only without explicit approval.",
            "Before/after source mutation evidence is required before applying any wiki or raw-file edit.",
        ],
    }, envelope)
    if policy_artifacts:
        evidence.setdefault("artifacts", []).extend(policy_artifacts)
    return _attach_policy_decision_if_present(evidence, policy_decision)


def _wiki_roots_for_read(envelope: dict[str, Any]) -> list[Path]:
    inputs = dict(envelope.get("inputs") or {})
    roots: list[Path] = []
    raw_root = str(inputs.get("wiki_root") or "").strip()
    if raw_root:
        path = Path(raw_root)
        roots.append(path if path.is_absolute() else HARNESS_DIR / path)
    else:
        roots.extend(
            [
                HARNESS_DIR / "artifacts" / "autosci" / "workspace" / "wiki",
                HARNESS_DIR / "wiki",
                REPO_HARNESS_DIR / "harness" / "artifacts" / "autosci" / "workspace" / "wiki",
            ]
        )
    seen: set[Path] = set()
    out: list[Path] = []
    for root in roots:
        try:
            resolved = root.resolve()
        except OSError:
            continue
        if resolved in seen:
            continue
        seen.add(resolved)
        out.append(root)
    return out


def _query_terms(query: str) -> list[str]:
    stop = {"a", "an", "and", "are", "for", "how", "in", "is", "of", "on", "or", "the", "to", "what"}
    terms = [term for term in re.findall(r"[a-z0-9][a-z0-9_-]+", query.lower()) if term not in stop]
    return _unique_strings(terms)[:12]


def _wiki_retrieval_hits(envelope: dict[str, Any], query: str, *, limit: int = 5) -> list[dict[str, Any]]:
    terms = _query_terms(query)
    if not terms:
        return []
    hits: list[dict[str, Any]] = []
    for root in _wiki_roots_for_read(envelope):
        if not root.exists():
            continue
        for path in sorted(root.rglob("*.md"), key=lambda item: str(item)):
            try:
                text = path.read_text(encoding="utf-8", errors="replace")
            except OSError:
                continue
            lowered = text.lower()
            score = sum(lowered.count(term) for term in terms)
            if score <= 0:
                continue
            lines = [
                line.strip()
                for line in text.splitlines()
                if line.strip()
                and line.strip() != "---"
                and not re.match(r"^[a-zA-Z_ -]{1,32}:\s", line.strip())
            ]
            ranked_lines = sorted(
                (
                    (sum(line.lower().count(term) for term in terms), line)
                    for line in lines
                    if any(term in line.lower() for term in terms)
                ),
                key=lambda item: (-item[0], len(item[1])),
            )
            snippet = ranked_lines[0][1] if ranked_lines else (lines[0] if lines else "")
            hits.append(
                {
                    "path": _rel(path),
                    "score": score,
                    "matched_terms": [term for term in terms if term in lowered],
                    "snippet": snippet[:300],
                }
            )
    hits.sort(key=lambda item: (-int(item["score"]), str(item["path"])))
    return hits[:limit]


def _ask_source_slug(path_value: Any) -> str:
    return _slug(Path(str(path_value or "source")).stem or "source")


def _ask_context_source(root: Path, rel_path: str, terms: list[str], *, line_limit: int = 5) -> dict[str, Any]:
    path = root / rel_path
    source: dict[str, Any] = {
        "path": _rel(path),
        "status": "missing",
        "matched_terms": [],
        "matched_lines": [],
    }
    if not path.exists():
        return source
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError as exc:
        source["status"] = "unreadable"
        source["error"] = str(exc)
        return source
    lowered = text.lower()
    matched_terms = [term for term in terms if term in lowered]
    lines = [
        line.strip()
        for line in text.splitlines()
        if line.strip() and any(term in line.lower() for term in terms)
    ]
    source.update(
        {
            "status": "present",
            "sha256": _hash_text(text),
            "line_count": len(text.splitlines()),
            "matched_terms": matched_terms,
            "matched_lines": lines[:line_limit],
        }
    )
    return source


def _ask_edge_context(root: Path, terms: list[str], *, line_limit: int = 10) -> dict[str, Any]:
    path = root / "graph" / "edges.jsonl"
    source: dict[str, Any] = {
        "path": _rel(path),
        "status": "missing",
        "matched_terms": [],
        "matched_edges": [],
        "matched_edge_count": 0,
    }
    if not path.exists():
        return source
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError as exc:
        source["status"] = "unreadable"
        source["error"] = str(exc)
        return source
    matched_edges: list[dict[str, Any]] = []
    matched_terms: list[str] = []
    for line_number, line in enumerate(text.splitlines(), start=1):
        lowered = line.lower()
        line_terms = [term for term in terms if term in lowered]
        if not line_terms:
            continue
        matched_terms.extend(line_terms)
        try:
            payload = json.loads(line)
        except json.JSONDecodeError:
            payload = {"raw": line[:300]}
        matched_edges.append({"line": line_number, "matched_terms": _unique_strings(line_terms), "edge": payload})
    source.update(
        {
            "status": "present",
            "sha256": _hash_text(text),
            "line_count": len(text.splitlines()),
            "matched_terms": _unique_strings(matched_terms),
            "matched_edges": matched_edges[:line_limit],
            "matched_edge_count": len(matched_edges),
        }
    )
    return source


def _ask_wiki_context(envelope: dict[str, Any], query: str) -> dict[str, Any]:
    terms = _query_terms(query)
    selected_root: Path | None = None
    for root in _wiki_roots_for_read(envelope):
        if root.exists():
            selected_root = root
            break
    if selected_root is None:
        return {
            "schema": "autosci_ask_wiki_context.v1",
            "status": "missing",
            "query_terms": terms,
            "wiki_root": "",
            "sources": {},
            "limitations": ["No readable wiki root was available for ask context evidence."],
        }
    sources = {
        "context_brief": _ask_context_source(selected_root, "graph/context_brief.md", terms),
        "open_questions": _ask_context_source(selected_root, "graph/open_questions.md", terms),
        "index": _ask_context_source(selected_root, "index.md", terms),
        "edges": _ask_edge_context(selected_root, terms),
    }
    required_present = all(sources[name]["status"] == "present" for name in ("context_brief", "open_questions", "index"))
    return {
        "schema": "autosci_ask_wiki_context.v1",
        "status": "completed" if required_present else "partial",
        "query_terms": terms,
        "wiki_root": _rel(selected_root),
        "sources": sources,
        "limitations": [] if required_present else [
            "Ask context evidence is partial because one or more native context files are missing."
        ],
    }


def _ask_gap_annotations(wiki_context: dict[str, Any], hits: list[dict[str, Any]]) -> dict[str, Any]:
    sources = wiki_context.get("sources") if isinstance(wiki_context.get("sources"), dict) else {}
    open_questions = sources.get("open_questions") if isinstance(sources.get("open_questions"), dict) else {}
    matched_lines = [str(line) for line in open_questions.get("matched_lines") or [] if str(line).strip()]
    annotations: list[dict[str, Any]] = []
    for line in matched_lines:
        annotations.append(
            {
                "status": "matched_open_question",
                "source": str(open_questions.get("path") or ""),
                "text": line,
            }
        )
    if not hits:
        annotations.append(
            {
                "status": "insufficient_wiki_evidence",
                "source": "retrieval",
                "text": "No matching wiki pages were retrieved for this ask query.",
            }
        )
    if str(open_questions.get("status") or "") == "missing":
        annotations.append(
            {
                "status": "open_questions_missing",
                "source": str(open_questions.get("path") or ""),
                "text": "open_questions.md was not available, so gap matching could not run.",
            }
        )
    status = "matched_open_questions" if matched_lines else ("insufficient_wiki_evidence" if not hits else "no_matching_open_questions")
    return {
        "schema": "autosci_ask_gap_annotations.v1",
        "status": status,
        "annotations": annotations,
    }


def _ask_crystallize_recommendation(
    *,
    hits: list[dict[str, Any]],
    model_output: dict[str, Any],
    final_boundary: dict[str, Any],
    requested: bool,
    gap_annotations: dict[str, Any],
) -> dict[str, Any]:
    final_ready = bool(final_boundary.get("final_answer_ready"))
    model_completed = model_output.get("status") == "completed"
    gap_matched = str(gap_annotations.get("status") or "") == "matched_open_questions"
    if not final_ready:
        recommendation = "blocked"
        reason = "Crystallize requires retrieved source evidence and completed model synthesis with evidence ids."
    elif requested:
        recommendation = "worthwhile"
        reason = "The user requested crystallize and the final answer boundary is ready."
    elif len(hits) >= 2 or gap_matched:
        recommendation = "worthwhile"
        reason = "The answer draws on multiple wiki sources or touches a recorded open question."
    elif model_completed and hits:
        recommendation = "optional"
        reason = "The answer is source-backed and model-synthesized, but relies on a narrow evidence set."
    else:
        recommendation = "not_needed"
        reason = "The answer is a simple retrieval result without enough evidence for durable wiki writeback."
    return {
        "schema": "autosci_ask_crystallize_recommendation.v1",
        "status": "completed" if final_ready else "blocked",
        "recommendation": recommendation,
        "reason": reason,
        "source": "ask_final_answer_boundary",
        "retrieval_source_count": len(hits),
        "model_status": str(model_output.get("status") or "missing"),
        "gap_status": str(gap_annotations.get("status") or ""),
    }


def _ask_gap_markdown_lines(gap_annotations: dict[str, Any]) -> list[str]:
    lines = [
        f"- `{annotation.get('status')}` from `{annotation.get('source')}`: {annotation.get('text')}"
        for annotation in gap_annotations.get("annotations") or []
        if isinstance(annotation, dict)
    ]
    return lines or [f"- `{gap_annotations.get('status') or 'N/A'}`"]


def _ask_recommendation_markdown_line(crystallize_recommendation: dict[str, Any]) -> str:
    return (
        f"Crystallize recommendation: `{crystallize_recommendation.get('recommendation') or 'N/A'}` - "
        f"{crystallize_recommendation.get('reason') or 'N/A'}"
    )


def _wiki_frontmatter_value(raw: str) -> Any:
    value = raw.strip()
    if not value:
        return ""
    if value.startswith("[") and value.endswith("]"):
        inner = value[1:-1].strip()
        if not inner:
            return []
        return [_wiki_frontmatter_value(item) for item in inner.split(",")]
    lowered = value.lower()
    if lowered in {"true", "false"}:
        return lowered == "true"
    if lowered in {"null", "none"}:
        return None
    try:
        if re.fullmatch(r"-?\d+", value):
            return int(value)
        if re.fullmatch(r"-?\d+\.\d+", value):
            return float(value)
    except ValueError:
        pass
    return value.strip("\"'")


def _wiki_frontmatter(text: str) -> tuple[dict[str, Any], str]:
    if not text.startswith("---"):
        return {}, text
    end = text.find("\n---", 3)
    if end < 0:
        return {}, text
    values: dict[str, Any] = {}
    current_list_key = ""
    for raw_line in text[3:end].splitlines():
        line = raw_line.rstrip()
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if stripped.startswith("- ") and current_list_key:
            current = values.setdefault(current_list_key, [])
            if not isinstance(current, list):
                current = [current]
                values[current_list_key] = current
            current.append(_wiki_frontmatter_value(stripped[2:]))
            continue
        if ":" not in line:
            current_list_key = ""
            continue
        key, raw_value = line.split(":", 1)
        key = key.strip()
        if not key:
            current_list_key = ""
            continue
        if raw_value.strip():
            values[key] = _wiki_frontmatter_value(raw_value)
            current_list_key = ""
        else:
            values[key] = []
            current_list_key = key
    return values, text[end + len("\n---") :]


def _wiki_title(path: Path, text: str, frontmatter: dict[str, Any]) -> str:
    title = str(frontmatter.get("title") or "").strip()
    if title:
        return title
    for line in text.splitlines():
        if line.startswith("# "):
            return line[2:].strip()
    return path.stem.replace("-", " ").replace("_", " ").title()


def _string_list(value: Any) -> list[str]:
    if value is None:
        return []
    if isinstance(value, list):
        raw_items = value
    elif isinstance(value, tuple):
        raw_items = list(value)
    elif isinstance(value, str) and "," in value:
        raw_items = value.split(",")
    else:
        raw_items = [value]
    out: list[str] = []
    for item in raw_items:
        text = str(item).strip().strip("\"'")
        if text:
            out.append(text)
    return _unique_strings(out)


def _first_string_list(frontmatter: dict[str, Any], keys: tuple[str, ...]) -> list[str]:
    for key in keys:
        values = _string_list(frontmatter.get(key))
        if values:
            return values
    return []


def _optional_float(value: Any) -> float | None:
    if value is None or value == "":
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _resolve_wiki_link(root: Path, source_path: Path, raw_path: str) -> tuple[str, bool]:
    raw_path = raw_path.strip()
    if not raw_path:
        return "", False
    path = Path(raw_path)
    candidates = [path] if path.is_absolute() else [source_path.parent / path, root / path]
    for candidate in candidates:
        if candidate.exists():
            return _rel(candidate), True
    fallback = candidates[0]
    return _rel(fallback), False


def _read_wiki_markdown(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return ""


def _wiki_entity_common(root: Path, group: str, path: Path, text: str, frontmatter: dict[str, Any]) -> dict[str, Any]:
    raw_slug = str(frontmatter.get("slug") or path.stem).strip()
    slug = _slug(raw_slug)
    entity_id = str(frontmatter.get(f"{group[:-1]}_id") or frontmatter.get("id") or frontmatter.get("slug") or slug)
    return {
        "id": entity_id,
        "slug": slug,
        "title": _wiki_title(path, text, frontmatter),
        "status": str(frontmatter.get("status") or frontmatter.get("state") or "unknown"),
        "path": _rel(path),
        "frontmatter_keys": sorted(str(key) for key in frontmatter),
    }


def _wiki_markdown_entities(root: Path, group: str) -> list[dict[str, Any]]:
    directory = root / group
    if not directory.exists():
        return []
    entities: list[dict[str, Any]] = []
    for path in sorted(directory.rglob("*.md"), key=lambda item: str(item)):
        text = _read_wiki_markdown(path)
        if not text:
            continue
        frontmatter, body = _wiki_frontmatter(text)
        entity = _wiki_entity_common(root, group, path, body or text, frontmatter)
        if group == "ideas":
            entity["idea_id"] = str(frontmatter.get("idea_id") or entity["id"])
            novelty_score = _optional_float(frontmatter.get("novelty_score"))
            entity["novelty_score"] = novelty_score if novelty_score is not None else "N/A"
            entity["has_novelty_score"] = novelty_score is not None
            entity["linked_experiments"] = _first_string_list(
                frontmatter,
                ("linked_experiments", "experiments", "experiment_ids"),
            )
            if frontmatter.get("failure_reason"):
                entity["failure_reason"] = str(frontmatter.get("failure_reason"))
        elif group == "experiments":
            entity["experiment_id"] = str(frontmatter.get("experiment_id") or entity["id"])
            entity["idea_id"] = str(frontmatter.get("idea_id") or "")
            entity["linked_outputs"] = _first_string_list(frontmatter, ("linked_outputs", "outputs", "output_ids"))
            entity["pipeline"] = str(frontmatter.get("pipeline") or frontmatter.get("pipeline_id") or "")
            aliases = _first_string_list(frontmatter, ("aliases", "pipeline_aliases", "pipelines"))
            if entity["pipeline"]:
                aliases.append(str(entity["pipeline"]))
            entity["aliases"] = _unique_strings(aliases)
            entity["outcome"] = str(frontmatter.get("outcome") or frontmatter.get("result") or "")
            entity["evidence_ids"] = _first_string_list(
                frontmatter,
                ("evidence_ids", "result_evidence_ids", "runtime_evidence_ids"),
            )
            run_log = str(frontmatter.get("run_log") or frontmatter.get("run_log_path") or "").strip()
            entity["run_log"] = run_log
            if run_log:
                resolved, exists = _resolve_wiki_link(root, path, run_log)
                entity["run_log_path"] = resolved
                entity["run_log_exists"] = exists
            else:
                entity["run_log_path"] = ""
                entity["run_log_exists"] = False
            if frontmatter.get("env"):
                entity["env"] = str(frontmatter.get("env"))
        elif group == "outputs":
            entity["output_id"] = str(frontmatter.get("output_id") or entity["id"])
            entity["experiment_id"] = str(frontmatter.get("experiment_id") or "")
            entity["idea_id"] = str(frontmatter.get("idea_id") or "")
            entity["artifact_type"] = str(frontmatter.get("artifact_type") or frontmatter.get("type") or "")
        entities.append(entity)
    return entities


def _wiki_graph_edges(root: Path) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    edges_path = root / "graph" / "edges.jsonl"
    edges: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    if not edges_path.exists():
        return edges, errors
    try:
        lines = edges_path.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError as exc:
        return edges, [{"path": _rel(edges_path), "line": 0, "error": str(exc)}]
    for index, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped:
            continue
        try:
            payload = json.loads(stripped)
        except json.JSONDecodeError as exc:
            errors.append({"path": _rel(edges_path), "line": index, "error": str(exc)})
            continue
        if not isinstance(payload, dict):
            errors.append({"path": _rel(edges_path), "line": index, "error": "edge row is not an object"})
            continue
        source = str(payload.get("source") or payload.get("from") or payload.get("src") or "").strip()
        target = str(payload.get("target") or payload.get("to") or payload.get("dst") or "").strip()
        relation = str(payload.get("relation") or payload.get("type") or payload.get("label") or "").strip()
        edges.append(
            {
                "source": source,
                "target": target,
                "relation": relation or "related_to",
                "status": str(payload.get("status") or ""),
                "evidence_ids": _string_list(payload.get("evidence_ids") or payload.get("evidence_id")),
                "path": _rel(edges_path),
                "line": index,
            }
        )
    return edges, errors


def _wiki_entity_aliases(entity: dict[str, Any], id_keys: tuple[str, ...]) -> set[str]:
    aliases: set[str] = set()
    for key in ("id", "slug", "title", "path", "pipeline", *id_keys):
        value = str(entity.get(key) or "").strip()
        if not value:
            continue
        aliases.add(value.lower())
        aliases.add(_slug(value))
        if "/" in value:
            aliases.add(Path(value).stem.lower())
            aliases.add(_slug(Path(value).stem))
    for value in _string_list(entity.get("aliases")):
        aliases.add(value.lower())
        aliases.add(_slug(value))
    return {alias for alias in aliases if alias}


def _target_matches_entity(target: str, entity: dict[str, Any], id_keys: tuple[str, ...]) -> bool:
    if not target:
        return False
    aliases = _wiki_entity_aliases(entity, id_keys)
    return target.lower() in aliases or _slug(target) in aliases


def _edge_links(edge: dict[str, Any], left_aliases: set[str], right_aliases: set[str]) -> bool:
    source = str(edge.get("source") or "").lower()
    target = str(edge.get("target") or "").lower()
    return (source in left_aliases and target in right_aliases) or (source in right_aliases and target in left_aliases)


def _enrich_wiki_entities(
    ideas: list[dict[str, Any]],
    experiments: list[dict[str, Any]],
    outputs: list[dict[str, Any]],
    edges: list[dict[str, Any]],
) -> None:
    experiment_aliases = {
        str(experiment.get("experiment_id") or experiment.get("id")): _wiki_entity_aliases(experiment, ("experiment_id",))
        for experiment in experiments
    }
    output_aliases = {
        str(output.get("output_id") or output.get("id")): _wiki_entity_aliases(output, ("output_id",))
        for output in outputs
    }
    for idea in ideas:
        idea_aliases = _wiki_entity_aliases(idea, ("idea_id",))
        linked = list(idea.get("linked_experiments") or [])
        edge_count = 0
        for edge in edges:
            if str(edge.get("source") or "").lower() in idea_aliases or str(edge.get("target") or "").lower() in idea_aliases:
                edge_count += 1
            for experiment_id, aliases in experiment_aliases.items():
                if _edge_links(edge, idea_aliases, aliases):
                    linked.append(experiment_id)
        idea["linked_experiments"] = _unique_strings(str(item) for item in linked if str(item).strip())
        idea["graph_edge_count"] = edge_count
    for experiment in experiments:
        experiment_aliases_for_entity = _wiki_entity_aliases(experiment, ("experiment_id",))
        linked_outputs = list(experiment.get("linked_outputs") or [])
        edge_count = 0
        for edge in edges:
            if str(edge.get("source") or "").lower() in experiment_aliases_for_entity or str(edge.get("target") or "").lower() in experiment_aliases_for_entity:
                edge_count += 1
            for output_id, aliases in output_aliases.items():
                if _edge_links(edge, experiment_aliases_for_entity, aliases):
                    linked_outputs.append(output_id)
        experiment["linked_outputs"] = _unique_strings(str(item) for item in linked_outputs if str(item).strip())
        experiment["graph_edge_count"] = edge_count


def _resolve_wiki_state_target(
    envelope: dict[str, Any],
    ideas: list[dict[str, Any]],
    experiments: list[dict[str, Any]],
    outputs: list[dict[str, Any]],
    *,
    action: str,
) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    target = str(
        inputs.get("experiment_id")
        or inputs.get("idea_id")
        or inputs.get("target")
        or inputs.get("topic")
        or inputs.get("query")
        or ""
    ).strip()
    preferred = ["idea", "experiment", "output"]
    if action in {"monitor_experiment", "run_experiment"} or inputs.get("experiment_id"):
        preferred = ["experiment", "idea", "output"]
    elif action in {"design_experiment", "generate_ideas", "evaluate_ideas"} or inputs.get("idea_id"):
        preferred = ["idea", "experiment", "output"]
    groups = {
        "idea": (ideas, ("idea_id",)),
        "experiment": (experiments, ("experiment_id",)),
        "output": (outputs, ("output_id",)),
    }
    if target:
        for kind in preferred:
            entities, id_keys = groups[kind]
            for entity in entities:
                if _target_matches_entity(target, entity, id_keys):
                    return {
                        "target": target,
                        "target_type": kind,
                        "target_id": str(entity.get(id_keys[0]) or entity.get("id") or entity.get("slug")),
                        "target_path": str(entity.get("path") or ""),
                        "fallback_used": False,
                        "warnings": [],
                    }
        return {
            "target": target,
            "target_type": "unresolved",
            "target_id": "",
            "target_path": "",
            "fallback_used": False,
            "warnings": [f"Target `{target}` was not found in wiki ideas, experiments, outputs, or graph edges."],
        }
    return {
        "target": "N/A",
        "target_type": "unresolved",
        "target_id": "",
        "target_path": "",
        "fallback_used": False,
        "warnings": ["No explicit target, topic, idea_id, or experiment_id was supplied for wiki state resolution."],
    }


def _wiki_state_resolver(envelope: dict[str, Any], *, action: str) -> dict[str, Any]:
    roots = _wiki_roots_for_read(envelope)
    existing_roots = [root for root in roots if root.exists()]
    ideas: list[dict[str, Any]] = []
    experiments: list[dict[str, Any]] = []
    outputs: list[dict[str, Any]] = []
    edges: list[dict[str, Any]] = []
    graph_errors: list[dict[str, Any]] = []
    for root in existing_roots:
        ideas.extend(_wiki_markdown_entities(root, "ideas"))
        experiments.extend(_wiki_markdown_entities(root, "experiments"))
        outputs.extend(_wiki_markdown_entities(root, "outputs"))
        root_edges, root_errors = _wiki_graph_edges(root)
        edges.extend(root_edges)
        graph_errors.extend(root_errors)
    _enrich_wiki_entities(ideas, experiments, outputs, edges)
    resolution = _resolve_wiki_state_target(envelope, ideas, experiments, outputs, action=action)
    status = "completed" if any((ideas, experiments, outputs, edges)) else ("inconclusive" if existing_roots else "missing")
    limitations = [
        "Resolver is read-only; it does not mutate wiki state, add graph edges, or rebuild wiki indexes.",
        "Frontmatter parsing supports scalar values and simple lists only; complex YAML is reported through missing fields.",
    ]
    if not existing_roots:
        limitations.append("No wiki root exists for state resolution.")
    if graph_errors:
        limitations.append("Some graph edge rows could not be parsed.")
    return {
        "schema": "autosci_wiki_state_resolver.v1",
        "status": status,
        "action": action,
        "wiki_roots": [_rel(root) for root in roots],
        "existing_wiki_roots": [_rel(root) for root in existing_roots],
        "selected_root": _rel(existing_roots[0]) if existing_roots else "N/A",
        "ideas": ideas,
        "experiments": experiments,
        "outputs": outputs,
        "graph_edges": edges,
        "graph_errors": graph_errors,
        "indexes": {
            "ideas_by_slug": {str(idea.get("slug")): str(idea.get("idea_id") or idea.get("id")) for idea in ideas},
            "experiments_by_slug": {
                str(experiment.get("slug")): str(experiment.get("experiment_id") or experiment.get("id"))
                for experiment in experiments
            },
            "outputs_by_slug": {str(output.get("slug")): str(output.get("output_id") or output.get("id")) for output in outputs},
        },
        "resolution": resolution,
        "limitations": limitations,
    }


def _should_resolve_wiki_state(envelope: dict[str, Any]) -> bool:
    if _fixture_like_envelope(envelope):
        return False
    inputs = dict(envelope.get("inputs") or {})
    return any(
        bool(inputs.get(key))
        for key in ("wiki_root", "from_wiki", "target", "topic", "query", "idea_id", "experiment_id")
    )


def _wiki_state_resolver_artifact(envelope: dict[str, Any], action: str) -> tuple[dict[str, Any] | None, dict[str, str] | None]:
    if not _should_resolve_wiki_state(envelope):
        return None, None
    resolver = _wiki_state_resolver(envelope, action=action)
    output_dir = _output_dir(envelope, action)
    path = _configured_output_path(envelope, "wiki_state_resolver_path", output_dir / "wiki_state_resolver.json")
    artifact = {"type": "wiki_state_resolver_json", "path": _write_json_sidecar(path, resolver)}
    return resolver, artifact


def _wiki_state_limitations(resolver: dict[str, Any] | None) -> list[str]:
    if not resolver:
        return []
    resolution = resolver.get("resolution") if isinstance(resolver.get("resolution"), dict) else {}
    warnings = [str(item) for item in resolution.get("warnings") or [] if str(item).strip()]
    limitations = [str(item) for item in resolver.get("limitations") or [] if str(item).strip()]
    return [*warnings, *limitations]


def _target_idea_from_wiki_state(resolver: dict[str, Any] | None) -> dict[str, Any] | None:
    if not resolver:
        return None
    resolution = resolver.get("resolution") if isinstance(resolver.get("resolution"), dict) else {}
    if resolution.get("target_type") != "idea":
        return None
    target_id = str(resolution.get("target_id") or "")
    target_path = str(resolution.get("target_path") or "")
    for idea in resolver.get("ideas") or []:
        if not isinstance(idea, dict):
            continue
        if target_id not in {str(idea.get("idea_id") or ""), str(idea.get("id") or ""), str(idea.get("slug") or "")} and target_path != str(idea.get("path") or ""):
            continue
        idea_id = str(idea.get("idea_id") or idea.get("id") or idea.get("slug") or "idea-wiki-target")
        return {
            "idea_id": idea_id,
            "title": str(idea.get("title") or idea_id),
            "hypothesis": f"Wiki idea `{idea_id}` should be evaluated against current source evidence.",
            "approach": "Use the resolved wiki idea state, linked experiments, graph edges, and external novelty evidence before promotion.",
            "origin_evidence_ids": [str(idea.get("path") or idea_id)],
            "novelty_hypothesis": "Novelty must be established from external source evidence and Review LLM evidence.",
            "source_mode": "wiki_state",
            "generation_path": "wiki-state-resolver",
            "duplicate_status": "unknown",
            "status": str(idea.get("status") or "candidate"),
            "wiki_state": {
                "path": str(idea.get("path") or ""),
                "slug": str(idea.get("slug") or ""),
                "novelty_score": idea.get("novelty_score", "N/A"),
                "linked_experiments": list(idea.get("linked_experiments") or []),
            },
        }
    return None


def _resolved_wiki_experiment(resolver: dict[str, Any] | None) -> dict[str, Any] | None:
    if not resolver:
        return None
    resolution = resolver.get("resolution") if isinstance(resolver.get("resolution"), dict) else {}
    if resolution.get("target_type") != "experiment":
        return None
    target_id = str(resolution.get("target_id") or "").strip()
    target_path = str(resolution.get("target_path") or "").strip()
    for experiment in resolver.get("experiments") or []:
        if not isinstance(experiment, dict):
            continue
        ids = {
            str(experiment.get("experiment_id") or ""),
            str(experiment.get("id") or ""),
            str(experiment.get("slug") or ""),
        }
        if target_id and target_id in ids:
            return experiment
        if target_path and target_path == str(experiment.get("path") or ""):
            return experiment
    return None


def _resolved_wiki_experiment_id(resolver: dict[str, Any] | None) -> str:
    experiment = _resolved_wiki_experiment(resolver)
    if not experiment:
        return ""
    return str(experiment.get("experiment_id") or experiment.get("id") or "").strip()


def _experiment_state_from_wiki_status(raw_status: str) -> str:
    normalized = _slug(raw_status)
    if normalized in {"completed", "complete", "done", "passed", "success", "succeeded", "collected"}:
        return "completed"
    if normalized in {"failed", "failure", "error", "errored", "abandoned", "cancelled", "canceled"}:
        return "failed"
    if normalized in {"planned", "plan", "designed", "drafted"}:
        return "planned"
    if normalized in {"running", "active", "launched", "queued", "in-progress", "ready", "collect-ready", "collectible"}:
        return "running"
    if normalized in {"blocked", "paused", "gated", "waiting", "needs-approval"}:
        return "blocked"
    return "unknown"


def _model_command(inputs: dict[str, Any]) -> list[str]:
    raw = inputs.get("model_command") or os.environ.get("AUTOSCI_MODEL_COMMAND", "")
    if isinstance(raw, list):
        return [str(item) for item in raw if str(item).strip()]
    raw_text = str(raw).strip()
    return shlex.split(raw_text) if raw_text else []


def _normalize_model_response(payload: dict[str, Any], source: str) -> dict[str, Any]:
    outputs = payload.get("outputs") if isinstance(payload.get("outputs"), dict) else {}
    answer = str(outputs.get("answer") or outputs.get("summary") or payload.get("answer") or payload.get("summary") or "").strip()
    ideas_raw = outputs.get("ideas") if isinstance(outputs.get("ideas"), list) else payload.get("ideas")
    ideas = ideas_raw if isinstance(ideas_raw, list) else []
    evidence_ids_raw = outputs.get("evidence_ids") or payload.get("evidence_ids") or []
    evidence_ids = [str(item) for item in (evidence_ids_raw if isinstance(evidence_ids_raw, list) else [evidence_ids_raw]) if str(item).strip()]
    findings_raw = outputs.get("findings") if isinstance(outputs.get("findings"), list) else payload.get("findings")
    findings = findings_raw if isinstance(findings_raw, list) else []
    try:
        confidence = float(outputs.get("confidence", payload.get("confidence", 0.0)))
    except (TypeError, ValueError):
        confidence = 0.0
    confidence = round(max(0.0, min(confidence, 1.0)), 3)
    status = str(payload.get("status") or "completed")
    if status not in {"completed", "inconclusive"}:
        return {"status": "invalid", "source": source, "reason": f"model response status is not completed/inconclusive: {status}"}
    if status == "completed" and ((not answer and not ideas) or not evidence_ids):
        return {
            "status": "invalid",
            "source": source,
            "reason": "completed model response requires answer/summary or ideas plus evidence_ids.",
        }
    return {
        "status": status,
        "source": source,
        "answer": answer,
        "ideas": ideas,
        "confidence": confidence,
        "evidence_ids": evidence_ids,
        "findings": findings,
        "model": str(outputs.get("model") or payload.get("model") or ""),
        "provider": str(outputs.get("provider") or payload.get("provider") or ""),
    }


def _model_output(
    envelope: dict[str, Any],
    *,
    action: str,
    prompt: str,
    context: dict[str, Any],
) -> tuple[dict[str, Any], list[dict[str, str]]]:
    inputs = dict(envelope.get("inputs") or {})
    artifacts: list[dict[str, str]] = []
    paths = _input_path_values(inputs, "model_evidence", "model_output_evidence")
    checked: list[str] = []
    for raw in paths:
        path = _resolve_harness_path(raw)
        checked.append(_rel(path))
        payload = _load_optional_evidence(raw)
        if not payload:
            continue
        artifacts.append({"type": "model_output_evidence_json", "path": _rel(path)})
        normalized = _normalize_model_response(payload, _rel(path))
        normalized["checked_paths"] = checked
        if normalized.get("status") in {"completed", "inconclusive"}:
            return normalized, artifacts
    command = _model_command(inputs)
    if not command:
        return {
            "status": "unavailable",
            "reason": "No model evidence or model command was supplied.",
            "checked_paths": checked,
        }, artifacts
    request = {
        "schema": "autosci_model_request.v1",
        "action": action,
        "prompt": prompt,
        "context": context,
        "required_response_schema": {
            "schema": "autosci_model_response.v1",
            "status": "completed",
            "outputs": {
                "answer": "source-grounded answer or assessment",
                "confidence": "number between 0 and 1",
                "evidence_ids": ["source id used by the answer"],
                "findings": [],
                "ideas": [],
            },
        },
    }
    output_dir = _output_dir(envelope, action)
    request_path = output_dir / f"{action}_model_request.json"
    request_rel = _write_json_sidecar(request_path, request)
    request_sha256 = hashlib.sha256(request_path.read_bytes()).hexdigest()
    artifacts.append({"type": "model_command_request_json", "path": request_rel, "sha256": request_sha256})
    timeout = int(os.environ.get("AUTOSCI_MODEL_COMMAND_TIMEOUT", "60"))
    try:
        proc = subprocess.run(
            command,
            input=json.dumps(request, sort_keys=True),
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=timeout,
            check=False,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        return {
            "status": "failed",
            "reason": f"model command invocation failed: {exc}",
            "command": command,
            "checked_paths": checked,
            "request_path": request_rel,
            "request_sha256": request_sha256,
        }, artifacts
    stdout_path = output_dir / f"{action}_model_stdout.json"
    stderr_path = output_dir / f"{action}_model_stderr.txt"
    stdout_rel = _write_text_sidecar(stdout_path, proc.stdout)
    stderr_rel = _write_text_sidecar(stderr_path, proc.stderr)
    response_sha256 = hashlib.sha256(stdout_path.read_bytes()).hexdigest()
    artifacts.extend([
        {"type": "model_command_stdout_json", "path": stdout_rel, "sha256": response_sha256},
        {"type": "model_command_stderr", "path": stderr_rel},
    ])
    if proc.returncode != 0:
        return {
            "status": "failed",
            "reason": f"model command exited {proc.returncode}: {proc.stderr.strip()[:500]}",
            "command": command,
            "checked_paths": checked,
            "request_path": request_rel,
            "request_sha256": request_sha256,
            "response_path": stdout_rel,
            "response_sha256": response_sha256,
        }, artifacts
    try:
        payload = json.loads(proc.stdout)
    except json.JSONDecodeError as exc:
        return {
            "status": "invalid",
            "reason": f"model command returned invalid JSON: {exc}",
            "command": command,
            "checked_paths": checked,
            "request_path": request_rel,
            "request_sha256": request_sha256,
            "response_path": stdout_rel,
            "response_sha256": response_sha256,
        }, artifacts
    if not isinstance(payload, dict):
        return {
            "status": "invalid",
            "reason": "model command must return a JSON object.",
            "command": command,
            "checked_paths": checked,
            "request_path": request_rel,
            "request_sha256": request_sha256,
            "response_path": stdout_rel,
            "response_sha256": response_sha256,
        }, artifacts
    normalized = _normalize_model_response(payload, "model-command")
    normalized["invocation_mode"] = "command"
    normalized["command"] = command
    normalized["checked_paths"] = checked
    normalized["request_path"] = request_rel
    normalized["request_sha256"] = request_sha256
    normalized["response_path"] = stdout_rel
    normalized["response_sha256"] = response_sha256
    return normalized, artifacts


def _model_output_requested(envelope: dict[str, Any]) -> bool:
    inputs = dict(envelope.get("inputs") or {})
    return bool(_input_path_values(inputs, "model_evidence", "model_output_evidence") or _model_command(inputs))


def _ask_final_answer_boundary(
    *,
    query: str,
    hits: list[dict[str, Any]],
    model_output: dict[str, Any],
    answer_status: str,
) -> dict[str, Any]:
    retrieval_ready = bool(hits)
    retrieval_source_ids = _unique_strings(
        [
            str(value)
            for hit in hits
            if isinstance(hit, dict)
            for value in (
                hit.get("path"),
                Path(str(hit.get("path") or "source")).stem,
                _ask_source_slug(hit.get("path")),
            )
            if str(value or "").strip()
        ]
    )
    model_evidence_ids = _unique_strings([str(item) for item in model_output.get("evidence_ids") or []])
    cited_retrieval_ids = [
        evidence_id
        for evidence_id in model_evidence_ids
        if any(
            source_id.lower() == evidence_id.lower()
            or evidence_id.lower().endswith(f":{source_id.lower()}")
            for source_id in retrieval_source_ids
        )
    ]
    model_ready = (
        model_output.get("status") == "completed"
        and bool(str(model_output.get("answer") or "").strip())
        and bool(model_evidence_ids)
        and bool(cited_retrieval_ids)
        and float(model_output.get("confidence") or 0.0) > 0.0
    )
    blocking_reasons: list[str] = []
    if not retrieval_ready:
        blocking_reasons.append("retrieval sources are missing")
    if not model_ready:
        blocking_reasons.append(
            f"model synthesis status is `{model_output.get('status') or 'missing'}`, not completed with answer, confidence, and an evidence id linked to a retrieved source"
        )
    final_answer_ready = retrieval_ready and model_ready
    return {
        "schema": "autosci_ask_final_answer_boundary.v1",
        "status": "final_answer_ready" if final_answer_ready else "ask_final_answer_incomplete",
        "final_answer_ready": final_answer_ready,
        "query": query,
        "retrieval_status": "completed" if retrieval_ready else "missing",
        "retrieval_source_count": len(hits),
        "retrieval_paths": [str(hit.get("path") or "") for hit in hits],
        "answer_status": answer_status,
        "model_status": str(model_output.get("status") or "missing"),
        "model_source": str(model_output.get("source") or ""),
        "model_provider": str(model_output.get("provider") or ""),
        "model_name": str(model_output.get("model") or ""),
        "model_confidence": model_output.get("confidence", "N/A"),
        "retrieval_source_ids": retrieval_source_ids,
        "model_evidence_ids": model_evidence_ids,
        "cited_retrieval_source_ids": cited_retrieval_ids,
        "request_sha256": str(model_output.get("request_sha256") or ""),
        "response_sha256": str(model_output.get("response_sha256") or ""),
        "blocking_reasons": blocking_reasons,
        "limitations": [] if final_answer_ready else [
            "Final ask answer requires retrieved source evidence and completed model-backed synthesis with evidence ids."
        ],
    }


def _ask_crystallize_requested(envelope: dict[str, Any]) -> bool:
    inputs = dict(envelope.get("inputs") or {})
    native_options = inputs.get("native_options") if isinstance(inputs.get("native_options"), dict) else {}
    return bool(inputs.get("crystallize") or native_options.get("crystallize") or native_options.get("write"))


def _ask_format_mode(envelope: dict[str, Any]) -> str:
    inputs = dict(envelope.get("inputs") or {})
    native_options = inputs.get("native_options") if isinstance(inputs.get("native_options"), dict) else {}
    raw = str(inputs.get("format") or native_options.get("format") or "bullets").strip().lower()
    return raw if raw in {"bullets", "markdown", "table", "timeline"} else "bullets"


def _ask_markdown_cell(value: Any, limit: int = 180) -> str:
    text = " ".join(str(value or "N/A").split())
    if len(text) > limit:
        text = text[: max(0, limit - 3)].rstrip() + "..."
    return text.replace("|", "\\|")


def _ask_hit_date(hit: dict[str, Any]) -> str:
    for key in ("date", "published", "year", "timestamp"):
        value = str(hit.get(key) or "").strip()
        if value:
            return value
    return "Undated"


def _ask_answer_section(
    *,
    format_mode: str,
    hits: list[dict[str, Any]],
    answer_lines: list[str],
    model_output: dict[str, Any],
    model_completed: bool,
) -> list[str]:
    fallback = "No source-grounded wiki answer could be generated because no matching wiki sources were retrieved."
    if format_mode == "table":
        rows = [
            "| # | Evidence | Source | Score |",
            "|---:|---|---|---:|",
        ]
        for index, hit in enumerate(hits, start=1):
            rows.append(
                "| "
                f"{index} | {_ask_markdown_cell(hit.get('snippet'))} | "
                f"`{_ask_markdown_cell(hit.get('path'), 120)}` | "
                f"{float(hit.get('score') or 0.0):.3f} |"
            )
        if model_completed:
            rows.append(
                "| model | "
                f"{_ask_markdown_cell(model_output.get('answer'))} | "
                f"`{_ask_markdown_cell(', '.join(str(item) for item in model_output.get('evidence_ids') or []), 120)}` | "
                f"{float(model_output.get('confidence') or 0.0):.3f} |"
            )
        if len(rows) == 2:
            rows.append("| N/A | N/A | N/A | 0.000 |")
        return ["## Answer Table", "", *rows]
    if format_mode == "timeline":
        rows = []
        for index, hit in enumerate(hits, start=1):
            rows.append(
                f"- {index}. `{_ask_hit_date(hit)}` - `{hit.get('path')}`: {str(hit.get('snippet') or 'N/A').strip() or 'N/A'}"
            )
        if model_completed:
            rows.append(
                f"- model - `{model_output.get('model') or model_output.get('provider') or 'model'}`: {model_output.get('answer')}"
            )
        return ["## Timeline", "", *(rows or [f"- Undated - N/A: {fallback}"])]
    heading = "## Answer" if format_mode == "markdown" else "## Bullet Answer"
    rows = answer_lines or [fallback]
    if model_completed:
        rows = [*rows, f"- Model synthesis: {model_output.get('answer')}"]
    return [heading, "", *rows]


def _ask_crystallize_page_body(
    *,
    query: str,
    slug: str,
    entity_type: str,
    entity_id: str,
    hits: list[dict[str, Any]],
    answer_lines: list[str],
    model_output: dict[str, Any],
    model_completed: bool,
    final_boundary: dict[str, Any],
    gap_annotations: dict[str, Any],
    crystallize_recommendation: dict[str, Any],
    evidence_ids: list[str],
    approval_ref: str,
    format_mode: str,
) -> str:
    timestamp = datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    source_lines: list[str] = []
    for hit in hits:
        rel_path = str(hit.get("path") or "").strip()
        source_slug = _slug(Path(rel_path).stem if rel_path else "source")
        snippet = str(hit.get("snippet") or "").strip() or "N/A"
        source_lines.append(f"- [[{source_slug}]] (`{rel_path}`): {snippet}")
    if not source_lines:
        source_lines.append("- N/A")
    model_answer = str(model_output.get("answer") or "").strip()
    extractive_lines = answer_lines or [
        "No source-grounded wiki answer could be generated because no matching wiki sources were retrieved."
    ]
    return "\n".join(
        [
            "---",
            f'entity_type: {json.dumps(entity_type)}',
            f'entity_id: {json.dumps(entity_id)}',
            f'title: {json.dumps(query)}',
            f'slug: {json.dumps(slug)}',
            f'query: {json.dumps(query)}',
            f'approval_ref: {json.dumps(approval_ref)}',
            f'output_format: {json.dumps(format_mode)}',
            f'generated_at: {json.dumps(timestamp)}',
            f'status: {json.dumps("crystallized" if final_boundary.get("final_answer_ready") else "incomplete")}',
            f'source_count: {len(hits)}',
            "evidence_ids:",
            *[f"  - {json.dumps(evidence_id)}" for evidence_id in (evidence_ids or [f"ask:{slug}"])],
            "---",
            "",
            f"# {query}",
            "",
            *_ask_answer_section(
                format_mode=format_mode,
                hits=hits,
                answer_lines=answer_lines,
                model_output=model_output,
                model_completed=model_completed,
            ),
            "",
            "## Knowledge Gaps",
            "",
            *_ask_gap_markdown_lines(gap_annotations),
            "",
            "## Crystallize Recommendation",
            "",
            _ask_recommendation_markdown_line(crystallize_recommendation),
            "",
            "## Retrieved Evidence",
            "",
            *source_lines,
            "",
            "## Extractive Notes",
            "",
            *[f"- {line}" for line in extractive_lines],
            "",
            "## Finality",
            "",
            f"- Final answer boundary: `{final_boundary.get('status')}`",
            f"- Model status: `{model_output.get('status')}`",
            f"- Retrieval sources: `{len(hits)}`",
            "",
        ]
    )


def _append_ask_crystallize_edges(
    root: Path,
    page_path: Path,
    *,
    slug: str,
    hits: list[dict[str, Any]],
    evidence_ids: list[str],
) -> Path:
    edges_path = root / "graph" / "edges.jsonl"
    edges_path.parent.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    existing = set(edges_path.read_text(encoding="utf-8").splitlines()) if edges_path.exists() else set()
    lines: list[str] = []
    for hit in hits:
        source_path = str(hit.get("path") or "").strip()
        source_id = _slug(Path(source_path).stem if source_path else "retrieved-source")
        edge = {
            "edge_type": "derived_from",
            "source_type": "wiki_page",
            "source_id": source_id,
            "source_path": source_path,
            "relation": "supports_answer",
            "target_type": "ask_output",
            "target_id": f"ask-{slug}",
            "target_path": _rel(page_path),
            "evidence_ids": evidence_ids,
            "timestamp": timestamp,
        }
        line = json.dumps(edge, sort_keys=True)
        if line not in existing:
            lines.append(line)
            existing.add(line)
    if lines:
        edges_path.open("a", encoding="utf-8").write("\n".join(lines) + "\n")
    return edges_path


ASK_CRYSTALLIZE_TARGET_DIRS = {
    "concept": ("concepts", "concept"),
    "concepts": ("concepts", "concept"),
    "idea": ("ideas", "idea"),
    "ideas": ("ideas", "idea"),
    "method": ("methods", "method"),
    "methods": ("methods", "method"),
    "output": ("outputs", "ask_output"),
    "outputs": ("outputs", "ask_output"),
    "topic": ("topics", "topic"),
    "topics": ("topics", "topic"),
}


def _ask_crystallize_target_page(root: Path, target: str, slug: str) -> tuple[Path, str, str, bool]:
    raw = str(target or "").strip()
    if not raw:
        return root / "outputs" / f"{slug}.md", "ask_output", f"ask-{slug}", False
    if ":" in raw:
        prefix, value = raw.split(":", 1)
        subdir, entity_type = ASK_CRYSTALLIZE_TARGET_DIRS.get(
            prefix.strip().lower(),
            ("outputs", "ask_output"),
        )
        target_slug = _slug(value or slug)
        entity_prefix = entity_type if entity_type != "ask_output" else "ask"
        return root / subdir / f"{target_slug}.md", entity_type, f"{entity_prefix}-{target_slug}", True
    path = Path(raw)
    if path.suffix.lower() in {".md", ".markdown"}:
        if path.is_absolute():
            page = path
        elif path.parts and path.parts[0] == "wiki":
            page = root / Path(*path.parts[1:])
        else:
            page = root / path
        first_part = page.relative_to(root).parts[0] if _path_is_under(page, root) and page.relative_to(root).parts else "outputs"
        entity_type = ASK_CRYSTALLIZE_TARGET_DIRS.get(first_part, ("outputs", "ask_output"))[1]
        entity_prefix = entity_type if entity_type != "ask_output" else "ask"
        return page, entity_type, f"{entity_prefix}-{_slug(page.stem)}", True
    target_slug = _slug(raw)
    return root / "outputs" / f"{target_slug}.md", "ask_output", f"ask-{target_slug}", True


def _ask_crystallize_append_section(
    *,
    query: str,
    hits: list[dict[str, Any]],
    answer_lines: list[str],
    model_output: dict[str, Any],
    model_completed: bool,
    final_boundary: dict[str, Any],
    gap_annotations: dict[str, Any],
    crystallize_recommendation: dict[str, Any],
    evidence_ids: list[str],
    format_mode: str,
) -> str:
    timestamp = datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    return "\n".join(
        [
            f"## Ask Crystallization: {query}",
            "",
            f"- Generated at: `{timestamp}`",
            f"- Final answer boundary: `{final_boundary.get('status')}`",
            f"- Evidence ids: {', '.join(evidence_ids) if evidence_ids else 'N/A'}",
            f"- Output format: `{format_mode}`",
            "",
            *_ask_answer_section(
                format_mode=format_mode,
                hits=hits,
                answer_lines=answer_lines,
                model_output=model_output,
                model_completed=model_completed,
            ),
            "",
            "### Knowledge Gaps",
            "",
            *_ask_gap_markdown_lines(gap_annotations),
            "",
            "### Crystallize Recommendation",
            "",
            _ask_recommendation_markdown_line(crystallize_recommendation),
            "",
        ]
    )


def _ask_crystallize_writeback(
    envelope: dict[str, Any],
    *,
    query: str,
    slug: str,
    hits: list[dict[str, Any]],
    answer_lines: list[str],
    model_output: dict[str, Any],
    final_boundary: dict[str, Any],
    gap_annotations: dict[str, Any],
    crystallize_recommendation: dict[str, Any],
    evidence_ids: list[str],
    answer_artifact: str,
    retrieval_artifact: str,
    final_boundary_artifact: str,
) -> dict[str, Any]:
    requested = _ask_crystallize_requested(envelope)
    summary: dict[str, Any] = {
        "requested": requested,
        "status": "not_requested",
        "applied": False,
        "operation": "no_op",
        "path": f"knowledge/research/queries/{slug}.md",
    }
    if not requested:
        return {"summary": summary, "artifacts": [], "limitations": [], "status": "not_requested"}

    contract = _approval_contract(
        envelope,
        "ask_wiki",
        ["wiki_output_write", "wiki_graph_edge", "wiki_navigation_rebuild"],
    )
    contract, policy_decision, policy_artifacts = _policy_prepare_auto_contract_if_needed(
        envelope,
        "ask_wiki",
        ["read_local", "write_artifact", "wiki_mutation"],
        contract,
        allowlist_payload={
            "native_surface": "$ask --crystallize",
            "allowed_side_effects": ["wiki_output_write", "wiki_graph_edge", "wiki_navigation_rebuild"],
            "limitations": [
                "Policy approval applies only to local crystallized ask-output writeback.",
                "Final answer boundary must be ready before writeback is applied.",
            ],
        },
    )
    artifacts: list[dict[str, Any]] = [*policy_artifacts]
    limitations: list[str] = []
    status = "inconclusive"
    write = {
        **summary,
        "approval_ref": str(contract.get("approval_ref") or "N/A"),
        "approval_state": str(contract.get("approval_state") or "unknown"),
        "final_answer_boundary_status": str(final_boundary.get("status") or "unknown"),
        "retrieval_source_count": len(hits),
        "model_status": str(model_output.get("status") or "missing"),
    }
    page_path: Path | None = None
    log_path: Path | None = None
    edge_path: Path | None = None
    rebuilt: list[Path] = []

    preflight_ready = contract.get("execution_verified") is True or (
        contract.get("policy_auto_approved") is True and contract.get("ready_for_execution") is True
    )
    if not preflight_ready:
        limitations.extend(_approval_contract_limitations(contract))
        limitations.append("Ask crystallize write-back requires verified approval, allowlist, runtime, before, and after artifacts.")
        write.update({"status": "blocked", "operation": "blocked"})
    elif final_boundary.get("final_answer_ready") is not True:
        limitations.append("Ask crystallize write-back requires retrieved wiki evidence plus completed model synthesis with evidence ids.")
        write.update({"status": "blocked", "operation": "blocked"})
    else:
        wiki_root = _wiki_roots_for_write(envelope)[0]
        inputs = dict(envelope.get("inputs") or {})
        crystallize_target = str(inputs.get("crystallize_target") or "").strip()
        page_path, target_entity_type, target_entity_id, explicit_target = _ask_crystallize_target_page(
            wiki_root,
            crystallize_target,
            slug,
        )
        if not _path_is_under(page_path, wiki_root):
            limitations.append("Ask crystallize target escaped the configured wiki root.")
            write.update({"status": "blocked", "operation": "blocked"})
        else:
            before = page_path.read_text(encoding="utf-8", errors="replace") if page_path.exists() else ""
            format_mode = _ask_format_mode(envelope)
            model_completed = model_output.get("status") == "completed"
            if before and explicit_target:
                body = "\n".join(
                    [
                        before.rstrip(),
                        "",
                        _ask_crystallize_append_section(
                            query=query,
                            hits=hits,
                            answer_lines=answer_lines,
                            model_output=model_output,
                            model_completed=model_completed,
                            final_boundary=final_boundary,
                            gap_annotations=gap_annotations,
                            crystallize_recommendation=crystallize_recommendation,
                            evidence_ids=evidence_ids,
                            format_mode=format_mode,
                        ).rstrip(),
                        "",
                    ]
                )
            else:
                body = _ask_crystallize_page_body(
                    query=query,
                    slug=slug,
                    entity_type=target_entity_type,
                    entity_id=target_entity_id,
                    hits=hits,
                    answer_lines=answer_lines,
                    model_output=model_output,
                    model_completed=model_completed,
                    final_boundary=final_boundary,
                    gap_annotations=gap_annotations,
                    crystallize_recommendation=crystallize_recommendation,
                    evidence_ids=evidence_ids,
                    approval_ref=str(contract.get("approval_ref") or ""),
                    format_mode=format_mode,
                )
            changed = _write_text_if_changed_bridge(page_path, body)
            after = page_path.read_text(encoding="utf-8", errors="replace")
            edge_path = _append_ask_crystallize_edges(wiki_root, page_path, slug=slug, hits=hits, evidence_ids=evidence_ids)
            log_path = _write_generic_wiki_log(
                wiki_root,
                "Ask Crystallize",
                page_path,
                evidence_ids,
                "Crystallized approved ask answer into wiki outputs.",
            )
            rebuilt = _rebuild_generic_wiki_views(
                wiki_root,
                str(envelope.get("run_id") or envelope.get("sprint_id") or "autosci-ask-crystallize"),
                page_path,
                evidence_ids,
            )
            operation = "create" if not before else ("update" if changed else "no_op")
            status = "completed"
            write.update(
                {
                    "status": status,
                    "applied": True,
                    "operation": operation,
                    "path": _rel(page_path),
                    "crystallize_target": crystallize_target,
                    "target_entity_type": target_entity_type,
                    "target_entity_id": target_entity_id,
                    "changed": changed,
                    "before_sha256": _hash_text(before),
                    "after_sha256": _hash_text(after),
                    "log_path": _rel(log_path),
                    "edge_paths": [_rel(edge_path)],
                    "rebuilt_paths": [_rel(path) for path in rebuilt],
                }
            )
            artifacts.extend(
                [
                    {
                        "type": "wiki_output" if target_entity_type == "ask_output" else "wiki_page",
                        "path": _rel(page_path),
                    },
                    {"type": "wiki_log", "path": _rel(log_path)},
                    {"type": "wiki_graph_edges", "path": _rel(edge_path)},
                    *[{"type": "wiki_rebuild", "path": _rel(path)} for path in rebuilt],
                ]
            )
            runtime_artifact = _append_local_mutation_runtime_to_contract(
                envelope,
                "ask_wiki",
                contract,
                command_run="ask_wiki:local_crystallize_writeback",
                evidence_ids=evidence_ids,
                after_refs=[page_path, log_path, edge_path, *rebuilt],
                runtime_fields={
                    "crystallize_target": crystallize_target,
                    "target_entity_type": target_entity_type,
                    "target_entity_id": target_entity_id,
                    "final_answer_boundary_status": str(final_boundary.get("status") or "unknown"),
                },
            )
            artifacts.append(runtime_artifact)
            limitations.append("Ask crystallize write-back was applied only because approval_ref and execute_approved_side_effect were supplied with runtime evidence.")

    contract_artifact = _write_approval_contract_sidecar(envelope, "ask_wiki", contract)
    artifacts.insert(0, contract_artifact)

    writeback = {
        "schema": "autosci_ask_crystallize_writeback.v1",
        "task_id": "task-ask_wiki:crystallize",
        "sprint_id": str(envelope.get("sprint_id") or "sprint-autosci"),
        "node_id": "node-ask_wiki:crystallize",
        "status": status,
        "inputs": dict(envelope.get("inputs") or {}),
        "outputs": {
            "write": write,
            "query": query,
            "final_answer_boundary": final_boundary,
        },
        "artifacts": artifacts,
        "provenance": {
            "operator_id": "autosci-bridge",
            "implementation_package": "plugins/autosci",
            "timestamp": datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        },
        "limitations": limitations,
    }
    writeback_path = _output_dir(envelope, "ask_wiki") / "ask_wiki_crystallize_writeback.json"
    writeback_artifact = {"type": "ask_crystallize_writeback_json", "path": _write_evidence_payload(writeback_path, writeback)}
    proof_artifacts: list[dict[str, str]] = []
    if write.get("applied") is True and contract.get("execution_verified") is True:
        evidence_payload_path = _configured_output_path(
            envelope,
            "evidence_payload_path",
            _output_dir(envelope, "ask_wiki") / "ask_wiki.evidence.json",
            legacy_key="evidence_path",
            legacy_suffix=".json",
        )
        source_refs: list[str | Path] = [answer_artifact, retrieval_artifact, final_boundary_artifact]
        source_refs.extend(str(hit.get("path") or "") for hit in hits if str(hit.get("path") or "").strip())
        mutation_refs: list[str | Path] = [writeback_path]
        if page_path is not None:
            mutation_refs.append(page_path)
        if log_path is not None:
            mutation_refs.append(log_path)
        if edge_path is not None:
            mutation_refs.append(edge_path)
        mutation_refs.extend(rebuilt)
        proof_artifacts = _write_approved_mutation_runtime_proof_manifests(
            envelope,
            action="ask_wiki",
            native_skill="ask",
            evidence_path=evidence_payload_path,
            applied=True,
            contract=contract,
            contract_artifact=contract_artifact,
            source_refs=source_refs,
            mutation_refs=mutation_refs,
            include_wiki_mutation=True,
            source_label="ask_retrieval_and_model_synthesis",
            artifact_kind="ask_crystallize_writeback",
            include_provider_source=False,
        )
    result = {
        "summary": write,
        "artifacts": [writeback_artifact, *artifacts, *proof_artifacts],
        "limitations": limitations,
        "status": status,
    }
    if policy_decision:
        result["policy_decision"] = policy_decision
    return result


def _idea_candidates_from_model_output(
    model: dict[str, Any],
    *,
    source_mode: str,
) -> tuple[list[dict[str, Any]], list[str]]:
    raw_ideas = model.get("ideas") if isinstance(model.get("ideas"), list) else []
    model_evidence_ids = [str(item) for item in model.get("evidence_ids") or [] if str(item).strip()]
    ideas: list[dict[str, Any]] = []
    skipped: list[str] = []
    normalized_source_mode = source_mode if source_mode and source_mode != "missing" else "external"
    for index, item in enumerate(raw_ideas, start=1):
        if not isinstance(item, dict):
            skipped.append(f"ideas[{index}] is not an object")
            continue
        title = str(item.get("title") or "").strip()
        hypothesis = str(item.get("hypothesis") or "").strip()
        approach = str(item.get("approach") or "").strip()
        if not (title and hypothesis and approach):
            skipped.append(f"ideas[{index}] missing title, hypothesis, or approach")
            continue
        origin_evidence_ids = _unique_strings(
            [
                *[str(value) for value in item.get("origin_evidence_ids") or [] if str(value).strip()],
                *model_evidence_ids,
            ]
        )
        if not origin_evidence_ids:
            skipped.append(f"ideas[{index}] missing origin evidence ids")
            continue
        ideas.append(
            {
                "idea_id": str(item.get("idea_id") or f"idea-model-{index:03d}"),
                "title": title,
                "hypothesis": hypothesis,
                "approach": approach,
                "origin_evidence_ids": origin_evidence_ids,
                "novelty_hypothesis": str(
                    item.get("novelty_hypothesis")
                    or item.get("rationale")
                    or "Novelty must be validated by external source evidence and Review LLM evidence."
                ),
                "grounding_summary": str(
                    item.get("grounding_summary")
                    or model.get("answer")
                    or "Model-supplied brainstorm grounded in explicit model evidence."
                )[:600],
                "source_mode": str(item.get("source_mode") or normalized_source_mode),
                "generation_path": str(item.get("generation_path") or f"model-{model.get('invocation_mode') or 'evidence'}"),
                "duplicate_status": str(item.get("duplicate_status") or "unknown"),
                "status": str(item.get("status") or "candidate"),
                "model": str(model.get("model") or ""),
                "provider": str(model.get("provider") or ""),
            }
        )
    return ideas, skipped


def _input_path_references(inputs: dict[str, Any], keys: tuple[str, ...]) -> list[str]:
    refs: list[str] = []
    for key in keys:
        raw = inputs.get(key)
        values = raw if isinstance(raw, list) else [raw] if raw else []
        refs.extend(str(item) for item in values if str(item).strip())
    return _unique_strings(refs)


IDEATE_REQUIRED_GENERATION_PATHS = {
    "A": "landscape-driven",
    "B": "incremental",
    "C": "combination",
    "D": "innovation",
    "E": "cross-domain-transfer",
}


def _ideate_generation_path_code(value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    first = text.split(":", 1)[0].strip().upper()
    if first in IDEATE_REQUIRED_GENERATION_PATHS:
        return first
    lowered = text.lower()
    for code, label in IDEATE_REQUIRED_GENERATION_PATHS.items():
        if label in lowered:
            return code
    return ""


def _ideate_generation_path_coverage(ideas: list[dict[str, Any]]) -> dict[str, Any]:
    present = sorted(
        {
            code
            for idea in ideas
            if isinstance(idea, dict)
            for code in [_ideate_generation_path_code(idea.get("generation_path"))]
            if code
        }
    )
    missing = [code for code in IDEATE_REQUIRED_GENERATION_PATHS if code not in present]
    return {
        "required_paths": dict(IDEATE_REQUIRED_GENERATION_PATHS),
        "present_paths": present,
        "missing_paths": missing,
        "status": "complete" if not missing else "partial" if present else "missing",
    }


def _ideate_novelty_review_gate_state(inputs: dict[str, Any]) -> dict[str, Any]:
    novelty_payloads = [
        payload
        for key in ("novelty_evidence", "idea_evaluation_evidence")
        for payload in _load_optional_evidence_many(inputs.get(key))
    ]
    review_payloads = [
        payload
        for key in ("review_llm_evidence", "review_evidence", "idea_evaluation_evidence")
        for payload in _load_optional_evidence_many(inputs.get(key))
    ]
    refs = _input_path_references(
        inputs,
        ("novelty_evidence", "idea_evaluation_evidence", "review_llm_evidence", "review_evidence"),
    )
    external_completed = _external_novelty_evidence_completed(novelty_payloads)
    review_completed = _review_llm_evidence_completed(review_payloads)
    return {
        "evidence_refs": refs,
        "external_novelty_completed": external_completed,
        "review_llm_completed": review_completed,
        "ready": external_completed and review_completed,
    }


def _ideate_evidence_ids_from_payload(payload: dict[str, Any]) -> list[str]:
    ids: list[str] = []

    def collect(raw: Any) -> None:
        values = raw if isinstance(raw, list) else ([raw] if raw else [])
        ids.extend(str(item) for item in values if str(item).strip())

    collect(payload.get("evidence_ids"))
    for key in ("task_id", "node_id", "source_path"):
        value = payload.get(key)
        if str(value or "").strip():
            ids.append(str(value))
    outputs = payload.get("outputs") if isinstance(payload.get("outputs"), dict) else {}
    for nested_key in ("handoff", "runtime", "result", "review", "evaluation"):
        nested = outputs.get(nested_key) if isinstance(outputs.get(nested_key), dict) else {}
        collect(nested.get("evidence_ids"))
    return _unique_strings(ids)


def _ideate_pilot_handoff_payload_ready(payload: dict[str, Any]) -> tuple[bool, list[str]]:
    outputs = payload.get("outputs") if isinstance(payload.get("outputs"), dict) else {}
    handoff = outputs.get("handoff") if isinstance(outputs.get("handoff"), dict) else {}
    status = str(payload.get("status") or handoff.get("status") or "").strip().lower()
    explicit_ready = any(
        _truthy(value)
        for value in (
            payload.get("pilot_handoff_ready"),
            payload.get("handoff_ready"),
            payload.get("ready"),
            handoff.get("pilot_handoff_ready"),
            handoff.get("handoff_ready"),
            handoff.get("ready"),
        )
    )
    status_ready = status in {"completed", "pilot_handoff_ready", "handoff_ready"}
    evidence_ids = _ideate_evidence_ids_from_payload(payload)
    return bool(status_ready and explicit_ready and evidence_ids), evidence_ids


def _ideate_pilot_runtime_payload_ready(payload: dict[str, Any]) -> tuple[bool, list[str]]:
    action = str(_field(payload, "action") or "").strip().lower()
    node_id = str(payload.get("node_id") or "").strip().lower()
    is_pilot = action in {"run_pilot_experiment", "pilot_run", "run_pilot"} or (
        "pilot" in action and "run" in action
    ) or ("pilot" in node_id and "run" in node_id)
    status_completed = _status_ok(_field(payload, "status"))
    exit_ok = _runtime_exit_ok(payload)
    metrics = _runtime_metrics(payload)
    result_collected = bool(metrics) or _truthy(_field(payload, "result_collected", "pilot_result_collected"))
    evidence_ids = _ideate_evidence_ids_from_payload(payload)
    return bool(is_pilot and status_completed and exit_ok and result_collected and evidence_ids), evidence_ids


def _ideate_pilot_handoff_state(inputs: dict[str, Any]) -> dict[str, Any]:
    handoff_payloads = _load_optional_evidence_many(inputs.get("pilot_handoff_evidence"))
    runtime_payloads = _load_optional_evidence_many(inputs.get("pilot_runtime_evidence"))
    refs = _input_path_references(inputs, ("pilot_handoff_evidence", "pilot_runtime_evidence"))
    handoff_ready = False
    runtime_ready = False
    evidence_ids: list[str] = []
    for payload in handoff_payloads:
        ready, ids = _ideate_pilot_handoff_payload_ready(payload)
        handoff_ready = handoff_ready or ready
        evidence_ids.extend(ids)
    for payload in runtime_payloads:
        ready, ids = _ideate_pilot_runtime_payload_ready(payload)
        runtime_ready = runtime_ready or ready
        evidence_ids.extend(ids)
    evidence_ids = _unique_strings(evidence_ids)
    ready = bool((handoff_ready or runtime_ready) and evidence_ids)
    blockers: list[str] = []
    if not refs:
        blockers.append("pilot handoff or pilot runtime evidence is missing")
    elif not evidence_ids:
        blockers.append("pilot handoff/runtime evidence ids are missing")
    elif not (handoff_ready or runtime_ready):
        blockers.append("pilot handoff/runtime evidence is incomplete")
    return {
        "status": "completed" if ready else "pending",
        "ready": ready,
        "handoff_ready": handoff_ready,
        "runtime_ready": runtime_ready,
        "evidence_refs": refs,
        "evidence_ids": evidence_ids,
        "handoff_evidence_count": len(handoff_payloads),
        "runtime_evidence_count": len(runtime_payloads),
        "blocking_reasons": blockers,
    }


def _ideate_write_approval_state(inputs: dict[str, Any]) -> dict[str, Any]:
    native_options = inputs.get("native_options") if isinstance(inputs.get("native_options"), dict) else {}
    approval_ref = str(inputs.get("approval_ref") or native_options.get("approval_ref") or "").strip()
    execute_approved = bool(
        inputs.get("execute_approved_side_effect")
        or inputs.get("execute_approved")
        or native_options.get("execute_approved")
    )
    requested = bool(inputs.get("write") or native_options.get("write") or execute_approved)
    approved = bool(requested and execute_approved and approval_ref)
    return {
        "requested": requested,
        "approved": approved,
        "approval_ref": approval_ref or "N/A",
        "execute_approved": execute_approved,
    }


def _ideate_max_ideas(inputs: dict[str, Any]) -> int:
    try:
        return max(0, int(inputs.get("max_ideas") or 0))
    except (TypeError, ValueError):
        return 0


def _apply_ideate_max_ideas_selection(ideas: list[dict[str, Any]], inputs: dict[str, Any]) -> None:
    max_ideas = _ideate_max_ideas(inputs)
    selected = 0
    for idea in ideas:
        if not isinstance(idea, dict):
            continue
        if str(idea.get("status") or "") in {"blocked", "filtered"}:
            idea["selected_for_write"] = False
            idea["selection_rank"] = "N/A"
            continue
        if max_ideas > 0 and selected >= max_ideas:
            idea["selected_for_write"] = False
            idea["selection_rank"] = "N/A"
            idea["selection_reason"] = f"Not selected because max_ideas={max_ideas} was reached."
            continue
        selected += 1
        idea["selected_for_write"] = True
        idea["selection_rank"] = selected


def _ideate_final_promotion_boundary(
    *,
    ideas: list[dict[str, Any]],
    inputs: dict[str, Any],
    source_summary: dict[str, Any],
    wiki_state: dict[str, Any] | None,
    model_output: dict[str, Any] | None,
) -> dict[str, Any]:
    model_output = model_output if isinstance(model_output, dict) else {}
    source_mode = str(source_summary.get("source_mode") or (ideas[0].get("source_mode") if ideas else "") or "missing")
    wiki_state = wiki_state if isinstance(wiki_state, dict) else {}
    wiki_resolution = wiki_state.get("resolution") if isinstance(wiki_state.get("resolution"), dict) else {}
    wiki_maturity_scan_completed = bool(wiki_state) and str(wiki_state.get("status") or "") == "completed"
    failed_banlist_checked = "failed_idea_count" in source_summary
    active_dedup_checked = "active_idea_count" in source_summary
    source_ready = source_mode not in {"", "missing", "fixture"} and any(
        str(idea.get("status") or "") not in {"blocked", "filtered"}
        and str(idea.get("source_mode") or source_mode) not in {"missing", "fixture"}
        for idea in ideas
        if isinstance(idea, dict)
    )
    path_coverage = _ideate_generation_path_coverage(ideas)
    model_completed = (
        str(model_output.get("status") or "") == "completed"
        and bool(model_output.get("evidence_ids"))
        and bool(str(model_output.get("model") or model_output.get("source") or model_output.get("provider") or "").strip())
    )
    gate_state = _ideate_novelty_review_gate_state(inputs)
    gate_references = list(gate_state.get("evidence_refs") or [])
    novelty_review_refs_present = bool(gate_references)
    global_blocking: list[str] = []
    if not wiki_maturity_scan_completed:
        global_blocking.append("wiki maturity scan was not completed")
    if not failed_banlist_checked:
        global_blocking.append("failed-idea banlist was not checked")
    if not active_dedup_checked:
        global_blocking.append("active idea dedup was not checked")
    if not source_ready:
        global_blocking.append("source-backed idea evidence is missing")
    if not model_completed:
        global_blocking.append("model brainstorm provenance is missing or incomplete")
    if not novelty_review_refs_present:
        global_blocking.append("novelty/review gate evidence references are missing")
    elif not gate_state.get("external_novelty_completed"):
        global_blocking.append("completed external novelty evidence is missing")
    if novelty_review_refs_present and not gate_state.get("review_llm_completed"):
        global_blocking.append("completed Review LLM evidence is missing")
    if str(path_coverage.get("status") or "") != "complete":
        global_blocking.append("generation path coverage A/B/C/D/E is incomplete")
    idea_boundaries: list[dict[str, Any]] = []
    for idea in ideas:
        if not isinstance(idea, dict):
            continue
        idea_reasons = list(global_blocking)
        if not _ideate_generation_path_code(idea.get("generation_path")):
            idea_reasons.append("structured generation path A/B/C/D/E is missing")
        if str(idea.get("duplicate_status") or "") == "duplicate":
            idea_reasons.append("idea overlaps failed or duplicate idea banlist")
        if str(idea.get("status") or "") in {"blocked", "filtered"}:
            idea_reasons.append(f"idea status is `{idea.get('status')}`")
        ready = not idea_reasons
        idea_boundary = {
            "schema": "autosci_ideate_idea_promotion_boundary.v1",
            "idea_id": str(idea.get("idea_id") or "N/A"),
            "status": "idea_promotion_ready" if ready else "idea_promotion_incomplete",
            "promotion_ready": ready,
            "source_mode": str(idea.get("source_mode") or source_mode),
            "duplicate_status": str(idea.get("duplicate_status") or "unknown"),
            "generation_path": str(idea.get("generation_path") or "N/A"),
            "blocking_reasons": idea_reasons,
        }
        idea["final_promotion_boundary"] = idea_boundary
        idea["promotion_ready"] = ready
        idea_boundaries.append(idea_boundary)
    final_ready = bool(idea_boundaries) and all(bool(item.get("promotion_ready")) for item in idea_boundaries)
    return {
        "schema": "autosci_ideate_final_promotion_boundary.v1",
        "status": "final_promotion_ready" if final_ready else "ideate_promotion_incomplete",
        "final_promotion_ready": final_ready,
        "wiki_maturity_scan_completed": wiki_maturity_scan_completed,
        "wiki_resolution_status": str(wiki_state.get("status") or "missing"),
        "wiki_target_type": str(wiki_resolution.get("target_type") or "N/A"),
        "wiki_fallback_used": bool(wiki_resolution.get("fallback_used")) if wiki_resolution else False,
        "failed_idea_banlist_checked": failed_banlist_checked,
        "failed_idea_count": int(source_summary.get("failed_idea_count") or 0),
        "active_idea_dedup_checked": active_dedup_checked,
        "active_idea_count": int(source_summary.get("active_idea_count") or 0),
        "source_evidence_ready": source_ready,
        "source_mode": source_mode,
        "wiki_source_count": int(source_summary.get("wiki_source_count") or 0),
        "discovery_source_count": int(source_summary.get("discovery_source_count") or 0),
        "generation_path_coverage": path_coverage,
        "model_brainstorm_completed": model_completed,
        "model_status": str(model_output.get("status") or "not_requested"),
        "model_source": str(model_output.get("source") or ""),
        "model_provider": str(model_output.get("provider") or ""),
        "model_name": str(model_output.get("model") or ""),
        "model_evidence_ids": _unique_strings([str(item) for item in model_output.get("evidence_ids") or []]),
        "novelty_review_gate_references_present": novelty_review_refs_present,
        "novelty_review_gate_references": gate_references,
        "external_novelty_evidence_completed": bool(gate_state.get("external_novelty_completed")),
        "review_llm_evidence_completed": bool(gate_state.get("review_llm_completed")),
        "novelty_review_gate_ready": bool(gate_state.get("ready")),
        "idea_boundaries": idea_boundaries,
        "blocking_reasons": global_blocking,
        "limitations": [] if final_ready else [
            "Final idea promotion requires wiki maturity scan, failed-idea banlist check, source-backed evidence, model brainstorm provenance, and novelty/review gate evidence references."
        ],
    }


def _phase_record(name: str, *, status: str, completed: bool, evidence_refs: list[str], blockers: list[str]) -> dict[str, Any]:
    return {
        "name": name,
        "status": status,
        "completed": completed,
        "evidence_refs": _unique_strings(evidence_refs),
        "blocking_reasons": _unique_strings(blockers),
    }


def _ideate_pipeline_report(
    *,
    inputs: dict[str, Any],
    source_summary: dict[str, Any],
    wiki_state: dict[str, Any] | None,
    model_output: dict[str, Any] | None,
    boundary: dict[str, Any],
    ideas: list[dict[str, Any]],
) -> dict[str, Any]:
    wiki_state = wiki_state if isinstance(wiki_state, dict) else {}
    model_output = model_output if isinstance(model_output, dict) else {}
    source_refs = _input_path_references(inputs, ("discovery_evidence", "latest_discovery_evidence"))
    gate_state = _ideate_novelty_review_gate_state(inputs)
    novelty_review_refs = list(gate_state.get("evidence_refs") or [])
    review_refs = _input_path_references(inputs, ("review_llm_evidence", "review_evidence", "idea_evaluation_evidence"))
    review_llm_completed = bool(gate_state.get("review_llm_completed"))
    write_state = _ideate_write_approval_state(inputs)
    write_requested = bool(write_state.get("requested"))
    write_approved = bool(write_state.get("approved"))
    skip_validation = bool(inputs.get("skip_validation"))
    skip_pilot = bool(inputs.get("skip_pilot"))
    pilot_state = _ideate_pilot_handoff_state(inputs)
    source_ready = bool(boundary.get("source_evidence_ready"))
    wiki_ready = bool(boundary.get("wiki_maturity_scan_completed"))
    banlist_ready = bool(boundary.get("failed_idea_banlist_checked"))
    active_dedup_ready = bool(boundary.get("active_idea_dedup_checked"))
    model_ready = bool(boundary.get("model_brainstorm_completed"))
    dual_model_ready = model_ready and review_llm_completed
    validation_ready = bool(gate_state.get("ready"))
    path_coverage = boundary.get("generation_path_coverage") if isinstance(boundary.get("generation_path_coverage"), dict) else _ideate_generation_path_coverage(ideas)
    phases = [
        _phase_record(
            "phase1_landscape_scan",
            status="completed" if source_ready and wiki_ready and banlist_ready and active_dedup_ready else "incomplete",
            completed=source_ready and wiki_ready and banlist_ready and active_dedup_ready,
            evidence_refs=[*source_refs, str(wiki_state.get("artifact_path") or "")],
            blockers=[
                *([] if source_ready else ["source evidence is missing"]),
                *([] if wiki_ready else ["wiki maturity/state scan is missing"]),
                *([] if banlist_ready else ["failed idea banlist was not checked"]),
                *([] if active_dedup_ready else ["active idea dedup was not checked"]),
            ],
        ),
        _phase_record(
            "phase2_dual_model_brainstorm",
            status="completed" if dual_model_ready else "incomplete",
            completed=dual_model_ready,
            evidence_refs=[*review_refs, str(model_output.get("response_path") or ""), *[str(item) for item in model_output.get("evidence_ids") or []]],
            blockers=[
                *([] if model_ready else ["Codex/model brainstorm evidence is missing"]),
                *([] if review_llm_completed else ["independent Review LLM brainstorm evidence is missing or incomplete"]),
            ],
        ),
        _phase_record(
            "phase3_filter_and_validation",
            status="skipped" if skip_validation else "completed" if validation_ready else "incomplete",
            completed=skip_validation or validation_ready,
            evidence_refs=novelty_review_refs,
            blockers=[] if skip_validation or validation_ready else ["novelty/review gate evidence is missing"],
        ),
        _phase_record(
            "phase4_wiki_write",
            status="completed" if write_approved and bool(boundary.get("final_promotion_ready")) else "pending_approval" if write_requested else "not_requested",
            completed=write_approved and bool(boundary.get("final_promotion_ready")),
            evidence_refs=_input_path_references(inputs, ("approval_ref", "after_artifact")),
            blockers=[] if write_approved and bool(boundary.get("final_promotion_ready")) else _unique_strings(
                [
                    *([] if write_approved else ["approved writeback evidence is missing"]),
                    *([] if bool(boundary.get("final_promotion_ready")) else ["final promotion boundary is not ready"]),
                ]
            ),
        ),
        _phase_record(
            "phase5_pilot_handoff",
            status="skipped" if skip_pilot else "completed" if pilot_state.get("ready") else "pending",
            completed=skip_pilot or bool(pilot_state.get("ready")),
            evidence_refs=list(pilot_state.get("evidence_refs") or []),
            blockers=[] if skip_pilot or pilot_state.get("ready") else list(pilot_state.get("blocking_reasons") or []),
        ),
    ]
    report_ready = (
        all(bool(phase.get("completed")) for phase in phases)
        and str(path_coverage.get("status") or "") == "complete"
        and bool(boundary.get("final_promotion_ready"))
    )
    return {
        "schema": "autosci_ideate_pipeline_report.v1",
        "status": "completed" if report_ready else "incomplete",
        "pipeline_ready": report_ready,
        "required_generation_paths": dict(IDEATE_REQUIRED_GENERATION_PATHS),
        "generation_path_coverage": path_coverage,
        "phase_count": len(phases),
        "phases": phases,
        "review_llm_evidence_completed": review_llm_completed,
        "idea_count": len([idea for idea in ideas if isinstance(idea, dict)]),
        "max_ideas": _ideate_max_ideas(inputs),
        "selected_for_write_count": len([idea for idea in ideas if isinstance(idea, dict) and idea.get("selected_for_write") is True]),
        "promotion_boundary_status": str(boundary.get("status") or "missing"),
        "pilot_handoff_state": pilot_state,
        "blocking_reasons": _unique_strings(
            [
                *[reason for phase in phases for reason in phase.get("blocking_reasons", [])],
                *[f"missing generation path {code}" for code in path_coverage.get("missing_paths", [])],
                *[str(reason) for reason in boundary.get("blocking_reasons") or []],
            ]
        ),
        "limitations": [] if report_ready else [
            "Native /ideate full parity requires completed landscape scan, independent dual-model brainstorm, novelty/review validation, approved wiki writeback, pilot handoff or explicit skip, and A/B/C/D/E generation-path coverage."
        ],
    }


def _ideate_growth_report(
    *,
    inputs: dict[str, Any],
    source_summary: dict[str, Any],
    wiki_state: dict[str, Any] | None,
    boundary: dict[str, Any],
    pipeline_report: dict[str, Any],
    ideas: list[dict[str, Any]],
) -> dict[str, Any]:
    wiki_state = wiki_state if isinstance(wiki_state, dict) else {}
    phases = pipeline_report.get("phases") if isinstance(pipeline_report.get("phases"), list) else []
    phase_by_name = {str(phase.get("name") or ""): phase for phase in phases if isinstance(phase, dict)}
    write_phase = phase_by_name.get("phase4_wiki_write", {})
    write_state = _ideate_write_approval_state(inputs)
    selected_ideas = [idea for idea in ideas if isinstance(idea, dict) and idea.get("selected_for_write") is True]
    promotion_ready = [idea for idea in ideas if isinstance(idea, dict) and idea.get("promotion_ready") is True]
    filtered_or_blocked = [
        idea
        for idea in ideas
        if isinstance(idea, dict) and str(idea.get("status") or "") in {"blocked", "filtered"}
    ]
    actual_write_count = len(selected_ideas) if write_phase.get("completed") is True else 0
    return {
        "schema": "autosci_ideate_growth_report.v1",
        "status": "completed" if ideas else "incomplete",
        "topic": str(inputs.get("topic") or inputs.get("target") or inputs.get("query") or "N/A"),
        "candidate_count": len([idea for idea in ideas if isinstance(idea, dict)]),
        "selected_for_write_count": len(selected_ideas),
        "promotion_ready_count": len(promotion_ready),
        "filtered_or_blocked_count": len(filtered_or_blocked),
        "generation_path_coverage": boundary.get("generation_path_coverage") if isinstance(boundary.get("generation_path_coverage"), dict) else {},
        "wiki_scan": {
            "status": str(wiki_state.get("status") or "missing"),
            "idea_count": len(wiki_state.get("ideas") or []) if isinstance(wiki_state.get("ideas"), list) else 0,
            "experiment_count": len(wiki_state.get("experiments") or []) if isinstance(wiki_state.get("experiments"), list) else 0,
            "output_count": len(wiki_state.get("outputs") or []) if isinstance(wiki_state.get("outputs"), list) else 0,
            "graph_edge_count": len(wiki_state.get("graph_edges") or []) if isinstance(wiki_state.get("graph_edges"), list) else 0,
            "failed_idea_count": int(source_summary.get("failed_idea_count") or 0),
            "active_idea_count": int(source_summary.get("active_idea_count") or 0),
            "source_mode": str(source_summary.get("source_mode") or "missing"),
        },
        "writeback": {
            "requested": bool(write_state.get("requested")),
            "approved": bool(write_state.get("approved")),
            "approval_ref": str(write_state.get("approval_ref") or "N/A"),
            "phase_status": str(write_phase.get("status") or "missing"),
            "applied": write_phase.get("completed") is True,
            "actual_wiki_idea_write_count": actual_write_count,
            "projected_selected_count": len(selected_ideas),
            "blocking_reasons": list(write_phase.get("blocking_reasons") or []) if isinstance(write_phase.get("blocking_reasons"), list) else [],
        },
        "pilot_handoff": {
            "phase_status": str((phase_by_name.get("phase5_pilot_handoff") or {}).get("status") or "missing"),
            "completed": bool((phase_by_name.get("phase5_pilot_handoff") or {}).get("completed")),
            "evidence_refs": list((phase_by_name.get("phase5_pilot_handoff") or {}).get("evidence_refs") or []),
            "blocking_reasons": list((phase_by_name.get("phase5_pilot_handoff") or {}).get("blocking_reasons") or []),
        },
        "final_promotion_ready": bool(boundary.get("final_promotion_ready")),
        "pipeline_ready": bool(pipeline_report.get("pipeline_ready")),
        "limitations": [] if pipeline_report.get("pipeline_ready") else [
            "Growth report is evidence-only unless approved wiki writeback and pilot handoff complete."
        ],
    }


def _attach_ideate_final_promotion_boundary(
    envelope: dict[str, Any],
    *,
    ideas: list[dict[str, Any]],
    artifacts: list[dict[str, str]],
    limitations: list[str],
    source_summary: dict[str, Any],
    wiki_state: dict[str, Any] | None,
    model_output: dict[str, Any] | None = None,
) -> tuple[list[dict[str, Any]], list[dict[str, str]], list[str]]:
    inputs = dict(envelope.get("inputs") or {})
    _apply_ideate_max_ideas_selection(ideas, inputs)
    boundary = _ideate_final_promotion_boundary(
        ideas=ideas,
        inputs=inputs,
        source_summary=source_summary,
        wiki_state=wiki_state,
        model_output=model_output,
    )
    boundary_path = _write_json_sidecar(
        _output_dir(envelope, "generate_ideas") / "ideate_final_promotion_boundary.json",
        boundary,
    )
    pipeline_report = _ideate_pipeline_report(
        inputs=inputs,
        source_summary=source_summary,
        wiki_state=wiki_state,
        model_output=model_output,
        boundary=boundary,
        ideas=ideas,
    )
    pipeline_report_path = _write_json_sidecar(
        _output_dir(envelope, "generate_ideas") / "ideate_pipeline_report.json",
        pipeline_report,
    )
    pilot_state = pipeline_report.get("pilot_handoff_state") if isinstance(pipeline_report.get("pilot_handoff_state"), dict) else {}
    pilot_boundary = {
        "schema": "autosci_ideate_pilot_handoff_boundary.v1",
        "status": "pilot_handoff_ready" if pilot_state.get("ready") else "pilot_handoff_pending",
        "pilot_handoff_ready": bool(pilot_state.get("ready")),
        "handoff_ready": bool(pilot_state.get("handoff_ready")),
        "runtime_ready": bool(pilot_state.get("runtime_ready")),
        "evidence_refs": list(pilot_state.get("evidence_refs") or []),
        "evidence_ids": list(pilot_state.get("evidence_ids") or []),
        "handoff_evidence_count": int(pilot_state.get("handoff_evidence_count") or 0),
        "runtime_evidence_count": int(pilot_state.get("runtime_evidence_count") or 0),
        "blocking_reasons": list(pilot_state.get("blocking_reasons") or []),
        "limitations": [] if pilot_state.get("ready") else [
            "Pilot handoff requires completed handoff or pilot runtime evidence with explicit evidence ids."
        ],
    }
    pilot_boundary_path = _write_json_sidecar(
        _output_dir(envelope, "generate_ideas") / "ideate_pilot_handoff_boundary.json",
        pilot_boundary,
    )
    growth_report = _ideate_growth_report(
        inputs=inputs,
        source_summary=source_summary,
        wiki_state=wiki_state,
        boundary=boundary,
        pipeline_report=pipeline_report,
        ideas=ideas,
    )
    growth_report_path = _write_json_sidecar(
        _output_dir(envelope, "generate_ideas") / "ideate_growth_report.json",
        growth_report,
    )
    evidence_payload_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        _output_dir(envelope, "generate_ideas") / "generate_ideas.evidence.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    source_runtime_proof_artifact = _write_ideate_source_runtime_proof_manifest(
        envelope,
        evidence_path=evidence_payload_path,
        source_summary=source_summary,
        ideas=ideas,
        boundary_artifact=boundary_path,
        pipeline_report_artifact=pipeline_report_path,
        growth_report_artifact=growth_report_path,
    )
    pilot_runtime_proof_artifact = _write_ideate_pilot_handoff_runtime_proof_manifest(
        envelope,
        evidence_path=evidence_payload_path,
        pilot_state=pilot_state,
        pilot_boundary_artifact=pilot_boundary_path,
    )
    out_artifacts = [
        *artifacts,
        {"type": "ideate_final_promotion_boundary_json", "path": boundary_path},
        {"type": "ideate_pipeline_report_json", "path": pipeline_report_path},
        {"type": "ideate_pilot_handoff_boundary_json", "path": pilot_boundary_path},
        {"type": "ideate_growth_report_json", "path": growth_report_path},
        *([source_runtime_proof_artifact] if source_runtime_proof_artifact is not None else []),
        *([pilot_runtime_proof_artifact] if pilot_runtime_proof_artifact is not None else []),
    ]
    out_limitations = [
        *limitations,
        *[str(item) for item in boundary.get("limitations") or []],
        *[str(item) for item in pipeline_report.get("limitations") or []],
    ]
    return ideas, out_artifacts, out_limitations


def _action_ask_wiki(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    query = str(inputs.get("query") or inputs.get("target") or inputs.get("topic") or "N/A")
    output_dir = _output_dir(envelope, "ask_wiki")
    answer_path = _configured_output_path(envelope, "answer_markdown_path", output_dir / "ask_wiki_answer.md")
    retrieval_path = _configured_output_path(envelope, "retrieval_json_path", output_dir / "ask_wiki_retrieval.json")
    final_boundary_path = _configured_output_path(
        envelope,
        "ask_final_answer_boundary_path",
        output_dir / "ask_final_answer_boundary.json",
    )
    hits = _wiki_retrieval_hits(envelope, query, limit=int(inputs.get("limit") or 5))
    wiki_context = _ask_wiki_context(envelope, query)
    context_sources = wiki_context.get("sources") if isinstance(wiki_context.get("sources"), dict) else {}
    context_lines = [
        f"- `{name}`: `{source.get('status')}` at `{source.get('path')}`"
        for name, source in context_sources.items()
        if isinstance(source, dict)
    ] or ["- N/A"]
    source_lines = [
        f"- [[{_ask_source_slug(hit.get('path'))}]] `{hit['path']}` score={hit['score']}: {hit['snippet']}"
        for hit in hits
    ] or ["- N/A"]
    answer_lines = [
        f"- {hit['snippet']} Source: [[{_ask_source_slug(hit.get('path'))}]] (`{hit['path']}`)."
        for hit in hits
        if str(hit.get("snippet") or "").strip()
    ]
    gap_annotations = _ask_gap_annotations(wiki_context, hits)
    model_output, model_artifacts = _model_output(
        envelope,
        action="ask_wiki",
        prompt=query,
        context={
            "query": query,
            "retrieval_hits": hits,
            "wiki_context": wiki_context,
            "gap_annotations": gap_annotations,
        },
    )
    model_completed = model_output.get("status") == "completed"
    answer_status = "completed" if answer_lines or model_completed else "inconclusive"
    format_mode = _ask_format_mode(envelope)
    final_boundary = _ask_final_answer_boundary(
        query=query,
        hits=hits,
        model_output=model_output,
        answer_status=answer_status,
    )
    crystallize_requested_for_recommendation = _ask_crystallize_requested(envelope)
    crystallize_recommendation = _ask_crystallize_recommendation(
        hits=hits,
        model_output=model_output,
        final_boundary=final_boundary,
        requested=crystallize_requested_for_recommendation,
        gap_annotations=gap_annotations,
    )
    gap_lines = _ask_gap_markdown_lines(gap_annotations)
    recommendation_line = _ask_recommendation_markdown_line(crystallize_recommendation)
    model_section = [
        "## Model Synthesis",
        "",
        model_output.get("answer", "N/A") if model_completed else f"Model evidence status: `{model_output.get('status')}`.",
        "",
    ]
    body = "\n".join(
        [
            "# AutoSci Ask Wiki",
            "",
            f"Query: `{query}`",
            "",
            "## Wiki Context",
            "",
            *context_lines,
            "",
            "## Retrieval Sources",
            "",
            *source_lines,
            "",
            *_ask_answer_section(
                format_mode=format_mode,
                hits=hits,
                answer_lines=answer_lines,
                model_output=model_output,
                model_completed=model_completed,
            ),
            "",
            *model_section,
            "## Knowledge Gaps",
            "",
            *gap_lines,
            "",
            "## Crystallize Recommendation",
            "",
            recommendation_line,
            "",
            "## Confidence",
            "",
            f"- Retrieval-backed extractive answer: `{answer_status}`",
            f"- Source count: `{len(hits)}`",
            f"- Model evidence status: `{model_output.get('status')}`",
            f"- Final answer boundary: `{final_boundary.get('status')}`",
            "",
        ]
    )
    answer_artifact = _write_text_sidecar(answer_path, body)
    final_boundary_artifact = _write_json_sidecar(final_boundary_path, final_boundary)
    retrieval_artifact = _write_json_sidecar(
        retrieval_path,
        {
            "query": query,
            "status": "completed" if hits else "missing",
            "hits": hits,
            "requested_format": format_mode,
            "answer_status": answer_status,
            "answer_lines": answer_lines,
            "wiki_context": wiki_context,
            "gap_annotations": gap_annotations,
            "crystallize_recommendation": crystallize_recommendation,
            "model_output": model_output,
            "final_answer_boundary": final_boundary,
            "limitations": [
                "Extractive answer is grounded in retrieved wiki snippets.",
                "Model synthesis is included only when explicit model evidence or a model command was supplied.",
            ],
        },
    )
    evidence_payload_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        output_dir / "ask_wiki.evidence.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    model_runtime_proof_artifact = _write_model_runtime_proof_manifest(
        envelope,
        action="ask_wiki",
        native_skill="ask",
        evidence_path=evidence_payload_path,
        model_output=model_output,
    )
    source_runtime_proof_artifact = _write_workspace_retrieval_runtime_proof_manifest(
        envelope,
        action="ask_wiki",
        native_skill="ask",
        evidence_path=evidence_payload_path,
        retrieval_artifact=retrieval_artifact,
        hits=hits,
    )
    slug = _slug(query)
    evidence_ids = _unique_strings([f"ask:{slug}", *[str(hit["path"]) for hit in hits], *[str(item) for item in model_output.get("evidence_ids") or []]])
    artifacts = [
        {"type": "ask_answer_markdown", "path": answer_artifact},
        {"type": "ask_retrieval_json", "path": retrieval_artifact},
        {"type": "ask_final_answer_boundary_json", "path": final_boundary_artifact},
        *model_artifacts,
    ]
    if model_runtime_proof_artifact is not None:
        artifacts.append(model_runtime_proof_artifact)
    if source_runtime_proof_artifact is not None:
        artifacts.append(source_runtime_proof_artifact)
    crystallize = _ask_crystallize_writeback(
        envelope,
        query=query,
        slug=slug,
        hits=hits,
        answer_lines=answer_lines,
        model_output=model_output,
        final_boundary=final_boundary,
        gap_annotations=gap_annotations,
        crystallize_recommendation=crystallize_recommendation,
        evidence_ids=evidence_ids,
        answer_artifact=answer_artifact,
        retrieval_artifact=retrieval_artifact,
        final_boundary_artifact=final_boundary_artifact,
    )
    artifacts.extend(crystallize.get("artifacts") or [])
    crystallize_summary = crystallize.get("summary") if isinstance(crystallize.get("summary"), dict) else {}
    crystallize_requested = bool(crystallize_summary.get("requested"))
    crystallize_applied = bool(crystallize_summary.get("applied"))
    change_operation = str(crystallize_summary.get("operation") or "no_op")
    change_path = str(crystallize_summary.get("path") or f"knowledge/research/queries/{slug}.md")
    change_entity_type = str(
        crystallize_summary.get("target_entity_type")
        or ("ask_output" if crystallize_requested else "ask_query")
    )
    change_entity_id = str(crystallize_summary.get("target_entity_id") or f"ask-{slug}")
    evidence_status = "completed" if (hits or crystallize_applied) else "inconclusive"
    if crystallize_requested and not crystallize_applied:
        evidence_status = "inconclusive"
    evidence = convert_research_memory_update({
        "changes": [
            {
                "entity_type": change_entity_type,
                "entity_id": change_entity_id,
                "operation": change_operation,
                "path": change_path,
                "evidence_ids": evidence_ids,
                "confidence": (
                    0.86
                    if crystallize_applied
                    else max(0.75 if hits else 0.0, float(model_output.get("confidence") or 0.0) if model_completed else 0.0)
                ),
                "summary": (
                    "Approved ask answer crystallized into wiki outputs with source edges and rebuilt views."
                    if crystallize_applied
                    else (
                        "Ask crystallize write-back was requested but blocked by missing approval/finality evidence."
                        if crystallize_requested
                        else (
                            "Source-grounded answer generated from retrieved wiki snippets and explicit model evidence."
                            if model_completed
                            else (
                                "Source-grounded extractive answer generated from retrieved wiki snippets."
                                if hits
                                else "Ask query captured, but no matching wiki evidence was retrieved."
                            )
                        )
                    )
                ),
            }
        ],
        "artifacts": artifacts,
        "status": evidence_status,
        "limitations": [
            "Ask wiki answer is limited to local retrieved wiki snippets plus explicit model evidence when supplied.",
            "Use human review before treating the answer as final for publication.",
            *[str(item) for item in crystallize.get("limitations") or []],
        ],
    }, envelope)
    policy_decision = crystallize.get("policy_decision") if isinstance(crystallize.get("policy_decision"), dict) else {}
    return _attach_policy_decision_if_present(evidence, policy_decision)


def _source_fan_in_path(envelope: dict[str, Any], action: str) -> Path:
    return _output_dir(envelope, action) / "source_fan_in_writeback.json"


def _source_candidate_page_path(root: Path, candidate: dict[str, Any], index: int, seen_slugs: set[str]) -> Path:
    raw_slug = str(candidate.get("candidate_id") or candidate.get("title") or f"source-candidate-{index:03d}")
    slug = _slug(raw_slug)
    if slug in {"runtime-candidate", "runtime-candidate-001", "candidate", "paper"}:
        slug = _slug(str(candidate.get("title") or raw_slug))
    base = slug or f"source-candidate-{index:03d}"
    suffix = 1
    while slug in seen_slugs:
        suffix += 1
        slug = f"{base}-{suffix}"
    seen_slugs.add(slug)
    return root / "papers" / f"{slug}.md"


def _frontmatter_string(value: Any) -> str:
    return json.dumps(str(value), ensure_ascii=True)


def _source_candidate_page_body(
    candidate: dict[str, Any],
    *,
    action: str,
    query: str,
    evidence_ids: list[str],
) -> str:
    title = str(candidate.get("title") or "Untitled Source Candidate").strip() or "Untitled Source Candidate"
    candidate_id = str(candidate.get("candidate_id") or _slug(title))
    source_ref = str(candidate.get("source_ref") or "N/A")
    channels = [str(item) for item in candidate.get("source_channels") or [] if str(item).strip()]
    abstract = str(candidate.get("abstract") or "N/A").strip() or "N/A"
    rationale = str(candidate.get("ranking_rationale") or "N/A").strip() or "N/A"
    frontmatter = [
        "---",
        f"title: {_frontmatter_string(title)}",
        f"candidate_id: {_frontmatter_string(candidate_id)}",
        f"source_ref: {_frontmatter_string(source_ref)}",
        f"autosci_source_action: {_frontmatter_string(action)}",
        f"query: {_frontmatter_string(query)}",
        f"fetch_status: {_frontmatter_string(candidate.get('fetch_status') or 'unknown')}",
        f"dedup_status: {_frontmatter_string(candidate.get('dedup_status') or 'unknown')}",
        f"ranking_score: {float(candidate.get('ranking_score') or 0.0):.6g}",
        "source_channels:",
        *[f"  - {_frontmatter_string(channel)}" for channel in (channels or ["approved_runtime"])],
        "evidence_ids:",
        *[f"  - {_frontmatter_string(evidence_id)}" for evidence_id in (evidence_ids or [candidate_id])],
        "status: discovered",
        f"discovered_at: {_frontmatter_string(datetime.now(UTC).replace(microsecond=0).isoformat().replace('+00:00', 'Z'))}",
        "---",
        "",
    ]
    return "\n".join(
        [
            *frontmatter,
            f"# {title}",
            "",
            "## Abstract",
            "",
            abstract,
            "",
            "## Source",
            "",
            f"- Reference: `{source_ref}`",
            f"- Channels: {', '.join(channels) if channels else 'approved_runtime'}",
            f"- Ranking rationale: {rationale}",
            "",
        ]
    )


def _append_source_fan_in_edge(
    root: Path,
    page_path: Path,
    candidate: dict[str, Any],
    *,
    action: str,
    evidence_ids: list[str],
) -> Path:
    edges_path = root / "graph" / "edges.jsonl"
    edges_path.parent.mkdir(parents=True, exist_ok=True)
    edge = {
        "edge_type": "source_candidate_ingested",
        "source_type": "runtime_source_manifest",
        "source_id": action,
        "relation": "discovered",
        "target_type": "paper",
        "target_id": str(candidate.get("candidate_id") or page_path.stem),
        "target_path": _rel(page_path),
        "source_ref": str(candidate.get("source_ref") or "N/A"),
        "evidence_ids": evidence_ids,
        "timestamp": datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
    }
    line = json.dumps(edge, sort_keys=True)
    existing = set(edges_path.read_text(encoding="utf-8").splitlines()) if edges_path.exists() else set()
    if line not in existing:
        edges_path.open("a", encoding="utf-8").write(line + "\n")
    return edges_path


def _source_candidate_wiki_fan_in(
    envelope: dict[str, Any],
    *,
    action: str,
    query: str,
    candidates: list[dict[str, Any]],
    semantic: dict[str, Any],
    contract: dict[str, Any],
) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    native_options = inputs.get("native_options") if isinstance(inputs.get("native_options"), dict) else {}
    requested = bool(native_options.get("write"))
    summary: dict[str, Any] = {
        "requested": requested,
        "status": "not_requested",
        "applied": False,
        "candidate_count": len(candidates),
        "written_count": 0,
    }
    if not requested:
        return {"summary": summary, "artifact": None, "limitations": [], "artifacts": []}

    evidence_ids = _unique_strings(
        [str(item) for item in ((semantic.get("detail") or {}).get("evidence_ids") or []) if str(item).strip()]
    )

    if action == "daily_arxiv_prepare_finalize":
        ingest_commands = []
        for index, candidate in enumerate(candidates, start=1):
            if not isinstance(candidate, dict):
                continue
            source_ref = str(candidate.get("source_ref") or candidate.get("url") or "").strip()
            candidate_id = str(candidate.get("candidate_id") or f"daily-arxiv-candidate-{index:03d}")
            ingest_commands.append(
                {
                    "candidate_id": candidate_id,
                    "title": str(candidate.get("title") or "Untitled Source Candidate"),
                    "source_ref": source_ref,
                    "command": f"/ingest {source_ref}" if source_ref else "/ingest <missing-source-ref>",
                    "decision_required": "ingest",
                    "confidence_required": "high",
                    "evidence_ids": _unique_strings([
                        str(item)
                        for item in [
                            *evidence_ids,
                            candidate_id,
                            source_ref,
                        ]
                        if str(item).strip()
                    ]),
                }
            )
        status = "ingest_handoff_ready" if ingest_commands and semantic.get("verified") else "inconclusive"
        handoff = {
            **summary,
            "status": status,
            "applied": False,
            "handoff_ready": status == "ingest_handoff_ready",
            "ingest_completed": False,
            "written_count": 0,
            "approval_ref": str(contract.get("approval_ref") or "N/A"),
            "approval_state": str(contract.get("approval_state") or "unknown"),
            "semantic_runtime_status": str(semantic.get("status") or "unknown"),
            "ingest_commands": ingest_commands,
        }
        evidence = {
            "schema": "daily_arxiv_ingest_handoff.v1",
            "task_id": "task-daily_arxiv_prepare_finalize:ingest-handoff",
            "sprint_id": str(envelope.get("sprint_id") or "sprint-autosci"),
            "node_id": "node-daily_arxiv_prepare_finalize:ingest-handoff",
            "status": status,
            "inputs": inputs,
            "outputs": {
                "handoff": handoff,
                "query": query,
                "candidates": candidates,
                "semantic_runtime": semantic,
            },
            "artifacts": [],
            "provenance": {
                "operator_id": "autosci-bridge",
                "implementation_package": "plugins/autosci",
                "timestamp": datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
            },
            "limitations": [
                "Daily arXiv auto-ingest must invoke /ingest for each accepted paper; this bridge emitted an ingest handoff and did not write wiki paper pages directly.",
                "Final delivery readiness requires explicit digest delivery or completed /ingest evidence, not handoff creation alone.",
            ],
        }
        handoff_path = _output_dir(envelope, action) / "daily_arxiv_ingest_handoff.json"
        handoff["sidecar_path"] = _rel(handoff_path)
        artifact = {"type": "daily_arxiv_ingest_handoff_json", "path": _write_evidence_payload(handoff_path, evidence)}
        return {
            "summary": handoff,
            "artifact": artifact,
            "runtime_proof_artifact": None,
            "limitations": list(evidence["limitations"]),
            "artifacts": [],
        }

    status = "inconclusive"
    artifacts: list[dict[str, Any]] = []
    limitations: list[str] = []
    write: dict[str, Any] = {
        **summary,
        "approval_ref": str(contract.get("approval_ref") or "N/A"),
        "approval_state": str(contract.get("approval_state") or "unknown"),
        "semantic_runtime_status": str(semantic.get("status") or "unknown"),
        "written_pages": [],
    }
    detail = semantic.get("detail") if isinstance(semantic.get("detail"), dict) else {}
    source_boundary = detail.get("source_provider_boundary") if isinstance(detail.get("source_provider_boundary"), dict) else {}
    policy_auto_fan_in = (
        action == "init_sources"
        and bool(inputs.get("policy_auto_execute_side_effect"))
        and contract.get("policy_auto_approved") is True
    )
    policy_source_runtime_verified = (
        policy_auto_fan_in
        and contract.get("ready_for_execution") is True
        and contract.get("runtime_ready") is True
        and bool(detail.get("source_fetch_ok"))
        and bool(source_boundary.get("completed"))
    )
    source_runtime_verified = bool(semantic.get("verified")) or policy_source_runtime_verified
    if policy_auto_fan_in:
        write["policy_auto_fan_in"] = True
        write["source_runtime_verified_for_policy"] = policy_source_runtime_verified

    if not contract.get("execution_verified") and not policy_source_runtime_verified:
        limitations.append("Source fan-in write-back requires verified approval, allowlist, runtime, before, and after artifacts.")
    elif not source_runtime_verified:
        limitations.append("Source fan-in write-back requires verified runtime source candidates.")
    elif not candidates:
        limitations.append("Source fan-in write-back requires at least one runtime source candidate.")
    else:
        wiki_root = _wiki_roots_for_write(envelope)[0]
        seen_slugs: set[str] = set()
        written_pages: list[str] = []
        edge_paths: list[Path] = []
        for index, candidate in enumerate(candidates, start=1):
            if not isinstance(candidate, dict):
                continue
            candidate_ids = _unique_strings([*evidence_ids, str(candidate.get("candidate_id") or f"candidate-{index:03d}")])
            page_path = _source_candidate_page_path(wiki_root, candidate, index, seen_slugs)
            page_body = _source_candidate_page_body(candidate, action=action, query=query, evidence_ids=candidate_ids)
            _write_text_if_changed_bridge(page_path, page_body)
            edge_paths.append(
                _append_source_fan_in_edge(
                    wiki_root,
                    page_path,
                    candidate,
                    action=action,
                    evidence_ids=candidate_ids,
                )
            )
            written_pages.append(_rel(page_path))
            artifacts.append({"type": "wiki_paper", "path": _rel(page_path)})

        if written_pages:
            log_path = _write_generic_wiki_log(
                wiki_root,
                "Source Candidate Fan-In",
                wiki_root / "papers",
                evidence_ids,
                f"Wrote {len(written_pages)} approved runtime source candidate(s) from {action}.",
            )
            rebuild_paths = _rebuild_generic_wiki_views(
                wiki_root,
                str(envelope.get("run_id") or envelope.get("sprint_id") or "autosci-source-fan-in"),
                wiki_root / "papers",
                evidence_ids,
            )
            status = "completed"
            write.update(
                {
                    "status": status,
                    "applied": True,
                    "wiki_root": _rel(wiki_root),
                    "written_count": len(written_pages),
                    "ingest_completed": True,
                    "written_pages": written_pages,
                    "log_path": _rel(log_path),
                    "edge_paths": _unique_strings([_rel(path) for path in edge_paths]),
                    "rebuilt_paths": [_rel(path) for path in rebuild_paths],
                }
            )
            artifacts.extend(
                [
                    {"type": "wiki_log", "path": _rel(log_path)},
                    *[{"type": "wiki_graph_edges", "path": _rel(path)} for path in edge_paths],
                    *[{"type": "wiki_rebuild", "path": _rel(path)} for path in rebuild_paths],
                ]
            )
            limitations.append("Approved source fan-in wrote runtime candidates into wiki papers, graph edges, log, and views.")
            if policy_auto_fan_in:
                limitations.append(
                    "Policy auto approval applied only to wiki fan-in; source candidates came from supplied runtime evidence."
                )
        else:
            limitations.append("Source fan-in write-back found no valid candidate dictionaries to write.")

    write["status"] = status
    write["applied"] = status == "completed"
    write["ingest_completed"] = status == "completed"
    write["written_count"] = len(write.get("written_pages") or [])
    evidence = {
        "schema": "source_fan_in_writeback.v1",
        "task_id": f"task-{action}:source-fan-in",
        "sprint_id": str(envelope.get("sprint_id") or "sprint-autosci"),
        "node_id": f"node-{action}:source-fan-in",
        "status": status,
        "inputs": inputs,
        "outputs": {
            "write": write,
            "query": query,
            "candidates": candidates,
            "semantic_runtime": semantic,
        },
        "artifacts": artifacts,
        "provenance": {
            "operator_id": "autosci-bridge",
            "implementation_package": "plugins/autosci",
            "timestamp": datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        },
        "limitations": limitations,
    }
    sidecar_path = _source_fan_in_path(envelope, action)
    write["sidecar_path"] = _rel(sidecar_path)
    artifact = {"type": "source_fan_in_writeback_json", "path": _write_evidence_payload(sidecar_path, evidence)}
    native_skill = {
        "daily_arxiv_prepare_finalize": "daily-arxiv",
        "init_sources": "init",
    }.get(action, action.replace("_", "-"))
    runtime_proof_artifact = _write_wiki_mutation_runtime_proof_manifest(
        envelope,
        action=action,
        native_skill=native_skill,
        writeback_path=sidecar_path,
        writeback=evidence,
    )
    if status == "completed" and policy_auto_fan_in:
        after_paths = [sidecar_path]
        for item in artifacts:
            if not isinstance(item, dict):
                continue
            raw_path = str(item.get("path") or "").strip()
            if raw_path:
                after_paths.append(_resolve_harness_path(raw_path))
        if isinstance(runtime_proof_artifact, dict):
            raw_path = str(runtime_proof_artifact.get("path") or "").strip()
            if raw_path:
                after_paths.append(_resolve_harness_path(raw_path))
        for path in after_paths:
            _append_contract_path(contract, "after_artifacts", path)
        _refresh_approval_contract(contract)
        write["approval_state"] = str(contract.get("approval_state") or "unknown")
        write["policy_auto_after_artifacts"] = _unique_strings([_rel(path) for path in after_paths if path.exists()])
        evidence["outputs"]["write"] = write
        artifact = {"type": "source_fan_in_writeback_json", "path": _write_evidence_payload(sidecar_path, evidence)}
    return {
        "summary": write,
        "artifact": artifact,
        "runtime_proof_artifact": runtime_proof_artifact,
        "limitations": limitations,
        "artifacts": artifacts,
    }


def _init_sources_final_fan_in_boundary(
    *,
    contract: dict[str, Any],
    semantic: dict[str, Any],
    candidates: list[dict[str, Any]],
    source_boundary: dict[str, Any],
    fan_in_summary: dict[str, Any] | None,
) -> dict[str, Any]:
    fan_in_summary = fan_in_summary if isinstance(fan_in_summary, dict) else {}
    semantic_verified = semantic.get("verified") is True
    provider_boundary_completed = source_boundary.get("completed") is True
    candidate_refs = _unique_strings(
        [
            str(candidate.get("source_ref") or candidate.get("url") or candidate.get("paper_url") or candidate.get("candidate_id") or "")
            for candidate in candidates
            if isinstance(candidate, dict)
        ]
    )
    coverage_ready = len(candidates) >= 2 and len(candidate_refs) >= 2
    provider_candidates_ready = coverage_ready and provider_boundary_completed
    fan_in_completed = (
        fan_in_summary.get("ingest_completed") is True
        and str(fan_in_summary.get("status") or "") in {"completed", "ingest_completed"}
    )
    edge_paths = [str(item) for item in fan_in_summary.get("edge_paths") or [] if str(item).strip()]
    rebuilt_paths = [str(item) for item in fan_in_summary.get("rebuilt_paths") or [] if str(item).strip()]
    graph_log_rebuild_ready = bool(
        fan_in_summary.get("log_path")
        and edge_paths
        and any(path.endswith("index.md") for path in rebuilt_paths)
        and any(path.endswith("context_brief.md") for path in rebuilt_paths)
    )
    stage_provider_ready = (
        contract.get("execution_verified") is True
        and semantic_verified
        and provider_candidates_ready
    )
    final_ready = stage_provider_ready and fan_in_completed and graph_log_rebuild_ready
    limitations: list[str] = []
    if contract.get("execution_verified") is not True:
        limitations.append("Init source finality requires a verified approval contract with runtime and after-artifact evidence.")
    if not semantic_verified:
        limitations.append("Init source finality requires semantic runtime verification to pass.")
    if not provider_boundary_completed:
        limitations.append("Init source finality requires completed non-fixture provider source-channel evidence.")
    if not candidates:
        limitations.append("Init source finality requires provider-backed source candidates.")
    elif not coverage_ready:
        limitations.append("Init source finality requires at least two distinct provider-backed source candidates.")
    if not fan_in_completed:
        limitations.append("Init source finality requires approved wiki fan-in writeback.")
    if not graph_log_rebuild_ready:
        limitations.append("Init source finality requires wiki log, graph edge, index, and context rebuild evidence.")
    if not limitations:
        limitations.append("Init source final fan-in boundary passed with provider candidates and wiki mutation/rebuild evidence.")
    return {
        "schema": "autosci_init_sources_final_fan_in_boundary.v1",
        "status": "init_sources_final_fan_in_ready" if final_ready else (
            "init_sources_provider_ready" if stage_provider_ready else "init_sources_fan_in_incomplete"
        ),
        "stage_provider_ready": stage_provider_ready,
        "final_fan_in_ready": final_ready,
        "approval_contract_verified": contract.get("execution_verified") is True,
        "approval_state": str(contract.get("approval_state") or "missing"),
        "semantic_runtime_verified": semantic_verified,
        "semantic_runtime_status": str(semantic.get("status") or "missing"),
        "provider_boundary_completed": provider_boundary_completed,
        "provider_boundary_status": str(source_boundary.get("status") or "missing"),
        "candidate_count": len(candidates),
        "distinct_candidate_ref_count": len(candidate_refs),
        "coverage_ready": coverage_ready,
        "fan_in_completed": fan_in_completed,
        "written_count": int(fan_in_summary.get("written_count") or 0),
        "graph_log_rebuild_ready": graph_log_rebuild_ready,
        "log_path": str(fan_in_summary.get("log_path") or ""),
        "edge_paths": edge_paths,
        "rebuilt_paths": rebuilt_paths,
        "limitations": limitations,
    }


def _attach_init_sources_final_fan_in_boundary(
    envelope: dict[str, Any],
    evidence: dict[str, Any],
    *,
    contract: dict[str, Any],
    semantic: dict[str, Any],
    candidates: list[dict[str, Any]],
    source_boundary: dict[str, Any],
    fan_in_summary: dict[str, Any] | None,
) -> dict[str, Any]:
    boundary = _init_sources_final_fan_in_boundary(
        contract=contract,
        semantic=semantic,
        candidates=candidates,
        source_boundary=source_boundary,
        fan_in_summary=fan_in_summary,
    )
    outputs = evidence.setdefault("outputs", {})
    outputs["final_fan_in_boundary"] = boundary
    boundary_path = _write_json_sidecar(
        _output_dir(envelope, "init_sources") / "init_sources_final_fan_in_boundary.json",
        boundary,
    )
    evidence.setdefault("artifacts", []).append(
        {"type": "init_sources_final_fan_in_boundary_json", "path": boundary_path}
    )
    evidence.setdefault("limitations", []).extend(str(item) for item in boundary.get("limitations") or [])
    return evidence


def _init_native_plan_candidates(plan: dict[str, Any]) -> list[dict[str, Any]]:
    shortlist = plan.get("shortlist") if isinstance(plan.get("shortlist"), list) else []
    candidates: list[dict[str, Any]] = []
    for index, item in enumerate(shortlist, start=1):
        if not isinstance(item, dict):
            continue
        raw = dict(item)
        raw["candidate_id"] = raw.get("candidate_id") or raw.get("paper_id") or raw.get("arxiv_id") or f"init-candidate-{index:03d}"
        raw["ranking_score"] = raw.get("ranking_score") or raw.get("total_score") or raw.get("_score") or 1.0
        raw["ranking_rationale"] = raw.get("ranking_rationale") or raw.get("selection_reason") or "Native init_discovery.py selected this source candidate."
        source_channels = raw.get("source_channels") if isinstance(raw.get("source_channels"), list) else []
        raw["source_channels"] = source_channels or [str(raw.get("source") or raw.get("origin") or "native_init_discovery")]
        raw["dedup_status"] = raw.get("dedup_status") or ("known" if raw.get("user_owned") else "new")
        raw["source_ref"] = (
            raw.get("source_ref")
            or raw.get("canonical_ingest_path")
            or raw.get("prepared_path")
            or raw.get("source_path")
            or raw.get("url")
            or raw.get("arxiv_id")
            or raw.get("candidate_id")
            or ""
        )
        candidate = _candidate_from_runtime(raw, index)
        if candidate is not None:
            candidates.append(candidate)
    return candidates


def _init_native_local_plan(envelope: dict[str, Any], query: str) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    output_dir = _output_dir(envelope, "init_sources")
    output_dir.mkdir(parents=True, exist_ok=True)
    raw_root = _resolve_harness_path(inputs.get("raw_root") or "artifacts/autosci/workspace/raw")
    wiki_root = _resolve_harness_path(inputs.get("wiki_root") or "artifacts/autosci/workspace/wiki")
    prepare_manifest_path = output_dir / "init_prepare_manifest.json"
    plan_path = output_dir / "init_discovery_plan.json"
    artifacts: list[dict[str, str]] = []
    limitations: list[str] = []

    prepare_run = _run_root_tool_json(
        "init_discovery.py",
        [
            "prepare",
            "--raw-root",
            str(raw_root),
            "--output-manifest",
            str(prepare_manifest_path),
        ],
        output_dir=output_dir,
        artifact_prefix="init_discovery_prepare",
        timeout_env="AUTOSCI_INIT_DISCOVERY_TIMEOUT_SECONDS",
    )
    artifacts.extend(prepare_run.get("artifacts") or [])
    if prepare_manifest_path.exists():
        artifacts.append(_artifact("init_discovery_prepare_manifest_json", prepare_manifest_path))
    if int(prepare_run.get("returncode") or 0) != 0:
        limitations.append(
            f"Native init_discovery.py prepare failed: {str(prepare_run.get('stderr') or '').strip() or 'no stderr'}"
        )

    plan_args = [
        "plan",
        "--topic",
        query,
        "--raw-root",
        str(raw_root),
        "--wiki-root",
        str(wiki_root),
        "--no-network-fetch",
        "--output-plan",
        str(plan_path),
    ]
    if prepare_manifest_path.exists():
        plan_args.extend(["--prepared-manifest", str(prepare_manifest_path)])
    if inputs.get("init_mode"):
        plan_args.extend(["--mode", str(inputs["init_mode"])])
    plan_run = _run_root_tool_json(
        "init_discovery.py",
        plan_args,
        output_dir=output_dir,
        artifact_prefix="init_discovery_plan",
        timeout_env="AUTOSCI_INIT_DISCOVERY_TIMEOUT_SECONDS",
    )
    artifacts.extend(plan_run.get("artifacts") or [])
    if plan_path.exists():
        artifacts.append(_artifact("init_discovery_plan_json", plan_path))
    payload = plan_run.get("payload") if isinstance(plan_run.get("payload"), dict) else {}
    plan = payload.get("plan") if isinstance(payload.get("plan"), dict) else payload
    if not isinstance(plan, dict):
        plan = {}
    candidates = _init_native_plan_candidates(plan)
    if int(plan_run.get("returncode") or 0) != 0:
        limitations.append(
            f"Native init_discovery.py plan failed: {str(plan_run.get('stderr') or '').strip() or 'no stderr'}"
        )
        status = "failed"
    elif candidates:
        limitations.append(
            "Native init_discovery.py prepare/plan completed in no-network local mode; provider fetch and bulk ingest were not executed."
        )
        status = "prepared"
    else:
        limitations.append(
            "Native init_discovery.py prepare/plan completed in no-network local mode, but no shortlist candidates were selected."
        )
        status = "prepared"
    return {
        "status": status,
        "query": query,
        "mode": "init_native_local_plan",
        "candidates": candidates,
        "artifacts": artifacts,
        "limitations": limitations,
        "plan": plan,
    }


def _action_init_sources(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    native_options = inputs.get("native_options") if isinstance(inputs.get("native_options"), dict) else {}
    query = str(inputs.get("query") or inputs.get("topic") or inputs.get("target") or "AutoSci source initialization")
    contract = _approval_contract(
        envelope,
        "init_sources",
        ["network_source_fetch", "bulk_ingest", "wiki_fan_in"],
    )
    policy_decision: dict[str, Any] = {}
    policy_artifacts: list[dict[str, str]] = []
    if native_options.get("write"):
        contract, policy_decision, policy_artifacts = _policy_prepare_auto_contract(
            envelope,
            "init_sources",
            ["read_local", "write_artifact", "wiki_mutation"],
            contract,
            allowlist_payload={
                "allowed_side_effects": ["wiki_fan_in"],
                "limitations": [
                    "Policy approval applies only to approved runtime source candidates written into the local wiki.",
                    "Policy approval does not execute network/provider fetch, email delivery, remote execution, or bulk ingest.",
                ],
            },
        )
    semantic = _approval_semantic_runtime(contract, "init_sources", limit=int(inputs.get("limit") or 10))
    contract["semantic_runtime"] = semantic
    candidates = semantic.get("detail", {}).get("candidates") if isinstance(semantic.get("detail"), dict) else []
    candidates = candidates if isinstance(candidates, list) else []
    runtime_candidates_available = bool(candidates)
    local_plan = _init_native_local_plan(envelope, query) if not runtime_candidates_available and not semantic.get("verified") else {}
    if local_plan.get("candidates") and not runtime_candidates_available and not semantic.get("verified"):
        candidates = [item for item in local_plan["candidates"] if isinstance(item, dict)]
    fan_in = _source_candidate_wiki_fan_in(
        envelope,
        action="init_sources",
        query=query,
        candidates=candidates,
        semantic=semantic,
        contract=contract,
    )
    if (fan_in.get("summary") or {}).get("applied") is True and contract.get("execution_verified") is True:
        semantic = _approval_semantic_runtime(contract, "init_sources", limit=int(inputs.get("limit") or 10))
        contract["semantic_runtime"] = semantic
        refreshed_candidates = semantic.get("detail", {}).get("candidates") if isinstance(semantic.get("detail"), dict) else []
        if isinstance(refreshed_candidates, list) and refreshed_candidates:
            candidates = [item for item in refreshed_candidates if isinstance(item, dict)]
    contract_artifact = _write_approval_contract_sidecar(envelope, "init_sources", contract)
    artifacts = [contract_artifact, *policy_artifacts, *list(local_plan.get("artifacts") or [])]
    if fan_in.get("artifact"):
        artifacts.append(fan_in["artifact"])
    if fan_in.get("runtime_proof_artifact"):
        artifacts.append(fan_in["runtime_proof_artifact"])
    limitations = [
        "Init source preparation did not execute network fetch or fan-in ingest inside this bridge.",
        "Provide topic, anchors, approved network fetch, or source manifests before treating initialization as complete.",
        *_approval_contract_limitations(contract),
    ]
    if local_plan:
        limitations.extend(str(item) for item in local_plan.get("limitations") or [])
    if semantic.get("verified"):
        limitations = [
            "Init source runtime was verified from supplied approval-gated evidence; this bridge did not execute the fetch.",
        ]
    source_boundary = (semantic.get("detail") or {}).get("source_provider_boundary") if isinstance(semantic.get("detail"), dict) else {}
    if isinstance(source_boundary, dict):
        limitations.extend(str(item) for item in source_boundary.get("limitations") or [])
    limitations.extend(str(item) for item in fan_in.get("limitations") or [])
    evidence = convert_literature_discovery({
        "query": query,
        "mode": "init_runtime_verified" if semantic.get("verified") else str(local_plan.get("mode") or "init_plan"),
        "limit": int(inputs.get("limit") or 10),
        "candidates": candidates,
        "source_provider_boundary": source_boundary,
        "source_fan_in": fan_in.get("summary"),
        "status": "completed" if semantic.get("verified") else "inconclusive",
        "artifacts": artifacts,
        "limitations": limitations,
    }, envelope)
    evidence = _attach_init_sources_final_fan_in_boundary(
        envelope,
        evidence,
        contract=contract,
        semantic=semantic,
        candidates=candidates,
        source_boundary=source_boundary if isinstance(source_boundary, dict) else {},
        fan_in_summary=fan_in.get("summary") if isinstance(fan_in, dict) else {},
    )
    if policy_decision:
        evidence = _attach_policy_decision(evidence, policy_decision)
    approval_proof_artifact = _write_approval_boundary_runtime_proof_manifest(
        envelope,
        action="init_sources",
        native_skill="init",
        contract_path=_resolve_harness_path(contract_artifact["path"]),
        contract=contract,
    )
    if approval_proof_artifact is not None:
        evidence.setdefault("artifacts", []).append(approval_proof_artifact)
    evidence_payload_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        _output_dir(envelope, "init_sources") / "init_sources.evidence.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    runtime_proof_artifact = _write_source_provider_runtime_proof_manifest(
        envelope,
        action="init_sources",
        native_skill="init",
        evidence_path=evidence_payload_path,
        source_boundary=source_boundary if isinstance(source_boundary, dict) else {},
        candidates=candidates,
        artifacts=list(evidence.get("artifacts") or []),
    )
    if runtime_proof_artifact is not None:
        evidence.setdefault("artifacts", []).append(runtime_proof_artifact)
    return evidence


def _daily_arxiv_delivery_completed(contract: dict[str, Any]) -> tuple[bool, list[str]]:
    records, errors = _runtime_records(contract)
    delivery_evidence: list[str] = []
    completed = False
    for record in records:
        if not isinstance(record, dict):
            continue
        sent = (
            _truthy(_field(record, "email_sent", "digest_sent", "delivery_completed", "sent"))
            or str(_field(record, "delivery_status", "email_status", "digest_status") or "").strip().lower()
            in {"sent", "delivered", "completed", "ok", "success"}
        )
        if sent:
            completed = True
            delivery_evidence.append(str(_field(record, "delivery_id", "message_id", "digest_id") or "runtime-delivery:completed"))
    if errors:
        delivery_evidence.extend(f"runtime_error:{error}" for error in errors)
    return completed, _unique_strings(delivery_evidence)


def _daily_arxiv_final_provider_delivery_boundary(
    *,
    contract: dict[str, Any],
    semantic: dict[str, Any],
    candidates: list[dict[str, Any]],
    source_boundary: dict[str, Any],
    fan_in_summary: dict[str, Any] | None,
) -> dict[str, Any]:
    fan_in_summary = fan_in_summary if isinstance(fan_in_summary, dict) else {}
    semantic_verified = semantic.get("verified") is True
    provider_boundary_completed = source_boundary.get("completed") is True
    candidate_count = len(candidates)
    source_channels = _unique_strings(
        [
            str(channel)
            for candidate in candidates
            if isinstance(candidate, dict)
            for channel in (candidate.get("source_channels") if isinstance(candidate.get("source_channels"), list) else [])
            if str(channel).strip()
        ]
    )
    ranking_ready = bool(candidates) and all(
        isinstance(candidate, dict)
        and candidate.get("ranking_score") is not None
        and str(candidate.get("ranking_rationale") or "").strip()
        for candidate in candidates
    )
    candidate_refs = _unique_strings(
        [
            str(candidate.get("source_ref") or candidate.get("url") or candidate.get("paper_url") or candidate.get("candidate_id") or "")
            for candidate in candidates
            if isinstance(candidate, dict)
        ]
    )
    coverage_ready = len(candidates) >= 2 and len(candidate_refs) >= 2
    fan_in_completed = fan_in_summary.get("applied") is True and str(fan_in_summary.get("status") or "") == "completed"
    delivery_completed, delivery_evidence = _daily_arxiv_delivery_completed(contract)
    delivery_or_ingest_completed = fan_in_completed or delivery_completed
    approval_contract_verified = contract.get("execution_verified") is True
    stage_provider_ready = (
        approval_contract_verified
        and semantic_verified
        and provider_boundary_completed
        and coverage_ready
        and ranking_ready
    )
    final_ready = stage_provider_ready and delivery_or_ingest_completed
    limitations: list[str] = []
    if contract.get("execution_verified") is not True:
        limitations.append("Daily arXiv finality requires a verified approval contract with runtime and after-artifact evidence.")
    if not semantic_verified:
        limitations.append("Daily arXiv finality requires semantic runtime verification to pass.")
    if not provider_boundary_completed:
        limitations.append("Daily arXiv finality requires completed non-fixture provider source-channel evidence.")
    if not candidates:
        limitations.append("Daily arXiv finality requires at least one candidate.")
    elif not coverage_ready:
        limitations.append("Daily arXiv finality requires at least two distinct ranked candidates before coverage is treated as ready.")
    if not ranking_ready:
        limitations.append("Daily arXiv finality requires ranking score and rationale for every candidate.")
    if not delivery_or_ingest_completed:
        limitations.append("Daily arXiv finality requires explicit digest delivery or completed /ingest evidence.")
    if not limitations:
        limitations.append("Daily arXiv final boundary passed with provider candidates plus delivery or ingest evidence.")
    return {
        "schema": "autosci_daily_arxiv_final_provider_delivery_boundary.v1",
        "status": "daily_final_delivery_ready" if final_ready else (
            "daily_provider_ready" if stage_provider_ready else "daily_provider_delivery_incomplete"
        ),
        "stage_provider_ready": stage_provider_ready,
        "final_delivery_ready": final_ready,
        "approval_contract_verified": approval_contract_verified,
        "approval_state": str(contract.get("approval_state") or "missing"),
        "semantic_runtime_verified": semantic_verified,
        "semantic_runtime_status": str(semantic.get("status") or "missing"),
        "provider_boundary_completed": provider_boundary_completed,
        "provider_boundary_status": str(source_boundary.get("status") or "missing"),
        "candidate_count": candidate_count,
        "distinct_candidate_ref_count": len(candidate_refs),
        "coverage_ready": coverage_ready,
        "source_channels": source_channels,
        "ranking_ready": ranking_ready,
        "fan_in_completed": fan_in_completed,
        "delivery_completed": delivery_completed,
        "delivery_evidence_ids": delivery_evidence,
        "limitations": limitations,
    }


def _attach_daily_arxiv_final_provider_delivery_boundary(
    envelope: dict[str, Any],
    evidence: dict[str, Any],
    *,
    contract: dict[str, Any],
    semantic: dict[str, Any],
    candidates: list[dict[str, Any]],
    source_boundary: dict[str, Any],
    fan_in_summary: dict[str, Any] | None,
) -> dict[str, Any]:
    boundary = _daily_arxiv_final_provider_delivery_boundary(
        contract=contract,
        semantic=semantic,
        candidates=candidates,
        source_boundary=source_boundary,
        fan_in_summary=fan_in_summary,
    )
    outputs = evidence.setdefault("outputs", {})
    outputs["final_provider_delivery_boundary"] = boundary
    boundary_path = _write_json_sidecar(
        _output_dir(envelope, "daily_arxiv_prepare_finalize") / "daily_arxiv_final_provider_delivery_boundary.json",
        boundary,
    )
    evidence.setdefault("artifacts", []).append(
        {"type": "daily_arxiv_final_provider_delivery_boundary_json", "path": boundary_path}
    )
    evidence.setdefault("limitations", []).extend(str(item) for item in boundary.get("limitations") or [])
    return evidence


def _daily_arxiv_management_raw(envelope: dict[str, Any], command: str) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    approval_ref = str(inputs.get("approval_ref") or "").strip()
    paths = _control_workflow_paths(envelope, "daily_arxiv_prepare_finalize")
    paths["patch_candidates"].mkdir(parents=True, exist_ok=True)
    command_labels = {
        "setup": "daily arXiv setup",
        "status": "daily arXiv status",
        "disable": "daily arXiv disable",
    }
    protected_change = command in {"setup", "disable"}
    proposed_changes = {
        "setup": [
            "Resolve or create config/daily-arxiv.yml from config/daily-arxiv.yml.example.",
            "Verify .github/workflows/daily-arxiv.yml env exposures for S2 and DeepXiv secrets.",
            "Report missing required secrets without reading secret values.",
        ],
        "status": [
            "Inspect daily-arxiv config, workflow presence, schedule state, and required secret availability.",
            "Report recent runtime artifact availability when supplied.",
        ],
        "disable": [
            "Set schedule.enabled=false in config/daily-arxiv.yml only after explicit approval.",
            "Leave manual /daily-arxiv execution available.",
        ],
    }[command]
    evidence_ids = [f"daily-arxiv:{command}", "route:daily-arxiv"]
    proposed_change_objects = [
        {
            "change_id": f"change.manual.daily-arxiv-{command}",
            "category": "manual",
            "target": f"/daily-arxiv {command}",
            "description": proposed_changes[0],
            "evidence_ids": evidence_ids,
            "review_required": True,
            "application_state": "proposed_only",
        },
        {
            "change_id": f"change.gate.daily-arxiv-{command}",
            "category": "gate",
            "target": "daily-arxiv management approval gate",
            "description": (
                "Require explicit approval/runtime evidence before applying daily-arxiv setup or disable changes."
                if protected_change
                else "Keep status inspection read-only and prevent it from being treated as recommendation execution."
            ),
            "evidence_ids": evidence_ids,
            "review_required": True,
            "application_state": "proposed_only",
        },
    ]
    recommended_lines = [
        f"# /daily-arxiv {command} Management Boundary",
        "",
        "## Proposed Changes",
        "",
        *[f"- {item}" for item in proposed_changes],
        "",
        "## Execution Boundary",
        "",
        "- No protected config, workflow, secret, scheduler, SMTP, or wiki mutation was applied.",
        "- Apply changes only through a separately approved execution path.",
        "",
    ]
    _write_text_if_changed_bridge(paths["recommended_changes"], "\n".join(recommended_lines))
    limitations = [
        f"/daily-arxiv {command} was routed as a management subcommand, not as recommendation query text.",
        "No config, workflow, secret, scheduler, SMTP, or wiki mutation was executed by this bridge.",
    ]
    if protected_change and not approval_ref:
        limitations.append("Protected setup/disable changes require explicit approval evidence before execution.")
    return {
        "proposal_id": f"daily-arxiv-{command}",
        "scope": command_labels[command],
        "change_type": "workflow_template",
        "rationale": f"Native /daily-arxiv {command} compatibility requires a management evidence boundary.",
        "expected_effect": "Preserve native daily-arxiv management UX while keeping protected changes approval-gated.",
        "approval_state": "approved" if approval_ref else "proposed",
        "approval_ref": approval_ref,
        "status": "completed" if command == "status" else "inconclusive",
        "evidence_ids": evidence_ids,
        "collected": {
            "failed_nodes": [
                {
                    "node_id": f"daily-arxiv-{command}-management-boundary",
                    "logical_operator": "ScientificWorkflowEvolver",
                    "status": "blocked" if protected_change else "completed",
                    "gate": "daily_arxiv_management_gate",
                }
            ],
            "gate_rejection_reasons": [
                {
                    "gate_id": "daily_arxiv_management_gate",
                    "status": "blocked" if protected_change and not approval_ref else "passed",
                    "reasons": limitations,
                }
            ],
            "ambiguous_manuals_or_prompts": [],
            "insufficient_schemas": [],
            "poor_operator_bindings": [],
            "human_intervention_points": [
                {
                    "id": "daily-arxiv-approved-management",
                    "description": "Approve workflow/config mutation before setup or disable applies changes.",
                },
                {
                    "id": "daily-arxiv-secret-management",
                    "description": "Set required GitHub/SMTP secrets through the provider UI or approved CLI.",
                },
            ],
            "runtime_errors": [],
        },
        "proposed_changes": proposed_change_objects,
        "human_intervention_points": [
            "Set required GitHub/SMTP secrets through the provider UI or approved CLI.",
            "Approve workflow/config mutation before setup or disable applies changes.",
        ],
        "runtime_errors": [],
        "review": {
            "human_accept_reject_required": True,
            "daily_command": command,
            "protected_core_edits_required": protected_change,
            "protected_core_edits_applied": False,
            "application_state": "proposed_only",
            "approval_ref": approval_ref or "N/A",
        },
        "recommended_changes_path": _rel(paths["recommended_changes"]),
        "patch_candidates_path": _rel(paths["patch_candidates"]),
        "artifacts": [
            _artifact("recommended_changes_markdown", paths["recommended_changes"]),
            _artifact("patch_candidates_directory", paths["patch_candidates"]),
        ],
        "limitations": limitations,
    }


def _run_daily_arxiv_tool(
    args: list[str],
    *,
    output_dir: Path,
    artifact_prefix: str,
) -> tuple[int, str, str, list[dict[str, str]]]:
    command = [sys.executable, str(REPO_HARNESS_DIR.parent / "tools" / "daily_arxiv.py"), *args]
    timeout = int(os.environ.get("AUTOSCI_DAILY_ARXIV_TIMEOUT_SECONDS", "60"))
    try:
        proc = subprocess.run(
            command,
            cwd=REPO_HARNESS_DIR.parent,
            env={**os.environ, "PYTHONIOENCODING": "utf-8"},
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            check=False,
            timeout=timeout,
        )
        stdout = proc.stdout
        stderr = proc.stderr
        return_code = proc.returncode
    except (OSError, subprocess.TimeoutExpired) as exc:
        stdout = ""
        stderr = str(exc)
        return_code = 1
    stdout_path = _write_text_sidecar(output_dir / f"{artifact_prefix}_stdout.txt", stdout)
    stderr_path = _write_text_sidecar(output_dir / f"{artifact_prefix}_stderr.txt", stderr)
    return return_code, stdout, stderr, [
        {"type": f"{artifact_prefix}_stdout", "path": stdout_path},
        {"type": f"{artifact_prefix}_stderr", "path": stderr_path},
    ]


def _daily_arxiv_native_local_pipeline(envelope: dict[str, Any], *, allow_network_fetch: bool = False) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    feed_raw = str(inputs.get("feed") or inputs.get("daily_feed") or "").strip()
    if not feed_raw and not allow_network_fetch:
        return {}
    output_dir = _output_dir(envelope, "daily_arxiv_prepare_finalize")
    output_dir.mkdir(parents=True, exist_ok=True)
    feed_path = _resolve_harness_path(feed_raw) if feed_raw else None
    artifacts: list[dict[str, str]] = []
    limitations: list[str] = []
    if feed_path is not None and not feed_path.exists():
        return {
            "status": "failed",
            "candidates": [],
            "artifacts": [],
            "limitations": [f"Local daily-arxiv feed was not found: {feed_raw}"],
        }
    wiki_root = _resolve_harness_path(inputs.get("wiki_root") or "artifacts/autosci/workspace/wiki")
    context_path = output_dir / "daily_arxiv_recommendation_context.json"
    digest_md_path = output_dir / "daily_arxiv_digest.md"
    digest_json_path = output_dir / "daily_arxiv_digest.json"
    prepare_args = [
        "prepare",
        "--wiki-root",
        str(wiki_root),
        "--out",
        str(context_path),
    ]
    feed_out_path = output_dir / "daily_arxiv_live_feed.json"
    if feed_path is not None:
        prepare_args.extend(["--feed", str(feed_path)])
    else:
        prepare_args.extend(["--out-feed", str(feed_out_path)])
    if inputs.get("mode"):
        prepare_args.extend(["--mode", str(inputs["mode"])])
    if inputs.get("hours"):
        prepare_args.extend(["--hours", str(inputs["hours"])])
    if inputs.get("max_recommendations") or inputs.get("limit"):
        prepare_args.extend(["--max-recommendations", str(inputs.get("max_recommendations") or inputs.get("limit"))])
    if inputs.get("max_auto_ingest"):
        prepare_args.extend(["--max-auto-ingest", str(inputs["max_auto_ingest"])])
    categories = inputs.get("categories")
    if isinstance(categories, list) and categories:
        prepare_args.append("--categories")
        prepare_args.extend(str(item) for item in categories)
    if inputs.get("send_email"):
        prepare_args.extend(["--send-email", str(inputs["send_email"])])
    if inputs.get("no_external") is True or not allow_network_fetch:
        prepare_args.append("--no-external")
    code, _stdout, stderr, run_artifacts = _run_daily_arxiv_tool(
        prepare_args,
        output_dir=output_dir,
        artifact_prefix="daily_arxiv_prepare",
    )
    artifacts.extend(run_artifacts)
    if code != 0 or not context_path.exists():
        limitations.append(f"Native daily_arxiv.py prepare failed: {stderr.strip() or 'no stderr'}")
        return {"status": "failed", "candidates": [], "artifacts": artifacts, "limitations": limitations}
    if feed_path is None and feed_out_path.exists():
        artifacts.append(_artifact("daily_arxiv_live_feed_json", feed_out_path))
    artifacts.append(_artifact("daily_arxiv_recommendation_context_json", context_path))
    context_payload = _load_json(context_path)
    candidates = context_payload.get("candidates") if isinstance(context_payload.get("candidates"), list) else []
    normalized_candidates = _daily_arxiv_normalize_local_candidates(candidates)
    decisions_raw = str(inputs.get("decisions") or inputs.get("daily_decisions") or "").strip()
    if not decisions_raw:
        limitations.append(
            "Native daily_arxiv.py prepare completed; finalize is pending LLM decisions."
        )
        return {
            "status": "prepared",
            "candidates": normalized_candidates,
            "artifacts": artifacts,
            "limitations": limitations,
            "context_path": _rel(context_path),
        }
    decisions_path = _resolve_harness_path(decisions_raw)
    if not decisions_path.exists():
        limitations.append(f"Daily-arxiv decisions file was not found: {decisions_raw}")
        return {
            "status": "prepared",
            "candidates": normalized_candidates,
            "artifacts": artifacts,
            "limitations": limitations,
            "context_path": _rel(context_path),
        }
    finalize_args = [
        "finalize",
        "--context",
        str(context_path),
        "--decisions",
        str(decisions_path),
        "--out-md",
        str(digest_md_path),
        "--out-json",
        str(digest_json_path),
    ]
    code, _stdout, stderr, run_artifacts = _run_daily_arxiv_tool(
        finalize_args,
        output_dir=output_dir,
        artifact_prefix="daily_arxiv_finalize",
    )
    artifacts.extend(run_artifacts)
    if code != 0 or not digest_json_path.exists():
        limitations.append(f"Native daily_arxiv.py finalize failed: {stderr.strip() or 'no stderr'}")
        return {
            "status": "prepared",
            "candidates": normalized_candidates,
            "artifacts": artifacts,
            "limitations": limitations,
            "context_path": _rel(context_path),
        }
    artifacts.append(_artifact("daily_arxiv_digest_markdown", digest_md_path))
    artifacts.append(_artifact("daily_arxiv_digest_json", digest_json_path))
    digest_payload = _load_json(digest_json_path)
    listed = digest_payload.get("listed_candidates") if isinstance(digest_payload.get("listed_candidates"), list) else []
    normalized_listed = _daily_arxiv_normalize_local_candidates(listed or candidates)
    limitations.append(
        "Native daily_arxiv.py prepare/finalize completed; email, scheduler, and auto-ingest side effects remain gated unless explicit delivery/ingest evidence is supplied."
    )
    return {
        "status": "completed",
        "candidates": normalized_listed,
        "artifacts": artifacts,
        "limitations": limitations,
        "context_path": _rel(context_path),
        "digest_json_path": _rel(digest_json_path),
        "digest_markdown_path": _rel(digest_md_path),
    }


def _daily_arxiv_normalize_local_candidates(candidates: list[Any]) -> list[dict[str, Any]]:
    normalized: list[dict[str, Any]] = []
    for index, item in enumerate(candidates, start=1):
        if not isinstance(item, dict):
            continue
        raw = dict(item)
        if "ranking_score" not in raw:
            raw["ranking_score"] = raw.get("score") or raw.get("tool_rank_score") or 1.0
        if "ranking_rationale" not in raw:
            raw["ranking_rationale"] = raw.get("rationale") or "Native daily_arxiv.py local feed pipeline selected this candidate."
        if "source_channels" not in raw:
            signals = raw.get("signals_used") if isinstance(raw.get("signals_used"), list) else []
            raw["source_channels"] = signals or ["arxiv"]
        if "dedup_status" not in raw:
            raw["dedup_status"] = "known" if raw.get("is_known") else "new"
        if "source_ref" not in raw:
            raw["source_ref"] = raw.get("arxiv_url") or raw.get("url") or raw.get("arxiv_id") or ""
        candidate = _candidate_from_runtime(raw, index)
        if candidate is not None:
            normalized.append(candidate)
    return normalized


def _discover_native_values(raw: Any) -> list[str]:
    if isinstance(raw, list):
        return _unique_strings([str(item) for item in raw if str(item).strip()])
    text = str(raw or "").strip()
    if not text:
        return []
    return _unique_strings([item.strip() for item in text.split(",") if item.strip()])


def _discover_native_command(inputs: dict[str, Any], wiki_root: Path, allow_network_fetch: bool) -> tuple[str, list[str]]:
    query = str(inputs.get("query") or inputs.get("topic") or "").strip()
    limit = int(inputs.get("limit") or 10)
    discover_mode = str(inputs.get("discover_mode") or "").strip().lower()
    anchors = _discover_native_values(inputs.get("anchors") or inputs.get("anchor_ids"))
    negative_ids = _discover_native_values(inputs.get("negative_ids"))
    venue = str(inputs.get("venue") or "").strip()
    year = inputs.get("year")
    if inputs.get("from_wiki") and not discover_mode:
        discover_mode = "wiki"
    args: list[str]
    mode: str
    if discover_mode in {"wiki", "from-wiki"}:
        mode = "wiki"
        args = ["from-wiki"]
    elif anchors:
        mode = "anchors"
        args = ["from-anchors"]
        for anchor in anchors:
            args.extend(["--id", anchor])
        for negative in negative_ids:
            args.extend(["--negative", negative])
    elif discover_mode in {"venue", "from-venue"} or (venue and year):
        mode = "venue"
        args = ["from-venue", "--venue", venue, "--year", str(year or datetime.now(UTC).year)]
    else:
        mode = "topic"
        args = ["from-topic", query or "AutoSci literature discovery"]
    args.extend([
        "--wiki-root",
        str(wiki_root),
        "--limit",
        str(limit),
        "--workspace-root",
        str(HARNESS_DIR),
        "--repository-root",
        str(REPO_HARNESS_DIR),
    ])
    if bool(inputs.get("no_citation_expand")) and mode in {"anchors", "wiki"}:
        args.append("--no-citation-expand")
    if not allow_network_fetch:
        args.append("--no-network-fetch")
    return mode, args


def _discover_native_candidates(payload: dict[str, Any]) -> list[dict[str, Any]]:
    raw_candidates = payload.get("shortlist") if isinstance(payload.get("shortlist"), list) else payload.get("candidates")
    candidates = raw_candidates if isinstance(raw_candidates, list) else []
    normalized: list[dict[str, Any]] = []
    for index, item in enumerate(candidates, start=1):
        if not isinstance(item, dict):
            continue
        raw = dict(item)
        raw["candidate_id"] = (
            raw.get("candidate_id")
            or (f"arxiv:{raw.get('arxiv_id')}" if raw.get("arxiv_id") else "")
            or (f"s2:{raw.get('paperId')}" if raw.get("paperId") else "")
            or f"discover-candidate-{index:03d}"
        )
        raw["ranking_score"] = raw.get("ranking_score") or raw.get("_score") or raw.get("score") or 1.0
        raw["ranking_rationale"] = raw.get("ranking_rationale") or raw.get("_rationale") or "Native discover.py selected this candidate."
        sources = raw.get("_sources") if isinstance(raw.get("_sources"), list) else raw.get("source_channels")
        raw["source_channels"] = sources if isinstance(sources, list) and sources else ["native_discover"]
        raw["dedup_status"] = raw.get("dedup_status") or "new"
        raw["source_ref"] = raw.get("source_ref") or raw.get("url") or raw.get("arxiv_id") or raw.get("paperId") or ""
        candidate = _candidate_from_runtime(raw, index)
        if candidate is not None:
            normalized.append(candidate)
    return normalized


def _production_discovery_candidates(result: dict[str, Any], *, limit: int) -> list[dict[str, Any]]:
    normalized: list[dict[str, Any]] = []
    for index, item in enumerate(result.get("candidates") or [], start=1):
        if not isinstance(item, dict):
            continue
        metadata = item.get("metadata") if isinstance(item.get("metadata"), dict) else {}
        provider = str(item.get("provider") or "").strip().lower()
        relevance = item.get("relevance_gate") if isinstance(item.get("relevance_gate"), dict) else {}
        matched_terms = _unique_strings([str(value) for value in relevance.get("matched_query_terms") or []])
        matched_anchors = _unique_strings([
            str(anchor.get("label") or "")
            for group in relevance.get("coverage_group_matches") or []
            if isinstance(group, dict)
            for anchor in group.get("matched_anchor_items") or []
            if isinstance(anchor, dict) and str(anchor.get("label") or "").strip()
        ])
        if matched_terms:
            relevance_score = min(0.999, 0.50 + (0.04 * min(len(matched_terms), 8)) + (0.03 * min(len(matched_anchors), 6)))
            relevance_score = round(max(0.0, relevance_score - ((index - 1) * 0.0001)), 4)
            rationale = (
                f"Lexical relevance: matched query terms [{', '.join(matched_terms)}]; "
                f"covered anchors [{', '.join(matched_anchors) or 'none'}]; "
                f"provider {provider or 'unknown'}, provider order {index}."
            )
        else:
            relevance_score = item.get("ranking_score") or item.get("score") or max(0.0, 1.0 - ((index - 1) * 0.01))
            rationale = f"Production public-provider fallback supplied this candidate via {provider or 'unknown provider'}."
        raw = {
            "candidate_id": item.get("source_id") or item.get("canonical_id") or f"provider-candidate-{index:03d}",
            "title": item.get("title"),
            "source_ref": item.get("url") or item.get("canonical_id"),
            "source_channels": [provider] if provider else [],
            "ranking_score": relevance_score,
            "ranking_rationale": rationale,
            "relevance_gate": relevance,
            "relevance_evidence": {
                "matched_query_terms": matched_terms,
                "matched_coverage_anchors": matched_anchors,
                "provider": provider or "unknown",
                "provider_order": index,
                "scoring_method": "deterministic_lexical_relevance_v1",
            },
            "dedup_status": "new",
            "fetch_status": "fetched",
            "year": metadata.get("year"),
            "abstract": item.get("content_summary"),
        }
        candidate = _candidate_from_runtime(raw, index)
        if candidate is not None:
            normalized.append(candidate)
        if len(normalized) >= limit:
            break
    return normalized


def _production_discovery_artifacts(result: dict[str, Any], workspace_root: Path) -> list[dict[str, str]]:
    artifacts: list[dict[str, str]] = []
    for usage in result.get("provider_usage") or []:
        if not isinstance(usage, dict):
            continue
        raw_path = str(usage.get("archive_path") or "").strip()
        archive = workspace_root / raw_path if raw_path else Path()
        if raw_path and archive.is_file():
            artifacts.append(_artifact("public_provider_discovery_archive_json", archive))
    relevance_gate = result.get("relevance_gate") if isinstance(result.get("relevance_gate"), dict) else {}
    audit_path = str(relevance_gate.get("audit_path") or "").strip()
    audit = workspace_root / audit_path if audit_path else Path()
    if audit_path and audit.is_file():
        artifacts.append(_artifact("public_provider_discovery_relevance_audit_json", audit))
    return artifacts


def _discover_native_local_pipeline(envelope: dict[str, Any], *, wiki_root: Path, allow_network_fetch: bool) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    output_dir = _output_dir(envelope, "discover_literature")
    mode, args = _discover_native_command(inputs, wiki_root, allow_network_fetch)
    checkpoint_path = output_dir / "discover_native_checkpoint.json"
    args.extend(["--output-checkpoint", str(checkpoint_path)])
    run = _run_root_tool_json(
        "discover.py",
        args,
        output_dir=output_dir,
        artifact_prefix="discover_native",
        timeout_env="AUTOSCI_DISCOVER_TIMEOUT_SECONDS",
    )
    artifacts = list(run.get("artifacts") or [])
    if checkpoint_path.exists():
        artifacts.append(_artifact("discover_native_checkpoint_json", checkpoint_path))
    payload = run.get("payload") if isinstance(run.get("payload"), dict) else {}
    payload_path = output_dir / "discover_native_payload.json"
    artifacts.append(_artifact("discover_native_payload_json", payload_path))
    _write_json_sidecar(payload_path, payload)
    candidates = _discover_native_candidates(payload)
    seed = payload.get("seed") if isinstance(payload.get("seed"), dict) else {}
    native_mode = str(payload.get("mode") or seed.get("mode") or mode)
    anchors = payload.get("anchors")
    if not anchors and isinstance(seed.get("derived_anchors"), list):
        anchors = seed.get("derived_anchors")
    if not anchors and isinstance(seed.get("positive_ids"), list):
        anchors = seed.get("positive_ids")
    limitations = [str(item) for item in payload.get("limitations") or []]
    provider_relevance_gate: dict[str, Any] = {}
    if int(run.get("returncode") or 0) != 0:
        limitations.append(f"Native discover.py failed: {str(run.get('stderr') or '').strip() or 'no stderr'}")
        status = "failed"
    elif candidates:
        status = "completed"
    else:
        status = str(payload.get("status") or "inconclusive")
        if not limitations:
            limitations.append("Native discover.py completed without shortlist candidates.")
    if allow_network_fetch and not candidates:
        try:
            fallback = discover_literature(
                query=str(inputs.get("query") or inputs.get("topic") or payload.get("query") or ""),
                mode=mode,
                anchors=list(inputs.get("anchors") or inputs.get("anchor_ids") or []),
                negative_ids=list(inputs.get("negative_ids") or []),
                venue=str(inputs.get("venue") or ""),
                year=int(inputs["year"]) if inputs.get("year") else None,
                limit=int(inputs.get("limit") or payload.get("shortlist_count") or 10),
                wiki_root=wiki_root,
                workspace_root=HARNESS_DIR,
                repository_root=REPO_HARNESS_DIR,
                allow_network_fetch=True,
                no_citation_expand=bool(inputs.get("no_citation_expand")),
                fixture_fallback=False,
                progress_path=output_dir / "semantic_scholar_retry_progress.json",
                max_retries=1,
                max_retry_wait_seconds=5,
            )
            fallback_candidates = fallback.get("candidates") if isinstance(fallback.get("candidates"), list) else []
            if fallback_candidates:
                candidates = fallback_candidates
                native_mode = str(fallback.get("mode") or native_mode)
                anchors = fallback.get("anchors") if isinstance(fallback.get("anchors"), list) else anchors
                status = "completed"
                limitations.append("Native discover.py did not produce a shortlist before timeout/failure; provider-backed backend fallback produced candidates.")
                limitations.extend(str(item) for item in fallback.get("limitations") or [])
        except Exception as exc:
            limitations.append(f"Provider-backed discovery fallback failed: {type(exc).__name__}: {exc}")
    if allow_network_fetch and mode == "topic" and not candidates:
        try:
            service_workspace = output_dir / "public-provider-fallback"
            production_services = production_services_from_environment(workspace_root=service_workspace)
            discover_sources = production_services["discover_sources"]
            if hasattr(discover_sources, "limit"):
                discover_sources.limit = int(inputs.get("limit") or payload.get("shortlist_count") or 10)
            provider_result = discover_sources(
                seed_snapshot={"seeds": [{"seed_kind": "topic", "content": str(inputs.get("query") or inputs.get("topic") or "")}]},
                payload={"task_contract": {
                    "user_intent": str(inputs.get("query") or inputs.get("topic") or ""),
                    "min_provider_families": int(inputs.get("min_provider_families") or 1),
                }},
            )
            provider_candidates = _production_discovery_candidates(
                provider_result,
                limit=int(inputs.get("limit") or payload.get("shortlist_count") or 10),
            )
            provider_relevance_gate = (
                dict(provider_result.get("relevance_gate"))
                if isinstance(provider_result.get("relevance_gate"), dict)
                else {}
            )
            artifacts.extend(_production_discovery_artifacts(provider_result, service_workspace))
            limitations.extend(str(item) for item in provider_result.get("limitations") or [] if str(item).strip())
            if provider_candidates:
                candidates = provider_candidates
                native_mode = "topic_public_provider_fallback"
                status = "completed"
                limitations.append("Native topic discovery returned no shortlist; bounded production public-provider fallback supplied traceable candidates.")
            elif str(provider_result.get("status") or "") == "inconclusive":
                status = "inconclusive"
                limitations.append(
                    "Production public-provider fallback returned no publishable shortlist after deterministic relevance filtering."
                )
        except Exception as exc:
            limitations.append(f"Production public-provider discovery fallback failed: {type(exc).__name__}: {exc}")
    return {
        "status": status,
        "mode": native_mode,
        "query": str(inputs.get("query") or inputs.get("topic") or payload.get("query") or ""),
        "limit": int(inputs.get("limit") or payload.get("shortlist_count") or 10),
        "anchors": anchors if isinstance(anchors, list) else [],
        "negative_ids": _discover_native_values(inputs.get("negative_ids")),
        "venue": str(inputs.get("venue") or (seed.get("venue") if isinstance(seed, dict) else "") or ""),
        "year": inputs.get("year") or (seed.get("year") if isinstance(seed, dict) else None),
        "candidates": candidates,
        "artifacts": artifacts,
        "limitations": limitations,
        "native_payload": payload,
        "relevance_gate": provider_relevance_gate,
    }


def _action_daily_arxiv_prepare_finalize(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    daily_command = str(inputs.get("daily_command") or "run").strip().lower()
    if daily_command in {"setup", "status", "disable"}:
        return convert_workflow_evolution(_daily_arxiv_management_raw(envelope, daily_command), envelope)
    query = str(inputs.get("query") or inputs.get("topic") or "daily arXiv digest")
    contract = _approval_contract(
        envelope,
        "daily_arxiv_prepare_finalize",
        ["network_feed_fetch", "digest_email_send", "auto_ingest"],
    )
    feed_raw = str(inputs.get("feed") or inputs.get("daily_feed") or "").strip()
    daily_side_effects = ["read_local", "write_artifact"]
    if not feed_raw or inputs.get("no_external") is False:
        daily_side_effects.append("network_fetch")
    if inputs.get("send_email"):
        daily_side_effects.append("email_send")
    if inputs.get("max_auto_ingest") or str(inputs.get("mode") or "").strip().lower() in {"auto-ingest", "auto_ingest"}:
        daily_side_effects.append("wiki_mutation")
    contract, policy_decision, policy_artifacts = _policy_prepare_auto_contract(
        envelope,
        "daily_arxiv_prepare_finalize",
        daily_side_effects,
        contract,
        allowlist_payload={
            "daily_command": daily_command,
            "feed": feed_raw or "live_fetch",
            "limitations": [
                "This policy sidecar authorizes the bridge to attempt native daily_arxiv.py prepare/finalize only within configured gate bounds.",
                "SMTP delivery, scheduler mutation, and wiki auto-ingest still require concrete runtime proof before final delivery is considered complete.",
            ],
        },
    )
    semantic = _approval_semantic_runtime(
        contract,
        "daily_arxiv_prepare_finalize",
        limit=int(inputs.get("limit") or 10),
    )
    allow_network_fetch = bool(policy_decision.get("execute_side_effects") and policy_decision.get("allow_network"))
    local_pipeline = (
        {}
        if _side_effect_access_required(policy_decision)
        else _daily_arxiv_native_local_pipeline(envelope, allow_network_fetch=allow_network_fetch)
    )
    contract["semantic_runtime"] = semantic
    candidates = semantic.get("detail", {}).get("candidates") if isinstance(semantic.get("detail"), dict) else []
    candidates = candidates if isinstance(candidates, list) else []
    if local_pipeline.get("candidates") and not semantic.get("verified"):
        candidates = [item for item in local_pipeline["candidates"] if isinstance(item, dict)]
    contract_artifact = _write_approval_contract_sidecar(envelope, "daily_arxiv_prepare_finalize", contract)
    fan_in = _source_candidate_wiki_fan_in(
        envelope,
        action="daily_arxiv_prepare_finalize",
        query=query,
        candidates=candidates,
        semantic=semantic,
        contract=contract,
    )
    review_llm, review_evidence_ids, review_artifacts = _claim_review_llm_context(
        envelope,
        "daily_arxiv_digest_selection",
        artifact_type="daily_arxiv_review_llm_evidence_json",
    )
    artifacts = [contract_artifact, *policy_artifacts, *list(local_pipeline.get("artifacts") or [])]
    if fan_in.get("artifact"):
        artifacts.append(fan_in["artifact"])
    if fan_in.get("runtime_proof_artifact"):
        artifacts.append(fan_in["runtime_proof_artifact"])
    artifacts.extend(review_artifacts)
    limitations = [
        "Daily arXiv prepare/finalize is approval-gated; this bridge did not execute network feed fetch, email, or auto-ingest.",
        "Provide approved feed fetch evidence before treating this digest as complete.",
        *_approval_contract_limitations(contract),
    ]
    if local_pipeline:
        limitations.extend(str(item) for item in local_pipeline.get("limitations") or [])
    if semantic.get("verified"):
        limitations = [
            "Daily arXiv runtime was verified from supplied approval-gated evidence; this bridge did not execute network/email side effects.",
        ]
    source_boundary = (semantic.get("detail") or {}).get("source_provider_boundary") if isinstance(semantic.get("detail"), dict) else {}
    if isinstance(source_boundary, dict):
        limitations.extend(str(item) for item in source_boundary.get("limitations") or [])
    limitations.extend(str(item) for item in fan_in.get("limitations") or [])
    if review_llm.get("status") == "completed":
        limitations.append(
            f"Review LLM digest-selection evidence was attached from `{review_llm.get('source_path')}`."
        )
    elif inputs.get("require_review_llm") or _input_path_values(inputs, "review_llm_evidence", "review_evidence"):
        limitations.extend(str(item) for item in review_llm.get("reasons") or ["Review LLM evidence did not complete."])
    evidence = convert_literature_discovery({
        "query": query,
        "mode": (
            "daily_arxiv_runtime_verified"
            if semantic.get("verified")
            else "daily_arxiv_native_local_finalized"
            if local_pipeline.get("status") == "completed"
            else "daily_arxiv_native_local_prepare"
            if local_pipeline.get("status") == "prepared"
            else "daily_arxiv_plan"
        ),
        "limit": int(inputs.get("limit") or 10),
        "candidates": candidates,
        "source_provider_boundary": source_boundary,
        "source_fan_in": fan_in.get("summary"),
        "status": "completed" if semantic.get("verified") or local_pipeline.get("status") == "completed" else "inconclusive",
        "artifacts": artifacts,
        "limitations": limitations,
    }, envelope)
    evidence.setdefault("outputs", {})["review_llm"] = review_llm
    evidence["outputs"]["review_llm_completed"] = review_llm.get("status") == "completed"
    evidence["outputs"]["review_evidence_ids"] = review_evidence_ids
    evidence = _attach_daily_arxiv_final_provider_delivery_boundary(
        envelope,
        evidence,
        contract=contract,
        semantic=semantic,
        candidates=candidates,
        source_boundary=source_boundary if isinstance(source_boundary, dict) else {},
        fan_in_summary=fan_in.get("summary") if isinstance(fan_in, dict) else {},
    )
    approval_proof_artifact = _write_approval_boundary_runtime_proof_manifest(
        envelope,
        action="daily_arxiv_prepare_finalize",
        native_skill="daily-arxiv",
        contract_path=_resolve_harness_path(contract_artifact["path"]),
        contract=contract,
    )
    if approval_proof_artifact is not None:
        evidence.setdefault("artifacts", []).append(approval_proof_artifact)
    evidence_payload_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        _output_dir(envelope, "daily_arxiv_prepare_finalize") / "daily_arxiv_prepare_finalize.evidence.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    runtime_proof_artifact = _write_source_provider_runtime_proof_manifest(
        envelope,
        action="daily_arxiv_prepare_finalize",
        native_skill="daily-arxiv",
        evidence_path=evidence_payload_path,
        source_boundary=source_boundary if isinstance(source_boundary, dict) else {},
        candidates=candidates,
        artifacts=list(evidence.get("artifacts") or []),
    )
    if runtime_proof_artifact is not None:
        evidence.setdefault("artifacts", []).append(runtime_proof_artifact)
    review_runtime_proof_artifact = _write_review_context_runtime_proof_manifest(
        envelope,
        action="daily_arxiv_prepare_finalize",
        native_skill="daily-arxiv",
        evidence_path=evidence_payload_path,
        review_llm=review_llm,
    )
    if review_runtime_proof_artifact is not None:
        evidence.setdefault("artifacts", []).append(review_runtime_proof_artifact)
    side_effect_proof_artifact = _write_side_effect_execution_runtime_proof_manifest(
        envelope,
        action="daily_arxiv_prepare_finalize",
        native_skill="daily-arxiv",
        evidence_path=evidence_payload_path,
        boundary=(evidence.get("outputs") or {}).get("final_provider_delivery_boundary")
        if isinstance(evidence.get("outputs"), dict)
        else {},
        artifacts=list(evidence.get("artifacts") or []),
    )
    if side_effect_proof_artifact is not None:
        evidence.setdefault("artifacts", []).append(side_effect_proof_artifact)
    evidence = _attach_policy_decision(evidence, policy_decision)
    if _side_effect_access_required(policy_decision) and not semantic.get("verified"):
        request_payload, request_artifact = _side_effect_access_request(
            envelope,
            "daily_arxiv_prepare_finalize",
            "daily-arxiv",
            policy_decision,
            requested_side_effects=daily_side_effects,
            required_inputs=[
                "approval_ref or permissive gate mode for live feed fetch",
                "daily-arxiv decisions JSON for finalize",
                "delivery or wiki-ingest runtime proof when email/auto-ingest is requested",
            ],
        )
        evidence = _attach_side_effect_access_request(evidence, request_payload, request_artifact)
    return evidence


def _action_discover_literature(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    wiki_root = _resolve_harness_path(str(inputs.get("wiki_root") or "artifacts/autosci/workspace/wiki"))
    runtime_requested = bool(
        inputs.get("approval_ref")
        or inputs.get("allowlist_evidence")
        or inputs.get("before_artifacts")
        or inputs.get("runtime_evidence")
        or inputs.get("after_artifacts")
    )
    if runtime_requested:
        query = str(inputs.get("query") or inputs.get("topic") or "AutoSci literature discovery")
        limit = int(inputs.get("limit") or 10)
        contract = _approval_contract(
            envelope,
            "discover_literature",
            ["network_source_fetch", "source_manifest_ingest"],
        )
        semantic = _approval_semantic_runtime(contract, "discover_literature", limit=limit)
        contract["semantic_runtime"] = semantic
        candidates = semantic.get("detail", {}).get("candidates") if isinstance(semantic.get("detail"), dict) else []
        candidates = candidates if isinstance(candidates, list) else []
        contract_artifact = _write_approval_contract_sidecar(envelope, "discover_literature", contract)
        runtime_artifacts = _contract_existing_artifacts(
            contract,
            "runtime_evidence",
            "source_runtime_evidence_json",
        )
        limitations = [
            "Literature discovery used supplied approval-gated runtime evidence; the bridge did not execute network fetches.",
            *_approval_contract_limitations(contract),
        ]
        if semantic.get("verified"):
            limitations = [
                "Literature discovery runtime was verified from supplied approval-gated source evidence; this bridge did not execute the fetch.",
            ]
        source_boundary = (semantic.get("detail") or {}).get("source_provider_boundary") if isinstance(semantic.get("detail"), dict) else {}
        if isinstance(source_boundary, dict):
            limitations.extend(str(item) for item in source_boundary.get("limitations") or [])
        raw = {
            "query": query,
            "mode": "discover_literature_runtime_verified" if semantic.get("verified") else "discover_literature_runtime_pending",
            "limit": limit,
            "candidates": candidates,
            "source_provider_boundary": source_boundary,
            "status": "completed" if semantic.get("verified") else "inconclusive",
            "artifacts": [contract_artifact, *runtime_artifacts],
            "limitations": limitations,
        }
        raw = _attach_discover_final_shortlist_boundary(
            envelope,
            raw,
            mode=str(raw["mode"]),
        )
        evidence_payload_path = _configured_output_path(
            envelope,
            "evidence_payload_path",
            _output_dir(envelope, "discover_literature") / "discover_literature.evidence.json",
            legacy_key="evidence_path",
            legacy_suffix=".json",
        )
        runtime_proof_artifact = _write_source_provider_runtime_proof_manifest(
            envelope,
            action="discover_literature",
            native_skill="discover",
            evidence_path=evidence_payload_path,
            source_boundary=raw.get("source_provider_boundary") if isinstance(raw.get("source_provider_boundary"), dict) else {},
            candidates=candidates,
            artifacts=list(raw.get("artifacts") or []),
        )
        if runtime_proof_artifact is not None:
            raw.setdefault("artifacts", []).append(runtime_proof_artifact)
        return convert_literature_discovery(
            raw,
            envelope,
        )

    allow_network_fetch = str(inputs.get("allow_network_fetch", "true")).lower() not in {"0", "false", "no"}
    if os.environ.get("AUTOSCI_DISABLE_NETWORK_FETCH", "").lower() in {"1", "true", "yes"}:
        allow_network_fetch = False
    fixture_fallback = bool(inputs.get("fixture_fallback")) or bool(inputs.get("smoke_mode")) or (
        str(envelope.get("mode") or "") == "fixture"
        and not any(
            key in inputs
            for key in (
                "discover_mode",
                "from_wiki",
                "anchors",
                "anchor_ids",
                "venue",
                "year",
                "limit",
            )
        )
    )
    discover_mode = str(inputs.get("discover_mode") or "")
    if inputs.get("from_wiki") and not discover_mode:
        discover_mode = "wiki"
    progress_path = _output_dir(envelope, "discover_literature") / "semantic_scholar_retry_progress.json"
    if fixture_fallback:
        raw = discover_literature(
            query=str(inputs.get("query") or inputs.get("topic") or ""),
            mode=discover_mode,
            anchors=list(inputs.get("anchors") or inputs.get("anchor_ids") or []),
            negative_ids=list(inputs.get("negative_ids") or []),
            venue=str(inputs.get("venue") or ""),
            year=int(inputs["year"]) if inputs.get("year") else None,
            limit=int(inputs.get("limit") or 10),
            wiki_root=wiki_root,
            workspace_root=HARNESS_DIR,
            repository_root=REPO_HARNESS_DIR,
            allow_network_fetch=allow_network_fetch,
            no_citation_expand=bool(inputs.get("no_citation_expand")),
            fixture_fallback=True,
            progress_path=progress_path,
        )
    else:
        raw = _discover_native_local_pipeline(
            envelope,
            wiki_root=wiki_root,
            allow_network_fetch=allow_network_fetch,
        )
    raw["source_provider_boundary"] = _source_provider_boundary(
        [],
        raw.get("candidates") if isinstance(raw.get("candidates"), list) else [],
        action="discover_literature",
    )
    raw = _attach_discover_final_shortlist_boundary(
        envelope,
        raw,
        mode=str(raw.get("mode") or "unknown"),
    )
    evidence_payload_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        _output_dir(envelope, "discover_literature") / "discover_literature.evidence.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    runtime_proof_artifact = _write_source_provider_runtime_proof_manifest(
        envelope,
        action="discover_literature",
        native_skill="discover",
        evidence_path=evidence_payload_path,
        source_boundary=raw.get("source_provider_boundary") if isinstance(raw.get("source_provider_boundary"), dict) else {},
        candidates=raw.get("candidates") if isinstance(raw.get("candidates"), list) else [],
        artifacts=list(raw.get("artifacts") or []),
    )
    if runtime_proof_artifact is not None:
        raw.setdefault("artifacts", []).append(runtime_proof_artifact)
    return convert_literature_discovery(
        raw,
        envelope,
    )


def _phase9_sidecar_paths(envelope: dict[str, Any]) -> tuple[Path, Path]:
    output_dir = _output_dir(envelope, "ingest_paper")
    outputs = envelope.get("outputs") if isinstance(envelope.get("outputs"), dict) else {}
    memory_raw = outputs.get("memory_update_path") if isinstance(outputs, dict) else None
    graph_raw = outputs.get("graph_update_path") if isinstance(outputs, dict) else None
    memory_path = Path(str(memory_raw)) if memory_raw else output_dir / "research_memory_update.json"
    graph_path = Path(str(graph_raw)) if graph_raw else output_dir / "research_graph_update.json"
    if not memory_path.is_absolute():
        memory_path = HARNESS_DIR / memory_path
    if not graph_path.is_absolute():
        graph_path = HARNESS_DIR / graph_path
    return memory_path, graph_path


def _write_phase9_foundation_sidecars(envelope: dict[str, Any], paper_evidence: dict[str, Any]) -> list[str]:
    memory_path, graph_path = _phase9_sidecar_paths(envelope)
    memory_evidence = convert_research_memory_update(_paper_update_raw(envelope, paper_evidence), envelope)
    graph_evidence = convert_research_graph_update(_paper_update_raw(envelope, paper_evidence), envelope)
    return [
        _write_evidence_payload(memory_path, memory_evidence),
        _write_evidence_payload(graph_path, graph_evidence),
    ]


def _register_ingest_paper_wiki(
    envelope: dict[str, Any],
    paper_evidence: dict[str, Any],
    sidecar_paths: list[str],
) -> list[dict[str, str]]:
    outputs = paper_evidence.get("outputs") if isinstance(paper_evidence.get("outputs"), dict) else {}
    paper = outputs.get("paper") if isinstance(outputs.get("paper"), dict) else {}
    paper_id = str(paper.get("paper_id") or "").strip()
    title = str(paper.get("title") or "").strip()
    if not paper_id or not title:
        return []
    existing_state = _ingest_wiki_registration_state(envelope, paper)
    if all(
        bool(existing_state.get(key))
        for key in ("paper_registered", "graph_registered", "index_rebuilt", "context_rebuilt")
    ):
        return []

    wiki_root = _wiki_roots_for_write(envelope)[0]
    page_path = wiki_root / "papers" / f"{_slug(paper_id)}.md"
    evidence_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        _output_dir(envelope, "ingest_paper") / "ingest_paper.evidence.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    evidence_refs = _unique_strings(
        [
            _rel(evidence_path),
            *[str(path) for path in sidecar_paths],
            str(paper.get("source_ref") or ""),
        ]
    )
    abstract = str(paper.get("abstract") or "").strip()
    sections = paper.get("sections") if isinstance(paper.get("sections"), list) else []
    section_lines: list[str] = []
    for section in sections[:6]:
        if not isinstance(section, dict):
            continue
        section_title = str(section.get("title") or "Section").strip() or "Section"
        section_text = str(section.get("text") or "").strip()
        if section_text:
            section_lines.extend([f"### {section_title}", "", section_text, ""])

    page_body = "\n".join(
        [
            "---",
            f"title: {_frontmatter_string(title)}",
            f"paper_id: {_frontmatter_string(paper_id)}",
            f"source_ref: {_frontmatter_string(paper.get('source_ref') or '')}",
            f"source_type: {_frontmatter_string(paper.get('source_type') or '')}",
            "autosci_source_action: \"ingest\"",
            f"registered_at: {_frontmatter_string(datetime.now(UTC).replace(microsecond=0).isoformat().replace('+00:00', 'Z'))}",
            "---",
            "",
            f"# {title}",
            "",
            f"Paper id: `{paper_id}`",
            "",
            "## Abstract",
            "",
            abstract or "N/A",
            "",
            "## Extracted Sections",
            "",
            *(section_lines or ["N/A", ""]),
            "## Evidence",
            "",
            "Evidence:",
            *[f"- `{ref}`" for ref in evidence_refs],
            "",
        ]
    )
    _write_text_if_changed_bridge(page_path, page_body)

    edges_path = wiki_root / "graph" / "edges.jsonl"
    edges_path.parent.mkdir(parents=True, exist_ok=True)
    edge = {
        "edge_type": "source_candidate_ingested",
        "source_type": "ingest_paper",
        "source_id": str(envelope.get("run_id") or envelope.get("task_id") or "ingest"),
        "relation": "registered",
        "target_type": "paper",
        "target_id": paper_id,
        "target_path": _rel(page_path),
        "title": title,
        "source_ref": str(paper.get("source_ref") or ""),
        "evidence_refs": evidence_refs,
        "timestamp": datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
    }
    already_registered = False
    if edges_path.exists():
        for raw_line in edges_path.read_text(encoding="utf-8").splitlines():
            try:
                existing_edge = json.loads(raw_line)
            except json.JSONDecodeError:
                continue
            if (
                isinstance(existing_edge, dict)
                and str(existing_edge.get("edge_type") or "") == "source_candidate_ingested"
                and str(existing_edge.get("target_id") or "") == paper_id
            ):
                already_registered = True
                break
    if not already_registered:
        line = json.dumps(edge, sort_keys=True)
        edges_path.open("a", encoding="utf-8").write(line + "\n")

    evidence_ids = _unique_strings([paper_id, str(paper.get("source_ref") or "")])
    log_path = _write_generic_wiki_log(
        wiki_root,
        "Ingest Paper",
        page_path,
        evidence_ids,
        f"Registered ingested paper `{paper_id}` ({title}) into the local AutoSci wiki.",
    )
    rebuilt_paths = _rebuild_generic_wiki_views(
        wiki_root,
        str(envelope.get("run_id") or envelope.get("sprint_id") or "autosci-ingest"),
        page_path,
        evidence_ids,
    )
    artifacts = paper_evidence.setdefault("artifacts", [])
    wiki_artifacts = [
        {"type": "wiki_paper", "path": _rel(page_path)},
        {"type": "wiki_graph_edges", "path": _rel(edges_path)},
        {"type": "wiki_log", "path": _rel(log_path)},
        *[{"type": "wiki_rebuild", "path": _rel(path)} for path in rebuilt_paths],
    ]
    known = {
        (str(item.get("type") or ""), str(item.get("path") or ""))
        for item in artifacts
        if isinstance(item, dict)
    }
    for artifact in wiki_artifacts:
        key = (artifact["type"], artifact["path"])
        if key not in known:
            artifacts.append(artifact)
            known.add(key)
    return wiki_artifacts


def _artifact_path_exists(raw_path: Any) -> bool:
    if not raw_path:
        return False
    raw_text = str(raw_path)
    if raw_text.startswith(("http://", "https://")):
        return False
    return _resolve_harness_path(raw_text).exists()


def _ingest_wiki_registration_state(envelope: dict[str, Any], paper: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    wiki_root = _resolve_harness_path(str(inputs.get("wiki_root") or "artifacts/autosci/workspace/wiki"))
    paper_id = str(paper.get("paper_id") or "paper-unresolved")
    title = str(paper.get("title") or "")
    paper_page = wiki_root / "papers" / f"{_slug(paper_id)}.md"
    matched_page = paper_page if paper_page.exists() else None
    if matched_page is None and (wiki_root / "papers").exists():
        needles = [item.lower() for item in (paper_id, title) if item]
        for candidate in sorted((wiki_root / "papers").glob("*.md")):
            try:
                text = candidate.read_text(encoding="utf-8").lower()
            except OSError:
                continue
            if any(needle and needle in text for needle in needles):
                matched_page = candidate
                break

    log_path = wiki_root / "log.md"
    edge_path = wiki_root / "graph" / "edges.jsonl"
    index_path = wiki_root / "index.md"
    context_path = wiki_root / "graph" / "context_brief.md"

    def _contains(path: Path, values: list[str]) -> bool:
        if not path.exists():
            return False
        try:
            text = path.read_text(encoding="utf-8").lower()
        except OSError:
            return False
        return any(value and value.lower() in text for value in values)

    page_values = [paper_id, title, matched_page.name if matched_page else ""]
    return {
        "wiki_root": _rel(wiki_root),
        "paper_page": _rel(matched_page) if matched_page else _rel(paper_page),
        "paper_registered": bool(matched_page and matched_page.exists()),
        "log_path": _rel(log_path),
        "log_registered": _contains(log_path, page_values + ["ingest"]),
        "graph_edges_path": _rel(edge_path),
        "graph_registered": _contains(edge_path, page_values + ["source_candidate_ingested", "paper_ingested"]),
        "index_path": _rel(index_path),
        "index_rebuilt": _contains(index_path, [matched_page.name if matched_page else paper_page.name, paper_id, title, "papers"]),
        "context_brief_path": _rel(context_path),
        "context_rebuilt": context_path.exists(),
    }


def _ingest_final_source_registration_boundary(
    envelope: dict[str, Any],
    evidence: dict[str, Any],
    sidecar_paths: list[str],
) -> dict[str, Any]:
    outputs = evidence.get("outputs") if isinstance(evidence.get("outputs"), dict) else {}
    paper = outputs.get("paper") if isinstance(outputs.get("paper"), dict) else {}
    preparation = paper.get("preparation") if isinstance(paper.get("preparation"), dict) else {}
    artifacts = evidence.get("artifacts") if isinstance(evidence.get("artifacts"), list) else []
    sections = paper.get("sections") if isinstance(paper.get("sections"), list) else []
    section_text_ready = any(
        isinstance(section, dict) and str(section.get("text") or section.get("title") or "").strip()
        for section in sections
    )
    prep_paths = [
        preparation.get("source_path"),
        preparation.get("canonical_ingest_path"),
        preparation.get("prepared_path"),
        preparation.get("extracted_text_path"),
    ]
    artifact_paths = [
        artifact.get("path")
        for artifact in artifacts
        if isinstance(artifact, dict) and artifact.get("type") in {
            "arxiv_source",
            "extracted_pdf_text",
            "prepared_archive_source",
            "synthetic_latex",
        }
    ]
    source_preparation_verified = (
        str(preparation.get("status") or "").lower() == "completed"
        and bool(preparation.get("canonical_ingest_path") or preparation.get("source_path"))
    )
    parse_quality_ready = (
        evidence.get("status") == "completed"
        and str(paper.get("parse_status") or "") in {"parsed", "partial"}
        and bool(str(paper.get("paper_id") or "").strip())
        and bool(str(paper.get("title") or "").strip())
        and section_text_ready
    )
    raw_artifact_provenance_ready = any(_artifact_path_exists(path) for path in [*prep_paths, *artifact_paths])
    memory_sidecar_ready = len(sidecar_paths) >= 1 and _artifact_path_exists(sidecar_paths[0])
    graph_sidecar_ready = len(sidecar_paths) >= 2 and _artifact_path_exists(sidecar_paths[1])
    downstream_handoff_ready = memory_sidecar_ready and graph_sidecar_ready
    wiki_state = _ingest_wiki_registration_state(envelope, paper)
    wiki_registration_ready = all(
        bool(wiki_state.get(key))
        for key in ("paper_registered", "graph_registered", "index_rebuilt", "context_rebuilt")
    )

    checks = [
        {"name": "source_preparation_verified", "status": "ok" if source_preparation_verified else "missing"},
        {"name": "parse_quality_ready", "status": "ok" if parse_quality_ready else "missing"},
        {"name": "raw_artifact_provenance_ready", "status": "ok" if raw_artifact_provenance_ready else "missing"},
        {"name": "downstream_handoff_ready", "status": "ok" if downstream_handoff_ready else "missing"},
        {"name": "wiki_registration_ready", "status": "ok" if wiki_registration_ready else "missing"},
    ]
    missing = [check["name"] for check in checks if check["status"] != "ok"]
    final_ready = not missing
    return {
        "schema": "autosci_ingest_final_source_registration_boundary.v1",
        "status": "ingest_source_registration_ready" if final_ready else "ingest_source_registration_incomplete",
        "final_registration_ready": final_ready,
        "paper_id": str(paper.get("paper_id") or ""),
        "source_preparation_verified": source_preparation_verified,
        "parse_quality_ready": parse_quality_ready,
        "raw_artifact_provenance_ready": raw_artifact_provenance_ready,
        "downstream_handoff_ready": downstream_handoff_ready,
        "memory_sidecar_ready": memory_sidecar_ready,
        "graph_sidecar_ready": graph_sidecar_ready,
        "wiki_registration_ready": wiki_registration_ready,
        "wiki_registration": wiki_state,
        "sidecar_evidence_paths": list(sidecar_paths),
        "checks": checks,
        "missing": missing,
    }


def _attach_ingest_final_source_registration_boundary(
    envelope: dict[str, Any],
    evidence: dict[str, Any],
    sidecar_paths: list[str],
) -> dict[str, Any]:
    artifacts = evidence.setdefault("artifacts", [])
    for artifact_type, sidecar_path in zip(
        ("research_memory_update_json", "research_graph_update_json"),
        sidecar_paths,
        strict=False,
    ):
        if not any(isinstance(item, dict) and item.get("path") == sidecar_path for item in artifacts):
            artifacts.append({"type": artifact_type, "path": sidecar_path})
    boundary = _ingest_final_source_registration_boundary(envelope, evidence, sidecar_paths)
    output_dir = _output_dir(envelope, "ingest_paper")
    boundary_path = _configured_output_path(
        envelope,
        "ingest_final_source_registration_boundary_path",
        output_dir / "ingest_final_source_registration_boundary.json",
    )
    boundary_artifact = _write_json_sidecar(boundary_path, boundary)
    artifacts.append({"type": "ingest_final_source_registration_boundary_json", "path": boundary_artifact})
    evidence_payload_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        output_dir / "ingest_paper.evidence.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    source_runtime_proof_artifact = _write_ingest_source_runtime_proof_manifest(
        envelope,
        evidence_path=evidence_payload_path,
        evidence=evidence,
        boundary=boundary,
        boundary_artifact=boundary_artifact,
        sidecar_paths=sidecar_paths,
    )
    if source_runtime_proof_artifact is not None:
        artifacts.append(source_runtime_proof_artifact)
    wiki_runtime_proof_artifact = _write_ingest_wiki_registration_runtime_proof_manifest(
        envelope,
        evidence_path=evidence_payload_path,
        boundary=boundary,
        boundary_artifact=boundary_artifact,
        sidecar_paths=sidecar_paths,
    )
    if wiki_runtime_proof_artifact is not None:
        artifacts.append(wiki_runtime_proof_artifact)
    outputs = evidence.setdefault("outputs", {})
    outputs["final_source_registration_boundary"] = boundary
    paper = outputs.get("paper")
    if isinstance(paper, dict):
        paper["final_source_registration_boundary"] = boundary
    if not boundary["final_registration_ready"]:
        limitation = "Ingest final source registration incomplete: " + ", ".join(boundary["missing"])
        limitations = evidence.setdefault("limitations", [])
        if limitation not in limitations:
            limitations.append(limitation)
    return evidence


def _load_optional_evidence(raw_path: Any) -> dict[str, Any] | None:
    if not raw_path:
        return None
    path = _resolve_harness_path(str(raw_path))
    if not path.exists():
        return None
    try:
        payload = _load_json(path)
    except (OSError, json.JSONDecodeError):
        return None
    return payload if isinstance(payload, dict) else None


def _load_optional_evidence_many(raw_value: Any) -> list[dict[str, Any]]:
    if isinstance(raw_value, list):
        return [payload for item in raw_value if (payload := _load_optional_evidence(item))]
    payload = _load_optional_evidence(raw_value)
    return [payload] if payload else []


def _claim_text_from_evidence(envelope: dict[str, Any], claim_id: str) -> str:
    inputs = dict(envelope.get("inputs") or {})
    for payload in _load_optional_evidence_many(inputs.get("claims_evidence")):
        outputs = payload.get("outputs") if isinstance(payload, dict) else {}
        claims = outputs.get("claims") if isinstance(outputs, dict) else []
        for claim in (claims if isinstance(claims, list) else []):
            if isinstance(claim, dict) and str(claim.get("claim_id") or "") == claim_id:
                return str(claim.get("text") or "")
    return ""


def _claims_from_evidence(envelope: dict[str, Any]) -> list[dict[str, Any]]:
    inputs = dict(envelope.get("inputs") or {})
    out: list[dict[str, Any]] = []
    for payload in _load_optional_evidence_many(inputs.get("claims_evidence")):
        outputs = payload.get("outputs") if isinstance(payload, dict) else {}
        claims = outputs.get("claims") if isinstance(outputs, dict) else []
        if isinstance(claims, list):
            out.extend(claim for claim in claims if isinstance(claim, dict))
    return out


def _methods_from_evidence(envelope: dict[str, Any]) -> list[dict[str, Any]]:
    inputs = dict(envelope.get("inputs") or {})
    payload = _load_optional_evidence(inputs.get("method_evidence"))
    outputs = payload.get("outputs") if isinstance(payload, dict) else {}
    methods = outputs.get("methods") if isinstance(outputs, dict) else []
    return [method for method in methods if isinstance(method, dict)] if isinstance(methods, list) else []


def _ideas_from_evidence(envelope: dict[str, Any]) -> list[dict[str, Any]]:
    inputs = dict(envelope.get("inputs") or {})
    payload = _load_optional_evidence(inputs.get("ideas_evidence"))
    outputs = payload.get("outputs") if isinstance(payload, dict) else {}
    ideas = outputs.get("ideas") if isinstance(outputs, dict) else []
    return [idea for idea in ideas if isinstance(idea, dict)] if isinstance(ideas, list) else []


def _target_idea_from_inputs(envelope: dict[str, Any]) -> dict[str, Any] | None:
    inputs = dict(envelope.get("inputs") or {})
    target = str(inputs.get("target") or inputs.get("topic") or inputs.get("query") or "").strip()
    if not target:
        return None
    safe_id = re.sub(r"[^a-z0-9]+", "-", target.lower()).strip("-")[:48] or "target"
    return {
        "idea_id": f"idea-target-{safe_id}",
        "title": target[:120],
        "hypothesis": f"The proposed target `{target}` may address an evidence-backed research gap.",
        "approach": "Assess novelty against local wiki/discovery evidence before designing an experiment.",
        "origin_evidence_ids": ["target:user-supplied"],
        "novelty_hypothesis": "User-supplied target requires multi-source novelty and review validation.",
        "source_mode": "target",
        "generation_path": "novelty-target",
        "duplicate_status": "unknown",
        "status": "candidate",
    }


def _source_memory_evidence_ids(envelope: dict[str, Any]) -> list[str]:
    inputs = dict(envelope.get("inputs") or {})
    evidence_ids: list[str] = []
    for key in ("paper_evidence", "claims_evidence", "method_evidence", "memory_evidence"):
        payload = _load_optional_evidence(inputs.get(key))
        if not payload:
            continue
        schema = str(payload.get("schema") or "")
        task_id = str(payload.get("task_id") or "")
        if task_id:
            evidence_ids.append(task_id)
        outputs = payload.get("outputs") if isinstance(payload.get("outputs"), dict) else {}
        for collection, id_field in (
            ("claims", "claim_id"),
            ("methods", "method_id"),
            ("changes", "entity_id"),
            ("ideas", "idea_id"),
        ):
            values = outputs.get(collection) if isinstance(outputs, dict) else None
            if isinstance(values, list):
                for item in values:
                    if isinstance(item, dict) and item.get(id_field):
                        evidence_ids.append(str(item[id_field]))
        if schema and not evidence_ids:
            evidence_ids.append(schema)
    seen: set[str] = set()
    unique: list[str] = []
    for item in evidence_ids:
        if item not in seen:
            seen.add(item)
            unique.append(item)
    return unique


def _tokens(value: str) -> set[str]:
    stop_words = {
        "about",
        "after",
        "agent",
        "before",
        "fixture",
        "from",
        "into",
        "markdown",
        "paper",
        "phase",
        "sample",
        "that",
        "the",
        "this",
        "with",
        "without",
    }
    return {
        token
        for token in re.findall(r"[a-z0-9_]+", value.lower())
        if len(token) >= 4 and token not in stop_words
    }


def _code_relevance(claim_text: str, code_text: str) -> tuple[str, str]:
    if not claim_text.strip():
        return "unknown", "No claim text was available to compare with the code file."
    claim_tokens = _tokens(claim_text)
    code_tokens = _tokens(code_text)
    overlap = sorted(claim_tokens & code_tokens)
    if len(overlap) >= 2:
        return "related", f"Claim and code share terms: {', '.join(overlap[:5])}."
    return "unknown", "The file exists, but the script could not prove that it supports the claim."


def _action_extract_claims(envelope: dict[str, Any]) -> dict[str, Any]:
    return convert_research_claims(_paper_claims_raw(envelope), envelope)


def _action_extract_methods(envelope: dict[str, Any]) -> dict[str, Any]:
    return convert_research_method(_paper_methods_raw(envelope), envelope)


def _action_map_code_evidence(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    raw_repo = inputs.get("repo_path") or "tests/plugins/autosci/fixtures/sample_repo"
    repo_path = _resolve_harness_path(str(raw_repo))
    claim_id = str(inputs.get("claim_id") or "claim-001")
    claim_text = _claim_text_from_evidence(envelope, claim_id)
    if repo_path.exists():
        files = sorted(path for path in repo_path.rglob("*.py") if path.is_file())
        if files:
            primary = files[0]
            code_text = primary.read_text(encoding="utf-8", errors="replace")
            relevance_label, relevance_reason = _code_relevance(claim_text, code_text)
            mapping_status = "mapped" if relevance_label != "unknown" else "unknown"
            mapping: dict[str, Any] = {
                "mapping_id": "map-001",
                "claim_id": claim_id,
                "repo_or_path": _rel(repo_path),
                "files": [_rel(primary)],
                "symbols": ["run_fixture_bridge"],
                "execution_entrypoint": f"python3 {_rel(primary)}",
                "mapping_status": mapping_status,
                "relevance_label": relevance_label,
                "relevance_reason": relevance_reason,
                "evidence_ids": [claim_id],
            }
            if mapping_status == "unknown":
                mapping["unknown_reason"] = relevance_reason
            else:
                mapping["evidence_ids"].append(_rel(primary))
            return convert_code_evidence_map({
                "mappings": [mapping],
                "limitations": ["Code mapping records candidate file relevance; it is not evidence of claim verification."],
            }, envelope)
    return convert_code_evidence_map({
        "mappings": [
            {
                "mapping_id": "map-001",
                "claim_id": claim_id,
                "repo_or_path": str(raw_repo),
                "files": ["N/A"],
                "execution_entrypoint": "fixture-mode",
                "mapping_status": "unknown",
                "relevance_label": "unknown",
                "relevance_reason": f"Repository path not available: {raw_repo}",
                "evidence_ids": [claim_id],
                "unknown_reason": f"Repository path not available: {raw_repo}",
            }
        ],
        "limitations": ["Code evidence mapping is unknown because the repository path was unavailable."],
    }, envelope)


def _action_generate_ideas(envelope: dict[str, Any]) -> dict[str, Any]:
    mode = str(envelope.get("mode") or "")
    inputs = dict(envelope.get("inputs") or {})
    contract = _approval_contract(
        envelope,
        "generate_ideas",
        ["source_discovery", "model_brainstorm", "novelty_review", "wiki_writeback", "pilot_handoff"],
    )
    contract, policy_decision, policy_artifacts = _policy_prepare_auto_contract(
        envelope,
        "generate_ideas",
        ["read_local", "write_artifact", "network_fetch", "local_command", "wiki_mutation"],
        contract,
        allowlist_payload={
            "native_pipeline": "ideate",
            "limitations": [
                "Policy approval only permits the bridge to attempt native side effects; novelty/review and pilot promotion gates still need typed evidence.",
            ],
        },
    )
    contract_artifact = _write_approval_contract_sidecar(envelope, "generate_ideas", contract)
    policy_artifacts = [contract_artifact, *policy_artifacts]
    inputs = dict(envelope.get("inputs") or {})
    wiki_state, wiki_state_artifact = _wiki_state_resolver_artifact(envelope, "generate_ideas")
    wiki_artifacts = [wiki_state_artifact] if wiki_state_artifact else []

    def _ideate_policy_access_applies() -> bool:
        if not _side_effect_access_required(policy_decision):
            return False
        if _policy_gate_requested(envelope):
            return True
        if _model_output_requested(envelope):
            return True
        if bool(_ideate_write_approval_state(inputs).get("requested")):
            return True
        return mode != "fixture" and not inputs.get("smoke_mode")

    def _finalize_ideate(raw: dict[str, Any], *, status: str | None = None) -> dict[str, Any]:
        evidence = convert_idea_candidate(raw, envelope, status=status)
        evidence = _attach_policy_decision(evidence, policy_decision)
        if _ideate_policy_access_applies():
            request_payload, request_artifact = _side_effect_access_request(
                envelope,
                "generate_ideas",
                "ideate",
                policy_decision,
                requested_side_effects=["read_local", "write_artifact", "network_fetch", "local_command", "wiki_mutation"],
                required_inputs=[
                    "model brainstorm evidence or approved model command",
                    "novelty/review evidence for promotion",
                    "write approval/runtime proof for wiki idea projection",
                    "pilot handoff evidence or explicit --skip-pilot",
                ],
            )
            evidence = _attach_side_effect_access_request(
                evidence,
                request_payload,
                request_artifact,
                mark_inconclusive=_policy_gate_requested(envelope),
            )
        return evidence

    if mode != "fixture" and not inputs.get("smoke_mode"):
        sourced = build_idea_candidates(envelope, workspace_root=HARNESS_DIR, repository_root=REPO_HARNESS_DIR)
        source_summary = sourced.get("source_summary") if isinstance(sourced.get("source_summary"), dict) else {}
        if _model_output_requested(envelope):
            topic = str(inputs.get("topic") or inputs.get("query") or inputs.get("target") or "research workflow")
            model, model_artifacts = _model_output(
                envelope,
                action="generate_ideas",
                prompt=(
                    "Brainstorm source-grounded AutoSci research ideas. Return JSON with outputs.ideas; each idea "
                    "must include title, hypothesis, approach, novelty_hypothesis, origin_evidence_ids, and "
                    "generation_path using exactly one native path: A:landscape-driven, B:incremental, "
                    "C:combination, D:innovation, or E:cross-domain-transfer."
                ),
                context={
                    "topic": topic,
                    "source_summary": source_summary,
                    "wiki_state_resolution": (wiki_state or {}).get("resolution") if isinstance(wiki_state, dict) else {},
                    "local_candidate_count": len(sourced.get("ideas") or []),
                },
            )
            model_ideas, skipped_model_ideas = _idea_candidates_from_model_output(
                model,
                source_mode=str(source_summary.get("source_mode") or "external"),
            )
            if model.get("status") == "completed" and model_ideas:
                evidence_payload_path = _configured_output_path(
                    envelope,
                    "evidence_payload_path",
                    _output_dir(envelope, "generate_ideas") / "generate_ideas.evidence.json",
                    legacy_key="evidence_path",
                    legacy_suffix=".json",
                )
                model_runtime_proof_artifact = _write_model_runtime_proof_manifest(
                    envelope,
                    action="generate_ideas",
                    native_skill="ideate",
                    evidence_path=evidence_payload_path,
                    model_output=model,
                )
                if model_runtime_proof_artifact is not None:
                    model_artifacts = [*model_artifacts, model_runtime_proof_artifact]
                boundary_ideas, boundary_artifacts, boundary_limitations = _attach_ideate_final_promotion_boundary(
                    envelope,
                    ideas=model_ideas,
                    artifacts=[*policy_artifacts, *wiki_artifacts, *model_artifacts],
                    limitations=[
                        "Ideas came from explicit model evidence or a model-command bridge; novelty/review validation remains required.",
                        *(
                            [f"Skipped incomplete model ideas: {'; '.join(skipped_model_ideas)}"]
                            if skipped_model_ideas
                            else []
                        ),
                        *_wiki_state_limitations(wiki_state),
                    ],
                    source_summary=source_summary,
                    wiki_state=wiki_state,
                    model_output=model,
                )
                return _finalize_ideate(
                    {
                        "ideas": boundary_ideas,
                        "artifacts": boundary_artifacts,
                        "limitations": boundary_limitations,
                    },
                    status="completed",
                )
            if model.get("status") in {"failed", "invalid", "inconclusive"}:
                boundary_ideas, boundary_artifacts, boundary_limitations = _attach_ideate_final_promotion_boundary(
                    envelope,
                    ideas=sourced["ideas"],
                    artifacts=[*policy_artifacts, *wiki_artifacts, *model_artifacts],
                    limitations=[
                        f"Explicit model brainstorm did not complete: {model.get('reason') or model.get('status')}.",
                        "Returned source-grounded local candidates as inconclusive fallback evidence, not as model brainstorm parity.",
                        *list(sourced["limitations"]),
                        *_wiki_state_limitations(wiki_state),
                    ],
                    source_summary=source_summary,
                    wiki_state=wiki_state,
                    model_output=model,
                )
                return _finalize_ideate(
                    {
                        "ideas": boundary_ideas,
                        "artifacts": boundary_artifacts,
                        "limitations": boundary_limitations,
                    },
                    status="inconclusive",
                )
        boundary_ideas, boundary_artifacts, boundary_limitations = _attach_ideate_final_promotion_boundary(
            envelope,
            ideas=sourced["ideas"],
            artifacts=[*policy_artifacts, *wiki_artifacts],
            limitations=[*list(sourced["limitations"]), *_wiki_state_limitations(wiki_state)],
            source_summary=source_summary,
            wiki_state=wiki_state,
        )
        return _finalize_ideate(
            {
                "ideas": boundary_ideas,
                "artifacts": boundary_artifacts,
                "limitations": boundary_limitations,
            },
            status=str(sourced.get("status") or "completed"),
        )
    claims = _claims_from_evidence(envelope)
    methods = _methods_from_evidence(envelope)
    source_ids = _source_memory_evidence_ids(envelope)
    primary_claim = next(
        (claim for claim in claims if str(claim.get("testability") or "") in {"testable", "partially_testable"}),
        claims[0] if claims else {},
    )
    primary_method = methods[0] if methods else {}
    claim_id = str(primary_claim.get("claim_id") or "claim-001")
    method_id = str(primary_method.get("method_id") or "method-001")
    claim_text = str(primary_claim.get("text") or "Fixture claim evidence needs a follow-up experiment.")
    method_name = str(primary_method.get("name") or "Fixture method")
    origin_ids = [item for item in [claim_id, method_id, *source_ids] if item]
    ideas = [
        {
            "idea_id": "idea-001",
            "title": "Evidence-linked verification coverage experiment",
            "hypothesis": (
                "Pairing source-grounded claims with method and code evidence will expose verification gaps "
                "before claim verdict generation."
            ),
            "approach": (
                f"Use claim `{claim_id}` and method `{method_id}` to compare source-only evidence against "
                "source-plus-code evidence coverage."
            ),
            "origin_evidence_ids": origin_ids or [claim_id],
            "novelty_hypothesis": "Combines claim, method, and code evidence at the same Solar Evidence ABI grain.",
            "grounding_summary": f"Seeded from claim: {claim_text}",
            "source_mode": "fixture",
            "generation_path": "fixture-smoke",
            "duplicate_status": "new",
            "status": "candidate",
        },
        {
            "idea_id": "idea-duplicate-001",
            "title": "Repeat existing fixture bridge smoke",
            "hypothesis": "Repeating the bridge smoke test alone will improve scientific verification.",
            "approach": f"Run the existing {method_name} without adding new evidence dimensions.",
            "origin_evidence_ids": origin_ids or [method_id],
            "novelty_hypothesis": "Low novelty because it duplicates the fixture smoke path.",
            "grounding_summary": "Included to prove duplicate ideas are marked rather than silently promoted.",
            "source_mode": "fixture",
            "generation_path": "fixture-smoke",
            "duplicate_status": "duplicate",
            "duplicate_of": "task-autosci-smoke",
            "status": "filtered",
        },
    ]
    boundary_ideas, boundary_artifacts, boundary_limitations = _attach_ideate_final_promotion_boundary(
        envelope,
        ideas=ideas,
        artifacts=[*policy_artifacts, *wiki_artifacts],
        limitations=["Fixture ideas are generated from supplied local evidence only; external novelty is not proven."],
        source_summary={
            "wiki_source_count": 0,
            "discovery_source_count": 0,
            "failed_idea_count": 0,
            "source_mode": "fixture",
        },
        wiki_state=wiki_state,
    )
    return _finalize_ideate({
        "ideas": boundary_ideas,
        "artifacts": boundary_artifacts,
        "limitations": boundary_limitations,
    })


def _novelty_payload_archive_artifacts(evaluations: list[dict[str, Any]]) -> list[dict[str, str]]:
    paths: list[str] = []
    for evaluation in evaluations:
        if not isinstance(evaluation, dict):
            continue
        external = evaluation.get("external_novelty")
        if not isinstance(external, dict):
            continue
        for status in external.get("provider_statuses", []):
            if not isinstance(status, dict):
                continue
            raw_paths = status.get("raw_payload_archive_paths")
            if isinstance(raw_paths, list):
                paths.extend(str(item) for item in raw_paths if str(item).strip())
            raw_path = str(status.get("raw_payload_archive_path") or "").strip()
            if raw_path:
                paths.append(raw_path)
    artifacts: list[dict[str, str]] = []
    seen: set[str] = set()
    for raw_path in paths:
        path = Path(raw_path)
        path_text = _rel(path) if path.is_absolute() else raw_path
        if path_text in seen:
            continue
        seen.add(path_text)
        artifacts.append({"type": "external_novelty_payload_json", "path": path_text})
    return artifacts


def _novelty_final_acceptance_boundary(evaluation: dict[str, Any]) -> dict[str, Any]:
    external_status = _external_novelty_status(evaluation)
    provenance_status = _external_novelty_provenance_status(evaluation)
    review_status = _review_llm_status(evaluation)
    score = _novelty_score_from_evaluation(evaluation)
    external = evaluation.get("external_novelty") if isinstance(evaluation.get("external_novelty"), dict) else {}
    external_source_count = int(evaluation.get("external_source_count") or external.get("source_count") or 0)
    provenance = external.get("provenance") if isinstance(external.get("provenance"), dict) else {}
    completed_provider_count = int(provenance.get("completed_provider_count") or 0)
    blocking_reasons: list[str] = []
    if external_status != "completed":
        blocking_reasons.append(f"external_novelty status is `{external_status}`, not `completed`")
    if provenance_status != "passed":
        blocking_reasons.append(f"external_novelty provenance status is `{provenance_status}`, not `passed`")
    if review_status != "completed":
        blocking_reasons.append(f"review_llm status is `{review_status}`, not `completed`")
    if external_source_count < 2:
        blocking_reasons.append("fewer than two external prior-work sources were verified")
    if completed_provider_count < 1:
        blocking_reasons.append("no completed external novelty provider was verified")
    if str(evaluation.get("failed_overlap") or "").strip():
        blocking_reasons.append("the idea overlaps failed-idea memory")
    if score is None:
        blocking_reasons.append("numeric novelty score is missing")
    final_acceptance_ready = not blocking_reasons
    review_llm = evaluation.get("review_llm") if isinstance(evaluation.get("review_llm"), dict) else {}
    return {
        "schema": "autosci_novelty_final_acceptance_boundary.v1",
        "status": "final_acceptance_ready" if final_acceptance_ready else "novelty_acceptance_incomplete",
        "final_acceptance_ready": final_acceptance_ready,
        "idea_id": str(evaluation.get("idea_id") or "N/A"),
        "external_novelty_status": external_status,
        "external_novelty_provenance_status": provenance_status,
        "external_source_count": external_source_count,
        "completed_provider_count": completed_provider_count,
        "failed_overlap": str(evaluation.get("failed_overlap") or ""),
        "review_llm_status": review_status,
        "review_mode": str(evaluation.get("review_mode") or "N/A"),
        "review_available": bool(evaluation.get("review_available")),
        "review_invocation_mode": str(review_llm.get("invocation_mode") or "N/A"),
        "recommendation": str(evaluation.get("recommendation") or "N/A"),
        "novelty": evaluation.get("novelty", "N/A"),
        "novelty_score": score,
        "evidence_ids": _unique_strings([str(item) for item in evaluation.get("evidence_ids") or []]),
        "provider_statuses": list(external.get("provider_statuses") or []) if isinstance(external, dict) else [],
        "blocking_reasons": blocking_reasons,
        "limitations": [] if final_acceptance_ready else [
            "Novelty final acceptance requires completed external novelty evidence, passed provider provenance, and completed Review LLM evidence."
        ],
    }


def _action_evaluate_ideas(envelope: dict[str, Any]) -> dict[str, Any]:
    mode = str(envelope.get("mode") or "")
    inputs = dict(envelope.get("inputs") or {})
    wiki_state, wiki_state_artifact = _wiki_state_resolver_artifact(envelope, "evaluate_ideas")
    wiki_artifacts = [wiki_state_artifact] if wiki_state_artifact else []
    if mode != "fixture" and not inputs.get("smoke_mode"):
        inputs.setdefault(
            "novelty_payload_archive_dir",
            str(_output_dir(envelope, "evaluate_ideas") / "external_novelty_payloads"),
        )
    ideas = _ideas_from_evidence(envelope)
    if not ideas:
        target_idea = _target_idea_from_wiki_state(wiki_state) or _target_idea_from_inputs(envelope)
        if target_idea and mode != "fixture" and not inputs.get("smoke_mode"):
            ideas = [target_idea]
        else:
            ideas = convert_idea_candidate({}, envelope)["outputs"]["ideas"]
    evaluations: list[dict[str, Any]] = []
    for idea in ideas:
        idea_id = str(idea.get("idea_id") or f"idea-{len(evaluations) + 1:03d}")
        duplicate_status = str(idea.get("duplicate_status") or "unknown")
        source_mode = str(idea.get("source_mode") or "unknown")
        origin_ids = list(idea.get("origin_evidence_ids") or [idea_id])
        if duplicate_status in {"duplicate", "insufficient_source"} or source_mode == "missing":
            evaluations.append({
                "idea_id": idea_id,
                "novelty": 0.15 if duplicate_status == "duplicate" else 0.0,
                "feasibility": 0.8 if duplicate_status == "duplicate" else 0.2,
                "recommendation": "reject" if duplicate_status == "duplicate" else "inconclusive",
                "risks": [
                    "Marked duplicate of an existing fixture smoke path."
                    if duplicate_status == "duplicate"
                    else "No wiki, discovery, or paper source evidence was available."
                ],
                "evidence_ids": [idea_id, *origin_ids],
                "novelty_rationale": (
                    "The idea duplicates known fixture validation rather than adding a new research question."
                    if duplicate_status == "duplicate"
                    else "Novelty cannot be assessed without source evidence."
                ),
                "feasibility_rationale": (
                    "It is easy to run but does not add meaningful evidence."
                    if duplicate_status == "duplicate"
                    else "Feasibility cannot be assessed without a concrete sourced idea."
                ),
                "duplicate_status": duplicate_status,
                "source_mode": source_mode,
            })
        else:
            validation = (
                {}
                if source_mode == "fixture" or mode == "fixture" or inputs.get("smoke_mode")
                else evaluate_novelty_and_review(
                    idea,
                    inputs,
                    workspace_root=HARNESS_DIR,
                    repository_root=REPO_HARNESS_DIR,
                )
            )
            novelty = 0.68 if source_mode == "fixture" else float(validation.get("novelty", 0.62))
            feasibility = 0.76 if source_mode == "fixture" else max(0.25, float(validation.get("review_score", 0.55)))
            recommendation = "advance" if source_mode == "fixture" else str(validation.get("recommendation") or "revise")
            risks = (
                ["External novelty is unverified because fixture mode does not search live literature."]
                if source_mode == "fixture"
                else list(validation.get("risks") or ["Requires /novelty and /review validation before promotion."])
            )
            closest_prior_work = list(validation.get("closest_prior_work") or [])
            validation_review_llm = validation.get("review_llm") if isinstance(validation.get("review_llm"), dict) else {}
            validation_evidence_ids = [
                str(item.get("source_id"))
                for item in closest_prior_work
                if isinstance(item, dict) and str(item.get("source_id") or "").strip()
            ]
            validation_evidence_ids.extend(
                str(item)
                for item in validation_review_llm.get("evidence_ids", [])
                if str(item).strip()
            )
            evidence_ids = list(dict.fromkeys(str(item) for item in [idea_id, *origin_ids, *validation_evidence_ids] if str(item).strip()))
            evaluations.append({
                "idea_id": idea_id,
                "novelty": novelty,
                "feasibility": feasibility,
                "recommendation": recommendation,
                "risks": risks,
                "evidence_ids": evidence_ids,
                "novelty_rationale": (
                    "The idea combines claim, method, and code evidence at a shared artifact grain."
                    if source_mode == "fixture"
                    else str(validation.get("novelty_rationale") or "The idea is grounded in source evidence but still requires validation.")
                ),
                "feasibility_rationale": (
                    "The required inputs already exist as Solar Evidence ABI artifacts."
                    if source_mode == "fixture"
                    else str(validation.get("review_rationale") or "A bounded pilot should be designed before full execution.")
                ),
                "duplicate_status": duplicate_status,
                "source_mode": source_mode,
                "closest_prior_work": closest_prior_work,
                "review_score": validation.get("review_score", "N/A") if validation else "N/A",
                "review_mode": validation.get("review_mode", "N/A") if validation else "N/A",
                "review_available": bool(validation.get("review_available", False)) if validation else False,
                "review_llm": validation_review_llm if validation else {"status": "N/A"},
                "novelty_label": validation.get("novelty_label", "fixture") if validation else "fixture",
                "failed_overlap": validation.get("failed_overlap", "") if validation else "",
                "source_count": validation.get("source_count", "N/A") if validation else "N/A",
                "local_source_count": validation.get("local_source_count", "N/A") if validation else "N/A",
                "external_source_count": validation.get("external_source_count", "N/A") if validation else "N/A",
                "external_novelty": validation.get("external_novelty", {"status": "N/A"}) if validation else {"status": "N/A"},
            })
    final_boundaries = []
    for evaluation in evaluations:
        if not isinstance(evaluation, dict):
            continue
        boundary = _novelty_final_acceptance_boundary(evaluation)
        evaluation["final_acceptance_boundary"] = boundary
        final_boundaries.append(boundary)
    boundary_path = _output_dir(envelope, "evaluate_ideas") / "novelty_final_acceptance_boundary.json"
    boundary_artifact = _write_json_sidecar(
        boundary_path,
        {
            "schema": "autosci_novelty_final_acceptance_boundary_set.v1",
            "status": "final_acceptance_ready"
            if final_boundaries and all(bool(item.get("final_acceptance_ready")) for item in final_boundaries)
            else "novelty_acceptance_incomplete",
            "boundaries": final_boundaries,
        },
    )
    limitations = ["Fixture evaluation uses local evidence and does not update idea status directly."]
    if mode != "fixture" and not inputs.get("smoke_mode"):
        limitations = [
            "Novelty/review signals are derived from local wiki/discovery evidence.",
            "Independent Review LLM and live external search are still required before promotion.",
        ]
    if any(not bool(item.get("final_acceptance_ready")) for item in final_boundaries):
        limitations.append("Novelty final acceptance boundary is incomplete for at least one evaluated idea.")
    evidence_payload_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        _output_dir(envelope, "evaluate_ideas") / "evaluate_ideas.evidence.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    runtime_proof_artifacts = [
        artifact
        for artifact in (
            _write_external_novelty_runtime_proof_manifest(
                envelope,
                action="evaluate_ideas",
                native_skill="novelty",
                evidence_path=evidence_payload_path,
                evaluations=evaluations,
            ),
            _write_novelty_review_runtime_proof_manifest(
                envelope,
                action="evaluate_ideas",
                native_skill="novelty",
                evidence_path=evidence_payload_path,
                evaluations=evaluations,
            ),
        )
        if artifact is not None
    ]
    return convert_idea_evaluation({
        "evaluations": evaluations,
        "artifacts": [
            {"type": "novelty_final_acceptance_boundary_json", "path": boundary_artifact},
            *_novelty_payload_archive_artifacts(evaluations),
            *runtime_proof_artifacts,
            *wiki_artifacts,
        ],
        "limitations": [*limitations, *_wiki_state_limitations(wiki_state)],
    }, envelope)


def _review_final_acceptance_boundary(inputs: dict[str, Any], raw: dict[str, Any]) -> dict[str, Any]:
    review = raw.get("review") if isinstance(raw.get("review"), dict) else {}
    review_llm = review.get("review_llm") if isinstance(review.get("review_llm"), dict) else {}
    review_mode = str(review.get("review_mode") or "").strip()
    llm_status = str(review_llm.get("status") or "").strip()
    evidence_ids = _review_evidence_ids(review, review_llm)
    proof = review.get("proof_contract") if isinstance(review.get("proof_contract"), dict) else {}
    proof_blockers = [str(item) for item in proof.get("blockers") or [] if str(item).strip()]
    separation = proof.get("reviewer_separation") if isinstance(proof.get("reviewer_separation"), dict) else {}
    independence = separation.get("independence") if isinstance(separation.get("independence"), dict) else {}
    invalid_reasons: list[str] = []
    if review_mode != "review_llm":
        invalid_reasons.append(f"review_mode is `{review_mode or 'missing'}`, not `review_llm`")
    if review.get("review_available") is not True:
        invalid_reasons.append("review_available is not true")
    if llm_status != "completed":
        invalid_reasons.append(f"review_llm status is `{llm_status or 'missing'}`, not `completed`")
    if not evidence_ids:
        invalid_reasons.append("Review LLM evidence ids are missing")
    if proof.get("verdict") != "supported" or proof_blockers:
        invalid_reasons.append("persisted review proof is missing, stale, or unsupported")
    if independence.get("status") != "independent_provider" or independence.get("execution_bound") is not True:
        invalid_reasons.append("reviewer execution is not bound to an independent provider")
    final_acceptance_ready = not invalid_reasons
    return {
        "schema": "autosci_review_final_acceptance_boundary.v1",
        "status": "final_acceptance_ready" if final_acceptance_ready else "review_llm_incomplete",
        "required": bool(inputs.get("require_review_llm")),
        "final_acceptance_ready": final_acceptance_ready,
        "review_mode": review_mode or "missing",
        "review_available": bool(review.get("review_available")),
        "review_llm_status": llm_status or "missing",
        "invocation_mode": str(review_llm.get("invocation_mode") or "local_surrogate"),
        "provider": str(review_llm.get("provider") or ""),
        "model": str(review_llm.get("model") or ""),
        "source_path": str(review_llm.get("source_path") or review_llm.get("archive_path") or ""),
        "request_sha256": str(review_llm.get("request_sha256") or ""),
        "response_sha256": str(review_llm.get("response_sha256") or ""),
        "score": review.get("score", review_llm.get("score")),
        "recommendation": str(review.get("recommendation") or review_llm.get("recommendation") or "inconclusive"),
        "evidence_ids": evidence_ids,
        "proof_verdict": str(proof.get("verdict") or "missing"),
        "proof_blockers": proof_blockers,
        "reviewer_independence_status": str(independence.get("status") or "missing"),
        "reviewer_independence_execution_bound": bool(independence.get("execution_bound")),
        "blocking_reasons": invalid_reasons,
        "limitations": [] if final_acceptance_ready else [
            "Final review acceptance requires Review LLM evidence from supplied evidence, command bridge, or provider mode."
        ],
    }


def _action_review_artifact(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    raw = review_artifact(
        inputs,
        workspace_root=HARNESS_DIR,
        repository_root=REPO_HARNESS_DIR,
    )
    output_dir = _output_dir(envelope, "review_artifact")
    report_path = output_dir / "artifact_review.md"
    artifacts = []
    artifact = raw.get("artifact") if isinstance(raw.get("artifact"), dict) else {}
    artifact_path = Path(str(artifact.get("path") or ""))
    if artifact_path.is_absolute() and artifact_path.exists():
        artifacts.append({"type": "review_target", "path": _rel(artifact_path)})
    report_markdown = str(raw.get("report_markdown") or "")
    if report_markdown:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(report_markdown, encoding="utf-8")
        artifacts.append({"type": "artifact_review_markdown", "path": _rel(report_path)})
    final_boundary = _review_final_acceptance_boundary(inputs, raw)
    final_boundary_path = output_dir / "review_acceptance.json"
    final_boundary_artifact_path = _write_json_sidecar(final_boundary_path, final_boundary)
    artifacts.append({
        "type": "review_final_acceptance_boundary_json",
        "path": final_boundary_artifact_path,
    })
    evidence_payload_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        output_dir / "review.evidence.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    runtime_proof_artifact = _write_review_runtime_proof_manifest(
        envelope,
        evidence_payload_path,
        final_boundary,
    )
    if runtime_proof_artifact is not None:
        artifacts.append(runtime_proof_artifact)
    source_runtime_proof_artifact = _write_review_target_runtime_proof_manifest(
        envelope,
        evidence_path=evidence_payload_path,
        artifact_path=artifact_path,
        report_artifact=_rel(report_path) if report_markdown else "",
        final_boundary_artifact=final_boundary_artifact_path,
    )
    if source_runtime_proof_artifact is not None:
        artifacts.append(source_runtime_proof_artifact)
    limitations = list(raw.get("limitations") or ["Review LLM MCP evidence is unavailable."])
    limitations.extend(str(item) for item in final_boundary.get("limitations") or [])
    timestamp = datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    return {
        "schema": "artifact_review.v1",
        "task_id": str(envelope.get("task_id") or "task-review-artifact"),
        "sprint_id": str(envelope.get("sprint_id") or "sprint-autosci-review"),
        "node_id": str(envelope.get("node_id") or "node-review-artifact"),
        "status": str(raw.get("status") or "inconclusive"),
        "inputs": inputs,
        "outputs": {
            "review": raw.get("review") if isinstance(raw.get("review"), dict) else {},
            "findings": list(raw.get("findings") or []),
            "artifact": artifact,
            "final_acceptance_boundary": final_boundary,
        },
        "artifacts": artifacts,
        "provenance": {
            "operator_id": "autosci-bridge-review",
            "implementation_package": "plugins/autosci",
            "timestamp": timestamp,
        },
        "limitations": _unique_strings(limitations),
    }


def _phase11_memory_update_path(envelope: dict[str, Any]) -> Path:
    output_dir = _output_dir(envelope, "evaluate_ideas")
    outputs = envelope.get("outputs") if isinstance(envelope.get("outputs"), dict) else {}
    raw = outputs.get("memory_update_path") if isinstance(outputs, dict) else None
    path = Path(str(raw)) if raw else output_dir / "research_memory_update.ideas.json"
    if not path.is_absolute():
        path = HARNESS_DIR / path
    return path


def _write_phase11_idea_memory_sidecar(envelope: dict[str, Any], evaluation_evidence: dict[str, Any]) -> str:
    path = _phase11_memory_update_path(envelope)
    evaluations = list((evaluation_evidence.get("outputs") or {}).get("evaluations") or [])
    changes = []
    for evaluation in evaluations:
        if not isinstance(evaluation, dict):
            continue
        idea_id = str(evaluation.get("idea_id") or "")
        if not idea_id:
            continue
        changes.append({
            "entity_type": "idea",
            "entity_id": idea_id,
            "operation": "propose",
            "path": f"knowledge/research/ideas/{idea_id}.md",
            "evidence_ids": list(evaluation.get("evidence_ids") or [idea_id]),
            "confidence": float(evaluation.get("feasibility") or 0.5),
            "recommendation": evaluation.get("recommendation"),
        })
    memory_evidence = convert_research_memory_update({
        "changes": changes or [{
            "entity_type": "idea",
            "entity_id": "idea-unknown",
            "operation": "no_op",
            "path": "knowledge/research/ideas/N/A",
            "evidence_ids": [str(evaluation_evidence.get("task_id") or "idea-evaluation")],
            "confidence": 0.0,
        }],
        "limitations": ["Fixture proposes idea memory records; it does not mutate research memory."],
    }, envelope)
    return _write_evidence_payload(path, memory_evidence)


def _novelty_writeback_path(envelope: dict[str, Any]) -> Path:
    output_dir = _output_dir(envelope, "evaluate_ideas")
    return output_dir / "novelty_writeback.json"


def _wiki_roots_for_write(envelope: dict[str, Any]) -> list[Path]:
    inputs = dict(envelope.get("inputs") or {})
    raw_root = str(inputs.get("wiki_root") or "").strip()
    roots: list[Path] = []
    if raw_root:
        path = Path(raw_root)
        roots.append(path if path.is_absolute() else HARNESS_DIR / path)
    roots.extend(
        [
            HARNESS_DIR / "artifacts" / "autosci" / "workspace" / "wiki",
            HARNESS_DIR / "wiki",
            REPO_HARNESS_DIR / "harness" / "artifacts" / "autosci" / "workspace" / "wiki",
        ]
    )
    seen: set[Path] = set()
    out: list[Path] = []
    for root in roots:
        try:
            resolved = root.resolve()
        except OSError:
            continue
        if resolved in seen:
            continue
        seen.add(resolved)
        out.append(root)
    return out


def _path_is_under(path: Path, root: Path) -> bool:
    try:
        path.resolve().relative_to(root.resolve())
        return True
    except ValueError:
        return False


def _target_idea_path_for_write(envelope: dict[str, Any]) -> tuple[Path | None, str, list[str]]:
    inputs = dict(envelope.get("inputs") or {})
    target = str(inputs.get("target") or inputs.get("topic") or inputs.get("query") or "").strip()
    if not target:
        return None, "", ["No idea target was supplied for novelty write-back."]
    roots = _wiki_roots_for_write(envelope)
    raw_path = Path(target)
    candidates: list[Path] = []
    if raw_path.suffix.lower() in {".md", ".markdown"}:
        if raw_path.is_absolute():
            candidates.append(raw_path)
        else:
            for root in roots:
                candidates.extend([root / raw_path, root / "ideas" / raw_path.name])
    else:
        slug = _slug(raw_path.stem if raw_path.suffix else target)
        for root in roots:
            candidates.append(root / "ideas" / f"{slug}.md")

    checked: list[str] = []
    for candidate in candidates:
        checked.append(str(candidate))
        if not candidate.exists() or not candidate.is_file():
            continue
        if not any(_path_is_under(candidate, root) for root in roots):
            continue
        return candidate, _slug(candidate.stem), checked
    return None, _slug(raw_path.stem if raw_path.suffix else target), checked


def _set_frontmatter_scalar(text: str, key: str, value: str) -> str | None:
    match = re.match(r"^---\s*\n(.*?)\n---\s*(?:\n|$)", text, flags=re.S)
    if not match:
        return None
    body = match.group(1)
    lines = body.splitlines()
    replacement = f"{key}: {value}"
    for idx, line in enumerate(lines):
        if line.split(":", 1)[0].strip() == key:
            lines[idx] = replacement
            break
    else:
        lines.append(replacement)
    return "---\n" + "\n".join(lines).rstrip() + "\n---\n" + text[match.end():]


def _novelty_score_from_evaluation(evaluation: dict[str, Any]) -> int | None:
    try:
        novelty = float(evaluation.get("novelty"))
    except (TypeError, ValueError):
        return None
    if novelty < 0:
        novelty = 0.0
    if novelty > 1:
        novelty = 1.0
    return max(1, min(5, int(novelty * 4 + 1.5)))


def _external_novelty_status(evaluation: dict[str, Any]) -> str:
    external = evaluation.get("external_novelty")
    if not isinstance(external, dict):
        return "missing"
    return str(external.get("status") or "missing")


def _external_novelty_provenance_status(evaluation: dict[str, Any]) -> str:
    external = evaluation.get("external_novelty")
    if not isinstance(external, dict):
        return "missing"
    provenance = external.get("provenance")
    if not isinstance(provenance, dict):
        return "missing"
    return str(provenance.get("status") or "missing")


def _review_llm_status(evaluation: dict[str, Any]) -> str:
    review_llm = evaluation.get("review_llm")
    if not isinstance(review_llm, dict):
        return "missing"
    return str(review_llm.get("status") or "missing")


def _append_novelty_wiki_log(root: Path, idea_path: Path, score: int, evaluation: dict[str, Any]) -> Path:
    log_path = root / "log.md"
    log_path.parent.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    idea_rel = _rel(idea_path)
    evidence_ids = ", ".join(str(item) for item in evaluation.get("evidence_ids") or []) or "N/A"
    entry = (
        "\n## Novelty Writeback\n\n"
        f"- {timestamp} | novelty | wrote novelty_score={score} | idea={idea_rel} | evidence={evidence_ids}\n"
    )
    with log_path.open("a", encoding="utf-8") as handle:
        handle.write(entry)
    return log_path


def _append_novelty_wiki_edge(root: Path, idea_path: Path, score: int, evaluation: dict[str, Any]) -> Path:
    edges_path = root / "graph" / "edges.jsonl"
    edges_path.parent.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    evidence_ids = _unique_strings([str(item) for item in evaluation.get("evidence_ids") or []])
    edge = {
        "edge_type": "novelty_evaluated",
        "source_type": "idea",
        "source_id": str(evaluation.get("idea_id") or idea_path.stem),
        "source_path": _rel(idea_path),
        "relation": "has_novelty_score",
        "target_type": "novelty_evaluation",
        "target_id": str(evaluation.get("idea_id") or idea_path.stem),
        "novelty_score": score,
        "recommendation": str(evaluation.get("recommendation") or "N/A"),
        "evidence_ids": evidence_ids,
        "timestamp": timestamp,
    }
    line = json.dumps(edge, sort_keys=True)
    existing = set(edges_path.read_text(encoding="utf-8").splitlines()) if edges_path.exists() else set()
    if line not in existing:
        with edges_path.open("a", encoding="utf-8") as handle:
            handle.write(line + "\n")
    return edges_path


def _rebuild_wiki_mutation_views(root: Path, run_id: str, idea_path: Path, evaluation: dict[str, Any]) -> list[Path]:
    updated: list[Path] = []
    index_path = root / "index.md"
    lines = [
        "# Solar AutoSci Wiki\n\n",
        "Human-facing research memory projected from Solar-managed evidence and approved wiki mutations.\n\n",
        f"Last mutation run: `{run_id}`\n\n",
    ]
    for subdir in ["papers", "concepts", "methods", "people", "topics", "ideas", "experiments", "outputs"]:
        lines.append(f"## {subdir.title()}\n\n")
        pages = sorted((root / subdir).glob("*.md"))
        if not pages:
            lines.append("- N/A\n\n")
            continue
        for page in pages:
            lines.append(f"- [{page.stem}]({subdir}/{page.name})\n")
        lines.append("\n")
    index_body = "".join(lines)
    if _write_text_if_changed_bridge(index_path, index_body):
        updated.append(index_path)

    context_path = root / "graph" / "context_brief.md"
    evidence_ids = ", ".join(str(item) for item in evaluation.get("evidence_ids") or []) or "N/A"
    context_body = "\n".join(
        [
            "# Solar AutoSci Context Brief",
            "",
            f"Last mutation run: `{run_id}`",
            f"Updated at: `{datetime.now(UTC).replace(microsecond=0).isoformat().replace('+00:00', 'Z')}`",
            f"Mutation target: `{_rel(idea_path)}`",
            f"Evidence ids: {evidence_ids}",
            "",
            "Use `wiki/graph/edges.jsonl` for structured mutation edges.",
            "Use `artifacts/autosci/runs/` for Solar-managed execution evidence.",
            "",
        ]
    )
    if _write_text_if_changed_bridge(context_path, context_body):
        updated.append(context_path)

    open_questions_path = root / "graph" / "open_questions.md"
    gap_lines = _wiki_open_question_lines(root)
    open_questions_body = "# Gap Map\n\n_Auto-generated open questions. Do not edit._\n\n"
    open_questions_body += "\n".join(gap_lines) + "\n" if gap_lines else "_No gaps detected yet._\n"
    if _write_text_if_changed_bridge(open_questions_path, open_questions_body):
        updated.append(open_questions_path)
    return updated


def _wiki_open_question_lines(root: Path) -> list[str]:
    gaps: list[str] = []
    _collect_wiki_section_items(root / "papers", "Open questions", gaps, "paper")
    _collect_wiki_section_items(root / "topics", "Open problems", gaps, "topic")
    _collect_wiki_section_items(root / "concepts", "Open problems", gaps, "concept")
    return gaps


def _collect_wiki_section_items(directory: Path, section_name: str, out: list[str], source_type: str) -> None:
    if not directory.exists():
        return
    for path in sorted(directory.glob("*.md")):
        content = path.read_text(encoding="utf-8", errors="replace")
        in_section = False
        for line in content.splitlines():
            if re.match(rf"^##\s+{re.escape(section_name)}\s*$", line, re.IGNORECASE):
                in_section = True
                continue
            if in_section and line.startswith("## "):
                break
            if in_section and line.lstrip().startswith(("- ", "* ")):
                bullet = line.lstrip()[2:].strip()
                if bullet:
                    out.append(f"- [{source_type}:{path.stem}] {bullet}")


def _write_text_if_changed_bridge(path: Path, content: str) -> bool:
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists() and path.read_text(encoding="utf-8") == content:
        return False
    path.write_text(content, encoding="utf-8")
    return True


WIKI_MUTATION_ARTIFACT_TYPES = {
    "wiki_claim_verdict_target",
    "wiki_graph_edges",
    "wiki_idea",
    "wiki_log",
    "wiki_page",
    "wiki_rebuild",
}


def _write_wiki_mutation_runtime_proof_manifest(
    envelope: dict[str, Any],
    *,
    action: str,
    native_skill: str,
    writeback_path: Path,
    writeback: dict[str, Any],
) -> dict[str, str] | None:
    outputs = writeback.get("outputs") if isinstance(writeback.get("outputs"), dict) else {}
    write = outputs.get("write") if isinstance(outputs.get("write"), dict) else {}
    if str(writeback.get("status") or "") != "completed":
        return None
    if write.get("applied") is not True:
        return None
    refs: list[str | Path] = [writeback_path]
    for artifact in writeback.get("artifacts") or []:
        if not isinstance(artifact, dict):
            continue
        if str(artifact.get("type") or "") not in WIKI_MUTATION_ARTIFACT_TYPES:
            continue
        path = str(artifact.get("path") or "").strip()
        if path:
            refs.append(path)
    for key in ("target_path", "idea_path", "log_path", "edge_path"):
        path = str(write.get(key) or "").strip()
        if path:
            refs.append(path)
    for key in ("rebuilt_paths", "edge_paths"):
        for path in write.get(key) or []:
            if str(path or "").strip():
                refs.append(str(path))
    timestamp = str(
        writeback.get("generated_at")
        or writeback.get("captured_at")
        or (writeback.get("provenance") or {}).get("timestamp")
        or datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    )
    manifest = {
        "schema": "autosci_runtime_proof_manifest.v1",
        "generated_at": timestamp,
        "proofs": [
            {
                "native_skill": native_skill,
                "proof_id": f"runtime:{_slug(native_skill)}:wiki-writeback-sidecar:{timestamp.replace(':', '').replace('-', '')}",
                "categories": ["wiki_mutation_evidence"],
                "collection_mode": "approved_side_effect",
                "production_ready": True,
                "provenance": {
                    "source": "wiki_writeback_sidecar",
                    "captured_at": timestamp,
                    "artifact_kind": str(writeback.get("schema") or "wiki_writeback"),
                    "command": f"{action}:wiki_writeback",
                },
                "evidence_refs": _runtime_evidence_refs(*refs),
                "description": "Completed wiki mutation writeback sidecar for AutoSci parity.",
            }
        ],
    }
    artifact_path = _write_json_sidecar(
        _output_dir(envelope, action) / f"{action}_wiki_mutation_runtime_proof.json",
        manifest,
    )
    return {"type": "wiki_mutation_runtime_proof_manifest_json", "path": artifact_path}


def _write_novelty_writeback_sidecar(envelope: dict[str, Any], evaluation_evidence: dict[str, Any]) -> str | None:
    inputs = dict(envelope.get("inputs") or {})
    native_options = inputs.get("native_options") if isinstance(inputs.get("native_options"), dict) else {}
    if not native_options.get("write"):
        return None

    path = _novelty_writeback_path(envelope)
    evaluations = list((evaluation_evidence.get("outputs") or {}).get("evaluations") or [])
    evaluation = next((item for item in evaluations if isinstance(item, dict)), {})
    idea_path, idea_slug, checked_paths = _target_idea_path_for_write(envelope)
    status = "inconclusive"
    write: dict[str, Any] = {
        "requested": True,
        "applied": False,
        "approval_ref": "cli --write",
        "idea_slug": idea_slug or "N/A",
        "checked_paths": checked_paths,
        "external_novelty_status": _external_novelty_status(evaluation) if isinstance(evaluation, dict) else "missing",
        "external_novelty_provenance_status": _external_novelty_provenance_status(evaluation) if isinstance(evaluation, dict) else "missing",
        "review_llm_status": _review_llm_status(evaluation) if isinstance(evaluation, dict) else "missing",
        "final_acceptance_status": (
            (evaluation.get("final_acceptance_boundary") or {}).get("status")
            if isinstance(evaluation, dict) and isinstance(evaluation.get("final_acceptance_boundary"), dict)
            else "missing"
        ),
        "final_acceptance_ready": (
            bool((evaluation.get("final_acceptance_boundary") or {}).get("final_acceptance_ready"))
            if isinstance(evaluation, dict) and isinstance(evaluation.get("final_acceptance_boundary"), dict)
            else False
        ),
    }
    artifacts: list[dict[str, Any]] = []
    limitations: list[str] = []

    if not evaluation:
        limitations.append("No idea evaluation was available for novelty write-back.")
    elif not bool((evaluation.get("final_acceptance_boundary") or {}).get("final_acceptance_ready")):
        limitations.append("Novelty write-back was skipped because the final multi-source and independent-review acceptance boundary is incomplete.")
    elif str(evaluation.get("source_mode") or "") == "missing" or str(evaluation.get("recommendation") or "") == "inconclusive":
        limitations.append("Novelty write-back was skipped because evaluation evidence is inconclusive.")
    elif _external_novelty_status(evaluation) != "completed":
        limitations.append(
            "Novelty write-back was skipped because completed external novelty evidence is required before mutating wiki novelty_score."
        )
    elif _external_novelty_provenance_status(evaluation) != "passed":
        limitations.append(
            "Novelty write-back was skipped because external novelty provider provenance did not pass write-grade validation."
        )
    elif _review_llm_status(evaluation) != "completed":
        limitations.append(
            "Novelty write-back was skipped because completed Review LLM evidence is required before promotion-grade wiki mutation."
        )
    elif idea_path is None:
        limitations.append("Novelty write-back was skipped because the target did not resolve to an existing wiki idea file.")
    else:
        score = _novelty_score_from_evaluation(evaluation)
        if score is None:
            limitations.append("Novelty write-back was skipped because the evaluation did not include a numeric novelty score.")
        else:
            original = idea_path.read_text(encoding="utf-8", errors="replace")
            updated = _set_frontmatter_scalar(original, "novelty_score", str(score))
            if updated is None:
                limitations.append("Novelty write-back was skipped because the wiki idea file has no YAML frontmatter.")
            else:
                idea_path.write_text(updated, encoding="utf-8")
                wiki_root = next((root for root in _wiki_roots_for_write(envelope) if _path_is_under(idea_path, root)), idea_path.parent.parent)
                log_path = _append_novelty_wiki_log(wiki_root, idea_path, score, evaluation)
                edge_path = _append_novelty_wiki_edge(wiki_root, idea_path, score, evaluation)
                rebuild_paths = _rebuild_wiki_mutation_views(
                    wiki_root,
                    str(evaluation_evidence.get("sprint_id") or envelope.get("sprint_id") or "sprint-autosci"),
                    idea_path,
                    evaluation,
                )
                status = "completed"
                write.update(
                    {
                        "applied": True,
                        "idea_path": _rel(idea_path),
                        "log_path": _rel(log_path),
                        "edge_path": _rel(edge_path),
                        "rebuilt_paths": [_rel(path) for path in rebuild_paths],
                        "novelty_score": score,
                        "source_review_mode": evaluation.get("review_mode", "N/A"),
                        "source_recommendation": evaluation.get("recommendation", "N/A"),
                    }
                )
                artifacts.extend(
                    [
                        {"type": "wiki_idea", "path": _rel(idea_path)},
                        {"type": "wiki_log", "path": _rel(log_path)},
                        {"type": "wiki_graph_edges", "path": _rel(edge_path)},
                        *[{"type": "wiki_rebuild", "path": _rel(path)} for path in rebuild_paths],
                    ]
                )

    if not limitations:
        limitations.append(
            "Novelty write-back updates the targeted wiki idea frontmatter, appends a wiki log entry, "
            "adds a graph edge, and rebuilds lightweight wiki navigation/context."
        )

    evidence = {
        "schema": "novelty_writeback.v1",
        "task_id": f"{evaluation_evidence.get('task_id', 'task-evaluate-ideas')}:novelty-writeback",
        "sprint_id": str(evaluation_evidence.get("sprint_id") or envelope.get("sprint_id") or "sprint-autosci"),
        "node_id": f"{evaluation_evidence.get('node_id', 'node-evaluate-ideas')}:novelty-writeback",
        "status": status,
        "inputs": inputs,
        "outputs": {
            "write": write,
            "source_evaluation": {
                "idea_id": evaluation.get("idea_id", "N/A") if isinstance(evaluation, dict) else "N/A",
                "evidence_ids": list(evaluation.get("evidence_ids") or []) if isinstance(evaluation, dict) else [],
            },
        },
        "artifacts": artifacts,
        "provenance": {
            "operator_id": "autosci-bridge",
            "implementation_package": "plugins/autosci",
            "timestamp": datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        },
        "limitations": limitations,
    }
    sidecar_path = _write_evidence_payload(path, evidence)
    runtime_proof_artifact = _write_wiki_mutation_runtime_proof_manifest(
        envelope,
        action="evaluate_ideas",
        native_skill="novelty",
        writeback_path=path,
        writeback=evidence,
    )
    if runtime_proof_artifact is not None:
        evaluation_evidence.setdefault("artifacts", []).append(runtime_proof_artifact)
    return sidecar_path


SAFE_EXPERIMENT_EXECUTION_MODES = {
    "fixture",
    "dry-run",
    "bounded",
    "bounded-local",
    "benchmark",
    "known-safe-benchmark",
    "human_approved",
    "approved-external",
}
APPROVAL_REQUIRED_EXPERIMENT_MODES = {"human_approved", "approved-external"}


def _fixture_like_envelope(envelope: dict[str, Any]) -> bool:
    inputs = dict(envelope.get("inputs") or {})
    return str(envelope.get("mode") or "") == "fixture" or bool(inputs.get("smoke_mode"))


def _experiment_plan_from_evidence(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    for key in ("experiment_plan_evidence", "plan_evidence", "experiment_plan"):
        payload = _load_optional_evidence(inputs.get(key))
        if not payload:
            continue
        if payload.get("schema") == "experiment_plan.v1":
            plan = ((payload.get("outputs") or {}).get("experiment_plan") or {})
            return dict(plan) if isinstance(plan, dict) else {}
        if isinstance(payload.get("experiment_plan"), dict):
            return dict(payload["experiment_plan"])
    return {}


def _experiment_result_payload(envelope: dict[str, Any]) -> dict[str, Any] | None:
    inputs = dict(envelope.get("inputs") or {})
    for key in ("experiment_result_evidence", "result_evidence", "experiment_result"):
        for payload in _load_optional_evidence_many(inputs.get(key)):
            return payload
    # `exp-status --collect --after-artifact result.json` is a legitimate local
    # monitoring path: the result file is already the collected after-artifact,
    # even when it has not yet been wrapped as experiment_result.v1 evidence.
    # Treat it only as a fallback so explicit evidence remains authoritative.
    for payload in _load_optional_evidence_many(inputs.get("after_artifacts")):
        return payload
    return None


def _experiment_execution_mode(envelope: dict[str, Any], plan: dict[str, Any] | None = None) -> str:
    inputs = dict(envelope.get("inputs") or {})
    return str(
        inputs.get("execution_mode")
        or (plan or {}).get("execution_mode")
        or envelope.get("mode")
        or "fixture"
    )


def _experiment_approval_satisfied(envelope: dict[str, Any]) -> bool:
    inputs = dict(envelope.get("inputs") or {})
    if inputs.get("approved") is True or inputs.get("human_approval") is True:
        return True
    approval_ref = str(inputs.get("approval_ref") or "").strip()
    return bool(approval_ref and approval_ref.upper() != "N/A")


def _experiment_log_artifact(envelope: dict[str, Any], experiment_id: str, log_lines: list[str]) -> dict[str, str]:
    output_dir = _output_dir(envelope, "run_experiment")
    path = output_dir / f"{_slug(experiment_id)}.log"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(log_lines).rstrip() + "\n", encoding="utf-8")
    return {"type": "experiment_run_log", "path": _rel(path)}


def _write_experiment_state_mutation(
    envelope: dict[str, Any],
    *,
    experiment_id: str,
    outcome: str,
    evidence_ids: list[str],
    metrics: list[dict[str, Any]],
) -> list[dict[str, str]]:
    root = _wiki_roots_for_write(envelope)[0]
    now = datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    exp_dir = root / "experiments"
    graph_dir = root / "graph"
    exp_dir.mkdir(parents=True, exist_ok=True)
    graph_dir.mkdir(parents=True, exist_ok=True)
    exp_path = exp_dir / f"{_slug(experiment_id)}.md"
    metric_lines = [
        f"- {metric.get('name')}: {metric.get('value')}"
        for metric in metrics
        if isinstance(metric, dict) and str(metric.get("name") or "").strip()
    ]
    exp_path.write_text(
        "\n".join(
            [
                "---",
                f"experiment_id: {experiment_id}",
                "status: completed",
                f"outcome: {outcome}",
                f"updated_at: {now}",
                "evidence_ids:",
                *[f"  - {item}" for item in evidence_ids],
                "---",
                f"# {experiment_id}",
                "",
                "## Runtime Result",
                "",
                f"- Outcome: `{outcome}`",
                f"- Updated: `{now}`",
                "",
                "## Metrics",
                "",
                *(metric_lines or ["- N/A"]),
                "",
            ]
        ),
        encoding="utf-8",
    )
    log_path = root / "log.md"
    with log_path.open("a", encoding="utf-8") as handle:
        handle.write(f"- {now} | experiment | completed `{experiment_id}` outcome `{outcome}` evidence `{', '.join(evidence_ids)}`\n")
    edge_path = graph_dir / "edges.jsonl"
    with edge_path.open("a", encoding="utf-8") as handle:
        handle.write(
            json.dumps(
                {
                    "source": experiment_id,
                    "target": evidence_ids[0] if evidence_ids else f"runtime:{_slug(experiment_id)}",
                    "relation": "produced_result",
                    "operation": "add",
                    "evidence_ids": evidence_ids,
                    "timestamp": now,
                },
                sort_keys=True,
            )
            + "\n"
        )
    return [
        {"type": "wiki_experiment_state", "path": _rel(exp_path)},
        {"type": "wiki_log", "path": _rel(log_path)},
        {"type": "wiki_graph_edges", "path": _rel(edge_path)},
    ]


def _existing_experiment_state_artifacts(envelope: dict[str, Any], experiment_id: str) -> list[dict[str, str]]:
    artifacts: list[dict[str, str]] = []
    for root in _wiki_roots_for_write(envelope):
        exp_path = root / "experiments" / f"{_slug(experiment_id)}.md"
        log_path = root / "log.md"
        edge_path = root / "graph" / "edges.jsonl"
        if exp_path.exists():
            artifacts.append({"type": "wiki_experiment_state", "path": _rel(exp_path)})
        if log_path.exists():
            artifacts.append({"type": "wiki_log", "path": _rel(log_path)})
        if edge_path.exists():
            artifacts.append({"type": "wiki_graph_edges", "path": _rel(edge_path)})
        if artifacts:
            break
    return artifacts


def _file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _collection_file_digests(paths: list[Path]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for path in sorted(paths, key=lambda item: _rel(item)):
        if not path.exists() or not path.is_file():
            continue
        rows.append({
            "path": _rel(path),
            "sha256": _file_sha256(path),
            "bytes": path.stat().st_size,
        })
    return rows


def _record_collection_ledger(
    envelope: dict[str, Any],
    *,
    experiment_id: str,
    command_run: str,
    collected_files: list[Path],
    evidence_ids: list[str],
) -> dict[str, Any]:
    root = _wiki_roots_for_write(envelope)[0]
    ledger_path = root / "collections" / "collection-ledger.json"
    ledger_path.parent.mkdir(parents=True, exist_ok=True)
    file_digests = _collection_file_digests(collected_files)
    identity_seed = json.dumps({"experiment_id": experiment_id, "files": file_digests}, sort_keys=True)
    identity = hashlib.sha1(identity_seed.encode("utf-8")).hexdigest()
    try:
        ledger = json.loads(ledger_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        ledger = {"schema": "autosci_collection_ledger.v1", "entries": []}
    if not isinstance(ledger, dict):
        ledger = {"schema": "autosci_collection_ledger.v1", "entries": []}
    entries = ledger.get("entries") if isinstance(ledger.get("entries"), list) else []
    for entry in entries:
        if isinstance(entry, dict) and entry.get("collection_identity") == identity:
            ledger["entries"] = entries
            ledger_path.write_text(json.dumps(ledger, indent=2, sort_keys=True) + "\n", encoding="utf-8")
            return {
                "duplicate": True,
                "collection_identity": identity,
                "ledger_path": _rel(ledger_path),
                "entry": entry,
                "file_digests": file_digests,
            }
    now = datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    entry = {
        "collection_identity": identity,
        "experiment_id": experiment_id,
        "accepted_at": now,
        "command_run": command_run,
        "files": file_digests,
        "evidence_ids": _unique_strings(evidence_ids),
    }
    entries.append(entry)
    ledger.update({"schema": "autosci_collection_ledger.v1", "entries": entries})
    ledger_path.write_text(json.dumps(ledger, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return {
        "duplicate": False,
        "collection_identity": identity,
        "ledger_path": _rel(ledger_path),
        "entry": entry,
        "file_digests": file_digests,
    }


def _experiment_run_final_runtime_audit_boundary(
    *,
    stage: str,
    experiment_id: str,
    contract: dict[str, Any] | None,
    semantic: dict[str, Any] | None,
    result_collected: bool,
    artifacts: list[dict[str, str]],
    collection_boundary: dict[str, Any] | None = None,
) -> dict[str, Any]:
    contract = contract if isinstance(contract, dict) else {}
    semantic = semantic if isinstance(semantic, dict) else {}
    detail = semantic.get("detail") if isinstance(semantic.get("detail"), dict) else {}
    artifact_types = {str(artifact.get("type") or "") for artifact in artifacts if isinstance(artifact, dict)}
    runtime_semantic_verified = semantic.get("verified") is True
    approval_contract_verified = contract.get("execution_verified") is True
    wiki_state_mutated = {"wiki_experiment_state", "wiki_log", "wiki_graph_edges"}.issubset(artifact_types)
    collection_ledger_recorded = any(
        str(artifact.get("type") or "") == "collection_ledger_json" and str(artifact.get("path") or "").strip()
        for artifact in artifacts
        if isinstance(artifact, dict)
    )
    if not collection_ledger_recorded and str(detail.get("collection_ledger_path") or "").strip():
        collection_ledger_recorded = True
    collection_boundary = collection_boundary if isinstance(collection_boundary, dict) else {}
    live_remote_collection_verified = collection_boundary.get("live_remote_collection_verified") is True
    stage_audit_ready = all(
        [
            approval_contract_verified,
            runtime_semantic_verified,
            result_collected,
            wiki_state_mutated,
        ]
    )
    if stage == "collect":
        stage_audit_ready = stage_audit_ready and collection_ledger_recorded
    final_runtime_audit_ready = stage == "collect" and stage_audit_ready and live_remote_collection_verified
    limitations: list[str] = []
    if not approval_contract_verified:
        limitations.append("Final runtime audit requires a fully verified approval contract with runtime and after-artifact evidence.")
    if not runtime_semantic_verified:
        limitations.append("Final runtime audit requires semantic runtime verification to pass.")
    if not result_collected:
        limitations.append("Final runtime audit requires collected experiment result evidence.")
    if not wiki_state_mutated:
        limitations.append("Final runtime audit requires wiki experiment state, log, and graph mutation proof.")
    if stage == "run":
        limitations.append("Final lifecycle audit also requires an approved monitor/collect stage with collection ledger evidence.")
    if stage == "collect" and not collection_ledger_recorded:
        limitations.append("Final collect audit requires a collection ledger entry.")
    if stage == "collect" and not live_remote_collection_verified:
        limitations.append("Final collect audit requires live remote/provider collection boundary proof.")
    if not limitations:
        limitations.append("Final runtime audit passed with approved runtime, live collection, collection ledger, and wiki mutation evidence.")
    status = (
        "final_runtime_audit_ready"
        if final_runtime_audit_ready
        else "stage_runtime_audit_ready"
        if stage_audit_ready
        else "runtime_audit_incomplete"
    )
    return {
        "schema": "autosci_experiment_run_final_runtime_audit_boundary.v1",
        "stage": stage,
        "experiment_id": experiment_id,
        "status": status,
        "stage_audit_ready": stage_audit_ready,
        "final_runtime_audit_ready": final_runtime_audit_ready,
        "approval_contract_verified": approval_contract_verified,
        "approval_state": str(contract.get("approval_state") or "missing"),
        "runtime_semantic_verified": runtime_semantic_verified,
        "runtime_semantic_status": str(semantic.get("status") or "missing"),
        "result_collected": result_collected,
        "wiki_state_mutated": wiki_state_mutated,
        "collection_ledger_recorded": collection_ledger_recorded,
        "live_remote_collection_verified": live_remote_collection_verified,
        "remote_collection_boundary_status": str(collection_boundary.get("status") or "N/A"),
        "artifact_types": sorted(item for item in artifact_types if item),
        "limitations": limitations,
    }


def _attach_experiment_run_runtime_audit_boundary(
    envelope: dict[str, Any],
    evidence: dict[str, Any],
    *,
    action: str,
    stage: str,
    experiment_id: str,
    contract: dict[str, Any] | None,
    semantic: dict[str, Any] | None,
    result_collected: bool,
    collection_boundary: dict[str, Any] | None = None,
) -> dict[str, Any]:
    artifacts = [artifact for artifact in evidence.get("artifacts") or [] if isinstance(artifact, dict)]
    boundary = _experiment_run_final_runtime_audit_boundary(
        stage=stage,
        experiment_id=experiment_id,
        contract=contract,
        semantic=semantic,
        result_collected=result_collected,
        artifacts=artifacts,
        collection_boundary=collection_boundary,
    )
    outputs = evidence.setdefault("outputs", {})
    if isinstance(outputs.get("result"), dict):
        outputs["result"]["final_runtime_audit_boundary"] = boundary
        outputs["result"]["final_runtime_audit_ready"] = boundary.get("final_runtime_audit_ready") is True
    if isinstance(outputs.get("status_report"), dict):
        outputs["status_report"]["final_runtime_audit_boundary"] = boundary
        outputs["status_report"]["final_runtime_audit_ready"] = boundary.get("final_runtime_audit_ready") is True
    outputs["final_runtime_audit_boundary"] = boundary
    boundary_path = _write_json_sidecar(
        _output_dir(envelope, action) / "experiment_run_final_runtime_audit_boundary.json",
        boundary,
    )
    evidence.setdefault("artifacts", []).append(
        {"type": "experiment_run_final_runtime_audit_boundary_json", "path": boundary_path}
    )
    evidence_payload_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        _output_dir(envelope, action) / f"{action}.evidence.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    runtime_proof_artifact = _write_experiment_run_final_runtime_proof_manifest(
        envelope,
        action=action,
        evidence_path=evidence_payload_path,
        boundary_path=boundary_path,
        boundary=boundary,
        artifacts=[artifact for artifact in evidence.get("artifacts") or [] if isinstance(artifact, dict)],
    )
    if runtime_proof_artifact is not None:
        evidence.setdefault("artifacts", []).append(runtime_proof_artifact)
    evidence.setdefault("limitations", []).extend(str(item) for item in boundary.get("limitations") or [])
    return evidence


def _experiment_session_registry_path(envelope: dict[str, Any]) -> Path:
    root = _wiki_roots_for_write(envelope)[0]
    return root / "experiments" / "session-registry.json"


def _remote_launch_session_state(record: dict[str, Any], *, remote_runtime_rel: str) -> str:
    status = str(record.get("status") or "").strip().lower()
    if status == "failed":
        return "failed"
    if status == "completed" and remote_runtime_rel:
        return "completed"
    if status in {"completed", "inconclusive", "running", "started", "launched"}:
        return "running"
    return "unknown"


def _record_experiment_session(
    envelope: dict[str, Any],
    *,
    experiment_id: str,
    command_run: str,
    record: dict[str, Any],
    remote_runtime_rel: str,
) -> dict[str, Any]:
    registry_path = _experiment_session_registry_path(envelope)
    registry_path.parent.mkdir(parents=True, exist_ok=True)
    try:
        registry = json.loads(registry_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        registry = {"schema": "autosci_experiment_session_registry.v1", "sessions": []}
    if not isinstance(registry, dict):
        registry = {"schema": "autosci_experiment_session_registry.v1", "sessions": []}
    sessions = registry.get("sessions") if isinstance(registry.get("sessions"), list) else []
    now = datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    session = {
        "experiment_id": experiment_id,
        "state": _remote_launch_session_state(record, remote_runtime_rel=remote_runtime_rel),
        "command_run": command_run,
        "remote_cli_status": str(record.get("status") or ""),
        "run_dir": str(record.get("run_dir") or ""),
        "runtime_evidence_path": remote_runtime_rel,
        "result_collected": bool(record.get("result_collected")),
        "updated_at": now,
    }
    replaced = False
    for index, existing in enumerate(sessions):
        if isinstance(existing, dict) and existing.get("experiment_id") == experiment_id:
            sessions[index] = session
            replaced = True
            break
    if not replaced:
        sessions.append(session)
    registry.update({"schema": "autosci_experiment_session_registry.v1", "sessions": sessions})
    registry_path.write_text(json.dumps(registry, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return {"registry_path": _rel(registry_path), "session": session}


def _experiment_session_from_registry(envelope: dict[str, Any], experiment_id: str) -> tuple[dict[str, Any] | None, dict[str, str] | None]:
    registry_path = _experiment_session_registry_path(envelope)
    if not registry_path.exists():
        return None, None
    try:
        registry = json.loads(registry_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None, {"type": "experiment_session_registry_json", "path": _rel(registry_path)}
    sessions = registry.get("sessions") if isinstance(registry, dict) and isinstance(registry.get("sessions"), list) else []
    for session in sessions:
        if isinstance(session, dict) and str(session.get("experiment_id") or "") == experiment_id:
            return session, {"type": "experiment_session_registry_json", "path": _rel(registry_path)}
    return None, {"type": "experiment_session_registry_json", "path": _rel(registry_path)}


def _session_status_raw(
    *,
    experiment_id: str,
    session: dict[str, Any],
    session_artifact: dict[str, str] | None,
    wiki_artifacts: list[dict[str, str]],
    wiki_state: dict[str, Any] | None,
) -> dict[str, Any]:
    state = str(session.get("state") or "unknown")
    session_artifacts = [*wiki_artifacts]
    if session_artifact:
        session_artifacts.append(session_artifact)
    observations = [
        f"Resolved experiment session `{experiment_id}` with state `{state}`.",
        f"remote_cli_status={session.get('remote_cli_status') or 'N/A'}",
    ]
    run_dir = str(session.get("run_dir") or "").strip()
    if run_dir:
        observations.append(f"run_dir={run_dir}")
    next_actions = (
        ["Run approved collect with runtime evidence before treating results as collected."]
        if state in {"running", "unknown"}
        else ["Inspect failed session logs before retry."]
        if state == "failed"
        else ["Use collected result evidence for claim verification and reporting."]
    )
    evidence_ids = _unique_strings([experiment_id, str(session.get("runtime_evidence_path") or ""), session_artifact["path"] if session_artifact else ""])
    return {
        "experiment_id": experiment_id,
        "state": state,
        "observations": observations,
        "next_actions": next_actions,
        "evidence_ids": evidence_ids or [experiment_id, "experiment-session:registry"],
        "status": "completed" if state != "unknown" else "inconclusive",
        "artifacts": session_artifacts,
        "limitations": [
            "Experiment status was read from the local session registry; no remote process was polled and no results were collected in this status call.",
            *_wiki_state_limitations(wiki_state),
        ],
    }


def _strict_experiment_command_allowlisted(command: list[str], contract: dict[str, Any]) -> tuple[bool, str]:
    """Match the complete argv only; broad executable/prefix/template rules are unsafe here."""
    if not command:
        return False, "empty command argv"
    for payload in _allowlist_payloads(contract):
        candidates = payload.get("command_argvs")
        if not isinstance(candidates, list):
            continue
        for candidate in candidates:
            if isinstance(candidate, list) and [str(item) for item in candidate] == command:
                return True, "exact command_argvs token match"
    return False, "no token-for-token exact argv entry matched"


def _verification_contract_safety(
    verification_contract: dict[str, Any],
    contract: dict[str, Any],
) -> tuple[dict[str, Any], list[str]]:
    reasons: list[str] = []
    version = str(verification_contract.get("verification_contract_version") or "")
    profile = str(verification_contract.get("readiness_profile") or "")
    workspace_raw = str(verification_contract.get("workspace_root") or "").strip()
    runner_raw = str((verification_contract.get("runner") or {}).get("path") or "").strip()
    dataset_raw = str((verification_contract.get("dataset") or {}).get("path") or "").strip()
    expected_raw = [str(item) for item in verification_contract.get("expected_artifacts") or [] if str(item).strip()]
    write_raw = [str(item) for item in verification_contract.get("write_scope") or [] if str(item).strip()]
    command_argv = [str(item) for item in verification_contract.get("command_argv") or [] if str(item).strip()]

    if version != "1":
        reasons.append("verification contract version is missing or unsupported")
    if profile not in {"deterministic_local_fixture", "human_approved_local"}:
        reasons.append("readiness profile is missing or unsupported")
    if verification_contract.get("network_access") != "denied":
        reasons.append("network access is not denied")

    workspace = _resolve_harness_path(workspace_raw).resolve() if workspace_raw else None
    runner = _resolve_harness_path(runner_raw).resolve() if runner_raw else None
    dataset = _resolve_harness_path(dataset_raw).resolve() if dataset_raw else None
    expected = [_resolve_harness_path(item).resolve() for item in expected_raw]
    write_scope = [_resolve_harness_path(item).resolve() for item in write_raw]
    allowed_anchor = HARNESS_DIR.parent.resolve()
    workspace_allowed = bool(
        workspace
        and workspace.is_dir()
        and _path_is_under(workspace, allowed_anchor)
    )
    if not workspace_allowed:
        reasons.append("workspace root is missing or outside the harness sandbox allow root")

    asset_paths = [path for path in [runner, dataset, *expected] if path is not None]
    if not runner or not runner.is_file():
        reasons.append("runner path is missing or does not exist")
    if not dataset or not dataset.is_file():
        reasons.append("dataset path is missing or does not exist")
    expected_targets_writable = bool(expected) and all(
        (path.is_file() and os.access(path, os.W_OK))
        if path.exists()
        else path.parent.is_dir() and os.access(path.parent, os.W_OK)
        for path in expected
    )
    if not expected_targets_writable:
        reasons.append("expected artifact targets must have an existing writable parent and must not be directories")
    if workspace and any(not _path_is_under(path, workspace) for path in asset_paths):
        reasons.append("runner, dataset, and expected artifacts must remain inside workspace root")
    write_scope_restricted = bool(write_scope) and all(
        path.is_dir()
        and os.access(path, os.W_OK)
        and (not workspace or _path_is_under(path, workspace))
        for path in write_scope
    )
    if not write_scope_restricted:
        reasons.append("write scope is missing or escapes workspace root")
    if expected and write_scope and any(not any(_path_is_under(path, root) for root in write_scope) for path in expected):
        reasons.append("expected artifacts are outside the declared write scope")

    before_paths = {
        _resolve_harness_path(str(entry.get("path") or "")).resolve()
        for entry in contract.get("before_artifacts") or []
        if isinstance(entry, dict) and str(entry.get("path") or "").strip()
    }
    before_dataset_matches = bool(dataset and before_paths == {dataset})
    if not before_dataset_matches:
        reasons.append("before-state evidence must match the declared dataset exactly")

    runner_matches = bool(len(command_argv) >= 2 and runner and Path(command_argv[1]).resolve() == runner)
    dataset_matches = bool(len(command_argv) >= 3 and dataset and Path(command_argv[2]).resolve() == dataset)
    expected_matches = bool(command_argv and expected and Path(command_argv[-1]).resolve() in expected)
    if not runner_matches or not dataset_matches or not expected_matches:
        reasons.append("command argv does not bind the declared runner, dataset, and expected artifact")

    checks = {
        "verification_contract_version": version,
        "readiness_profile": profile,
        "workspace_allowed": workspace_allowed,
        "runner_exists": bool(runner and runner.is_file()),
        "dataset_exists": bool(dataset and dataset.is_file()),
        "expected_artifact_targets_writable": expected_targets_writable,
        "network_denied": verification_contract.get("network_access") == "denied",
        "write_scope_restricted": write_scope_restricted,
        "before_dataset_matches": before_dataset_matches,
        "command_binds_declared_assets": runner_matches and dataset_matches and expected_matches,
    }
    return checks, reasons


def _experiment_design_final_execution_boundary(
    envelope: dict[str, Any],
    *,
    target_ref: str,
    review_llm: dict[str, Any],
    execution_mode: str,
    approval_required: bool,
    command_allowlist: list[str],
    expected_artifacts: list[str],
    verification_contract: dict[str, Any],
) -> dict[str, Any]:
    contract = _approval_contract(
        envelope,
        "run_experiment",
        ["local_process_launch", "remote_execution", "result_collection", "artifact_handoff"],
    )
    target_resolved = bool(str(target_ref or "").strip())
    review_completed = str(review_llm.get("status") or "") == "completed"
    approval_ready = bool(contract.get("ready_for_execution"))
    command_handoff_declared = bool(command_allowlist)
    artifact_handoff_declared = bool(expected_artifacts)
    dataset = verification_contract.get("dataset")
    variants = verification_contract.get("variants")
    thresholds = verification_contract.get("thresholds")
    random_seed = verification_contract.get("random_seed")
    stopping_conditions = verification_contract.get("stopping_conditions")
    command_argv = [str(item) for item in verification_contract.get("command_argv") or [] if str(item).strip()]
    verification_contract_version = str(verification_contract.get("verification_contract_version") or "")
    readiness_profile = str(verification_contract.get("readiness_profile") or "")
    verification_contract_complete = bool(
        verification_contract_version == "1"
        and readiness_profile in {"deterministic_local_fixture", "human_approved_local"}
        and isinstance(dataset, dict)
        and all(str(dataset.get(key) or "").strip() for key in ("path", "format", "role"))
        and isinstance(variants, list)
        and len(variants) >= 2
        and isinstance(thresholds, list)
        and bool(thresholds)
        and isinstance(random_seed, int)
        and isinstance(stopping_conditions, list)
        and bool(stopping_conditions)
        and command_argv
    )
    safety_checks, safety_reasons = _verification_contract_safety(verification_contract, contract)
    safety_ready = not safety_reasons
    command_authorized, command_authorization_reason = _strict_experiment_command_allowlisted(command_argv, contract)
    fixture_exemption = execution_mode == "fixture" and readiness_profile == "deterministic_local_fixture"
    human_profile = execution_mode == "human_approved" and readiness_profile == "human_approved_local"
    effective_approval_state = (
        str(contract.get("approval_state") or "N/A")
        if approval_required
        else "not_required"
        if fixture_exemption
        else "approval_required"
    )
    approval_gate_satisfied = approval_ready if approval_required else fixture_exemption
    preflight_ready = safety_ready and command_authorized and (
        approval_ready if approval_required else fixture_exemption
    )
    approval_preflight = {
        "status": "ready" if approval_required and preflight_ready else "not_required" if fixture_exemption and preflight_ready else "incomplete",
        "approval_state": effective_approval_state,
        "approval_ref": str(contract.get("approval_ref") or ""),
        "allowlist_ready": bool(contract.get("allowlist_ready")),
        "before_state_ready": bool(contract.get("before_ready")),
        "command_authorized": command_authorized,
        "command_authorization_reason": command_authorization_reason,
        "safety_checks": safety_checks,
    }
    blocking_reasons: list[str] = []
    if not target_resolved:
        blocking_reasons.append("target idea/claim evidence was not resolved")
    if approval_required and not review_completed:
        blocking_reasons.append("completed Review LLM design validation is missing")
    if approval_required and not approval_ready:
        blocking_reasons.append("approved runtime preflight contract is incomplete")
    if approval_required and not human_profile:
        blocking_reasons.append("human-approved execution requires the human_approved_local readiness profile")
    if not approval_required and not fixture_exemption:
        blocking_reasons.append("approval exemption is limited to explicit deterministic fixture mode")
    if not command_handoff_declared:
        blocking_reasons.append("runtime command handoff is missing")
    if not artifact_handoff_declared:
        blocking_reasons.append("expected artifact handoff is missing")
    if not verification_contract_complete:
        blocking_reasons.append("dataset, variants, thresholds, seed, stopping conditions, or exact command are incomplete")
    blocking_reasons.extend(safety_reasons)
    if command_argv and not command_authorized:
        blocking_reasons.append("planned runtime command is not authorized by the supplied allowlist evidence")
    execution_ready = not blocking_reasons
    return {
        "schema": "autosci_experiment_design_final_execution_boundary.v1",
        "status": "execution_ready" if execution_ready else "execution_readiness_incomplete",
        "execution_ready": execution_ready,
        "target_resolved": target_resolved,
        "target_ref": target_ref or "N/A",
        "execution_mode": execution_mode,
        "approval_required": approval_required,
        "approval_state": effective_approval_state,
        "approval_ready_for_execution": approval_gate_satisfied,
        "review_llm_status": str(review_llm.get("status") or "missing"),
        "review_llm_completed": review_completed,
        "review_evidence_ids": _unique_strings([str(item) for item in review_llm.get("evidence_ids") or []]),
        "command_handoff_declared": command_handoff_declared,
        "command_allowlist": command_allowlist,
        "artifact_handoff_declared": artifact_handoff_declared,
        "expected_artifacts": expected_artifacts,
        "verification_contract_complete": verification_contract_complete,
        "approval_preflight": approval_preflight,
        "blocking_reasons": blocking_reasons,
        "limitations": [] if execution_ready else [
            "Experiment design final execution readiness requires resolved target evidence, completed Review LLM validation, approval preflight, command handoff, and expected artifact handoff."
        ],
    }


def _write_experiment_design_boundary(
    envelope: dict[str, Any],
    boundary: dict[str, Any],
) -> dict[str, str]:
    path = _output_dir(envelope, "design_experiment") / "experiment_design_final_execution_boundary.json"
    return {"type": "experiment_design_final_execution_boundary_json", "path": _write_json_sidecar(path, boundary)}


def _path_token(path: Path | str) -> str:
    return str(Path(path).resolve()).replace("\\", "/")


def _write_experiment_poc_assets(
    envelope: dict[str, Any],
    *,
    experiment_id: str,
    target_ref: str,
) -> dict[str, Any]:
    short_id = hashlib.sha256(experiment_id.encode("utf-8")).hexdigest()[:12]
    asset_root = _output_dir(envelope, "design_experiment") / "poc" / short_id
    data_path = asset_root / "input_samples.csv"
    runner_path = asset_root / "run_poc_experiment.py"
    result_path = asset_root / "experiment_result.v1.json"
    manifest_path = asset_root / "poc_manifest.json"
    allowlist_path = asset_root / "command_allowlist.json"
    check_path = asset_root / "poc_usability_check.json"
    asset_root.mkdir(parents=True, exist_ok=True)
    _write_text_sidecar(
        data_path,
        "\n".join(
            [
                "sample_id,condition,baseline_errors,variant_errors",
                "s1,fixture,4,1",
                "s2,fixture,3,1",
                "s3,fixture,5,2",
                "s4,fixture,4,1",
            ]
        )
        + "\n",
    )
    _write_text_sidecar(
        runner_path,
        "\n".join(
            [
                "from __future__ import annotations",
                "",
                "import csv",
                "import json",
                "import os",
                "import sys",
                "from pathlib import Path",
                "",
                "def _windows_long_path(path: Path) -> str:",
                "    resolved = str(path.resolve())",
                "    if os.name != 'nt' or resolved.startswith('\\\\\\\\?\\\\'):",
                "        return resolved",
                "    if resolved.startswith('\\\\\\\\'):",
                "        return '\\\\\\\\?\\\\UNC\\\\' + resolved[2:]",
                "    return '\\\\\\\\?\\\\' + resolved",
                "",
                "def _write_text(path: Path, body: str) -> None:",
                "    path.parent.mkdir(parents=True, exist_ok=True)",
                "    with open(_windows_long_path(path), 'w', encoding='utf-8') as fh:",
                "        fh.write(body)",
                "",
                "def main(argv: list[str]) -> int:",
                "    if len(argv) != 3:",
                "        print(json.dumps({'schema': 'experiment_result.v1', 'status': 'failed', 'outputs': {'result': {'outcome': 'failed', 'metrics': [], 'evidence_ids': ['poc:usage-error'], 'logs': ['usage: run_poc_experiment.py <input.csv> <result.json>']}}}))",
                "        return 2",
                "    data_path = Path(argv[1])",
                "    result_path = Path(argv[2])",
                "    rows = list(csv.DictReader(data_path.open(encoding='utf-8')))",
                "    baseline = sum(int(row['baseline_errors']) for row in rows)",
                "    variant = sum(int(row['variant_errors']) for row in rows)",
                "    reduction = (baseline - variant) / baseline if baseline else 0.0",
                "    outcome = 'supports' if reduction >= 0.5 else 'refutes'",
                "    result = {",
                "        'experiment_id': '" + experiment_id.replace("'", "\\'") + "',",
                "        'random_seed': 0,",
                "        'outcome': outcome,",
                "        'metrics': [",
                "            {'name': 'baseline_error_total', 'value': baseline},",
                "            {'name': 'variant_error_total', 'value': variant},",
                "            {'name': 'error_reduction_fraction', 'value': reduction},",
                "        ],",
                "        'evidence_ids': ['poc:" + _slug(experiment_id) + ":input_samples', 'poc:" + _slug(experiment_id) + ":runtime'],",
                "        'logs': [f'processed_rows={len(rows)}', f'error_reduction_fraction={reduction:.6f}'],",
                "    }",
                "    payload = {",
                "        'schema': 'experiment_result.v1',",
                "        'status': 'completed',",
                "        'outputs': {'result': result},",
                "    }",
                "    _write_text(result_path, json.dumps(payload, indent=2, sort_keys=True) + '\\n')",
                "    print(json.dumps(payload, sort_keys=True))",
                "    return 0",
                "",
                "if __name__ == '__main__':",
                "    raise SystemExit(main(sys.argv))",
            ]
        )
        + "\n",
    )
    command = [_path_token(sys.executable), _path_token(runner_path), _path_token(data_path), _path_token(result_path)]
    command_text = " ".join(shlex.quote(item) for item in command)
    allowlist = {
        "schema": "autosci_experiment_command_allowlist.v1",
        "experiment_id": experiment_id,
        "commands": [command_text],
        "command_argvs": [command],
        "executables": [_path_token(sys.executable), Path(sys.executable).name],
        "allowed_prefixes": [" ".join(shlex.quote(item) for item in command[:3])],
        "limitations": ["Allowlist is scoped to the generated deterministic local POC runner."],
    }
    manifest = {
        "schema": "autosci_experiment_poc_manifest.v1",
        "experiment_id": experiment_id,
        "target_ref": target_ref,
        "runner_path": _rel(runner_path),
        "input_path": _rel(data_path),
        "result_path": _rel(result_path),
        "allowlist_path": _rel(allowlist_path),
        "command": command_text,
        "artifact_contract": {
            "physical_operator": "autosci-experiment-design-worker",
            "run_operator": "autosci-experiment-run-worker",
            "monitor_operator": "autosci-experiment-monitor-worker",
            "terminal_states": ["completed", "failed", "blocked", "cancelled"],
        },
    }
    usability = {
        "schema": "autosci_experiment_poc_usability_check.v1",
        "experiment_id": experiment_id,
        "status": "completed",
        "checks": [
            {"check": "runner_exists", "status": "ok" if runner_path.is_file() else "error", "path": _rel(runner_path)},
            {"check": "input_exists", "status": "ok" if data_path.is_file() else "error", "path": _rel(data_path)},
            {"check": "allowlist_exists", "status": "ok", "path": _rel(allowlist_path)},
            {"check": "command_declared", "status": "ok" if command_text else "error", "command": command_text},
        ],
        "minimum_usability": "runner plus CSV plus allowlist are present and can be passed to exp-run.",
    }
    _write_json_sidecar(allowlist_path, allowlist)
    _write_json_sidecar(manifest_path, manifest)
    _write_json_sidecar(check_path, usability)
    return {
        "manifest": manifest,
        "allowlist": allowlist,
        "usability": usability,
        "verification_contract": {
            "verification_contract_version": "1",
            "readiness_profile": "deterministic_local_fixture",
            "workspace_root": _path_token(asset_root),
            "runner": {"path": _path_token(runner_path)},
            "dataset": {"path": _path_token(data_path), "format": "csv", "role": "bounded evaluation input"},
            "variants": [
                {"name": "baseline", "description": "Unmodified baseline error counts from each input row."},
                {"name": "variant", "description": "Candidate variant error counts from each input row."},
            ],
            "thresholds": [{"metric": "error_reduction_fraction", "operator": ">=", "value": 0.5}],
            "random_seed": 0,
            "stopping_conditions": [
                "Stop after every declared input row is processed.",
                "Stop with failure if the bounded process exceeds the declared timeout.",
            ],
            "command_argv": command,
            "expected_artifacts": [_path_token(result_path)],
            "network_access": "denied",
            "write_scope": [_path_token(asset_root)],
        },
        "artifacts": [
            {"type": "poc_runtime_runner", "path": _rel(runner_path)},
            {"type": "poc_input_dataset", "path": _rel(data_path)},
            {"type": "poc_expected_result_json", "path": _rel(result_path)},
            {"type": "poc_command_allowlist_json", "path": _rel(allowlist_path)},
            {"type": "poc_manifest_json", "path": _rel(manifest_path)},
            {"type": "poc_usability_check_json", "path": _rel(check_path)},
        ],
    }


def _action_design_experiment(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    execution_mode = _experiment_execution_mode(envelope)
    supplied_contract = _load_optional_evidence(inputs.get("experiment_contract"))
    if supplied_contract and supplied_contract.get("execution_mode") is not None:
        execution_mode = str(supplied_contract.get("execution_mode") or "")
    wiki_state, wiki_state_artifact = _wiki_state_resolver_artifact(envelope, "design_experiment")
    wiki_artifacts = [wiki_state_artifact] if wiki_state_artifact else []
    raw_target = str(inputs.get("claim_or_idea_ref") or inputs.get("target") or "").strip()
    claim_id = str(inputs.get("claim_id") or "").strip()
    idea_id = str(inputs.get("idea_id") or "").strip()
    if not claim_id and raw_target.startswith("claim"):
        claim_id = raw_target
    if not idea_id and raw_target.startswith("idea"):
        idea_id = raw_target
    resolved_idea = _target_idea_from_wiki_state(wiki_state)
    if resolved_idea and not idea_id:
        idea_id = str(resolved_idea.get("idea_id") or "")
        raw_target = raw_target or idea_id
    if _fixture_like_envelope(envelope):
        claim_id = claim_id or "claim-001"
        idea_id = idea_id or "idea-001"
        raw_target = raw_target or claim_id or idea_id
    target_ref = raw_target or claim_id or idea_id
    if not target_ref:
        boundary = _experiment_design_final_execution_boundary(
            envelope,
            target_ref="",
            review_llm={},
            execution_mode=execution_mode,
            approval_required=False,
            command_allowlist=[],
            expected_artifacts=[],
            verification_contract={},
        )
        boundary_artifact = _write_experiment_design_boundary(envelope, boundary)
        return convert_experiment_plan({
            "experiment_id": "experiment-unresolved",
            "objective": "No claim, idea, target, or experiment plan evidence was resolved for experiment design.",
            "hypothesis": "N/A",
            "variables": ["N/A"],
            "metrics": ["N/A"],
            "procedure": ["Resolve a concrete wiki idea, claim, or experiment plan before designing an experiment."],
            "approval_required": False,
            "expected_artifacts": [],
            "execution_mode": execution_mode,
            "baseline": "N/A",
            "baseline_absence_reason": "No target evidence was resolved.",
            "success_criteria": ["target evidence resolved"],
            "command_allowlist": [],
            "resource_limits": {"network": "denied", "write_scope": "none"},
            "source_context": {"final_execution_boundary": boundary},
            "status": "inconclusive",
            "artifacts": [*wiki_artifacts, boundary_artifact],
            "limitations": [
                "Experiment design was skipped because no target evidence was resolved; no default idea-001 fallback was used.",
                *[str(item) for item in boundary.get("limitations") or []],
                *_wiki_state_limitations(wiki_state),
            ],
        }, envelope)
    review_llm, review_evidence_ids, review_artifacts = _claim_review_llm_context(
        envelope,
        target_ref,
        artifact_type="experiment_design_review_llm_evidence_json",
    )
    approval_required = execution_mode in APPROVAL_REQUIRED_EXPERIMENT_MODES
    fixture_plan = execution_mode == "fixture" or _fixture_like_envelope(envelope)
    if fixture_plan:
        objective = f"Validate evidence coverage for `{target_ref}` using a bounded fixture experiment."
        hypothesis = "Fixture execution will emit result evidence, a ledger entry, and a monitorable status without external side effects."
        variables = ["execution_mode", "evidence_payload"]
        metrics = ["result_json_written", "evidence_jsonl_written", "fixture_passed"]
        procedure = [
            "Confirm the experiment plan evidence is present.",
            "Run the AutoSci bridge in fixture mode only.",
            "Record command, metrics, logs, and produced evidence paths.",
            "Validate experiment_result.v1 and experiment_status.v1 gates.",
        ]
        baseline = "previous fixture bridge run writes result.json and evidence.jsonl"
        baseline_absence_reason = ""
        success_criteria = [
            "result_json_written == true",
            "evidence_jsonl_written == true",
            "fixture_passed == true",
        ]
        resource_limits = {"network": "denied", "write_scope": "artifact_dir_only", "timeout_seconds": 30}
        limitations = ["Fixture experiment design is bounded to local bridge artifacts.", *_wiki_state_limitations(wiki_state)]
    else:
        objective = f"Validate evidence coverage for `{target_ref}` using an approval-gated native experiment."
        hypothesis = "A verified approved runtime will produce result artifacts without relying on surrogate outcomes."
        variables = ["execution_mode", "approval_contract", "runtime_evidence"]
        metrics = ["approval_present", "runtime_evidence_verified", "result_artifact_present"]
        procedure = [
            "Resolve the target idea, claim, or experiment plan evidence.",
            "Require explicit approval and allowlisted runtime command evidence before execution.",
            "Collect runtime logs, metrics, and produced result artifacts.",
            "Validate experiment_result.v1 and experiment_status.v1 from supplied runtime evidence.",
        ]
        baseline = "N/A"
        baseline_absence_reason = "No native runtime has executed yet."
        success_criteria = [
            "approval_present == true",
            "runtime_evidence_verified == true",
            "result_artifact_present == true",
        ]
        resource_limits = {"network": "requires_approval", "write_scope": "approved_artifact_dir_only", "timeout_seconds": 0}
        limitations = ["Approval-gated native experiment design; no command is executed by this planning action.", *_wiki_state_limitations(wiki_state)]
    if review_llm.get("status") == "completed":
        procedure.append("Attach completed Review LLM design validation before execution approval.")
        success_criteria.append("review_llm_design_validation == completed")
        limitations.append("Review LLM design validation evidence is attached; execution still requires explicit approval/runtime evidence.")
    elif _input_path_values(inputs, "review_llm_evidence", "review_evidence", "artifact_review_evidence"):
        limitations.append("Supplied Review LLM design validation evidence did not complete.")
    elif fixture_plan:
        limitations.append("Review LLM validation is not required for the deterministic local fixture design; non-fixture execution remains approval-gated.")
    else:
        limitations.append("Review LLM design validation was not supplied.")
    native_experiment_id = _slug(target_ref)
    if not native_experiment_id.startswith(("exp-", "experiment-")):
        native_experiment_id = f"exp-{native_experiment_id}"
    plan_experiment_id = "exp-001" if _fixture_like_envelope(envelope) else native_experiment_id
    poc_assets = _write_experiment_poc_assets(
        envelope,
        experiment_id=plan_experiment_id,
        target_ref=target_ref,
    )
    expected_artifacts = [
        poc_assets["manifest"]["result_path"],
        "experiment_status.json",
        "experiment_run.log",
    ]
    command_allowlist = [str(poc_assets["manifest"]["command"])]
    verification_contract = dict(poc_assets["verification_contract"])
    if execution_mode == "human_approved":
        verification_contract["readiness_profile"] = "human_approved_local"
    if supplied_contract:
        verification_contract = {
            key: supplied_contract.get(key)
            for key in (
                "verification_contract_version",
                "readiness_profile",
                "workspace_root",
                "runner",
                "dataset",
                "variants",
                "thresholds",
                "random_seed",
                "stopping_conditions",
                "command_argv",
                "expected_artifacts",
                "network_access",
                "write_scope",
            )
        }
        supplied_allowlist = [str(item) for item in supplied_contract.get("command_allowlist") or [] if str(item).strip()]
        if supplied_allowlist:
            command_allowlist = supplied_allowlist
        supplied_artifacts = [str(item) for item in supplied_contract.get("expected_artifacts") or [] if str(item).strip()]
        if supplied_artifacts:
            expected_artifacts = supplied_artifacts
        objective = str(supplied_contract.get("objective") or objective)
        hypothesis = str(supplied_contract.get("hypothesis") or hypothesis)
        variables = [str(item) for item in supplied_contract.get("variables") or variables]
        metrics = [str(item) for item in supplied_contract.get("metrics") or metrics]
        procedure = [str(item) for item in supplied_contract.get("procedure") or procedure]
        baseline = str(supplied_contract.get("baseline") or baseline)
        baseline_absence_reason = str(supplied_contract.get("baseline_absence_reason") or baseline_absence_reason)
        success_criteria = [str(item) for item in supplied_contract.get("success_criteria") or success_criteria]
    boundary = _experiment_design_final_execution_boundary(
        envelope,
        target_ref=target_ref,
        review_llm=review_llm,
        execution_mode=execution_mode,
        approval_required=approval_required,
        command_allowlist=command_allowlist,
        expected_artifacts=expected_artifacts,
        verification_contract=verification_contract,
    )
    boundary_artifact = _write_experiment_design_boundary(envelope, boundary)
    if boundary.get("execution_ready"):
        success_criteria.append("final_execution_boundary == execution_ready")
    else:
        limitations.extend(str(item) for item in boundary.get("limitations") or [])
    evidence_payload_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        _output_dir(envelope, "design_experiment") / "design_experiment.evidence.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    review_runtime_proof_artifact = _write_review_context_runtime_proof_manifest(
        envelope,
        action="design_experiment",
        native_skill="exp-design",
        evidence_path=evidence_payload_path,
        review_llm=review_llm,
    )
    artifacts = [*wiki_artifacts, *review_artifacts, boundary_artifact, *poc_assets["artifacts"]]
    if review_runtime_proof_artifact is not None:
        artifacts.append(review_runtime_proof_artifact)
    return convert_experiment_plan({
        "experiment_id": plan_experiment_id,
        "objective": objective,
        "hypothesis": hypothesis,
        "variables": variables,
        "metrics": metrics,
        "procedure": procedure,
        "approval_required": approval_required,
        "expected_artifacts": expected_artifacts,
        "execution_mode": execution_mode,
        "baseline": baseline,
        "baseline_absence_reason": baseline_absence_reason,
        "success_criteria": success_criteria,
        "command_allowlist": command_allowlist,
        "resource_limits": resource_limits,
        **verification_contract,
        "approval_preflight": boundary["approval_preflight"],
        "execution_ready": bool(boundary.get("execution_ready")),
        "review_llm": review_llm,
        "source_context": {"final_execution_boundary": boundary},
        "evidence_ids": _unique_strings([target_ref, *review_evidence_ids]),
        "artifacts": artifacts,
        "limitations": limitations,
    }, envelope)


def _action_run_experiment(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    plan = _experiment_plan_from_evidence(envelope)
    execution_mode = _experiment_execution_mode(envelope, plan)
    target_ref = str(inputs.get("experiment_id") or inputs.get("target") or "").strip()
    experiment_id = str(
        plan.get("experiment_id")
        or target_ref
        or ("exp-001" if _fixture_like_envelope(envelope) else "experiment-unresolved")
    )
    command_allowlist = list(plan.get("command_allowlist") or [])
    command_run = str(command_allowlist[0] if command_allowlist else "fixture-mode:no-external-command")
    evidence_ids = [experiment_id, str(plan.get("objective") or "experiment-plan")]
    raw = dict(_load_json(_fixture_path("sample_autosci_raw_experiment_result.json")))
    supplied_result = _experiment_result_payload(envelope)
    if supplied_result and supplied_result.get("schema") != "experiment_result.v1":
        raw.update(supplied_result)

    log_lines = [
        f"execution_mode={execution_mode}",
        f"experiment_id={experiment_id}",
        f"command_run={command_run}",
    ]
    # Unapproved EXTERNAL execution is a safety condition, not merely incomplete
    # input, so it fails closed ahead of the plan-resolution check. Previously
    # the missing-plan branch below returned "inconclusive" first and this was
    # never reached, so an approved-external experiment with no approval at all
    # was reported as inconclusive rather than failed. With no upstream approval
    # node, this is the only remaining check on unapproved external execution.
    if execution_mode == "approved-external" and not _experiment_approval_satisfied(envelope):
        log_lines.append("blocked missing approval for external execution")
        artifact = _experiment_log_artifact(envelope, experiment_id, log_lines)
        return convert_experiment_result({
            "experiment_id": experiment_id,
            "outcome": "failed",
            "status": "failed",
            "metrics": [{"name": "approval_present", "value": False}],
            "evidence_ids": evidence_ids,
            "execution_mode": execution_mode,
            "command_run": command_run,
            "logs": log_lines,
            "artifacts": [artifact],
            "limitations": [
                "External experiment execution was blocked because approval is required and absent; no experiment command was executed.",
            ],
        }, envelope)
    if experiment_id == "experiment-unresolved" and not plan and not target_ref:
        log_lines.append("blocked missing experiment plan evidence")
        artifact = _experiment_log_artifact(envelope, experiment_id, log_lines)
        return convert_experiment_result({
            "experiment_id": experiment_id,
            "outcome": "inconclusive",
            "status": "inconclusive",
            "metrics": [{"name": "experiment_plan_resolved", "value": False}],
            "evidence_ids": ["experiment-plan:missing"],
            "execution_mode": execution_mode,
            "command_run": command_run,
            "logs": log_lines,
            "artifacts": [artifact],
            "limitations": ["Experiment execution was skipped because no experiment plan evidence was resolved; no default exp-001 fallback was used."],
        }, envelope)
    if execution_mode not in SAFE_EXPERIMENT_EXECUTION_MODES:
        log_lines.append(f"blocked unsupported execution mode: {execution_mode}")
        artifact = _experiment_log_artifact(envelope, experiment_id, log_lines)
        return convert_experiment_result({
            "experiment_id": experiment_id,
            "outcome": "failed",
            "status": "failed",
            "metrics": [{"name": "execution_allowed", "value": False}],
            "evidence_ids": evidence_ids,
            "execution_mode": execution_mode,
            "command_run": command_run,
            "logs": log_lines,
            "artifacts": [artifact],
            "limitations": [f"Unsupported execution mode: {execution_mode}"],
        }, envelope)

    approval_required = execution_mode in APPROVAL_REQUIRED_EXPERIMENT_MODES or bool(plan.get("approval_required"))
    if approval_required:
        contract = _approval_contract(
            envelope,
            "run_experiment",
            ["local_process_launch", "remote_execution", "result_collection", "wiki_state_mutation"],
        )
        rendered_policy_commands = [
            " ".join(_format_command(raw, {"experiment_id": experiment_id}))
            for raw in command_allowlist
            if _format_command(raw, {"experiment_id": experiment_id})
        ]
        experiment_side_effects = ["read_local", "write_artifact", "local_command", "wiki_mutation"]
        if execution_mode == "approved-external":
            experiment_side_effects.append("remote_execution")
        contract, policy_decision, policy_artifacts = _policy_prepare_auto_contract(
            envelope,
            "run_experiment",
            experiment_side_effects,
            contract,
            allowlist_payload={
                "declared_plan_commands": rendered_policy_commands,
                "limitations": [
                    "Policy sidecar records resolved plan commands for audit but does not itself allowlist experiment command execution.",
                    "Experiment command execution still requires concrete command allowlist evidence or a verified supplied runtime artifact.",
                ],
            },
        )
        contract_artifact = _write_approval_contract_sidecar(envelope, "run_experiment", contract)
        runtime_artifacts = _contract_existing_artifacts(contract, "runtime_evidence", "experiment_runtime_evidence_json")
        if not _experiment_approval_satisfied(envelope):
            log_lines.append("blocked missing approval for non-fixture execution")
            artifact = _experiment_log_artifact(envelope, experiment_id, log_lines)
            blocked_status = "inconclusive" if execution_mode == "human_approved" else "failed"
            semantic = _approval_semantic_runtime(contract, "run_experiment")
            evidence = convert_experiment_result({
                "experiment_id": experiment_id,
                "outcome": blocked_status,
                "status": blocked_status,
                "metrics": [{"name": "approval_present", "value": False}],
                "evidence_ids": evidence_ids,
                "execution_mode": execution_mode,
                "command_run": command_run,
                "logs": log_lines,
                "artifacts": [artifact, contract_artifact, *policy_artifacts, *runtime_artifacts],
                "limitations": [
                    "Experiment execution was blocked because approval is required and absent; no experiment command was executed.",
                    *_approval_contract_limitations(contract),
                ],
            }, envelope)
            evidence = _attach_experiment_run_runtime_audit_boundary(
                envelope,
                evidence,
                action="run_experiment",
                stage="run",
                experiment_id=experiment_id,
                contract=contract,
                semantic=semantic,
                result_collected=False,
            )
            evidence = _attach_policy_decision(evidence, policy_decision)
            if _side_effect_access_required(policy_decision):
                request_payload, request_artifact = _side_effect_access_request(
                    envelope,
                    "run_experiment",
                    "exp-run",
                    policy_decision,
                    requested_side_effects=experiment_side_effects,
                    required_inputs=[
                        "approval_ref for non-fixture experiment execution",
                        "command allowlist evidence",
                        "before/runtime/after artifacts proving the experiment command ran",
                    ],
                )
                evidence = _attach_side_effect_access_request(evidence, request_payload, request_artifact)
            return evidence
        contract, executor_result = _execute_experiment_if_approved(envelope, contract, plan)
        semantic = _approval_semantic_runtime(contract, "run_experiment")
        contract["semantic_runtime"] = semantic
        contract_artifact = _write_approval_contract_sidecar(envelope, "run_experiment", contract)
        runtime_artifacts = _contract_existing_artifacts(contract, "runtime_evidence", "experiment_runtime_evidence_json")
        detail = semantic.get("detail") if isinstance(semantic.get("detail"), dict) else {}
        if not semantic.get("verified"):
            log_lines.extend([
                f"approval_state={contract.get('approval_state')}",
                f"runtime_semantic_status={semantic.get('status')}",
                "blocked missing verified runtime evidence for approval-gated execution",
            ])
            artifact = _experiment_log_artifact(envelope, experiment_id, log_lines)
            evidence = convert_experiment_result({
                "experiment_id": experiment_id,
                "outcome": "inconclusive",
                "status": "inconclusive",
                "metrics": [
                    {"name": "approval_present", "value": True},
                    {"name": "runtime_evidence_verified", "value": False},
                ],
                "evidence_ids": evidence_ids,
                "execution_mode": execution_mode,
                "command_run": command_run,
                "logs": log_lines,
                "artifacts": [artifact, contract_artifact, *policy_artifacts, *runtime_artifacts],
                "limitations": [
                    "Experiment execution was not marked complete because approval/runtime evidence did not pass semantic verification.",
                    *_approval_contract_limitations(contract),
                    *(
                        [f"Auto-approved by gate policy mode `{policy_decision.get('mode')}`; runtime verification still failed or remained incomplete."]
                        if policy_decision.get("execute_side_effects")
                        else []
                    ),
                ],
            }, envelope)
            evidence = _attach_experiment_run_runtime_audit_boundary(
                envelope,
                evidence,
                action="run_experiment",
                stage="run",
                experiment_id=experiment_id,
                contract=contract,
                semantic=semantic,
                result_collected=False,
            )
            evidence = _attach_policy_decision(evidence, policy_decision)
            if _side_effect_access_required(policy_decision):
                request_payload, request_artifact = _side_effect_access_request(
                    envelope,
                    "run_experiment",
                    "exp-run",
                    policy_decision,
                    requested_side_effects=experiment_side_effects,
                    required_inputs=[
                        "verified runtime evidence for approved experiment execution",
                        "result collection artifact",
                        "wiki mutation proof for completed experiment state",
                    ],
                )
                evidence = _attach_side_effect_access_request(evidence, request_payload, request_artifact)
            return evidence
        if executor_result.get("executed"):
            log_lines.append(f"experiment_executor_result={executor_result.get('result_collected')}")
            log_lines.append(f"executor_exit_code={executor_result.get('exit_code')}")
            if executor_result.get("result_path"):
                log_lines.append(f"executor_result_path={executor_result.get('result_path')}")
        runtime_metrics = detail.get("metrics") if isinstance(detail.get("metrics"), list) else []
        metrics = runtime_metrics or [{"name": "runtime_evidence_verified", "value": True}]
        outcome = str(detail.get("outcome") or "supports")
        runtime_evidence_ids = [str(item) for item in detail.get("evidence_ids") or [] if str(item).strip()]
        completed_evidence_ids = _unique_strings([*evidence_ids, *runtime_evidence_ids])
        command_run = str(detail.get("command_run") or command_run)
        runtime_logs = [str(item) for item in detail.get("logs") or [] if str(item).strip()]
        result_path = executor_result.get("result_path")
        if result_path:
            result_payload = _load_json(_resolve_harness_path(result_path))
            result_logs = (result_payload.get("outputs") or {}).get("result", {}).get("logs")
            if isinstance(result_logs, list):
                for item in result_logs:
                    text = str(item).strip()
                    if text and text not in runtime_logs:
                        runtime_logs.append(text)
        runtime_artifacts.extend(_contract_existing_artifacts(contract, "after_artifacts", "run_experiment_result_json"))
        for key, artifact_type in (
            ("stdout_path", "executor_stdout"),
            ("stderr_path", "executor_stderr"),
        ):
            raw_path = str(executor_result.get(key) or "").strip()
            if raw_path:
                artifact_path = _resolve_harness_path(raw_path)
                if artifact_path.exists():
                    runtime_artifacts.append({"type": artifact_type, "path": _rel(artifact_path)})
        runtime_artifacts.extend(
            artifact
            for artifact in executor_result.get("report_artifacts") or []
            if isinstance(artifact, dict)
            and str(artifact.get("type") or "").strip()
            and str(artifact.get("path") or "").strip()
        )
        logs = [
            *log_lines,
            f"approval_state={contract.get('approval_state')}",
            "approved runtime evidence verified",
            *runtime_logs,
        ]
        artifact = _experiment_log_artifact(envelope, experiment_id, logs)
        wiki_artifacts = _write_experiment_state_mutation(
            envelope,
            experiment_id=experiment_id,
            outcome=outcome,
            evidence_ids=completed_evidence_ids,
            metrics=metrics,
        )
        evidence = convert_experiment_result({
            "experiment_id": experiment_id,
            "outcome": outcome,
            "status": "completed",
            "metrics": metrics,
            "evidence_ids": completed_evidence_ids,
            "execution_mode": execution_mode,
            "command_run": command_run,
            "logs": logs,
            "artifacts": [artifact, contract_artifact, *policy_artifacts, *runtime_artifacts, *wiki_artifacts],
            "limitations": [
                "Experiment result was completed from approved runtime evidence and mutated wiki state.",
                *(
                    [f"Auto-approved by gate policy mode `{policy_decision.get('mode')}`; no human approval was requested."]
                    if policy_decision.get("execute_side_effects")
                    else []
                ),
            ],
        }, envelope)
        evidence = _attach_experiment_run_runtime_audit_boundary(
            envelope,
            evidence,
            action="run_experiment",
            stage="run",
            experiment_id=experiment_id,
            contract=contract,
            semantic=semantic,
            result_collected=True,
        )
        # The consolidated POC handoff package proves a product-executed run,
        # including its execution lease.  A caller may instead supply already
        # completed runtime evidence; that path is valid, but it has no local
        # executor lease and must not fabricate one merely to build a package.
        executed_argv = _normalize_command(
            [str(item) for item in executor_result.get("command") or []]
        )
        planned_argv = _normalize_command(
            [str(item) for item in plan.get("command_argv") or []]
        )
        if (
            executor_result.get("executed") is True
            and planned_argv
            and executed_argv == planned_argv
        ):
            evidence.setdefault("artifacts", []).append(
                _write_experiment_poc_handoff_package(
                    envelope,
                    experiment_id=experiment_id,
                    plan=plan,
                    evidence=evidence,
                    contract=contract,
                    semantic=semantic,
                    executor_result=executor_result,
                )
            )
        return _attach_policy_decision(evidence, policy_decision)

    raw["experiment_id"] = str(raw.get("experiment_id") or experiment_id)
    raw["execution_mode"] = execution_mode
    raw["command_run"] = command_run
    raw["logs"] = [*log_lines, "fixture result collected"]
    raw["evidence_ids"] = list(raw.get("evidence_ids") or evidence_ids)
    raw["artifacts"] = [_experiment_log_artifact(envelope, experiment_id, raw["logs"])]
    raw["limitations"] = list(raw.get("limitations") or ["Fixture result is deterministic and not a real benchmark run."])
    return convert_experiment_result(raw, envelope)


def _pilot_run_final_acceptance_boundary(
    *,
    experiment_id: str,
    contract: dict[str, Any],
    semantic: dict[str, Any],
    result_collected: bool,
) -> dict[str, Any]:
    runtime_ready = (
        contract.get("execution_verified") is True
        and semantic.get("verified") is True
        and result_collected
    )
    limitations: list[str] = []
    if contract.get("execution_verified") is not True:
        limitations.append("Pilot runtime acceptance requires a verified approval contract with runtime and after-artifact evidence.")
    if semantic.get("verified") is not True:
        limitations.append("Pilot runtime acceptance requires semantic runtime verification to pass.")
    if not result_collected:
        limitations.append("Pilot runtime acceptance requires collected pilot result evidence.")
    if not limitations:
        limitations.append("Pilot runtime is ready; `/exp-pilot-eval` owns the verdict and any approved wiki update.")
    return {
        "schema": "autosci_pilot_experiment_final_acceptance_boundary.v1",
        "stage": "pilot_run",
        "experiment_id": experiment_id,
        "status": "pilot_runtime_ready" if runtime_ready else "pilot_runtime_incomplete",
        "pilot_runtime_ready": runtime_ready,
        "pilot_verdict_ready": False,
        "writeback_completed": False,
        "final_pilot_acceptance_ready": False,
        "approval_contract_verified": contract.get("execution_verified") is True,
        "approval_state": str(contract.get("approval_state") or "missing"),
        "runtime_semantic_verified": semantic.get("verified") is True,
        "runtime_semantic_status": str(semantic.get("status") or "missing"),
        "result_collected": result_collected,
        "limitations": limitations,
    }


def _attach_pilot_run_final_acceptance_boundary(
    envelope: dict[str, Any],
    evidence: dict[str, Any],
    *,
    experiment_id: str,
    contract: dict[str, Any],
    semantic: dict[str, Any],
    result_collected: bool,
) -> dict[str, Any]:
    boundary = _pilot_run_final_acceptance_boundary(
        experiment_id=experiment_id,
        contract=contract,
        semantic=semantic,
        result_collected=result_collected,
    )
    outputs = evidence.setdefault("outputs", {})
    if isinstance(outputs.get("result"), dict):
        outputs["result"]["pilot_final_acceptance_boundary"] = boundary
        outputs["result"]["final_pilot_acceptance_ready"] = False
    outputs["pilot_final_acceptance_boundary"] = boundary
    boundary_path = _write_json_sidecar(
        _output_dir(envelope, "run_pilot_experiment") / "pilot_final_acceptance_boundary.json",
        boundary,
    )
    evidence.setdefault("artifacts", []).append(
        {"type": "pilot_run_final_acceptance_boundary_json", "path": boundary_path}
    )
    evidence.setdefault("limitations", []).extend(str(item) for item in boundary.get("limitations") or [])
    return evidence


def _pilot_eval_final_acceptance_boundary(
    envelope: dict[str, Any],
    verdict_evidence: dict[str, Any],
    *,
    writeback_path: str | None,
) -> dict[str, Any]:
    outputs = verdict_evidence.get("outputs") if isinstance(verdict_evidence.get("outputs"), dict) else {}
    verdicts = outputs.get("verdicts") if isinstance(outputs.get("verdicts"), list) else []
    verdict = dict(verdicts[0]) if verdicts and isinstance(verdicts[0], dict) else {}
    claim_id = str(verdict.get("claim_id") or "pilot-claim")
    evidence_ids = [str(item) for item in verdict.get("evidence_ids") or [] if str(item).strip()]
    runtime_evidence_linked = any(item != claim_id for item in evidence_ids)
    pilot_verdict_ready = str(verdict.get("verdict") or "inconclusive") != "inconclusive" and verdict_evidence.get("status") == "completed"
    writeback = _claim_verdict_writeback_status(envelope, writeback_path)
    writeback_completed = writeback.get("status") == "completed" and writeback.get("applied") is True
    final_ready = pilot_verdict_ready and runtime_evidence_linked and writeback_completed
    limitations: list[str] = []
    if not pilot_verdict_ready:
        limitations.append("Final pilot acceptance requires a non-inconclusive pilot verdict.")
    if not runtime_evidence_linked:
        limitations.append("Final pilot acceptance requires linked pilot result/runtime evidence.")
    if not writeback_completed:
        limitations.append("Final pilot acceptance requires completed approved wiki writeback.")
    if not limitations:
        limitations.append("Final pilot acceptance passed with runtime evidence, pilot verdict, and approved wiki writeback.")
    return {
        "schema": "autosci_pilot_experiment_final_acceptance_boundary.v1",
        "stage": "pilot_eval",
        "claim_id": claim_id,
        "status": "final_pilot_acceptance_ready" if final_ready else "pilot_acceptance_incomplete",
        "pilot_runtime_ready": runtime_evidence_linked,
        "pilot_verdict_ready": pilot_verdict_ready,
        "writeback_completed": writeback_completed,
        "writeback_status": writeback,
        "final_pilot_acceptance_ready": final_ready,
        "evidence_ids": _unique_strings(evidence_ids),
        "limitations": limitations,
    }


def _attach_pilot_eval_final_acceptance_boundary(
    envelope: dict[str, Any],
    verdict_evidence: dict[str, Any],
    *,
    writeback_path: str | None,
) -> dict[str, Any]:
    boundary = _pilot_eval_final_acceptance_boundary(
        envelope,
        verdict_evidence,
        writeback_path=writeback_path,
    )
    outputs = verdict_evidence.setdefault("outputs", {})
    verdicts = outputs.get("verdicts") if isinstance(outputs.get("verdicts"), list) else []
    if verdicts and isinstance(verdicts[0], dict):
        verdicts[0]["pilot_final_acceptance_boundary"] = boundary
        verdicts[0]["final_pilot_acceptance_ready"] = boundary.get("final_pilot_acceptance_ready") is True
    outputs["pilot_final_acceptance_boundary"] = boundary
    boundary_path = _write_json_sidecar(
        _output_dir(envelope, "evaluate_pilot_result") / "pilot_final_acceptance_boundary.json",
        boundary,
    )
    verdict_evidence.setdefault("artifacts", []).append(
        {"type": "pilot_eval_final_acceptance_boundary_json", "path": boundary_path}
    )
    verdict_evidence.setdefault("limitations", []).extend(str(item) for item in boundary.get("limitations") or [])
    return verdict_evidence


def _action_run_pilot_experiment(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    target = str(inputs.get("target") or inputs.get("experiment_id") or "pilot-unresolved")
    experiment_id = target if target.startswith("exp") or target.startswith("pilot") else f"pilot-{_slug(target)}"
    contract = _approval_contract(
        envelope,
        "run_pilot_experiment",
        ["local_process_launch", "remote_execution", "result_collection"],
    )
    contract, policy_decision, policy_artifacts = _policy_prepare_auto_contract_if_needed(
        envelope,
        "run_pilot_experiment",
        ["read_local", "write_artifact", "local_command"],
        contract,
        allowlist_payload={
            "native_surface": "$exp-pilot-run",
            "allowed_side_effects": ["local_process_launch", "result_collection"],
            "limitations": [
                "Policy approval applies only to local allowlisted pilot command execution.",
                "Remote pilot launch still requires a remote/provider gate opt-in and concrete command allowlist evidence.",
            ],
        },
    )
    inputs = dict(envelope.get("inputs") or {})
    executor_result: dict[str, Any] = {"executed": False, "reason": "execute_approved_side_effect=false"}
    if inputs.get("execute_approved_side_effect"):
        contract, executor_result = _execute_experiment_if_approved(
            envelope,
            contract,
            {"experiment_id": experiment_id},
            action="run_pilot_experiment",
            stage="pilot_run",
            result_path_key="pilot_result_path",
            result_json_artifact_type="pilot_run_result_json",
            result_artifact_type="pilot_run_result",
            blocked_evidence_id="pilot-runtime:blocked",
            default_evidence_prefix="pilot-runtime",
            runner_operator_id="autosci-experiment-run-worker",
            executor_label="Pilot experiment",
        )
    semantic = _approval_semantic_runtime(contract, "run_pilot_experiment")
    contract["semantic_runtime"] = semantic
    contract_artifact = _write_approval_contract_sidecar(envelope, "run_pilot_experiment", contract)
    semantic_detail = semantic.get("detail") if isinstance(semantic.get("detail"), dict) else {}
    runtime_metrics = semantic_detail.get("metrics") if isinstance(semantic_detail.get("metrics"), list) else []
    metrics = runtime_metrics or [
        {"name": "pilot_execution_started", "value": False},
        {"name": "approval_contract_verified", "value": bool(contract.get("execution_verified"))},
        {"name": "runtime_semantic_verified", "value": bool(semantic.get("verified"))},
    ]
    outcome = str(semantic_detail.get("outcome") or "inconclusive")
    status = "completed" if semantic.get("verified") else "inconclusive"
    executor_executed = bool(executor_result.get("executed"))
    limitations = [
        "Pilot run is diagnostics-only unless approved runtime evidence is supplied.",
        "This bridge did not launch local or remote experiment commands.",
    ]
    if semantic.get("verified"):
        if executor_executed:
            limitations = [
                "Pilot runtime executed through an approved allowlisted command and was verified from runtime evidence.",
                "`/exp-pilot-eval` owns verdict assessment and any approved wiki update.",
            ]
        else:
            limitations = [
                "Pilot runtime was verified from supplied approval-gated evidence; this bridge did not execute the command.",
            ]
    else:
        limitations.extend(_approval_contract_limitations(contract))
    runtime_artifacts = _contract_existing_artifacts(contract, "runtime_evidence", "pilot_runtime_evidence_json")
    after_artifacts = _contract_existing_artifacts(contract, "after_artifacts", "pilot_runtime_after_artifact")
    executor_artifacts: list[dict[str, str]] = []
    raw_result_path = executor_result.get("result_path")
    if raw_result_path:
        result_path = raw_result_path if isinstance(raw_result_path, Path) else _resolve_harness_path(str(raw_result_path))
        if result_path.exists():
            executor_artifacts.append({"type": "pilot_run_result_json", "path": _rel(result_path)})
    for key, artifact_type in (
        ("stdout_path", "executor_stdout"),
        ("stderr_path", "executor_stderr"),
    ):
        raw_path = str(executor_result.get(key) or "").strip()
        if raw_path:
            artifact_path = _resolve_harness_path(raw_path)
            if artifact_path.exists():
                executor_artifacts.append({"type": artifact_type, "path": _rel(artifact_path)})
    executor_artifacts.extend(
        artifact
        for artifact in executor_result.get("report_artifacts") or []
        if isinstance(artifact, dict)
        and str(artifact.get("type") or "").strip()
        and str(artifact.get("path") or "").strip()
    )
    runtime_evidence_ids = [str(item) for item in semantic_detail.get("evidence_ids") or [] if str(item).strip()]
    evidence_ids = _unique_strings([f"pilot-run:{_slug(target)}", *runtime_evidence_ids])
    command_run = str(
        semantic_detail.get("command_run")
        or (" ".join(str(item) for item in executor_result.get("command") or []) if executor_result.get("command") else "")
        or "approval-gated:no-external-command"
    )
    runtime_logs = [str(item) for item in semantic_detail.get("logs") or [] if str(item).strip()]
    if executor_executed:
        runtime_logs.extend([
            f"pilot_executor_exit_code={executor_result.get('exit_code')}",
            f"pilot_executor_result_path={executor_result.get('result_path') or 'N/A'}",
        ])
    evidence = convert_experiment_result({
        "experiment_id": experiment_id,
        "outcome": outcome,
        "status": status,
        "metrics": metrics,
        "evidence_ids": evidence_ids,
        "execution_mode": str(inputs.get("execution_mode") or "approval_gated_pilot"),
        "command_run": command_run,
        "logs": [
            "Pilot execution ran through approved executor." if executor_executed else "Pilot execution was not started by this bridge.",
            "Approved runtime evidence was verified." if semantic.get("verified") else "Code execution, local process launch, remote execution, and result collection require approval.",
            f"approval_state={contract.get('approval_state')}",
            f"runtime_semantic_status={semantic.get('status')}",
            *runtime_logs,
        ],
        "artifacts": [contract_artifact, *policy_artifacts, *runtime_artifacts, *after_artifacts, *executor_artifacts],
        "limitations": limitations,
    }, envelope)
    evidence = _attach_pilot_run_final_acceptance_boundary(
        envelope,
        evidence,
        experiment_id=experiment_id,
        contract=contract,
        semantic=semantic,
        result_collected=bool(semantic_detail.get("result_collected")),
    )
    if semantic.get("verified"):
        evidence_payload_path = _configured_output_path(
            envelope,
            "evidence_payload_path",
            _output_dir(envelope, "run_pilot_experiment") / "run_pilot_experiment.evidence.json",
            legacy_key="evidence_path",
            legacy_suffix=".json",
        )
        evidence.setdefault("artifacts", []).extend(
            _write_approved_mutation_runtime_proof_manifests(
                envelope,
                action="run_pilot_experiment",
                native_skill="exp-pilot-run",
                evidence_path=evidence_payload_path,
                applied=True,
                contract=contract,
                contract_artifact=contract_artifact,
                source_refs=[],
                mutation_refs=[
                    str(artifact.get("path") or "")
                    for artifact in evidence.get("artifacts") or []
                    if isinstance(artifact, dict)
                ],
                include_wiki_mutation=False,
                source_label="approved_pilot_runtime",
                artifact_kind="pilot_runtime_execution",
                include_provider_source=False,
            )
        )
    return _attach_policy_decision_if_present(evidence, policy_decision)


def _action_monitor_experiment(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    plan = _experiment_plan_from_evidence(envelope)
    result_payload = _experiment_result_payload(envelope)
    wiki_state, wiki_state_artifact = _wiki_state_resolver_artifact(envelope, "monitor_experiment")
    wiki_artifacts = [wiki_state_artifact] if wiki_state_artifact else []
    target_ref = str(inputs.get("target") or inputs.get("experiment_id") or "").strip()
    resolved_experiment_id = _resolved_wiki_experiment_id(wiki_state)
    experiment_id = str(
        plan.get("experiment_id")
        or resolved_experiment_id
        or target_ref
        or ("exp-001" if _fixture_like_envelope(envelope) else "experiment-unresolved")
    )
    collect_requested = bool(inputs.get("collect"))
    session, session_artifact = _experiment_session_from_registry(envelope, experiment_id)
    remote_check_requested = bool(inputs.get("remote_check_command") or inputs.get("remote_run_dir"))
    if result_payload and result_payload.get("schema") == "experiment_result.v1":
        result = ((result_payload.get("outputs") or {}).get("result") or {})
        experiment_id = str(result.get("experiment_id") or experiment_id)
        outcome = str(result.get("outcome") or "inconclusive")
        state = "failed" if outcome == "failed" or result_payload.get("status") == "failed" else "completed"
        evidence_ids = [str(result_payload.get("task_id") or experiment_id), *list(result.get("evidence_ids") or [])]
        return convert_experiment_status({
            "experiment_id": experiment_id,
            "state": state,
            "observations": [f"Observed experiment result outcome: {outcome}."],
            "next_actions": ["Collect result evidence for claim verification." if state == "completed" else "Inspect failed run logs before retry."],
            "evidence_ids": evidence_ids,
            "artifacts": wiki_artifacts,
            "limitations": ["Status is derived from local result evidence only.", *_wiki_state_limitations(wiki_state)],
        }, envelope)
    if result_payload:
        experiment_id = str(result_payload.get("experiment_id") or experiment_id)
        outcome = str(result_payload.get("outcome") or "inconclusive")
        state = "failed" if outcome == "failed" else "completed"
        return convert_experiment_status({
            "experiment_id": experiment_id,
            "state": state,
            "observations": [f"Observed raw fixture result outcome: {outcome}."],
            "next_actions": ["Convert raw result to experiment_result.v1 evidence."],
            "evidence_ids": list(result_payload.get("evidence_ids") or [experiment_id]),
            "artifacts": wiki_artifacts,
            "limitations": [
                "Status was derived from a raw fixture result, not a persisted result evidence artifact.",
                *_wiki_state_limitations(wiki_state),
            ],
        }, envelope)
    if remote_check_requested and not collect_requested and not inputs.get("runtime_evidence"):
        contract = _approval_contract(
            envelope,
            "monitor_experiment",
            ["remote_status_poll"],
        )
        contract, policy_decision, policy_artifacts = _policy_prepare_auto_contract_if_needed(
            envelope,
            "monitor_experiment",
            ["read_local", "write_artifact", "local_command", "remote_execution"],
            contract,
            allowlist_payload={
                "native_surface": "$exp-status",
                "allowed_side_effects": ["remote_status_poll"],
                "limitations": [
                    "Policy approval applies only to an allowlisted remote status check command.",
                    "Remote execution requires the configured gate mode plus explicit remote/provider opt-in.",
                ],
            },
        )
        inputs = dict(envelope.get("inputs") or {})
        contract, remote_check = _execute_remote_check_if_approved(
            envelope,
            contract,
            experiment_id=experiment_id,
            session=session,
        )
        contract_artifact = _write_approval_contract_sidecar(envelope, "monitor_experiment", contract)
        remote_artifacts = _contract_existing_artifacts(contract, "runtime_evidence", "remote_status_runtime_evidence_json")
        for key, artifact_type in (
            ("stdout_path", "executor_stdout"),
            ("stderr_path", "executor_stderr"),
        ):
            raw_path = str(remote_check.get(key) or "").strip()
            if raw_path:
                artifact_path = _resolve_harness_path(raw_path)
                if artifact_path.exists():
                    remote_artifacts.append({"type": artifact_type, "path": _rel(artifact_path)})
        remote_artifacts.extend(
            {"type": "remote_status_file", "path": str(path)}
            for path in remote_check.get("evidence_paths") or []
            if str(path).strip()
        )
        state = str(remote_check.get("state") or "unknown")
        status = "completed" if state != "unknown" and remote_check.get("status") == "completed" else "inconclusive"
        poll_boundary = remote_check.get("remote_poll_boundary") if isinstance(remote_check.get("remote_poll_boundary"), dict) else {}
        remote_executed = bool(remote_check.get("executed"))
        observations = [
            f"Approved remote status check for `{experiment_id}` returned state `{state}`."
            if remote_executed
            else f"Remote status check for `{experiment_id}` did not execute: {remote_check.get('reason') or 'not approved'}.",
            *[str(item) for item in remote_check.get("observations") or [] if str(item).strip()],
        ]
        if poll_boundary:
            observations.append(f"remote_poll_boundary_status={poll_boundary.get('status') or 'unknown'}")
        if remote_check.get("reason"):
            observations.append(f"remote_check_reason={remote_check.get('reason')}")
        evidence_payload_path = _configured_output_path(
            envelope,
            "evidence_payload_path",
            _output_dir(envelope, "monitor_experiment") / "experiment_status.json",
            legacy_key="evidence_path",
            legacy_suffix=".json",
        )
        runtime_proof_artifact = _write_remote_status_runtime_proof_manifest(
            envelope,
            evidence_path=evidence_payload_path,
            remote_check=remote_check,
            contract_artifact=contract_artifact,
        )
        if runtime_proof_artifact is not None:
            remote_artifacts.append(runtime_proof_artifact)
        next_actions = (
            ["Use linked run/result evidence for claim verification and reporting."]
            if state == "completed"
            else ["Continue monitoring or run approved collect when result artifacts are ready."]
            if state == "running"
            else ["Inspect remote check diagnostics before treating the experiment as running or complete."]
        )
        evidence = convert_experiment_status({
            "experiment_id": experiment_id,
            "state": state,
            "observations": observations,
            "next_actions": next_actions,
            "evidence_ids": _unique_strings([experiment_id, *[str(item) for item in remote_check.get("evidence_paths") or []]]),
            "status": status,
            "artifacts": [
                *wiki_artifacts,
                contract_artifact,
                *policy_artifacts,
                *remote_artifacts,
            ],
            "limitations": [
                "Experiment status was read by an approved remote status check command; no result collection was performed."
                if remote_executed
                else "Remote status check was requested but did not execute because approval or gate policy did not authorize it.",
                *[str(item) for item in poll_boundary.get("limitations", []) if str(item).strip()],
                *_wiki_state_limitations(wiki_state),
            ],
        }, envelope)
        return _attach_policy_decision_if_present(evidence, policy_decision)
    wiki_experiment = _resolved_wiki_experiment(wiki_state)
    if wiki_experiment and not collect_requested and not inputs.get("runtime_evidence"):
        experiment_id = str(wiki_experiment.get("experiment_id") or experiment_id)
        raw_status = str(wiki_experiment.get("status") or "")
        state = _experiment_state_from_wiki_status(raw_status)
        outcome = str(wiki_experiment.get("outcome") or "").strip()
        experiment_path = str(wiki_experiment.get("path") or "").strip()
        run_log_path = str(wiki_experiment.get("run_log_path") or "").strip()
        evidence_ids = _unique_strings(
            [
                experiment_id,
                experiment_path,
                run_log_path if wiki_experiment.get("run_log_exists") else "",
                *[str(item) for item in wiki_experiment.get("evidence_ids") or [] if str(item).strip()],
            ]
        )
        experiment_artifacts = list(wiki_artifacts)
        if experiment_path:
            experiment_artifacts.append({"type": "wiki_experiment_markdown", "path": experiment_path})
        if run_log_path and wiki_experiment.get("run_log_exists"):
            experiment_artifacts.append({"type": "wiki_experiment_run_log", "path": run_log_path})
        observations = [f"Resolved wiki experiment `{experiment_id}` with status `{raw_status or 'unknown'}`."]
        if outcome:
            observations.append(f"Wiki experiment outcome: {outcome}.")
        if run_log_path:
            observations.append(
                "Wiki experiment run log exists." if wiki_experiment.get("run_log_exists") else "Wiki experiment run log path is recorded but missing."
            )
        next_actions = (
            ["Use linked run/result evidence for claim verification and reporting."]
            if state == "completed"
            else ["Supply experiment_result.v1 or approved runtime evidence before treating results as collected."]
        )
        status = "completed" if state != "unknown" else "inconclusive"
        limitations = [
            "Experiment status was read from wiki experiment state; no command was executed and no remote results were collected.",
            *_wiki_state_limitations(wiki_state),
        ]
        if not evidence_ids:
            evidence_ids = [experiment_id or "wiki-experiment:missing-evidence"]
        if session and state in {"planned", "running", "unknown", "blocked"}:
            return convert_experiment_status(
                _session_status_raw(
                    experiment_id=experiment_id,
                    session=session,
                    session_artifact=session_artifact,
                    wiki_artifacts=experiment_artifacts,
                    wiki_state=wiki_state,
                ),
                envelope,
            )
        return convert_experiment_status({
            "experiment_id": experiment_id,
            "state": state,
            "observations": observations,
            "next_actions": next_actions,
            "evidence_ids": evidence_ids,
            "status": status,
            "artifacts": experiment_artifacts,
            "limitations": limitations,
        }, envelope)
    if session and not collect_requested and not inputs.get("runtime_evidence"):
        return convert_experiment_status(
            _session_status_raw(
                experiment_id=experiment_id,
                session=session,
                session_artifact=session_artifact,
                wiki_artifacts=wiki_artifacts,
                wiki_state=wiki_state,
            ),
            envelope,
        )
    if collect_requested or inputs.get("runtime_evidence"):
        contract = _approval_contract(
            envelope,
            "monitor_experiment",
            ["result_collection", "status_mutation", "wiki_state_mutation"],
        )
        policy_decision: dict[str, Any] = {}
        policy_artifacts: list[dict[str, str]] = []
        collector_result: dict[str, Any] = {"executed": False}
        if collect_requested:
            contract, policy_decision, policy_artifacts = _policy_prepare_auto_contract_if_needed(
                envelope,
                "monitor_experiment",
                ["read_local", "write_artifact", "local_command", "remote_execution", "wiki_mutation"],
                contract,
                allowlist_payload={
                    "native_surface": "$exp-status/$exp-run --collect",
                    "allowed_side_effects": ["result_collection", "status_mutation", "wiki_state_mutation"],
                    "limitations": [
                        "Policy approval applies only to allowlisted result collection and local wiki state mutation.",
                        "Remote/provider result collection requires the configured gate mode plus explicit remote/provider opt-in.",
                    ],
                },
            )
            inputs = dict(envelope.get("inputs") or {})
            contract, collector_result = _execute_monitor_collect_if_approved(envelope, contract, plan, experiment_id)
        semantic = _approval_semantic_runtime(contract, "run_experiment")
        contract["semantic_runtime"] = semantic
        contract_artifact = _write_approval_contract_sidecar(envelope, "monitor_experiment", contract)
        runtime_artifacts = [
            *policy_artifacts,
            *_contract_existing_artifacts(contract, "runtime_evidence", "experiment_runtime_evidence_json"),
        ]
        if collector_result.get("executed"):
            for key, artifact_type in (
                ("stdout_path", "executor_stdout"),
                ("stderr_path", "executor_stderr"),
            ):
                raw_path = str(collector_result.get(key) or "").strip()
                if raw_path:
                    artifact_path = _resolve_harness_path(raw_path)
                    if artifact_path.exists():
                        runtime_artifacts.append({"type": artifact_type, "path": _rel(artifact_path)})
            runtime_artifacts.extend(
                {"type": "remote_collected_file", "path": str(path)}
                for path in collector_result.get("collected_files") or []
                if str(path).strip()
            )
            if collector_result.get("collection_ledger_path"):
                runtime_artifacts.append({"type": "collection_ledger_json", "path": str(collector_result["collection_ledger_path"])})
            runtime_artifacts.extend(
                artifact
                for artifact in collector_result.get("report_artifacts") or []
                if isinstance(artifact, dict)
                and str(artifact.get("type") or "").strip()
                and str(artifact.get("path") or "").strip()
            )
        detail = semantic.get("detail") if isinstance(semantic.get("detail"), dict) else {}
        runtime_evidence_ids = [str(item) for item in detail.get("evidence_ids") or [] if str(item).strip()]
        evidence_ids = _unique_strings([experiment_id, *runtime_evidence_ids])
        if semantic.get("verified"):
            outcome = str(detail.get("outcome") or "supports")
            state = "failed" if outcome == "failed" else "completed"
            metrics = detail.get("metrics") if isinstance(detail.get("metrics"), list) else []
            observations = [
                f"Approved runtime evidence verified experiment outcome: {outcome}.",
                f"approval_state={contract.get('approval_state')}",
                f"runtime_semantic_status={semantic.get('status')}",
            ]
            if collector_result.get("executed"):
                observations.extend([
                    f"collect_executor_result={collector_result.get('result_collected')}",
                    f"collector_exit_code={collector_result.get('exit_code')}",
                    f"collection_duplicate={collector_result.get('collection_duplicate')}",
                ])
                boundary = collector_result.get("remote_collection_boundary")
                if isinstance(boundary, dict):
                    observations.append(f"remote_collection_boundary_status={boundary.get('status') or 'unknown'}")
            if collector_result.get("collection_duplicate"):
                wiki_update_artifacts = _existing_experiment_state_artifacts(envelope, experiment_id)
                if not wiki_update_artifacts:
                    wiki_update_artifacts = _write_experiment_state_mutation(
                        envelope,
                        experiment_id=experiment_id,
                        outcome=outcome,
                        evidence_ids=evidence_ids,
                        metrics=metrics,
                    )
            else:
                wiki_update_artifacts = _write_experiment_state_mutation(
                    envelope,
                    experiment_id=experiment_id,
                    outcome=outcome,
                    evidence_ids=evidence_ids,
                    metrics=metrics,
                )
            evidence = convert_experiment_status({
                "experiment_id": experiment_id,
                "state": state,
                "observations": observations,
                "next_actions": ["Use collected result evidence for claim verification and paper reporting."],
                "evidence_ids": evidence_ids,
                "artifacts": [*wiki_artifacts, contract_artifact, *runtime_artifacts, *wiki_update_artifacts],
                "limitations": [
                    "Experiment status was completed from approved runtime evidence; this bridge verified evidence and mutated wiki state but did not pull remote results directly.",
                    *[
                        str(item)
                        for item in (collector_result.get("remote_collection_boundary") or {}).get("limitations", [])
                        if str(item).strip()
                    ],
                    *_wiki_state_limitations(wiki_state),
                ],
            }, envelope)
            evidence = _attach_experiment_run_runtime_audit_boundary(
                envelope,
                evidence,
                action="monitor_experiment",
                stage="collect",
                experiment_id=experiment_id,
                contract=contract,
                semantic=semantic,
                result_collected=bool(detail.get("result_collected") or collector_result.get("result_collected")),
                collection_boundary=collector_result.get("remote_collection_boundary")
                if isinstance(collector_result.get("remote_collection_boundary"), dict)
                else None,
            )
            return _attach_policy_decision_if_present(evidence, policy_decision)
        if inputs.get("runtime_evidence") or inputs.get("approval_ref") or collect_requested:
            evidence = convert_experiment_status({
                "experiment_id": experiment_id,
                "state": "unknown",
                "observations": [
                    *(
                        ["Collect mode was requested, but no local experiment_result.v1 evidence was supplied."]
                        if collect_requested
                        else []
                    ),
                    "Runtime evidence was supplied but did not pass semantic verification.",
                    f"approval_state={contract.get('approval_state')}",
                    f"runtime_semantic_status={semantic.get('status')}",
                ],
                "next_actions": ["Supply verified runtime evidence with exit_code=0 and collected result metrics."],
                "evidence_ids": evidence_ids or [experiment_id, "runtime-evidence:unverified"],
                "status": "inconclusive",
                "artifacts": [*wiki_artifacts, contract_artifact, *runtime_artifacts],
                "limitations": [
                    "Collect/status remains inconclusive because approved runtime evidence did not pass semantic verification.",
                    *_approval_contract_limitations(contract),
                    *_wiki_state_limitations(wiki_state),
                ],
            }, envelope)
            evidence = _attach_experiment_run_runtime_audit_boundary(
                envelope,
                evidence,
                action="monitor_experiment",
                stage="collect",
                experiment_id=experiment_id,
                contract=contract,
                semantic=semantic,
                result_collected=False,
                collection_boundary=collector_result.get("remote_collection_boundary")
                if isinstance(collector_result.get("remote_collection_boundary"), dict)
                else None,
            )
            return _attach_policy_decision_if_present(evidence, policy_decision)
    observations = []
    if target_ref:
        observations.append(f"Status target requested: {target_ref}.")
    if collect_requested:
        observations.append("Collect mode was requested, but no local experiment_result.v1 evidence was supplied.")
    observations.append("No experiment result evidence was available to monitor.")
    next_actions = [
        "Provide experiment_result_evidence from the run artifact directory.",
        "Use an approved remote pull-results path before marking collect as complete.",
    ]
    limitations = ["Experiment status is unknown because result evidence is missing; no default exp-001 fallback was used."]
    if collect_requested:
        limitations.append("Collect mode is diagnostics-only without approved runtime artifact retrieval.")
    limitations.extend(_wiki_state_limitations(wiki_state))
    evidence = convert_experiment_status({
        "experiment_id": experiment_id,
        "state": "unknown",
        "observations": observations,
        "next_actions": next_actions,
        "evidence_ids": [
            experiment_id if experiment_id != "experiment-unresolved" else "experiment-result:missing",
            "experiment-result:missing",
        ],
        "status": "inconclusive",
        "artifacts": wiki_artifacts,
        "limitations": limitations,
    }, envelope)
    if collect_requested:
        return _attach_experiment_run_runtime_audit_boundary(
            envelope,
            evidence,
            action="monitor_experiment",
            stage="collect",
            experiment_id=experiment_id,
            contract=None,
            semantic=None,
            result_collected=False,
        )
    return evidence


def _action_evaluate_pilot_result(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    claim_id = str(inputs.get("claim_id") or inputs.get("target") or "pilot-claim-unresolved")
    result_payload = _experiment_result_payload(envelope)
    artifacts: list[dict[str, str]] = []
    outcome = "inconclusive"
    basis = "Pilot-specific result evidence was not supplied; no wiki idea update was applied."
    evidence_ids = [claim_id, f"pilot-eval:{_slug(claim_id)}"]
    metrics: list[dict[str, Any]] = []

    if result_payload and result_payload.get("schema") == "experiment_result.v1":
        result = ((result_payload.get("outputs") or {}).get("result") or {})
        outcome = str(result.get("outcome") or result_payload.get("status") or "inconclusive")
        evidence_ids = _unique_strings(
            [
                claim_id,
                str(result_payload.get("task_id") or ""),
                *[str(item) for item in result.get("evidence_ids") or [] if str(item).strip()],
            ]
        )
        metrics = result.get("metrics") if isinstance(result.get("metrics"), list) else []
        basis = f"Pilot verdict derived from experiment_result.v1 outcome `{outcome}`."
    elif inputs.get("runtime_evidence"):
        runtime_entries = _approval_path_entries(inputs.get("runtime_evidence"))
        runtime_contract = {"runtime_evidence": runtime_entries}
        records, errors = _runtime_records(runtime_contract)
        artifacts.extend(_contract_existing_artifacts(runtime_contract, "runtime_evidence", "pilot_runtime_evidence_json"))
        if records and not errors:
            record = records[0]
            raw_outcome = str(_field(record, "outcome", "result", "verdict") or "").strip()
            exit_code = _field(record, "exit_code", "returncode")
            if raw_outcome:
                outcome = raw_outcome
            elif str(exit_code).strip() == "0":
                outcome = "supports"
            elif str(exit_code).strip():
                outcome = "failed"
            metrics = _runtime_metrics(record)
            evidence_ids = _unique_strings([claim_id, *_runtime_evidence_ids(records)])
            basis = f"Pilot verdict derived from supplied runtime evidence outcome `{outcome}`."
        else:
            basis = "Pilot runtime evidence was supplied but could not be loaded cleanly."

    verdict = {
        "supports": "supported",
        "supported": "supported",
        "partially_supports": "partially_supported",
        "partial": "partially_supported",
        "refutes": "not_supported",
        "not_supported": "not_supported",
        "failed": "inconclusive",
        "inconclusive": "inconclusive",
    }.get(outcome, "inconclusive")
    status = "completed" if verdict != "inconclusive" else "inconclusive"
    limitations = [
        "Pilot evaluation is lenient and bounded to supplied local result/runtime evidence.",
        "Pilot wiki writes remain proposed-only until explicitly approved.",
    ]
    if status != "completed":
        limitations.append("Pilot evaluation remains inconclusive because result/runtime evidence is missing or non-supportive.")
    verdict_evidence = convert_claim_verdict({
        "claim_id": claim_id,
        "verdict": verdict,
        "confidence": 0.58 if verdict == "supported" else 0.48 if verdict == "partially_supported" else 0.42 if verdict == "not_supported" else 0.2,
        "basis": basis,
        "evidence_ids": evidence_ids,
        "claim_evidence_ids": [claim_id],
        "experiment_evidence_ids": [item for item in evidence_ids if item != claim_id],
        "code_evidence_ids": [],
        "evidence_outcome": outcome,
        "metrics": metrics,
        "status": status,
        "artifacts": artifacts,
        "limitations": limitations,
    }, envelope)
    writeback_path = _write_claim_verdict_writeback_sidecar(
        envelope,
        verdict_evidence,
        require_review_llm=False,
        action="evaluate_pilot_result",
        native_skill="exp-pilot-eval",
    )
    writeback_payload: dict[str, Any] | None = None
    if writeback_path:
        verdict_evidence.setdefault("artifacts", []).append({"type": "pilot_verdict_writeback_json", "path": writeback_path})
        writeback_payload = _load_optional_evidence(writeback_path)
        if isinstance(writeback_payload, dict):
            verdict_evidence.setdefault("artifacts", []).extend(
                artifact
                for artifact in writeback_payload.get("artifacts") or []
                if isinstance(artifact, dict)
            )
            policy = (writeback_payload.get("outputs") or {}).get("policy_decision") if isinstance(writeback_payload.get("outputs"), dict) else {}
            if isinstance(policy, dict) and policy:
                verdict_evidence = _attach_policy_decision(verdict_evidence, policy)
    verdict_evidence = _attach_pilot_eval_final_acceptance_boundary(
        envelope,
        verdict_evidence,
        writeback_path=writeback_path,
    )
    writeback_status = _claim_verdict_writeback_status(envelope, writeback_path)
    writeback_has_contract = any(
        isinstance(artifact, dict) and artifact.get("type") == "approval_contract_json"
        for artifact in (writeback_payload or {}).get("artifacts", [])
    )
    if writeback_status.get("status") == "completed" and writeback_status.get("applied") is True and not writeback_has_contract:
        contract = _approval_contract(
            envelope,
            "evaluate_pilot_result",
            ["pilot_verdict_writeback", "wiki_log", "wiki_graph_edge"],
        )
        if contract.get("execution_verified") is True:
            contract_artifact = _write_approval_contract_sidecar(envelope, "evaluate_pilot_result", contract)
            verdict_evidence.setdefault("artifacts", []).append(contract_artifact)
            evidence_payload_path = _configured_output_path(
                envelope,
                "evidence_payload_path",
                _output_dir(envelope, "evaluate_pilot_result") / "evaluate_pilot_result.evidence.json",
                legacy_key="evidence_path",
                legacy_suffix=".json",
            )
            writeback_refs: list[str] = []
            if writeback_path:
                writeback_refs.append(writeback_path)
                try:
                    writeback_payload = _load_json(_resolve_harness_path(writeback_path))
                except (OSError, json.JSONDecodeError):
                    writeback_payload = {}
                for artifact in writeback_payload.get("artifacts") or []:
                    if isinstance(artifact, dict) and str(artifact.get("path") or "").strip():
                        writeback_refs.append(str(artifact["path"]))
            writeback_refs.extend(
                str(artifact.get("path") or "")
                for artifact in verdict_evidence.get("artifacts") or []
                if isinstance(artifact, dict)
            )
            verdict_evidence.setdefault("artifacts", []).extend(
                _write_approved_mutation_runtime_proof_manifests(
                    envelope,
                    action="evaluate_pilot_result",
                    native_skill="exp-pilot-eval",
                    evidence_path=evidence_payload_path,
                    applied=True,
                    contract=contract,
                    contract_artifact=contract_artifact,
                    source_refs=[],
                    mutation_refs=writeback_refs,
                    include_wiki_mutation=True,
                    source_label="approved_pilot_eval_writeback",
                    artifact_kind="pilot_eval_wiki_writeback",
                    include_provider_source=False,
                    include_side_effect=False,
                )
            )
    return verdict_evidence


def _claim_under_verification(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    claim_id = str(inputs.get("claim_id") or inputs.get("target") or "claim-001")
    for claim in _claims_from_evidence(envelope):
        if str(claim.get("claim_id") or "") == claim_id:
            return dict(claim)
    return {"claim_id": claim_id, "text": "Claim text unavailable in supplied evidence.", "evidence_ids": [claim_id]}


def _claim_verdict_code_evidence_ids(envelope: dict[str, Any], claim_id: str) -> list[str]:
    inputs = dict(envelope.get("inputs") or {})
    ids: list[str] = []
    for key in ("code_evidence", "code_evidence_map", "code_evidence_evidence"):
        for payload in _load_optional_evidence_many(inputs.get(key)):
            if payload.get("task_id"):
                ids.append(str(payload["task_id"]))
            mappings = ((payload.get("outputs") or {}).get("mappings") or [])
            for mapping in mappings if isinstance(mappings, list) else []:
                if not isinstance(mapping, dict):
                    continue
                if str(mapping.get("claim_id") or claim_id) != claim_id:
                    continue
                if mapping.get("mapping_id"):
                    ids.append(str(mapping["mapping_id"]))
                for field in ("files", "evidence_ids"):
                    values = mapping.get(field)
                    if isinstance(values, list):
                        ids.extend(str(item) for item in values if str(item).strip())
    seen: set[str] = set()
    unique: list[str] = []
    for item in ids:
        if item not in seen:
            seen.add(item)
            unique.append(item)
    return unique


def _claim_review_llm_context(
    envelope: dict[str, Any],
    claim_id: str,
    *,
    artifact_type: str = "claim_review_llm_evidence_json",
) -> tuple[dict[str, Any], list[str], list[dict[str, str]]]:
    inputs = dict(envelope.get("inputs") or {})
    paths = _input_path_values(inputs, "review_llm_evidence", "review_evidence", "artifact_review_evidence")
    artifacts: list[dict[str, str]] = []
    checked_paths: list[str] = []
    reasons: list[str] = []
    for raw in paths:
        path = _resolve_harness_path(raw)
        checked_paths.append(_rel(path))
        if not path.exists() or not path.is_file():
            reasons.append(f"missing review evidence: {raw}")
            continue
        artifacts.append({"type": artifact_type, "path": _rel(path)})
        try:
            payload = _load_json(path)
        except (OSError, json.JSONDecodeError) as exc:
            reasons.append(f"invalid review evidence JSON: {_rel(path)}: {exc}")
            continue
        if not isinstance(payload, dict):
            reasons.append(f"review evidence is not a JSON object: {_rel(path)}")
            continue
        outputs = payload.get("outputs") if isinstance(payload.get("outputs"), dict) else {}
        review = outputs.get("review") if isinstance(outputs.get("review"), dict) else payload.get("review")
        if not isinstance(review, dict):
            reasons.append(f"review evidence lacks outputs.review: {_rel(path)}")
            continue
        review_llm = review.get("review_llm") if isinstance(review.get("review_llm"), dict) else {}
        completed = (
            str(payload.get("status") or "") == "completed"
            and str(review.get("review_mode") or "") == "review_llm"
            and review.get("review_available") is True
            and str(review_llm.get("status") or "completed") == "completed"
        )
        evidence_ids = _unique_strings(
            [
                str(payload.get("task_id") or ""),
                *[str(item) for item in review.get("evidence_ids") or []],
            ]
        )
        findings = outputs.get("findings") if isinstance(outputs.get("findings"), list) else []
        if completed:
            return (
                {
                    "status": "completed",
                    "source_path": _rel(path),
                    "claim_id": claim_id,
                    "review_mode": "review_llm",
                    "review_available": True,
                    "score": review.get("score", "N/A"),
                    "recommendation": str(review.get("recommendation") or "N/A"),
                    "difficulty": str(review.get("difficulty") or "N/A"),
                    "focus": str(review.get("focus") or "N/A"),
                    "evidence_ids": evidence_ids,
                    "finding_count": len(findings),
                    "findings": findings,
                    "review_llm": review_llm or {"status": "completed"},
                    "checked_paths": checked_paths,
                },
                evidence_ids,
                artifacts,
            )
        reasons.append(f"review evidence was not completed Review LLM evidence: {_rel(path)}")
    return (
        {
            "status": "unavailable" if not paths else "inconclusive",
            "claim_id": claim_id,
            "checked_paths": checked_paths,
            "reasons": reasons or ["No Review LLM evidence was supplied."],
        },
        [],
        artifacts,
    )


def _claim_verdict_experiment_context(envelope: dict[str, Any]) -> tuple[str, list[str], str, str]:
    payload = _experiment_result_payload(envelope)
    if not payload:
        return (
            "inconclusive",
            [],
            "No experiment result evidence was supplied.",
            "missing-experiment-result",
        )
    if payload.get("schema") == "experiment_result.v1":
        result = ((payload.get("outputs") or {}).get("result") or {})
        outcome = str(result.get("outcome") or "inconclusive")
        if payload.get("status") in {"failed", "inconclusive"}:
            outcome = str(payload.get("status"))
        experiment_id = str(result.get("experiment_id") or payload.get("task_id") or "experiment-result")
        evidence_ids = [
            str(payload.get("task_id") or ""),
            experiment_id,
            *[str(item) for item in (result.get("evidence_ids") or []) if str(item).strip()],
        ]
        basis = f"Verdict derived from experiment_result.v1 outcome `{outcome}` for `{experiment_id}`."
        return outcome, [item for item in evidence_ids if item], basis, experiment_id
    outcome = str(payload.get("outcome") or "inconclusive")
    experiment_id = str(payload.get("experiment_id") or "raw-experiment-result")
    evidence_ids = [experiment_id, *[str(item) for item in (payload.get("evidence_ids") or []) if str(item).strip()]]
    basis = f"Verdict derived from raw fixture experiment outcome `{outcome}` for `{experiment_id}`."
    return outcome, evidence_ids, basis, experiment_id


def _verdict_confidence(verdict: str, outcome: str) -> float:
    if verdict == "supported":
        return 0.72
    if verdict == "partially_supported":
        return 0.58
    if verdict == "not_supported":
        return 0.66
    if verdict == "insufficient":
        return 0.35
    if outcome == "failed":
        return 0.24
    return 0.32


def _claim_verdict_writeback_status(envelope: dict[str, Any], writeback_path: str | None) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    native_options = inputs.get("native_options") if isinstance(inputs.get("native_options"), dict) else {}
    requested = bool(native_options.get("write"))
    if not requested:
        return {
            "requested": False,
            "status": "not_requested",
            "applied": False,
            "path": "",
            "approval_ref": str(inputs.get("approval_ref") or native_options.get("approval_ref") or "N/A"),
            "limitations": ["Claim verdict writeback was not requested."],
        }
    if not writeback_path:
        return {
            "requested": True,
            "status": "missing_sidecar",
            "applied": False,
            "path": "",
            "approval_ref": str(inputs.get("approval_ref") or native_options.get("approval_ref") or "N/A"),
            "limitations": ["Claim verdict writeback was requested but no writeback sidecar was produced."],
        }
    path = _resolve_harness_path(writeback_path)
    summary = {
        "requested": True,
        "status": "unreadable",
        "applied": False,
        "path": _rel(path),
        "approval_ref": str(inputs.get("approval_ref") or native_options.get("approval_ref") or "N/A"),
        "limitations": [],
    }
    try:
        payload = _load_json(path)
    except (OSError, json.JSONDecodeError) as exc:
        summary["limitations"] = [f"Claim verdict writeback sidecar could not be read: {exc}"]
        return summary
    write = ((payload.get("outputs") or {}).get("write") or {})
    if not isinstance(write, dict):
        write = {}
    summary.update(
        {
            "status": str(payload.get("status") or "unknown"),
            "applied": write.get("applied") is True,
            "approval_ref": str(write.get("approval_ref") or summary["approval_ref"]),
            "target_path": str(write.get("target_path") or ""),
            "edge_path": str(write.get("edge_path") or ""),
            "log_path": str(write.get("log_path") or ""),
            "review_llm_status": str(write.get("review_llm_status") or "missing"),
            "limitations": [str(item) for item in payload.get("limitations") or []],
        }
    )
    return summary


def _experiment_evaluation_final_verdict_boundary(
    envelope: dict[str, Any],
    verdict_evidence: dict[str, Any],
    *,
    writeback_path: str | None,
) -> dict[str, Any]:
    outputs = verdict_evidence.get("outputs") if isinstance(verdict_evidence.get("outputs"), dict) else {}
    verdicts = outputs.get("verdicts") if isinstance(outputs.get("verdicts"), list) else []
    verdict = dict(verdicts[0]) if verdicts and isinstance(verdicts[0], dict) else {}
    claim_id = str(verdict.get("claim_id") or "claim")
    experiment_payload = _experiment_result_payload(envelope)
    experiment_schema = str((experiment_payload or {}).get("schema") or "missing")
    experiment_status = str((experiment_payload or {}).get("status") or "missing")
    experiment_evidence_ids = [str(item) for item in verdict.get("experiment_evidence_ids") or [] if str(item).strip()]
    claim_evidence_ids = [str(item) for item in verdict.get("claim_evidence_ids") or [] if str(item).strip()]
    code_evidence_ids = [str(item) for item in verdict.get("code_evidence_ids") or [] if str(item).strip()]
    review_llm = verdict.get("review_llm") if isinstance(verdict.get("review_llm"), dict) else {}
    writeback = _claim_verdict_writeback_status(envelope, writeback_path)
    verdict_label = str(verdict.get("verdict") or "inconclusive")
    non_inconclusive_verdict = verdict_label not in {"inconclusive", "insufficient"}
    experiment_result_ready = (
        experiment_schema == "experiment_result.v1"
        and experiment_status == "completed"
        and bool(experiment_evidence_ids)
    )
    claim_evidence_linked = any(item != claim_id for item in claim_evidence_ids)
    code_evidence_linked = bool(code_evidence_ids)
    review_llm_completed = review_llm.get("status") == "completed"
    writeback_completed = writeback.get("status") == "completed" and writeback.get("applied") is True
    final_ready = all(
        [
            non_inconclusive_verdict,
            experiment_result_ready,
            claim_evidence_linked,
            code_evidence_linked,
            review_llm_completed,
            writeback_completed,
        ]
    )
    limitations: list[str] = []
    if not non_inconclusive_verdict:
        limitations.append("Final experiment evaluation requires a non-inconclusive claim verdict.")
    if not experiment_result_ready:
        limitations.append("Final experiment evaluation requires completed experiment_result.v1 evidence.")
    if not claim_evidence_linked:
        limitations.append("Final experiment evaluation requires linked claim evidence beyond the claim id.")
    if not code_evidence_linked:
        limitations.append("Final experiment evaluation requires linked code evidence for the evaluated claim.")
    if not review_llm_completed:
        limitations.append("Final experiment evaluation requires completed Review LLM proof.")
    if not writeback_completed:
        limitations.append("Final experiment evaluation requires completed approved wiki writeback before treating the verdict as final.")
    if not limitations:
        limitations.append("Final experiment evaluation boundary passed with result, claim, code, Review LLM, and wiki writeback evidence.")
    return {
        "schema": "autosci_experiment_evaluation_final_verdict_boundary.v1",
        "status": "final_verdict_ready" if final_ready else "final_verdict_incomplete",
        "final_verdict_ready": final_ready,
        "claim_id": claim_id,
        "verdict": verdict_label,
        "experiment_result_ready": experiment_result_ready,
        "experiment_schema": experiment_schema,
        "experiment_status": experiment_status,
        "experiment_evidence_ids": experiment_evidence_ids,
        "claim_evidence_linked": claim_evidence_linked,
        "claim_evidence_ids": claim_evidence_ids,
        "code_evidence_linked": code_evidence_linked,
        "code_evidence_ids": code_evidence_ids,
        "review_llm_completed": review_llm_completed,
        "review_llm_status": str(review_llm.get("status") or "missing"),
        "writeback_completed": writeback_completed,
        "writeback_status": writeback,
        "evidence_ids": _unique_strings([str(item) for item in verdict.get("evidence_ids") or []]),
        "limitations": limitations,
    }


def _attach_experiment_evaluation_final_verdict_boundary(
    envelope: dict[str, Any],
    verdict_evidence: dict[str, Any],
    *,
    writeback_path: str | None,
) -> dict[str, Any]:
    boundary = _experiment_evaluation_final_verdict_boundary(
        envelope,
        verdict_evidence,
        writeback_path=writeback_path,
    )
    outputs = verdict_evidence.setdefault("outputs", {})
    verdicts = outputs.get("verdicts") if isinstance(outputs.get("verdicts"), list) else []
    if verdicts and isinstance(verdicts[0], dict):
        verdicts[0]["final_verdict_boundary"] = boundary
        verdicts[0]["final_verdict_ready"] = boundary.get("final_verdict_ready") is True
    outputs["final_verdict_boundary"] = boundary
    boundary_path = _write_json_sidecar(
        _output_dir(envelope, "verify_claim") / "verdict_boundary.json",
        boundary,
    )
    verdict_evidence.setdefault("artifacts", []).append(
        {"type": "experiment_evaluation_final_verdict_boundary_json", "path": boundary_path}
    )
    verdict_evidence.setdefault("limitations", []).extend(str(item) for item in boundary.get("limitations") or [])
    return verdict_evidence


def _claim_review_blocks_support(review_llm: dict[str, Any]) -> tuple[bool, list[str]]:
    if str(review_llm.get("status") or "") != "completed":
        return False, []
    recommendation = str(review_llm.get("recommendation") or "").strip().lower()
    blocking_recommendations = {"revise", "revise_required", "reject", "rejected", "fail", "failed", "not_supported"}
    reasons: list[str] = []
    if recommendation in blocking_recommendations:
        reasons.append(f"review recommendation `{recommendation}` blocks supported verdict")
    for finding in review_llm.get("findings") or []:
        if not isinstance(finding, dict):
            continue
        severity = str(finding.get("severity") or "").strip().lower()
        category = str(finding.get("category") or "").strip().lower()
        text = " ".join(
            str(finding.get(key) or "")
            for key in ("finding_id", "category", "evidence", "suggestion")
        ).lower()
        if severity == "high" or category in {"external_validity", "reasoning"} or any(
            token in text for token in ("overgeneral", "unsupported", "worldwide", "future dataset")
        ):
            reasons.append(str(finding.get("finding_id") or category or "review finding blocks supported verdict"))
    return bool(reasons), _unique_strings(reasons)


def _action_verify_claim(envelope: dict[str, Any]) -> dict[str, Any]:
    claim = _claim_under_verification(envelope)
    claim_id = str(claim.get("claim_id") or "claim-001")
    outcome, experiment_ids, basis, experiment_id = _claim_verdict_experiment_context(envelope)
    review_llm, review_evidence_ids, review_artifacts = _claim_review_llm_context(envelope, claim_id)
    verdict = {
        "supports": "supported",
        "partially_supports": "partially_supported",
        "refutes": "not_supported",
        "not_supported": "not_supported",
        "inconclusive": "inconclusive",
        "failed": "inconclusive",
    }.get(outcome, "inconclusive")
    support_classification = {
        "supported": "supported",
        "partially_supported": "supported",
        "not_supported": "unsupported",
        "insufficient": "insufficient_evidence",
        "inconclusive": "insufficient_evidence",
    }.get(verdict, "insufficient_evidence")
    experiment_payload = _experiment_result_payload(envelope) or {}
    experiment_scope_source = (
        ((experiment_payload.get("outputs") or {}).get("result") or {})
        if experiment_payload.get("schema") == "experiment_result.v1"
        else experiment_payload
    )
    scope_comparison = compare_claim_evidence_scope(claim, experiment_scope_source)
    scope_risks = list(scope_comparison["risks"])
    claim_evidence_ids = [claim_id, *[str(item) for item in (claim.get("evidence_ids") or []) if str(item).strip()]]
    code_evidence_ids = _claim_verdict_code_evidence_ids(envelope, claim_id)
    evidence_ids = [*claim_evidence_ids, *experiment_ids, *code_evidence_ids, *review_evidence_ids]
    if not experiment_ids:
        verdict = "inconclusive"
        support_classification = "insufficient_evidence"
    elif scope_risks and verdict == "supported":
        verdict = "insufficient"
        outcome = "insufficient_evidence"
        support_classification = "insufficient_evidence"
        basis = f"{basis} Claim scope exceeds the available evidence; local support cannot establish the broader assertion."
    seen: set[str] = set()
    unique_evidence_ids: list[str] = []
    for item in evidence_ids:
        if item and item not in seen:
            seen.add(item)
            unique_evidence_ids.append(item)
    limitations = [
        "Fixture verdict is derived only from supplied local evidence; it is not external scientific validation."
    ]
    review_blocks_support, review_block_reasons = _claim_review_blocks_support(review_llm)
    if verdict == "supported" and review_blocks_support:
        verdict = "inconclusive"
        basis = f"{basis} Review LLM blocked supported verdict: {'; '.join(review_block_reasons)}."
        limitations.append("Supported experiment evidence was not promoted because independent review found overreach or unsupported assumptions.")
    if verdict == "inconclusive":
        limitations.append("Supplied experiment evidence is missing, failed, or inconclusive; the claim was not upgraded.")
    if scope_risks:
        limitations.extend(scope_risks)
    if review_llm.get("status") == "completed":
        basis = (
            f"{basis} Review LLM evidence `{review_llm.get('source_path')}` was attached "
            f"with recommendation `{review_llm.get('recommendation')}`."
        )
        limitations.append("Review LLM evidence is attached as an independent second opinion; verdict outcome still follows experiment evidence.")
    else:
        limitations.append("Review LLM second-opinion evidence was not supplied or did not complete.")
    verdict_evidence = convert_claim_verdict({
        "claim_id": claim_id,
        "verdict": verdict,
        "confidence": _verdict_confidence(verdict, outcome),
        "basis": f"{basis} Claim text: {claim.get('text', 'N/A')}",
        "evidence_ids": unique_evidence_ids,
        "claim_evidence_ids": claim_evidence_ids,
        "experiment_evidence_ids": experiment_ids,
        "code_evidence_ids": code_evidence_ids,
        "evidence_outcome": outcome,
        "support_classification": support_classification,
        "overclaim_risks": scope_risks,
        "scope_comparison": scope_comparison,
        "classification_reason": "scope_overclaim" if scope_risks else "experiment_outcome",
        "experiment_id": experiment_id,
        "review_llm": review_llm,
        "artifacts": review_artifacts,
        "limitations": limitations,
    }, envelope)
    evidence_payload_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        _output_dir(envelope, "verify_claim") / "verify_claim.evidence.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    review_runtime_proof_artifact = _write_review_context_runtime_proof_manifest(
        envelope,
        action="verify_claim",
        native_skill="exp-eval",
        evidence_path=evidence_payload_path,
        review_llm=review_llm,
    )
    if review_runtime_proof_artifact is not None:
        verdict_evidence.setdefault("artifacts", []).append(review_runtime_proof_artifact)
    writeback_path = _write_claim_verdict_writeback_sidecar(
        envelope,
        verdict_evidence,
        action="verify_claim",
        native_skill="exp-eval",
    )
    writeback_payload: dict[str, Any] | None = None
    if writeback_path:
        verdict_evidence.setdefault("artifacts", []).append({"type": "claim_verdict_writeback_json", "path": writeback_path})
        writeback_payload = _load_optional_evidence(writeback_path)
        if isinstance(writeback_payload, dict):
            verdict_evidence.setdefault("artifacts", []).extend(
                artifact
                for artifact in writeback_payload.get("artifacts") or []
                if isinstance(artifact, dict)
            )
            policy = (writeback_payload.get("outputs") or {}).get("policy_decision") if isinstance(writeback_payload.get("outputs"), dict) else {}
            if isinstance(policy, dict) and policy:
                verdict_evidence = _attach_policy_decision(verdict_evidence, policy)
        writeback_has_contract = any(
            isinstance(artifact, dict) and artifact.get("type") == "approval_contract_json"
            for artifact in (writeback_payload or {}).get("artifacts", [])
        )
        if isinstance(writeback_payload, dict) and str(writeback_payload.get("status") or "") == "completed" and not writeback_has_contract:
            contract = _approval_contract(
                envelope,
                "verify_claim",
                ["claim_verdict_wiki_writeback"],
            )
            contract_artifact = _write_approval_contract_sidecar(envelope, "verify_claim", contract)
            verdict_evidence.setdefault("artifacts", []).append(contract_artifact)
            mutation_refs = [writeback_path]
            for artifact in writeback_payload.get("artifacts") or []:
                if isinstance(artifact, dict) and str(artifact.get("path") or "").strip():
                    mutation_refs.append(str(artifact["path"]))
            verdict_evidence.setdefault("artifacts", []).extend(
                _write_approved_mutation_runtime_proof_manifests(
                    envelope,
                    action="verify_claim",
                    native_skill="exp-eval",
                    evidence_path=evidence_payload_path,
                    applied=True,
                    contract=contract,
                    contract_artifact=contract_artifact,
                    source_refs=[*review_evidence_ids],
                    mutation_refs=mutation_refs,
                    include_wiki_mutation=True,
                    source_label="claim_verdict_writeback",
                    artifact_kind="claim_verdict_writeback",
                    include_provider_source=False,
                    include_side_effect=False,
                )
            )
    verdict_evidence = _attach_experiment_evaluation_final_verdict_boundary(
        envelope,
        verdict_evidence,
        writeback_path=writeback_path,
    )
    return verdict_evidence


def _claim_verdict_writeback_path(envelope: dict[str, Any]) -> Path:
    return _output_dir(envelope, "verify_claim") / "claim_verdict_writeback.json"


def _target_claim_verdict_path_for_write(envelope: dict[str, Any], claim_id: str) -> tuple[Path | None, str, list[str]]:
    inputs = dict(envelope.get("inputs") or {})
    target = str(inputs.get("target") or inputs.get("claim_id") or claim_id or "").strip()
    roots = _wiki_roots_for_write(envelope)
    candidates: list[Path] = []
    raw_path = Path(target)
    if raw_path.suffix.lower() in {".md", ".markdown"}:
        if raw_path.is_absolute():
            candidates.append(raw_path)
        else:
            for root in roots:
                candidates.extend([root / raw_path, root / "ideas" / raw_path.name, root / "experiments" / raw_path.name])
    else:
        slug = _slug(target or claim_id)
        for root in roots:
            candidates.extend([root / "ideas" / f"{slug}.md", root / "experiments" / f"{slug}.md"])
    checked: list[str] = []
    for candidate in candidates:
        checked.append(str(candidate))
        if not candidate.exists() or not candidate.is_file():
            continue
        if not any(_path_is_under(candidate, root) for root in roots):
            continue
        return candidate, _slug(candidate.stem), checked
    return None, _slug(target or claim_id), checked


def _append_claim_verdict_wiki_log(root: Path, target_path: Path, verdict: dict[str, Any]) -> Path:
    log_path = root / "log.md"
    log_path.parent.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    evidence_ids = ", ".join(str(item) for item in verdict.get("evidence_ids") or []) or "N/A"
    entry = (
        "\n## Claim Verdict Writeback\n\n"
        f"- {timestamp} | claim-verdict | wrote verdict={verdict.get('verdict')} | "
        f"target={_rel(target_path)} | evidence={evidence_ids}\n"
    )
    with log_path.open("a", encoding="utf-8") as handle:
        handle.write(entry)
    return log_path


def _append_claim_verdict_wiki_edge(root: Path, target_path: Path, verdict: dict[str, Any]) -> Path:
    edges_path = root / "graph" / "edges.jsonl"
    edges_path.parent.mkdir(parents=True, exist_ok=True)
    edge = {
        "edge_type": "claim_verdict_written",
        "source_type": "claim",
        "source_id": str(verdict.get("claim_id") or "claim"),
        "relation": "has_claim_verdict",
        "target_type": "wiki_page",
        "target_path": _rel(target_path),
        "verdict": str(verdict.get("verdict") or "inconclusive"),
        "confidence": verdict.get("confidence", "N/A"),
        "evidence_ids": _unique_strings([str(item) for item in verdict.get("evidence_ids") or []]),
        "timestamp": datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
    }
    with edges_path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(edge, sort_keys=True) + "\n")
    return edges_path


def _write_claim_verdict_writeback_sidecar(
    envelope: dict[str, Any],
    verdict_evidence: dict[str, Any],
    *,
    require_review_llm: bool = True,
    action: str = "verify_claim",
    native_skill: str = "exp-eval",
) -> str | None:
    inputs = dict(envelope.get("inputs") or {})
    native_options = inputs.get("native_options") if isinstance(inputs.get("native_options"), dict) else {}
    if not native_options.get("write"):
        return None
    path = _claim_verdict_writeback_path(envelope)
    verdicts = ((verdict_evidence.get("outputs") or {}).get("verdicts") or [])
    verdict = dict(verdicts[0]) if verdicts and isinstance(verdicts[0], dict) else {}
    claim_id = str(verdict.get("claim_id") or inputs.get("claim_id") or "claim")
    contract = _approval_contract(
        envelope,
        action,
        ["claim_verdict_wiki_writeback", "wiki_log", "wiki_graph_edge"],
    )
    contract, policy_decision, policy_artifacts = _policy_prepare_auto_contract_if_needed(
        envelope,
        action,
        ["read_local", "write_artifact", "wiki_mutation"],
        contract,
        allowlist_payload={
            "native_surface": f"${native_skill}",
            "allowed_side_effects": ["claim_verdict_wiki_writeback", "wiki_log", "wiki_graph_edge"],
            "limitations": [
                "Policy approval applies only to local claim-verdict wiki frontmatter/log/edge writeback.",
                "A non-inconclusive verdict and resolved target wiki page are still required.",
            ],
        },
    )
    inputs = dict(envelope.get("inputs") or {})
    native_options = inputs.get("native_options") if isinstance(inputs.get("native_options"), dict) else {}
    approval_ref = str(inputs.get("approval_ref") or native_options.get("approval_ref") or "").strip()
    review_llm = verdict.get("review_llm") if isinstance(verdict.get("review_llm"), dict) else {}
    target_path, target_slug, checked_paths = _target_claim_verdict_path_for_write(envelope, claim_id)
    status = "inconclusive"
    artifacts: list[dict[str, str]] = [*policy_artifacts]
    limitations: list[str] = []
    write = {
        "requested": True,
        "applied": False,
        "approval_ref": approval_ref or "N/A",
        "claim_id": claim_id,
        "target_slug": target_slug,
        "checked_paths": checked_paths,
        "verdict": verdict.get("verdict", "N/A"),
        "review_llm_status": review_llm.get("status", "missing"),
    }

    if not approval_ref:
        limitations.append("Claim verdict write-back requires --approval-ref.")
    elif verdict.get("verdict") == "inconclusive":
        limitations.append("Claim verdict write-back requires a non-inconclusive verdict.")
    elif require_review_llm and review_llm.get("status") != "completed":
        limitations.append("Claim verdict write-back requires completed Review LLM evidence.")
    elif target_path is None:
        limitations.append("Claim verdict write-back target did not resolve to an existing wiki idea or experiment page.")
    else:
        original = target_path.read_text(encoding="utf-8", errors="replace")
        updated = _set_frontmatter_scalar(original, "claim_verdict", str(verdict.get("verdict") or "inconclusive"))
        if updated is not None:
            updated = _set_frontmatter_scalar(updated, "claim_verdict_confidence", str(verdict.get("confidence", "N/A"))) or updated
            updated = _set_frontmatter_scalar(updated, "claim_verdict_evidence", ",".join(str(item) for item in verdict.get("evidence_ids") or [])) or updated
        if updated is None:
            limitations.append("Claim verdict write-back target has no YAML frontmatter.")
        else:
            target_path.write_text(updated, encoding="utf-8")
            wiki_root = next((root for root in _wiki_roots_for_write(envelope) if _path_is_under(target_path, root)), target_path.parent.parent)
            log_path = _append_claim_verdict_wiki_log(wiki_root, target_path, verdict)
            edge_path = _append_claim_verdict_wiki_edge(wiki_root, target_path, verdict)
            rebuild_paths = _rebuild_wiki_mutation_views(wiki_root, str(envelope.get("sprint_id") or "sprint-autosci"), target_path, verdict)
            status = "completed"
            write.update(
                {
                    "applied": True,
                    "target_path": _rel(target_path),
                    "log_path": _rel(log_path),
                    "edge_path": _rel(edge_path),
                    "rebuilt_paths": [_rel(item) for item in rebuild_paths],
                }
            )
            artifacts.extend(
                [
                    {"type": "wiki_claim_verdict_target", "path": _rel(target_path)},
                    {"type": "wiki_log", "path": _rel(log_path)},
                    {"type": "wiki_graph_edges", "path": _rel(edge_path)},
                    *[{"type": "wiki_rebuild", "path": _rel(item)} for item in rebuild_paths],
                ]
            )
            runtime_artifact = _append_local_mutation_runtime_to_contract(
                envelope,
                action,
                contract,
                command_run=f"{action}:local_claim_verdict_writeback",
                evidence_ids=[str(item) for item in verdict.get("evidence_ids") or [] if str(item).strip()],
                after_refs=[target_path, log_path, edge_path, *rebuild_paths],
                runtime_fields={
                    "claim_id": claim_id,
                    "verdict": str(verdict.get("verdict") or "N/A"),
                    "target_path": _rel(target_path),
                },
                limitations=["Claim verdict writeback executed through the approved local AutoSci side-effect path."],
            )
            artifacts.append(runtime_artifact)
    if not limitations:
        limitations.append("Approved claim verdict write-back updated wiki frontmatter, log, graph edge, and lightweight wiki views.")
    outputs: dict[str, Any] = {"write": write, "source_verdict": verdict}
    if policy_decision:
        outputs["policy_decision"] = policy_decision
    if policy_artifacts or status == "completed":
        contract_artifact = _write_approval_contract_sidecar(envelope, action, contract)
        artifacts.append(contract_artifact)
        if status == "completed":
            mutation_refs: list[str | Path] = [path]
            mutation_refs.extend(
                str(artifact.get("path") or "")
                for artifact in artifacts
                if isinstance(artifact, dict) and str(artifact.get("path") or "").strip()
            )
            artifacts.extend(
                _write_approved_mutation_runtime_proof_manifests(
                    envelope,
                    action=action,
                    native_skill=native_skill,
                    evidence_path=path,
                    applied=True,
                    contract=contract,
                    contract_artifact=contract_artifact,
                    source_refs=[],
                    mutation_refs=mutation_refs,
                    include_wiki_mutation=True,
                    source_label="claim_verdict_writeback",
                    artifact_kind="claim_verdict_writeback",
                    include_provider_source=False,
                    include_side_effect=False,
                )
            )

    evidence = {
        "schema": "claim_verdict_writeback.v1",
        "task_id": f"{verdict_evidence.get('task_id', 'task-verify-claim')}:claim-verdict-writeback",
        "sprint_id": str(verdict_evidence.get("sprint_id") or envelope.get("sprint_id") or "sprint-autosci"),
        "node_id": f"{verdict_evidence.get('node_id', 'node-verify-claim')}:claim-verdict-writeback",
        "status": status,
        "inputs": inputs,
        "outputs": outputs,
        "artifacts": artifacts,
        "provenance": {
            "operator_id": "autosci-bridge",
            "implementation_package": "plugins/autosci",
            "timestamp": datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        },
        "limitations": limitations,
    }
    return _write_evidence_payload(path, evidence)


