def _write_approved_mutation_runtime_proof_manifests(
    envelope: dict[str, Any],
    *,
    action: str,
    native_skill: str,
    evidence_path: Path,
    applied: bool,
    contract: dict[str, Any],
    contract_artifact: dict[str, str],
    source_refs: list[str | Path],
    mutation_refs: list[str | Path],
    include_wiki_mutation: bool,
    source_label: str,
    artifact_kind: str,
    include_provider_source: bool = True,
    include_side_effect: bool = True,
) -> list[dict[str, str]]:
    if not applied or contract.get("execution_verified") is not True:
        return []
    timestamp = datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    proof_stamp = timestamp.replace(":", "").replace("-", "")
    contract_path = str(contract_artifact.get("path") or "").strip() if isinstance(contract_artifact, dict) else ""
    approval_refs = _runtime_evidence_refs(evidence_path, contract_path, *_approval_contract_runtime_refs(contract))
    mutation_refs_normalized = _runtime_evidence_refs(evidence_path, *mutation_refs)
    source_refs_normalized = _runtime_evidence_refs(evidence_path, *source_refs)
    proof_artifacts: list[dict[str, str]] = []

    def write_proof(
        *,
        filename: str,
        artifact_type: str,
        categories: list[str],
        source: str,
        refs: list[str],
        description: str,
    ) -> None:
        manifest = {
            "schema": "autosci_runtime_proof_manifest.v1",
            "generated_at": timestamp,
            "proofs": [
                {
                    "native_skill": native_skill,
                    "proof_id": f"runtime:{_slug(native_skill)}:{_slug(source)}:{proof_stamp}",
                    "categories": categories,
                    "collection_mode": "approved_side_effect",
                    "production_ready": True,
                    "provenance": {
                        "source": source,
                        "captured_at": timestamp,
                        "artifact_kind": artifact_kind,
                        "command": f"{action}:approved_mutation",
                    },
                    "evidence_refs": refs,
                    "description": description,
                }
            ],
        }
        artifact_path = _write_json_sidecar(_output_dir(envelope, action) / filename, manifest)
        proof_artifacts.append({"type": artifact_type, "path": artifact_path})

    if include_provider_source and source_refs_normalized:
        write_proof(
            filename=f"{action}_source_provider_runtime_proof.json",
            artifact_type="provider_source_runtime_proof_manifest_json",
            categories=["provider_source_evidence"],
            source=source_label,
            refs=source_refs_normalized,
            description=f"Completed approved source artifact evidence for AutoSci `{native_skill}` parity.",
        )
    write_proof(
        filename=f"{action}_approval_runtime_proof.json",
        artifact_type="approval_runtime_proof_manifest_json",
        categories=["external_runtime_evidence", "approval_boundary_evidence"],
        source="approval_contract",
        refs=approval_refs,
        description=f"Verified approval/runtime evidence for AutoSci `{native_skill}` parity.",
    )
    if include_side_effect:
        write_proof(
            filename=f"{action}_side_effect_execution_runtime_proof.json",
            artifact_type="side_effect_runtime_proof_manifest_json",
            categories=["side_effect_execution_evidence"],
            source="approved_mutation",
            refs=mutation_refs_normalized,
            description=f"Completed approved side-effect execution evidence for AutoSci `{native_skill}` parity.",
        )
    if include_wiki_mutation:
        write_proof(
            filename=f"{action}_wiki_mutation_runtime_proof.json",
            artifact_type="wiki_mutation_runtime_proof_manifest_json",
            categories=["wiki_mutation_evidence"],
            source="wiki_writeback",
            refs=mutation_refs_normalized,
            description=f"Completed approved wiki mutation evidence for AutoSci `{native_skill}` parity.",
        )
    return proof_artifacts


def _write_paper_compile_runtime_proof_manifest(
    envelope: dict[str, Any],
    *,
    evidence_path: Path,
    status: str,
    semantic: dict[str, Any],
    contract: dict[str, Any],
    artifacts: list[dict[str, Any]],
    latex_files: list[Path],
    pdf_files: list[Path],
) -> dict[str, str] | None:
    if status != "completed" or semantic.get("verified") is not True or contract.get("execution_verified") is not True:
        return None
    refs: list[str | Path] = [evidence_path]
    for artifact in artifacts:
        if not isinstance(artifact, dict):
            continue
        path = str(artifact.get("path") or "").strip()
        if path:
            refs.append(path)
    refs.extend(latex_files)
    refs.extend(pdf_files)
    timestamp = datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    detail = semantic.get("detail") if isinstance(semantic.get("detail"), dict) else {}
    executor = str(detail.get("tex_executor") or detail.get("command_run") or "compile_runtime")
    manifest = {
        "schema": "autosci_runtime_proof_manifest.v1",
        "generated_at": timestamp,
        "proofs": [
            {
                "native_skill": "paper-compile",
                "proof_id": f"runtime:paper-compile:{_slug(executor)}:{timestamp.replace(':', '').replace('-', '')}",
                "categories": [
                    "external_runtime_evidence",
                    "approval_boundary_evidence",
                    "side_effect_execution_evidence",
                    "provider_source_evidence",
                ],
                "collection_mode": "approved_side_effect",
                "production_ready": True,
                "provenance": {
                    "source": "paper_compile_runtime",
                    "captured_at": timestamp,
                    "artifact_kind": "paper_compile_checklist",
                    "command": "compile_paper:runtime_semantic",
                    "executor": executor,
                },
                "evidence_refs": _runtime_evidence_refs(*refs),
                "description": "Completed approved runtime/source evidence for AutoSci `paper-compile` parity.",
            }
        ],
    }
    artifact_path = _write_json_sidecar(
        _output_dir(envelope, "compile_paper") / "compile_paper_runtime_proof.json",
        manifest,
    )
    return {"type": "provider_source_runtime_proof_manifest_json", "path": artifact_path}


def _write_phase14_publication_sidecars(envelope: dict[str, Any], report_evidence: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    paths = _phase14_report_paths(envelope)
    report = dict(((report_evidence.get("outputs") or {}).get("report") or {}))
    limitations_list = [str(item) for item in report_evidence.get("limitations") or []]
    file_artifacts = [
        _artifact("report_plan_json", paths["report_plan"]),
        _artifact("markdown_report", paths["report_md"]),
        _artifact("report_evidence_index_json", paths["evidence_index"]),
        _artifact("optional_poster_html", paths["poster_html"]),
        _artifact("optional_rebuttal_markdown", paths["rebuttal_md"]),
    ]
    if inputs.get("paper_draft"):
        file_artifacts.extend([
            _artifact("latex_source", paths["paper_main_tex"]),
            _artifact("paper_math_commands_tex", paths["paper_math_commands_tex"]),
            _artifact("paper_sections_directory", paths["paper_sections_dir"]),
            _artifact("paper_figures_directory", paths["paper_figures_dir"]),
            _artifact("paper_tables_directory", paths["paper_tables_dir"]),
            _artifact("paper_references_bib", paths["paper_references_bib"]),
        ])
    passthrough_types = {
        "paper_draft_compile_handoff_json",
        "paper_compile_runtime_evidence_json",
        "compile_runtime_after_artifact",
        "compiled_pdf",
        "citation_map_json",
        "paper_draft_final_manuscript_boundary_json",
        "paper_references_bib",
        "paper_draft_bibtex_coverage_json",
        "paper_draft_section_evidence_map_json",
    }
    seen_file_artifacts = {(artifact["type"], artifact["path"]) for artifact in file_artifacts}
    for artifact in report_evidence.get("artifacts") or []:
        if not isinstance(artifact, dict):
            continue
        artifact_type = str(artifact.get("type") or "")
        artifact_path = str(artifact.get("path") or "")
        if artifact_type not in passthrough_types or not artifact_path:
            continue
        key = (artifact_type, artifact_path)
        if key in seen_file_artifacts:
            continue
        seen_file_artifacts.add(key)
        file_artifacts.append({"type": artifact_type, "path": artifact_path})
    _write_json_sidecar(paths["report_plan"], {
        "report_id": report.get("report_id"),
        "title": report.get("title"),
        "sections": [
            {
                "section_id": section.get("section_id"),
                "title": section.get("title"),
                "evidence_ids": section.get("evidence_ids") or [],
            }
            for section in report.get("sections") or []
            if isinstance(section, dict)
        ],
        "publication_bundle_path": report.get("publication_bundle_path"),
    })
    _write_text_sidecar(paths["report_md"], _render_report_markdown(report, limitations_list))
    _write_text_sidecar(paths["poster_html"], _render_poster_html(report))
    _write_text_sidecar(paths["rebuttal_md"], _render_rebuttal_markdown(report, limitations_list))
    if inputs.get("paper_draft"):
        _write_text_sidecar(paths["paper_main_tex"], _render_latex_paper(report, limitations_list))
        _write_text_sidecar(
            paths["paper_math_commands_tex"],
            "\n".join(
                [
                    "% AutoSci local draft macros.",
                    r"\newcommand{\methodname}{AutoSci}",
                    r"\newcommand{\evidenceid}[1]{\texttt{#1}}",
                    "",
                ]
            ),
        )
        if not paths["paper_references_bib"].exists():
            _write_text_sidecar(paths["paper_references_bib"], "")
        paths["paper_sections_dir"].mkdir(parents=True, exist_ok=True)
        paths["paper_figures_dir"].mkdir(parents=True, exist_ok=True)
        paths["paper_tables_dir"].mkdir(parents=True, exist_ok=True)
        standard_sections = _paper_draft_standard_sections(report)
        for section in standard_sections:
            section_id = _slug(str(section.get("section_id") or section.get("title") or "section"))
            section_body = "\n".join(
                [
                    r"\section{" + _latex_escape(str(section.get("title") or section_id)) + "}",
                    _latex_escape(str(section.get("body") or "N/A")),
                    "",
                    r"\paragraph{Evidence ids} "
                    + _latex_escape(", ".join(str(item) for item in section.get("evidence_ids") or []) or "N/A"),
                    "",
                ]
            )
            _write_text_sidecar(paths["paper_sections_dir"] / f"{section_id}.tex", section_body)
        for section in report.get("sections") or []:
            if not isinstance(section, dict):
                continue
            section_id = _slug(str(section.get("section_id") or section.get("title") or "section"))
            section_body = "\n".join(
                [
                    r"\section{" + _latex_escape(str(section.get("title") or section_id)) + "}",
                    _latex_escape(str(section.get("body") or "N/A")),
                    "",
                ]
            )
            _write_text_sidecar(paths["paper_sections_dir"] / f"{section_id}.tex", section_body)
    _write_json_sidecar(paths["evidence_index"], {
        "report_id": report.get("report_id"),
        "evidence_ids": report.get("evidence_ids") or [],
        "sections": [
            {
                "section_id": section.get("section_id"),
                "evidence_ids": section.get("evidence_ids") or [],
            }
            for section in report.get("sections") or []
            if isinstance(section, dict)
        ],
    })
    report_id = str(report.get("report_id") or "report-autosci-phase14")
    bundle_evidence = convert_publication_bundle({
        "bundle_id": f"bundle-{report_id}",
        "publication_type": "mixed",
        "source_report_id": report_id,
        "files": file_artifacts,
        "evidence_ids": _unique_strings([report_id, *[str(item) for item in report.get("evidence_ids") or []]]),
        "artifacts": file_artifacts,
        "limitations": [
            "Fixture publication bundle contains local files only.",
            "Human approval is required before external publication or submission.",
        ],
    }, envelope)
    bundle_path = _write_evidence_payload(paths["publication_bundle"], bundle_evidence)
    return {
        "publication_bundle_path": bundle_path,
        "publication_files": [artifact["path"] for artifact in file_artifacts],
        "sidecar_evidence_paths": [bundle_path],
    }


def _action_write_report(envelope: dict[str, Any]) -> dict[str, Any]:
    return convert_scientific_report(_phase14_report_raw(envelope), envelope)


def _native_publication_title(envelope: dict[str, Any], fallback: str) -> str:
    inputs = dict(envelope.get("inputs") or {})
    return str(
        inputs.get("report_title")
        or inputs.get("title")
        or inputs.get("topic")
        or inputs.get("target")
        or fallback
    )


def _native_publication_target(envelope: dict[str, Any]) -> str:
    inputs = dict(envelope.get("inputs") or {})
    return str(inputs.get("target") or inputs.get("paper_path") or inputs.get("topic") or "N/A")


def _native_publication_evidence_ids(envelope: dict[str, Any], fallback: str) -> list[str]:
    inputs = dict(envelope.get("inputs") or {})
    ids = [
        *[str(item) for payload in _phase14_source_payloads(envelope) for item in _phase14_payload_evidence_ids(payload)],
        str(inputs.get("claim_id") or ""),
        str(inputs.get("experiment_id") or ""),
        str(inputs.get("target") or ""),
    ]
    return _unique_strings(ids) or [fallback]


def _native_publication_has_source_evidence(envelope: dict[str, Any]) -> bool:
    return bool(_phase14_source_payloads(envelope))


def _citation_id_from_entry(entry: dict[str, Any], fallback: str) -> str:
    for key in ("candidate_id", "citation_id", "paper_id", "paperId", "arxiv_id", "source_ref", "url"):
        value = str(entry.get(key) or "").strip()
        if value:
            return value
    return fallback


def _citation_entry(entry: dict[str, Any], *, source: str, evidence_id: str, fallback: str) -> dict[str, Any] | None:
    title = str(entry.get("title") or entry.get("name") or "").strip()
    if not title:
        return None
    source_ref = str(entry.get("source_ref") or entry.get("url") or "").strip()
    arxiv_id = str(entry.get("arxiv_id") or "").strip()
    if not source_ref and arxiv_id:
        source_ref = f"https://arxiv.org/abs/{arxiv_id}"
    citation_id = _citation_id_from_entry(entry, fallback)
    channels = entry.get("source_channels") if isinstance(entry.get("source_channels"), list) else []
    citation = {
        "citation_id": citation_id,
        "title": title,
        "source_ref": source_ref or "N/A",
        "source": source,
        "evidence_id": evidence_id,
        "source_channels": [str(item) for item in channels if str(item).strip()],
    }
    bibtex = str(entry.get("bibtex") or "").strip()
    if bibtex:
        citation["bibtex"] = bibtex
        citation["bibtex_verified"] = entry.get("bibtex_verified") is True
        citation["bibtex_provenance"] = str(entry.get("bibtex_provenance") or "").strip()
    return citation


def _citation_entries_from_payload(payload: dict[str, Any]) -> list[dict[str, Any]]:
    outputs = payload.get("outputs") if isinstance(payload.get("outputs"), dict) else {}
    evidence_id = str(payload.get("task_id") or payload.get("node_id") or payload.get("schema") or "source-evidence")
    entries: list[dict[str, Any]] = []
    for index, candidate in enumerate(outputs.get("candidates") or []):
        if isinstance(candidate, dict):
            entry = _citation_entry(candidate, source="literature_discovery", evidence_id=evidence_id, fallback=f"{evidence_id}:candidate-{index + 1}")
            if entry:
                entries.append(entry)
    paper = outputs.get("paper")
    if isinstance(paper, dict):
        entry = _citation_entry(paper, source="research_paper", evidence_id=evidence_id, fallback=f"{evidence_id}:paper")
        if entry:
            entries.append(entry)
    return entries


def _citation_entries_from_wiki(envelope: dict[str, Any]) -> list[dict[str, Any]]:
    entries: list[dict[str, Any]] = []
    for root in _wiki_roots_for_read(envelope):
        papers_dir = root / "papers"
        if not papers_dir.exists():
            continue
        for index, path in enumerate(sorted(papers_dir.glob("*.md")), start=1):
            text = path.read_text(encoding="utf-8", errors="replace")
            title = path.stem.replace("-", " ").title()
            for line in text.splitlines():
                if line.startswith("# "):
                    title = line[2:].strip()
                    break
            arxiv_match = re.search(r"(?:arxiv:|arxiv_id:)\s*([0-9]{4}\.[0-9]{4,5}(?:v\d+)?)", text, re.IGNORECASE)
            source_ref = f"https://arxiv.org/abs/{arxiv_match.group(1)}" if arxiv_match else _rel(path)
            entries.append(
                {
                    "citation_id": f"wiki:{_rel(path)}",
                    "title": title,
                    "source_ref": source_ref,
                    "source": "wiki_paper",
                    "evidence_id": _rel(path),
                    "source_channels": ["wiki"],
                    "path": _rel(path),
                }
            )
            if index >= 50:
                break
    return entries


def _native_publication_citation_map(envelope: dict[str, Any]) -> dict[str, Any]:
    entries: list[dict[str, Any]] = []
    for payload in _phase14_source_payloads(envelope):
        entries.extend(_citation_entries_from_payload(payload))
    entries.extend(_citation_entries_from_wiki(envelope))
    deduped: dict[str, dict[str, Any]] = {}
    for entry in entries:
        key = str(entry.get("citation_id") or entry.get("title") or "").strip().lower()
        if key and key not in deduped:
            deduped[key] = entry
    citations = list(deduped.values())
    return {
        "schema": "autosci_publication_citation_map.v1",
        "status": "completed" if citations else "inconclusive",
        "citation_count": len(citations),
        "citations": citations,
        "limitations": [] if citations else ["No source-backed citation entries were available."],
    }


def _survey_final_coverage_boundary(
    citation_map: dict[str, Any],
    *,
    has_source_evidence: bool,
    requested_limit: int,
) -> dict[str, Any]:
    citations = citation_map.get("citations") if isinstance(citation_map.get("citations"), list) else []
    blocking_reasons: list[str] = []
    if not has_source_evidence:
        blocking_reasons.append("literature/source evidence was not supplied")
    if not citations:
        blocking_reasons.append("source-backed citation entries are missing")
    traceable_citations = [
        item
        for item in citations
        if isinstance(item, dict)
        and str(item.get("citation_id") or item.get("title") or "").strip()
        and str(item.get("source_ref") or item.get("path") or item.get("arxiv_id") or item.get("url") or "").strip()
    ]
    minimum_citation_count = 1 if requested_limit == 1 else 2
    if len(citations) < minimum_citation_count:
        blocking_reasons.append(f"fewer than {minimum_citation_count} distinct citation entries were supplied")
    if len(traceable_citations) != len(citations):
        blocking_reasons.append("one or more citation entries lack a traceable source reference")
    final_coverage_ready = not blocking_reasons
    return {
        "schema": "autosci_survey_final_coverage_boundary.v1",
        "status": "final_coverage_ready" if final_coverage_ready else "survey_coverage_incomplete",
        "final_coverage_ready": final_coverage_ready,
        "coverage_scope": "bounded_source_backed" if final_coverage_ready else "incomplete",
        "exhaustive_coverage_verified": False,
        "source_evidence_supplied": has_source_evidence,
        "citation_count": len(citations),
        "traceable_citation_count": len(traceable_citations),
        "minimum_citation_count": minimum_citation_count,
        "requested_limit": requested_limit,
        "citation_ids": _unique_strings([str(item.get("citation_id") or item.get("title") or "") for item in citations if isinstance(item, dict)]),
        "blocking_reasons": blocking_reasons,
        "limitations": [
            "Survey coverage is bounded to supplied source/citation evidence and does not claim exhaustive live literature coverage."
        ]
        if final_coverage_ready
        else [
            "Final survey coverage requires supplied source evidence and at least one source-backed citation entry."
        ],
    }


def _survey_citation_key(citation: dict[str, Any]) -> str:
    raw = str(citation.get("citation_id") or citation.get("title") or "survey-source")
    arxiv_id = str(citation.get("arxiv_id") or "").strip()
    if arxiv_id:
        raw = f"arxiv-{arxiv_id}"
    return _slug(raw).replace("-", "")[:48] or "surveysource"


def _survey_citation_marker(citation: dict[str, Any], requested_format: str) -> str:
    key = _survey_citation_key(citation)
    if requested_format in {"latex", "tex"}:
        return f"\\cite{{{key}}}"
    wiki_slug = str(citation.get("path") or citation.get("citation_id") or citation.get("title") or key)
    return f"[[{Path(wiki_slug).stem}]]"


def _survey_apply_max_papers(citation_map: dict[str, Any], max_papers: int) -> dict[str, Any]:
    citations = citation_map.get("citations") if isinstance(citation_map.get("citations"), list) else []
    if max_papers <= 0 or len(citations) <= max_papers:
        return citation_map
    limited = dict(citation_map)
    limited["citations"] = citations[:max_papers]
    limited["citation_count"] = len(limited["citations"])
    limitations = list(limited.get("limitations") or [])
    limitations.append(f"Citation map was capped to max_papers={max_papers}.")
    limited["limitations"] = _unique_strings([str(item) for item in limitations])
    return limited


def _survey_theme_sections(
    *,
    citations: list[dict[str, Any]],
    evidence_ids: list[str],
    target: str,
    requested_format: str,
) -> list[dict[str, Any]]:
    if not citations:
        return [
            {
                "section_id": "themes",
                "title": "Themes",
                "evidence_ids": evidence_ids,
                "body": "No source-backed papers were available for thematic grouping.",
            }
        ]
    groups: dict[str, list[dict[str, Any]]] = {}
    for citation in citations:
        channels = citation.get("source_channels") if isinstance(citation.get("source_channels"), list) else []
        source = str(citation.get("source") or (channels[0] if channels else "") or "source").lower()
        if "wiki" in source or "wiki" in [str(item).lower() for item in channels]:
            group = "Wiki-Registered Prior Work"
        elif "reference" in source or "references" in [str(item).lower() for item in channels]:
            group = "Reference-Graph Neighbors"
        elif "semantic" in source or "s2" in source:
            group = "Semantic Retrieval Candidates"
        else:
            group = "Source-Backed Related Work"
        groups.setdefault(group, []).append(citation)
    sections: list[dict[str, Any]] = []
    for index, (group, group_citations) in enumerate(groups.items(), start=1):
        cited = []
        for citation in group_citations[:8]:
            title = str(citation.get("title") or citation.get("citation_id") or "Untitled source")
            cited.append(f"{title} {_survey_citation_marker(citation, requested_format)}")
        body = (
            f"{group} frames `{target}` through {len(group_citations)} source-backed citation(s). "
            f"{'; '.join(cited)}. "
            "Unlike a flat paper list, this group is used to position the current work by shared source channel, evidence role, and methodological proximity recorded in the wiki/citation map."
        )
        sections.append({
            "section_id": f"theme-{index}",
            "title": group,
            "evidence_ids": _unique_strings([
                *evidence_ids,
                *[str(item.get("citation_id") or item.get("title") or "") for item in group_citations],
            ]),
            "body": body,
        })
    return sections


def _survey_source_signal_sections(
    *,
    citations: list[dict[str, Any]],
    evidence_ids: list[str],
    target: str,
) -> list[dict[str, Any]]:
    source_ids = _unique_strings([
        str(item.get("citation_id") or item.get("title") or "")
        for item in citations
        if isinstance(item, dict) and str(item.get("citation_id") or item.get("title") or "").strip()
    ])
    if not source_ids:
        return []
    preview = []
    for citation in citations[:8]:
        title = str(citation.get("title") or citation.get("citation_id") or "Untitled source").strip()
        source_ref = str(citation.get("source_ref") or "").strip()
        preview.append(f"- `{str(citation.get('citation_id') or title)}`: {title} ({source_ref or 'source reference unavailable'})")
    source_list = "\n".join(preview)
    grounded_ids = _unique_strings([*evidence_ids, *source_ids])
    sections = [
        {
            "section_id": "method-evidence-signals",
            "title": "Method Evidence Signals",
            "evidence_ids": grounded_ids,
            "body": (
                f"Source-backed method signals for `{target}` are bounded to the retrieved titles and provider metadata, "
                "not full-text method extraction. The shortlist indicates method/evaluation context in these sources:\n\n"
                f"{source_list}"
            ),
        },
        {
            "section_id": "technical-claim-evidence-signals",
            "title": "Technical Claim Evidence Signals",
            "evidence_ids": grounded_ids,
            "body": (
                f"Technical-claim signals for `{target}` are source-level hypotheses for follow-up review. "
                "They are traceable to the retrieved public source ids and should be promoted only after full-text verification:\n\n"
                f"{source_list}"
            ),
        },
        {
            "section_id": "experiment-evidence-signals",
            "title": "Experiment Evidence Signals",
            "evidence_ids": grounded_ids,
            "body": (
                f"Experiment/evidence signals for `{target}` are inferred from source titles, provider metadata, and citation-map inclusion. "
                "This section records which public sources can support later benchmark/result extraction:\n\n"
                f"{source_list}"
            ),
        },
    ]
    if len(source_ids) >= 2:
        sections.append({
            "section_id": "cross-source-trend-comparison",
            "title": "Cross-Source Trend Comparison",
            "evidence_ids": grounded_ids,
            "body": (
                f"Across {len(source_ids)} retrieved source-backed records for `{target}`, the recurring pattern is evaluation-method evidence around retrieval, "
                "generation, and benchmark-style comparison. This is a citation-map trend, not a claim that every paper reports the same experimental result."
            ),
        })
    sections.append({
        "section_id": "evidence-gap-and-uncertainty",
        "title": "Evidence Gap and Uncertainty",
        "evidence_ids": grounded_ids,
        "body": (
            "The current survey can support source-backed shortlist, signal, and trend triage, but it does not claim exhaustive coverage or full-text extraction. "
            "Remaining uncertainty: exact methods, measured effects, and negative/contradictory findings require paper-level extraction before final synthesis."
        ),
    })
    return sections


def _survey_bibtex_coverage(
    envelope: dict[str, Any],
    *,
    citation_map: dict[str, Any],
) -> dict[str, str]:
    citations = citation_map.get("citations") if isinstance(citation_map.get("citations"), list) else []
    entries: list[dict[str, Any]] = []
    for citation in citations:
        if not isinstance(citation, dict):
            continue
        key = _survey_citation_key(citation)
        title = str(citation.get("title") or key)
        source_ref = str(citation.get("source_ref") or "")
        arxiv_id = str(citation.get("arxiv_id") or "")
        bibtex = str(citation.get("bibtex") or "").strip()
        verified = bool(bibtex)
        if not bibtex:
            bibtex = (
                f"@misc{{{key},\n"
                f"  title = {{{title} [UNCONFIRMED]}},\n"
                f"  note = {{{source_ref or arxiv_id or 'source-backed citation without fetched BibTeX'}}}\n"
                "}"
            )
        entries.append({
            "key": key,
            "title": title,
            "source_ref": source_ref,
            "arxiv_id": arxiv_id,
            "verified": verified,
            "bibtex": bibtex,
        })
    payload = {
        "schema": "autosci_survey_bibtex_coverage.v1",
        "status": "completed" if entries else "inconclusive",
        "entry_count": len(entries),
        "verified_count": sum(1 for item in entries if item["verified"]),
        "unconfirmed_count": sum(1 for item in entries if not item["verified"]),
        "entries": entries,
        "limitations": [] if entries else ["No citation entries were available for BibTeX coverage."],
    }
    path = _write_json_sidecar(_output_dir(envelope, "write_survey") / "survey_bibtex_coverage.json", payload)
    return {"type": "survey_bibtex_coverage_json", "path": path}


def _write_survey_archive_writeback(
    envelope: dict[str, Any],
    *,
    title: str,
    target: str,
    markdown_path: str,
    citation_map: dict[str, Any],
    evidence_ids: list[str],
    coverage_boundary: dict[str, Any],
) -> list[dict[str, str]]:
    if coverage_boundary.get("final_coverage_ready") is not True:
        return []
    wiki_root = _wiki_roots_for_write(envelope)[0]
    outputs_dir = wiki_root / "outputs"
    graph_dir = wiki_root / "graph"
    outputs_dir.mkdir(parents=True, exist_ok=True)
    graph_dir.mkdir(parents=True, exist_ok=True)
    slug = _slug(target or title or "survey")
    date_stamp = datetime.now(UTC).date().isoformat()
    output_path = outputs_dir / f"related-work-{slug}-{date_stamp}.md"
    markdown_abs = _resolve_harness_path(markdown_path)
    body = markdown_abs.read_text(encoding="utf-8", errors="replace") if markdown_abs.exists() else ""
    output_path.write_text(
        "\n".join(
            [
                "---",
                f"title: \"Related Work: {title}\"",
                "type: related-work",
                f"format: {str((envelope.get('inputs') or {}).get('format') or 'markdown')}",
                f"paper_count: {int(citation_map.get('citation_count') or 0)}",
                f"date_generated: {date_stamp}",
                "---",
                "",
                body,
            ]
        ).rstrip()
        + "\n",
        encoding="utf-8",
    )
    edge_path = graph_dir / "edges.jsonl"
    edge_count = 0
    with edge_path.open("a", encoding="utf-8") as handle:
        for citation in citation_map.get("citations") or []:
            if not isinstance(citation, dict):
                continue
            to_ref = str(citation.get("path") or citation.get("citation_id") or citation.get("title") or "").strip()
            if not to_ref:
                continue
            handle.write(json.dumps({
                "from": f"outputs/{output_path.stem}",
                "to": to_ref,
                "type": "derived_from",
                "evidence": "Cited in related work section",
            }, sort_keys=True) + "\n")
            edge_count += 1
    log_path = _write_generic_wiki_log(
        wiki_root,
        "Survey Archive",
        output_path,
        evidence_ids,
        f"survey | {target or title} | {int(citation_map.get('citation_count') or 0)} papers, format: {str((envelope.get('inputs') or {}).get('format') or 'markdown')}",
    )
    timestamp = datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    writeback = {
        "schema": "autosci_survey_archive_writeback.v1",
        "status": "completed",
        "generated_at": timestamp,
        "outputs": {
            "write": {
                "applied": True,
                "wiki_root": _rel(wiki_root),
                "target_path": _rel(output_path),
                "log_path": _rel(log_path),
                "edge_path": _rel(edge_path),
                "citation_count": int(citation_map.get("citation_count") or 0),
                "edge_count": edge_count,
            }
        },
        "artifacts": [
            {"type": "wiki_page", "path": _rel(output_path)},
            {"type": "wiki_graph_edges", "path": _rel(edge_path)},
            {"type": "wiki_log", "path": _rel(log_path)},
        ],
        "limitations": [],
    }
    writeback_path = _output_dir(envelope, "write_survey") / "survey_archive_writeback.json"
    writeback_artifact = {"type": "survey_archive_writeback_json", "path": _write_json_sidecar(writeback_path, writeback)}
    proof_artifact = _write_wiki_mutation_runtime_proof_manifest(
        envelope,
        action="write_survey",
        native_skill="survey",
        writeback_path=writeback_path,
        writeback=writeback,
    )
    artifacts = [writeback_artifact, *writeback["artifacts"]]
    if proof_artifact is not None:
        artifacts.append(proof_artifact)
    return artifacts


def _paper_plan_final_acceptance_boundary(
    citation_map: dict[str, Any],
    review_boundary: dict[str, Any],
    compile_handoff: dict[str, Any],
    idea_graph_map: dict[str, Any],
    *,
    has_source_evidence: bool,
    section_ids: list[str],
) -> dict[str, Any]:
    citations = citation_map.get("citations") if isinstance(citation_map.get("citations"), list) else []
    review_completed = bool(review_boundary.get("completed"))
    compile_verified = bool(compile_handoff.get("verified")) and str(compile_handoff.get("status") or "") == "completed"
    pdf_paths = [str(item) for item in compile_handoff.get("pdf_paths") or [] if str(item).strip()]
    has_figure_citation_plan = "figure-citation-plan" in set(section_ids)
    idea_graph_ready = bool(idea_graph_map.get("idea_graph_ready"))
    blocking_reasons: list[str] = []
    if not idea_graph_ready:
        blocking_reasons.append("validated idea graph with succeeded experiment evidence is missing")
    if not has_source_evidence:
        blocking_reasons.append("source evidence was not supplied")
    if not citations:
        blocking_reasons.append("source-backed citation plan is missing")
    if not has_figure_citation_plan:
        blocking_reasons.append("figure/citation plan section is missing")
    if not review_completed:
        blocking_reasons.append("completed Review LLM boundary evidence is missing")
    if not compile_verified:
        blocking_reasons.append("verified downstream compile/PDF handoff is missing")
    final_ready = not blocking_reasons
    return {
        "schema": "autosci_paper_plan_final_acceptance_boundary.v1",
        "status": "final_plan_accepted" if final_ready else "paper_plan_final_acceptance_incomplete",
        "final_plan_accepted": final_ready,
        "draft_compile_ready": final_ready,
        "plan_scope": "source_review_compile_ready" if final_ready else "plan_scaffold",
        "source_evidence_supplied": has_source_evidence,
        "idea_graph_ready": idea_graph_ready,
        "idea_count": len(idea_graph_map.get("ideas") or []),
        "supporting_experiment_count": len(idea_graph_map.get("supporting_experiments") or []),
        "citation_count": len(citations),
        "citation_ids": _unique_strings([
            str(item.get("citation_id") or item.get("title") or "")
            for item in citations
            if isinstance(item, dict)
        ]),
        "figure_citation_plan_present": has_figure_citation_plan,
        "review_llm_completed": review_completed,
        "review_boundary_status": str(review_boundary.get("status") or "missing"),
        "review_evidence_ids": _unique_strings([str(item) for item in review_boundary.get("evidence_ids") or []]),
        "compile_handoff_status": str(compile_handoff.get("status") or "not_requested"),
        "compile_handoff_verified": compile_verified,
        "compiled_pdf_paths": pdf_paths,
        "blocking_reasons": blocking_reasons,
        "limitations": (
            [
                "Paper plan final acceptance is bounded to supplied source evidence, Review LLM proof, and verified compile/PDF handoff."
            ]
            if final_ready
            else [
                "Paper plan final acceptance requires validated idea graph evidence, source-backed citation planning, completed Review LLM proof, and verified downstream compile/PDF handoff."
            ]
        ),
    }


def _paper_plan_target_slugs(target: str) -> list[str]:
    values = re.split(r"[\s,]+", str(target or "").strip())
    slugs: list[str] = []
    for value in values:
        value = value.strip().strip("[]")
        if not value:
            continue
        name = Path(value).stem if "/" in value else value
        if name.startswith("idea-"):
            slugs.append(name.removeprefix("idea-"))
        slugs.append(name)
    return _unique_strings([_slug(item) for item in slugs if item])


def _frontmatter_value(text: str, key: str) -> str:
    match = re.search(rf"(?m)^\s*{re.escape(key)}\s*:\s*(.+?)\s*$", text)
    if not match:
        return ""
    return match.group(1).strip().strip("'\"")


def _frontmatter_list(text: str, key: str) -> list[str]:
    raw = _frontmatter_value(text, key)
    if not raw:
        return []
    if raw.startswith("[") and raw.endswith("]"):
        raw = raw[1:-1]
    return _unique_strings([item.strip().strip("'\"") for item in raw.split(",") if item.strip()])


def _paper_plan_idea_graph_map(envelope: dict[str, Any], *, target: str) -> dict[str, Any]:
    slugs = _paper_plan_target_slugs(target)
    ideas: list[dict[str, Any]] = []
    experiments: list[dict[str, Any]] = []
    references: list[dict[str, Any]] = []
    checked_roots: list[str] = []
    for root in _wiki_roots_for_read(envelope):
        checked_roots.append(_rel(root))
        for slug in slugs:
            idea_path = root / "ideas" / f"{slug}.md"
            if not idea_path.exists():
                continue
            text = idea_path.read_text(encoding="utf-8", errors="replace")
            status = _frontmatter_value(text, "status") or "unknown"
            novelty_score = _frontmatter_value(text, "novelty_score")
            linked_experiments = _frontmatter_list(text, "linked_experiments")
            idea_refs = []
            for link in re.findall(r"\[\[([^\]|#]+)", text):
                ref_slug = _slug(link)
                for directory, ref_type in (
                    ("methods", "method"),
                    ("concepts", "concept"),
                    ("topics", "topic"),
                    ("papers", "paper"),
                ):
                    ref_path = root / directory / f"{ref_slug}.md"
                    if ref_path.exists():
                        references.append({"type": ref_type, "slug": ref_slug, "path": _rel(ref_path)})
                        idea_refs.append(ref_slug)
                        break
            ideas.append({
                "slug": slug,
                "status": status,
                "novelty_score": novelty_score,
                "path": _rel(idea_path),
                "linked_experiments": linked_experiments,
                "referenced_entities": _unique_strings(idea_refs),
            })
            for exp_slug in linked_experiments:
                exp_name = _slug(exp_slug)
                exp_path = root / "experiments" / f"{exp_name}.md"
                if not exp_path.exists():
                    continue
                exp_text = exp_path.read_text(encoding="utf-8", errors="replace")
                exp_status = _frontmatter_value(exp_text, "status") or ("succeeded" if re.search(r"\bsucceeded\b", exp_text, re.IGNORECASE) else "unknown")
                experiments.append({
                    "slug": exp_name,
                    "status": exp_status,
                    "path": _rel(exp_path),
                    "linked_idea": slug,
                    "key_result": _frontmatter_value(exp_text, "key_result"),
                })
    validated = [idea for idea in ideas if str(idea.get("status") or "").lower() in {"validated", "in_progress"}]
    succeeded = [exp for exp in experiments if str(exp.get("status") or "").lower() in {"succeeded", "success", "completed"}]
    ready = bool(validated and succeeded)
    return {
        "schema": "autosci_paper_plan_idea_graph_map.v1",
        "status": "completed" if ready else "incomplete",
        "idea_graph_ready": ready,
        "target": target,
        "target_slugs": slugs,
        "checked_roots": checked_roots,
        "ideas": ideas,
        "supporting_experiments": experiments,
        "referenced_entities": references,
        "limitations": [] if ready else ["Paper plan requires at least one validated/in-progress idea with a succeeded linked experiment."],
    }


def _native_publication_review_completed(envelope: dict[str, Any]) -> bool:
    return bool(_native_publication_review_boundary(envelope).get("completed"))


def _review_evidence_ids(review: dict[str, Any], review_llm: dict[str, Any]) -> list[str]:
    values: list[str] = []
    for source in (review, review_llm):
        raw = source.get("evidence_ids") if isinstance(source, dict) else []
        if isinstance(raw, list):
            values.extend(str(item) for item in raw if str(item).strip())
    return _unique_strings(values)


def _native_publication_review_boundary(envelope: dict[str, Any]) -> dict[str, Any]:
    checked: list[str] = []
    invalid_reasons: list[str] = []
    for payload in _phase14_source_payloads(envelope):
        if payload.get("schema") != "artifact_review.v1" or payload.get("status") != "completed":
            continue
        source_path = str(payload.get("source_path") or payload.get("task_id") or payload.get("node_id") or "artifact_review.v1")
        checked.append(source_path)
        review = ((payload.get("outputs") or {}).get("review") or {})
        if not isinstance(review, dict):
            invalid_reasons.append(f"{source_path}: missing outputs.review object")
            continue
        review_llm = review.get("review_llm") if isinstance(review.get("review_llm"), dict) else {}
        review_mode = str(review.get("review_mode") or "").strip()
        review_available = review.get("review_available") is True
        evidence_ids = _review_evidence_ids(review, review_llm)
        llm_status = str(review_llm.get("status") or "").strip()
        if review_mode not in {"review_llm", "llm_review", "external_review"}:
            invalid_reasons.append(f"{source_path}: review_mode is not Review LLM-backed")
            continue
        if not review_available:
            invalid_reasons.append(f"{source_path}: review_available is not true")
            continue
        if not evidence_ids:
            invalid_reasons.append(f"{source_path}: Review LLM evidence ids are missing")
            continue
        if review_llm and llm_status != "completed":
            invalid_reasons.append(f"{source_path}: nested review_llm status is not completed")
            continue
        invocation_mode = str(review_llm.get("invocation_mode") or "evidence").strip() or "evidence"
        boundary = {
            "schema": "autosci_publication_review_boundary.v1",
            "status": "completed",
            "completed": True,
            "source_path": str(review_llm.get("source_path") or review_llm.get("archive_path") or source_path),
            "source_task_id": str(payload.get("task_id") or ""),
            "review_mode": review_mode,
            "review_available": True,
            "invocation_mode": invocation_mode,
            "provider": str(review_llm.get("provider") or ""),
            "model": str(review_llm.get("model") or ""),
            "request_sha256": str(review_llm.get("request_sha256") or ""),
            "response_sha256": str(review_llm.get("response_sha256") or ""),
            "score": review.get("score", review_llm.get("score")),
            "recommendation": str(review.get("recommendation") or review_llm.get("recommendation") or "inconclusive"),
            "evidence_ids": evidence_ids,
            "checked_reviews": checked,
            "invalid_reasons": invalid_reasons,
            "limitations": [],
        }
        if invocation_mode == "evidence":
            boundary["limitations"].append(
                "Review LLM evidence was supplied externally; hosted provider or command provenance is not claimed."
            )
        return boundary
    return {
        "schema": "autosci_publication_review_boundary.v1",
        "status": "inconclusive" if not invalid_reasons else "invalid",
        "completed": False,
        "checked_reviews": checked,
        "invalid_reasons": invalid_reasons,
        "limitations": [
            "No completed Review LLM boundary evidence was available for publication planning."
            if not invalid_reasons
            else "Supplied Review LLM evidence did not satisfy publication planning boundary checks."
        ],
    }


def _native_report_paths(envelope: dict[str, Any], action: str) -> dict[str, Path]:
    output_dir = _output_dir(envelope, action)
    return {
        "plan_json": _configured_output_path(envelope, "plan_json_path", output_dir / f"{action}_plan.json"),
        "markdown": _configured_output_path(envelope, "markdown_path", output_dir / f"{action}.md"),
        "citation_map": _configured_output_path(envelope, "citation_map_path", output_dir / f"{action}_citation_map.json"),
    }


def _native_report_markdown(title: str, sections: list[dict[str, Any]], limitations_list: list[str]) -> str:
    lines = [f"# {title}", ""]
    for section in sections:
        lines.extend([f"## {section.get('title', 'Section')}", ""])
        body = str(section.get("body") or "")
        if body:
            lines.extend([body, ""])
        evidence_ids = ", ".join(str(item) for item in section.get("evidence_ids") or [])
        lines.extend([f"Evidence ids: {evidence_ids or 'N/A'}", ""])
    if limitations_list:
        lines.extend(["## Limitations", ""])
        lines.extend(f"- {limitation}" for limitation in limitations_list)
        lines.append("")
    return "\n".join(lines).rstrip() + "\n"


def _action_plan_report(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    paths = _native_report_paths(envelope, "plan_report")
    title = _native_publication_title(envelope, "AutoSci Paper Plan")
    target = _native_publication_target(envelope)
    evidence_ids = _native_publication_evidence_ids(envelope, "paper-plan:request")
    has_source_evidence = _native_publication_has_source_evidence(envelope)
    citation_map = _native_publication_citation_map(envelope)
    has_citations = bool(citation_map.get("citations"))
    idea_graph_map = _paper_plan_idea_graph_map(envelope, target=target)
    idea_graph_ready = bool(idea_graph_map.get("idea_graph_ready"))
    if idea_graph_ready:
        evidence_ids = _unique_strings([
            *evidence_ids,
            *[str(item.get("slug") or "") for item in idea_graph_map.get("ideas") or []],
            *[str(item.get("slug") or "") for item in idea_graph_map.get("supporting_experiments") or []],
        ])
    if has_citations:
        evidence_ids = _unique_strings([
            *evidence_ids,
            *[
                str(item.get("citation_id") or item.get("title") or "")
                for item in citation_map.get("citations") or []
                if isinstance(item, dict)
            ],
        ])
    review_boundary = _native_publication_review_boundary(envelope)
    has_review_llm = bool(review_boundary.get("completed"))
    if has_review_llm:
        evidence_ids = _unique_strings([*evidence_ids, *[str(item) for item in review_boundary.get("evidence_ids") or []]])
    compile_requested = bool(
        inputs.get("approval_ref")
        or inputs.get("runtime_evidence")
        or inputs.get("after_artifacts")
        or inputs.get("allowlist_evidence")
        or inputs.get("before_artifacts")
        or inputs.get("supplied_compile_target_evidence")
    )
    compile_handoff, compile_artifacts, compile_limitations = _phase14_compile_handoff(
        envelope,
        requested=compile_requested,
    )
    if compile_handoff.get("status") == "completed":
        evidence_ids = _unique_strings([*evidence_ids, *[str(item) for item in compile_handoff.get("evidence_ids") or []]])
    limitations = [
        "Paper plan is generated from local Solar evidence, request metadata, and supplied source/review evidence.",
    ]
    if not has_source_evidence:
        limitations.append("No source evidence was supplied; plan remains a scaffold until linked evidence is provided.")
    if not has_citations:
        limitations.append("No source-backed citation map was available; citation slots remain incomplete.")
    if not idea_graph_ready:
        limitations.extend(str(item) for item in idea_graph_map.get("limitations") or [])
    if not has_review_llm:
        limitations.append("No completed Review LLM evidence was supplied; plan remains pre-review.")
    limitations.extend(str(item) for item in review_boundary.get("limitations") or [])
    limitations.extend(compile_limitations)
    citation_preview = citation_map.get("citations") or []
    citation_body = "\n".join(
        f"- `{item.get('citation_id')}`: {item.get('title')} ({item.get('source_ref')})"
        for item in citation_preview[:8]
    ) or "No source-backed citation entries were available."
    sections = [
        {
            "section_id": "outline",
            "title": "Outline Plan",
            "evidence_ids": evidence_ids,
            "body": f"Plan a paper around target `{target}` with title `{title}`.",
        },
        {
            "section_id": "idea-evidence-map",
            "title": "Idea Evidence Map",
            "evidence_ids": evidence_ids,
            "body": (
                f"Idea graph ready: `{idea_graph_ready}`. "
                f"Validated/in-progress ideas: `{len(idea_graph_map.get('ideas') or [])}`. "
                f"Supporting experiments: `{len(idea_graph_map.get('supporting_experiments') or [])}`."
            ),
        },
        {
            "section_id": "evidence-map",
            "title": "Evidence Map",
            "evidence_ids": evidence_ids,
            "body": "Every planned claim, figure, and table must be backed by explicit evidence ids before drafting.",
        },
        {
            "section_id": "figure-citation-plan",
            "title": "Figure And Citation Plan",
            "evidence_ids": evidence_ids,
            "body": f"Citation map contains `{citation_map.get('citation_count', 0)}` source-backed entries.\n\n{citation_body}",
        },
        {
            "section_id": "review-gates",
            "title": "Review Gates",
            "evidence_ids": evidence_ids,
            "body": (
                f"Review LLM boundary status: `{review_boundary.get('status', 'missing')}`. "
                f"Invocation mode: `{review_boundary.get('invocation_mode', 'N/A')}`. "
                f"Source: `{review_boundary.get('source_path', 'N/A')}`. "
                "Novelty/relevance checks remain required before promotion beyond plan status."
            ),
        },
        {
            "section_id": "compile-audit",
            "title": "Compile Audit",
            "evidence_ids": compile_handoff.get("evidence_ids") or evidence_ids,
            "body": f"Compile/PDF handoff status: `{compile_handoff.get('status', 'not_requested')}`.",
        },
        {
            "section_id": "limitations",
            "title": "Limitations",
            "evidence_ids": evidence_ids,
            "body": "This is a bounded planning artifact, not a compiled manuscript or external-review result.",
        },
    ]
    final_acceptance_boundary = _paper_plan_final_acceptance_boundary(
        citation_map,
        review_boundary,
        compile_handoff,
        idea_graph_map,
        has_source_evidence=has_source_evidence,
        section_ids=[str(section.get("section_id") or "") for section in sections if isinstance(section, dict)],
    )
    limitations.extend(str(item) for item in final_acceptance_boundary.get("limitations") or [])
    sections.insert(
        -1,
        {
            "section_id": "final-plan-acceptance-boundary",
            "title": "Final Plan Acceptance Boundary",
            "evidence_ids": evidence_ids,
            "body": (
                f"Final plan acceptance status: `{final_acceptance_boundary.get('status')}`. "
                f"Draft/compile ready: `{final_acceptance_boundary.get('draft_compile_ready')}`. "
                f"Review LLM completed: `{final_acceptance_boundary.get('review_llm_completed')}`. "
                f"Compile handoff verified: `{final_acceptance_boundary.get('compile_handoff_verified')}`."
            ),
        },
    )
    plan_payload = {
        "title": title,
        "target": target,
        "evidence_ids": evidence_ids,
        "sections": [
            {
                "section_id": section["section_id"],
                "title": section["title"],
                "evidence_ids": section["evidence_ids"],
            }
            for section in sections
        ],
        "limitations": limitations,
        "citation_map": citation_map,
        "idea_graph_map": idea_graph_map,
        "review_llm_completed": has_review_llm,
        "review_boundary": review_boundary,
        "compile_handoff": compile_handoff,
        "final_acceptance_boundary": final_acceptance_boundary,
    }
    plan_path = _write_json_sidecar(paths["plan_json"], plan_payload)
    citation_map_path = _write_json_sidecar(paths["citation_map"], citation_map)
    idea_graph_map_path = _write_json_sidecar(
        paths["markdown"].parent / "paper_plan_idea_graph_map.json",
        idea_graph_map,
    )
    final_boundary_path = _write_json_sidecar(
        paths["markdown"].parent / "paper_plan_final_acceptance_boundary.json",
        final_acceptance_boundary,
    )
    markdown_path = _write_text_sidecar(paths["markdown"], _native_report_markdown(title, sections, limitations))
    evidence_payload_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        _output_dir(envelope, "plan_report") / "plan_report.evidence.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    review_runtime_proof_artifact = _write_review_context_runtime_proof_manifest(
        envelope,
        action="plan_report",
        native_skill="paper-plan",
        evidence_path=evidence_payload_path,
        review_llm=review_boundary,
    )
    source_runtime_proof_artifact = _write_publication_source_runtime_proof_manifest(
        envelope,
        action="plan_report",
        native_skill="paper-plan",
        evidence_path=evidence_payload_path,
        citation_map=citation_map,
        artifact_refs=[plan_path, markdown_path, citation_map_path, idea_graph_map_path, final_boundary_path],
    )
    artifacts = [
        {"type": "paper_plan_json", "path": plan_path},
        {"type": "paper_plan_markdown", "path": markdown_path},
        {"type": "citation_map_json", "path": citation_map_path},
        {"type": "paper_plan_idea_graph_map_json", "path": idea_graph_map_path},
        {"type": "paper_plan_final_acceptance_boundary_json", "path": final_boundary_path},
        *compile_artifacts,
    ]
    if review_runtime_proof_artifact is not None:
        artifacts.append(review_runtime_proof_artifact)
    if source_runtime_proof_artifact is not None:
        artifacts.append(source_runtime_proof_artifact)
    return convert_scientific_report({
        "report_id": f"paper-plan-{_slug(title)}",
        "title": title,
        "sections": sections,
        "evidence_ids": evidence_ids,
        "unsupported_claims": [],
        "compile_handoff": compile_handoff,
        "status": "completed" if final_acceptance_boundary.get("final_plan_accepted") else "inconclusive",
        "artifacts": artifacts,
        "limitations": limitations,
    }, envelope)


def _action_write_survey(envelope: dict[str, Any]) -> dict[str, Any]:
    paths = _native_report_paths(envelope, "write_survey")
    inputs = dict(envelope.get("inputs") or {})
    title = _native_publication_title(envelope, "AutoSci Literature Survey")
    target = _native_publication_target(envelope)
    evidence_ids = _native_publication_evidence_ids(envelope, "survey:request")
    has_source_evidence = _native_publication_has_source_evidence(envelope)
    citation_map = _native_publication_citation_map(envelope)
    try:
        max_papers = int(inputs.get("max_papers") or 30)
    except (TypeError, ValueError):
        max_papers = 30
    citation_map = _survey_apply_max_papers(citation_map, max_papers)
    has_citations = bool(citation_map.get("citations"))
    coverage_boundary = _survey_final_coverage_boundary(
        citation_map,
        has_source_evidence=has_source_evidence,
        requested_limit=max_papers,
    )
    limitations = [
        "Survey is assembled from local Solar evidence and supplied discovery/paper citation evidence.",
        *list(coverage_boundary.get("limitations") or []),
    ]
    if not has_source_evidence:
        limitations.append("No literature/source evidence was supplied; survey remains an evidence scaffold.")
    if not has_citations:
        limitations.append("No source-backed citation map was available; survey coverage remains incomplete.")
    citation_preview = citation_map.get("citations") or []
    citation_body = "\n".join(
        f"- `{item.get('citation_id')}`: {item.get('title')} ({item.get('source_ref')})"
        for item in citation_preview[:12]
    ) or "No source-backed citation entries were available."
    requested_format = str(inputs.get("format") or "").strip().lower()
    theme_sections = _survey_theme_sections(
        citations=[item for item in citation_preview if isinstance(item, dict)],
        evidence_ids=evidence_ids,
        target=target,
        requested_format=requested_format,
    )
    source_signal_sections = _survey_source_signal_sections(
        citations=[item for item in citation_preview if isinstance(item, dict)],
        evidence_ids=evidence_ids,
        target=target,
    )
    sections = [
        {
            "section_id": "scope",
            "title": "Scope",
            "evidence_ids": evidence_ids,
            "body": f"Survey scope: `{target}`.",
        },
        *theme_sections,
        *source_signal_sections,
        {
            "section_id": "prior-work-map",
            "title": "Prior Work Map",
            "evidence_ids": evidence_ids,
            "body": f"Citation map contains `{citation_map.get('citation_count', 0)}` source-backed entries.\n\n{citation_body}",
        },
        {
            "section_id": "limitations",
            "title": "Limitations",
            "evidence_ids": evidence_ids,
            "body": "This survey scaffold does not claim exhaustive literature coverage.",
        },
        {
            "section_id": "coverage-boundary",
            "title": "Coverage Boundary",
            "evidence_ids": evidence_ids,
            "body": (
                f"Survey final coverage boundary: `{coverage_boundary.get('status')}`. "
                f"Coverage scope: `{coverage_boundary.get('coverage_scope')}`. "
                f"Exhaustive coverage verified: `{coverage_boundary.get('exhaustive_coverage_verified')}`."
            ),
        },
    ]
    plan_path = _write_json_sidecar(paths["plan_json"], {
        "title": title,
        "target": target,
        "max_papers": max_papers,
        "survey_evidence_ids": evidence_ids,
        "citation_map": citation_map,
        "final_coverage_boundary": coverage_boundary,
        "limitations": limitations,
    })
    citation_map_path = _write_json_sidecar(paths["citation_map"], citation_map)
    coverage_boundary_path = _write_json_sidecar(
        paths["markdown"].parent / "survey_final_coverage_boundary.json",
        coverage_boundary,
    )
    markdown_path = _write_text_sidecar(paths["markdown"], _native_report_markdown(title, sections, limitations))
    artifacts = [
        {"type": "survey_plan_json", "path": plan_path},
        {"type": "survey_markdown", "path": markdown_path},
        {"type": "citation_map_json", "path": citation_map_path},
        {"type": "survey_final_coverage_boundary_json", "path": coverage_boundary_path},
    ]
    evidence_payload_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        _output_dir(envelope, "write_survey") / "scientific_report.survey.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    source_runtime_proof_artifact = _write_publication_source_runtime_proof_manifest(
        envelope,
        action="write_survey",
        native_skill="survey",
        evidence_path=evidence_payload_path,
        citation_map=citation_map,
        artifact_refs=[plan_path, markdown_path, citation_map_path, coverage_boundary_path],
    )
    if source_runtime_proof_artifact is not None:
        artifacts.append(source_runtime_proof_artifact)
    bibtex_artifact = None
    if requested_format in {"latex", "tex"}:
        latex_path = _configured_output_path(envelope, "latex_path", paths["markdown"].with_suffix(".tex"))
        bibtex_artifact = _survey_bibtex_coverage(envelope, citation_map=citation_map)
        artifacts.append(bibtex_artifact)
        latex_report = {
            "title": title,
            "sections": sections,
        }
        artifacts.append(
            {
                "type": "survey_latex_source",
                "path": _write_text_sidecar(latex_path, _render_latex_paper(latex_report, limitations)),
            }
        )
    artifacts.extend(
        _write_survey_archive_writeback(
            envelope,
            title=title,
            target=target,
            markdown_path=markdown_path,
            citation_map=citation_map,
            evidence_ids=evidence_ids,
            coverage_boundary=coverage_boundary,
        )
    )
    return convert_scientific_report({
        "report_id": f"survey-{_slug(title)}",
        "title": title,
        "sections": sections,
        "evidence_ids": evidence_ids,
        "unsupported_claims": [],
        "status": "completed" if has_source_evidence and has_citations else "inconclusive",
        "artifacts": artifacts,
        "limitations": limitations,
    }, envelope)


