def _rebuttal_evidence_values(raw_value: Any) -> list[str]:
    values = raw_value if isinstance(raw_value, list) else [raw_value] if raw_value else []
    out: list[str] = []
    for value in values:
        text = str(value or "").strip()
        if not text:
            continue
        if "," in text and "\n" not in text and not text.lstrip().startswith(("{", "[")):
            out.extend(part.strip() for part in text.split(",") if part.strip())
        else:
            out.append(text)
    return out


def _looks_like_reviewer_text(text: str) -> bool:
    normalized = text.strip().lower()
    return bool(
        normalized
        and (
            "\n" in text
            or len(normalized) > 80
            or normalized.startswith(("reviewer", "review ", "meta-review", "meta review"))
        )
    )


def _looks_like_path_reference(text: str) -> bool:
    stripped = text.strip()
    if not stripped or "\n" in stripped:
        return False
    return "/" in stripped or "\\" in stripped or bool(Path(stripped).suffix)


def _rebuttal_review_sources(envelope: dict[str, Any]) -> list[dict[str, Any]]:
    inputs = dict(envelope.get("inputs") or {})
    sources: list[dict[str, Any]] = []

    def add_source(raw: str, *, direct_label: str, direct_evidence_id: str) -> None:
        path = _resolve_harness_path(raw)
        if path.exists() and path.is_file():
            if path.suffix.lower() == ".json":
                try:
                    payload = _load_json(path)
                except Exception:  # noqa: BLE001
                    return
                if isinstance(payload, dict):
                    source_payload = dict(payload)
                    source_payload.setdefault("source_path", _rel(path))
                    sources.append({"kind": "payload", "payload": source_payload, "source_path": _rel(path)})
            else:
                sources.append({
                    "kind": "text",
                    "text": _read_limited_text(path),
                    "source_path": _rel(path),
                    "evidence_id": f"review-thread:{_slug(path.stem)}",
                })
        elif _looks_like_reviewer_text(raw) and not _looks_like_path_reference(raw):
            sources.append({
                "kind": "text",
                "text": raw,
                "source_path": direct_label,
                "evidence_id": direct_evidence_id,
            })

    for raw in _rebuttal_evidence_values(inputs.get("reviewer_thread_evidence")):
        add_source(raw, direct_label="direct:reviewer-thread", direct_evidence_id="review-thread:direct")

    target = str(inputs.get("target") or "").strip()
    if target:
        target_values = _rebuttal_evidence_values(target)
        if len(target_values) <= 1 or not all(_looks_like_path_reference(value) for value in target_values):
            target_values = [target]
        for target_value in target_values:
            add_source(target_value, direct_label="direct:target", direct_evidence_id="review-thread:target")
    return sources


def _rebuttal_text_segments(text: str) -> list[str]:
    bullet_segments: list[str] = []
    paragraph_segments: list[str] = []
    current: list[str] = []
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            if current:
                paragraph_segments.append(" ".join(current).strip())
                current = []
            continue
        bullet = re.match(r"^(?:[-*•]|\d+[.)])\s+(.*)$", line)
        if bullet:
            if current:
                paragraph_segments.append(" ".join(current).strip())
                current = []
            bullet_segments.append(bullet.group(1).strip())
        else:
            current.append(line)
    if current:
        paragraph_segments.append(" ".join(current).strip())
    segments = bullet_segments or paragraph_segments
    if len(segments) <= 1:
        split = [
            item.strip()
            for item in re.split(r"(?<=[.?])\s+(?=[A-Z0-9])", segments[0] if segments else text.strip())
            if item.strip()
        ]
        segments = split or segments
    return [segment for segment in segments if len(segment) >= 12]


def _rebuttal_review_sections_from_text(text: str) -> list[dict[str, Any]]:
    matches = list(re.finditer(r"(?im)^(reviewer\s*\d+|review\s*\d+|meta[- ]?review)\s*:?\s*$", text))
    if not matches:
        return [{"reviewer": "Reviewer 1", "items": _rebuttal_text_segments(text)}]
    sections: list[dict[str, Any]] = []
    for index, match in enumerate(matches):
        start = match.end()
        end = matches[index + 1].start() if index + 1 < len(matches) else len(text)
        reviewer = match.group(1).strip().replace("review ", "Reviewer ")
        body = text[start:end].strip()
        sections.append({"reviewer": reviewer, "items": _rebuttal_text_segments(body)})
    return sections


def _rebuttal_payload_thread_view(payload: dict[str, Any]) -> Any:
    outputs = payload.get("outputs") if isinstance(payload.get("outputs"), dict) else {}
    for source in (outputs, payload):
        for key in (
            "reviewer_thread",
            "reviewer_threads",
            "review_comments",
            "review_thread",
            "reviews",
            "reviewers",
            "comments",
            "concerns",
        ):
            if key in source:
                return source.get(key)
    return None


def _rebuttal_review_sections_from_payload(payload: dict[str, Any]) -> list[dict[str, Any]]:
    view = _rebuttal_payload_thread_view(payload)
    if isinstance(view, dict):
        for key in ("reviewers", "reviews", "comments", "concerns"):
            nested = view.get(key)
            if isinstance(nested, list):
                view = nested
                break
        else:
            return [{"reviewer": view.get("reviewer") or view.get("reviewer_id") or "Reviewer 1", "items": [view]}]
    if isinstance(view, str):
        return _rebuttal_review_sections_from_text(view)
    if isinstance(view, list):
        sections: list[dict[str, Any]] = []
        for index, item in enumerate(view, start=1):
            if isinstance(item, dict):
                reviewer = item.get("reviewer") or item.get("reviewer_id") or item.get("source") or f"Reviewer {index}"
                values: list[Any] = []
                for key in ("concerns", "comments", "weaknesses", "questions", "issues", "findings"):
                    raw = item.get(key)
                    if isinstance(raw, list):
                        values.extend(raw)
                    elif isinstance(raw, str):
                        values.extend(_rebuttal_text_segments(raw))
                if not values:
                    values.append(item)
                sections.append({"reviewer": reviewer, "items": values})
            elif isinstance(item, str):
                sections.append({"reviewer": f"Reviewer {index}", "items": _rebuttal_text_segments(item)})
        return sections
    return []


def _rebuttal_concern_text(item: Any) -> str:
    if isinstance(item, dict):
        for key in ("concern", "issue", "comment", "question", "weakness", "finding", "text", "summary"):
            value = str(item.get(key) or "").strip()
            if value:
                return value
    return str(item or "").strip()


def _rebuttal_concern_type(text: str, item: Any) -> tuple[str, str]:
    if isinstance(item, dict):
        raw = str(item.get("type") or item.get("category") or item.get("criterion") or item.get("focus") or "").strip()
        if raw:
            return raw, "structured"
    lower = text.lower()
    for category, keywords in REBUTTAL_CONCERN_TYPES.items():
        if any(keyword in lower for keyword in keywords):
            return category, "local_parser"
    return "review", "local_parser"


def _rebuttal_concern_severity(text: str, item: Any) -> tuple[str, str]:
    if isinstance(item, dict):
        raw = str(item.get("severity") or item.get("priority") or "").strip().lower()
        if raw in {"critical", "major", "minor"}:
            return raw, "structured"
    lower = text.lower()
    if any(word in lower for word in ("fatal", "invalid", "incorrect", "major", "critical")):
        return "critical", "local_parser"
    if any(word in lower for word in ("typo", "format", "minor", "grammar")):
        return "minor", "local_parser"
    return "major", "local_parser"


def _rebuttal_item_evidence_ids(item: Any, fallback: str) -> list[str]:
    ids = [fallback]
    if isinstance(item, dict):
        raw = item.get("evidence_ids")
        if isinstance(raw, list):
            ids.extend(str(value) for value in raw if str(value).strip())
        for key in ("evidence_id", "source_id", "id"):
            value = str(item.get(key) or "").strip()
            if value:
                ids.append(value)
    return _unique_strings(ids)


def _rebuttal_reviewer_number(reviewer: str, fallback: int) -> int:
    match = re.search(r"(\d+)", reviewer)
    return int(match.group(1)) if match else fallback


def _rebuttal_concerns_from_reviewer_sources(envelope: dict[str, Any]) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    concerns: list[dict[str, Any]] = []
    sources = _rebuttal_review_sources(envelope)
    raw_parser_used = False
    reviewer_count = 0
    for source_index, source in enumerate(sources, start=1):
        source_path = str(source.get("source_path") or f"reviewer-thread-{source_index}")
        evidence_id = str(source.get("evidence_id") or "")
        sections: list[dict[str, Any]] = []
        if source.get("kind") == "payload" and isinstance(source.get("payload"), dict):
            payload = dict(source["payload"])
            evidence_id = str(payload.get("task_id") or payload.get("evidence_id") or evidence_id or f"reviewer-thread-{source_index}")
            sections = _rebuttal_review_sections_from_payload(payload)
        elif source.get("kind") == "text":
            raw_parser_used = True
            sections = _rebuttal_review_sections_from_text(str(source.get("text") or ""))
        for section_index, section in enumerate(sections, start=1):
            reviewer_count += 1
            reviewer = str(section.get("reviewer") or f"Reviewer {section_index}").strip()
            reviewer_number = _rebuttal_reviewer_number(reviewer, reviewer_count)
            concern_index = 0
            for item in section.get("items") or []:
                text = _rebuttal_concern_text(item)
                if not text:
                    continue
                concern_index += 1
                concern_type, type_source = _rebuttal_concern_type(text, item)
                severity, severity_source = _rebuttal_concern_severity(text, item)
                explicit_id = str(item.get("concern_id") or item.get("id") or "").strip() if isinstance(item, dict) else ""
                concern_id = explicit_id if re.match(r"(?i)^rv\d+-c\d+$", explicit_id) else f"Rv{reviewer_number}-C{concern_index}"
                concerns.append({
                    "concern_id": concern_id,
                    "reviewer": reviewer,
                    "reviewer_number": reviewer_number,
                    "type": concern_type,
                    "focus": concern_type,
                    "severity": severity,
                    "concern": text,
                    "source_path": source_path,
                    "source_kind": str(source.get("kind") or "payload"),
                    "evidence_id": evidence_id or f"reviewer-thread-{source_index}",
                    "evidence_ids": _rebuttal_item_evidence_ids(item, evidence_id or f"reviewer-thread-{source_index}"),
                    "classification_source": "structured" if type_source == "structured" and severity_source == "structured" else "local_parser",
                })
    boundary = {
        "schema": "autosci_rebuttal_reviewer_thread_boundary.v1",
        "status": "completed" if concerns else "missing",
        "thread_loaded": bool(sources),
        "atomization_completed": bool(concerns),
        "reviewer_count": reviewer_count,
        "concern_count": len(concerns),
        "source_paths": _unique_strings([str(source.get("source_path") or "") for source in sources]),
        "raw_parser_used": raw_parser_used,
        "limitations": (
            ["Non-standard reviewer text was parsed by a bounded local parser; supply structured reviewer-thread evidence for strict auditability."]
            if raw_parser_used
            else []
        ),
    }
    if not sources:
        boundary["limitations"].append("No reviewer-thread evidence was supplied.")
    if sources and not concerns:
        boundary["limitations"].append("Reviewer-thread evidence was supplied but no concerns were atomized.")
    return concerns, boundary


def _rebuttal_concerns_from_review_evidence(envelope: dict[str, Any]) -> list[dict[str, Any]]:
    concerns: list[dict[str, Any]] = []
    for payload in _phase14_source_payloads(envelope):
        if payload.get("schema") != "artifact_review.v1":
            continue
        evidence_id = str(payload.get("task_id") or "artifact-review")
        review = ((payload.get("outputs") or {}).get("review") or {})
        if not isinstance(review, dict):
            continue
        findings = review.get("findings") if isinstance(review.get("findings"), list) else []
        for index, finding in enumerate(findings, start=1):
            if isinstance(finding, dict):
                concern = str(
                    finding.get("issue")
                    or finding.get("finding")
                    or finding.get("evidence")
                    or finding.get("suggestion")
                    or ""
                ).strip()
                focus = str(finding.get("criterion") or finding.get("focus") or "review").strip()
            else:
                concern = str(finding).strip()
                focus = "review"
            if not concern:
                continue
            concern_type, _ = _rebuttal_concern_type(concern, finding)
            severity, _ = _rebuttal_concern_severity(concern, finding)
            concerns.append(
                {
                    "concern_id": f"Rv1-C{index}",
                    "reviewer": "Review LLM",
                    "reviewer_number": 1,
                    "type": concern_type,
                    "focus": focus,
                    "severity": severity,
                    "concern": concern,
                    "evidence_id": evidence_id,
                    "evidence_ids": [evidence_id],
                    "source_kind": "artifact_review",
                    "source_path": str(payload.get("source_path") or evidence_id),
                    "classification_source": "artifact_review",
                }
            )
    return concerns


def _rebuttal_tokens(text: str) -> set[str]:
    return {
        token
        for token in re.findall(r"[a-z0-9][a-z0-9_-]{2,}", text.lower())
        if token not in REBUTTAL_STOPWORDS
    }


def _rebuttal_wiki_entities(envelope: dict[str, Any]) -> list[dict[str, Any]]:
    entities: list[dict[str, Any]] = []
    folders = ("ideas", "methods", "experiments", "papers", "concepts", "outputs")
    for root in _wiki_roots_for_read(envelope):
        if not root.exists():
            continue
        for folder in folders:
            base = root / folder
            if not base.exists():
                continue
            for index, path in enumerate(sorted(base.glob("**/*.md")), start=1):
                if index > 80:
                    break
                text = _read_limited_text(path, limit=60_000)
                title = path.stem.replace("-", " ")
                for line in text.splitlines():
                    if line.startswith("# "):
                        title = line[2:].strip()
                        break
                entities.append({
                    "entity_id": path.stem,
                    "entity_type": folder[:-1] if folder.endswith("s") else folder,
                    "title": title,
                    "path": _rel(path),
                    "text": text,
                    "tokens": _rebuttal_tokens(f"{title} {path.stem} {text[:4000]}"),
                })
    return entities


def _rebuttal_evidence_status(entity: dict[str, Any] | None) -> str:
    if not entity:
        return "insufficient"
    text = str(entity.get("text") or "").lower()
    entity_type = str(entity.get("entity_type") or "")
    if any(word in text for word in ("invalidated", "contradicted", "failed")):
        return "contradicted"
    if entity_type == "experiment":
        if any(word in text for word in ("succeeded", "success", "completed", "passed")):
            return "sufficient"
        if any(word in text for word in ("inconclusive", "mixed", "partial")):
            return "partial"
    if entity_type == "idea":
        if any(word in text for word in ("linked_experiments", "succeeded", "validated", "completed")):
            return "sufficient"
        if "novelty_score" in text or "status:" in text:
            return "partial"
    if entity_type == "method":
        if any(word in text for word in ("source_papers", "procedure", "mechanism", "implementation")):
            return "sufficient"
        return "partial"
    if entity_type in {"paper", "concept", "output"}:
        return "sufficient"
    return "partial"


def _rebuttal_map_concern(concern: dict[str, Any], entities: list[dict[str, Any]]) -> dict[str, Any]:
    tokens = _rebuttal_tokens(str(concern.get("concern") or ""))
    best: dict[str, Any] | None = None
    best_score = 0
    for entity in entities:
        entity_tokens = entity.get("tokens") if isinstance(entity.get("tokens"), set) else set()
        score = len(tokens & entity_tokens)
        if score > best_score:
            best = entity
            best_score = score
    evidence_status = _rebuttal_evidence_status(best if best_score >= 1 else None)
    mapped = best is not None and best_score >= 1
    strategy = _rebuttal_response_strategy(str(concern.get("type") or ""), evidence_status)
    mapping = {
        "mapped": mapped,
        "entity_id": str(best.get("entity_id") or "") if mapped and best else "",
        "entity_type": str(best.get("entity_type") or "") if mapped and best else "",
        "entity_title": str(best.get("title") or "") if mapped and best else "",
        "entity_path": str(best.get("path") or "") if mapped and best else "",
        "match_score": best_score,
        "evidence_status": evidence_status,
        "strategy": strategy,
    }
    return mapping


def _rebuttal_response_strategy(concern_type: str, evidence_status: str) -> str:
    normalized = concern_type.lower()
    if normalized == "clarity":
        return "C"
    if normalized in {"scope", "novelty"}:
        return "D" if evidence_status in {"sufficient", "partial"} else "B"
    if evidence_status == "sufficient":
        return "A"
    return "B"


def _rebuttal_response_text(concern: dict[str, Any], mapping: dict[str, Any]) -> str:
    strategy = str(mapping.get("strategy") or "B")
    entity_path = str(mapping.get("entity_path") or "").strip()
    entity_title = str(mapping.get("entity_title") or mapping.get("entity_id") or "the available project evidence").strip()
    if strategy == "A":
        return (
            f"We will answer this directly by citing `{entity_path or entity_title}` as the supporting evidence. "
            "The response will state only the result recorded in that source and will avoid adding unverified claims."
        )
    if strategy == "C":
        return (
            "We agree that the presentation can be clearer. The rebuttal will provide the corrected wording and mark the "
            "corresponding paper edit without claiming new experimental evidence."
        )
    if strategy == "D":
        return (
            f"We will address the scope/novelty concern by pointing to `{entity_path or entity_title}` and clarifying the "
            "bounded distinction from prior work. Any unsupported broader claim is left out."
        )
    return (
        "We acknowledge that the current evidence is not sufficient for a direct claim. The response proposes a concrete "
        "follow-up experiment or paper edit and does not promise unsupported results."
    )


def _rebuttal_safety_checks(concern: dict[str, Any], mapping: dict[str, Any]) -> list[dict[str, Any]]:
    evidence_status = str(mapping.get("evidence_status") or "insufficient")
    strategy = str(mapping.get("strategy") or "B")
    mapped = bool(mapping.get("mapped"))
    return [
        _check_row(
            "no_fabrication",
            "ok" if strategy != "A" or (mapped and evidence_status == "sufficient") else "warn",
            "Direct evidence-backed claims are tied to mapped wiki/source evidence."
            if strategy != "A" or (mapped and evidence_status == "sufficient")
            else "Direct response needs sufficient mapped evidence before final use.",
            [str(mapping.get("entity_path") or "")] if mapping.get("entity_path") else [],
        ),
        _check_row(
            "no_overpromise",
            "ok",
            "Responses either cite recorded evidence or frame missing evidence as a concrete follow-up.",
        ),
        _check_row(
            "traceability",
            "ok" if mapped else "warn",
            "Concern maps to a wiki/source entity." if mapped else "Concern has no direct wiki/source entity mapping.",
            [str(mapping.get("entity_path") or "")] if mapping.get("entity_path") else [],
        ),
        _check_row(
            "invalidated_guard",
            "ok" if evidence_status != "contradicted" else "warn",
            "No contradicted evidence is presented as support."
            if evidence_status != "contradicted"
            else "Mapped evidence is contradicted/failed; rebuttal must acknowledge this.",
        ),
    ]


def _rebuttal_stress_test_boundary(
    inputs: dict[str, Any],
    review_boundary: dict[str, Any],
    *,
    concern_count: int,
) -> dict[str, Any]:
    requested = inputs.get("stress_test") is not False
    review_completed = bool(review_boundary.get("completed"))
    raw_score = _optional_number(review_boundary.get("score"))
    score_1_to_5 = None
    if raw_score is not None:
        score_1_to_5 = round(raw_score * 5, 2) if raw_score <= 1 else round(raw_score, 2)
    ready = (not requested) or (review_completed and concern_count > 0)
    return {
        "schema": "autosci_rebuttal_review_llm_stress_test_boundary.v1",
        "status": "completed" if requested and ready else "not_requested" if not requested else "missing_review_llm_evidence",
        "stress_test_requested": requested,
        "stress_test_ready": ready,
        "review_llm_completed": review_completed,
        "review_boundary_status": str(review_boundary.get("status") or "missing"),
        "invocation_mode": str(review_boundary.get("invocation_mode") or ""),
        "score": score_1_to_5,
        "follow_up_required": bool(score_1_to_5 is not None and score_1_to_5 <= 3),
        "concern_count": concern_count,
        "evidence_ids": _unique_strings([str(item) for item in review_boundary.get("evidence_ids") or []]),
        "limitations": (
            []
            if requested and ready
            else ["Review LLM stress-test was disabled by CLI; this is not strict native rebuttal parity."]
            if not requested
            else ["Completed Review LLM stress-test evidence is required for final rebuttal acceptance."]
        ),
    }


def _rebuttal_submission_boundary(
    inputs: dict[str, Any],
    submission_audit: dict[str, Any],
    *,
    formal_text_path: str,
    concern_count: int,
    safety_checks: list[dict[str, Any]],
) -> dict[str, Any]:
    blocking_checks = [
        str(row.get("check") or "safety_check")
        for row in safety_checks
        if isinstance(row, dict) and str(row.get("status") or "") != "ok"
    ]
    if concern_count <= 0:
        blocking_checks.append("reviewer_thread_atomization")
    if not formal_text_path:
        blocking_checks.append("formal_rebuttal_text")
    audit_ready = bool(submission_audit.get("audit_verified"))
    if not audit_ready:
        blocking_checks.append("publication_submission_audit")
    ready = audit_ready and concern_count > 0 and bool(formal_text_path) and not blocking_checks
    return {
        "schema": "autosci_rebuttal_submission_boundary.v1",
        "status": "submission_audit_ready" if ready else "submission_audit_incomplete",
        "submission_audit_ready": ready,
        "portal_submission_completed": bool(submission_audit.get("portal_submission_completed")),
        "formal_rebuttal_text_path": formal_text_path,
        "venue": str(inputs.get("venue") or submission_audit.get("venue") or ""),
        "format": str(inputs.get("format") or "formal"),
        "concern_count": concern_count,
        "blocking_checks": _unique_strings(blocking_checks),
        "submission_audit": submission_audit,
        "limitations": (
            ["Portal submission is not claimed by this dry-run bridge unless external audit evidence records completion."]
            if ready
            else ["Rebuttal submission readiness requires formal text, full concern coverage, clean safety checks, and valid submission audit evidence."]
        ),
    }


def _render_rebuttal_markdown_from_map(response_map: dict[str, Any]) -> str:
    lines = [
        f"# Rebuttal Analysis: {response_map.get('title') or 'AutoSci Rebuttal'}",
        "",
        f"Target: `{response_map.get('target') or 'N/A'}`",
        "",
        "## Coverage Summary",
        "",
        "| Concern ID | Reviewer | Type | Severity | Entity | Evidence Status | Review LLM | Strategy |",
        "|---|---|---|---|---|---|---|---|",
    ]
    for item in response_map.get("mapped_concerns") or []:
        mapping = item.get("mapping") if isinstance(item.get("mapping"), dict) else {}
        stress = response_map.get("stress_test_boundary") if isinstance(response_map.get("stress_test_boundary"), dict) else {}
        entity = mapping.get("entity_path") or mapping.get("entity_id") or "unmapped"
        score = stress.get("score") if stress.get("score") is not None else "N/A"
        lines.append(
            f"| {item.get('concern_id')} | {item.get('reviewer')} | {item.get('type')} | {item.get('severity')} | "
            f"{entity} | {mapping.get('evidence_status')} | {score} | {mapping.get('strategy')} |"
        )
    lines.extend(["", "## Responses", ""])
    for item in response_map.get("mapped_concerns") or []:
        lines.extend([
            f"### {item.get('reviewer')} - {item.get('concern_id')}",
            "",
            f"**Concern.** {item.get('concern')}",
            "",
            str(item.get("response") or ""),
            "",
        ])
    if response_map.get("unmapped_concerns"):
        lines.extend(["## Unmapped Concerns", ""])
        lines.extend(f"- {item}" for item in response_map.get("unmapped_concerns") or [])
        lines.append("")
    lines.extend(["## Safety Checklist", ""])
    for row in response_map.get("safety_checks") or []:
        lines.append(f"- [{ 'x' if row.get('status') == 'ok' else ' ' }] {row.get('check')}: {row.get('detail')}")
    lines.extend(["", "## Limitations", ""])
    lines.extend(f"- {item}" for item in response_map.get("limitations") or [])
    lines.append("")
    return "\n".join(lines)


def _render_rebuttal_formal_text(response_map: dict[str, Any]) -> str:
    lines = [
        "We thank the reviewers for their constructive feedback. We address each concern below.",
        "",
    ]
    current_reviewer = ""
    for item in response_map.get("mapped_concerns") or []:
        reviewer = str(item.get("reviewer") or "Reviewer")
        if reviewer != current_reviewer:
            current_reviewer = reviewer
            lines.extend([f"{reviewer}:", ""])
        lines.extend([
            f"[{item.get('concern_id')}] {item.get('concern')}",
            str(item.get("response") or ""),
            "",
        ])
    lines.extend([
        "Summary of Revisions:",
        "- We will make only the paper edits and follow-up experiment commitments supported by the mapped evidence above.",
        "",
        "Additional Experiments:",
        "- Any additional experiment is framed as a planned follow-up unless completed evidence is already cited.",
        "",
    ])
    return "\n".join(lines)


def _poster_paper_dir(envelope: dict[str, Any]) -> Path | None:
    inputs = dict(envelope.get("inputs") or {})
    for key in ("paper_path", "paper_dir", "target"):
        raw = str(inputs.get(key) or "").strip()
        if not raw:
            continue
        path = _resolve_harness_path(raw)
        if path.is_dir() and (path / "main.tex").exists():
            return path
    default = _resolve_harness_path("paper")
    if default.is_dir() and (default / "main.tex").exists():
        return default
    return None


def _poster_template_html(title: str) -> str:
    escaped_title = html.escape(title)
    return (
        "<!doctype html>\n"
        "<html><head><meta charset=\"utf-8\"><title>"
        f"{escaped_title}</title><style>"
        "body{margin:0;font-family:Arial,sans-serif;background:#f8fafc;color:#111827;}"
        ".poster{width:1400px;min-height:900px;margin:0 auto;padding:36px;box-sizing:border-box;background:white;}"
        "header{display:flex;justify-content:space-between;gap:24px;border-bottom:4px solid #111827;padding-bottom:18px;}"
        ".title-block{display:grid;grid-template-columns:auto 1fr;gap:18px;align-items:center;}"
        ".logo-affiliation img,.conf img{max-height:70px;max-width:160px;object-fit:contain;}"
        ".title{font-size:44px;line-height:1.05;margin:0;max-width:980px;}"
        ".authors{font-size:20px;margin-top:10px;color:#374151;}"
        ".venue,.conf{font-size:18px;text-align:right;color:#374151;}"
        ".flow{columns:3 360px;column-gap:26px;margin-top:24px;}"
        ".section{break-inside:avoid;border:1px solid #d1d5db;padding:14px;margin:0 0 16px;background:#ffffff;}"
        ".section h2{font-size:24px;margin:0 0 8px;}"
        ".section p{font-size:15px;line-height:1.35;margin:0 0 8px;}"
        ".img-section{display:flex;gap:8px;align-items:center;}"
        ".img-section img{max-width:100%;height:auto;border:1px solid #e5e7eb;}"
        "table{width:100%;border-collapse:collapse;font-size:12px;}td,th{border:1px solid #d1d5db;padding:3px;}"
        "</style></head><body><div class=\"poster\"><header><div class=\"title-block\">"
        "<div class=\"logo-affiliation\"></div><div>"
        f"<h1 class=\"title\">{escaped_title}</h1><div class=\"authors\">Anonymous</div>"
        "</div></div><div class=\"conf\"><div class=\"venue\"></div></div></header><main class=\"main\"><div class=\"flow\" id=\"flow\">"
        "</div></main></div></body></html>\n"
    )


def _poster_sentence_summary(text: str, *, max_sentences: int = 3) -> str:
    cleaned = re.sub(r"<[^>]+>", " ", text)
    cleaned = re.sub(r"\s+", " ", cleaned).strip()
    if not cleaned:
        return "No section prose was available in the paper source."
    sentences = [item.strip() for item in re.split(r"(?<=[.!?])\s+", cleaned) if item.strip()]
    summary = " ".join(sentences[:max_sentences] or [cleaned])
    return summary[:900]


def _poster_outline_from_dag(dag: dict[str, Any], *, no_figures: bool) -> str:
    nodes = dag.get("nodes") if isinstance(dag.get("nodes"), list) else []
    sections = [node for node in nodes if isinstance(node, dict) and node.get("level") == 1]
    blocks: list[str] = []
    for section in sections[:6]:
        title = html.escape(str(section.get("name") or "Section"))
        content = str(section.get("content") or "")
        summary = html.escape(_poster_sentence_summary(content))
        block = [f'<section class="section"><h2>{title}</h2><p>{summary}</p>']
        if "<table" in content.lower():
            tables = re.findall(r"(<table.*?</table>)", content, flags=re.IGNORECASE | re.DOTALL)
            block.extend(tables[:1])
        if not no_figures:
            visuals = section.get("visual_node") if isinstance(section.get("visual_node"), list) else []
            image_tags: list[str] = []
            for visual in visuals[:2]:
                visual_text = str(visual if not isinstance(visual, dict) else visual.get("name") or "")
                match = re.search(r"!\[[^\]]*\]\(([^)]+)\)", visual_text)
                if match:
                    src = html.escape(match.group(1))
                    image_tags.append(f'<img src="{src}" alt="{title} figure">')
            if image_tags:
                block.append('<div class="img-section">' + "".join(image_tags) + "</div>")
        block.append("</section>")
        blocks.append("\n".join(block))
    return "\n".join(blocks) + ("\n" if blocks else "")


def _poster_run_tool(command: list[str]) -> dict[str, Any]:
    proc = subprocess.run(
        command,
        cwd=REPO_HARNESS_DIR.parent,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
    )
    return {
        "command": command,
        "exit_code": proc.returncode,
        "stdout": proc.stdout[-4000:],
        "stderr": proc.stderr[-4000:],
        "status": "completed" if proc.returncode == 0 else "failed",
    }


def _poster_review_requested(inputs: dict[str, Any]) -> bool:
    return bool(
        inputs.get("review")
        or inputs.get("review_llm_requested")
        or inputs.get("require_review_llm")
        or inputs.get("review_llm_evidence")
        or inputs.get("review_evidence")
        or inputs.get("artifact_review_evidence")
        or inputs.get("review_llm_command")
        or inputs.get("review_llm_provider")
        or inputs.get("review_llm_endpoint")
    )


def _poster_review_from_command_or_provider(
    envelope: dict[str, Any],
    *,
    poster_html_path: Path,
) -> tuple[dict[str, Any], list[str], list[dict[str, str]]]:
    inputs = dict(envelope.get("inputs") or {})
    review_inputs = dict(inputs)
    review_inputs["target"] = _rel(poster_html_path)
    review_inputs["artifact_path"] = _rel(poster_html_path)
    review_inputs["review_llm_requested"] = True
    review_inputs.setdefault("focus", "poster critique, content fidelity, layout risks, and missing evidence")
    raw_review = review_artifact(
        review_inputs,
        workspace_root=HARNESS_DIR,
        repository_root=REPO_HARNESS_DIR,
    )
    review = raw_review.get("review") if isinstance(raw_review.get("review"), dict) else {}
    review_llm = review.get("review_llm") if isinstance(review.get("review_llm"), dict) else {}
    completed = (
        str(raw_review.get("status") or "") == "completed"
        and str(review.get("review_mode") or "") == "review_llm"
        and review.get("review_available") is True
        and str(review_llm.get("status") or "completed") == "completed"
    )
    evidence_ids = _unique_strings([
        str(raw_review.get("task_id") or ""),
        *[str(item) for item in review.get("evidence_ids") or []],
        *[str(item) for item in review_llm.get("evidence_ids") or []],
    ])
    payload = {
        "schema": "artifact_review.v1",
        "task_id": str(raw_review.get("task_id") or "poster-review-llm"),
        "status": "completed" if completed else str(raw_review.get("status") or "inconclusive"),
        "outputs": {
            "artifact": raw_review.get("artifact") if isinstance(raw_review.get("artifact"), dict) else {},
            "review": review,
            "findings": raw_review.get("findings") if isinstance(raw_review.get("findings"), list) else [],
        },
        "provenance": {
            "operator_id": "autosci-bridge-poster",
            "implementation_package": "plugins/autosci/backends/artifact_review.py",
            "timestamp": datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
            "source": "poster_review_llm_auto_critique",
        },
        "limitations": list(raw_review.get("limitations") or []),
    }
    payload_path = _write_json_sidecar(_output_dir(envelope, "build_poster") / "poster_review_llm_round_01.json", payload)
    artifacts = [{"type": "poster_review_llm_evidence_json", "path": payload_path}]
    if completed:
        return (
            {
                "status": "completed",
                "source_path": payload_path,
                "claim_id": f"poster:{_slug(_rel(poster_html_path))}",
                "review_mode": "review_llm",
                "review_available": True,
                "score": review.get("score", "N/A"),
                "recommendation": str(review.get("recommendation") or "N/A"),
                "difficulty": str(review.get("difficulty") or "N/A"),
                "focus": str(review.get("focus") or review_inputs.get("focus") or "N/A"),
                "evidence_ids": evidence_ids,
                "finding_count": len(payload["outputs"]["findings"]),
                "review_llm": review_llm or {"status": "completed"},
                "checked_paths": [payload_path],
            },
            evidence_ids,
            artifacts,
        )
    return (
        {
            "status": "inconclusive",
            "source_path": payload_path,
            "claim_id": f"poster:{_slug(_rel(poster_html_path))}",
            "checked_paths": [payload_path],
            "reasons": list(raw_review.get("limitations") or ["Review LLM command/provider did not produce completed evidence."]),
        },
        [],
        artifacts,
    )


def _poster_review_llm_boundary(
    envelope: dict[str, Any],
    *,
    poster_html_path: Path,
    content_report_path: str,
) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    requested = _poster_review_requested(inputs)
    if requested and not poster_html_path.exists():
        return {
            "schema": "autosci_poster_review_llm_boundary.v1",
            "status": "poster_html_missing",
            "requested": True,
            "review_llm_completed": False,
            "critique_refine_ready": False,
            "poster_html_path": _rel(poster_html_path),
            "content_report_path": content_report_path,
            "review_llm": {
                "status": "blocked",
                "reasons": ["Poster Review LLM cannot run because poster HTML was not generated."],
            },
            "evidence_ids": [],
            "artifacts": [],
            "limitations": ["Poster Review LLM critique/refine is blocked until native poster HTML exists."],
        }
    if inputs.get("no_refine"):
        return {
            "schema": "autosci_poster_review_llm_boundary.v1",
            "status": "skipped_by_no_refine" if requested else "not_requested",
            "requested": requested,
            "review_llm_completed": False,
            "critique_refine_ready": False,
            "poster_html_path": _rel(poster_html_path),
            "content_report_path": content_report_path,
            "review_llm": {"status": "skipped"},
            "evidence_ids": [],
            "artifacts": [],
            "limitations": ["Poster critique/refine pass was skipped by `--no-refine`."],
        }
    if not requested:
        return {
            "schema": "autosci_poster_review_llm_boundary.v1",
            "status": "not_requested",
            "requested": False,
            "review_llm_completed": False,
            "critique_refine_ready": False,
            "poster_html_path": _rel(poster_html_path),
            "content_report_path": content_report_path,
            "review_llm": {"status": "not_requested"},
            "evidence_ids": [],
            "artifacts": [],
            "limitations": ["Poster Review LLM critique/refine was not requested."],
        }
    if _input_path_values(inputs, "review_llm_evidence", "review_evidence", "artifact_review_evidence"):
        review_llm, evidence_ids, artifacts = _claim_review_llm_context(
            envelope,
            f"poster:{_slug(_rel(poster_html_path))}",
            artifact_type="poster_review_llm_evidence_json",
        )
    elif inputs.get("review_llm_command") or inputs.get("review_llm_provider") or inputs.get("review_llm_endpoint"):
        review_llm, evidence_ids, artifacts = _poster_review_from_command_or_provider(
            envelope,
            poster_html_path=poster_html_path,
        )
    else:
        review_llm = {
            "status": "missing",
            "claim_id": f"poster:{_slug(_rel(poster_html_path))}",
            "reasons": ["Review was requested but no Review LLM evidence, command, or provider was supplied."],
        }
        evidence_ids = []
        artifacts = []
    completed = str(review_llm.get("status") or "") == "completed"
    return {
        "schema": "autosci_poster_review_llm_boundary.v1",
        "status": "completed" if completed else "missing_review_llm_evidence",
        "requested": True,
        "review_llm_completed": completed,
        "critique_refine_ready": completed,
        "poster_html_path": _rel(poster_html_path),
        "content_report_path": content_report_path,
        "review_llm": review_llm,
        "evidence_ids": evidence_ids,
        "artifacts": artifacts,
        "limitations": [] if completed else list(review_llm.get("reasons") or ["Poster Review LLM critique/refine evidence is incomplete."]),
    }


def _poster_native_content_pipeline(
    envelope: dict[str, Any],
    *,
    title: str,
    paths: dict[str, Path],
) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    output_dir = _output_dir(envelope, "build_poster")
    paper_dir = _poster_paper_dir(envelope)
    dag_path = output_dir / "dag.json"
    outline_path = output_dir / "outline.html"
    template_path = output_dir / "poster_template.html"
    report_path = output_dir / "poster_generation_report.json"
    validate_path = output_dir / "poster_validate_result.json"
    report: dict[str, Any] = {
        "schema": "autosci_poster_generation_report.v1",
        "status": "paper_source_missing",
        "paper_dir": _rel(paper_dir) if paper_dir else "",
        "dag_path": _rel(dag_path),
        "outline_path": _rel(outline_path),
        "template_path": _rel(template_path),
        "html_path": _rel(paths["html"]),
        "distillation_mode": "extractive_local",
        "commands": [],
        "validation": {},
        "limitations": [],
    }
    if paper_dir is None:
        report["limitations"].append(
            "No paper directory containing main.tex was resolved; native /poster precondition was not met."
        )
        report_rel = _write_json_sidecar(report_path, report)
        return {"ready": False, "report_path": report_rel, "artifacts": [{"type": "poster_generation_report_json", "path": report_rel}], "report": report}
    wiki2dag = REPO_HARNESS_DIR.parent / "tools" / "wiki2dag.py"
    poster_tool = REPO_HARNESS_DIR.parent / "tools" / "poster.py"
    build_cmd = [sys.executable, str(wiki2dag), "build", "--paper-dir", str(paper_dir), "--output", str(dag_path)]
    if inputs.get("anonymous"):
        build_cmd.append("--anonymous")
    build_result = _poster_run_tool(build_cmd)
    report["commands"].append(build_result)
    if build_result["exit_code"] != 0 or not dag_path.exists():
        report["status"] = "dag_build_failed"
        report["limitations"].append("wiki2dag.py build failed; poster content was not generated from paper source.")
        report_rel = _write_json_sidecar(report_path, report)
        return {"ready": False, "report_path": report_rel, "artifacts": [{"type": "poster_generation_report_json", "path": report_rel}], "report": report}
    dag = _load_json(dag_path)
    outline = _poster_outline_from_dag(dag, no_figures=bool(inputs.get("no_figures")))
    _write_text_sidecar(outline_path, outline)
    _write_text_sidecar(template_path, _poster_template_html(title))
    build_poster_result = _poster_run_tool([
        sys.executable,
        str(poster_tool),
        "build",
        "--template",
        str(template_path),
        "--outline",
        str(outline_path),
        "--output",
        str(paths["html"]),
    ])
    report["commands"].append(build_poster_result)
    if build_poster_result["exit_code"] == 0:
        title_cmd = [sys.executable, str(poster_tool), "inject-title", "--dag", str(dag_path), str(paths["html"])]
        if inputs.get("anonymous"):
            title_cmd.append("--anonymous")
        if inputs.get("authors"):
            title_cmd.extend(["--authors", str(inputs["authors"])])
        report["commands"].append(_poster_run_tool(title_cmd))
        header_cmd = [sys.executable, str(poster_tool), "inject-header", str(paths["html"])]
        if inputs.get("venue"):
            header_cmd.extend(["--venue", str(inputs["venue"])])
        if not inputs.get("no_logos"):
            if inputs.get("affiliation_logo"):
                header_cmd.extend(["--affiliation-logo", str(inputs["affiliation_logo"])])
            if inputs.get("conference_logo"):
                header_cmd.extend(["--conference-logo", str(inputs["conference_logo"])])
        if inputs.get("layout"):
            header_cmd.extend(["--layout", str(inputs["layout"])])
        report["commands"].append(_poster_run_tool(header_cmd))
        if not inputs.get("no_figures"):
            report["commands"].append(_poster_run_tool([
                sys.executable,
                str(poster_tool),
                "inject-figures",
                "--dag",
                str(dag_path),
                "--paper-dir",
                str(paper_dir),
                "--poster-dir",
                str(output_dir),
            ]))
        validate_result = _poster_run_tool([sys.executable, str(poster_tool), "validate", str(paths["html"])])
        report["commands"].append(validate_result)
        try:
            validation_payload = json.loads(validate_result.get("stdout") or "{}")
        except json.JSONDecodeError:
            validation_payload = {"status": "failed", "raw_stdout": validate_result.get("stdout")}
        _write_json_sidecar(validate_path, validation_payload if isinstance(validation_payload, dict) else {"raw": validation_payload})
        report["validation"] = validation_payload if isinstance(validation_payload, dict) else {}
    successful = all(str(item.get("status")) == "completed" for item in report["commands"])
    validate_ok = str((report.get("validation") or {}).get("status") or "") == "completed"
    report["status"] = "completed" if successful and validate_ok and paths["html"].exists() else "incomplete"
    if report["status"] != "completed":
        report["limitations"].append("Poster source pipeline did not fully complete; inspect command statuses and validation output.")
    if not _poster_review_requested(inputs):
        report["limitations"].append("Critique/revise Review LLM pass was not requested; content distillation is extractive and source-bound.")
    report_rel = _write_json_sidecar(report_path, report)
    artifacts = [
        {"type": "poster_dag_json", "path": _rel(dag_path)},
        {"type": "poster_outline_html", "path": _rel(outline_path)},
        {"type": "poster_template_html", "path": _rel(template_path)},
        {"type": "poster_validate_result_json", "path": _rel(validate_path)},
        {"type": "poster_generation_report_json", "path": report_rel},
    ]
    return {"ready": report["status"] == "completed", "report_path": report_rel, "artifacts": artifacts, "report": report}


def _write_rebuttal_final_runtime_proof_manifest(
    envelope: dict[str, Any],
    *,
    evidence_path: Path,
    response_map: dict[str, Any],
    map_path: str,
    reviewer_thread_boundary_path: str,
    stress_test_boundary_path: str,
    submission_boundary_path: str,
    formal_text_path: str,
) -> dict[str, str] | None:
    coverage = response_map.get("coverage") if isinstance(response_map.get("coverage"), dict) else {}
    concern_count = int(coverage.get("concern_count") or 0)
    wiki_mapped_count = int(coverage.get("wiki_mapped_count") or 0)
    stress_boundary = (
        response_map.get("stress_test_boundary")
        if isinstance(response_map.get("stress_test_boundary"), dict)
        else {}
    )
    submission_boundary = (
        response_map.get("submission_boundary")
        if isinstance(response_map.get("submission_boundary"), dict)
        else {}
    )
    reviewer_thread = (
        response_map.get("reviewer_thread")
        if isinstance(response_map.get("reviewer_thread"), dict)
        else {}
    )
    if (
        concern_count <= 0
        or wiki_mapped_count < concern_count
        or reviewer_thread.get("status") != "completed"
        or stress_boundary.get("stress_test_ready") is not True
        or submission_boundary.get("submission_audit_ready") is not True
    ):
        return None
    refs: list[str | Path] = [
        evidence_path,
        map_path,
        reviewer_thread_boundary_path,
        stress_test_boundary_path,
        submission_boundary_path,
        formal_text_path,
    ]
    for concern in response_map.get("mapped_concerns") or []:
        if not isinstance(concern, dict):
            continue
        mapping = concern.get("mapping") if isinstance(concern.get("mapping"), dict) else {}
        if mapping.get("entity_path"):
            refs.append(str(mapping["entity_path"]))
        if concern.get("source_path"):
            refs.append(str(concern["source_path"]))
    review_boundary = response_map.get("review_boundary") if isinstance(response_map.get("review_boundary"), dict) else {}
    if review_boundary.get("source_path"):
        refs.append(str(review_boundary["source_path"]))
    audit = submission_boundary.get("submission_audit") if isinstance(submission_boundary.get("submission_audit"), dict) else {}
    if audit.get("path"):
        refs.append(str(audit["path"]))
    timestamp = datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    manifest = {
        "schema": "autosci_runtime_proof_manifest.v1",
        "generated_at": timestamp,
        "proofs": [
            {
                "native_skill": "rebuttal",
                "proof_id": f"runtime:rebuttal:thread-audit:{timestamp.replace(':', '').replace('-', '')}",
                "categories": [
                    "review_llm_or_model_evidence",
                    "external_runtime_evidence",
                    "provider_source_evidence",
                ],
                "collection_mode": "manual_review",
                "production_ready": True,
                "provenance": {
                    "source": "rebuttal_thread_stress_submission_boundary",
                    "captured_at": timestamp,
                    "artifact_kind": "autosci_rebuttal_response_map",
                    "command": "draft_rebuttal:thread_stress_submission_audit",
                },
                "evidence_refs": _runtime_evidence_refs(*refs),
                "description": "Completed reviewer-thread, wiki/source mapping, Review LLM stress-test, and submission audit evidence for AutoSci `rebuttal` parity.",
            }
        ],
    }
    artifact_path = _write_json_sidecar(
        _output_dir(envelope, "draft_rebuttal") / "draft_rebuttal_final_runtime_proof.json",
        manifest,
    )
    return {"type": "provider_source_runtime_proof_manifest_json", "path": artifact_path}


def _action_draft_rebuttal(envelope: dict[str, Any]) -> dict[str, Any]:
    paths = _publication_action_paths(envelope, "draft_rebuttal")
    inputs = dict(envelope.get("inputs") or {})
    title = _native_publication_title(envelope, "AutoSci Rebuttal Draft")
    target = _native_publication_target(envelope)
    evidence_ids = _native_publication_evidence_ids(envelope, "rebuttal:request")
    reviewer_concerns, reviewer_thread_boundary = _rebuttal_concerns_from_reviewer_sources(envelope)
    review_llm_concerns = _rebuttal_concerns_from_review_evidence(envelope)
    concerns = reviewer_concerns or review_llm_concerns
    has_source_evidence = bool(concerns) or _native_publication_has_source_evidence(envelope)
    entities = _rebuttal_wiki_entities(envelope)
    review_boundary = _native_publication_review_boundary(envelope)
    stress_test_boundary = _rebuttal_stress_test_boundary(
        inputs,
        review_boundary,
        concern_count=len(concerns),
    )
    submission_audit = _submission_audit_boundary(inputs)
    limitations = [
        "Rebuttal draft is local and evidence-linked; it is not a submitted response.",
    ]
    limitations.extend(str(item) for item in reviewer_thread_boundary.get("limitations") or [])
    limitations.extend(str(item) for item in stress_test_boundary.get("limitations") or [])
    if not has_source_evidence:
        limitations.append("No review/comment/evidence payload was supplied; all concerns remain unmapped.")
    if has_source_evidence and not concerns:
        limitations.append("Review evidence was supplied but no structured findings/concerns were available to map.")
    if not submission_audit.get("audit_verified"):
        limitations.append("Rebuttal submission audit readiness is not proven; supply valid --submission-audit evidence.")
    mapped_concerns: list[dict[str, Any]] = []
    safety_checks: list[dict[str, Any]] = []
    for concern in concerns:
        mapping = _rebuttal_map_concern(concern, entities)
        response = _rebuttal_response_text(concern, mapping)
        concern_safety = _rebuttal_safety_checks(concern, mapping)
        safety_checks.extend(concern_safety)
        mapped_concerns.append({
            "concern_id": concern["concern_id"],
            "reviewer": concern.get("reviewer") or "Reviewer",
            "type": concern.get("type") or concern.get("focus") or "review",
            "focus": concern.get("focus") or concern.get("type") or "review",
            "severity": concern.get("severity") or "major",
            "concern": concern["concern"],
            "response": response,
            "status": "mapped",
            "wiki_mapping_status": "mapped" if mapping.get("mapped") else "unmapped",
            "evidence_ids": _unique_strings([str(item) for item in concern.get("evidence_ids") or [concern.get("evidence_id")]]),
            "source_path": str(concern.get("source_path") or ""),
            "classification_source": str(concern.get("classification_source") or ""),
            "mapping": mapping,
            "safety_checks": concern_safety,
        })
    formal_text = _render_rebuttal_formal_text({
        "title": title,
        "target": target,
        "mapped_concerns": mapped_concerns,
    })
    formal_text_path = _write_text_sidecar(paths["formal_text"], formal_text)
    submission_boundary = _rebuttal_submission_boundary(
        inputs,
        submission_audit,
        formal_text_path=formal_text_path,
        concern_count=len(mapped_concerns),
        safety_checks=safety_checks,
    )
    if not submission_boundary.get("submission_audit_ready"):
        limitations.extend(str(item) for item in submission_boundary.get("limitations") or [])
    reviewer_thread_boundary_path = _write_json_sidecar(
        _output_dir(envelope, "draft_rebuttal") / "rebuttal_reviewer_thread_boundary.json",
        reviewer_thread_boundary,
    )
    stress_test_boundary_path = _write_json_sidecar(
        _output_dir(envelope, "draft_rebuttal") / "rebuttal_stress_test_boundary.json",
        stress_test_boundary,
    )
    submission_boundary_path = _write_json_sidecar(
        _output_dir(envelope, "draft_rebuttal") / "rebuttal_submission_boundary.json",
        submission_boundary,
    )
    response_map = {
        "schema": "autosci_rebuttal_response_map.v1",
        "title": title,
        "target": target,
        "paper_slug": str(inputs.get("paper_slug") or ""),
        "venue": str(inputs.get("venue") or ""),
        "mapped_concerns": mapped_concerns,
        "unmapped_concerns": [] if mapped_concerns else ["No structured reviewer comments were supplied."],
        "wiki_unmapped_concerns": [
            item["concern_id"]
            for item in mapped_concerns
            if item.get("wiki_mapping_status") != "mapped"
        ],
        "coverage": {
            "concern_count": len(mapped_concerns),
            "mapped_count": len(mapped_concerns),
            "unmapped_count": 0 if mapped_concerns else 1,
            "wiki_mapped_count": sum(1 for item in mapped_concerns if item.get("wiki_mapping_status") == "mapped"),
            "wiki_unmapped_count": sum(1 for item in mapped_concerns if item.get("wiki_mapping_status") != "mapped"),
            "reviewer_thread_status": reviewer_thread_boundary.get("status"),
            "stress_test_status": stress_test_boundary.get("status"),
            "submission_status": submission_boundary.get("status"),
        },
        "source_types": _unique_strings([str(item.get("source_kind") or "") for item in concerns]),
        "reviewer_thread": reviewer_thread_boundary,
        "review_boundary": review_boundary,
        "stress_test_boundary": stress_test_boundary,
        "submission_boundary": submission_boundary,
        "safety_checks": safety_checks,
        "evidence_ids": evidence_ids,
        "limitations": limitations,
    }
    map_path = _write_json_sidecar(paths["map_json"], response_map)
    body = _render_rebuttal_markdown_from_map(response_map)
    markdown_path = _write_text_sidecar(paths["markdown"], body)
    evidence_payload_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        _output_dir(envelope, "draft_rebuttal") / "draft_rebuttal.evidence.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    review_runtime_proof_artifact = _write_review_context_runtime_proof_manifest(
        envelope,
        action="draft_rebuttal",
        native_skill="rebuttal",
        evidence_path=evidence_payload_path,
        review_llm=review_boundary,
    )
    final_runtime_proof_artifact = _write_rebuttal_final_runtime_proof_manifest(
        envelope,
        evidence_path=evidence_payload_path,
        response_map=response_map,
        map_path=map_path,
        reviewer_thread_boundary_path=reviewer_thread_boundary_path,
        stress_test_boundary_path=stress_test_boundary_path,
        submission_boundary_path=submission_boundary_path,
        formal_text_path=formal_text_path,
    )
    files = [
        {"type": "rebuttal_markdown", "path": markdown_path},
        {"type": "rebuttal_formal_text", "path": formal_text_path},
        {"type": "rebuttal_response_map_json", "path": map_path},
        {"type": "rebuttal_reviewer_thread_boundary_json", "path": reviewer_thread_boundary_path},
        {"type": "rebuttal_stress_test_boundary_json", "path": stress_test_boundary_path},
        {"type": "rebuttal_submission_audit_boundary_json", "path": submission_boundary_path},
    ]
    if review_runtime_proof_artifact is not None:
        files.append(review_runtime_proof_artifact)
    if final_runtime_proof_artifact is not None:
        files.append(final_runtime_proof_artifact)
    if submission_audit.get("audit_loaded"):
        files.append({
            "type": "publication_submission_audit_json",
            "path": str(submission_audit.get("path") or ""),
            "sha256": str(submission_audit.get("sha256") or ""),
        })
    return convert_publication_bundle({
        "bundle_id": f"rebuttal-{_slug(title)}",
        "publication_type": "rebuttal",
        "source_report_id": f"rebuttal:{_slug(target)}",
        "files": files,
        "evidence_ids": _unique_strings([f"rebuttal:{_slug(target)}", *evidence_ids]),
        "artifacts": files,
        "status": "completed"
        if has_source_evidence and mapped_concerns and stress_test_boundary.get("stress_test_ready")
        else "inconclusive",
        "limitations": limitations,
    }, envelope)


def _action_build_poster(envelope: dict[str, Any]) -> dict[str, Any]:
    paths = _publication_action_paths(envelope, "build_poster")
    inputs = dict(envelope.get("inputs") or {})
    title = _native_publication_title(envelope, "AutoSci Poster")
    target = _native_publication_target(envelope)
    evidence_ids = _native_publication_evidence_ids(envelope, "poster:request")
    has_source_evidence = _native_publication_has_source_evidence(envelope)
    contract = _approval_contract(
        envelope,
        "build_poster",
        ["browser_render", "overflow_probe", "png_export"],
    )
    contract, policy_decision, policy_artifacts = _policy_prepare_auto_contract(
        envelope,
        "build_poster",
        ["read_local", "write_artifact", "browser_render", "png_export", "local_command"],
        contract,
    )
    limitations = [
        "Poster HTML is generated locally; browser rendering, overflow probing, and PNG export are not executed by this bridge.",
        "Poster output requires human/browser validation before publication use.",
        *_approval_contract_limitations(contract),
    ]
    content_pipeline = _poster_native_content_pipeline(envelope, title=title, paths=paths)
    content_ready = bool(content_pipeline.get("ready"))
    if content_ready:
        html_path = _rel(paths["html"])
        has_source_evidence = True
    elif inputs.get("smoke_mode") or inputs.get("allow_compat_scaffold"):
        limitations.append(
            "Compatibility poster scaffold was generated only because smoke/compat mode was explicit."
        )
        html_body = (
            "<!doctype html>\n"
            "<html><head><meta charset=\"utf-8\"><title>"
            f"{html.escape(title)}</title></head><body><main>"
            f"<h1>{html.escape(title)}</h1>"
            f"<p>Target: {html.escape(target)}</p>"
            "<section><h2>Evidence</h2><ul>"
            + "".join(f"<li>{html.escape(str(item))}</li>" for item in evidence_ids)
            + "</ul></section>"
            "<section><h2>Limitations</h2><ul>"
            + "".join(f"<li>{html.escape(str(item))}</li>" for item in limitations)
            + "</ul></section>"
            "</main></body></html>\n"
        )
        html_path = _write_text_sidecar(paths["html"], html_body)
    else:
        html_path = ""
        limitations.append(
            "No poster HTML was generated because native /poster requires a paper directory containing main.tex."
        )
    review_boundary = _poster_review_llm_boundary(
        envelope,
        poster_html_path=paths["html"],
        content_report_path=str(content_pipeline.get("report_path") or ""),
    )
    review_boundary_path = _write_json_sidecar(
        _output_dir(envelope, "build_poster") / "poster_review_llm_boundary.json",
        review_boundary,
    )
    contract, executor_result = _execute_poster_if_approved(envelope, contract, paths["html"])
    semantic = _approval_semantic_runtime(contract, "build_poster")
    contract["semantic_runtime"] = semantic
    contract_artifact = _write_approval_contract_sidecar(envelope, "build_poster", contract)
    runtime_evidence_artifacts = _contract_existing_artifacts(contract, "runtime_evidence", "poster_runtime_evidence_json")
    limitations = [
        "Poster HTML is generated locally; browser rendering, overflow probing, and PNG export are not executed by this bridge.",
        "Poster output requires human/browser validation before publication use.",
        *_approval_contract_limitations(contract),
    ]
    if bool(executor_result.get("executed")):
        limitations = [
            "Poster render/export was executed by the approved side-effect executor and verified from runtime evidence."
            if semantic.get("verified")
            else f"Approved poster executor ran but did not verify successfully: {executor_result.get('reason') or 'semantic runtime incomplete'}",
        ]
    elif semantic.get("verified"):
        limitations = [
            "Poster runtime was verified from supplied approval-gated evidence; this bridge did not execute browser rendering.",
        ]
    elif policy_decision.get("execute_side_effects"):
        limitations.append(
            f"Auto-approved by gate policy mode `{policy_decision.get('mode')}`; poster render execution still requires a render command in allowlist evidence."
        )
    if not has_source_evidence:
        limitations.append("No report/evidence payload was supplied; poster content remains a scaffold.")
    pipeline_report = content_pipeline.get("report") if isinstance(content_pipeline.get("report"), dict) else {}
    limitations.extend(str(item) for item in pipeline_report.get("limitations") or [] if str(item).strip())
    limitations.extend(str(item) for item in review_boundary.get("limitations") or [] if str(item).strip())
    validation_path = _write_json_sidecar(paths["map_json"], {
        "title": title,
        "target": target,
        "content_pipeline_status": str(pipeline_report.get("status") or "not_run"),
        "content_pipeline_report": str(content_pipeline.get("report_path") or ""),
        "review_llm_status": str(review_boundary.get("status") or "missing"),
        "review_llm_completed": bool(review_boundary.get("review_llm_completed")),
        "critique_refine_ready": bool(review_boundary.get("critique_refine_ready")),
        "poster_review_llm_boundary": review_boundary_path,
        "browser_rendered": bool(semantic.get("detail", {}).get("browser_rendered")) if isinstance(semantic.get("detail"), dict) else False,
        "png_exported": bool(semantic.get("detail", {}).get("png_exported")) if isinstance(semantic.get("detail"), dict) else False,
        "overflow_probe": "passed" if semantic.get("detail", {}).get("overflow_probe_passed") else "not_run",
        "approval_contract": contract,
        "policy_decision": policy_decision,
        "runtime_semantic": semantic,
        "evidence_ids": evidence_ids,
        "limitations": limitations,
    })
    files = [
        {"type": "poster_validation_json", "path": validation_path},
        {"type": "poster_review_llm_boundary_json", "path": review_boundary_path},
        *list(content_pipeline.get("artifacts") or []),
        *list(review_boundary.get("artifacts") or []),
        contract_artifact,
        *policy_artifacts,
        *runtime_evidence_artifacts,
        *_contract_existing_artifacts(contract, "after_artifacts", "poster_runtime_after_artifact"),
    ]
    if html_path:
        files.insert(0, {"type": "poster_html", "path": html_path})
    evidence_payload_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        _output_dir(envelope, "build_poster") / "build_poster.evidence.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    review_runtime_proof_artifact = _write_review_context_runtime_proof_manifest(
        envelope,
        action="build_poster",
        native_skill="poster",
        evidence_path=evidence_payload_path,
        review_llm=review_boundary.get("review_llm") if isinstance(review_boundary.get("review_llm"), dict) else {},
    )
    if review_runtime_proof_artifact is not None:
        files.append(review_runtime_proof_artifact)
    if semantic.get("verified"):
        files.extend(
            _write_approved_mutation_runtime_proof_manifests(
                envelope,
                action="build_poster",
                native_skill="poster",
                evidence_path=evidence_payload_path,
                applied=True,
                contract=contract,
                contract_artifact=contract_artifact,
                source_refs=[],
                mutation_refs=[str(item.get("path") or "") for item in files if isinstance(item, dict)],
                include_wiki_mutation=False,
                source_label="approved_poster_render",
                artifact_kind="poster_render_export",
                include_provider_source=False,
            )
        )
    evidence = convert_publication_bundle({
        "bundle_id": f"poster-{_slug(title)}",
        "publication_type": "poster",
        "source_report_id": f"poster:{_slug(target)}",
        "files": files,
        "evidence_ids": _unique_strings([f"poster:{_slug(target)}", *evidence_ids]),
        "artifacts": files,
        "status": "completed" if semantic.get("verified") and has_source_evidence else "inconclusive",
        "limitations": limitations,
        "policy_decision": policy_decision,
    }, envelope)
    return _attach_policy_decision(evidence, policy_decision)


def _paper_compile_paths(envelope: dict[str, Any]) -> dict[str, Path]:
    output_dir = _output_dir(envelope, "compile_paper")
    return {
        "checklist": _configured_output_path(
            envelope,
            "compile_checklist_path",
            output_dir / "paper_compile_checklist.json",
        ),
        "diagnostics": _configured_output_path(
            envelope,
            "compile_diagnostics_path",
            output_dir / "paper_compile_diagnostics.md",
        ),
        "compile_report": _configured_output_path(
            envelope,
            "compile_report_path",
            output_dir / "paper_compile_report.json",
        ),
        "submission_boundary": _configured_output_path(
            envelope,
            "publication_submission_boundary_path",
            output_dir / "publication_submission_boundary.json",
        ),
        "fix_writeback": _configured_output_path(
            envelope,
            "compile_fix_writeback_path",
            output_dir / "paper_compile_fix_writeback.json",
        ),
    }


def _paper_compile_target(envelope: dict[str, Any]) -> tuple[str, Path | None]:
    inputs = envelope.get("inputs") if isinstance(envelope.get("inputs"), dict) else {}
    raw = str(inputs.get("paper_path") or inputs.get("target") or "").strip()
    if not raw:
        return "", None
    return raw, _resolve_harness_path(raw)


def _compile_source_candidates(target_path: Path | None) -> dict[str, list[Path]]:
    suffixes = {
        "latex": {".tex"},
        "pdf": {".pdf"},
        "markdown": {".md", ".markdown"},
        "bibliography": {".bib"},
    }
    candidates: dict[str, list[Path]] = {key: [] for key in suffixes}
    if not target_path or not target_path.exists():
        return candidates

    ignored_parts = {".git", ".hg", ".svn", ".venv", "node_modules", "__pycache__"}

    def add_file(path: Path) -> None:
        if any(part in ignored_parts for part in path.parts):
            return
        suffix = path.suffix.lower()
        for key, key_suffixes in suffixes.items():
            if suffix in key_suffixes and len(candidates[key]) < 25:
                candidates[key].append(path)

    if target_path.is_file():
        add_file(target_path)
        return candidates

    for path in sorted(target_path.rglob("*"), key=lambda item: str(item)):
        if path.is_file():
            add_file(path)
    return candidates


def _paper_compile_fix_target(target_path: Path | None, latex_files: list[Path]) -> Path | None:
    if target_path and target_path.exists() and target_path.is_file() and target_path.suffix.lower() == ".tex":
        return target_path
    return latex_files[0] if latex_files else None


def _paper_compile_fix_if_approved(
    envelope: dict[str, Any],
    contract: dict[str, Any],
    target_path: Path | None,
    latex_files: list[Path],
) -> dict[str, Any]:
    inputs = envelope.get("inputs") if isinstance(envelope.get("inputs"), dict) else {}
    if not bool(inputs.get("fix")):
        return {"requested": False, "applied": False, "artifacts": [], "limitations": [], "status": "not_requested"}

    paths = _paper_compile_paths(envelope)
    after_artifacts = inputs.get("after_artifacts") if isinstance(inputs.get("after_artifacts"), list) else []
    status = "inconclusive"
    artifacts: list[dict[str, Any]] = []
    limitations: list[str] = []
    write: dict[str, Any] = {
        "requested": True,
        "applied": False,
        "approval_ref": str(contract.get("approval_ref") or "N/A"),
        "approval_state": str(contract.get("approval_state") or "unknown"),
    }

    target_tex = _paper_compile_fix_target(target_path, latex_files)
    if not bool(inputs.get("execute_approved_side_effect")):
        limitations.append("Paper compile --fix requires --execute-approved before mutating TeX source.")
    elif not contract.get("ready_for_execution"):
        limitations.append("Paper compile --fix requires approval_ref, allowlist evidence, and before_artifact evidence.")
    elif target_tex is None:
        limitations.append("Paper compile --fix requires an existing .tex target.")
    elif not after_artifacts:
        limitations.append("Paper compile --fix requires an after_artifact containing the approved fixed TeX source.")
    else:
        after_path = _resolve_harness_path(str(after_artifacts[0]))
        allowed_roots = [HARNESS_DIR, REPO_HARNESS_DIR]
        if not any(_path_is_under(target_tex, root) for root in allowed_roots):
            limitations.append("Paper compile --fix target must stay inside the harness or repository root.")
        elif not after_path.exists() or after_path.is_dir():
            limitations.append("Paper compile --fix after_artifact does not resolve to an existing file.")
        else:
            before = target_tex.read_text(encoding="utf-8", errors="replace")
            desired = after_path.read_text(encoding="utf-8", errors="replace")
            changed = _write_text_if_changed_bridge(target_tex, desired)
            after = target_tex.read_text(encoding="utf-8", errors="replace")
            status = "completed"
            write.update(
                {
                    "applied": True,
                    "target_path": _rel(target_tex),
                    "after_artifact": _rel(after_path),
                    "changed": changed,
                    "before_sha256": _hash_text(before),
                    "after_sha256": _hash_text(after),
                }
            )
            artifacts.append({"type": "latex_source", "path": _rel(target_tex)})
            limitations.append("Approved paper compile --fix replaced the TeX source from after_artifact evidence.")

    write["status"] = status
    write["sidecar_path"] = _rel(paths["fix_writeback"])
    evidence = {
        "schema": "paper_compile_fix_writeback.v1",
        "task_id": f"task-compile-fix:{_slug(str(target_path or 'target'))}",
        "sprint_id": str(envelope.get("sprint_id") or "sprint-autosci"),
        "node_id": f"node-compile-fix:{_slug(str(target_path or 'target'))}",
        "status": status,
        "inputs": inputs,
        "outputs": {"write": write},
        "artifacts": artifacts,
        "provenance": {
            "operator_id": "autosci-bridge",
            "implementation_package": "plugins/autosci",
            "timestamp": datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        },
        "limitations": limitations,
    }
    artifact = {"type": "paper_compile_fix_writeback_json", "path": _write_evidence_payload(paths["fix_writeback"], evidence)}
    return {
        "requested": True,
        "applied": status == "completed",
        "status": status,
        "artifact": artifact,
        "artifacts": artifacts,
        "limitations": limitations,
        "write": write,
    }


def _allowlist_payloads(contract: dict[str, Any]) -> list[dict[str, Any]]:
    payloads: list[dict[str, Any]] = []
    entries = contract.get("allowlist_evidence") if isinstance(contract.get("allowlist_evidence"), list) else []
    for entry in entries:
        if not isinstance(entry, dict) or not entry.get("exists"):
            continue
        raw_path = str(entry.get("path") or entry.get("artifact_path") or "").strip()
        if not raw_path:
            continue
        path = _resolve_harness_path(raw_path)
        if path.is_dir():
            continue
        try:
            text = path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        try:
            payload = json.loads(text)
        except json.JSONDecodeError:
            payload = {"commands": [line.strip() for line in text.splitlines() if line.strip()]}
        if isinstance(payload, dict):
            payloads.append(payload)
    return payloads


def _tokenize_command_text(raw: str) -> list[str]:
    if not raw:
        return []
    try:
        tokens = shlex.split(raw, posix=os.name != "nt")
    except ValueError:
        return [raw]
    tokens = [token[1:-1] if len(token) >= 2 and token[0] == token[-1] and token[0] in {"'", '"'} else token for token in tokens]
    if not tokens:
        return []

    if os.name == "nt":
        recovered: list[str] = []
        index = 0
        while index < len(tokens):
            token = tokens[index]
            if re.match(r"^[A-Za-z]:[\\/]", token):
                end = index + 1
                candidate = token
                while end < len(tokens) and not tokens[end].startswith("-"):
                    if Path(candidate).is_file() and (
                        end >= len(tokens)
                        or tokens[end].startswith("-")
                        or re.match(r"^[A-Za-z]:[\\/]", tokens[end])
                    ):
                        break
                    candidate = " ".join(tokens[index : end + 1])
                    end += 1
                recovered.append(candidate)
                index = end
                continue
            recovered.append(token)
            index += 1
        tokens = recovered

    # Some environments place repositories under paths with spaces.
    # If the split broke the executable path, recover by joining prefix tokens
    # until a concrete file path exists.
    first = tokens[0]
    if Path(first).exists() or _resolve_harness_path(first).exists():
        return tokens

    for idx in range(2, min(len(tokens), 8) + 1):
        candidate = " ".join(tokens[:idx])
        if Path(candidate).exists() or _resolve_harness_path(candidate).exists():
            return [candidate] + tokens[idx:]

    return tokens


def _command_allowlisted(command: list[str], contract: dict[str, Any]) -> tuple[bool, str]:
    if not command:
        return False, "empty command"
    command_text = " ".join(command)
    executable = Path(command[0]).name
    for payload in _allowlist_payloads(contract):
        executables = [str(item) for item in payload.get("executables", []) if str(item).strip()]
        if executable in executables or command[0] in executables:
            return True, f"executable allowlisted: {executable}"
        for key in ("commands", "allowed_commands"):
            values = [str(item) for item in payload.get(key, []) if str(item).strip()]
            if command_text in values or command[0] in values or executable in values:
                return True, f"command allowlisted by {key}"
            for value in values:
                template_tokens = _tokenize_command_text(value)
                if not template_tokens:
                    continue
                if len(template_tokens) != len(command):
                    continue
                matched = True
                for command_token, template_token in zip(command, template_tokens):
                    if "{" in template_token and "}" in template_token:
                        continue
                    if command_token != template_token:
                        matched = False
                        break
                if matched:
                    return True, f"command allowlist template matched by {key}"
        prefixes = [str(item) for item in payload.get("allowed_prefixes", []) if str(item).strip()]
        if any(command_text.startswith(prefix) for prefix in prefixes):
            return True, "command allowlisted by prefix"
    return False, f"command is not allowlisted: {command_text}"


def _command_from_template(raw: Any, values: dict[str, str]) -> list[str]:
    if isinstance(raw, list):
        parts = [str(item) for item in raw if str(item).strip()]
    elif isinstance(raw, str):
        parts = _tokenize_command_text(raw)
    else:
        return []
    return [part.format(**values) for part in parts]


def _poster_render_command(contract: dict[str, Any], html_path: Path, png_path: Path, validation_path: Path) -> tuple[list[str], str]:
    values = {
        "html": str(html_path),
        "png": str(png_path),
        "validation": str(validation_path),
    }
    for payload in _allowlist_payloads(contract):
        command = _command_from_template(payload.get("poster_render_command"), values)
        if command:
            return command, "poster_render_command allowlisted"
        renderer = str(payload.get("poster_renderer") or "").strip()
        if renderer:
            return [renderer, values["html"], values["png"], values["validation"]], "poster_renderer allowlisted"
    return [], "No poster_render_command or poster_renderer was found in allowlist evidence."


def _format_command(raw: Any, values: dict[str, str]) -> list[str]:
    if isinstance(raw, list):
        rendered: list[str] = []
        for item in raw:
            text = str(item).strip()
            if not text:
                continue
            try:
                text = text.format(**values)
            except (KeyError, IndexError):
                pass
            rendered.append(text)
        return rendered
    text = str(raw).strip()
    if not text:
        return []
    try:
        text = text.format(**values)
    except (KeyError, IndexError):
        pass
    return _tokenize_command_text(text)


def _iter_experiment_run_commands(
    plan: dict[str, Any],
    contract: dict[str, Any],
    experiment_id: str,
) -> list[tuple[list[str], str]]:
    values = {"experiment_id": experiment_id}
    commands: list[tuple[list[str], str]] = []
    for raw in list(plan.get("command_allowlist") or []):
        parsed = _format_command(raw, values)
        if parsed:
            commands.append((parsed, "plan"))
    for payload in _allowlist_payloads(contract):
        for key in ("commands", "allowed_commands"):
            candidates = payload.get(key, [])
            for raw in candidates if isinstance(candidates, list) else []:
                parsed = _format_command(raw, values)
                if parsed:
                    commands.append((parsed, f"allowlist:{key}"))
    return commands


def _normalize_command(command: list[str]) -> list[str]:
    if not command:
        return []
    resolved = list(command)
    candidate = _resolve_harness_path(resolved[0])
    if candidate.exists():
        resolved[0] = str(candidate)
    return resolved


def _strict_execution_argv(
    selected: list[str],
    plan: dict[str, Any],
    contract: dict[str, Any],
) -> tuple[bool, str, list[str]]:
    """Authorize only one normalized, token-for-token argv at the execution edge.

    Normalization is deliberately limited to resolving the executable token on
    both sides. Runner paths, argument order, prefixes, and output paths must
    remain byte-for-byte identical after that normalization. A command may be
    supplied either by the experiment plan or by an exact full-command
    allowlist entry; executable-only and prefix authorizations are never
    accepted at this execution edge.
    """
    normalized_selected = _normalize_command([str(item) for item in selected])
    normalized_planned = _normalize_command(
        [str(item) for item in plan.get("command_argv") or []]
    )
    expected = normalized_planned or normalized_selected
    experiment_id = str(plan.get("experiment_id") or "experiment-unresolved")

    for payload in _allowlist_payloads(contract):
        for key in ("commands", "allowed_commands"):
            candidates = payload.get(key)
            if not isinstance(candidates, list):
                continue
            for candidate in candidates:
                normalized_candidate = _normalize_command(
                    _format_command(candidate, {"experiment_id": experiment_id})
                )
                if normalized_candidate == normalized_selected:
                    source = "plan" if normalized_selected == normalized_planned else "exact full-command allowlist"
                    return True, f"normalized token-for-token {source} and {key} match", normalized_selected

    if normalized_planned and normalized_selected != normalized_planned:
        return (
            False,
            "selected argv differs from the normalized experiment-plan command_argv and has no exact full-command authorization",
            normalized_selected,
        )

    for payload in _allowlist_payloads(contract):
        candidates = payload.get("command_argvs")
        if isinstance(candidates, list):
            for candidate in candidates:
                if not isinstance(candidate, list):
                    continue
                normalized_candidate = _normalize_command([str(item) for item in candidate])
                if normalized_candidate == expected:
                    source = "plan and command_argvs" if normalized_planned else "selected argv and command_argvs"
                    return True, f"normalized token-for-token {source} match", normalized_selected
    return (
        False,
        "selected argv has no token-for-token full-command authorization",
        normalized_selected,
    )


def _pick_experiment_command(
    plan: dict[str, Any],
    contract: dict[str, Any],
    experiment_id: str,
) -> tuple[list[str], str]:
    for command, source in _iter_experiment_run_commands(plan, contract, experiment_id):
        allowed, reason = _command_allowlisted(command, contract)
        if allowed:
            return command, f"Experiment command selected from {source}: {reason}"
    reason = "No experiment command was selected"
    candidate_commands = [" ".join(item[0]) for item in _iter_experiment_run_commands(plan, contract, experiment_id)]
    if not candidate_commands:
        return [], reason
    return [], f"{reason}; tried: {candidate_commands}"


def _pick_remote_check_command(
    contract: dict[str, Any],
    *,
    experiment_id: str,
    run_dir: str,
    explicit_command: str,
) -> tuple[list[str], str]:
    values = {"experiment_id": experiment_id, "run_dir": run_dir}
    candidates: list[tuple[list[str], str]] = []
    if explicit_command:
        parsed = _format_command(explicit_command, values)
        if parsed:
            candidates.append((parsed, "inputs.remote_check_command"))
    for payload in _allowlist_payloads(contract):
        for key in ("remote_check_command", "remote_status_command"):
            parsed = _format_command(payload.get(key), values)
            if parsed:
                candidates.append((parsed, f"allowlist:{key}"))
    if run_dir:
        candidates.append((
            [
                sys.executable,
                str(REPO_HARNESS_DIR.parent / "tools" / "remote.py"),
                "check",
                "--experiment",
                experiment_id,
                "--run-dir",
                run_dir,
            ],
            "default:tools/remote.py check",
        ))
    for command, source in candidates:
        allowed, reason = _command_allowlisted(command, contract)
        if allowed:
            return command, f"Remote status command selected from {source}: {reason}"
    if not candidates:
        return [], "No remote status check command was supplied"
    return [], "No remote status check command was allowlisted; tried: " + "; ".join(
        " ".join(command) for command, _source in candidates
    )


def _remote_state_from_status_value(raw: str) -> str:
    value = raw.strip().lower()
    if value in {"completed", "complete", "collected", "succeeded", "success", "done", "passed"}:
        return "completed"
    if value in {"failed", "error", "errored", "crashed"}:
        return "failed"
    if value in {"running", "started", "launched", "queued", "pending", "in_progress"}:
        return "running"
    return "unknown"


def _remote_check_state(record: dict[str, Any], evidence_paths: list[Path]) -> tuple[str, list[str]]:
    observations: list[str] = []
    raw_record_state = str(_field(record, "remote_state", "state", "job_state", "status_value") or "").strip()
    if raw_record_state:
        state = _remote_state_from_status_value(raw_record_state)
        observations.append(f"Remote check payload reported `{raw_record_state}`.")
        if state != "unknown":
            return state, observations
    for path in evidence_paths:
        try:
            payload = json.loads(path.read_text(encoding="utf-8", errors="replace"))
        except (OSError, json.JSONDecodeError):
            observations.append(f"Remote status artifact was present but not JSON: {_rel(path)}")
            continue
        if not isinstance(payload, dict):
            continue
        raw = str(_field(payload, "state", "status", "outcome") or "").strip()
        if raw:
            state = _remote_state_from_status_value(raw)
            observations.append(f"Remote status artifact `{_rel(path)}` reported `{raw}`.")
            if state != "unknown":
                return state, observations
        if path.name in {"results.json", "result.json", "metrics.json"}:
            observations.append(f"Remote result artifact exists: `{_rel(path)}`.")
            return "completed", observations
    if str(record.get("status") or "").lower() == "completed" and evidence_paths:
        observations.append("Remote check found status artifacts but no terminal state.")
        return "running", observations
    return "unknown", observations


LIVE_REMOTE_POLL_TRANSPORTS = {
    "ssh",
    "screen",
    "tmux",
    "slurm",
    "pbs",
    "lsf",
    "k8s",
    "kubernetes",
    "modal",
    "ray",
    "remote_provider",
}


def _remote_poll_boundary(
    record: dict[str, Any],
    *,
    run_dir: str,
    evidence_paths: list[Path],
    remote_state: str,
) -> dict[str, Any]:
    checked_paths = [
        str(item)
        for item in record.get("checked_paths", [])
        if str(item or "").strip()
    ] if isinstance(record.get("checked_paths"), list) else []
    transport = str(_field(record, "transport", "remote_transport", "provider", "remote_provider") or "").strip()
    session_id = str(_field(record, "session_id", "remote_session_id", "provider_session_id", "job_id") or "").strip()
    poll_scope = str(_field(record, "poll_scope", "poll_mode", "remote_poll_mode") or "").strip().lower()
    explicit_live = bool(record.get("live_remote_poll")) or poll_scope in {"live", "provider", "ssh", "remote"}
    transport_key = transport.lower()
    live_transport = transport_key in LIVE_REMOTE_POLL_TRANSPORTS
    live_remote_poll_verified = bool(
        explicit_live
        and live_transport
        and session_id
        and remote_state != "unknown"
    )
    local_artifact_check = bool(run_dir or checked_paths or evidence_paths)
    invalid_reasons: list[str] = []
    if not live_remote_poll_verified:
        if not explicit_live:
            invalid_reasons.append("remote check did not declare live provider polling")
        if not live_transport:
            invalid_reasons.append("remote check did not declare a recognized live transport")
        if not session_id:
            invalid_reasons.append("remote check did not include a provider/session identifier")
        if remote_state == "unknown":
            invalid_reasons.append("remote check did not resolve a concrete remote state")
        if local_artifact_check:
            invalid_reasons.append("status was derived from local run-dir artifacts")
    status = "live_remote_poll" if live_remote_poll_verified else (
        "local_run_dir_check" if local_artifact_check else "incomplete"
    )
    return {
        "schema": "autosci_remote_poll_boundary.v1",
        "status": status,
        "live_remote_poll_verified": live_remote_poll_verified,
        "local_artifact_check": local_artifact_check,
        "transport": transport,
        "session_id": session_id,
        "poll_scope": poll_scope,
        "run_dir": run_dir,
        "checked_paths": checked_paths,
        "evidence_paths": [_rel(path) for path in evidence_paths],
        "remote_state": remote_state,
        "invalid_reasons": _unique_strings(invalid_reasons),
        "limitations": [] if live_remote_poll_verified else [
            "Remote status was derived from local run-dir artifacts or unverified transport metadata, not a proven live SSH/provider poll."
        ],
    }


def _remote_collection_boundary(record: dict[str, Any], *, existing_files: list[Path]) -> dict[str, Any]:
    result_dir = str(record.get("result_dir") or "").strip()
    transport = str(_field(record, "transport", "remote_transport", "provider", "remote_provider") or "").strip()
    session_id = str(_field(record, "session_id", "remote_session_id", "provider_session_id", "job_id") or "").strip()
    collection_scope = str(_field(record, "collection_scope", "collection_mode", "pull_mode") or "").strip().lower()
    explicit_live = bool(record.get("live_remote_collection")) or collection_scope in {"live", "provider", "ssh", "remote"}
    live_transport = transport.lower() in LIVE_REMOTE_POLL_TRANSPORTS
    live_remote_collection_verified = bool(explicit_live and live_transport and session_id and existing_files)
    local_result_dir_collection = bool(result_dir or existing_files)
    invalid_reasons: list[str] = []
    if not live_remote_collection_verified:
        if not explicit_live:
            invalid_reasons.append("pull-results did not declare live provider collection")
        if not live_transport:
            invalid_reasons.append("pull-results did not declare a recognized live transport")
        if not session_id:
            invalid_reasons.append("pull-results did not include a provider/session identifier")
        if not existing_files:
            invalid_reasons.append("pull-results did not produce local result files")
        if local_result_dir_collection:
            invalid_reasons.append("results were collected from a local result directory")
    status = "live_remote_collection" if live_remote_collection_verified else (
        "local_result_dir_collection" if local_result_dir_collection else "incomplete"
    )
    return {
        "schema": "autosci_remote_collection_boundary.v1",
        "status": status,
        "live_remote_collection_verified": live_remote_collection_verified,
        "local_result_dir_collection": local_result_dir_collection,
        "transport": transport,
        "session_id": session_id,
        "collection_scope": collection_scope,
        "result_dir": result_dir,
        "result_paths": [_rel(path) for path in existing_files],
        "invalid_reasons": _unique_strings(invalid_reasons),
        "limitations": [] if live_remote_collection_verified else [
            "Remote results were collected from local files or unverified transport metadata, not a proven live SSH/provider pull-results operation."
        ],
    }


def _runtime_evidence_payload(
    envelope: dict[str, Any],
    *,
    action: str,
    status: str,
    approval_ref: str,
    command_run: str,
    exit_code: int,
    evidence_ids: list[str],
    checks: list[dict[str, Any]],
    runtime_fields: dict[str, Any],
    artifacts: list[dict[str, str]],
    limitations: list[str],
) -> dict[str, Any]:
    return {
        "schema": "autosci_runtime_evidence.v1",
        "task_id": str(envelope.get("task_id") or f"runtime-{action}"),
        "sprint_id": str(envelope.get("sprint_id") or f"runtime-{action}"),
        "node_id": str(envelope.get("node_id") or f"node-runtime-{action}"),
        "status": status,
        "inputs": {"approval_ref": approval_ref},
        "outputs": {
            "runtime": {
                "action": action,
                "status": status,
                "approval_ref": approval_ref,
                "command_run": command_run,
                "exit_code": exit_code,
                "evidence_ids": evidence_ids,
                "checks": checks,
                **runtime_fields,
            }
        },
        "artifacts": artifacts,
        "provenance": {
            "operator_id": "autosci-approved-side-effect-executor",
            "implementation_package": "plugins/autosci",
            "timestamp": datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        },
        "limitations": limitations,
    }


def _latex_tool_paths() -> dict[str, str]:
    return {name: shutil.which(name) or "" for name in ("latexmk", "pdflatex", "xelatex", "lualatex")}


def _paper_compile_command(tool_name: str, tool_path: str, tex_path: Path) -> list[str]:
    if tool_name == "latexmk":
        return [tool_path, "-pdf", "-interaction=nonstopmode", "-halt-on-error", tex_path.name]
    return [tool_path, "-interaction=nonstopmode", "-halt-on-error", tex_path.name]


def _select_paper_compile_command(
    latex_tool_paths: dict[str, str],
    contract: dict[str, Any],
    tex_path: Path,
) -> tuple[str, list[str], str, list[str], list[str]]:
    available = [name for name, path in latex_tool_paths.items() if path]
    rejected: list[str] = []
    for tool_name in ("latexmk", "pdflatex", "xelatex", "lualatex"):
        tool_path = latex_tool_paths.get(tool_name, "")
        if not tool_path:
            continue
        command = _paper_compile_command(tool_name, tool_path, tex_path)
        allowed, allow_reason = _command_allowlisted(command, contract)
        if allowed:
            return tool_name, command, allow_reason, available, rejected
        rejected.append(f"{tool_name}: {allow_reason}")
    if not available:
        return "", [], "No supported TeX executor was found on PATH.", available, rejected
    return "", [], "No available TeX executor was allowlisted: " + "; ".join(rejected), available, rejected


def _execute_paper_compile_if_approved(
    envelope: dict[str, Any],
    contract: dict[str, Any],
    latex_files: list[Path],
    latex_tool_paths: dict[str, str],
) -> tuple[dict[str, Any], dict[str, Any]]:
    inputs = envelope.get("inputs") if isinstance(envelope.get("inputs"), dict) else {}
    if not bool(inputs.get("execute_approved_side_effect")):
        return contract, {"executed": False, "reason": "execute_approved_side_effect=false"}
    output_dir = _output_dir(envelope, "compile_paper")
    runtime_path = _configured_output_path(envelope, "runtime_evidence_path", output_dir / "compile_paper_runtime_evidence.json")
    if not contract.get("ready_for_execution"):
        payload = _runtime_evidence_payload(
            envelope,
            action="compile_paper",
            status="inconclusive",
            approval_ref=str(contract.get("approval_ref") or ""),
            command_run="blocked:approval-contract-incomplete",
            exit_code=1,
            evidence_ids=["paper-compile-runtime:blocked"],
            checks=[{"check": "approval_preflight", "status": "error", "detail": "Approval contract was not ready for execution."}],
            runtime_fields={"pdf_generated": False},
            artifacts=[],
            limitations=["Paper compile executor did not run because approval preflight was incomplete."],
        )
        runtime_rel = _write_json_sidecar(runtime_path, payload)
        contract.setdefault("runtime_evidence", []).append({"path": runtime_rel, "artifact_path": runtime_rel, "exists": True, "kind": "file", "verifiable": True})
        return _refresh_approval_contract(contract), {"executed": False, "reason": "approval_preflight_incomplete", "runtime_path": runtime_rel}
    if not latex_files:
        return contract, {"executed": False, "reason": "no_latex_source"}
    tex_path = latex_files[0]
    executor_name, command, allow_reason, available_tools, rejected_tools = _select_paper_compile_command(
        latex_tool_paths,
        contract,
        tex_path,
    )
    if not command:
        payload = _runtime_evidence_payload(
            envelope,
            action="compile_paper",
            status="inconclusive",
            approval_ref=str(contract.get("approval_ref") or ""),
            command_run="blocked:tex-executor-unavailable-or-not-allowlisted",
            exit_code=1,
            evidence_ids=["paper-compile-runtime:blocked"],
            checks=[
                {
                    "check": "tex_executor_available",
                    "status": "ok" if available_tools else "error",
                    "detail": ", ".join(available_tools) if available_tools else "No supported TeX executor was found on PATH.",
                },
                {"check": "command_allowlisted", "status": "error", "detail": allow_reason},
            ],
            runtime_fields={"pdf_generated": False, "available_tex_executors": available_tools, "rejected_tex_executors": rejected_tools},
            artifacts=[],
            limitations=["Paper compile executor did not run because no available TeX executor was allowlisted."],
        )
        runtime_rel = _write_json_sidecar(runtime_path, payload)
        contract.setdefault("runtime_evidence", []).append({"path": runtime_rel, "artifact_path": runtime_rel, "exists": True, "kind": "file", "verifiable": True})
        reason = "tex_executor_not_found" if not available_tools else "command_not_allowlisted"
        return _refresh_approval_contract(contract), {"executed": False, "reason": reason, "runtime_path": runtime_rel}

    proc = subprocess.run(
        command,
        cwd=tex_path.parent,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
        timeout=int(inputs.get("executor_timeout_seconds") or 120),
    )
    pdf_path = tex_path.with_suffix(".pdf")
    pdf_integrity = _pdf_integrity(pdf_path)
    pdf_generated = proc.returncode == 0 and bool(pdf_integrity.get("valid"))
    stdout_path = output_dir / "compile_paper_executor_stdout.txt"
    stderr_path = output_dir / "compile_paper_executor_stderr.txt"
    stdout_rel = _write_text_sidecar(stdout_path, proc.stdout)
    stderr_rel = _write_text_sidecar(stderr_path, proc.stderr)
    artifacts = [
        {"type": "executor_stdout", "path": stdout_rel},
        {"type": "executor_stderr", "path": stderr_rel},
    ]
    if pdf_path.exists():
        artifacts.append(_artifact("compiled_pdf", pdf_path))
    payload = _runtime_evidence_payload(
        envelope,
        action="compile_paper",
        status="completed" if pdf_generated else "failed",
        approval_ref=str(contract.get("approval_ref") or ""),
        command_run=" ".join(command),
        exit_code=int(proc.returncode),
        evidence_ids=[f"paper-compile-runtime:{executor_name}", _rel(tex_path)],
        checks=[
            {"check": "command_allowlisted", "status": "ok", "detail": allow_reason},
            {"check": "tex_executor", "status": "ok", "detail": executor_name},
            {"check": "exit_code", "status": "ok" if proc.returncode == 0 else "error", "detail": f"exit_code={proc.returncode}"},
            {
                "check": "pdf_generated",
                "status": "ok" if pdf_generated else "error",
                "detail": _rel(pdf_path)
                if pdf_generated
                else str(pdf_integrity.get("detail") or "PDF was not found after executor run."),
            },
        ],
        runtime_fields={
            "pdf_generated": pdf_generated,
            "pdf_path": _rel(pdf_path) if pdf_path.exists() else "",
            "pdf_integrity": pdf_integrity,
            "tex_executor": executor_name,
            "available_tex_executors": available_tools,
        },
        artifacts=artifacts,
        limitations=[f"Approved paper compile executor ran {executor_name} locally."],
    )
    runtime_rel = _write_json_sidecar(runtime_path, payload)
    contract.setdefault("runtime_evidence", []).append({"path": runtime_rel, "artifact_path": runtime_rel, "exists": True, "kind": "file", "verifiable": True})
    if pdf_path.exists():
        contract.setdefault("after_artifacts", []).append({"path": _rel(pdf_path), "artifact_path": _rel(pdf_path), "exists": True, "kind": "file", "verifiable": True})
    return _refresh_approval_contract(contract), {
        "executed": True,
        "executor": executor_name,
        "exit_code": proc.returncode,
        "pdf_path": _rel(pdf_path) if pdf_path.exists() else "",
        "runtime_path": runtime_rel,
    }


def _parse_experiment_output_record(stdout_text: str) -> tuple[dict[str, Any] | None, str]:
    text = (stdout_text or "").strip()
    if not text:
        return None, ""
    lines = [line.strip() for line in text.splitlines() if line.strip()]
    if lines:
        for line in reversed(lines):
            try:
                payload = json.loads(line)
            except json.JSONDecodeError:
                continue
            if not isinstance(payload, dict):
                continue
            if payload.get("schema") == "autosci_remote_cli.v1":
                return payload, "remote_cli_runtime_evidence"
            if payload.get("schema") == "experiment_result.v1":
                result = ((payload.get("outputs") or {}).get("result") or {})
                return result if isinstance(result, dict) else payload, "experiment_result_payload"
            if isinstance(payload.get("result"), dict):
                return payload["result"], "result_key"
            return payload, "experiment_result_key_value"
    try:
        payload = json.loads(text)
    except json.JSONDecodeError:
        return None, ""
    if not isinstance(payload, dict):
        return None, ""
    if payload.get("schema") == "autosci_remote_cli.v1":
        return payload, "remote_cli_runtime_evidence"
    if payload.get("schema") == "experiment_result.v1":
        result = ((payload.get("outputs") or {}).get("result") or {})
        return result if isinstance(result, dict) else payload, "experiment_result_payload"
    if isinstance(payload.get("result"), dict):
        return payload["result"], "result_key"
    return payload, "experiment_result_key_value"


def _collected_result_summary(paths: list[Path]) -> dict[str, Any]:
    metrics: list[dict[str, Any]] = []
    logs: list[str] = []
    evidence_ids: list[str] = []
    outcome = ""
    for path in paths:
        if not path.exists() or not path.is_file():
            continue
        evidence_ids.append(_rel(path))
        try:
            payload = json.loads(path.read_text(encoding="utf-8", errors="replace"))
        except (OSError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        if not outcome:
            raw_outcome = _field(payload, "outcome", "experiment_outcome")
            if str(raw_outcome or "").strip():
                outcome = str(raw_outcome).strip()
        raw_metrics = _field(payload, "metrics")
        if isinstance(raw_metrics, list):
            metrics.extend(item for item in raw_metrics if isinstance(item, dict) and str(item.get("name") or "").strip())
        raw_logs = _field(payload, "logs", "log")
        log_values = raw_logs if isinstance(raw_logs, list) else ([raw_logs] if raw_logs else [])
        logs.extend(str(item) for item in log_values if str(item).strip())
        raw_ids = _field(payload, "evidence_ids")
        id_values = raw_ids if isinstance(raw_ids, list) else ([raw_ids] if raw_ids else [])
        evidence_ids.extend(str(item) for item in id_values if str(item).strip())
    return {
        "metrics": metrics,
        "logs": logs,
        "evidence_ids": _unique_strings(evidence_ids),
        "outcome": outcome,
    }


def _metric_numeric_value(metric: dict[str, Any]) -> float | None:
    raw = metric.get("value")
    if raw is None:
        raw = metric.get("score")
    try:
        return float(raw)
    except (TypeError, ValueError):
        return None


def _metric_seed_id(metric: dict[str, Any]) -> str:
    for key in ("seed", "seed_id", "random_seed", "trial_id", "run_id"):
        value = metric.get(key)
        if str(value or "").strip():
            return str(value).strip()
    return ""


def _metric_aggregate_rows(metrics: list[dict[str, Any]]) -> list[dict[str, Any]]:
    grouped: dict[str, list[tuple[str, float]]] = {}
    for metric in metrics:
        if not isinstance(metric, dict):
            continue
        name = str(metric.get("name") or "").strip()
        seed = _metric_seed_id(metric)
        value = _metric_numeric_value(metric)
        if not name or not seed or value is None:
            continue
        grouped.setdefault(name, []).append((seed, value))
    rows: list[dict[str, Any]] = []
    for name, values in sorted(grouped.items()):
        unique_seeds = _unique_strings([seed for seed, _value in values])
        if len(unique_seeds) < 2:
            continue
        numeric_values = [value for _seed, value in values]
        mean = sum(numeric_values) / len(numeric_values)
        if len(numeric_values) > 1:
            variance = sum((value - mean) ** 2 for value in numeric_values) / (len(numeric_values) - 1)
            std = variance ** 0.5
        else:
            std = 0.0
        rows.append({
            "name": name,
            "mean": mean,
            "std": std,
            "sample_count": len(numeric_values),
            "seed_count": len(unique_seeds),
            "seeds": unique_seeds,
            "values": numeric_values,
        })
    return rows


def _write_metric_aggregate_report(
    envelope: dict[str, Any],
    *,
    action: str,
    stage: str,
    experiment_id: str,
    metrics: list[dict[str, Any]],
    result_paths: list[str],
) -> dict[str, Any]:
    aggregates = _metric_aggregate_rows(metrics)
    seed_metrics = [
        metric
        for metric in metrics
        if isinstance(metric, dict)
        and str(metric.get("name") or "").strip()
        and _metric_seed_id(metric)
        and _metric_numeric_value(metric) is not None
    ]
    report = {
        "schema": "autosci_experiment_metric_aggregate_report.v1",
        "stage": stage,
        "experiment_id": experiment_id,
        "status": "completed" if aggregates else "insufficient_seed_metrics",
        "aggregate_ready": bool(aggregates),
        "metric_count": len(metrics),
        "seed_metric_count": len(seed_metrics),
        "aggregates": aggregates,
        "result_paths": result_paths,
        "limitations": [] if aggregates else [
            "Multi-seed mean/std aggregation requires at least two numeric metric samples with explicit seed metadata."
        ],
    }
    path = _output_dir(envelope, action) / "experiment_metric_aggregate_report.json"
    rel = _write_json_sidecar(path, report)
    return {
        "artifact": {"type": "experiment_metric_aggregate_report_json", "path": rel},
        "report": report,
    }


def _write_experiment_deploy_report(
    envelope: dict[str, Any],
    *,
    action: str,
    experiment_id: str,
    contract: dict[str, Any],
    command: list[str],
    command_reason: str,
    runtime_path: Path,
    deploy_mode: str,
    result_collected: bool,
    exit_code: int | None,
) -> dict[str, str]:
    report = {
        "schema": "autosci_experiment_deploy_report.v1",
        "experiment_id": experiment_id,
        "status": "completed" if exit_code == 0 else "inconclusive" if exit_code is None else "failed",
        "approval_ref": str(contract.get("approval_ref") or ""),
        "approval_state": str(contract.get("approval_state") or "missing"),
        "execution_verified": contract.get("execution_verified") is True,
        "ready_for_execution": contract.get("ready_for_execution") is True,
        "deploy_mode": deploy_mode,
        "command_reason": command_reason,
        "command_run": " ".join(command),
        "exit_code": exit_code,
        "result_collected": result_collected,
        "runtime_evidence_path": _rel(runtime_path),
        "before_artifact_count": len(contract.get("before_artifacts") if isinstance(contract.get("before_artifacts"), list) else []),
        "after_artifact_count": len(contract.get("after_artifacts") if isinstance(contract.get("after_artifacts"), list) else []),
        "limitations": [] if contract.get("execution_verified") else [
            "Deploy report is audit evidence only; final runtime readiness still depends on approval/runtime semantic verification."
        ],
    }
    rel = _write_json_sidecar(_output_dir(envelope, action) / "experiment_deploy_report.json", report)
    return {"type": "experiment_deploy_report_json", "path": rel}


def _write_experiment_run_report(
    envelope: dict[str, Any],
    *,
    action: str,
    stage: str,
    experiment_id: str,
    contract: dict[str, Any],
    command: list[str],
    runtime_path: Path,
    stdout_path: str,
    stderr_path: str,
    exit_code: int,
    result_collected: bool,
    metrics: list[dict[str, Any]],
    evidence_ids: list[str],
    result_paths: list[str],
    collection_identity: str = "",
    collection_duplicate: bool = False,
) -> dict[str, str]:
    report = {
        "schema": "autosci_experiment_run_report.v1",
        "stage": stage,
        "experiment_id": experiment_id,
        "status": "completed" if exit_code == 0 and result_collected else "failed" if exit_code else "inconclusive",
        "approval_ref": str(contract.get("approval_ref") or ""),
        "approval_state": str(contract.get("approval_state") or "missing"),
        "command_run": " ".join(command),
        "exit_code": exit_code,
        "result_collected": result_collected,
        "metric_count": len(metrics),
        "evidence_ids": _unique_strings(evidence_ids),
        "result_paths": result_paths,
        "runtime_evidence_path": _rel(runtime_path),
        "stdout_path": stdout_path,
        "stderr_path": stderr_path,
        "collection_identity": collection_identity,
        "collection_duplicate": collection_duplicate,
        "limitations": [
            "Run report records approved executor observations only; route readiness is still decided by runtime semantic verification and final audit boundary."
        ],
    }
    rel = _write_json_sidecar(_output_dir(envelope, action) / "experiment_run_report.json", report)
    return {"type": "experiment_run_report_json", "path": rel}


def _write_experiment_lease_report(
    envelope: dict[str, Any],
    *,
    action: str,
    stage: str,
    experiment_id: str,
    operator_id: str,
    acquire: dict[str, Any],
    duplicate_probe: dict[str, Any],
    heartbeat: dict[str, Any],
    release: dict[str, Any],
    stale_recovery: dict[str, Any],
) -> dict[str, str]:
    duplicate_blocker = duplicate_probe.get("blocker") if isinstance(duplicate_probe.get("blocker"), dict) else {}
    report = {
        "schema": "autosci_experiment_execution_lease_report.v1",
        "stage": stage,
        "experiment_id": experiment_id,
        "operator_id": operator_id,
        "status": "completed"
        if acquire.get("acquired")
        and release.get("released")
        and (not stale_recovery.get("attempted") or stale_recovery.get("audit_recorded"))
        else "blocked",
        "lease_acquired": bool(acquire.get("acquired")),
        "heartbeat_ok": bool(heartbeat.get("ok")),
        "duplicate_rejected": duplicate_probe.get("acquired") is False
        and str(duplicate_blocker.get("reason") or "") in {"run_node_already_active", "operator_busy"},
        "duplicate_blocker": duplicate_blocker,
        "release_recorded": bool(release.get("released")),
        "lease_id": str((acquire.get("lease") or {}).get("lease_id") or ""),
        "lease_identity": {
            "run_id": str((acquire.get("lease") or {}).get("research_run_id") or ""),
            "node_id": str((acquire.get("lease") or {}).get("node_id") or ""),
            "experiment_id": experiment_id,
        },
        "stale_recovery": stale_recovery,
        "limitations": [
            "Lease report is scoped to cooperating AutoSci experiment operators using ResearchLeaseAdapter."
        ],
    }
    rel = _write_json_sidecar(_output_dir(envelope, action) / "experiment_execution_lease_report.json", report)
    return {"type": "experiment_execution_lease_report_json", "path": rel}


def _exercise_experiment_stale_lease_recovery(
    lease_adapter: ResearchLeaseAdapter,
    *,
    experiment_id: str,
    operator_id: str,
    requested: bool,
) -> dict[str, Any]:
    if not requested:
        return {"attempted": False, "stale_observed": False, "recovered": False, "audit_recorded": False}

    probe_node_id = f"node-experiment-{_slug(experiment_id)}-stale-recovery-probe"
    seed = lease_adapter.acquire(
        experiment_id,
        probe_node_id,
        operator_id,
        ttl_seconds=1,
        heartbeat_timeout_seconds=1,
        recover_stale=True,
        metadata={"stage": "stale_recovery_probe", "trace_id": _slug(experiment_id)},
        safe_metadata_fields=["stage", "trace_id"],
    )
    lease_id = str((seed.get("lease") or {}).get("lease_id") or "")
    if not seed.get("acquired"):
        return {
            "attempted": True,
            "seed_acquired": False,
            "stale_observed": False,
            "recovered": False,
            "audit_recorded": False,
            "blocker": seed.get("blocker") or {},
        }

    time.sleep(1.1)
    stale_observed = lease_adapter.is_stale(experiment_id, probe_node_id)
    recovery = lease_adapter.recover_stale(
        experiment_id,
        probe_node_id,
        reason="experiment_stale_recovery_probe",
    )
    audit_record: dict[str, Any] = {}
    archive_dir = lease_adapter.lease_dir / "archive"
    for archive_path in sorted(archive_dir.glob("*.json")) if archive_dir.exists() else []:
        try:
            candidate = json.loads(archive_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            continue
        if isinstance(candidate, dict) and str(candidate.get("lease_id") or "") == lease_id:
            audit_record = {
                "path": _rel(archive_path),
                "state": str(candidate.get("state") or ""),
                "recovered_at": str(candidate.get("recovered_at") or ""),
                "recovery_reason": str(candidate.get("recovery_reason") or ""),
            }
            break
    audit_recorded = bool(
        audit_record.get("state") == "stale"
        and audit_record.get("recovered_at")
        and audit_record.get("recovery_reason") == "experiment_stale_recovery_probe"
    )
    return {
        "attempted": True,
        "seed_acquired": True,
        "lease_id": lease_id,
        "run_id": experiment_id,
        "node_id": probe_node_id,
        "stale_observed": stale_observed,
        "recovered": bool(recovery.get("recovered")),
        "audit_recorded": audit_recorded,
        "audit": audit_record,
    }


def _component_source(raw: Any, name: str) -> Path:
    text = str(raw or "").strip()
    candidate = _resolve_harness_path(text) if text else Path()
    if not text or not candidate.is_file():
        raise ValueError(f"POC handoff component is missing: {name}={text}")
    return candidate.resolve()


def _component_digest(path: Path, relative_path: str) -> dict[str, Any]:
    digest = hashlib.sha256(path.read_bytes()).hexdigest()
    return {"path": relative_path, "sha256": digest, "bytes": path.stat().st_size}


def _write_experiment_poc_handoff_package(
    envelope: dict[str, Any],
    *,
    experiment_id: str,
    plan: dict[str, Any],
    evidence: dict[str, Any],
    contract: dict[str, Any],
    semantic: dict[str, Any],
    executor_result: dict[str, Any],
) -> dict[str, str]:
    outputs = evidence.get("outputs") if isinstance(evidence.get("outputs"), dict) else {}
    result = outputs.get("result") if isinstance(outputs.get("result"), dict) else {}
    inputs = envelope.get("inputs") if isinstance(envelope.get("inputs"), dict) else {}
    dataset = plan.get("dataset") if isinstance(plan.get("dataset"), dict) else {}
    runner = plan.get("runner") if isinstance(plan.get("runner"), dict) else {}
    report_artifacts = [
        item
        for item in executor_result.get("report_artifacts") or []
        if isinstance(item, dict) and str(item.get("path") or "").strip()
    ]
    lease_path = next(
        (
            str(item.get("path") or "")
            for item in report_artifacts
            if item.get("type") == "experiment_execution_lease_report_json"
        ),
        "",
    )
    expected_artifacts = [str(item) for item in plan.get("expected_artifacts") or [] if str(item).strip()]
    allowlist_inputs = inputs.get("allowlist_evidence") or []
    allowlist_raw = allowlist_inputs[0] if isinstance(allowlist_inputs, list) and allowlist_inputs else allowlist_inputs
    lease_source = _component_source(lease_path, "lease_report")
    lease_payload = json.loads(lease_source.read_text(encoding="utf-8"))
    lease_stale_recovery = lease_payload.get("stale_recovery") if isinstance(lease_payload.get("stale_recovery"), dict) else {}
    stale_audit = lease_stale_recovery.get("audit") if isinstance(lease_stale_recovery.get("audit"), dict) else {}
    source_components = {
        "experiment_plan": _component_source(inputs.get("experiment_plan_evidence"), "experiment_plan"),
        "runner": _component_source(runner.get("path"), "runner"),
        "dataset": _component_source(dataset.get("path"), "dataset"),
        "allowlist": _component_source(allowlist_raw, "allowlist"),
        "manifest": _component_source(Path(str(runner.get("path") or "")).parent / "poc_manifest.json", "manifest"),
        "expected_result": _component_source(expected_artifacts[0] if expected_artifacts else "", "expected_result"),
        "runtime_evidence": _component_source(executor_result.get("runtime_path"), "runtime_evidence"),
        "result": _component_source(executor_result.get("result_path"), "result"),
        "lease_report": lease_source,
    }
    if str(stale_audit.get("path") or "").strip():
        source_components["lease_recovery_audit"] = _component_source(
            stale_audit.get("path"),
            "lease_recovery_audit",
        )
    bundle_root = _output_dir(envelope, "run_experiment") / "poc_handoff_bundle"
    component_dir = bundle_root / "components"
    replay_dir = bundle_root / "replay"
    component_dir.mkdir(parents=True, exist_ok=True)
    replay_dir.mkdir(parents=True, exist_ok=True)
    component_names = {
        "experiment_plan": "experiment_plan.json",
        "runner": "runner.py",
        "dataset": "dataset.csv",
        "allowlist": "command_allowlist.json",
        "manifest": "poc_manifest.json",
        "expected_result": "expected_result.json",
        "runtime_evidence": "runtime_evidence.json",
        "result": "result.json",
        "lease_report": "lease_report.json",
        "lease_recovery_audit": "lease_recovery_audit.json",
    }
    component_paths: dict[str, str] = {}
    for name, source in source_components.items():
        relative_path = f"components/{component_names[name]}"
        target = bundle_root / relative_path
        shutil.copy2(source, target)
        component_paths[name] = relative_path

    approved_argv = _normalize_command([str(item) for item in plan.get("command_argv") or []])
    executed_argv = [str(item) for item in executor_result.get("command") or []]
    replay_argv = [
        approved_argv[0],
        component_paths["runner"],
        component_paths["dataset"],
        "replay/result.json",
    ]
    rewritten_manifest_path = bundle_root / component_paths["manifest"]
    rewritten_manifest = json.loads(source_components["manifest"].read_text(encoding="utf-8"))
    rewritten_manifest.update(
        {
            "runner_path": "runner.py",
            "input_path": "dataset.csv",
            "result_path": "../replay/result.json",
            "allowlist_path": "command_allowlist.json",
            "command": " ".join(shlex.quote(item) for item in replay_argv),
            "replay_cwd": "..",
            "source_manifest_sha256": hashlib.sha256(source_components["manifest"].read_bytes()).hexdigest(),
        }
    )
    _write_json_sidecar(rewritten_manifest_path, rewritten_manifest)
    bundled_lease_path = bundle_root / component_paths["lease_report"]
    bundled_lease = json.loads(bundled_lease_path.read_text(encoding="utf-8"))
    bundled_stale_recovery = bundled_lease.get("stale_recovery") if isinstance(bundled_lease.get("stale_recovery"), dict) else {}
    bundled_audit = bundled_stale_recovery.get("audit") if isinstance(bundled_stale_recovery.get("audit"), dict) else {}
    if "lease_recovery_audit" in component_paths:
        bundled_audit["path"] = component_names["lease_recovery_audit"]
        bundled_stale_recovery["audit"] = bundled_audit
        bundled_lease["stale_recovery"] = bundled_stale_recovery
        _write_json_sidecar(bundled_lease_path, bundled_lease)
    component_hashes = {
        name: _component_digest(bundle_root / relative_path, relative_path)
        for name, relative_path in component_paths.items()
    }
    package = {
        "schema": "autosci_experiment_poc_handoff.v1",
        "status": "completed",
        "experiment_id": experiment_id,
        "summary": "Product-generated experiment assets were approved, executed, evaluated, and consolidated for downstream validation.",
        "production_entrypoints": ["exp-design", "exp-run"],
        "environment": {
            "runtime": "python",
            "python_version": sys.version.split()[0],
            "network_access": str(plan.get("network_access") or "denied"),
            "dependencies": ["Python standard library"],
        },
        "integration": {
            "approved_command": str((plan.get("command_allowlist") or [""])[0] or ""),
            "executed_command": str(result.get("command_run") or ""),
            "approved_argv": approved_argv,
            "executed_argv": executed_argv,
            "exit_code": executor_result.get("exit_code"),
            "result_collected": executor_result.get("result_collected") is True,
        },
        "conformance": {
            "approval_contract_verified": contract.get("execution_verified") is True,
            "runtime_semantic_verified": semantic.get("verified") is True,
            "runtime_semantic_status": str(semantic.get("status") or "missing"),
        },
        "provenance": {
            "producer": "autosci_bridge._write_experiment_poc_handoff_package",
            "implementation_package": "plugins/autosci",
            "action": "run_experiment",
            "created_at": datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
            "source_experiment_plan_sha256": component_hashes["experiment_plan"]["sha256"],
            "schema_validation": {
                "schema": "autosci_experiment_poc_handoff.v1",
                "validator": "jsonschema.Draft202012Validator",
                "status": "passed",
            },
        },
        "components": component_paths,
        "component_hashes": component_hashes,
        "replay": {
            "cwd": ".",
            "argv": replay_argv,
            "expected_output": "replay/result.json",
            "expected_result_component": component_paths["expected_result"],
            "network_access": "denied",
        },
        "lease_recovery": {
            "claimed": bool(lease_stale_recovery.get("attempted")),
            "experiment_id": experiment_id,
            "stale_observed": bool(lease_stale_recovery.get("stale_observed")),
            "recovered": bool(lease_stale_recovery.get("recovered")),
            "audit_recorded": bool(lease_stale_recovery.get("audit_recorded")),
        },
        "evidence_ids": _unique_strings([str(item) for item in result.get("evidence_ids") or []]),
        "known_constraints": [
            "This handoff covers one deterministic local Python POC; it is not evidence for arbitrary package, service, container, or workflow delivery.",
            "Lease coordination is limited to cooperating AutoSci experiment operators.",
        ],
    }
    schema_reasons, schema_warnings = validate_schema(package, "autosci_experiment_poc_handoff.v1")
    formal_validation_warnings = [item for item in schema_warnings if "jsonschema unavailable" in item]
    if schema_reasons or formal_validation_warnings:
        raise ValueError(
            "POC handoff package failed formal schema validation: "
            + "; ".join([*schema_reasons, *formal_validation_warnings])
        )
    package_path = bundle_root / "poc_handoff_package.json"
    rel = _write_json_sidecar(package_path, package)
    return {"type": "experiment_poc_handoff_package_json", "path": rel}


def _execute_experiment_if_approved(
    envelope: dict[str, Any],
    contract: dict[str, Any],
    plan: dict[str, Any],
    *,
    action: str = "run_experiment",
    stage: str = "run",
    result_path_key: str = "experiment_result_path",
    result_json_artifact_type: str = "run_experiment_result_json",
    result_artifact_type: str = "run_experiment_result",
    blocked_evidence_id: str = "experiment-runtime:blocked",
    default_evidence_prefix: str = "experiment-runtime",
    runner_operator_id: str = "autosci-experiment-run-worker",
    executor_label: str = "Experiment",
) -> tuple[dict[str, Any], dict[str, Any]]:
    inputs = envelope.get("inputs") if isinstance(envelope.get("inputs"), dict) else {}
    output_dir = _output_dir(envelope, action)
    runtime_path = _configured_output_path(envelope, "runtime_evidence_path", output_dir / f"{action}_runtime_evidence.json")
    if not bool(inputs.get("execute_approved_side_effect")):
        return contract, {"executed": False, "reason": "execute_approved_side_effect=false"}
    experiment_id = str(plan.get("experiment_id") or inputs.get("experiment_id") or inputs.get("target") or "experiment-unresolved")
    if not contract.get("ready_for_execution"):
        payload = _runtime_evidence_payload(
            envelope,
            action=action,
            status="inconclusive",
            approval_ref=str(contract.get("approval_ref") or ""),
            command_run="blocked:approval-contract-incomplete",
            exit_code=1,
            evidence_ids=[blocked_evidence_id],
            checks=[{"check": "approval_preflight", "status": "error", "detail": "Approval contract was not ready for execution."}],
            runtime_fields={"result_collected": False},
            artifacts=[],
            limitations=[f"{executor_label} executor did not run because approval preflight was incomplete."],
        )
        runtime_rel = _write_json_sidecar(runtime_path, payload)
        contract.setdefault("runtime_evidence", []).append({"path": runtime_rel, "artifact_path": runtime_rel, "exists": True, "kind": "file", "verifiable": True})
        return _refresh_approval_contract(contract), {"executed": False, "reason": "approval_preflight_incomplete", "runtime_path": runtime_rel}

    command, command_reason = _pick_experiment_command(plan, contract, experiment_id)
    if not command:
        payload = _runtime_evidence_payload(
            envelope,
            action=action,
            status="inconclusive",
            approval_ref=str(contract.get("approval_ref") or ""),
            command_run="blocked:experiment-command-availability",
            exit_code=1,
            evidence_ids=[blocked_evidence_id],
            checks=[{"check": "command_allowlisted", "status": "error", "detail": command_reason}],
            runtime_fields={"result_collected": False},
            artifacts=[],
            limitations=[f"{executor_label} executor did not run because no allowlisted command was selected."],
        )
        runtime_rel = _write_json_sidecar(runtime_path, payload)
        contract.setdefault("runtime_evidence", []).append({"path": runtime_rel, "artifact_path": runtime_rel, "exists": True, "kind": "file", "verifiable": True})
        return _refresh_approval_contract(contract), {"executed": False, "reason": "experiment_command_missing", "runtime_path": runtime_rel}

    argv_authorized, argv_reason, command = _strict_execution_argv(command, plan, contract)
    if not argv_authorized:
        payload = _runtime_evidence_payload(
            envelope,
            action=action,
            status="inconclusive",
            approval_ref=str(contract.get("approval_ref") or ""),
            command_run="blocked:strict-experiment-argv-mismatch",
            exit_code=1,
            evidence_ids=[blocked_evidence_id],
            checks=[{"check": "strict_execution_argv", "status": "error", "detail": argv_reason}],
            runtime_fields={
                "result_collected": False,
                "selected_argv": command,
                "approved_argv": [str(item) for item in plan.get("command_argv") or []],
            },
            artifacts=[],
            limitations=[f"{executor_label} executor did not run because strict argv authorization failed."],
        )
        runtime_rel = _write_json_sidecar(runtime_path, payload)
        contract.setdefault("runtime_evidence", []).append({"path": runtime_rel, "artifact_path": runtime_rel, "exists": True, "kind": "file", "verifiable": True})
        return _refresh_approval_contract(contract), {
            "executed": False,
            "reason": "strict_experiment_argv_mismatch",
            "runtime_path": runtime_rel,
            "command": command,
        }
    lease_adapter = ResearchLeaseAdapter(
        HARNESS_DIR,
        operator_runtime_api=False,
        operator_registry_path=REPO_HARNESS_DIR / "config" / "physical-operators.json",
        claim_timeout_seconds=2,
        abandoned_claim_seconds=2,
    )
    run_id = experiment_id
    node_id = f"node-experiment-{_slug(experiment_id)}-{stage}"
    stale_recovery = _exercise_experiment_stale_lease_recovery(
        lease_adapter,
        experiment_id=experiment_id,
        operator_id=runner_operator_id,
        requested=bool(inputs.get("lease_recovery_probe")),
    )
    lease = lease_adapter.acquire(
        run_id,
        node_id,
        runner_operator_id,
        ttl_seconds=int(inputs.get("executor_timeout_seconds") or 120) + 30,
        heartbeat_timeout_seconds=max(1, int(inputs.get("executor_timeout_seconds") or 120)),
        recover_stale=True,
        metadata={"stage": stage, "trace_id": _slug(experiment_id)},
        safe_metadata_fields=["stage", "trace_id"],
    )
    if not lease.get("acquired"):
        payload = _runtime_evidence_payload(
            envelope,
            action=action,
            status="inconclusive",
            approval_ref=str(contract.get("approval_ref") or ""),
            command_run="blocked:experiment-lease-not-acquired",
            exit_code=1,
            evidence_ids=[blocked_evidence_id],
            checks=[{"check": "execution_lease_acquired", "status": "error", "detail": json.dumps(lease.get("blocker") or {}, sort_keys=True)}],
            runtime_fields={"result_collected": False},
            artifacts=[],
            limitations=[f"{executor_label} executor did not run because an execution lease could not be acquired."],
        )
        runtime_rel = _write_json_sidecar(runtime_path, payload)
        contract.setdefault("runtime_evidence", []).append({"path": runtime_rel, "artifact_path": runtime_rel, "exists": True, "kind": "file", "verifiable": True})
        return _refresh_approval_contract(contract), {"executed": False, "reason": "execution_lease_not_acquired", "runtime_path": runtime_rel, "lease": lease}
    lease_id = str((lease.get("lease") or {}).get("lease_id") or "")
    heartbeat = lease_adapter.heartbeat(
        run_id,
        node_id,
        runner_operator_id,
        lease_id=lease_id,
        ttl_seconds=int(inputs.get("executor_timeout_seconds") or 120) + 30,
        state="running",
    )
    duplicate_probe = lease_adapter.acquire(
        run_id,
        node_id,
        runner_operator_id,
        ttl_seconds=30,
        heartbeat_timeout_seconds=30,
        metadata={"stage": stage, "trace_id": "duplicate-probe"},
        safe_metadata_fields=["stage", "trace_id"],
    )
    release: dict[str, Any] = {"released": False, "reason": "not_released"}
    try:
        proc = subprocess.run(
            command,
            cwd=REPO_HARNESS_DIR,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            check=False,
            timeout=int(inputs.get("executor_timeout_seconds") or 120),
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        proc = subprocess.CompletedProcess(
            command,
            124 if isinstance(exc, subprocess.TimeoutExpired) else 127,
            stdout=getattr(exc, "stdout", "") or "",
            stderr=str(exc),
        )
    finally:
        release = lease_adapter.release(
            run_id,
            node_id,
            runner_operator_id,
            lease_id=lease_id,
            reason="completed",
        )
    stdout_rel = _write_text_sidecar(output_dir / f"{action}_executor_stdout.txt", proc.stdout)
    stderr_rel = _write_text_sidecar(output_dir / f"{action}_executor_stderr.txt", proc.stderr)
    lease_report_artifact = _write_experiment_lease_report(
        envelope,
        action=action,
        stage=stage,
        experiment_id=experiment_id,
        operator_id=runner_operator_id,
        acquire=lease,
        duplicate_probe=duplicate_probe,
        heartbeat=heartbeat,
        release=release,
        stale_recovery=stale_recovery,
    )
    artifacts = [
        {"type": "executor_stdout", "path": stdout_rel},
        {"type": "executor_stderr", "path": stderr_rel},
        lease_report_artifact,
    ]
    result_record, result_source = _parse_experiment_output_record(proc.stdout)
    result_payload: dict[str, Any] = {}
    remote_runtime_rel = ""
    session_registry_rel = ""
    is_remote_cli_record = result_source == "remote_cli_runtime_evidence"
    if is_remote_cli_record and isinstance(result_record, dict):
        raw_runtime_path = str(result_record.get("runtime_evidence_path") or "").strip()
        if raw_runtime_path:
            runtime_candidate = _resolve_harness_path(raw_runtime_path)
            if runtime_candidate.exists() and runtime_candidate.is_file():
                remote_runtime_rel = _rel(runtime_candidate)
                contract.setdefault("runtime_evidence", []).append({
                    "path": remote_runtime_rel,
                    "artifact_path": remote_runtime_rel,
                    "exists": True,
                    "kind": "file",
                    "verifiable": True,
                })
                artifacts.append({"type": "remote_runtime_evidence_json", "path": remote_runtime_rel})
        if str(result_record.get("command") or "") == "launch":
            session_record = _record_experiment_session(
                envelope,
                experiment_id=experiment_id,
                command_run=" ".join(command),
                record=result_record,
                remote_runtime_rel=remote_runtime_rel,
            )
            session_registry_rel = str(session_record.get("registry_path") or "")
            if session_registry_rel:
                artifacts.append({"type": "experiment_session_registry_json", "path": session_registry_rel})
    if result_record and not is_remote_cli_record:
        result_payload.update({
            "experiment_id": str(result_record.get("experiment_id") or experiment_id),
            "outcome": str(result_record.get("outcome") or "supports"),
            "metrics": list(result_record.get("metrics") or []),
            "evidence_ids": list(result_record.get("evidence_ids") or []),
            "logs": list(result_record.get("logs") or []),
        })
        if not result_payload["evidence_ids"]:
            result_payload["evidence_ids"] = [f"{default_evidence_prefix}:{_slug(experiment_id)}"]
        if not result_payload["metrics"]:
            result_payload["metrics"] = [{"name": "experiment_exit_code", "value": int(proc.returncode)}]
    elif result_record and is_remote_cli_record:
        result_payload = {
            "experiment_id": experiment_id,
            "outcome": "failed" if proc.returncode != 0 else "inconclusive",
            "metrics": [],
            "evidence_ids": [],
            "logs": [
                "Remote helper stdout parsed; semantic experiment result is delegated to runtime_evidence_path."
            ],
        }
    else:
        result_payload = {
            "experiment_id": experiment_id,
            "outcome": "supports" if proc.returncode == 0 else "failed",
            "metrics": [{"name": "experiment_exit_code", "value": int(proc.returncode)}],
            "evidence_ids": [f"{default_evidence_prefix}:{_slug(experiment_id)}"],
            "logs": [f"{executor_label} command executed without parseable experiment payload."],
        }
    result_collected = False if is_remote_cli_record else (bool(result_record) or bool(proc.stdout.strip()))
    runtime_result_path = _configured_output_path(
        envelope,
        result_path_key,
        output_dir / f"{action}_result.json",
    )
    runtime_result_rel = _rel(runtime_result_path)
    runtime_result_json: dict[str, Any] = {
        "schema": "experiment_result.v1",
        "task_id": str(envelope.get("task_id") or f"runtime-{_slug(experiment_id)}"),
        "sprint_id": str(envelope.get("sprint_id") or f"runtime-{action.replace('_', '-')}"),
        "node_id": str(envelope.get("node_id") or f"node-runtime-{action.replace('_', '-')}"),
        "status": "completed" if result_collected else "inconclusive",
        "inputs": dict(envelope.get("inputs") or {}),
        "outputs": {"result": result_payload},
        "artifacts": [{"type": result_json_artifact_type, "path": runtime_result_rel}],
        "provenance": {
            "operator_id": runner_operator_id,
            "implementation_package": "plugins/autosci",
            "timestamp": datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        },
        "limitations": [f"{executor_label} result generated from command output source={result_source}."],
    }
    runtime_result_rel = _write_json_sidecar(runtime_result_path, runtime_result_json)
    artifacts.append({"type": result_artifact_type, "path": runtime_result_rel})
    semantic_result_path = "" if is_remote_cli_record else runtime_result_rel
    semantic_result_artifacts = [] if is_remote_cli_record else [runtime_result_rel]
    metrics = list(result_payload.get("metrics") or [])
    result_paths = [semantic_result_path] if semantic_result_path else []
    report_artifacts: list[dict[str, str]] = []
    metric_aggregates: list[dict[str, Any]] = []
    if any(_metric_seed_id(metric) for metric in metrics if isinstance(metric, dict)):
        aggregate_report = _write_metric_aggregate_report(
            envelope,
            action=action,
            stage=stage,
            experiment_id=experiment_id,
            metrics=metrics,
            result_paths=result_paths,
        )
        report_artifacts.append(aggregate_report["artifact"])
        metric_aggregates = list(aggregate_report["report"].get("aggregates") or [])
    deploy_mode = (
        "remote_launch"
        if is_remote_cli_record and str((result_record or {}).get("command") or "") == "launch"
        else "remote_helper"
        if is_remote_cli_record
        else "local_command"
    )
    report_artifacts.extend([
        lease_report_artifact,
        _write_experiment_deploy_report(
            envelope,
            action=action,
            experiment_id=experiment_id,
            contract=contract,
            command=command,
            command_reason=command_reason,
            runtime_path=runtime_path,
            deploy_mode=deploy_mode,
            result_collected=result_collected,
            exit_code=int(proc.returncode),
        ),
        _write_experiment_run_report(
            envelope,
            action=action,
            stage=stage,
            experiment_id=experiment_id,
            contract=contract,
            command=command,
            runtime_path=runtime_path,
            stdout_path=stdout_rel,
            stderr_path=stderr_rel,
            exit_code=int(proc.returncode),
            result_collected=result_collected,
            metrics=metrics,
            evidence_ids=[str(item) for item in result_payload.get("evidence_ids") or [] if str(item).strip()],
            result_paths=result_paths,
        ),
    ])
    artifacts.extend(report_artifacts)
    payload = _runtime_evidence_payload(
        envelope,
        action=action,
        status="completed" if proc.returncode == 0 and result_collected else "failed",
        approval_ref=str(contract.get("approval_ref") or ""),
        command_run=" ".join(command),
        exit_code=int(proc.returncode),
        evidence_ids=[str(item) for item in result_payload.get("evidence_ids") or [f"{default_evidence_prefix}:{_slug(experiment_id)}"] if str(item).strip()],
        checks=[
            {"check": "command_allowlisted", "status": "ok", "detail": command_reason},
            {"check": "exit_code", "status": "ok" if proc.returncode == 0 else "error", "detail": f"exit_code={proc.returncode}"},
            {"check": "result_collected", "status": "ok" if result_collected else "warn", "detail": str(result_collected)},
            {"check": "result_payload_source", "status": "ok" if result_source else "warn", "detail": result_source or "not-structured"},
        ],
        runtime_fields={
            "result_collected": result_collected,
            "metrics": list(result_payload.get("metrics") or []),
            "outcome": str(result_payload.get("outcome") or ("supports" if proc.returncode == 0 else "failed")),
            "logs": list(result_payload.get("logs") or []),
            "result_path": semantic_result_path,
            "result": result_payload,
            "result_artifacts": semantic_result_artifacts,
            "metric_aggregates": metric_aggregates,
            "parsed_record_count": 1 if result_record else 0,
            "remote_runtime_evidence_path": remote_runtime_rel,
            "session_registry_path": session_registry_rel,
        },
        artifacts=artifacts,
        limitations=[f"Approved {executor_label.lower()} executor ran a real command locally (subject to allowlist and approval contract)."],
    )
    runtime_rel = _write_json_sidecar(runtime_path, payload)
    contract.setdefault("runtime_evidence", []).append({"path": runtime_rel, "artifact_path": runtime_rel, "exists": True, "kind": "file", "verifiable": True})
    contract.setdefault("after_artifacts", []).append({
        "path": runtime_result_rel,
        "artifact_path": runtime_result_rel,
        "exists": True,
        "kind": "file",
        "verifiable": True,
    })
    return _refresh_approval_contract(contract), {
        "executed": True,
        "command": command,
        "exit_code": proc.returncode,
        "runtime_path": runtime_rel,
        "result_path": runtime_result_path,
        "stdout_path": stdout_rel,
        "stderr_path": stderr_rel,
        "result_collected": result_collected,
        "report_artifacts": report_artifacts,
    }


def _execute_monitor_collect_if_approved(
    envelope: dict[str, Any],
    contract: dict[str, Any],
    plan: dict[str, Any],
    experiment_id: str,
) -> tuple[dict[str, Any], dict[str, Any]]:
    inputs = envelope.get("inputs") if isinstance(envelope.get("inputs"), dict) else {}
    output_dir = _output_dir(envelope, "monitor_experiment")
    runtime_path = _configured_output_path(envelope, "runtime_evidence_path", output_dir / "monitor_experiment_runtime_evidence.json")
    if not bool(inputs.get("execute_approved_side_effect")):
        return contract, {"executed": False, "reason": "execute_approved_side_effect=false"}
    if not contract.get("ready_for_execution"):
        payload = _runtime_evidence_payload(
            envelope,
            action="run_experiment",
            status="inconclusive",
            approval_ref=str(contract.get("approval_ref") or ""),
            command_run="blocked:collect-approval-contract-incomplete",
            exit_code=1,
            evidence_ids=["remote-collect:blocked"],
            checks=[{"check": "approval_preflight", "status": "error", "detail": "Approval contract was not ready for collect execution."}],
            runtime_fields={"result_collected": False},
            artifacts=[],
            limitations=["Collect executor did not run because approval preflight was incomplete."],
        )
        runtime_rel = _write_json_sidecar(runtime_path, payload)
        contract.setdefault("runtime_evidence", []).append({"path": runtime_rel, "artifact_path": runtime_rel, "exists": True, "kind": "file", "verifiable": True})
        return _refresh_approval_contract(contract), {"executed": False, "reason": "approval_preflight_incomplete", "runtime_path": runtime_rel}

    command, command_reason = _pick_experiment_command(plan, contract, experiment_id)
    if not command:
        payload = _runtime_evidence_payload(
            envelope,
            action="run_experiment",
            status="inconclusive",
            approval_ref=str(contract.get("approval_ref") or ""),
            command_run="blocked:collect-command-availability",
            exit_code=1,
            evidence_ids=["remote-collect:blocked"],
            checks=[{"check": "command_allowlisted", "status": "error", "detail": command_reason}],
            runtime_fields={"result_collected": False},
            artifacts=[],
            limitations=["Collect executor did not run because no allowlisted collect command was selected."],
        )
        runtime_rel = _write_json_sidecar(runtime_path, payload)
        contract.setdefault("runtime_evidence", []).append({"path": runtime_rel, "artifact_path": runtime_rel, "exists": True, "kind": "file", "verifiable": True})
        return _refresh_approval_contract(contract), {"executed": False, "reason": "collect_command_missing", "runtime_path": runtime_rel}

    command = _normalize_command(command)
    proc = subprocess.run(
        command,
        cwd=REPO_HARNESS_DIR,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
        timeout=int(inputs.get("executor_timeout_seconds") or 120),
    )
    stdout_rel = _write_text_sidecar(output_dir / "monitor_experiment_executor_stdout.txt", proc.stdout)
    stderr_rel = _write_text_sidecar(output_dir / "monitor_experiment_executor_stderr.txt", proc.stderr)
    artifacts = [
        {"type": "executor_stdout", "path": stdout_rel},
        {"type": "executor_stderr", "path": stderr_rel},
    ]
    result_record, result_source = _parse_experiment_output_record(proc.stdout)
    remote_cli_status = str(result_record.get("status") or "") if isinstance(result_record, dict) else ""
    remote_cli_command = str(result_record.get("command") or "") if isinstance(result_record, dict) else ""
    files_raw = result_record.get("files") if isinstance(result_record, dict) and isinstance(result_record.get("files"), list) else []
    collected_files = [
        _resolve_harness_path(str(item))
        for item in files_raw
        if str(item or "").strip()
    ]
    existing_files = [path for path in collected_files if path.exists() and path.is_file()]
    summary = _collected_result_summary(existing_files)
    metrics = list(summary.get("metrics") or [])
    if existing_files and not metrics:
        metrics = [{"name": "collected_file_count", "value": len(existing_files)}]
    outcome = str(summary.get("outcome") or ("supports" if existing_files else "inconclusive"))
    evidence_ids = _unique_strings([f"remote-collect:{_slug(experiment_id)}", *[str(item) for item in summary.get("evidence_ids") or []]])
    result_collected = proc.returncode == 0 and bool(existing_files)
    collection_boundary = _remote_collection_boundary(
        result_record if isinstance(result_record, dict) else {},
        existing_files=existing_files,
    )
    runtime_status = "completed" if result_collected else ("failed" if proc.returncode else "inconclusive")
    ledger_result: dict[str, Any] = {}
    if result_collected:
        ledger_result = _record_collection_ledger(
            envelope,
            experiment_id=experiment_id,
            command_run=" ".join(command),
            collected_files=existing_files,
            evidence_ids=evidence_ids,
        )
        artifacts.append({"type": "collection_ledger_json", "path": str(ledger_result.get("ledger_path") or "")})
    for path in existing_files:
        rel = _rel(path)
        artifacts.append({"type": "remote_collected_file", "path": rel})
        contract.setdefault("after_artifacts", []).append({
            "path": rel,
            "artifact_path": rel,
            "exists": True,
            "kind": "file",
            "verifiable": True,
        })
    result_paths = [_rel(path) for path in existing_files]
    report_artifacts: list[dict[str, str]] = []
    metric_aggregates: list[dict[str, Any]] = []
    if any(_metric_seed_id(metric) for metric in metrics if isinstance(metric, dict)):
        aggregate_report = _write_metric_aggregate_report(
            envelope,
            action="monitor_experiment",
            stage="collect",
            experiment_id=experiment_id,
            metrics=metrics,
            result_paths=result_paths,
        )
        report_artifacts.append(aggregate_report["artifact"])
        metric_aggregates = list(aggregate_report["report"].get("aggregates") or [])
    report_artifacts.append(
        _write_experiment_run_report(
            envelope,
            action="monitor_experiment",
            stage="collect",
            experiment_id=experiment_id,
            contract=contract,
            command=command,
            runtime_path=runtime_path,
            stdout_path=stdout_rel,
            stderr_path=stderr_rel,
            exit_code=int(proc.returncode),
            result_collected=result_collected,
            metrics=metrics,
            evidence_ids=evidence_ids,
            result_paths=result_paths,
            collection_identity=str(ledger_result.get("collection_identity") or ""),
            collection_duplicate=bool(ledger_result.get("duplicate")),
        )
    )
    artifacts.extend(report_artifacts)
    payload = _runtime_evidence_payload(
        envelope,
        action="run_experiment",
        status=runtime_status,
        approval_ref=str(contract.get("approval_ref") or ""),
        command_run=" ".join(command),
        exit_code=int(proc.returncode),
        evidence_ids=evidence_ids,
        checks=[
            {"check": "command_allowlisted", "status": "ok", "detail": command_reason},
            {"check": "exit_code", "status": "ok" if proc.returncode == 0 else "error", "detail": f"exit_code={proc.returncode}"},
            {"check": "remote_cli_output", "status": "ok" if result_source == "remote_cli_runtime_evidence" else "warn", "detail": result_source or "not-structured"},
            {"check": "collected_files_present", "status": "ok" if existing_files else "error", "detail": str(len(existing_files))},
            {
                "check": "remote_collection_boundary",
                "status": "ok" if collection_boundary.get("live_remote_collection_verified") else "warn",
                "detail": ",".join(collection_boundary.get("invalid_reasons") or []),
            },
        ],
        runtime_fields={
            "result_collected": result_collected,
            "metrics": metrics,
            "outcome": outcome,
            "logs": [*list(summary.get("logs") or []), f"remote_cli_status={remote_cli_status or 'N/A'}"],
            "result_paths": result_paths,
            "remote_cli_command": remote_cli_command,
            "remote_cli_status": remote_cli_status,
            "collection_identity": str(ledger_result.get("collection_identity") or ""),
            "collection_duplicate": bool(ledger_result.get("duplicate")),
            "collection_ledger_path": str(ledger_result.get("ledger_path") or ""),
            "remote_collection_boundary": collection_boundary,
            "metric_aggregates": metric_aggregates,
            "parsed_record_count": 1 if result_record else 0,
        },
        artifacts=artifacts,
        limitations=[
            "Approved collect executor ran a real command locally and verified collected result files.",
            *collection_boundary.get("limitations", []),
        ],
    )
    runtime_rel = _write_json_sidecar(runtime_path, payload)
    contract.setdefault("runtime_evidence", []).append({"path": runtime_rel, "artifact_path": runtime_rel, "exists": True, "kind": "file", "verifiable": True})
    contract.setdefault("after_artifacts", []).append({"path": runtime_rel, "artifact_path": runtime_rel, "exists": True, "kind": "file", "verifiable": True})
    return _refresh_approval_contract(contract), {
        "executed": True,
        "command": command,
        "exit_code": proc.returncode,
        "runtime_path": runtime_rel,
        "stdout_path": stdout_rel,
        "stderr_path": stderr_rel,
        "collected_files": [_rel(path) for path in existing_files],
        "result_collected": result_collected,
        "collection_identity": str(ledger_result.get("collection_identity") or ""),
        "collection_duplicate": bool(ledger_result.get("duplicate")),
        "collection_ledger_path": str(ledger_result.get("ledger_path") or ""),
        "remote_collection_boundary": collection_boundary,
        "report_artifacts": report_artifacts,
    }


def _execute_remote_check_if_approved(
    envelope: dict[str, Any],
    contract: dict[str, Any],
    *,
    experiment_id: str,
    session: dict[str, Any] | None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    inputs = envelope.get("inputs") if isinstance(envelope.get("inputs"), dict) else {}
    output_dir = _output_dir(envelope, "monitor_experiment")
    runtime_path = _configured_output_path(envelope, "runtime_evidence_path", output_dir / "remote_status_runtime_evidence.json")
    explicit_command = str(inputs.get("remote_check_command") or "").strip()
    run_dir = str(inputs.get("remote_run_dir") or (session or {}).get("run_dir") or "").strip()
    if not bool(inputs.get("execute_approved_side_effect")):
        return contract, {"executed": False, "reason": "execute_approved_side_effect=false"}
    if not contract.get("ready_for_execution"):
        payload = _runtime_evidence_payload(
            envelope,
            action="monitor_experiment",
            status="inconclusive",
            approval_ref=str(contract.get("approval_ref") or ""),
            command_run="blocked:remote-status-approval-contract-incomplete",
            exit_code=1,
            evidence_ids=[f"remote-status:{_slug(experiment_id)}"],
            checks=[{"check": "approval_preflight", "status": "error", "detail": "Approval contract was not ready for remote status check."}],
            runtime_fields={"remote_status_state": "unknown", "result_collected": False},
            artifacts=[],
            limitations=["Remote status check did not run because approval preflight was incomplete."],
        )
        runtime_rel = _write_json_sidecar(runtime_path, payload)
        contract.setdefault("runtime_evidence", []).append({"path": runtime_rel, "artifact_path": runtime_rel, "exists": True, "kind": "file", "verifiable": True})
        return _refresh_approval_contract(contract), {"executed": False, "reason": "approval_preflight_incomplete", "runtime_path": runtime_rel}

    command, command_reason = _pick_remote_check_command(
        contract,
        experiment_id=experiment_id,
        run_dir=run_dir,
        explicit_command=explicit_command,
    )
    if not command:
        payload = _runtime_evidence_payload(
            envelope,
            action="monitor_experiment",
            status="inconclusive",
            approval_ref=str(contract.get("approval_ref") or ""),
            command_run="blocked:remote-status-command-availability",
            exit_code=1,
            evidence_ids=[f"remote-status:{_slug(experiment_id)}"],
            checks=[{"check": "command_allowlisted", "status": "error", "detail": command_reason}],
            runtime_fields={"remote_status_state": "unknown", "result_collected": False},
            artifacts=[],
            limitations=["Remote status check did not run because no allowlisted status command was selected."],
        )
        runtime_rel = _write_json_sidecar(runtime_path, payload)
        contract.setdefault("runtime_evidence", []).append({"path": runtime_rel, "artifact_path": runtime_rel, "exists": True, "kind": "file", "verifiable": True})
        return _refresh_approval_contract(contract), {"executed": False, "reason": "remote_status_command_missing", "runtime_path": runtime_rel}

    command = _normalize_command(command)
    proc = subprocess.run(
        command,
        cwd=REPO_HARNESS_DIR,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
        timeout=int(inputs.get("executor_timeout_seconds") or 120),
    )
    stdout_rel = _write_text_sidecar(output_dir / "remote_status_executor_stdout.txt", proc.stdout)
    stderr_rel = _write_text_sidecar(output_dir / "remote_status_executor_stderr.txt", proc.stderr)
    record, source = _parse_experiment_output_record(proc.stdout)
    record = record if isinstance(record, dict) else {}
    is_check_record = (
        source == "remote_cli_runtime_evidence"
        and record.get("schema") == "autosci_remote_cli.v1"
        and record.get("command") == "check"
    )
    evidence_paths = [
        _resolve_harness_path(str(item))
        for item in record.get("evidence_paths", [])
        if str(item or "").strip()
    ] if is_check_record and isinstance(record.get("evidence_paths"), list) else []
    evidence_paths = [path for path in evidence_paths if path.exists() and path.is_file()]
    remote_state, state_observations = _remote_check_state(record, evidence_paths)
    poll_boundary = _remote_poll_boundary(
        record,
        run_dir=run_dir,
        evidence_paths=evidence_paths,
        remote_state=remote_state,
    )
    live_poll_verified = bool(poll_boundary.get("live_remote_poll_verified"))
    state_resolved = remote_state != "unknown"
    runtime_status = "completed" if proc.returncode == 0 and is_check_record and (
        bool(evidence_paths) or live_poll_verified
    ) and state_resolved else (
        "failed" if proc.returncode else "inconclusive"
    )
    artifacts = [
        {"type": "executor_stdout", "path": stdout_rel},
        {"type": "executor_stderr", "path": stderr_rel},
        *[{"type": "remote_status_file", "path": _rel(path)} for path in evidence_paths],
    ]
    evidence_ids = _unique_strings([
        f"remote-status:{_slug(experiment_id)}",
        *[_rel(path) for path in evidence_paths],
    ])
    payload = _runtime_evidence_payload(
        envelope,
        action="monitor_experiment",
        status=runtime_status,
        approval_ref=str(contract.get("approval_ref") or ""),
        command_run=" ".join(command),
        exit_code=int(proc.returncode),
        evidence_ids=evidence_ids,
        checks=[
            {"check": "command_allowlisted", "status": "ok", "detail": command_reason},
            {"check": "exit_code", "status": "ok" if proc.returncode == 0 else "error", "detail": f"exit_code={proc.returncode}"},
            {"check": "remote_cli_check_output", "status": "ok" if is_check_record else "error", "detail": source or "not-structured"},
            {
                "check": "remote_status_artifacts_present",
                "status": "ok" if evidence_paths or live_poll_verified else "error",
                "detail": str(len(evidence_paths)) if evidence_paths else "live_provider_payload",
            },
            {
                "check": "remote_poll_boundary",
                "status": "ok" if poll_boundary.get("live_remote_poll_verified") else "warn",
                "detail": ",".join(poll_boundary.get("invalid_reasons") or []),
            },
        ],
        runtime_fields={
            "remote_status_state": remote_state,
            "remote_cli_command": str(record.get("command") or ""),
            "remote_cli_status": str(record.get("status") or ""),
            "checked_paths": [str(item) for item in record.get("checked_paths", []) if str(item).strip()]
            if isinstance(record.get("checked_paths"), list)
            else [],
            "evidence_paths": [_rel(path) for path in evidence_paths],
            "run_dir": run_dir,
            "result_collected": False,
            "logs": state_observations,
            "remote_poll_boundary": poll_boundary,
        },
        artifacts=artifacts,
        limitations=[
            "Approved remote status check ran an allowlisted command and verified status artifacts; no results were collected.",
            *poll_boundary.get("limitations", []),
        ],
    )
    runtime_rel = _write_json_sidecar(runtime_path, payload)
    contract.setdefault("runtime_evidence", []).append({"path": runtime_rel, "artifact_path": runtime_rel, "exists": True, "kind": "file", "verifiable": True})
    contract.setdefault("after_artifacts", []).append({"path": runtime_rel, "artifact_path": runtime_rel, "exists": True, "kind": "file", "verifiable": True})
    for path in evidence_paths:
        rel = _rel(path)
        contract.setdefault("after_artifacts", []).append({"path": rel, "artifact_path": rel, "exists": True, "kind": "file", "verifiable": True})
    return _refresh_approval_contract(contract), {
        "executed": True,
        "command": command,
        "exit_code": proc.returncode,
        "runtime_path": runtime_rel,
        "stdout_path": stdout_rel,
        "stderr_path": stderr_rel,
        "state": remote_state,
        "status": runtime_status,
        "evidence_paths": [_rel(path) for path in evidence_paths],
        "observations": state_observations,
        "remote_poll_boundary": poll_boundary,
    }


def _load_runtime_validation(path: Path) -> dict[str, Any]:
    if not path.exists():
        return {}
    try:
        payload = json.loads(path.read_text(encoding="utf-8", errors="replace"))
    except (OSError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


def _execute_poster_if_approved(
    envelope: dict[str, Any],
    contract: dict[str, Any],
    html_path: Path,
) -> tuple[dict[str, Any], dict[str, Any]]:
    inputs = envelope.get("inputs") if isinstance(envelope.get("inputs"), dict) else {}
    if not bool(inputs.get("execute_approved_side_effect")):
        return contract, {"executed": False, "reason": "execute_approved_side_effect=false"}
    output_dir = _output_dir(envelope, "build_poster")
    runtime_path = _configured_output_path(envelope, "runtime_evidence_path", output_dir / "poster_runtime_evidence.json")
    png_path = _configured_output_path(envelope, "poster_png_path", output_dir / "poster.png")
    executor_validation_path = _configured_output_path(
        envelope,
        "poster_executor_validation_path",
        output_dir / "poster_executor_validation.json",
    )
    if not contract.get("ready_for_execution"):
        payload = _runtime_evidence_payload(
            envelope,
            action="build_poster",
            status="inconclusive",
            approval_ref=str(contract.get("approval_ref") or ""),
            command_run="blocked:approval-contract-incomplete",
            exit_code=1,
            evidence_ids=["poster-runtime:blocked"],
            checks=[{"check": "approval_preflight", "status": "error", "detail": "Approval contract was not ready for execution."}],
            runtime_fields={"browser_rendered": False, "png_exported": False, "overflow_probe": "not_run"},
            artifacts=[],
            limitations=["Poster executor did not run because approval preflight was incomplete."],
        )
        runtime_rel = _write_json_sidecar(runtime_path, payload)
        contract.setdefault("runtime_evidence", []).append({"path": runtime_rel, "artifact_path": runtime_rel, "exists": True, "kind": "file", "verifiable": True})
        return _refresh_approval_contract(contract), {"executed": False, "reason": "approval_preflight_incomplete", "runtime_path": runtime_rel}

    if not html_path.exists():
        payload = _runtime_evidence_payload(
            envelope,
            action="build_poster",
            status="inconclusive",
            approval_ref=str(contract.get("approval_ref") or ""),
            command_run="blocked:poster-html-missing",
            exit_code=1,
            evidence_ids=["poster-runtime:blocked"],
            checks=[{"check": "poster_html_exists", "status": "error", "detail": f"Poster HTML was not found at {html_path}."}],
            runtime_fields={"browser_rendered": False, "png_exported": False, "overflow_probe": "not_run"},
            artifacts=[],
            limitations=["Poster executor did not run because native poster HTML was not generated."],
        )
        runtime_rel = _write_json_sidecar(runtime_path, payload)
        contract.setdefault("runtime_evidence", []).append({"path": runtime_rel, "artifact_path": runtime_rel, "exists": True, "kind": "file", "verifiable": True})
        return _refresh_approval_contract(contract), {"executed": False, "reason": "poster_html_missing", "runtime_path": runtime_rel}

    command, allow_reason = _poster_render_command(contract, html_path, png_path, executor_validation_path)
    if not command:
        payload = _runtime_evidence_payload(
            envelope,
            action="build_poster",
            status="inconclusive",
            approval_ref=str(contract.get("approval_ref") or ""),
            command_run="blocked:poster-render-command-missing",
            exit_code=1,
            evidence_ids=["poster-runtime:blocked"],
            checks=[{"check": "poster_render_command", "status": "error", "detail": allow_reason}],
            runtime_fields={"browser_rendered": False, "png_exported": False, "overflow_probe": "not_run"},
            artifacts=[],
            limitations=["Poster executor did not run because no allowlisted render command was supplied."],
        )
        runtime_rel = _write_json_sidecar(runtime_path, payload)
        contract.setdefault("runtime_evidence", []).append({"path": runtime_rel, "artifact_path": runtime_rel, "exists": True, "kind": "file", "verifiable": True})
        return _refresh_approval_contract(contract), {"executed": False, "reason": "poster_render_command_missing", "runtime_path": runtime_rel}

    output_dir.mkdir(parents=True, exist_ok=True)
    proc = subprocess.run(
        command,
        cwd=output_dir,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
        timeout=int(inputs.get("executor_timeout_seconds") or 120),
    )
    stdout_rel = _write_text_sidecar(output_dir / "poster_executor_stdout.txt", proc.stdout)
    stderr_rel = _write_text_sidecar(output_dir / "poster_executor_stderr.txt", proc.stderr)
    validation = _load_runtime_validation(executor_validation_path)
    browser_rendered = _truthy(validation.get("browser_rendered") if validation else png_path.exists())
    png_exported = _truthy(validation.get("png_exported") if validation else png_path.exists()) or png_path.exists()
    overflow_probe = str(validation.get("overflow_probe") or "not_run")
    overflow_ok = overflow_probe.strip().lower() in {"ok", "pass", "passed", "none", "no_overflow"}
    runtime_ok = proc.returncode == 0 and browser_rendered and png_exported and overflow_ok and png_path.exists()
    artifacts = [
        {"type": "executor_stdout", "path": stdout_rel},
        {"type": "executor_stderr", "path": stderr_rel},
    ]
    if executor_validation_path.exists():
        artifacts.append(_artifact("poster_executor_validation_json", executor_validation_path))
    if png_path.exists():
        artifacts.append(_artifact("poster_png", png_path))
    payload = _runtime_evidence_payload(
        envelope,
        action="build_poster",
        status="completed" if runtime_ok else "failed",
        approval_ref=str(contract.get("approval_ref") or ""),
        command_run=" ".join(command),
        exit_code=int(proc.returncode),
        evidence_ids=["poster-runtime:render", _rel(html_path)],
        checks=[
            {"check": "poster_render_command", "status": "ok", "detail": allow_reason},
            {"check": "exit_code", "status": "ok" if proc.returncode == 0 else "error", "detail": f"exit_code={proc.returncode}"},
            {"check": "browser_rendered", "status": "ok" if browser_rendered else "error", "detail": str(browser_rendered)},
            {"check": "overflow_probe", "status": "ok" if overflow_ok else "error", "detail": overflow_probe},
            {"check": "png_exported", "status": "ok" if png_exported and png_path.exists() else "error", "detail": _rel(png_path) if png_path.exists() else "PNG was not found after executor run."},
        ],
        runtime_fields={
            "browser_rendered": browser_rendered,
            "png_exported": bool(png_exported and png_path.exists()),
            "overflow_probe": overflow_probe,
            "png_path": _rel(png_path) if png_path.exists() else "",
        },
        artifacts=artifacts,
        limitations=["Approved poster executor ran an allowlisted render command locally."],
    )
    runtime_rel = _write_json_sidecar(runtime_path, payload)
    contract.setdefault("runtime_evidence", []).append({"path": runtime_rel, "artifact_path": runtime_rel, "exists": True, "kind": "file", "verifiable": True})
    if png_path.exists():
        contract.setdefault("after_artifacts", []).append({"path": _rel(png_path), "artifact_path": _rel(png_path), "exists": True, "kind": "file", "verifiable": True})
    if executor_validation_path.exists():
        contract.setdefault("after_artifacts", []).append({
            "path": _rel(executor_validation_path),
            "artifact_path": _rel(executor_validation_path),
            "exists": True,
            "kind": "file",
            "verifiable": True,
        })
    return _refresh_approval_contract(contract), {
        "executed": True,
        "exit_code": proc.returncode,
        "png_path": png_path,
        "runtime_path": runtime_rel,
    }


def _check_row(check: str, status: str, detail: str, evidence: list[str] | None = None) -> dict[str, Any]:
    return {
        "check": check,
        "status": status,
        "detail": detail,
        "evidence": evidence or [],
    }


def _read_limited_text(path: Path, *, limit: int = 200_000) -> str:
    try:
        return path.read_text(encoding="utf-8", errors="replace")[:limit]
    except OSError:
        return ""


def _optional_number(value: Any) -> float | None:
    if value is None or value == "":
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _optional_bool(value: Any) -> bool | None:
    if isinstance(value, bool):
        return value
    if value is None or value == "":
        return None
    normalized = str(value).strip().lower()
    if normalized in {"1", "true", "yes", "y", "on"}:
        return True
    if normalized in {"0", "false", "no", "n", "off"}:
        return False
    return None


def _submission_profile_first(payload: dict[str, Any], *keys: str) -> Any:
    requirements = payload.get("requirements") if isinstance(payload.get("requirements"), dict) else {}
    for source in (requirements, payload):
        for key in keys:
            if key in source and source.get(key) not in (None, ""):
                return source.get(key)
    return None


def _submission_profile_requirements(payload: dict[str, Any]) -> dict[str, Any]:
    mode = _submission_profile_first(payload, "submission_mode", "mode", "anonymity")
    anonymous = _optional_bool(_submission_profile_first(payload, "anonymous", "anonymized", "anonymous_required"))
    double_blind = _optional_bool(_submission_profile_first(payload, "double_blind", "double-blind", "double_blind_required"))
    page_limit = _optional_number(_submission_profile_first(payload, "page_limit", "max_pages", "maximum_pages"))
    min_font_size = _optional_number(
        _submission_profile_first(payload, "min_font_size", "minimum_font_size", "minimum_font_pt")
    )
    venue = str(_submission_profile_first(payload, "venue", "venue_slug") or payload.get("venue") or "").strip()
    return {
        "venue": venue,
        "submission_mode": str(mode or "").strip(),
        "anonymous": anonymous,
        "double_blind": double_blind,
        "page_limit": page_limit,
        "min_font_size": min_font_size,
    }


def _submission_profile_conflicts(inputs: dict[str, Any], requirements: dict[str, Any]) -> list[str]:
    conflicts: list[str] = []
    input_mode = str(inputs.get("submission_mode") or "").strip().lower()
    requirement_mode = str(requirements.get("submission_mode") or "").strip().lower()
    if input_mode and requirement_mode and input_mode != requirement_mode:
        conflicts.append(f"submission_mode input `{input_mode}` conflicts with profile `{requirement_mode}`")
    for key in ("anonymous", "double_blind"):
        requirement_bool = requirements.get(key)
        input_bool = _optional_bool(inputs.get(key))
        if requirement_bool is not None and input_bool is not None and input_bool != requirement_bool:
            conflicts.append(f"{key} input `{input_bool}` conflicts with profile `{requirement_bool}`")
    for key in ("page_limit", "min_font_size"):
        requirement_number = _optional_number(requirements.get(key))
        input_number = _optional_number(inputs.get(key))
        if requirement_number is not None and input_number is not None and abs(input_number - requirement_number) > 1e-9:
            conflicts.append(f"{key} input `{input_number}` conflicts with profile `{requirement_number}`")
    return conflicts


def _submission_profile_boundary(inputs: dict[str, Any]) -> dict[str, Any]:
    raw_path = str(inputs.get("submission_profile") or inputs.get("submission_profile_path") or "").strip()
    boundary: dict[str, Any] = {
        "schema": "autosci_submission_profile_boundary.v1",
        "status": "missing",
        "profile_loaded": False,
        "profile_valid": False,
        "path": raw_path,
        "sha256": "",
        "venue": str(inputs.get("venue") or ""),
        "requirements": {},
        "evidence_ids": [],
        "applied_fields": [],
        "conflicts": [],
        "invalid_reasons": [],
    }
    if not raw_path:
        boundary["invalid_reasons"] = ["No submission_profile evidence path was supplied."]
        return boundary
    path = _resolve_harness_path(raw_path)
    boundary["path"] = _rel(path)
    if not path.exists() or not path.is_file():
        boundary["status"] = "invalid"
        boundary["invalid_reasons"] = [f"Submission profile was not found: {_rel(path)}"]
        return boundary
    try:
        payload = _load_json(path)
    except Exception as exc:  # noqa: BLE001
        boundary["status"] = "invalid"
        boundary["sha256"] = _file_sha256(path)
        boundary["invalid_reasons"] = [f"Submission profile JSON could not be loaded: {exc}"]
        return boundary
    requirements = _submission_profile_requirements(payload)
    raw_evidence_ids = payload.get("evidence_ids")
    raw_source_evidence_ids = payload.get("source_evidence_ids")
    evidence_ids = _unique_strings([
        *(list(raw_evidence_ids) if isinstance(raw_evidence_ids, list) else []),
        *(list(raw_source_evidence_ids) if isinstance(raw_source_evidence_ids, list) else []),
    ])
    conflicts = _submission_profile_conflicts(inputs, requirements)
    boundary.update({
        "status": "conflict" if conflicts else "loaded",
        "profile_loaded": True,
        "profile_valid": not conflicts,
        "sha256": _file_sha256(path),
        "venue": requirements.get("venue") or str(inputs.get("venue") or ""),
        "requirements": requirements,
        "evidence_ids": evidence_ids,
        "conflicts": conflicts,
        "invalid_reasons": [],
    })
    return boundary


def _apply_submission_profile_inputs(inputs: dict[str, Any], profile_boundary: dict[str, Any]) -> dict[str, Any]:
    merged = dict(inputs)
    if not profile_boundary.get("profile_loaded"):
        return merged
    requirements = profile_boundary.get("requirements") if isinstance(profile_boundary.get("requirements"), dict) else {}
    applied: list[str] = []
    if requirements.get("venue") and not merged.get("venue"):
        merged["venue"] = requirements["venue"]
        applied.append("venue")
    if requirements.get("submission_mode") and not merged.get("submission_mode"):
        merged["submission_mode"] = requirements["submission_mode"]
        applied.append("submission_mode")
    for key in ("anonymous", "double_blind"):
        if requirements.get(key) is not None and merged.get(key) in (None, ""):
            merged[key] = bool(requirements[key])
            applied.append(key)
    for key in ("page_limit", "min_font_size"):
        if requirements.get(key) is not None and merged.get(key) in (None, ""):
            merged[key] = float(requirements[key])
            applied.append(key)
    profile_boundary["applied_fields"] = applied
    return merged


def _pdf_inspection_view(payload: dict[str, Any]) -> dict[str, Any]:
    outputs = payload.get("outputs") if isinstance(payload.get("outputs"), dict) else {}
    inspection = outputs.get("inspection") if isinstance(outputs.get("inspection"), dict) else {}
    return inspection or payload


def _pdf_inspection_first(payload: dict[str, Any], *keys: str) -> Any:
    view = _pdf_inspection_view(payload)
    for source in (view, payload):
        for key in keys:
            if key in source and source.get(key) not in (None, ""):
                return source.get(key)
    return None


def _pdf_inspection_boundary(inputs: dict[str, Any], *, pdf_files: list[Path]) -> dict[str, Any]:
    raw_path = str(inputs.get("pdf_inspection") or inputs.get("pdf_inspection_path") or "").strip()
    boundary: dict[str, Any] = {
        "schema": "autosci_pdf_inspection_boundary.v1",
        "status": "missing",
        "inspection_loaded": False,
        "inspection_valid": False,
        "path": raw_path,
        "sha256": "",
        "pdf_path": "",
        "pdf_sha256": "",
        "page_count": None,
        "min_font_size": None,
        "evidence_ids": [],
        "applied_fields": [],
        "invalid_reasons": [],
    }
    if not raw_path:
        boundary["invalid_reasons"] = ["No pdf_inspection evidence path was supplied."]
        return boundary
    path = _resolve_harness_path(raw_path)
    boundary["path"] = _rel(path)
    if not path.exists() or not path.is_file():
        boundary["status"] = "invalid"
        boundary["invalid_reasons"] = [f"PDF inspection evidence was not found: {_rel(path)}"]
        return boundary
    try:
        payload = _load_json(path)
    except Exception as exc:  # noqa: BLE001
        boundary["status"] = "invalid"
        boundary["sha256"] = _file_sha256(path)
        boundary["invalid_reasons"] = [f"PDF inspection JSON could not be loaded: {exc}"]
        return boundary
    raw_evidence_ids = payload.get("evidence_ids")
    view = _pdf_inspection_view(payload)
    raw_view_evidence_ids = view.get("evidence_ids") if isinstance(view.get("evidence_ids"), list) else []
    page_count = _optional_number(_pdf_inspection_first(payload, "verified_page_count", "page_count", "pages"))
    min_font_size = _optional_number(_pdf_inspection_first(payload, "verified_min_font_size", "min_font_size", "minimum_font_size"))
    pdf_ref = str(_pdf_inspection_first(payload, "pdf_path", "path") or "").strip()
    pdf_sha256 = str(_pdf_inspection_first(payload, "pdf_sha256", "sha256") or "").strip()
    invalid_reasons: list[str] = []
    matched_pdf = False
    if pdf_ref:
        resolved_pdf = _resolve_harness_path(pdf_ref)
        boundary["pdf_path"] = _rel(resolved_pdf)
        matched_pdf = any(existing.resolve() == resolved_pdf.resolve() for existing in pdf_files if existing.exists())
        if not matched_pdf:
            invalid_reasons.append(f"Inspection pdf_path does not match discovered compiled PDFs: {_rel(resolved_pdf)}")
        if pdf_sha256 and resolved_pdf.exists() and _file_sha256(resolved_pdf) != pdf_sha256:
            invalid_reasons.append("Inspection pdf_sha256 does not match the referenced PDF.")
    elif pdf_sha256:
        matched_pdf = any(existing.exists() and _file_sha256(existing) == pdf_sha256 for existing in pdf_files)
        if not matched_pdf:
            invalid_reasons.append("Inspection pdf_sha256 does not match any discovered compiled PDF.")
    else:
        invalid_reasons.append("PDF inspection evidence must include pdf_path or pdf_sha256.")
    if page_count is None:
        invalid_reasons.append("PDF inspection evidence is missing page_count.")
    if min_font_size is None:
        invalid_reasons.append("PDF inspection evidence is missing min_font_size.")
    boundary.update({
        "status": "invalid" if invalid_reasons else "loaded",
        "inspection_loaded": True,
        "inspection_valid": not invalid_reasons,
        "sha256": _file_sha256(path),
        "pdf_sha256": pdf_sha256,
        "page_count": page_count,
        "min_font_size": min_font_size,
        "evidence_ids": _unique_strings([
            *(list(raw_evidence_ids) if isinstance(raw_evidence_ids, list) else []),
            *list(raw_view_evidence_ids),
        ]),
        "invalid_reasons": invalid_reasons,
    })
    return boundary


def _apply_pdf_inspection_inputs(inputs: dict[str, Any], inspection_boundary: dict[str, Any]) -> dict[str, Any]:
    merged = dict(inputs)
    if inspection_boundary.get("status") != "loaded":
        return merged
    applied: list[str] = []
    if inspection_boundary.get("page_count") is not None and merged.get("verified_page_count") in (None, ""):
        merged["verified_page_count"] = float(inspection_boundary["page_count"])
        applied.append("verified_page_count")
    if inspection_boundary.get("min_font_size") is not None and merged.get("verified_min_font_size") in (None, ""):
        merged["verified_min_font_size"] = float(inspection_boundary["min_font_size"])
        applied.append("verified_min_font_size")
    inspection_boundary["applied_fields"] = applied
    return merged


def _submission_audit_view(payload: dict[str, Any]) -> dict[str, Any]:
    outputs = payload.get("outputs") if isinstance(payload.get("outputs"), dict) else {}
    audit = outputs.get("audit") if isinstance(outputs.get("audit"), dict) else {}
    return audit or payload


def _submission_audit_boundary(inputs: dict[str, Any]) -> dict[str, Any]:
    raw_path = str(inputs.get("submission_audit") or inputs.get("submission_audit_path") or "").strip()
    boundary: dict[str, Any] = {
        "schema": "autosci_publication_submission_audit_boundary.v1",
        "status": "missing",
        "audit_loaded": False,
        "audit_verified": False,
        "path": raw_path,
        "sha256": "",
        "venue": str(inputs.get("venue") or ""),
        "checks": [],
        "blocking_checks": [],
        "portal_submission_completed": False,
        "evidence_ids": [],
        "invalid_reasons": [],
    }
    if not raw_path:
        boundary["invalid_reasons"] = ["No submission_audit evidence path was supplied."]
        return boundary
    path = _resolve_harness_path(raw_path)
    boundary["path"] = _rel(path)
    if not path.exists() or not path.is_file():
        boundary["status"] = "invalid"
        boundary["invalid_reasons"] = [f"Submission audit evidence was not found: {_rel(path)}"]
        return boundary
    try:
        payload = _load_json(path)
    except Exception as exc:  # noqa: BLE001
        boundary["status"] = "invalid"
        boundary["sha256"] = _file_sha256(path)
        boundary["invalid_reasons"] = [f"Submission audit JSON could not be loaded: {exc}"]
        return boundary
    view = _submission_audit_view(payload)
    raw_checks = view.get("checks") if isinstance(view.get("checks"), list) else payload.get("checks")
    checks = [dict(item) for item in raw_checks or [] if isinstance(item, dict)]
    explicit_blocking = view.get("blocking_checks") if isinstance(view.get("blocking_checks"), list) else []
    blocking_checks = _unique_strings([
        *[str(item) for item in explicit_blocking],
        *[
            str(check.get("check") or check.get("name") or "submission_audit_check")
            for check in checks
            if str(check.get("status") or "").lower() not in {"ok", "passed", "pass", "completed"}
        ],
    ])
    audit_status = str(view.get("status") or payload.get("status") or "").strip().lower()
    submission_ready_flag = _optional_bool(view.get("submission_ready"))
    portal_submission_completed = bool(_optional_bool(view.get("portal_submission_completed")) or False)
    raw_evidence_ids = payload.get("evidence_ids")
    raw_view_evidence_ids = view.get("evidence_ids") if isinstance(view.get("evidence_ids"), list) else []
    invalid_reasons: list[str] = []
    if not checks:
        invalid_reasons.append("Submission audit evidence must include at least one check row.")
    audit_verified = (
        not invalid_reasons
        and not blocking_checks
        and audit_status in {"completed", "passed", "pass", "ok"}
        and submission_ready_flag is not False
    )
    boundary.update({
        "status": "loaded" if not invalid_reasons else "invalid",
        "audit_loaded": True,
        "audit_verified": audit_verified,
        "sha256": _file_sha256(path),
        "venue": str(view.get("venue") or payload.get("venue") or inputs.get("venue") or ""),
        "checks": checks,
        "blocking_checks": blocking_checks,
        "portal_submission_completed": portal_submission_completed,
        "evidence_ids": _unique_strings([
            *(list(raw_evidence_ids) if isinstance(raw_evidence_ids, list) else []),
            *list(raw_view_evidence_ids),
        ]),
        "invalid_reasons": invalid_reasons,
    })
    return boundary


def _submission_check_rows(
    inputs: dict[str, Any],
    *,
    latex_files: list[Path],
    markdown_files: list[Path],
) -> list[dict[str, Any]]:
    text_by_path = {
        _rel(path): _read_limited_text(path)
        for path in [*latex_files, *markdown_files]
    }
    unconfirmed_paths = [
        path
        for path, text in text_by_path.items()
        if "[UNCONFIRMED]" in text
    ]
    anonymous_requested = bool(
        inputs.get("anonymous")
        or inputs.get("anonymized")
        or inputs.get("double_blind")
        or str(inputs.get("submission_mode") or "").strip().lower() in {"anonymous", "double_blind", "double-blind"}
    )
    author_disclosures: list[str] = []
    for path, text in text_by_path.items():
        for match in re.finditer(r"\\author\s*\{([^{}]+)\}", text):
            author_text = match.group(1).strip()
            if author_text and "anonymous" not in author_text.lower():
                author_disclosures.append(path)
                break
    page_limit = _optional_number(inputs.get("page_limit"))
    page_count = _optional_number(inputs.get("page_count") or inputs.get("verified_page_count"))
    min_font_size = _optional_number(inputs.get("min_font_size") or inputs.get("minimum_font_size"))
    verified_min_font_size = _optional_number(inputs.get("verified_min_font_size"))
    rows = [
        _check_row(
            "unconfirmed_marker_scan",
            "warn" if unconfirmed_paths else "ok",
            f"[UNCONFIRMED] markers found in {len(unconfirmed_paths)} source file(s)."
            if unconfirmed_paths
            else "No [UNCONFIRMED] markers were found in scanned source files.",
            unconfirmed_paths,
        ),
        _check_row(
            "anonymity_check",
            "warn" if anonymous_requested and author_disclosures else "ok" if anonymous_requested else "warn",
            "Anonymous mode requested and no explicit non-anonymous author blocks were found."
            if anonymous_requested and not author_disclosures
            else f"Anonymous mode requested but author blocks may disclose identity in {len(author_disclosures)} file(s)."
            if anonymous_requested
            else "Anonymous/double-blind submission mode was not requested, so anonymity is not claimed.",
            author_disclosures,
        ),
        _check_row(
            "page_limit_check",
            "ok"
            if page_limit is not None and page_count is not None and page_count <= page_limit
            else "warn",
            f"Verified page count {page_count} is within limit {page_limit}."
            if page_limit is not None and page_count is not None and page_count <= page_limit
            else "Page limit compliance is unconfirmed; supply page_limit and verified_page_count evidence.",
        ),
        _check_row(
            "font_size_check",
            "ok"
            if min_font_size is not None and verified_min_font_size is not None and verified_min_font_size >= min_font_size
            else "warn",
            f"Verified minimum font size {verified_min_font_size} is >= required {min_font_size}."
            if min_font_size is not None and verified_min_font_size is not None and verified_min_font_size >= min_font_size
            else "Font-size compliance is unconfirmed; supply minimum font-size evidence from a PDF checker.",
        ),
    ]
    return rows


def _publication_submission_boundary(
    *,
    submission_checks: list[dict[str, Any]],
    pdf_files: list[Path],
    semantic: dict[str, Any],
    submission_profile: dict[str, Any],
    pdf_inspection: dict[str, Any],
    submission_audit: dict[str, Any],
) -> dict[str, Any]:
    check_statuses = {
        str(row.get("check") or ""): str(row.get("status") or "")
        for row in submission_checks
        if isinstance(row, dict) and str(row.get("check") or "").strip()
    }
    blocking_checks = [
        check
        for check, status in sorted(check_statuses.items())
        if status != "ok"
    ]
    compiled_pdf_verified = bool(pdf_files) or bool(semantic.get("verified"))
    if not compiled_pdf_verified:
        blocking_checks.append("compiled_pdf_verified")
    submission_ready = compiled_pdf_verified and not blocking_checks
    profile_status = str(submission_profile.get("status") or "missing")
    inspection_status = str(pdf_inspection.get("status") or "missing")
    venue_blocking_checks = []
    if profile_status != "loaded":
        venue_blocking_checks.append("venue_submission_profile")
    if inspection_status != "loaded":
        venue_blocking_checks.append("pdf_inspection")
    venue_submission_ready = submission_ready and profile_status == "loaded" and inspection_status == "loaded"
    audit_ready = bool(submission_audit.get("audit_verified"))
    submission_audit_blocking_checks = []
    if not venue_submission_ready:
        submission_audit_blocking_checks.append("venue_submission_ready")
    if not audit_ready:
        submission_audit_blocking_checks.append("publication_submission_audit")
    submission_audit_ready = venue_submission_ready and audit_ready
    return {
        "schema": "autosci_publication_submission_boundary.v1",
        "status": "submission_ready" if submission_ready else "submission_incomplete",
        "submission_ready": submission_ready,
        "venue_status": "venue_submission_ready"
        if venue_submission_ready
        else "venue_submission_incomplete"
        if profile_status != "missing"
        else "venue_profile_missing",
        "venue_submission_ready": venue_submission_ready,
        "venue_blocking_checks": venue_blocking_checks,
        "submission_audit_status": "submission_audit_ready"
        if submission_audit_ready
        else "submission_audit_incomplete"
        if str(submission_audit.get("status") or "missing") != "missing"
        else "submission_audit_missing",
        "submission_audit_ready": submission_audit_ready,
        "submission_audit_blocking_checks": submission_audit_blocking_checks,
        "portal_submission_completed": bool(submission_audit.get("portal_submission_completed")),
        "compiled_pdf_verified": compiled_pdf_verified,
        "runtime_semantic_verified": bool(semantic.get("verified")),
        "pdf_files": [_rel(path) for path in pdf_files],
        "check_statuses": check_statuses,
        "blocking_checks": _unique_strings(blocking_checks),
        "submission_profile": submission_profile,
        "pdf_inspection": pdf_inspection,
        "submission_audit": submission_audit,
        "limitations": [
            *([] if submission_ready else [
                "Publication compile evidence does not prove submission readiness; review blocking_checks and submission_checks."
            ]),
            *([] if venue_submission_ready else [
                "Venue submission readiness is not proven; supply a valid submission_profile and pdf_inspection evidence."
            ]),
            *([] if submission_audit_ready else [
                "Publication submission audit readiness is not proven; supply valid submission_audit evidence."
            ]),
        ],
    }


def _render_compile_diagnostics(checklist: dict[str, Any]) -> str:
    lines = [
        "# Paper Compile Checklist Diagnostics",
        "",
        f"Target: {checklist.get('target_raw') or 'N/A'}",
        f"Resolved target: {checklist.get('target_resolved') or 'N/A'}",
        f"Status: {checklist.get('status') or 'N/A'}",
        "",
        "| Check | Status | Detail |",
        "| --- | --- | --- |",
    ]
    for row in checklist.get("checks") or []:
        if not isinstance(row, dict):
            continue
        detail = str(row.get("detail") or "N/A").replace("|", "\\|")
        lines.append(f"| {row.get('check', 'N/A')} | {row.get('status', 'N/A')} | {detail} |")
    submission_checks = checklist.get("submission_checks") if isinstance(checklist.get("submission_checks"), list) else []
    if submission_checks:
        lines.extend(["", "## Submission Checks", "", "| Check | Status | Detail |", "| --- | --- | --- |"])
        for row in submission_checks:
            if not isinstance(row, dict):
                continue
            detail = str(row.get("detail") or "N/A").replace("|", "\\|")
            lines.append(f"| {row.get('check', 'N/A')} | {row.get('status', 'N/A')} | {detail} |")
    submission_boundary = checklist.get("submission_boundary") if isinstance(checklist.get("submission_boundary"), dict) else {}
    if submission_boundary:
        lines.extend([
            "",
            "## Submission Boundary",
            "",
            f"- status: {submission_boundary.get('status') or 'N/A'}",
            f"- submission_ready: {submission_boundary.get('submission_ready')}",
            f"- blocking_checks: {', '.join(submission_boundary.get('blocking_checks') or []) or 'N/A'}",
            f"- venue_status: {submission_boundary.get('venue_status') or 'N/A'}",
            f"- venue_submission_ready: {submission_boundary.get('venue_submission_ready')}",
            f"- venue_blocking_checks: {', '.join(submission_boundary.get('venue_blocking_checks') or []) or 'N/A'}",
            f"- submission_audit_status: {submission_boundary.get('submission_audit_status') or 'N/A'}",
            f"- submission_audit_ready: {submission_boundary.get('submission_audit_ready')}",
            f"- submission_audit_blocking_checks: {', '.join(submission_boundary.get('submission_audit_blocking_checks') or []) or 'N/A'}",
            f"- portal_submission_completed: {submission_boundary.get('portal_submission_completed')}",
        ])
        submission_profile = (
            submission_boundary.get("submission_profile")
            if isinstance(submission_boundary.get("submission_profile"), dict)
            else {}
        )
        if submission_profile:
            lines.extend([
                f"- submission_profile_status: {submission_profile.get('status') or 'N/A'}",
                f"- submission_profile_path: {submission_profile.get('path') or 'N/A'}",
            ])
        pdf_inspection = (
            submission_boundary.get("pdf_inspection")
            if isinstance(submission_boundary.get("pdf_inspection"), dict)
            else {}
        )
        if pdf_inspection:
            lines.extend([
                f"- pdf_inspection_status: {pdf_inspection.get('status') or 'N/A'}",
                f"- pdf_inspection_path: {pdf_inspection.get('path') or 'N/A'}",
            ])
        submission_audit = (
            submission_boundary.get("submission_audit")
            if isinstance(submission_boundary.get("submission_audit"), dict)
            else {}
        )
        if submission_audit:
            lines.extend([
                f"- submission_audit_evidence_status: {submission_audit.get('status') or 'N/A'}",
                f"- submission_audit_path: {submission_audit.get('path') or 'N/A'}",
            ])
    lines.extend(["", "## Files", ""])
    for key in ("latex_files", "pdf_files", "markdown_files", "bibliography_files"):
        values = checklist.get(key) if isinstance(checklist.get(key), list) else []
        lines.append(f"- {key}: {', '.join(str(item) for item in values) if values else 'N/A'}")
    limitations_list = checklist.get("limitations") if isinstance(checklist.get("limitations"), list) else []
    if limitations_list:
        lines.extend(["", "## Limitations", ""])
        lines.extend(f"- {limitation}" for limitation in limitations_list)
    return "\n".join(lines).rstrip() + "\n"


def _paper_compile_report_payload(
    checklist: dict[str, Any],
    *,
    checklist_path: str,
    diagnostics_path: str,
    submission_boundary_path: str,
) -> dict[str, Any]:
    checks = checklist.get("checks") if isinstance(checklist.get("checks"), list) else []
    check_statuses = {
        str(row.get("check") or ""): str(row.get("status") or "")
        for row in checks
        if isinstance(row, dict) and str(row.get("check") or "").strip()
    }
    toolchain = checklist.get("toolchain") if isinstance(checklist.get("toolchain"), dict) else {}
    tex_executors = toolchain.get("tex_executors") if isinstance(toolchain.get("tex_executors"), dict) else {}
    runtime_semantic = (
        checklist.get("runtime_semantic")
        if isinstance(checklist.get("runtime_semantic"), dict)
        else {}
    )
    approval_contract = (
        checklist.get("approval_contract")
        if isinstance(checklist.get("approval_contract"), dict)
        else {}
    )
    submission_boundary = (
        checklist.get("submission_boundary")
        if isinstance(checklist.get("submission_boundary"), dict)
        else {}
    )
    return {
        "schema": "paper_compile_report.v1",
        "status": checklist.get("status") or "inconclusive",
        "target": {
            "raw": checklist.get("target_raw") or "",
            "resolved": checklist.get("target_resolved") or "",
        },
        "toolchain": {
            "latexmk_available": bool(toolchain.get("latexmk_available")),
            "available_tex_executors": sorted(str(name) for name in tex_executors.keys()),
            "selected_executor": str(toolchain.get("selected_executor") or ""),
        },
        "execution": {
            "approval_ready": bool(approval_contract.get("ready_for_execution")),
            "execution_verified": bool(approval_contract.get("execution_verified")),
            "runtime_semantic_verified": bool(runtime_semantic.get("verified")),
        },
        "pdf": {
            "compiled_pdf_verified": bool(submission_boundary.get("compiled_pdf_verified")),
            "pdf_files": checklist.get("pdf_files") if isinstance(checklist.get("pdf_files"), list) else [],
            "verified_pdf_files": checklist.get("verified_pdf_files")
            if isinstance(checklist.get("verified_pdf_files"), list)
            else [],
            "pdf_integrity": checklist.get("pdf_integrity") if isinstance(checklist.get("pdf_integrity"), list) else [],
        },
        "submission": {
            "submission_ready": bool(submission_boundary.get("submission_ready")),
            "venue_submission_ready": bool(submission_boundary.get("venue_submission_ready")),
            "submission_audit_ready": bool(submission_boundary.get("submission_audit_ready")),
            "portal_submission_completed": bool(submission_boundary.get("portal_submission_completed")),
            "blocking_checks": submission_boundary.get("blocking_checks")
            if isinstance(submission_boundary.get("blocking_checks"), list)
            else [],
            "venue_blocking_checks": submission_boundary.get("venue_blocking_checks")
            if isinstance(submission_boundary.get("venue_blocking_checks"), list)
            else [],
            "submission_audit_blocking_checks": submission_boundary.get("submission_audit_blocking_checks")
            if isinstance(submission_boundary.get("submission_audit_blocking_checks"), list)
            else [],
        },
        "checks": check_statuses,
        "artifacts": {
            "checklist": checklist_path,
            "diagnostics": diagnostics_path,
            "submission_boundary": submission_boundary_path,
        },
        "limitations": checklist.get("limitations") if isinstance(checklist.get("limitations"), list) else [],
    }


def _paper_compile_raw(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = envelope.get("inputs") if isinstance(envelope.get("inputs"), dict) else {}
    paths = _paper_compile_paths(envelope)
    target_raw, target_path = _paper_compile_target(envelope)
    candidates = _compile_source_candidates(target_path)
    latex_files = candidates["latex"]
    pdf_files = candidates["pdf"]
    markdown_files = candidates["markdown"]
    bibliography_files = candidates["bibliography"]
    latex_tool_paths = _latex_tool_paths()
    available_tex_executors = {name: path for name, path in latex_tool_paths.items() if path}
    latexmk_path = latex_tool_paths.get("latexmk", "")
    checklist_requested = bool(inputs.get("checklist"))
    fix_requested = bool(inputs.get("fix"))
    target_exists = bool(target_path and target_path.exists())
    target_detail = str(target_path) if target_path else "No target or paper_path was provided."
    checklist_paths = [_rel(paths["checklist"]), _rel(paths["diagnostics"])]
    contract = _approval_contract(
        envelope,
        "compile_paper",
        ["tex_executor_execution", "source_auto_fix", "pdf_generation"],
    )
    compile_policy_allowlist = {
        "executables": _unique_strings([
            *available_tex_executors.keys(),
            *[Path(path).name for path in available_tex_executors.values() if path],
            *[path for path in available_tex_executors.values() if path],
        ]),
        "allowed_prefixes": [path for path in available_tex_executors.values() if path],
        "limitations": [
            "Policy allowlist is limited to supported TeX executors already discovered on PATH.",
        ],
    }
    contract, policy_decision, policy_artifacts = _policy_prepare_auto_contract(
        envelope,
        "compile_paper",
        ["read_local", "write_artifact", "tex_compile", "local_command"],
        contract,
        allowlist_payload=compile_policy_allowlist,
    )
    fix_result = _paper_compile_fix_if_approved(envelope, contract, target_path, latex_files)
    if fix_result.get("applied"):
        candidates = _compile_source_candidates(target_path)
        latex_files = candidates["latex"]
        pdf_files = candidates["pdf"]
        markdown_files = candidates["markdown"]
        bibliography_files = candidates["bibliography"]
    contract, executor_result = _execute_paper_compile_if_approved(envelope, contract, latex_files, latex_tool_paths)
    if executor_result.get("executed"):
        candidates = _compile_source_candidates(target_path)
        latex_files = candidates["latex"]
        pdf_files = candidates["pdf"]
        markdown_files = candidates["markdown"]
        bibliography_files = candidates["bibliography"]
    semantic = _approval_semantic_runtime(contract, "compile_paper")
    contract["semantic_runtime"] = semantic
    contract_artifact = _write_approval_contract_sidecar(envelope, "compile_paper", contract)
    runtime_artifacts = _contract_existing_artifacts(contract, "after_artifacts", "compile_runtime_after_artifact")
    runtime_evidence_artifacts = _contract_existing_artifacts(contract, "runtime_evidence", "compile_runtime_evidence_json")
    pdf_integrity = [_pdf_integrity(path) for path in pdf_files]
    valid_pdf_files = [
        path
        for path, integrity in zip(pdf_files, pdf_integrity)
        if bool(integrity.get("valid"))
    ]

    checks = [
        _check_row(
            "target_resolved",
            "ok" if target_exists else "error",
            f"Resolved to {target_detail}" if target_exists else target_detail,
            [_rel(target_path)] if target_exists and target_path else [],
        ),
        _check_row(
            "latex_source_present",
            "ok" if latex_files else "warn",
            f"{len(latex_files)} LaTeX source file(s) found." if latex_files else "No .tex source files were found.",
            [_rel(path) for path in latex_files],
        ),
        _check_row(
            "compiled_pdf_present",
            "ok" if valid_pdf_files else "warn",
            f"{len(valid_pdf_files)} structurally valid PDF file(s) found."
            if valid_pdf_files
            else "No structurally valid compiled PDF was found.",
            [_rel(path) for path in valid_pdf_files],
        ),
        _check_row(
            "bibliography_present",
            "ok" if bibliography_files else "warn",
            f"{len(bibliography_files)} BibTeX file(s) found." if bibliography_files else "No .bib files were found.",
            [_rel(path) for path in bibliography_files],
        ),
        _check_row(
            "latexmk_available",
            "ok" if latexmk_path else "warn",
            latexmk_path or "latexmk was not found on PATH; approved execution may use another allowlisted TeX executor.",
            [latexmk_path] if latexmk_path else [],
        ),
        _check_row(
            "tex_executor_available",
            "ok" if available_tex_executors else "warn",
            ", ".join(f"{name}={path}" for name, path in available_tex_executors.items())
            if available_tex_executors
            else "No supported TeX executor was found on PATH.",
            list(available_tex_executors.values()),
        ),
        _check_row(
            "checklist_requested",
            "ok" if checklist_requested else "warn",
            "Checklist mode was requested." if checklist_requested else "Checklist flag was not set.",
            checklist_paths,
        ),
        _check_row(
            "auto_fix_requested",
            "ok" if bool(fix_result.get("applied")) or not fix_requested else "warn",
            "Approved auto-fix applied from after_artifact evidence."
            if fix_result.get("applied")
            else "Auto-fix was requested but not applied; approval and after_artifact evidence are required."
            if fix_requested
            else "Auto-fix was not requested.",
            [fix_result["artifact"]["path"]] if fix_result.get("artifact") else [],
        ),
        _check_row(
            "compile_execution",
            "ok" if semantic.get("verified") else "warn",
            "Approved executor/runtime evidence verifies LaTeX/PDF compilation."
            if semantic.get("verified")
            else (
                f"Approved executor did not complete: {executor_result.get('reason') or 'semantic runtime incomplete'}"
                if inputs.get("execute_approved_side_effect")
                else "The bridge produced compile diagnostics only; it did not run a TeX executor or mutate sources."
            ),
        ),
        _check_row(
            "approval_contract_verified",
            "ok" if contract.get("execution_verified") else "warn",
            "Approval, allowlist, runtime, and before/after evidence are verified."
            if contract.get("execution_verified")
            else "Approval/runtime contract is incomplete; compile side effects were not executed by this bridge.",
            [contract_artifact["path"]],
        ),
        _check_row(
            "runtime_semantic_verified",
            "ok" if semantic.get("verified") else "warn",
            "Runtime evidence passed compile-specific semantic checks."
            if semantic.get("verified")
            else "Runtime evidence did not pass compile-specific semantic checks.",
            [contract_artifact["path"]],
        ),
    ]
    submission_profile = _submission_profile_boundary(inputs)
    submission_inputs = _apply_submission_profile_inputs(inputs, submission_profile)
    pdf_inspection = _pdf_inspection_boundary(inputs, pdf_files=valid_pdf_files)
    submission_inputs = _apply_pdf_inspection_inputs(submission_inputs, pdf_inspection)
    submission_audit = _submission_audit_boundary(inputs)
    submission_checks = _submission_check_rows(submission_inputs, latex_files=latex_files, markdown_files=markdown_files)
    submission_boundary = _publication_submission_boundary(
        submission_checks=submission_checks,
        pdf_files=valid_pdf_files,
        semantic=semantic,
        submission_profile=submission_profile,
        pdf_inspection=pdf_inspection,
        submission_audit=submission_audit,
    )
    checks.extend(submission_checks)
    checks.append(_check_row(
        "venue_submission_profile",
        "ok" if submission_profile.get("status") == "loaded" else "warn",
        "Venue submission profile loaded with source-backed requirements."
        if submission_profile.get("status") == "loaded"
        else "Venue submission profile is missing, invalid, or conflicts with CLI evidence.",
        [str(submission_profile.get("path") or "")] if submission_profile.get("path") else [],
    ))
    checks.append(_check_row(
        "pdf_inspection",
        "ok" if pdf_inspection.get("status") == "loaded" else "warn",
        "PDF inspection evidence loaded with verified page and font measurements."
        if pdf_inspection.get("status") == "loaded"
        else "PDF inspection evidence is missing or invalid; page/font proof may be CLI-only.",
        [str(pdf_inspection.get("path") or "")] if pdf_inspection.get("path") else [],
    ))
    checks.append(_check_row(
        "publication_submission_audit",
        "ok" if submission_audit.get("audit_verified") else "warn",
        "Publication submission audit evidence verified checklist readiness."
        if submission_audit.get("audit_verified")
        else "Publication submission audit evidence is missing, invalid, or has blocking checks.",
        [str(submission_audit.get("path") or "")] if submission_audit.get("path") else [],
    ))
    checks.append(_check_row(
        "publication_submission_boundary",
        "ok" if submission_boundary["submission_ready"] else "warn",
        "Submission readiness boundary passed."
        if submission_boundary["submission_ready"]
        else "Submission readiness boundary is incomplete; see publication_submission_boundary.json.",
        [str(paths["submission_boundary"])],
    ))
    limitations = [
        "Paper compile currently performs a bounded checklist and diagnostics pass only.",
        "The bridge does not run a TeX executor, mutate source files, or claim PDF compilation without explicit approved execution.",
        *_approval_contract_limitations(contract),
    ]
    if semantic.get("verified"):
        if executor_result.get("executed"):
            limitations = ["Paper compile was executed by the approved side-effect executor and verified from runtime evidence."]
        else:
            limitations = [
                "Paper compile runtime was verified from supplied approval-gated evidence; this bridge did not execute a TeX executor.",
            ]
    elif policy_decision.get("execute_side_effects"):
        limitations.append(
            f"Auto-approved by gate policy mode `{policy_decision.get('mode')}`; TeX execution was attempted only if a supported executor was available."
        )
    if not target_exists:
        limitations.append("Paper compile target was missing or unresolved.")
    if not latex_files:
        limitations.append("No LaTeX source was found for native paper compilation.")
    if not valid_pdf_files:
        limitations.append("No structurally valid compiled PDF was found in the target path.")
    if fix_requested:
        limitations.extend(str(item) for item in fix_result.get("limitations") or [])
    if any(row.get("status") != "ok" for row in submission_checks):
        limitations.append("Submission readiness includes warnings or unconfirmed checks; see submission_checks in the compile checklist.")
    limitations.extend(str(item) for item in submission_boundary.get("limitations") or [])
    status = (
        "completed"
        if target_exists and latex_files and (valid_pdf_files or semantic.get("verified")) and (not fix_requested or bool(fix_result.get("applied")))
        else "inconclusive"
    )
    checklist_payload = {
        "schema": "paper_compile_checklist.v1",
        "status": status,
        "target_raw": target_raw,
        "target_resolved": str(target_path) if target_path else "",
        "requested": {
            "checklist": checklist_requested,
            "fix": fix_requested,
            "title": str(inputs.get("title") or ""),
        },
        "toolchain": {
            "latexmk_available": bool(latexmk_path),
            "latexmk_path": latexmk_path,
            "tex_executors": available_tex_executors,
            "selected_executor": str(executor_result.get("executor") or ""),
        },
        "approval_contract": contract,
        "policy_decision": policy_decision,
        "runtime_semantic": semantic,
        "fix_writeback": fix_result.get("write"),
        "checks": checks,
        "submission_checks": submission_checks,
        "submission_profile": submission_profile,
        "pdf_inspection": pdf_inspection,
        "submission_audit": submission_audit,
        "submission_boundary": submission_boundary,
        "pdf_integrity": pdf_integrity,
        "latex_files": [_rel(path) for path in latex_files],
        "pdf_files": [_rel(path) for path in pdf_files],
        "verified_pdf_files": [_rel(path) for path in valid_pdf_files],
        "markdown_files": [_rel(path) for path in markdown_files],
        "bibliography_files": [_rel(path) for path in bibliography_files],
        "limitations": limitations,
    }
    submission_boundary_path = _write_json_sidecar(paths["submission_boundary"], submission_boundary)
    checklist_path = _write_json_sidecar(paths["checklist"], checklist_payload)
    diagnostics_path = _write_text_sidecar(paths["diagnostics"], _render_compile_diagnostics(checklist_payload))
    compile_report_path = _write_json_sidecar(
        paths["compile_report"],
        _paper_compile_report_payload(
            checklist_payload,
            checklist_path=checklist_path,
            diagnostics_path=diagnostics_path,
            submission_boundary_path=submission_boundary_path,
        ),
    )
    file_artifacts = [
        {"type": "publication_submission_boundary_json", "path": submission_boundary_path},
        {"type": "paper_compile_checklist_json", "path": checklist_path},
        {"type": "paper_compile_diagnostics_markdown", "path": diagnostics_path},
        {"type": "paper_compile_report_json", "path": compile_report_path},
        *(
            [{
                "type": "venue_submission_profile_json",
                "path": str(submission_profile.get("path")),
                "sha256": str(submission_profile.get("sha256") or ""),
            }]
            if submission_profile.get("profile_loaded")
            else []
        ),
        *(
            [{
                "type": "pdf_inspection_json",
                "path": str(pdf_inspection.get("path")),
                "sha256": str(pdf_inspection.get("sha256") or ""),
            }]
            if pdf_inspection.get("inspection_loaded")
            else []
        ),
        *(
            [{
                "type": "publication_submission_audit_json",
                "path": str(submission_audit.get("path")),
                "sha256": str(submission_audit.get("sha256") or ""),
            }]
            if submission_audit.get("audit_loaded")
            else []
        ),
        contract_artifact,
        *([fix_result["artifact"]] if fix_result.get("artifact") else []),
        *[artifact for artifact in fix_result.get("artifacts") or [] if isinstance(artifact, dict)],
        *runtime_evidence_artifacts,
        *runtime_artifacts,
        *policy_artifacts,
        *[_artifact("latex_source", path) for path in latex_files],
        *[_artifact("compiled_pdf", path) for path in valid_pdf_files],
        *[_artifact("paper_markdown_source", path) for path in markdown_files[:5]],
        *[_artifact("bibliography_source", path) for path in bibliography_files[:5]],
    ]
    evidence_payload_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        _output_dir(envelope, "compile_paper") / "compile_paper.evidence.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    runtime_proof_artifact = _write_paper_compile_runtime_proof_manifest(
        envelope,
        evidence_path=evidence_payload_path,
        status=status,
        semantic=semantic,
        contract=contract,
        artifacts=file_artifacts,
        latex_files=latex_files,
        pdf_files=valid_pdf_files,
    )
    if runtime_proof_artifact is not None:
        file_artifacts.append(runtime_proof_artifact)
    source_report_id = f"paper-compile:{_slug(target_raw or 'target')}"
    return {
        "bundle_id": f"bundle-{_slug(source_report_id)}",
        "publication_type": "paper",
        "source_report_id": source_report_id,
        "files": file_artifacts,
        "evidence_ids": _unique_strings([
            source_report_id,
            "paper-compile-checklist",
            *[_rel(path) for path in latex_files[:5]],
            *[_rel(path) for path in valid_pdf_files[:5]],
        ]),
        "artifacts": file_artifacts,
        "status": status,
        "limitations": limitations,
        "policy_decision": policy_decision,
    }


def _action_compile_paper(envelope: dict[str, Any]) -> dict[str, Any]:
    raw = _paper_compile_raw(envelope)
    evidence = convert_publication_bundle(raw, envelope)
    if isinstance(raw.get("policy_decision"), dict):
        evidence = _attach_policy_decision(evidence, raw["policy_decision"])
    return evidence


PHASE16_COLLECTION_KEYS = (
    "failed_nodes",
    "gate_rejection_reasons",
    "ambiguous_manuals_or_prompts",
    "insufficient_schemas",
    "poor_operator_bindings",
    "human_intervention_points",
    "runtime_errors",
)


def _phase16_paths(envelope: dict[str, Any]) -> dict[str, Path]:
    output_dir = _output_dir(envelope, "evolve_workflow")
    return {
        "recommended_changes": _configured_output_path(
            envelope,
            "recommended_changes_path",
            output_dir / "recommended_changes.md",
        ),
        "patch_candidates": _configured_output_path(
            envelope,
            "patch_candidates_path",
            output_dir / "patch_candidates",
        ),
    }


def _phase16_failed_run(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    inline = inputs.get("failed_run") or inputs.get("workflow_run") or inputs.get("postmortem")
    if isinstance(inline, dict):
        return inline
    for key in ("failed_run_path", "workflow_run_path", "lifecycle_summary_path", "postmortem_path"):
        payload = _load_optional_evidence(inputs.get(key))
        if payload:
            return payload
    return {
        "workflow_id": "unknown-workflow",
        "nodes": [],
        "gate_results": {},
        "runtime_errors": ["No failed run evidence was supplied."],
    }


def _phase16_failed_nodes(run: dict[str, Any]) -> list[dict[str, Any]]:
    explicit = run.get("failed_nodes")
    if isinstance(explicit, list):
        return [item for item in explicit if isinstance(item, dict)]
    failed: list[dict[str, Any]] = []
    node_results = run.get("node_results") if isinstance(run.get("node_results"), dict) else {}
    for node in run.get("nodes") or []:
        if not isinstance(node, dict):
            continue
        node_id = str(node.get("id") or node.get("node_id") or "")
        status = str(node.get("status") or "").lower()
        if node_id and isinstance(node_results.get(node_id), dict):
            status = str(node_results[node_id].get("status") or status).lower()
        if status in {"failed", "error", "inconclusive"}:
            failed.append({
                "node_id": node_id or f"node-{len(failed) + 1:03d}",
                "logical_operator": str(node.get("logical_operator") or "N/A"),
                "status": status,
                "gate": str(node.get("gate") or "N/A"),
            })
    return failed


def _phase16_gate_rejections(run: dict[str, Any]) -> list[dict[str, Any]]:
    explicit = run.get("gate_rejection_reasons")
    if isinstance(explicit, list):
        return [item for item in explicit if isinstance(item, dict)]
    gate_results = run.get("gate_results") if isinstance(run.get("gate_results"), dict) else {}
    rejections: list[dict[str, Any]] = []
    for gate_id, result in gate_results.items():
        if not isinstance(result, dict):
            continue
        status = str(result.get("status") or "").lower()
        if status not in {"failed", "error", "inconclusive"}:
            continue
        reasons = result.get("reasons") if isinstance(result.get("reasons"), list) else []
        if not reasons and result.get("reason"):
            reasons = [str(result["reason"])]
        rejections.append({
            "gate_id": str(gate_id),
            "status": status,
            "reasons": [str(item) for item in reasons if str(item).strip()] or ["Gate failed without a structured reason."],
        })
    return rejections


def _phase16_list_of_dicts(run: dict[str, Any], key: str) -> list[dict[str, Any]]:
    value = run.get(key)
    if not isinstance(value, list):
        return []
    items: list[dict[str, Any]] = []
    for index, item in enumerate(value):
        if isinstance(item, dict):
            items.append(item)
        elif str(item).strip():
            items.append({"id": f"{key}-{index + 1:03d}", "description": str(item)})
    return items


def _phase16_evidence_ids(collected: dict[str, list[dict[str, Any]]], run: dict[str, Any]) -> list[str]:
    ids: list[str] = []
    for key, items in collected.items():
        for item in items:
            for field in ("evidence_id", "node_id", "gate_id", "id", "artifact", "path"):
                value = item.get(field)
                if isinstance(value, str) and value.strip():
                    ids.append(value)
            values = item.get("evidence_ids")
            if isinstance(values, list):
                ids.extend(str(value) for value in values if str(value).strip())
    for field in ("workflow_id", "sprint_id", "task_id"):
        value = run.get(field)
        if isinstance(value, str) and value.strip():
            ids.append(value)
    return _unique_strings(ids) or ["workflow-run-missing-evidence"]


def _phase16_proposed_changes(collected: dict[str, list[dict[str, Any]]], evidence_ids: list[str]) -> list[dict[str, Any]]:
    changes: list[dict[str, Any]] = []
    if collected["failed_nodes"]:
        node_ids = ", ".join(str(item.get("node_id") or "N/A") for item in collected["failed_nodes"])
        changes.append({
            "change_id": "change.workflow-template.failed-node-recovery",
            "category": "workflow_template",
            "target": "scientific_research_lifecycle_full_v1",
            "description": f"Add or tighten recovery guidance for failed nodes: {node_ids}.",
            "evidence_ids": evidence_ids,
            "review_required": True,
            "application_state": "proposed_only",
        })
    if collected["gate_rejection_reasons"]:
        changes.append({
            "change_id": "change.gate.rejection-diagnostics",
            "category": "gate",
            "target": "scientific evaluator gates",
            "description": "Expose gate rejection reasons in the dispatch/evidence handoff before retry.",
            "evidence_ids": evidence_ids,
            "review_required": True,
            "application_state": "proposed_only",
        })
    if collected["ambiguous_manuals_or_prompts"]:
        changes.append({
            "change_id": "change.manual.ambiguity-clarification",
            "category": "manual",
            "target": "scientific dispatch manuals",
            "description": "Clarify ambiguous manual or prompt language cited by the failed run.",
            "evidence_ids": evidence_ids,
            "review_required": True,
            "application_state": "proposed_only",
        })
    if collected["insufficient_schemas"]:
        changes.append({
            "change_id": "change.schema.required-field-tightening",
            "category": "schema",
            "target": "scientific Evidence ABI schemas",
            "description": "Review whether missing fields should become schema requirements or deterministic gate checks.",
            "evidence_ids": evidence_ids,
            "review_required": True,
            "application_state": "proposed_only",
        })
    if collected["poor_operator_bindings"]:
        changes.append({
            "change_id": "change.routing.operator-binding",
            "category": "routing",
            "target": "logical-to-physical operator bindings",
            "description": "Review operator binding constraints for the cited poor bindings.",
            "evidence_ids": evidence_ids,
            "review_required": True,
            "application_state": "proposed_only",
        })
    if not changes:
        changes.append({
            "change_id": "change.other.collect-more-evidence",
            "category": "other",
            "target": "workflow postmortem collection",
            "description": "Collect more structured failure evidence before changing workflow behavior.",
            "evidence_ids": evidence_ids,
            "review_required": True,
            "application_state": "proposed_only",
        })
    return changes


def _phase16_markdown(raw: dict[str, Any]) -> str:
    collected = raw["collected"]
    lines = [
        "# Recommended Scientific Workflow Changes",
        "",
        "## Scope",
        "",
        str(raw.get("scope") or "scientific research workflow"),
        "",
        "## Failed Nodes",
        "",
    ]
    for node in collected["failed_nodes"] or [{"node_id": "N/A", "status": "N/A"}]:
        lines.append(f"- `{node.get('node_id', 'N/A')}` status `{node.get('status', 'N/A')}` gate `{node.get('gate', 'N/A')}`")
    lines.extend(["", "## Gate Rejection Reasons", ""])
    for rejection in collected["gate_rejection_reasons"] or [{"gate_id": "N/A", "reasons": ["N/A"]}]:
        reasons = "; ".join(str(item) for item in rejection.get("reasons") or ["N/A"])
        lines.append(f"- `{rejection.get('gate_id', 'N/A')}`: {reasons}")
    lines.extend(["", "## Proposed Changes", ""])
    for change in raw["proposed_changes"]:
        lines.append(
            "- "
            f"`{change.get('change_id', 'N/A')}` [{change.get('category', 'other')}] "
            f"{change.get('target', 'N/A')}: {change.get('description', 'N/A')}"
        )
    lines.extend([
        "",
        "## Patch Candidates",
        "",
        f"- Directory: `{raw.get('patch_candidates_path', 'N/A')}`",
        "- Status: proposed-only; no patch candidate is applied by this action.",
        "",
        "## Review Controls",
        "",
        "- Approval state: proposed",
        "- Protected core runtime edited: false",
        "- Human can accept or reject each proposed change independently.",
    ])
    return "\n".join(lines).rstrip() + "\n"


def _phase16_workflow_evolution_raw(envelope: dict[str, Any]) -> dict[str, Any]:
    run = _phase16_failed_run(envelope)
    collected = {
        "failed_nodes": _phase16_failed_nodes(run),
        "gate_rejection_reasons": _phase16_gate_rejections(run),
        "ambiguous_manuals_or_prompts": _phase16_list_of_dicts(run, "ambiguous_manuals_or_prompts"),
        "insufficient_schemas": _phase16_list_of_dicts(run, "insufficient_schemas"),
        "poor_operator_bindings": _phase16_list_of_dicts(run, "poor_operator_bindings"),
        "human_intervention_points": _phase16_list_of_dicts(run, "human_intervention_points"),
        "runtime_errors": _phase16_list_of_dicts(run, "runtime_errors"),
    }
    evidence_ids = _phase16_evidence_ids(collected, run)
    proposed_changes = _phase16_proposed_changes(collected, evidence_ids)
    paths = _phase16_paths(envelope)
    paths["patch_candidates"].mkdir(parents=True, exist_ok=True)
    scope = str(run.get("workflow_id") or run.get("sprint_id") or "scientific research workflow")
    raw = {
        "proposal_id": f"workflow-evolution-{_slug(scope)}",
        "scope": scope,
        "change_type": "workflow_template",
        "rationale": "A failed scientific workflow run exposed recoverable workflow, gate, manual, schema, or routing gaps.",
        "expected_effect": "Make future failures easier to diagnose and resume without silently changing protected runtime behavior.",
        "approval_state": "proposed",
        "evidence_ids": evidence_ids,
        "collected": collected,
        "proposed_changes": proposed_changes,
        "review": {
            "human_accept_reject_required": True,
            "protected_core_edits_applied": False,
            "application_state": "proposed_only",
            "approval_ref": "N/A",
        },
        "recommended_changes_path": _rel(paths["recommended_changes"]),
        "patch_candidates_path": _rel(paths["patch_candidates"]),
        "artifacts": [
            _artifact("recommended_changes_markdown", paths["recommended_changes"]),
            _artifact("patch_candidates_directory", paths["patch_candidates"]),
        ],
        "limitations": [
            "Workflow evolution output is a proposal only; it does not modify capsules, schemas, gates, routing, or workflows.",
            "Fixture analysis is bounded to supplied failed-run evidence and local deterministic extraction.",
        ],
    }
    _write_text_sidecar(paths["recommended_changes"], _phase16_markdown(raw))
    return raw


def _action_evolve_workflow(envelope: dict[str, Any]) -> dict[str, Any]:
    return convert_workflow_evolution(_phase16_workflow_evolution_raw(envelope), envelope)


def _control_workflow_paths(envelope: dict[str, Any], action: str) -> dict[str, Path]:
    output_dir = _output_dir(envelope, action)
    return {
        "recommended_changes": _configured_output_path(
            envelope,
            "recommended_changes_path",
            output_dir / "recommended_changes.md",
        ),
        "patch_candidates": _configured_output_path(
            envelope,
            "patch_candidates_path",
            output_dir / "patch_candidates",
        ),
    }


def _reset_scope(envelope: dict[str, Any]) -> str:
    inputs = dict(envelope.get("inputs") or {})
    native = inputs.get("native_options") if isinstance(inputs.get("native_options"), dict) else {}
    return str(native.get("scope") or inputs.get("reset_scope") or "wiki").strip() or "wiki"


def _reset_scopes_from_payload(scope: str, payload: dict[str, Any]) -> list[str]:
    raw = payload.get("scopes")
    if isinstance(raw, list) and raw:
        return [str(item) for item in raw if str(item).strip()]
    if not scope or scope == "all":
        return ["wiki", "raw", "log", "checkpoints"]
    return [item.strip() for item in scope.split(",") if item.strip()]


def _append_contract_path(contract: dict[str, Any], key: str, path: Path) -> None:
    entries = contract.setdefault(key, [])
    if not isinstance(entries, list):
        entries = []
        contract[key] = entries
    existing = {str(item.get("artifact_path") or item.get("path") or "") for item in entries if isinstance(item, dict)}
    for entry in _approval_path_entries([str(path)]):
        ref = str(entry.get("artifact_path") or entry.get("path") or "")
        if ref and ref not in existing:
            entries.append(entry)


def _reset_state_snapshot(wiki_root: Path, project_root: Path, scopes: list[str], tool_payload: dict[str, Any]) -> dict[str, Any]:
    wiki_dirs: dict[str, Any] = {}
    if wiki_root.exists():
        for child in sorted(path for path in wiki_root.iterdir() if path.is_dir()):
            wiki_dirs[child.name] = {
                "markdown_count": len(list(child.glob("*.md"))),
                "gitkeep_exists": (child / ".gitkeep").exists(),
            }
    raw_dirs: dict[str, Any] = {}
    raw_root = project_root / "raw"
    if raw_root.exists():
        for child in sorted(path for path in raw_root.iterdir() if path.is_dir()):
            raw_dirs[child.name] = {
                "item_count": len([path for path in child.iterdir() if path.name != ".gitkeep"]),
                "gitkeep_exists": (child / ".gitkeep").exists(),
            }
    return {
        "schema": "autosci_reset_after_snapshot.v1",
        "status": "completed" if str(tool_payload.get("status") or "") == "completed" else "snapshot",
        "scopes": scopes,
        "wiki_root": str(wiki_root),
        "project_root": str(project_root),
        "wiki_log_exists": (wiki_root / "log.md").exists(),
        "wiki_index_exists": (wiki_root / "index.md").exists(),
        "wiki_directories": wiki_dirs,
        "raw_directories": raw_dirs,
        "tool_status": str(tool_payload.get("status") or ""),
        "tool_counts": {
            "deleted_files": int(tool_payload.get("deleted_files") or 0),
            "reset_files": int(tool_payload.get("reset_files") or 0),
        },
        "captured_at": datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
    }


def _run_reset_wiki_tool(
    envelope: dict[str, Any],
    *,
    scope: str,
    execute: bool,
    approval_ref: str,
) -> dict[str, Any]:
    output_dir = _output_dir(envelope, "reset_plan")
    output_dir.mkdir(parents=True, exist_ok=True)
    wiki_root = _wiki_roots_for_write(envelope)[0]
    project_root = wiki_root.parent
    tool_path = REPO_HARNESS_DIR.parent / "tools" / "reset_wiki.py"
    artifact_prefix = "reset_wiki_execute" if execute else "reset_wiki_dry_run"
    runtime_evidence_path = output_dir / "reset_wiki_runtime_evidence.json"
    command = [
        sys.executable,
        str(tool_path),
        "--scope",
        scope,
        "--wiki-root",
        str(wiki_root),
        "--project-root",
        str(project_root),
    ]
    if execute:
        command.extend([
            "--yes",
            "--execute-approved",
            "--approval-ref",
            approval_ref,
            "--runtime-evidence-out",
            str(runtime_evidence_path),
        ])
    else:
        command.append("--dry-run")

    env = dict(os.environ)
    env["HARNESS_DIR"] = str(HARNESS_DIR)
    timeout = int(os.environ.get("AUTOSCI_RESET_TIMEOUT_SECONDS", "20"))
    try:
        proc = subprocess.run(
            command,
            cwd=REPO_HARNESS_DIR.parent,
            env=env,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            check=False,
            timeout=timeout,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        stdout_path = _write_text_sidecar(
            output_dir / f"{artifact_prefix}_stdout.json",
            json.dumps({"status": "failed", "message": str(exc)}, sort_keys=True),
        )
        stderr_path = _write_text_sidecar(output_dir / f"{artifact_prefix}_stderr.txt", str(exc))
        return {
            "returncode": 1,
            "payload": {"status": "failed", "message": str(exc)},
            "artifacts": [
                {"type": f"{artifact_prefix}_stdout_json", "path": stdout_path},
                {"type": f"{artifact_prefix}_stderr", "path": stderr_path},
            ],
            "command": command,
            "wiki_root": wiki_root,
            "project_root": project_root,
        }

    stdout_path = _write_text_sidecar(output_dir / f"{artifact_prefix}_stdout.json", proc.stdout)
    stderr_path = _write_text_sidecar(output_dir / f"{artifact_prefix}_stderr.txt", proc.stderr)
    payload: dict[str, Any]
    try:
        payload = json.loads(proc.stdout) if proc.stdout.strip() else {}
    except json.JSONDecodeError:
        payload = {"status": "non_json_stdout", "raw": proc.stdout[:512]}
    if not isinstance(payload, dict):
        payload = {}

    artifacts: list[dict[str, str]] = [
        {"type": f"{artifact_prefix}_stdout_json", "path": stdout_path},
        {"type": f"{artifact_prefix}_stderr", "path": stderr_path},
    ]
    plan_artifact = output_dir / "reset_wiki_dry_run_plan.json"
    if not execute:
        artifacts.append({"type": "reset_plan_json", "path": _write_json_sidecar(plan_artifact, payload)})
    if execute and runtime_evidence_path.exists():
        artifacts.append({"type": "reset_runtime_evidence_json", "path": _rel(runtime_evidence_path)})
        plan_path = Path(str(runtime_evidence_path) + ".plan.json")
        if plan_path.exists():
            artifacts.append({"type": "reset_plan_json", "path": _rel(plan_path)})
    return {
        "returncode": proc.returncode,
        "payload": payload,
        "artifacts": artifacts,
        "command": command,
        "wiki_root": wiki_root,
        "project_root": project_root,
        "runtime_evidence_path": runtime_evidence_path if runtime_evidence_path.exists() else None,
    }


def _reset_plan_markdown(
    *,
    target: str,
    scope: str,
    dry_run: dict[str, Any],
    executed: bool,
    contract: dict[str, Any],
) -> str:
    payload = dry_run.get("payload") if isinstance(dry_run.get("payload"), dict) else {}
    delete_count = len(payload.get("delete_files") or [])
    reset_count = len(payload.get("reset_files") or [])
    return "\n".join(
        [
            "# Reset Plan Proposal",
            "",
            f"Target: `{target}`",
            f"Scope: `{scope}`",
            "",
            "## Dry Run",
            "",
            f"- Planned delete files: `{delete_count}`",
            f"- Planned reset files: `{reset_count}`",
            f"- Tool status: `{payload.get('status', 'N/A')}`",
            "",
            "## Controls",
            "",
            f"- Approval state: `{contract.get('approval_state')}`",
            f"- Side effects executed locally: `{str(executed).lower()}`",
            f"- Approval ref: `{contract.get('approval_ref') or 'N/A'}`",
            "",
        ]
    )


def _reset_plan_raw(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    target = str(inputs.get("target") or inputs.get("topic") or "reset plan")
    scope = _reset_scope(envelope)
    evidence_ids = [f"reset:{_slug(target)}", f"reset-scope:{_slug(scope)}"]
    paths = _control_workflow_paths(envelope, "reset_plan")
    paths["patch_candidates"].mkdir(parents=True, exist_ok=True)
    dry_run = _run_reset_wiki_tool(envelope, scope=scope, execute=False, approval_ref="")
    dry_payload = dry_run.get("payload") if isinstance(dry_run.get("payload"), dict) else {}
    scopes = _reset_scopes_from_payload(scope, dry_payload)
    contract = _approval_contract(envelope, "reset_plan", ["destructive_reset", "state_archive", "workspace_rebuild"])
    contract, policy_decision, policy_artifacts = _policy_prepare_auto_contract(
        envelope,
        "reset_plan",
        ["read_local", "write_artifact", "local_command", "wiki_mutation", "destructive_mutation"],
        contract,
        allowlist_payload={
            "native_tool": "tools/reset_wiki.py",
            "scope": scope,
            "allowed_side_effects": ["scoped_reset", "state_archive", "workspace_rebuild"],
            "limitations": [
                "Policy approval applies only to the native reset_wiki.py scoped reset executor.",
                "Default strict_hitl and safe modes still block destructive reset execution.",
                "Use autosci_native or an explicit high-risk environment opt-in before auto-executing this path.",
            ],
        },
    )
    if policy_decision.get("execute_side_effects"):
        wiki_root = dry_run.get("wiki_root") if isinstance(dry_run.get("wiki_root"), Path) else _wiki_roots_for_write(envelope)[0]
        project_root = dry_run.get("project_root") if isinstance(dry_run.get("project_root"), Path) else wiki_root.parent
        before_snapshot_path = _output_dir(envelope, "reset_plan") / "reset_before_snapshot.json"
        before_snapshot = _reset_state_snapshot(wiki_root, project_root, scopes, dry_payload)
        before_snapshot["schema"] = "autosci_reset_before_snapshot.v1"
        before_snapshot["status"] = "snapshot"
        before_snapshot_artifact = {
            "type": "reset_before_snapshot_json",
            "path": _write_json_sidecar(before_snapshot_path, before_snapshot),
        }
        policy_artifacts.append(before_snapshot_artifact)
        _append_contract_path(contract, "before_artifacts", before_snapshot_path)
        _refresh_approval_contract(contract)
    inputs = dict(envelope.get("inputs") or {})
    external_runtime_supplied = bool(_input_path_values(inputs, "runtime_evidence"))
    execute_requested = bool(inputs.get("execute_approved_side_effect"))
    local_execution: dict[str, Any] = {
        "requested": execute_requested,
        "attempted": False,
        "executed": False,
        "mode": "external_runtime_evidence" if external_runtime_supplied else "local_reset_wiki",
        "scope": scope,
    }
    execution_artifacts: list[dict[str, str]] = []
    execution_refs: list[str | Path] = [str(artifact.get("path") or "") for artifact in dry_run.get("artifacts") or []]
    log_artifact: dict[str, str] | None = None
    after_snapshot_artifact: dict[str, str] | None = None

    if execute_requested and not external_runtime_supplied:
        if contract.get("ready_for_execution"):
            local_execution["attempted"] = True
            execution = _run_reset_wiki_tool(
                envelope,
                scope=scope,
                execute=True,
                approval_ref=str(contract.get("approval_ref") or ""),
            )
            execution_artifacts.extend(execution.get("artifacts") or [])
            execution_refs.extend(str(artifact.get("path") or "") for artifact in execution.get("artifacts") or [])
            execution_payload = execution.get("payload") if isinstance(execution.get("payload"), dict) else {}
            local_execution.update({
                "returncode": int(execution.get("returncode") or 0),
                "tool_status": str(execution_payload.get("status") or "unknown"),
                "deleted_files": int(execution_payload.get("deleted_files") or 0),
                "reset_files": int(execution_payload.get("reset_files") or 0),
            })
            executed = int(execution.get("returncode") or 0) == 0 and str(execution_payload.get("status") or "") == "completed"
            if executed:
                wiki_root = execution.get("wiki_root") if isinstance(execution.get("wiki_root"), Path) else _wiki_roots_for_write(envelope)[0]
                project_root = execution.get("project_root") if isinstance(execution.get("project_root"), Path) else wiki_root.parent
                if "log" not in scopes:
                    log_path = _write_generic_wiki_log(
                        wiki_root,
                        "AutoSci Reset",
                        wiki_root,
                        evidence_ids,
                        f"Applied approved reset scope `{scope}`.",
                    )
                    log_artifact = {"type": "wiki_log", "path": _rel(log_path)}
                    execution_artifacts.append(log_artifact)
                    execution_refs.append(log_artifact["path"])
                after_snapshot_path = _output_dir(envelope, "reset_plan") / "reset_after_snapshot.json"
                after_snapshot = _reset_state_snapshot(wiki_root, project_root, scopes, execution_payload)
                after_snapshot_artifact = {
                    "type": "reset_after_snapshot_json",
                    "path": _write_json_sidecar(after_snapshot_path, after_snapshot),
                }
                execution_artifacts.append(after_snapshot_artifact)
                execution_refs.append(after_snapshot_artifact["path"])
                runtime_evidence_path = execution.get("runtime_evidence_path")
                if isinstance(runtime_evidence_path, Path) and runtime_evidence_path.exists():
                    _append_contract_path(contract, "runtime_evidence", runtime_evidence_path)
                _append_contract_path(contract, "after_artifacts", after_snapshot_path)
                _refresh_approval_contract(contract)
            local_execution["executed"] = executed
        else:
            local_execution["blocked_reason"] = "Approval, allowlist, and before_artifact evidence are required before local reset execution."

    control_runtime_semantic: dict[str, Any] = {}
    external_control_runtime_verified = False
    if execute_requested and external_runtime_supplied:
        control_runtime_semantic = _approval_semantic_runtime(contract, "reset_plan")
        external_control_runtime_verified = bool(control_runtime_semantic.get("verified"))
        contract["semantic_runtime"] = control_runtime_semantic
    elif local_execution.get("executed"):
        control_runtime_semantic = _approval_semantic_runtime(contract, "reset_plan")
        contract["semantic_runtime"] = control_runtime_semantic

    contract_artifact = _write_approval_contract_sidecar(envelope, "reset_plan", contract)
    local_reset_executed = bool(local_execution.get("executed")) and bool(contract.get("execution_verified"))
    approval_state = "proposed"
    application_state = "proposed_only"
    gate_status = "blocked"
    gate_reason = (
        "Approved local reset executed through tools/reset_wiki.py."
        if local_reset_executed
        else (
            "Approved external reset runtime evidence was verified separately; local protected reset was not executed by the bridge."
            if external_control_runtime_verified
            else "Reset dry-run completed, but destructive execution is approval-gated."
        )
    )

    _write_text_sidecar(
        paths["recommended_changes"],
        _reset_plan_markdown(
            target=target,
            scope=scope,
            dry_run=dry_run,
            executed=local_reset_executed,
            contract=contract,
        ),
    )
    artifacts: list[dict[str, str]] = [
        _artifact("recommended_changes_markdown", paths["recommended_changes"]),
        _artifact("patch_candidates_directory", paths["patch_candidates"]),
        *(dry_run.get("artifacts") or []),
        *policy_artifacts,
        *execution_artifacts,
        contract_artifact,
    ]
    evidence_payload_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        _output_dir(envelope, "reset_plan") / "reset_plan.evidence.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    if local_reset_executed or external_control_runtime_verified:
        native_skill = "reset"
        mutation_refs = execution_refs if local_reset_executed else [
            str(artifact.get("path") or "")
            for artifact in [
                *_contract_existing_artifacts(contract, "runtime_evidence", "control_runtime_evidence_json"),
                *_contract_existing_artifacts(contract, "after_artifacts", "control_runtime_after_artifact"),
                *artifacts,
            ]
            if isinstance(artifact, dict)
        ]
        artifacts.extend(
            _write_approved_mutation_runtime_proof_manifests(
                envelope,
                action="reset_plan",
                native_skill=native_skill,
                evidence_path=evidence_payload_path,
                applied=True,
                contract=contract,
                contract_artifact=contract_artifact,
                source_refs=[],
                mutation_refs=mutation_refs,
                include_wiki_mutation=local_reset_executed and any(item in scopes for item in {"wiki", "log", "checkpoints"}),
                source_label="approved_reset_runtime",
                artifact_kind="reset_wiki_runtime",
                include_provider_source=False,
            )
        )

    limitations = [
        (
            "Approved local reset executed through tools/reset_wiki.py with refreshed runtime evidence and after snapshot."
            if local_reset_executed
            else (
                "Approved external reset runtime was verified from supplied evidence; local protected reset was not executed by the bridge."
                if external_control_runtime_verified
                else "Reset route produced a native dry-run plan only; no destructive mutation was applied."
            )
        ),
        *_approval_contract_limitations(contract),
    ]
    if int(dry_run.get("returncode") or 0) != 0:
        limitations.append("Reset dry-run tool returned a non-zero exit code.")
    if execute_requested and not external_runtime_supplied and not local_execution.get("attempted"):
        limitations.append(str(local_execution.get("blocked_reason") or "Local reset execution was blocked by the approval gate."))
    if policy_decision.get("execute_side_effects"):
        limitations.append(
            f"Auto-approved by gate policy mode `{policy_decision.get('mode')}`; destructive reset execution was scoped to native reset_wiki.py and verified by runtime/after artifacts."
        )

    proposed_changes = [
        {
            "change_id": "change.reset.scope_plan",
            "category": "manual",
            "target": "tools/reset_wiki.py",
            "description": f"Use native reset scope `{scope}` and preserve the dry-run plan before any destructive execution.",
            "evidence_ids": evidence_ids,
            "review_required": True,
            "application_state": application_state,
        },
        {
            "change_id": "change.reset.approval_gate",
            "category": "gate",
            "target": "approval gate",
            "description": "Execute reset only after explicit approval, allowlist evidence, and before-state evidence.",
            "evidence_ids": evidence_ids,
            "review_required": True,
            "application_state": application_state,
        },
    ]
    return {
        "proposal_id": f"reset-plan-{_slug(target)}",
        "scope": "reset plan",
        "change_type": "workflow_template",
        "rationale": "Native AutoSci reset requires scoped dry-run planning and approval-gated execution evidence.",
        "expected_effect": "Make reset destructive behavior auditable while preserving original scope semantics.",
        "approval_state": approval_state,
        "evidence_ids": evidence_ids,
        "collected": {
            "failed_nodes": [
                {
                    "node_id": "node-reset-plan",
                    "logical_operator": "ScientificWorkflowEvolver",
                    "status": "blocked",
                    "gate": "approval_gate",
                }
            ],
            "gate_rejection_reasons": [
                {
                    "gate_id": "approval_gate",
                    "status": gate_status,
                    "reasons": [
                        gate_reason,
                        f"Approval contract missing: {', '.join(str(item) for item in contract.get('missing', [])) if contract.get('missing') else 'N/A'}",
                    ],
                }
            ],
            "ambiguous_manuals_or_prompts": [],
            "insufficient_schemas": [],
            "poor_operator_bindings": [],
            "human_intervention_points": [
                {
                    "id": "reset_plan.approval",
                    "description": "Human approval is required before destructive reset execution.",
                }
            ],
            "runtime_errors": []
            if int(dry_run.get("returncode") or 0) == 0
            else [{"id": "reset_wiki.dry_run", "description": "Reset dry-run command failed."}],
        },
        "proposed_changes": proposed_changes,
        "review": {
            "human_accept_reject_required": True,
            "protected_core_edits_applied": False,
            "application_state": application_state,
            "approval_ref": str(contract.get("approval_ref") or "N/A"),
            "approval_contract_path": contract_artifact["path"],
            "approval_contract_verified": bool(contract.get("execution_verified")),
            "external_control_runtime_verified": external_control_runtime_verified,
            "control_runtime_semantic": control_runtime_semantic or None,
            "reset_scope": scope,
            "reset_scopes": scopes,
            "reset_dry_run": {
                "status": str(dry_payload.get("status") or ""),
                "delete_count": len(dry_payload.get("delete_files") or []),
                "reset_count": len(dry_payload.get("reset_files") or []),
            },
            "local_reset_execution": local_execution,
            "policy_decision": policy_decision,
        },
        "recommended_changes_path": _rel(paths["recommended_changes"]),
        "patch_candidates_path": _rel(paths["patch_candidates"]),
        "artifacts": artifacts,
        "limitations": limitations,
        "policy_decision": policy_decision,
    }


SETUP_STATUS_KEYS = [
    ("SEMANTIC_SCHOLAR_API_KEY", "Semantic Scholar", "recommended"),
    ("DEEPXIV_TOKEN", "DeepXiv token", "optional"),
    ("DEEPXIV_API_URL", "DeepXiv endpoint", "optional"),
    ("LLM_API_KEY", "Review LLM API key", "optional"),
    ("LLM_BASE_URL", "Review LLM base URL", "optional"),
    ("LLM_MODEL", "Review LLM model", "optional"),
    ("OPENAI_API_KEY", "OpenAI-compatible API key", "optional"),
    ("AUTOSCI_REVIEW_LLM_PROVIDER", "Solar Review LLM provider", "optional"),
    ("AUTOSCI_REVIEW_LLM_MODEL", "Solar Review LLM model", "optional"),
    ("AUTOSCI_REVIEW_LLM_ENDPOINT", "Solar Review LLM endpoint", "optional"),
    ("ARXIV_CATEGORIES", "arXiv categories", "optional"),
    ("AUTOSCI_DISABLE_NETWORK_FETCH", "Offline source-fetch switch", "safety"),
]


def _dotenv_configured_keys(path: Path) -> dict[str, bool]:
    configured: dict[str, bool] = {}
    if not path.exists() or not path.is_file():
        return configured
    try:
        lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError:
        return configured
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#") or "=" not in stripped:
            continue
        key, value = stripped.split("=", 1)
        configured[key.strip()] = bool(value.strip().strip('"').strip("'"))
    return configured


def _setup_status_paths(envelope: dict[str, Any] | None = None) -> dict[str, Path]:
    inputs = envelope.get("inputs") if isinstance(envelope, dict) and isinstance(envelope.get("inputs"), dict) else {}
    raw_dotenv = str(inputs.get("setup_dotenv_path") or "").strip()
    dotenv = Path(raw_dotenv) if raw_dotenv else REPO_HARNESS_DIR.parent / ".env"
    if raw_dotenv and not dotenv.is_absolute():
        dotenv = HARNESS_DIR / dotenv
    return {
        "setup_guide": PLUGIN_DIR / "config" / "setup-guide.md",
        "env_example": PLUGIN_DIR / "config" / ".env.example",
        "dotenv": dotenv,
        "venv": REPO_HARNESS_DIR.parent / ".venv",
    }


def _setup_status_payload(envelope: dict[str, Any]) -> dict[str, Any]:
    paths = _setup_status_paths(envelope)
    dotenv_keys = _dotenv_configured_keys(paths["dotenv"])
    env_example_keys = _dotenv_configured_keys(paths["env_example"])
    key_statuses: list[dict[str, Any]] = []
    for key, label, priority in SETUP_STATUS_KEYS:
        process_configured = bool(os.environ.get(key, "").strip())
        dotenv_configured = bool(dotenv_keys.get(key))
        example_declared = key in env_example_keys or key in _dotenv_configured_keys(paths["env_example"])
        key_statuses.append({
            "key": key,
            "label": label,
            "priority": priority,
            "configured": process_configured or dotenv_configured,
            "process_env_set": process_configured,
            "dotenv_set": dotenv_configured,
            "env_example_declared": example_declared,
            "value_recorded": False,
        })
    configured_count = sum(1 for item in key_statuses if item["configured"])
    review_llm_ready = any(
        item["configured"]
        for item in key_statuses
        if item["key"] in {"LLM_API_KEY", "OPENAI_API_KEY"}
    ) and any(
        item["configured"]
        for item in key_statuses
        if item["key"] in {"LLM_BASE_URL", "LLM_MODEL", "AUTOSCI_REVIEW_LLM_MODEL", "AUTOSCI_REVIEW_LLM_ENDPOINT"}
    )
    setup_guide_sections = 0
    if paths["setup_guide"].exists():
        setup_guide_sections = sum(
            1
            for line in paths["setup_guide"].read_text(encoding="utf-8", errors="replace").splitlines()
            if line.startswith("## ")
        )
    return {
        "schema": "autosci_setup_status.v1",
        "status": "completed",
        "paths": {
            "setup_guide": _rel(paths["setup_guide"]),
            "env_example": _rel(paths["env_example"]),
            "dotenv": _rel(paths["dotenv"]),
            "venv": _rel(paths["venv"]),
        },
        "checks": [
            {
                "check": "setup_guide_present",
                "status": "ok" if paths["setup_guide"].exists() else "error",
                "detail": _rel(paths["setup_guide"]),
            },
            {
                "check": "env_template_present",
                "status": "ok" if paths["env_example"].exists() else "error",
                "detail": _rel(paths["env_example"]),
            },
            {
                "check": "dotenv_present",
                "status": "ok" if paths["dotenv"].exists() else "warn",
                "detail": "present" if paths["dotenv"].exists() else "not found",
            },
            {
                "check": "venv_present",
                "status": "ok" if paths["venv"].exists() else "warn",
                "detail": "present" if paths["venv"].exists() else "not found",
            },
            {
                "check": "python_version",
                "status": "ok",
                "detail": sys.version.split()[0],
            },
            {
                "check": "secrets_redacted",
                "status": "ok",
                "detail": "Only booleans and key names are recorded; secret values are never serialized.",
            },
        ],
        "summary": {
            "configured_count": configured_count,
            "known_key_count": len(key_statuses),
            "review_llm_ready": review_llm_ready,
            "setup_guide_section_count": setup_guide_sections,
            "python_executable": sys.executable,
        },
        "keys": key_statuses,
        "captured_at": datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
    }


def _setup_allowed_keys() -> set[str]:
    return {key for key, _label, _priority in SETUP_STATUS_KEYS}


def _parse_setup_env_after_artifact(path: Path) -> tuple[dict[str, str], list[str]]:
    values: dict[str, str] = {}
    errors: list[str] = []
    if not path.exists() or not path.is_file():
        return values, [f"Setup after_artifact does not exist or is not a file: {_rel(path)}"]
    allowed = _setup_allowed_keys()
    for line_no, line in enumerate(path.read_text(encoding="utf-8", errors="replace").splitlines(), start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if stripped.startswith("export "):
            stripped = stripped[len("export "):].strip()
        if "=" not in stripped:
            errors.append(f"Line {line_no} is not KEY=value.")
            continue
        key, value = stripped.split("=", 1)
        key = key.strip()
        value = value.strip()
        if key not in allowed:
            errors.append(f"Line {line_no} key `{key}` is not an AutoSci setup key.")
            continue
        if not value.strip().strip('"').strip("'"):
            errors.append(f"Line {line_no} key `{key}` has an empty value.")
            continue
        values[key] = value
    if not values and not errors:
        errors.append("Setup after_artifact contained no approved KEY=value rows.")
    return values, errors


def _setup_redacted_snapshot(path: Path, *, status: str, label: str) -> dict[str, Any]:
    configured = _dotenv_configured_keys(path)
    return {
        "schema": f"autosci_setup_{label}_snapshot.v1",
        "status": status,
        "dotenv_path": _rel(path),
        "dotenv_exists": path.exists(),
        "configured_keys": sorted(key for key, present in configured.items() if present),
        "secret_values_recorded": False,
        "captured_at": datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
    }


def _setup_config_write_if_approved(
    envelope: dict[str, Any],
    contract: dict[str, Any],
) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    explicit_dotenv = bool(str(inputs.get("setup_dotenv_path") or "").strip())
    execution = {
        "requested": bool(inputs.get("execute_approved_side_effect")) and explicit_dotenv,
        "attempted": False,
        "executed": False,
        "reason": "",
        "secret_values_recorded": False,
        "keys_written": [],
    }
    artifacts: list[dict[str, str]] = []
    if not bool(inputs.get("execute_approved_side_effect")):
        execution["reason"] = "execute_approved_side_effect=false"
        return {"execution": execution, "artifacts": artifacts}
    dotenv_path = _setup_status_paths(envelope)["dotenv"]
    after_paths = _input_path_values(inputs, "after_artifacts")
    if not explicit_dotenv:
        execution["reason"] = "setup_dotenv_path_not_requested"
        return {"execution": execution, "artifacts": artifacts}
    if not contract.get("ready_for_execution"):
        execution["reason"] = "approval_contract_preflight_incomplete"
        return {"execution": execution, "artifacts": artifacts}
    if not after_paths:
        execution["reason"] = "after_artifact_required"
        return {"execution": execution, "artifacts": artifacts}

    before_snapshot_path = _output_dir(envelope, "setup_status") / "setup_before_snapshot.json"
    before_snapshot = _setup_redacted_snapshot(dotenv_path, status="snapshot", label="before")
    before_artifact = {"type": "setup_before_snapshot_json", "path": _write_json_sidecar(before_snapshot_path, before_snapshot)}
    artifacts.append(before_artifact)
    _append_contract_path(contract, "before_artifacts", before_snapshot_path)
    _refresh_approval_contract(contract)

    after_path = _resolve_harness_path(after_paths[0])
    values, errors = _parse_setup_env_after_artifact(after_path)
    if errors:
        execution["reason"] = "invalid_after_artifact"
        execution["errors"] = errors
        return {"execution": execution, "artifacts": artifacts}

    execution["attempted"] = True
    dotenv_path.parent.mkdir(parents=True, exist_ok=True)
    body = "\n".join(f"{key}={values[key]}" for key in sorted(values)) + "\n"
    changed = _write_text_if_changed_bridge(dotenv_path, body)
    after_snapshot_path = _output_dir(envelope, "setup_status") / "setup_after_snapshot.json"
    after_snapshot = _setup_redacted_snapshot(dotenv_path, status="completed", label="after")
    after_artifact = {"type": "setup_after_snapshot_json", "path": _write_json_sidecar(after_snapshot_path, after_snapshot)}
    runtime_path = _output_dir(envelope, "setup_status") / "setup_config_runtime_evidence.json"
    runtime_payload = {
        "schema": "autosci_setup_config_runtime.v1",
        "status": "completed",
        "exit_code": 0,
        "dotenv_path": _rel(dotenv_path),
        "after_artifact": _rel(after_path),
        "keys_written": sorted(values),
        "changed": changed,
        "secret_values_recorded": False,
        "evidence_ids": [f"setup-config:{_slug(key)}" for key in sorted(values)],
    }
    runtime_artifact = {"type": "setup_config_runtime_evidence_json", "path": _write_json_sidecar(runtime_path, runtime_payload)}
    artifacts.extend([after_artifact, runtime_artifact])
    _append_contract_path(contract, "after_artifacts", after_snapshot_path)
    _append_contract_path(contract, "after_artifacts", dotenv_path)
    _append_contract_path(contract, "runtime_evidence", runtime_path)
    _refresh_approval_contract(contract)
    execution.update({
        "executed": True,
        "changed": changed,
        "dotenv_path": _rel(dotenv_path),
        "keys_written": sorted(values),
        "runtime_evidence": runtime_artifact["path"],
        "after_snapshot": after_artifact["path"],
    })
    return {"execution": execution, "artifacts": artifacts}


def _setup_status_markdown(status: dict[str, Any], *, contract: dict[str, Any]) -> str:
    summary = status.get("summary") if isinstance(status.get("summary"), dict) else {}
    lines = [
        "# Setup Status",
        "",
        "## Configuration",
        "",
        f"- Configured keys: `{summary.get('configured_count', 0)}` / `{summary.get('known_key_count', 0)}`",
        f"- Review LLM ready: `{str(bool(summary.get('review_llm_ready'))).lower()}`",
        f"- Python: `{summary.get('python_executable', 'N/A')}`",
        "",
        "## Key Status",
        "",
        "| Key | Status |",
        "| --- | --- |",
    ]
    for item in status.get("keys") or []:
        if not isinstance(item, dict):
            continue
        state = "set" if item.get("configured") else "unset"
        lines.append(f"| `{item.get('key')}` | `{state}` |")
    lines.extend([
        "",
        "## Controls",
        "",
        f"- Approval state: `{contract.get('approval_state')}`",
        "- Secret values recorded: `false`",
        f"- Local `.env` mutation by bridge: `{str(bool(contract.get('setup_config_applied'))).lower()}`",
        "",
    ])
    return "\n".join(lines)


def _setup_status_raw(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    target = str(inputs.get("target") or inputs.get("topic") or "setup status")
    evidence_ids = [f"setup:{_slug(target)}"]
    paths = _control_workflow_paths(envelope, "setup_status")
    paths["patch_candidates"].mkdir(parents=True, exist_ok=True)
    status = _setup_status_payload(envelope)
    contract = _approval_contract(envelope, "setup_status", ["credential_probe", "persistent_config_write", "workspace_bootstrap"])
    contract, policy_decision, policy_artifacts = _policy_prepare_auto_contract(
        envelope,
        "setup_status",
        ["read_local", "write_artifact", "protected_config_mutation", "credential_mutation"],
        contract,
        allowlist_payload={
            "native_surface": "$setup",
            "allowed_side_effects": ["approved_dotenv_write"],
            "limitations": [
                "Policy approval can only write a user-supplied after_artifact to an explicit setup_dotenv_path.",
                "Secret values are written to the target .env file but are never serialized into evidence.",
                "Default strict_hitl and safe modes still block setup credential/config mutation.",
            ],
        },
    )
    inputs = dict(envelope.get("inputs") or {})
    setup_write = _setup_config_write_if_approved(envelope, contract)
    setup_execution = setup_write.get("execution") if isinstance(setup_write.get("execution"), dict) else {}
    if setup_execution.get("executed"):
        contract["setup_config_applied"] = True
        status = _setup_status_payload(envelope)
    status_path = _output_dir(envelope, "setup_status") / "setup_status.json"
    status_artifact = {"type": "setup_status_json", "path": _write_json_sidecar(status_path, status)}
    control_runtime_semantic: dict[str, Any] = {}
    control_runtime_verified = False
    if bool(inputs.get("execute_approved_side_effect")):
        control_runtime_semantic = _approval_semantic_runtime(contract, "setup_status")
        contract["semantic_runtime"] = control_runtime_semantic
        control_runtime_verified = bool(control_runtime_semantic.get("verified"))
    contract_artifact = _write_approval_contract_sidecar(envelope, "setup_status", contract)
    _write_text_sidecar(paths["recommended_changes"], _setup_status_markdown(status, contract=contract))
    artifacts: list[dict[str, str]] = [
        _artifact("recommended_changes_markdown", paths["recommended_changes"]),
        _artifact("patch_candidates_directory", paths["patch_candidates"]),
        status_artifact,
        {"type": "setup_guide_markdown", "path": _rel(_setup_status_paths(envelope)["setup_guide"])},
        {"type": "env_example", "path": _rel(_setup_status_paths(envelope)["env_example"])},
        *policy_artifacts,
        *[artifact for artifact in setup_write.get("artifacts") or [] if isinstance(artifact, dict)],
        contract_artifact,
    ]
    if control_runtime_verified:
        evidence_payload_path = _configured_output_path(
            envelope,
            "evidence_payload_path",
            _output_dir(envelope, "setup_status") / "setup_status.evidence.json",
            legacy_key="evidence_path",
            legacy_suffix=".json",
        )
        runtime_refs = [
            str(artifact.get("path") or "")
            for artifact in [
                *_contract_existing_artifacts(contract, "runtime_evidence", "control_runtime_evidence_json"),
                *_contract_existing_artifacts(contract, "after_artifacts", "control_runtime_after_artifact"),
                *artifacts,
            ]
            if isinstance(artifact, dict)
        ]
        artifacts.extend(
            _write_approved_mutation_runtime_proof_manifests(
                envelope,
                action="setup_status",
                native_skill="setup",
                evidence_path=evidence_payload_path,
                applied=True,
                contract=contract,
                contract_artifact=contract_artifact,
                source_refs=[],
                mutation_refs=runtime_refs,
                include_wiki_mutation=False,
                source_label="approved_setup_runtime",
                artifact_kind="setup_status_runtime",
                include_provider_source=False,
            )
        )
    limitations = [
        (
            "Approved setup config mutation wrote the supplied after_artifact to the explicit setup_dotenv_path; secret values were not serialized into evidence."
            if setup_execution.get("executed")
            else (
                "Approved external setup runtime was verified from supplied evidence; local secret/config mutation was not executed by the bridge."
                if control_runtime_verified
                else "Setup route reports configuration status only; it does not write secrets or credentials."
            )
        ),
        *_approval_contract_limitations(contract),
    ]
    if setup_execution.get("requested") and setup_execution.get("reason") and not setup_execution.get("executed"):
        limitations.append(f"Setup config write was not executed: {setup_execution.get('reason')}.")
    if policy_decision.get("execute_side_effects"):
        limitations.append(
            f"Auto-approved by gate policy mode `{policy_decision.get('mode')}`; setup writes still require after_artifact and explicit setup_dotenv_path."
        )
    application_state = "applied" if setup_execution.get("executed") else "proposed_only"
    gate_status = "passed" if setup_execution.get("executed") else "blocked"
    proposed_changes = [
        {
            "change_id": "change.setup.status",
            "category": "manual",
            "target": "setup status",
            "description": "Review current provider key status and choose which optional keys to configure.",
            "evidence_ids": evidence_ids,
            "review_required": True,
            "application_state": application_state,
        },
        {
            "change_id": "change.setup.approval_gate",
            "category": "gate",
            "target": "approval gate",
            "description": "Keep .env writes blocked unless explicit approved runtime evidence supplies user-selected secret values.",
            "evidence_ids": evidence_ids,
            "review_required": True,
            "application_state": application_state,
        },
    ]
    status_summary = status.get("summary") if isinstance(status.get("summary"), dict) else {}
    return {
        "proposal_id": f"setup-status-{_slug(target)}",
        "scope": "setup status",
        "change_type": "workflow_template",
        "rationale": "Native AutoSci setup requires configuration guide review, environment status detection, and approval-gated credential writes.",
        "expected_effect": "Make setup readiness auditable without serializing secrets or mutating .env automatically.",
        "approval_state": "applied" if setup_execution.get("executed") else "proposed",
        "evidence_ids": evidence_ids,
        "collected": {
            "failed_nodes": []
            if gate_status == "passed"
            else [
                {
                    "node_id": "node-setup-status",
                    "logical_operator": "ScientificWorkflowEvolver",
                    "status": "blocked",
                    "gate": "approval_gate",
                }
            ],
            "gate_rejection_reasons": [
                {
                    "gate_id": "approval_gate",
                    "status": gate_status,
                    "reasons": [
                        "Approved setup config mutation executed with redacted evidence."
                        if setup_execution.get("executed")
                        else "Setup writes are approval-gated; status detection completed without writing secrets.",
                        f"Approval contract missing: {', '.join(str(item) for item in contract.get('missing', [])) if contract.get('missing') else 'N/A'}",
                    ],
                }
            ],
            "ambiguous_manuals_or_prompts": [],
            "insufficient_schemas": [],
            "poor_operator_bindings": [],
            "human_intervention_points": []
            if gate_status == "passed"
            else [
                {
                    "id": "setup_status.configure_keys",
                    "description": "User chooses which optional provider keys to configure before any .env write.",
                }
            ],
            "runtime_errors": [
                {"id": item["check"], "description": item["detail"]}
                for item in status.get("checks", [])
                if isinstance(item, dict) and item.get("status") == "error"
            ],
        },
        "proposed_changes": proposed_changes,
        "review": {
            "human_accept_reject_required": not bool(setup_execution.get("executed")),
            "protected_core_edits_applied": bool(setup_execution.get("executed")),
            "application_state": application_state,
            "approval_ref": str(contract.get("approval_ref") or "N/A"),
            "approval_contract_path": contract_artifact["path"],
            "approval_contract_verified": bool(contract.get("execution_verified")),
            "external_control_runtime_verified": control_runtime_verified,
            "control_runtime_semantic": control_runtime_semantic or None,
            "setup_status": {
                "configured_count": int(status_summary.get("configured_count") or 0),
                "known_key_count": int(status_summary.get("known_key_count") or 0),
                "review_llm_ready": bool(status_summary.get("review_llm_ready")),
                "setup_status_path": status_artifact["path"],
                "secrets_redacted": True,
            },
            "setup_config_execution": setup_execution,
            "policy_decision": policy_decision,
        },
        "recommended_changes_path": _rel(paths["recommended_changes"]),
        "patch_candidates_path": _rel(paths["patch_candidates"]),
        "artifacts": artifacts,
        "limitations": limitations,
        "policy_decision": policy_decision,
    }


def _refine_apply_path(envelope: dict[str, Any]) -> Path:
    return _output_dir(envelope, "refine_artifact") / "refine_apply_writeback.json"


def _refine_target_path_for_write(envelope: dict[str, Any], target: str) -> tuple[Path | None, list[str]]:
    if not target.strip():
        return None, ["Refine apply requires an explicit target artifact path."]
    target_path = _resolve_harness_path(target)
    roots = [HARNESS_DIR, *_wiki_roots_for_write(envelope)]
    if not any(_path_is_under(target_path, root) for root in roots):
        return None, [f"Refine target is outside the allowed harness/wiki roots: {target}"]
    if not target_path.exists() or target_path.is_dir():
        return None, [f"Refine target does not resolve to an existing file: {target}"]
    return target_path, []


def _refine_loop_report_path(envelope: dict[str, Any]) -> Path:
    return _output_dir(envelope, "refine_artifact") / "refine_loop_report.json"


def _refine_review_payloads(envelope: dict[str, Any], *, target: str) -> list[dict[str, Any]]:
    inputs = dict(envelope.get("inputs") or {})
    payloads: list[dict[str, Any]] = []
    for key in ("review_llm_evidence", "review_evidence", "artifact_review_evidence"):
        raw_value = inputs.get(key)
        raw_items = raw_value if isinstance(raw_value, list) else [raw_value]
        for raw_item in raw_items:
            if isinstance(raw_item, dict):
                payloads.append(dict(raw_item))
                continue
            payload = _load_optional_evidence(raw_item)
            if not payload:
                continue
            enriched = dict(payload)
            path = _resolve_harness_path(str(raw_item))
            if path.exists():
                enriched.setdefault("source_path", _rel(path))
            payloads.append(enriched)
    max_rounds = int(inputs.get("max_rounds") or 4)
    target_score = float(inputs.get("target_score") or 8.0)
    scores = _numeric_scores(_refine_review_records(payloads))
    latest_score = scores[-1] if scores else None
    review_auto_requested = bool(
        inputs.get("review_llm_command")
        or inputs.get("review_llm_provider")
        or inputs.get("review_llm_endpoint")
        or inputs.get("review_llm_requested")
    )
    if review_auto_requested and len(payloads) < max_rounds and (latest_score is None or latest_score < target_score):
        review_inputs = dict(inputs)
        review_inputs["target"] = target
        review_inputs["artifact_path"] = target
        review_inputs["review_llm_requested"] = True
        raw_review = review_artifact(
            review_inputs,
            workspace_root=HARNESS_DIR,
            repository_root=REPO_HARNESS_DIR,
        )
        review = raw_review.get("review") if isinstance(raw_review.get("review"), dict) else {}
        review_completed = (
            str(raw_review.get("status") or "") == "completed"
            and str(review.get("review_mode") or "") == "review_llm"
            and review.get("review_available") is True
        )
        payload = {
            "schema": "artifact_review.v1",
            "status": "completed" if review_completed else "inconclusive",
            "outputs": {
                "artifact": raw_review.get("artifact") if isinstance(raw_review.get("artifact"), dict) else {},
                "review": review,
                "findings": raw_review.get("findings") if isinstance(raw_review.get("findings"), list) else [],
            },
            "provenance": {
                "operator_id": "autosci-bridge",
                "implementation_package": "plugins/autosci/backends/artifact_review.py",
                "timestamp": datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
                "source": "refine_auto_review_loop",
            },
            "limitations": list(raw_review.get("limitations") or []),
        }
        round_path = _output_dir(envelope, "refine_artifact") / f"refine_review_round_{len(payloads) + 1:02d}.json"
        payload["source_path"] = _write_json_sidecar(round_path, payload)
        payloads.append(payload)
    return payloads


def _refine_review_records(payloads: list[dict[str, Any]]) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    for index, payload in enumerate(payloads, start=1):
        outputs = payload.get("outputs") if isinstance(payload.get("outputs"), dict) else {}
        review = outputs.get("review") if isinstance(outputs.get("review"), dict) else payload.get("review") if isinstance(payload.get("review"), dict) else {}
        review_llm = review.get("review_llm") if isinstance(review.get("review_llm"), dict) else {}
        findings = outputs.get("findings") if isinstance(outputs.get("findings"), list) else []
        actionable = review.get("actionable_items") or review.get("issues") or findings
        weaknesses = review.get("weaknesses") or findings
        records.append(
            {
                "round": index,
                "status": str(payload.get("status") or "unknown"),
                "source_path": str(payload.get("source_path") or payload.get("task_id") or payload.get("node_id") or ""),
                "review_mode": str(review.get("review_mode") or ""),
                "review_available": review.get("review_available") is True,
                "score": review.get("score", review_llm.get("score")),
                "verdict": str(review.get("verdict") or review.get("recommendation") or review_llm.get("recommendation") or "inconclusive"),
                "actionable_items": actionable if isinstance(actionable, list) else [],
                "weaknesses": weaknesses if isinstance(weaknesses, list) else [],
                "review_llm": {
                    "status": str(review_llm.get("status") or ""),
                    "provider": str(review_llm.get("provider") or ""),
                    "model": str(review_llm.get("model") or ""),
                    "evidence_ids": _unique_strings([str(item) for item in review_llm.get("evidence_ids") or []]),
                },
            }
        )
    return records


def _numeric_scores(records: list[dict[str, Any]]) -> list[float]:
    scores: list[float] = []
    for record in records:
        try:
            scores.append(float(record.get("score")))
        except (TypeError, ValueError):
            continue
    return scores


def _refine_loop_report(
    envelope: dict[str, Any],
    *,
    target: str,
    refine_application: dict[str, Any] | None,
    refine_applied: bool,
) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    payloads = _refine_review_payloads(envelope, target=target)
    records = _refine_review_records(payloads)
    scores = _numeric_scores(records)
    target_score = float(inputs.get("target_score") or 8.0)
    max_rounds = int(inputs.get("max_rounds") or 4)
    final_score = scores[-1] if scores else None
    target_reached = final_score is not None and final_score >= target_score
    if not records:
        termination_reason = "review_evidence_missing"
        status = "incomplete"
    elif target_reached:
        termination_reason = "target_score_reached"
        status = "completed"
    elif len(records) >= max_rounds:
        termination_reason = "max_rounds_reached"
        status = "incomplete"
    elif refine_applied:
        termination_reason = "quality_target_not_reached"
        status = "incomplete"
    else:
        termination_reason = "needs_more_rounds_or_approval"
        status = "incomplete"
    action_items: list[dict[str, Any]] = []
    for record in records:
        for item in record.get("actionable_items") or []:
            if isinstance(item, dict):
                action_items.append({**item, "round": record.get("round")})
            else:
                action_items.append({"round": record.get("round"), "issue": str(item)})
    fixed_issues: list[dict[str, Any]] = []
    unresolved_issues = [] if target_reached else action_items
    report = {
        "schema": "autosci_refine_loop_report.v1",
        "status": status,
        "target": target,
        "max_rounds": max_rounds,
        "target_score": target_score,
        "difficulty": str(inputs.get("difficulty") or ""),
        "focus": str(inputs.get("focus") or ""),
        "review_llm_requested": bool(
            inputs.get("review_llm_requested")
            or inputs.get("review_llm_evidence")
            or inputs.get("review_llm_command")
            or inputs.get("review_llm_provider")
            or inputs.get("review_llm_endpoint")
        ),
        "review_evidence_count": len(records),
        "review_evidence_completed": _review_llm_evidence_completed(payloads),
        "score_history": scores,
        "final_score": final_score,
        "final_verdict": records[-1].get("verdict") if records else "missing_review",
        "auto_review_rounds": [
            {
                "type": "refine_review_round_json",
                "path": str(payload.get("source_path") or ""),
            }
            for payload in payloads
            if isinstance(payload.get("provenance"), dict)
            and payload["provenance"].get("source") == "refine_auto_review_loop"
            and str(payload.get("source_path") or "").strip()
        ],
        "termination_reason": termination_reason,
        "approved_after_artifact_applied": refine_applied,
        "rounds": records,
        "fixed_issues": fixed_issues,
        "unresolved_issues": unresolved_issues,
        "limitations": [] if status == "completed" else [
            "Applying an approved after_artifact records a revision, but refinement remains incomplete until independent review reaches the requested quality score."
        ],
    }
    path = _write_json_sidecar(_refine_loop_report_path(envelope), report)
    return {"type": "refine_loop_report_json", "path": path, "report": report}


def _write_refine_review_runtime_proof_manifest(
    envelope: dict[str, Any],
    *,
    evidence_path: Path,
    refine_loop_artifact: dict[str, Any] | None,
) -> dict[str, str] | None:
    report = (refine_loop_artifact or {}).get("report") if isinstance(refine_loop_artifact, dict) else {}
    if not isinstance(report, dict):
        return None
    rounds = report.get("rounds") if isinstance(report.get("rounds"), list) else []
    completed_rounds = [
        record
        for record in rounds
        if isinstance(record, dict)
        if str((record.get("review_llm") or {}).get("status") or "") == "completed"
    ]
    if not completed_rounds:
        return None
    latest = completed_rounds[-1]
    latest_review = latest.get("review_llm") if isinstance(latest.get("review_llm"), dict) else {}
    evidence_ids = _unique_strings([
        str(item)
        for record in completed_rounds
        for item in ((record.get("review_llm") or {}).get("evidence_ids") or [])
        if str(item).strip()
    ])
    if not evidence_ids:
        return None
    checked_paths = _unique_strings([
        str((refine_loop_artifact or {}).get("path") or ""),
        *[str(record.get("source_path") or "") for record in completed_rounds],
    ])
    review_llm = {
        **latest_review,
        "status": "completed",
        "source_path": str(latest_review.get("source_path") or latest.get("source_path") or ""),
        "checked_paths": checked_paths,
        "evidence_ids": evidence_ids,
    }
    return _write_review_context_runtime_proof_manifest(
        envelope,
        action="refine_artifact",
        native_skill="refine",
        evidence_path=evidence_path,
        review_llm=review_llm,
    )


def _approved_refine_application(
    envelope: dict[str, Any],
    *,
    target: str,
    contract: dict[str, Any],
    evidence_ids: list[str],
) -> dict[str, Any] | None:
    if not _local_mutation_requested(envelope):
        return None

    inputs = dict(envelope.get("inputs") or {})
    after_artifacts = inputs.get("after_artifacts") if isinstance(inputs.get("after_artifacts"), list) else []
    status = "inconclusive"
    artifacts: list[dict[str, Any]] = []
    limitations: list[str] = []
    write: dict[str, Any] = {
        "requested": True,
        "applied": False,
        "approval_ref": str(contract.get("approval_ref") or "N/A"),
        "approval_state": str(contract.get("approval_state") or "unknown"),
        "target": target,
    }

    target_path: Path | None = None
    preflight_ready = contract.get("execution_verified") is True or (
        contract.get("policy_auto_approved") is True and contract.get("ready_for_execution") is True
    )
    if not preflight_ready:
        limitations.append("Refine apply requires verified approval, allowlist, runtime, before, and after artifacts.")
    elif not after_artifacts:
        limitations.append("Refine apply requires an after_artifact file containing the approved target contents.")
    else:
        target_path, target_errors = _refine_target_path_for_write(envelope, target)
        limitations.extend(target_errors)
        after_path = _resolve_harness_path(str(after_artifacts[0]))
        if not limitations and (not after_path.exists() or after_path.is_dir()):
            limitations.append("Refine apply after_artifact does not resolve to an existing file.")
        if not limitations and target_path is not None:
            before = target_path.read_text(encoding="utf-8", errors="replace")
            desired = after_path.read_text(encoding="utf-8", errors="replace")
            changed = _write_text_if_changed_bridge(target_path, desired)
            after = target_path.read_text(encoding="utf-8", errors="replace")
            wiki_root = next((root for root in _wiki_roots_for_write(envelope) if _path_is_under(target_path, root)), None)
            wiki_artifacts: list[dict[str, Any]] = []
            if wiki_root is not None:
                log_path = _write_generic_wiki_log(
                    wiki_root,
                    "Approved Artifact Refine",
                    target_path,
                    evidence_ids,
                    "Applied approved after_artifact contents during refine.",
                )
                rebuilt = _rebuild_generic_wiki_views(
                    wiki_root,
                    str(envelope.get("sprint_id") or "sprint-autosci"),
                    target_path,
                    evidence_ids,
                )
                wiki_artifacts.extend(
                    [
                        {"type": "wiki_log", "path": _rel(log_path)},
                        *[{"type": "wiki_rebuild", "path": _rel(path)} for path in rebuilt],
                    ]
                )
            status = "completed"
            write.update(
                {
                    "applied": True,
                    "target_path": _rel(target_path),
                    "after_artifact": _rel(after_path),
                    "changed": changed,
                    "before_sha256": _hash_text(before),
                    "after_sha256": _hash_text(after),
                }
            )
            artifacts.extend(
                [
                    {"type": "refined_artifact", "path": _rel(target_path)},
                    *wiki_artifacts,
                ]
            )
            runtime_artifact = _append_local_mutation_runtime_to_contract(
                envelope,
                "refine_artifact",
                contract,
                command_run="refine_artifact:local_after_artifact_apply",
                evidence_ids=evidence_ids,
                after_refs=[
                    target_path,
                    *[
                        str(artifact.get("path") or "")
                        for artifact in wiki_artifacts
                        if isinstance(artifact, dict)
                    ],
                ],
                runtime_fields={
                    "target_path": _rel(target_path),
                    "after_artifact": _rel(after_path),
                    "changed": changed,
                },
            )
            artifacts.append(runtime_artifact)
            limitations.append("Approved refine apply replaced the target artifact with the supplied after_artifact contents.")

    write["status"] = status
    sidecar_path = _refine_apply_path(envelope)
    write["sidecar_path"] = _rel(sidecar_path)
    evidence = {
        "schema": "refine_apply_writeback.v1",
        "task_id": f"task-refine-artifact:{_slug(target or 'target')}",
        "sprint_id": str(envelope.get("sprint_id") or "sprint-autosci"),
        "node_id": f"node-refine-artifact:{_slug(target or 'target')}",
        "status": status,
        "inputs": inputs,
        "outputs": {"write": write},
        "artifacts": artifacts,
        "provenance": {
            "operator_id": "autosci-bridge",
            "implementation_package": "plugins/autosci",
            "timestamp": datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        },
        "limitations": limitations,
    }
    artifact = {"type": "refine_apply_writeback_json", "path": _write_evidence_payload(sidecar_path, evidence)}
    return {"write": write, "artifact": artifact, "artifacts": artifacts, "limitations": limitations, "status": status}


def _control_workflow_raw(envelope: dict[str, Any], action: str, scope: str) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    target = str(inputs.get("target") or inputs.get("topic") or scope)
    evidence_ids = [f"{action}:{_slug(target)}"]
    paths = _control_workflow_paths(envelope, action)
    paths["patch_candidates"].mkdir(parents=True, exist_ok=True)
    side_effects_by_action = {
        "setup_status": ["credential_probe", "persistent_config_write", "workspace_bootstrap"],
        "reset_plan": ["destructive_reset", "state_archive", "workspace_rebuild"],
        "refine_artifact": ["artifact_mutation", "source_rewrite", "quality_gate_rerun"],
        "run_research_lifecycle": ["multi_step_execution", "network_fetch", "workspace_mutation"],
    }
    contract = _approval_contract(
        envelope,
        action,
        side_effects_by_action.get(action, ["protected_runtime_change"]),
    )
    policy_decision: dict[str, Any] = {}
    policy_artifacts: list[dict[str, str]] = []
    if action == "refine_artifact":
        contract, policy_decision, policy_artifacts = _policy_prepare_auto_contract_if_needed(
            envelope,
            action,
            ["read_local", "write_artifact", "wiki_mutation"],
            contract,
            allowlist_payload={
                "native_surface": "$refine",
                "allowed_side_effects": ["artifact_mutation", "source_rewrite", "quality_gate_rerun"],
                "limitations": [
                    "Policy approval applies only to applying a supplied after_artifact to a local target.",
                    "Review/model quality still requires explicit Review LLM evidence or a review command.",
                ],
            },
        )
    refine_application = (
        _approved_refine_application(envelope, target=target, contract=contract, evidence_ids=evidence_ids)
        if action == "refine_artifact"
        else None
    )
    refine_applied = bool((refine_application or {}).get("write", {}).get("applied"))
    refine_loop_artifact = (
        _refine_loop_report(envelope, target=target, refine_application=refine_application, refine_applied=refine_applied)
        if action == "refine_artifact"
        else None
    )
    refine_loop_report = (
        refine_loop_artifact.get("report")
        if isinstance(refine_loop_artifact, dict) and isinstance(refine_loop_artifact.get("report"), dict)
        else {}
    )
    refine_quality_complete = bool(
        refine_applied and refine_loop_report.get("status") == "completed"
    )
    contract_missing = contract.get("missing") if isinstance(contract.get("missing"), list) else []
    control_runtime_semantic: dict[str, Any] = {}
    control_runtime_verified = False
    if action in {"setup_status", "reset_plan"} and bool(inputs.get("execute_approved_side_effect")):
        control_runtime_semantic = _approval_semantic_runtime(contract, action)
        contract["semantic_runtime"] = control_runtime_semantic
        control_runtime_verified = bool(control_runtime_semantic.get("verified"))
    contract_artifact = _write_approval_contract_sidecar(envelope, action, contract)
    approval_state = "applied" if refine_applied else "proposed"
    application_state = "applied" if refine_applied else "proposed_only"
    collected = {
        "failed_nodes": []
        if (action != "refine_artifact" or refine_quality_complete)
        else [
            {
                "node_id": f"node-{action.replace('_', '-')}",
                "logical_operator": "ScientificWorkflowEvolver",
                "status": "blocked",
                "gate": "quality_gate" if refine_applied else "approval_gate",
            }
        ],
        "gate_rejection_reasons": [
            {
                "gate_id": "quality_gate" if refine_applied else "approval_gate",
                "status": "passed" if refine_quality_complete else "blocked",
                "reasons": [
                    (
                        "Approved refine side effect was applied and the independent quality target was reached."
                        if refine_quality_complete
                        else (
                            "Approved refine side effect was applied, but independent review did not reach the requested quality target."
                            if refine_applied
                            else (
                                "Approved external control runtime evidence was verified separately; local protected control side effects were not executed by the bridge."
                                if control_runtime_verified
                                else "Approval-gated control side effects were not executed."
                            )
                        )
                    ),
                    f"Approval contract missing: {', '.join(str(item) for item in contract_missing) if contract_missing else 'N/A'}",
                ],
            }
        ],
        "ambiguous_manuals_or_prompts": [
            {
                "id": f"{action}.manual",
                "description": "Document the exact user-approved values and write scope before applying changes.",
            }
        ],
        "insufficient_schemas": [],
        "poor_operator_bindings": [],
        "human_intervention_points": []
        if (action != "refine_artifact" or refine_quality_complete)
        else [
            {
                "id": f"{action}.quality" if refine_applied else f"{action}.approval",
                "description": (
                    "A further approved revision is required because independent review did not reach the requested quality target."
                    if refine_applied
                    else "Human approval is required before credentials, destructive reset, or persistent config changes."
                ),
            }
        ],
        "runtime_errors": [],
    }
    proposed_changes = [
        {
            "change_id": f"change.manual.{action}",
            "category": "manual",
            "target": scope,
            "description": f"Record the approved {action.replace('_', ' ')} checklist, requested target, and rollback notes.",
            "evidence_ids": evidence_ids,
            "review_required": True,
            "application_state": application_state,
        },
        {
            "change_id": f"change.gate.{action}",
            "category": "gate",
            "target": "approval gate",
            "description": "Keep side-effect execution blocked until approval evidence and before/after artifact evidence are present.",
            "evidence_ids": evidence_ids,
            "review_required": True,
            "application_state": application_state,
        },
    ]
    markdown = "\n".join(
        [
            f"# {scope.title()} Proposal",
            "",
            f"Target: `{target}`",
            "",
            "## Proposed Changes",
            "",
            *[
                f"- `{item['change_id']}` [{item['category']}]: {item['description']}"
                for item in proposed_changes
            ],
            "",
            "## Controls",
            "",
            f"- Approval state: {approval_state}",
            f"- Protected runtime changed: {str(refine_applied).lower()}",
            f"- Side effects executed: {str(refine_applied).lower()}",
            f"- Approval contract state: {contract.get('approval_state')}",
            "",
        ]
    )
    _write_text_sidecar(paths["recommended_changes"], markdown)
    artifacts = [
        _artifact("recommended_changes_markdown", paths["recommended_changes"]),
        _artifact("patch_candidates_directory", paths["patch_candidates"]),
        *policy_artifacts,
        contract_artifact,
    ]
    if refine_application:
        artifacts.append(refine_application["artifact"])
        artifacts.extend(refine_application.get("artifacts") or [])
    if refine_loop_artifact:
        artifacts.append({k: v for k, v in refine_loop_artifact.items() if k != "report"})
        report = refine_loop_artifact.get("report") if isinstance(refine_loop_artifact.get("report"), dict) else {}
        for artifact in report.get("auto_review_rounds") or []:
            if isinstance(artifact, dict) and str(artifact.get("path") or "").strip():
                artifacts.append({"type": str(artifact.get("type") or "refine_review_round_json"), "path": str(artifact["path"])})
    limitations = [
        (
            "Approved refine side effect was applied from verified before/runtime/after artifact evidence."
            if refine_applied
            else (
                "Approved external setup/reset runtime was verified from supplied evidence; this bridge did not execute local protected mutations."
                if control_runtime_verified
                else "This action produces proposal evidence only; no secrets, configuration, wiki files, or run artifacts were changed."
            )
        ),
        "Approval and before/after evidence are required before applying setup or reset side effects.",
        *_approval_contract_limitations(contract),
    ]
    if refine_application:
        limitations.extend(str(item) for item in refine_application.get("limitations") or [])
    if policy_decision.get("execute_side_effects"):
        limitations.append(
            f"Auto-approved by gate policy mode `{policy_decision.get('mode')}`; no human approval was requested."
        )
    if refine_loop_artifact:
        report = refine_loop_artifact.get("report") if isinstance(refine_loop_artifact.get("report"), dict) else {}
        limitations.extend(str(item) for item in report.get("limitations") or [])
    raw = {
        "proposal_id": f"{action}-{_slug(target)}",
        "scope": scope,
        "change_type": "workflow_template",
        "rationale": f"{scope} requires explicit approval and auditable before/after evidence.",
        "expected_effect": "Make the requested control action auditable without applying side effects.",
        "approval_state": approval_state,
        "evidence_ids": evidence_ids,
        "collected": collected,
        "proposed_changes": proposed_changes,
        "review": {
            "human_accept_reject_required": action == "refine_artifact" and not refine_quality_complete,
            "protected_core_edits_applied": refine_applied,
            "application_state": application_state,
            "approval_ref": str(contract.get("approval_ref") or "N/A"),
            "approval_contract_path": contract_artifact["path"],
            "approval_contract_verified": bool(contract.get("execution_verified")),
            "external_control_runtime_verified": control_runtime_verified,
            "control_runtime_semantic": control_runtime_semantic or None,
            "refine_apply": (refine_application or {}).get("write"),
            "refine_loop_report": (refine_loop_artifact or {}).get("report"),
        },
        "recommended_changes_path": _rel(paths["recommended_changes"]),
        "patch_candidates_path": _rel(paths["patch_candidates"]),
        "artifacts": artifacts,
        "limitations": limitations,
        "status": "inconclusive" if action == "refine_artifact" and not refine_quality_complete else "completed",
    }
    if policy_decision:
        raw["policy_decision"] = policy_decision
    if action == "refine_artifact" and refine_application:
        evidence_payload_path = _configured_output_path(
            envelope,
            "evidence_payload_path",
            _output_dir(envelope, action) / f"{action}.evidence.json",
            legacy_key="evidence_path",
            legacy_suffix=".json",
        )
        review_runtime_proof_artifact = _write_refine_review_runtime_proof_manifest(
            envelope,
            evidence_path=evidence_payload_path,
            refine_loop_artifact=refine_loop_artifact,
        )
        if review_runtime_proof_artifact is not None:
            raw["artifacts"].append(review_runtime_proof_artifact)
        write = refine_application.get("write") if isinstance(refine_application.get("write"), dict) else {}
        refine_artifacts = refine_application.get("artifacts") if isinstance(refine_application.get("artifacts"), list) else []
        raw["artifacts"].extend(
            _write_approved_mutation_runtime_proof_manifests(
                envelope,
                action=action,
                native_skill="refine",
                evidence_path=evidence_payload_path,
                applied=refine_applied,
                contract=contract,
                contract_artifact=contract_artifact,
                source_refs=[
                    str(write.get("after_artifact") or ""),
                    str(write.get("target_path") or ""),
                    str((refine_application.get("artifact") or {}).get("path") or ""),
                ],
                mutation_refs=[
                    str(write.get("sidecar_path") or ""),
                    str(write.get("target_path") or ""),
                    *[
                        str(artifact.get("path") or "")
                        for artifact in refine_artifacts
                        if isinstance(artifact, dict)
                    ],
                ],
                include_wiki_mutation=False,
                source_label="approved_refine_apply",
                artifact_kind="refine_apply_writeback",
            )
        )
    if action in {"setup_status", "reset_plan"} and control_runtime_verified:
        native_skill = "setup" if action == "setup_status" else "reset"
        evidence_payload_path = _configured_output_path(
            envelope,
            "evidence_payload_path",
            _output_dir(envelope, action) / f"{action}.evidence.json",
            legacy_key="evidence_path",
            legacy_suffix=".json",
        )
        runtime_refs = [
            str(artifact.get("path") or "")
            for artifact in [
                *_contract_existing_artifacts(contract, "runtime_evidence", "control_runtime_evidence_json"),
                *_contract_existing_artifacts(contract, "after_artifacts", "control_runtime_after_artifact"),
                *raw["artifacts"],
            ]
            if isinstance(artifact, dict)
        ]
        raw["artifacts"].extend(
            _write_approved_mutation_runtime_proof_manifests(
                envelope,
                action=action,
                native_skill=native_skill,
                evidence_path=evidence_payload_path,
                applied=True,
                contract=contract,
                contract_artifact=contract_artifact,
                source_refs=[],
                mutation_refs=runtime_refs,
                include_wiki_mutation=False,
                source_label=f"approved_{native_skill}_external_runtime",
                artifact_kind=f"{action}_external_runtime",
                include_provider_source=False,
            )
        )
    return raw


RESEARCH_LIFECYCLE_STAGES = (
    ("setup", "Setup and topic initialization"),
    ("ingest", "Source ingest and wiki paper registration"),
    ("discover", "Landscape scan and source evidence fetch"),
    ("ideate", "Gap map and idea generation"),
    ("novelty-review", "Novelty and Review LLM gates"),
    ("experiment-design", "Experiment design"),
    ("experiment-run", "Experiment deployment"),
    ("collect", "Result collection"),
    ("review", "Result and artifact review"),
    ("paper-plan", "Publication plan"),
    ("paper-compile", "LaTeX/PDF compile and checklist"),
)


def _research_stage_from_token(raw_stage: str) -> str:
    token = _slug(raw_stage)
    stage_ids = [stage_id for stage_id, _ in RESEARCH_LIFECYCLE_STAGES]
    if token in stage_ids:
        return token
    aliases = {
        "stage0-setup": "setup",
        "stage1-ingest": "ingest",
        "stage2-discover": "discover",
        "stage2-ideate": "ideate",
        "stage3-collect": "collect",
        "stage3-experiment": "experiment-run",
        "stage4-review": "review",
        "stage5-paper": "paper-plan",
        "stage6-compile": "paper-compile",
    }
    if token in aliases:
        return aliases[token]
    for stage_id in stage_ids:
        if stage_id in token:
            return stage_id
    return "setup"


def _research_lifecycle_paths(envelope: dict[str, Any]) -> dict[str, Path]:
    output_dir = _output_dir(envelope, "run_research_lifecycle")
    wiki_outputs = _wiki_roots_for_write(envelope)[0] / "outputs"
    return {
        "recommended_changes": _configured_output_path(
            envelope,
            "recommended_changes_path",
            output_dir / "research_lifecycle_recommended_changes.md",
        ),
        "patch_candidates": _configured_output_path(
            envelope,
            "patch_candidates_path",
            output_dir / "patch_candidates",
        ),
        "pipeline_progress": _configured_output_path(
            envelope,
            "pipeline_progress_path",
            wiki_outputs / "pipeline-progress.md",
        ),
        "pipeline_report": _configured_output_path(
            envelope,
            "pipeline_report_path",
            wiki_outputs / "PIPELINE_REPORT.md",
        ),
        "pipeline_state": _configured_output_path(
            envelope,
            "pipeline_state_path",
            wiki_outputs / "pipeline-state.json",
        ),
    }


def _research_lifecycle_probe_query(target: str) -> str:
    query = str(target or "").strip()
    query = re.sub(r"^\s*Analyze\s+", "", query, flags=re.IGNORECASE)
    query = re.sub(
        r"\.?\s*Extract\s+methods,\s*evidence-backed\s+claims,\s*trends,\s*and\s*gaps\s+from\s+https?://\S+\s*$",
        "",
        query,
        flags=re.IGNORECASE,
    ).strip(" .")
    return query or str(target or "autosci real data research").strip() or "autosci real data research"


def _research_lifecycle_real_data_probe_artifact(
    envelope: dict[str, Any],
    *,
    target: str,
    evidence_payload_path: Path,
) -> dict[str, str] | None:
    inputs = dict(envelope.get("inputs") or {})
    online_requested = bool(inputs.get("online")) or str(os.environ.get("SOLAR_AUTOSCI_ALLOW_NETWORK") or "").lower() in {"1", "true", "yes"}
    if not online_requested:
        return None
    workspace = evidence_payload_path.with_name("real-data-workspace")
    result_path = workspace / "real-data-research-run.json"
    query = _research_lifecycle_probe_query(target)
    run_id = str(inputs.get("run_id") or envelope.get("sprint_id") or hashlib.sha1(query.encode("utf-8")).hexdigest()[:16])
    scratch_workspace = REPO_ROOT / ".codex-tmp" / "real-data-probes" / _slug(run_id)
    payload: dict[str, Any]
    try:
        production_services = production_services_from_environment(workspace_root=scratch_workspace)
        discover = production_services["discover_sources"]
        if hasattr(discover, "limit"):
            discover.limit = max(int(getattr(discover, "limit", 8) or 8), 9)
        run = run_live_research(topic=query, run_dir=scratch_workspace, discover=discover, retry_delays=(0.0, 1.0))
        source_pack = run.get("source_pack") if isinstance(run.get("source_pack"), dict) else {}
        source_count = int(source_pack.get("source_count") or 0)
        synthesis = run.get("technical_synthesis") if isinstance(run.get("technical_synthesis"), dict) else {}
        signal_types = [str(item) for item in synthesis.get("signal_types") or [] if str(item).strip()]
        trends = [item for item in synthesis.get("trends") or [] if isinstance(item, dict)]
        gaps = [item for item in synthesis.get("evidence_gaps") or [] if isinstance(item, dict)]
        payload = {
            "schema": "autosci_real_data_research_probe.v1",
            "status": "completed" if str(run.get("status") or "") == "PASS" else "environment_blocked",
            "topic": query,
            "run_dir": _rel(scratch_workspace),
            "source_count": source_count,
            "technical_synthesis_status": str(synthesis.get("status") or "missing"),
            "technical_synthesis_path": str(run.get("technical_synthesis_path") or ""),
            "source_pack_sources_path": str(source_pack.get("sources_path") or ""),
            "source_pack_evidence_path": str(source_pack.get("evidence_path") or ""),
            "research_report_path": str(run.get("report_path") or ""),
            "technical_signal_count": int(synthesis.get("signal_count") or 0),
            "technical_signal_types": signal_types,
            "cross_source_trends": trends,
            "evidence_gaps": gaps,
            "completed_nodes": list(run.get("completed_nodes") or (run.get("state") or {}).get("completed_nodes") or []),
            "report_path": str(run.get("report_path") or ""),
            "provider_trace": str(((run.get("provider_result") or {}) if isinstance(run.get("provider_result"), dict) else {}).get("trace") or ""),
            "assertions": [
                {"name": "provider_discovery_completed", "passed": str(run.get("status") or "") == "PASS"},
                {"name": "content_bearing_source_count_at_least_eight", "passed": source_count >= 8, "detail": {"source_count": source_count}},
                {
                    "name": "content_level_method_result_limitation_signals_present",
                    "passed": synthesis.get("status") == "completed"
                    and {"method", "result", "limitation"}.issubset(set(signal_types)),
                    "detail": {"signal_count": int(synthesis.get("signal_count") or 0), "signal_types": signal_types},
                },
                {
                    "name": "cross_source_trend_and_evidence_gap_present",
                    "passed": bool(trends)
                    and all(len(item.get("source_ids") or []) >= 2 for item in trends)
                    and bool(gaps),
                    "detail": {"trend_count": len(trends), "gap_count": len(gaps)},
                },
            ],
        }
    except Exception as exc:
        payload = {
            "schema": "autosci_real_data_research_probe.v1",
            "status": "failed",
            "topic": query,
            "run_dir": _rel(scratch_workspace),
            "source_count": 0,
            "failed_node": "real-data-research-probe",
            "error_type": type(exc).__name__,
            "error": str(exc),
            "assertions": [
                {"name": "provider_discovery_completed", "passed": False, "detail": {"error_type": type(exc).__name__}},
                {"name": "content_bearing_source_count_at_least_eight", "passed": False, "detail": {"source_count": 0}},
            ],
        }
    _write_json_sidecar(result_path, payload)
    return {"type": "real_data_research_probe_json", "path": _rel(result_path)}


def _research_lifecycle_stage_plan(start_stage: str, skip_paper: bool) -> list[dict[str, Any]]:
    stage_ids = [stage_id for stage_id, _ in RESEARCH_LIFECYCLE_STAGES]
    start_index = stage_ids.index(start_stage) if start_stage in stage_ids else 0
    plan: list[dict[str, Any]] = []
    for index, (stage_id, title) in enumerate(RESEARCH_LIFECYCLE_STAGES):
        if skip_paper and stage_id in {"paper-plan", "paper-compile"}:
            state = "skipped_by_request"
        elif index < start_index:
            state = "skipped_resume_boundary"
        elif index == start_index:
            state = "blocked_approval"
        else:
            state = "pending"
        plan.append({
            "stage_id": stage_id,
            "title": title,
            "state": state,
            "order": index + 1,
        })
    return plan


def _input_path_values(inputs: dict[str, Any], *keys: str) -> list[str]:
    native = inputs.get("native_options") if isinstance(inputs.get("native_options"), dict) else {}
    values: list[str] = []
    for source in (inputs, native):
        for key in keys:
            raw = source.get(key)
            if isinstance(raw, list):
                values.extend(str(item) for item in raw if str(item).strip())
            elif raw:
                values.append(str(raw))
    return _unique_strings(values)


def _load_json_evidence_paths(raw_paths: list[str]) -> tuple[list[dict[str, Any]], list[str], list[dict[str, str]]]:
    payloads: list[dict[str, Any]] = []
    errors: list[str] = []
    artifacts: list[dict[str, str]] = []
    for raw in raw_paths:
        path = _resolve_harness_path(raw)
        if not path.exists() or not path.is_file():
            errors.append(f"missing evidence: {raw}")
            continue
        artifacts.append({"type": "research_lifecycle_stage_evidence_json", "path": _rel(path)})
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc:
            errors.append(f"invalid evidence JSON: {_rel(path)}: {exc}")
            continue
        if isinstance(payload, dict):
            payload.setdefault("source_path", _rel(path))
            payloads.append(payload)
        else:
            errors.append(f"evidence JSON is not an object: {_rel(path)}")
    return payloads, errors, artifacts


def _evidence_status_completed(payload: dict[str, Any]) -> bool:
    return str(payload.get("status") or "").strip().lower() == "completed"


def _review_llm_evidence_completed(payloads: list[dict[str, Any]]) -> bool:
    for payload in payloads:
        if not _evidence_status_completed(payload):
            continue
        outputs = payload.get("outputs") if isinstance(payload.get("outputs"), dict) else {}
        review = outputs.get("review") if isinstance(outputs.get("review"), dict) else payload.get("review")
        if not isinstance(review, dict):
            review = {}
        review_llm = review.get("review_llm") if isinstance(review.get("review_llm"), dict) else {}
        final_boundary = outputs.get("final_acceptance_boundary") if isinstance(outputs.get("final_acceptance_boundary"), dict) else {}
        proof = review.get("proof_contract") if isinstance(review.get("proof_contract"), dict) else {}
        separation = proof.get("reviewer_separation") if isinstance(proof.get("reviewer_separation"), dict) else {}
        independence = separation.get("independence") if isinstance(separation.get("independence"), dict) else {}
        proof_ready = (
            final_boundary.get("final_acceptance_ready") is True
            or (
                proof.get("verdict") == "supported"
                and not list(proof.get("blockers") or [])
                and independence.get("status") == "independent_provider"
                and independence.get("execution_bound") is True
            )
        )
        if review and (
            str(review.get("review_mode") or "") == "review_llm"
            and review.get("review_available") is True
            and str(review_llm.get("status") or "completed") == "completed"
            and proof_ready
        ):
            return True
        evaluations = outputs.get("evaluations") if isinstance(outputs.get("evaluations"), list) else []
        for evaluation in evaluations:
            if not isinstance(evaluation, dict):
                continue
            evaluation_review = evaluation.get("review_llm") if isinstance(evaluation.get("review_llm"), dict) else {}
            evaluation_boundary = evaluation.get("final_acceptance_boundary") if isinstance(evaluation.get("final_acceptance_boundary"), dict) else {}
            if (
                str(evaluation.get("review_mode") or "") == "review_llm"
                and evaluation.get("review_available") is True
                and str(evaluation_review.get("status") or "") == "completed"
                and evaluation_boundary.get("final_acceptance_ready") is True
            ):
                return True
    return False


def _external_novelty_evidence_completed(payloads: list[dict[str, Any]]) -> bool:
    for payload in payloads:
        if not _evidence_status_completed(payload):
            continue
        outputs = payload.get("outputs") if isinstance(payload.get("outputs"), dict) else {}
        if str(payload.get("schema") or "") in {"external_novelty.v1", "external_novelty_sources.v1", "literature_discovery.v1"}:
            sources = outputs.get("sources") if isinstance(outputs.get("sources"), list) else outputs.get("candidates")
            sources = sources if isinstance(sources, list) else []
            source_ids = _unique_strings(
                [
                    str(item.get("source_id") or item.get("id") or item.get("candidate_id") or item.get("paperId") or item.get("url") or "")
                    for item in sources
                    if isinstance(item, dict)
                ]
            )
            if len(source_ids) >= 2:
                return True
        evaluation = outputs.get("evaluation") if isinstance(outputs.get("evaluation"), dict) else {}
        external = evaluation.get("external_novelty") if isinstance(evaluation.get("external_novelty"), dict) else {}
        boundary = evaluation.get("final_acceptance_boundary") if isinstance(evaluation.get("final_acceptance_boundary"), dict) else {}
        if str(external.get("status") or "") == "completed" and boundary.get("final_acceptance_ready") is True:
            return True
        evaluations = outputs.get("evaluations") if isinstance(outputs.get("evaluations"), list) else []
        for evaluation_item in evaluations:
            if not isinstance(evaluation_item, dict):
                continue
            external_item = (
                evaluation_item.get("external_novelty")
                if isinstance(evaluation_item.get("external_novelty"), dict)
                else {}
            )
            item_boundary = evaluation_item.get("final_acceptance_boundary") if isinstance(evaluation_item.get("final_acceptance_boundary"), dict) else {}
            if str(external_item.get("status") or "") == "completed" and item_boundary.get("final_acceptance_ready") is True:
                return True
    return False


def _discovery_evidence_completed(payloads: list[dict[str, Any]]) -> bool:
    return any(
        _evidence_status_completed(payload)
        and str(payload.get("schema") or "") == "literature_discovery.v1"
        and bool((payload.get("outputs") if isinstance(payload.get("outputs"), dict) else {}).get("candidates"))
        for payload in payloads
    )


SCHEDULER_FULL_LIFECYCLE_NODE_IDS = {
    "literature_discover",
    "paper_ingest",
    "paper_analyze",
    "memory_update_initial",
    "graph_update",
    "claim_extract",
    "method_extract",
    "code_evidence_map",
    "idea_generate",
    "idea_evaluate",
    "experiment_design",
    "experiment_run",
    "experiment_monitor",
    "claim_verify",
    "report_draft",
    "artifact_review",
    "memory_update_final",
    "workflow_evolve",
    "report_plan",
    "publication_produce",
}


def _scheduler_lifecycle_summary(payloads: list[dict[str, Any]]) -> dict[str, Any]:
    for payload in payloads:
        if str(payload.get("schema") or "") != "scientific_lifecycle.v1":
            continue
        if str(payload.get("lifecycle_status") or "").lower() != "passed":
            continue
        source_path_raw = str(payload.get("source_path") or "").strip()
        source_path = _resolve_harness_path(source_path_raw) if source_path_raw else None
        runtime_gate = evaluate_lifecycle_runtime(
            payload,
            path=source_path if source_path and source_path.exists() else None,
        ).to_dict()
        if runtime_gate.get("ok") is not True:
            continue
        alignment = (
            payload.get("workflow_config_alignment")
            if isinstance(payload.get("workflow_config_alignment"), dict)
            else {}
        )
        if alignment.get("ok") is not True or str(alignment.get("status") or "") != "aligned":
            continue
        blocked = payload.get("blocked_nodes")
        if isinstance(blocked, dict) and blocked:
            continue
        node_results = payload.get("node_results") if isinstance(payload.get("node_results"), dict) else {}
        present_nodes = {str(node_id) for node_id in node_results}
        missing = sorted(SCHEDULER_FULL_LIFECYCLE_NODE_IDS - present_nodes)
        if missing:
            continue
        if any(
            str((node_results.get(node_id) or {}).get("status") or "").lower() != "passed"
            for node_id in SCHEDULER_FULL_LIFECYCLE_NODE_IDS
        ):
            continue
        return {
            "schema": "scientific_lifecycle.v1",
            "status": "completed",
            "job_id": str(payload.get("job_id") or payload.get("sprint_id") or ""),
            "workflow_id": str(payload.get("workflow_id") or ""),
            "source_path": str(payload.get("source_path") or ""),
            "node_count": len(node_results),
            "required_node_count": len(SCHEDULER_FULL_LIFECYCLE_NODE_IDS),
            "lifecycle_runtime_gate_status": str(runtime_gate.get("status") or ""),
            "workflow_config_alignment_status": str(alignment.get("status") or ""),
        }
    return {}


def _wiki_entity_counts(envelope: dict[str, Any]) -> dict[str, int]:
    counts = {"papers": 0, "ideas": 0, "experiments": 0, "outputs": 0, "compiled_pdfs": 0, "latex_sources": 0}
    for root in _wiki_roots_for_read(envelope):
        if not root.exists():
            continue
        for key in ("papers", "ideas", "experiments", "outputs"):
            folder = root / key
            if folder.exists():
                counts[key] += len([path for path in folder.glob("*.md") if path.is_file()])
        parent = root.parent
        paper_dir = parent / "paper"
        if paper_dir.exists():
            counts["compiled_pdfs"] += len([path for path in paper_dir.rglob("*.pdf") if path.is_file()])
            counts["latex_sources"] += len([path for path in paper_dir.rglob("*.tex") if path.is_file()])
    return counts


def _runtime_pdf_paths(contract: dict[str, Any]) -> list[Path]:
    records, _errors = _runtime_records(contract)
    paths: list[Path] = []
    for record in records:
        raw = _field(record, "pdf_path", "output_pdf", "compiled_pdf")
        values = raw if isinstance(raw, list) else ([raw] if raw else [])
        for value in values:
            if not isinstance(value, str) or not value.strip():
                continue
            path = _resolve_harness_path(value)
            if path.exists() and path.is_file():
                paths.append(path)
    return paths


def _runtime_pdf_artifacts(contract: dict[str, Any]) -> list[dict[str, str]]:
    return [{"type": "compiled_pdf", "path": _rel(path)} for path in _runtime_pdf_paths(contract)]


def _materialize_research_pipeline_pdf(
    envelope: dict[str, Any],
    contract: dict[str, Any],
    compile_semantic: dict[str, Any],
) -> dict[str, Any]:
    if not contract.get("execution_verified") or not compile_semantic.get("verified"):
        return {"status": "not_materialized", "reason": "compile runtime or approval contract is not verified"}
    sources = _runtime_pdf_paths(contract)
    if not sources:
        return {"status": "missing", "reason": "no verified runtime PDF path was available"}
    workspace_root = _wiki_roots_for_write(envelope)[0].parent
    target = workspace_root / "paper" / "main.pdf"
    target.parent.mkdir(parents=True, exist_ok=True)
    source = sources[0]
    try:
        if source.resolve() != target.resolve():
            shutil.copyfile(source, target)
    except OSError as exc:
        return {"status": "failed", "reason": str(exc), "source_path": _rel(source), "target_path": _rel(target)}
    return {
        "status": "completed",
        "source_path": _rel(source),
        "target_path": _rel(target),
        "artifact": {"type": "integrated_paper_pdf", "path": _rel(target)},
    }


def _research_lifecycle_evidence_report(envelope: dict[str, Any], contract: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    paper_raw = str(inputs.get("paper_path") or "").strip()
    paper_path = _resolve_harness_path(paper_raw) if paper_raw else None
    discovery_payloads, discovery_errors, discovery_artifacts = _load_json_evidence_paths(
        _input_path_values(inputs, "discovery_evidence", "literature_evidence")
    )
    novelty_payloads, novelty_errors, novelty_artifacts = _load_json_evidence_paths(
        _input_path_values(inputs, "novelty_evidence", "external_novelty_evidence")
    )
    review_payloads, review_errors, review_artifacts = _load_json_evidence_paths(
        _input_path_values(inputs, "review_llm_evidence", "review_evidence")
    )
    lifecycle_payloads, lifecycle_errors, lifecycle_artifacts = _load_json_evidence_paths(
        _input_path_values(inputs, "lifecycle_summary", "lifecycle_summary_path", "scientific_lifecycle_evidence")
    )
    scheduler_lifecycle = _scheduler_lifecycle_summary(lifecycle_payloads)
    wiki_counts = _wiki_entity_counts(envelope)
    experiment_semantic = _approval_semantic_runtime(contract, "run_experiment")
    compile_semantic = _approval_semantic_runtime(contract, "compile_paper")
    integrated_pdf = _materialize_research_pipeline_pdf(envelope, contract, compile_semantic)
    paper_exists = bool(paper_path and paper_path.exists())
    report = {
        "paper_path": _rel(paper_path) if paper_path and paper_path.exists() else paper_raw,
        "paper_exists": paper_exists,
        "wiki_counts": wiki_counts,
        "discovery_completed": _discovery_evidence_completed(discovery_payloads),
        "external_novelty_completed": _external_novelty_evidence_completed(novelty_payloads),
        "review_llm_completed": _review_llm_evidence_completed(review_payloads),
        "scheduler_lifecycle_completed": bool(scheduler_lifecycle),
        "scheduler_lifecycle": scheduler_lifecycle,
        "experiment_runtime": experiment_semantic,
        "compile_runtime": compile_semantic,
        "integrated_pdf": integrated_pdf,
        "errors": [*discovery_errors, *novelty_errors, *review_errors, *lifecycle_errors],
        "artifacts": [
            *discovery_artifacts,
            *novelty_artifacts,
            *review_artifacts,
            *lifecycle_artifacts,
            *_contract_existing_artifacts(contract, "runtime_evidence", "research_lifecycle_runtime_evidence_json"),
            *_contract_existing_artifacts(contract, "before_artifacts", "research_lifecycle_before_artifact"),
            *_contract_existing_artifacts(contract, "after_artifacts", "research_lifecycle_after_artifact"),
            *_runtime_pdf_artifacts(contract),
            *([integrated_pdf["artifact"]] if isinstance(integrated_pdf.get("artifact"), dict) else []),
        ],
    }
    report["discovery_evidence_refs"] = _artifact_ref_paths(discovery_artifacts)
    report["novelty_evidence_refs"] = _artifact_ref_paths(novelty_artifacts)
    report["review_llm_evidence_refs"] = _artifact_ref_paths(review_artifacts)
    report["runtime_evidence_refs"] = _artifact_ref_paths(
        _contract_existing_artifacts(contract, "runtime_evidence", "research_lifecycle_runtime_evidence_json")
    )
    report["approval_evidence_refs"] = _unique_strings(_approval_contract_runtime_refs(contract))
    report["has_stage_evidence"] = any(
        [
            paper_exists,
            any(wiki_counts.values()),
            report["discovery_completed"],
            report["external_novelty_completed"],
            report["review_llm_completed"],
            report["scheduler_lifecycle_completed"],
            experiment_semantic.get("verified"),
            compile_semantic.get("verified"),
            integrated_pdf.get("status") == "completed",
        ]
    )
    return report


def _research_lifecycle_verified_stage_plan(
    start_stage: str,
    skip_paper: bool,
    evidence: dict[str, Any],
    contract: dict[str, Any],
) -> tuple[list[dict[str, Any]], list[dict[str, str]]]:
    stage_ids = [stage_id for stage_id, _ in RESEARCH_LIFECYCLE_STAGES]
    start_index = stage_ids.index(start_stage) if start_stage in stage_ids else 0
    wiki_counts = evidence.get("wiki_counts") if isinstance(evidence.get("wiki_counts"), dict) else {}
    experiment_runtime = evidence.get("experiment_runtime") if isinstance(evidence.get("experiment_runtime"), dict) else {}
    compile_runtime = evidence.get("compile_runtime") if isinstance(evidence.get("compile_runtime"), dict) else {}
    scheduler_lifecycle_completed = bool(evidence.get("scheduler_lifecycle_completed"))
    checks = {
        "setup": scheduler_lifecycle_completed or bool(contract.get("approved")),
        "ingest": scheduler_lifecycle_completed or bool(evidence.get("paper_exists") or int(wiki_counts.get("papers") or 0) > 0),
        "discover": scheduler_lifecycle_completed or bool(evidence.get("discovery_completed")),
        "ideate": scheduler_lifecycle_completed or int(wiki_counts.get("ideas") or 0) > 0,
        "novelty-review": scheduler_lifecycle_completed
        or bool(evidence.get("external_novelty_completed") and evidence.get("review_llm_completed")),
        "experiment-design": scheduler_lifecycle_completed or int(wiki_counts.get("experiments") or 0) > 0,
        "experiment-run": scheduler_lifecycle_completed or bool(experiment_runtime.get("verified")),
        "collect": scheduler_lifecycle_completed or bool((experiment_runtime.get("detail") or {}).get("result_collected")),
        "review": scheduler_lifecycle_completed or bool(evidence.get("review_llm_completed")),
        "paper-plan": scheduler_lifecycle_completed
        or bool(int(wiki_counts.get("outputs") or 0) > 0 or int(wiki_counts.get("latex_sources") or 0) > 0),
        "paper-compile": scheduler_lifecycle_completed or bool(
            (isinstance(evidence.get("integrated_pdf"), dict) and evidence["integrated_pdf"].get("status") == "completed")
            or compile_runtime.get("verified")
            or int(wiki_counts.get("compiled_pdfs") or 0) > 0
        ),
    }
    missing: list[dict[str, str]] = []
    plan: list[dict[str, Any]] = []
    for index, (stage_id, title) in enumerate(RESEARCH_LIFECYCLE_STAGES):
        if skip_paper and stage_id in {"paper-plan", "paper-compile"}:
            state = "skipped_by_request"
        elif index < start_index:
            state = "skipped_resume_boundary"
        elif checks.get(stage_id):
            state = "completed"
        else:
            state = "pending_evidence"
            missing.append({"stage": stage_id, "reason": f"Required evidence for {stage_id} is missing or incomplete."})
        plan.append({"stage_id": stage_id, "title": title, "state": state, "order": index + 1})
    return plan, missing


def _research_lifecycle_markdown(raw: dict[str, Any], *, report: bool = False) -> str:
    pipeline = raw["pipeline"]
    stage_plan = raw["stage_plan"]
    lines = [
        "# AutoSci Research Pipeline Report" if report else "# AutoSci Research Pipeline Progress",
        "",
        f"Target: `{pipeline['target']}`",
        f"Pipeline: `{pipeline['pipeline_id']}`",
        f"Resume from: `{pipeline['resume_from']}`",
        f"Venue: `{pipeline['venue']}`",
        f"Skip paper: `{pipeline['skip_paper']}`",
        "",
        "## Stage State",
        "",
        "| Order | Stage | State |",
        "| ---: | --- | --- |",
    ]
    for stage in stage_plan:
        lines.append(f"| {stage['order']} | `{stage['stage_id']}` | `{stage['state']}` |")
    lines.extend([
        "",
        "## Gate State",
        "",
        "- Execution state: gated",
        "- Side effects executed: false",
        "- Workspace mutation outside generated pipeline artifacts: false",
        "- Required before full parity: Review LLM evidence, online discovery evidence, experiment runtime evidence, collection evidence, and LaTeX/PDF compile evidence.",
        "",
    ])
    evidence = raw.get("evidence_report") if isinstance(raw.get("evidence_report"), dict) else {}
    if evidence:
        lines.extend([
            "## Evidence Summary",
            "",
            f"- Paper exists: `{evidence.get('paper_exists', 'N/A')}`",
            f"- Discovery completed: `{evidence.get('discovery_completed', 'N/A')}`",
            f"- External novelty completed: `{evidence.get('external_novelty_completed', 'N/A')}`",
            f"- Review LLM completed: `{evidence.get('review_llm_completed', 'N/A')}`",
            f"- Scheduler lifecycle completed: `{evidence.get('scheduler_lifecycle_completed', 'N/A')}`",
            f"- Experiment runtime verified: `{(evidence.get('experiment_runtime') or {}).get('verified', 'N/A')}`",
            f"- Compile runtime verified: `{(evidence.get('compile_runtime') or {}).get('verified', 'N/A')}`",
            f"- Integrated PDF: `{(evidence.get('integrated_pdf') or {}).get('target_path', (evidence.get('integrated_pdf') or {}).get('status', 'N/A'))}`",
            "",
        ])
    if report:
        lines.extend([
            "## Resume Notes",
            "",
            "- The next executable stage is recorded, but no native stage runner was launched.",
            "- This report is intended for parity auditing and resume planning, not as research outcome evidence.",
            "",
        ])
    return "\n".join(lines).rstrip() + "\n"


def _artifact_ref_paths(artifacts: list[dict[str, Any]]) -> list[str]:
    return _unique_strings(
        [str(artifact.get("path") or "").strip() for artifact in artifacts if isinstance(artifact, dict)]
    )


def _artifact_refs_by_type(artifacts: list[dict[str, Any]], types: set[str]) -> list[str]:
    return _unique_strings(
        [
            str(artifact.get("path") or "").strip()
            for artifact in artifacts
            if isinstance(artifact, dict) and str(artifact.get("type") or "") in types
        ]
    )


def _research_lifecycle_write_runtime_proof(
    envelope: dict[str, Any],
    *,
    filename: str,
    artifact_type: str,
    proof: dict[str, Any],
) -> dict[str, str]:
    timestamp = str(proof.get("generated_at") or datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z"))
    manifest = {
        "schema": "autosci_runtime_proof_manifest.v1",
        "generated_at": timestamp,
        "proofs": [proof],
    }
    artifact_path = _write_json_sidecar(_output_dir(envelope, "run_research_lifecycle") / filename, manifest)
    return {"type": artifact_type, "path": artifact_path}


def _write_research_lifecycle_runtime_proof_manifests(
    envelope: dict[str, Any],
    *,
    evidence_path: Path,
    raw: dict[str, Any],
    contract: dict[str, Any],
    contract_artifact: dict[str, str],
) -> list[dict[str, str]]:
    evidence_report = raw.get("evidence_report") if isinstance(raw.get("evidence_report"), dict) else {}
    artifacts = raw.get("artifacts") if isinstance(raw.get("artifacts"), list) else []
    timestamp = datetime.now(UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    proof_stamp = timestamp.replace(":", "").replace("-", "")
    pipeline_refs = _artifact_refs_by_type(
        artifacts,
        {
            "pipeline_progress_markdown",
            "pipeline_report_markdown",
            "pipeline_state_json",
            "recommended_changes_markdown",
        },
    )
    proof_artifacts: list[dict[str, str]] = []

    source_refs: list[str | Path] = [evidence_path, *pipeline_refs]
    source_kinds: list[str] = []
    if evidence_report.get("discovery_completed"):
        source_refs.extend(str(item) for item in evidence_report.get("discovery_evidence_refs") or [])
        source_kinds.append("literature_discovery")
    if evidence_report.get("external_novelty_completed"):
        source_refs.extend(str(item) for item in evidence_report.get("novelty_evidence_refs") or [])
        source_kinds.append("external_novelty")
    paper_path = str(evidence_report.get("paper_path") or "").strip()
    if evidence_report.get("paper_exists") and paper_path:
        source_refs.append(paper_path)
        source_kinds.append("paper_source")
    source_refs_normalized = _runtime_evidence_refs(*source_refs)
    if len(source_refs_normalized) > len(_runtime_evidence_refs(evidence_path, *pipeline_refs)):
        source = "+".join(_unique_strings(source_kinds)) or "research_lifecycle_sources"
        proof_artifacts.append(
            _research_lifecycle_write_runtime_proof(
                envelope,
                filename="run_research_lifecycle_source_provider_runtime_proof.json",
                artifact_type="provider_source_runtime_proof_manifest_json",
                proof={
                    "native_skill": "research",
                    "proof_id": f"runtime:research:{_slug(source)}:{proof_stamp}",
                    "categories": ["provider_source_evidence"],
                    "collection_mode": "manual_review",
                    "production_ready": True,
                    "generated_at": timestamp,
                    "provenance": {
                        "source": source,
                        "captured_at": timestamp,
                        "artifact_kind": "research_lifecycle_source_evidence",
                        "command": "run_research_lifecycle:source_evidence_report",
                    },
                    "evidence_refs": source_refs_normalized,
                    "description": "Completed source evidence for AutoSci `research` lifecycle parity.",
                },
            )
        )

    review_refs = _runtime_evidence_refs(
        evidence_path,
        *pipeline_refs,
        *[str(item) for item in evidence_report.get("review_llm_evidence_refs") or []],
    )
    if evidence_report.get("review_llm_completed") and len(review_refs) > len(_runtime_evidence_refs(evidence_path, *pipeline_refs)):
        proof_artifacts.append(
            _research_lifecycle_write_runtime_proof(
                envelope,
                filename="run_research_lifecycle_review_llm_runtime_proof.json",
                artifact_type="review_model_runtime_proof_manifest_json",
                proof={
                    "native_skill": "research",
                    "proof_id": f"runtime:research:review-llm:{proof_stamp}",
                    "categories": ["review_llm_or_model_evidence", "external_runtime_evidence"],
                    "collection_mode": "manual_review",
                    "production_ready": True,
                    "generated_at": timestamp,
                    "provenance": {
                        "source": "review_llm",
                        "captured_at": timestamp,
                        "artifact_kind": "research_lifecycle_review_evidence",
                        "command": "run_research_lifecycle:review_llm_evidence_report",
                    },
                    "evidence_refs": review_refs,
                    "description": "Completed Review LLM evidence for AutoSci `research` lifecycle parity.",
                },
            )
        )

    experiment_runtime = evidence_report.get("experiment_runtime") if isinstance(evidence_report.get("experiment_runtime"), dict) else {}
    compile_runtime = evidence_report.get("compile_runtime") if isinstance(evidence_report.get("compile_runtime"), dict) else {}
    runtime_verified = bool(experiment_runtime.get("verified") or compile_runtime.get("verified"))
    contract_path = str(contract_artifact.get("path") or "").strip() if isinstance(contract_artifact, dict) else ""
    runtime_refs = _runtime_evidence_refs(
        evidence_path,
        *pipeline_refs,
        contract_path,
        *[str(item) for item in evidence_report.get("runtime_evidence_refs") or []],
        *[str(item) for item in evidence_report.get("approval_evidence_refs") or []],
    )
    if contract.get("execution_verified") is True and runtime_verified and contract_path:
        proof_artifacts.append(
            _research_lifecycle_write_runtime_proof(
                envelope,
                filename="run_research_lifecycle_approval_runtime_proof.json",
                artifact_type="approval_runtime_proof_manifest_json",
                proof={
                    "native_skill": "research",
                    "proof_id": f"runtime:research:approved-runtime:{proof_stamp}",
                    "categories": ["external_runtime_evidence", "approval_boundary_evidence"],
                    "collection_mode": "approved_side_effect",
                    "production_ready": True,
                    "generated_at": timestamp,
                    "provenance": {
                        "source": "approval_contract",
                        "captured_at": timestamp,
                        "artifact_kind": "research_lifecycle_approved_runtime",
                        "command": "run_research_lifecycle:approval_runtime_evidence_report",
                    },
                    "evidence_refs": runtime_refs,
                    "description": "Verified approval/runtime evidence for AutoSci `research` lifecycle parity.",
                },
            )
        )

    return proof_artifacts


def _research_lifecycle_raw(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    target_raw = str(inputs.get("target") or "").strip()
    topic_raw = str(inputs.get("topic") or inputs.get("prompt") or "").strip()
    target = topic_raw if target_raw.lower() == "skillgen research lifecycle" and topic_raw else (target_raw or topic_raw or "autosci research lifecycle")
    pipeline_id = str(inputs.get("pipeline") or _slug(target))
    start_raw = str(inputs.get("start_from") or "setup")
    start_stage = _research_stage_from_token(start_raw)
    skip_paper = bool(inputs.get("skip_paper"))
    venue = str(inputs.get("venue") or "N/A")
    paths = _research_lifecycle_paths(envelope)
    paths["patch_candidates"].mkdir(parents=True, exist_ok=True)
    contract = _approval_contract(
        envelope,
        "run_research_lifecycle",
        [
            "multi_step_execution",
            "network_fetch",
            "workspace_mutation",
            "experiment_deploy",
            "paper_compile",
        ],
    )
    research_side_effects = [
        "read_local",
        "write_artifact",
        "network_fetch",
        "local_command",
        "wiki_mutation",
        "remote_execution",
        "tex_compile",
    ]
    contract, policy_decision, policy_artifacts = _policy_prepare_auto_contract(
        envelope,
        "run_research_lifecycle",
        research_side_effects,
        contract,
        allowlist_payload={
            "native_pipeline": "research_lifecycle",
            "resume_from": start_stage,
            "limitations": [
                "Policy approval allows stage runner side effects only within the configured gate mode.",
                "Each lifecycle stage still requires typed runtime evidence before completion is claimed.",
            ],
        },
    )
    contract_artifact = _write_approval_contract_sidecar(envelope, "run_research_lifecycle", contract)
    side_effect_access_payload: dict[str, Any] | None = None
    side_effect_access_artifact: dict[str, str] | None = None
    side_effect_access_required_by_policy = _side_effect_access_required(policy_decision)
    contract_missing = contract.get("missing") if isinstance(contract.get("missing"), list) else []
    evidence_report = _research_lifecycle_evidence_report(envelope, contract)
    evidence_mode = bool(evidence_report.get("has_stage_evidence") or contract.get("approved"))
    if evidence_mode:
        stage_plan, missing_stages = _research_lifecycle_verified_stage_plan(start_stage, skip_paper, evidence_report, contract)
        current = next((stage for stage in stage_plan if stage["state"] == "pending_evidence"), {"stage_id": "completed"})
        if current["stage_id"] == "completed" and evidence_report.get("errors"):
            current = {"stage_id": "evidence-verification"}
    else:
        stage_plan = _research_lifecycle_stage_plan(start_stage, skip_paper)
        missing_stages = [
            {
                "stage": str(next((stage for stage in stage_plan if stage["state"] == "blocked_approval"), stage_plan[0])["stage_id"]),
                "reason": "Native research lifecycle execution was not launched without approval/runtime evidence.",
            }
        ]
        current = next((stage for stage in stage_plan if stage["state"] == "blocked_approval"), stage_plan[0])
    supplied_evidence_completed = evidence_mode and not missing_stages and not evidence_report.get("errors")
    side_effect_access_blocked = (
        side_effect_access_required_by_policy
        and contract.get("execution_verified") is not True
        and not supplied_evidence_completed
    )
    if side_effect_access_blocked:
        side_effect_access_payload, side_effect_access_artifact = _side_effect_access_request(
            envelope,
            "run_research_lifecycle",
            "research",
            policy_decision,
            requested_side_effects=research_side_effects,
            required_inputs=[
                "approved source discovery/network fetch evidence",
                "approved experiment deployment/runtime evidence",
                "approved paper compile evidence",
                "wiki mutation proof for lifecycle state updates",
            ],
        )
    pipeline_completed = (
        not side_effect_access_blocked
        and evidence_mode
        and not missing_stages
        and not evidence_report.get("errors")
    )
    experiment_runtime = evidence_report.get("experiment_runtime") if isinstance(evidence_report.get("experiment_runtime"), dict) else {}
    compile_runtime = evidence_report.get("compile_runtime") if isinstance(evidence_report.get("compile_runtime"), dict) else {}
    runtime_evidence_ids = _unique_strings(
        [
            *[str(item) for item in (experiment_runtime.get("detail") or {}).get("evidence_ids", [])],
            *[str(item) for item in (compile_runtime.get("detail") or {}).get("evidence_ids", [])],
        ]
    )
    pipeline = {
        "pipeline_id": pipeline_id,
        "target": target,
        "resume_from": start_stage,
        "requested_start_from": start_raw,
        "venue": venue,
        "skip_paper": skip_paper,
        "auto": bool(inputs.get("auto")),
        "status": SIDE_EFFECT_ACCESS_REQUIRED_STATUS
        if side_effect_access_blocked
        else ("completed" if pipeline_completed else ("pending_evidence" if evidence_mode else "gated")),
    }
    evidence_ids = [
        f"research-lifecycle:{_slug(pipeline_id)}",
        f"pipeline-progress:{_slug(target)}",
        f"pipeline-report:{_slug(target)}",
        *runtime_evidence_ids,
    ]
    gate_reasons = [
        {
            "gate_id": "research_lifecycle_evidence_gate",
            "status": "passed" if pipeline_completed else "blocked",
            "reasons": ["All required research lifecycle stage evidence was verified."]
            if pipeline_completed
            else [
                *(
                    ["Side-effect access is required before native lifecycle stage runners can execute."]
                    if side_effect_access_blocked
                    else []
                ),
                "Native research lifecycle execution is incomplete until every required stage has verified evidence.",
                *[f"{item['stage']}: {item['reason']}" for item in missing_stages],
                *[f"evidence_error: {item}" for item in evidence_report.get("errors", [])],
                f"Approval contract missing: {', '.join(str(item) for item in contract_missing) if contract_missing else 'N/A'}",
            ],
        }
    ]
    blocked_nodes = [
        {
            "node_id": f"stage-{item['stage']}",
            "logical_operator": "ScientificWorkflowEvolver",
            "status": "blocked",
            "gate": "research_lifecycle_evidence_gate",
            "stage": item["stage"],
        }
        for item in missing_stages
    ] or [
        {
            "node_id": "research-lifecycle-evidence-errors",
            "logical_operator": "ScientificWorkflowEvolver",
            "status": "blocked",
            "gate": "research_lifecycle_evidence_gate",
            "stage": "evidence-verification",
        }
    ]
    failed_nodes = [
        {
            "node_id": "research-lifecycle-completed",
            "logical_operator": "ScientificWorkflowEvolver",
            "status": "completed",
            "gate": "research_lifecycle_evidence_gate",
            "stage": "completed",
        }
    ] if pipeline_completed else blocked_nodes
    collected = {
        "failed_nodes": failed_nodes,
        "gate_rejection_reasons": gate_reasons,
        "ambiguous_manuals_or_prompts": [
            {
                "id": "research.lifecycle.resume",
                "description": "Record the user-approved resume stage and exact stage runner before executing a native pipeline.",
            }
        ],
        "insufficient_schemas": [],
        "poor_operator_bindings": [],
        "human_intervention_points": [
            {
                "id": "research.lifecycle.approval",
                "description": "Human approval is required before network fetch, experiment deployment, workspace mutation, or paper compilation.",
            },
            *(
                [
                    {
                        "id": "research.lifecycle.side_effect_access",
                        "description": "The current AutoSci gate mode blocked required native lifecycle side effects; grant access or provide typed runtime evidence.",
                    }
                ]
                if side_effect_access_blocked
                else []
            ),
        ],
        "runtime_errors": [
            *(
                [
                    {
                        "id": "side-effect-access-required",
                        "description": "Native research lifecycle side effects were not executed because the gate policy requires access approval.",
                    }
                ]
                if side_effect_access_blocked
                else []
            ),
            *[
                {"id": f"research.lifecycle.evidence-error-{index + 1}", "description": str(error)}
                for index, error in enumerate(evidence_report.get("errors", []))
            ],
            *(
                []
                if evidence_mode
                else [
                    {
                        "id": "native-stage-runner-not-executed",
                        "description": "No native AutoSci stage runner evidence was supplied for this gated lifecycle request.",
                    }
                ]
            ),
        ],
    }
    proposed_changes = [
        {
            "change_id": "change.manual.research-lifecycle-resume",
            "category": "manual",
            "target": "research lifecycle resume protocol",
            "description": "Persist target, resume stage, venue, and skip-paper intent before executing native lifecycle stages.",
            "evidence_ids": evidence_ids,
            "review_required": True,
            "application_state": "proposed_only",
        },
        {
            "change_id": "change.gate.research-lifecycle-required-evidence",
            "category": "gate",
            "target": "research lifecycle gate",
            "description": "Require online evidence, Review LLM, experiment runtime, collection, and compile artifacts before marking the lifecycle complete.",
            "evidence_ids": evidence_ids,
            "review_required": True,
            "application_state": "proposed_only",
        },
        {
            "change_id": "change.workflow.research-lifecycle-stage-artifacts",
            "category": "workflow_template",
            "target": "wiki/outputs pipeline artifacts",
            "description": "Write pipeline progress, state, and report artifacts so resume and audit checks no longer depend on route-only evidence.",
            "evidence_ids": evidence_ids,
            "review_required": True,
            "application_state": "proposed_only",
        },
    ]
    raw = {
        "proposal_id": f"run-research-lifecycle-{_slug(pipeline_id)}",
        "scope": "scientific research lifecycle",
        "change_type": "workflow_template",
        "rationale": "A native research lifecycle request needs stage-resumable wiki-first state before protected side effects can run.",
        "expected_effect": "Expose auditable pipeline progress and required full-parity evidence without pretending the lifecycle executed.",
        "approval_state": "approved" if pipeline_completed else "proposed",
        "approval_ref": str(contract.get("approval_ref") or ""),
        "evidence_ids": evidence_ids,
        "pipeline": pipeline,
        "stage_plan": stage_plan,
        "current_stage": current["stage_id"],
        "resume_from": start_stage,
        "evidence_report": evidence_report,
        "collected": collected,
        "proposed_changes": proposed_changes,
        "review": {
            "human_accept_reject_required": True,
            "protected_core_edits_applied": False,
            "application_state": "not_applied" if pipeline_completed else "proposed_only",
            "approval_ref": str(contract.get("approval_ref") or "N/A"),
            "approval_contract_path": contract_artifact["path"],
            "approval_contract_verified": bool(contract.get("execution_verified")),
        },
        "recommended_changes_path": _rel(paths["recommended_changes"]),
        "patch_candidates_path": _rel(paths["patch_candidates"]),
        "artifacts": [
            _artifact("recommended_changes_markdown", paths["recommended_changes"]),
            _artifact("patch_candidates_directory", paths["patch_candidates"]),
            contract_artifact,
            *policy_artifacts,
            *([side_effect_access_artifact] if side_effect_access_artifact is not None else []),
            _artifact("pipeline_progress_markdown", paths["pipeline_progress"]),
            _artifact("pipeline_report_markdown", paths["pipeline_report"]),
            _artifact("pipeline_state_json", paths["pipeline_state"]),
            *list(evidence_report.get("artifacts") or []),
        ],
        "status": "completed" if pipeline_completed else "inconclusive",
        "limitations": (
            [
                "Research lifecycle completion was verified from supplied wiki/source, Review LLM, runtime, and compile evidence.",
                "This action records integrated lifecycle state; protected side effects must still be executed only through approved stage runners.",
            ]
            if pipeline_completed
            else [
                "Research lifecycle native side effects require explicit access before stage runners can execute.",
                *_approval_contract_limitations(contract),
            ]
            if side_effect_access_blocked
            else [
                "Pipeline progress/report artifacts were generated, but one or more native research lifecycle stages still lack verified evidence.",
                "Full parity remains blocked until real online evidence, Review LLM evidence, experiment runtime, collection, and paper compile artifacts are attached.",
                *_approval_contract_limitations(contract),
            ]
        ),
    }
    state = {
        "schema": "autosci_research_pipeline_state.v1",
        "generated_at": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
        "pipeline": pipeline,
        "stage_plan": stage_plan,
        "current_stage": current["stage_id"],
        "approval_contract": contract,
        "evidence_report": evidence_report,
        "policy_decision": policy_decision,
        "side_effect_access_request": side_effect_access_payload,
    }
    _write_text_sidecar(paths["recommended_changes"], _research_lifecycle_markdown(raw, report=True))
    _write_text_sidecar(paths["pipeline_progress"], _research_lifecycle_markdown(raw))
    _write_text_sidecar(paths["pipeline_report"], _research_lifecycle_markdown(raw, report=True))
    _write_json_sidecar(paths["pipeline_state"], state)
    evidence_payload_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        _output_dir(envelope, "run_research_lifecycle") / "run_research_lifecycle.evidence.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    real_data_probe_artifact = _research_lifecycle_real_data_probe_artifact(
        envelope,
        target=target,
        evidence_payload_path=evidence_payload_path,
    )
    if real_data_probe_artifact is not None:
        raw["artifacts"].append(real_data_probe_artifact)
    raw["artifacts"].extend(
        _write_research_lifecycle_runtime_proof_manifests(
            envelope,
            evidence_path=evidence_payload_path,
            raw=raw,
            contract=contract,
            contract_artifact=contract_artifact,
        )
    )
    raw["policy_decision"] = policy_decision
    if side_effect_access_payload is not None and side_effect_access_artifact is not None:
        raw["side_effect_access_request"] = side_effect_access_payload
        raw["side_effect_access_artifact"] = side_effect_access_artifact
    return raw


def _action_setup_status(envelope: dict[str, Any]) -> dict[str, Any]:
    raw = _setup_status_raw(envelope)
    evidence = convert_workflow_evolution(raw, envelope)
    if isinstance(raw.get("policy_decision"), dict):
        evidence = _attach_policy_decision(evidence, raw["policy_decision"])
    return evidence


def _action_reset_plan(envelope: dict[str, Any]) -> dict[str, Any]:
    raw = _reset_plan_raw(envelope)
    evidence = convert_workflow_evolution(raw, envelope)
    if isinstance(raw.get("policy_decision"), dict):
        evidence = _attach_policy_decision(evidence, raw["policy_decision"])
    return evidence


def _run_wiki_lint_report(wiki_root: Path, output_dir: Path) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    lint_tool = REPO_HARNESS_DIR.parent / "tools" / "lint.py"
    command = [sys.executable, str(lint_tool), "--wiki-root", str(wiki_root)]
    artifacts: list[dict[str, Any]] = []
    payload: dict[str, Any]
    stdout = ""
    stderr = ""
    returncode = 127
    if not lint_tool.exists():
        payload = {
            "schema": "autosci_wiki_lint_cli.v1",
            "ok": False,
            "status": "failed",
            "wiki_root": str(wiki_root),
            "page_count": 0,
            "edge_count": 0,
            "issues": [{"severity": "error", "message": f"lint tool not found: {lint_tool}"}],
        }
    else:
        proc = subprocess.run(
            command,
            cwd=REPO_HARNESS_DIR.parent,
            env={**os.environ, "PYTHONIOENCODING": "utf-8"},
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            check=False,
        )
        returncode = proc.returncode
        stdout = proc.stdout
        stderr = proc.stderr
        try:
            parsed = json.loads(stdout)
            payload = parsed if isinstance(parsed, dict) else {
                "schema": "autosci_wiki_lint_cli.v1",
                "ok": False,
                "status": "failed",
                "wiki_root": str(wiki_root),
                "page_count": 0,
                "edge_count": 0,
                "issues": [{"severity": "error", "message": "lint JSON output was not an object"}],
            }
        except json.JSONDecodeError as exc:
            payload = {
                "schema": "autosci_wiki_lint_cli.v1",
                "ok": False,
                "status": "failed",
                "wiki_root": str(wiki_root),
                "page_count": 0,
                "edge_count": 0,
                "issues": [{"severity": "error", "message": f"lint JSON parse failed: {exc}"}],
                "stdout_preview": stdout[:1000],
            }
    issues = payload.get("issues") if isinstance(payload.get("issues"), list) else []
    issue_counts = {
        "error": sum(1 for issue in issues if isinstance(issue, dict) and str(issue.get("severity") or "") == "error"),
        "warn": sum(1 for issue in issues if isinstance(issue, dict) and str(issue.get("severity") or "") == "warn"),
        "info": sum(1 for issue in issues if isinstance(issue, dict) and str(issue.get("severity") or "") == "info"),
    }
    payload.update(
        {
            "command": command,
            "returncode": returncode,
            "issue_counts": issue_counts,
        }
    )
    lint_report_path = output_dir / "wiki_lint_report.json"
    lint_report_ref = _write_json_sidecar(lint_report_path, payload)
    artifacts.append({"type": "wiki_lint_report_json", "path": lint_report_ref})
    if stderr.strip():
        stderr_ref = _write_text_sidecar(output_dir / "wiki_lint_stderr.log", stderr)
        artifacts.append({"type": "wiki_lint_stderr", "path": stderr_ref})
    return payload, artifacts


def _check_final_quality_boundary(findings: dict[str, Any], model_output: dict[str, Any]) -> dict[str, Any]:
    local_blocking: list[str] = []
    if not findings.get("root_exists"):
        local_blocking.append("wiki root is missing")
    if int(findings.get("markdown_page_count") or 0) <= 0:
        local_blocking.append("wiki markdown pages are missing")
    missing_dirs = list(findings.get("missing_dirs") or [])
    if missing_dirs:
        local_blocking.append(f"wiki directories are missing: {', '.join(str(item) for item in missing_dirs)}")
    edge_errors = list(findings.get("edge_errors") or [])
    if edge_errors:
        local_blocking.append("wiki graph edges are missing or invalid")
    lint_report = findings.get("lint_report") if isinstance(findings.get("lint_report"), dict) else {}
    lint_counts = lint_report.get("issue_counts") if isinstance(lint_report.get("issue_counts"), dict) else {}
    lint_error_count = int(lint_counts.get("error") or 0)
    if lint_error_count:
        local_blocking.append(f"native wiki lint reported {lint_error_count} error issue(s)")
    model_findings = [item for item in model_output.get("findings") or [] if isinstance(item, dict)]
    model_provenance_ready = bool(
        str(model_output.get("source") or "").strip()
        and str(model_output.get("model") or model_output.get("provider") or "").strip()
    )
    model_ready = (
        model_output.get("status") == "completed"
        and bool(str(model_output.get("answer") or "").strip())
        and bool(model_output.get("evidence_ids"))
        and bool(model_findings)
        and float(model_output.get("confidence") or 0.0) > 0.0
        and model_provenance_ready
    )
    blocking_reasons = [*local_blocking]
    if not model_ready:
        blocking_reasons.append(
            f"model quality review status is `{model_output.get('status') or 'missing'}`, not completed with answer, findings, confidence, provenance, and evidence ids"
        )
    final_quality_ready = not blocking_reasons
    return {
        "schema": "autosci_check_final_quality_boundary.v1",
        "status": "final_quality_ready" if final_quality_ready else "check_final_quality_incomplete",
        "final_quality_ready": final_quality_ready,
        "local_structure_ready": not local_blocking,
        "local_blocking_reasons": local_blocking,
        "model_status": str(model_output.get("status") or "missing"),
        "model_source": str(model_output.get("source") or ""),
        "model_provider": str(model_output.get("provider") or ""),
        "model_name": str(model_output.get("model") or ""),
        "model_confidence": model_output.get("confidence", "N/A"),
        "model_finding_count": len(model_findings),
        "model_provenance_ready": model_provenance_ready,
        "model_evidence_ids": _unique_strings([str(item) for item in model_output.get("evidence_ids") or []]),
        "request_sha256": str(model_output.get("request_sha256") or ""),
        "response_sha256": str(model_output.get("response_sha256") or ""),
        "blocking_reasons": blocking_reasons,
        "limitations": [] if final_quality_ready else [
            "Final wiki quality readiness requires passing local wiki checks plus completed model-backed recommendation evidence."
        ],
    }


def _wiki_health_raw(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    target = str(inputs.get("target") or inputs.get("wiki_root") or "autosci wiki")
    paths = _control_workflow_paths(envelope, "check_wiki_health")
    paths["patch_candidates"].mkdir(parents=True, exist_ok=True)
    roots = _wiki_roots_for_read(envelope)
    existing_roots = [root for root in roots if root.exists()]
    primary = existing_roots[0] if existing_roots else roots[0]
    expected_dirs = ["papers", "methods", "ideas", "experiments", "outputs", "graph"]
    missing_dirs = [name for name in expected_dirs if not (primary / name).is_dir()]
    markdown_pages = sorted(primary.rglob("*.md")) if primary.exists() else []
    edge_errors: list[dict[str, Any]] = []
    edges_path = primary / "graph" / "edges.jsonl"
    if edges_path.exists():
        for index, line in enumerate(edges_path.read_text(encoding="utf-8", errors="replace").splitlines(), start=1):
            if not line.strip():
                continue
            try:
                payload = json.loads(line)
            except json.JSONDecodeError as exc:
                edge_errors.append({"line": index, "error": str(exc)})
                continue
            legacy_ready = all(str(payload.get(field) or "").strip() for field in ("source", "target", "relation"))
            lint_ready = all(str(payload.get(field) or "").strip() for field in ("from", "to", "type"))
            if not (legacy_ready or lint_ready):
                edge_errors.append({"line": index, "error": "missing source/target/relation or from/to/type"})
    elif primary.exists():
        edge_errors.append({"line": 0, "error": "graph/edges.jsonl is missing"})
    evidence_ids = [f"check-wiki:{_slug(target)}", _rel(primary)]
    findings = {
        "target": target,
        "wiki_root": _rel(primary),
        "root_exists": primary.exists(),
        "checked_roots": [_rel(root) for root in roots],
        "markdown_page_count": len(markdown_pages),
        "missing_dirs": missing_dirs,
        "edge_errors": edge_errors,
    }
    lint_report, lint_artifacts = _run_wiki_lint_report(primary, paths["recommended_changes"].parent)
    lint_counts = lint_report.get("issue_counts") if isinstance(lint_report.get("issue_counts"), dict) else {}
    findings["lint_report"] = {
        "schema": str(lint_report.get("schema") or ""),
        "status": str(lint_report.get("status") or ""),
        "ok": bool(lint_report.get("ok")),
        "returncode": lint_report.get("returncode"),
        "wiki_root": str(lint_report.get("wiki_root") or ""),
        "page_count": int(lint_report.get("page_count") or 0),
        "edge_count": int(lint_report.get("edge_count") or 0),
        "issue_counts": lint_counts,
    }
    model_output, model_artifacts = _model_output(
        envelope,
        action="check_wiki_health",
        prompt=target,
        context={"target": target, "findings": findings},
    )
    model_completed = model_output.get("status") == "completed"
    findings["model_output"] = model_output
    evidence_ids = _unique_strings([
        *evidence_ids,
        *[str(item) for item in model_output.get("evidence_ids") or []],
    ])
    runtime_errors: list[dict[str, Any]] = []
    if not primary.exists():
        runtime_errors.append({"id": "wiki-root-missing", "description": f"Wiki root does not exist: {_rel(primary)}"})
    if not markdown_pages:
        runtime_errors.append({"id": "wiki-pages-missing", "description": "No Markdown wiki pages were found."})
    if missing_dirs:
        runtime_errors.append({"id": "wiki-dirs-missing", "description": f"Missing wiki directories: {', '.join(missing_dirs)}"})
    if edge_errors:
        runtime_errors.append({"id": "wiki-edges-invalid", "description": "Graph edge file is missing or contains invalid rows."})
    lint_error_count = int(lint_counts.get("error") or 0)
    if lint_error_count:
        runtime_errors.append({"id": "wiki-lint-errors", "description": f"Native wiki lint reported {lint_error_count} error issue(s)."})
    if not runtime_errors and not model_completed:
        runtime_errors.append({"id": "wiki-health-review", "description": "Structural checks passed; content quality still requires model/reviewer evidence."})
    final_boundary = _check_final_quality_boundary(findings, model_output)
    final_boundary_path = paths["recommended_changes"].parent / "quality_boundary.json"
    final_boundary_artifact = _write_json_sidecar(final_boundary_path, final_boundary)
    quality_reasons = [item["description"] for item in runtime_errors]
    if not quality_reasons:
        quality_reasons = [f"Model/reviewer evidence completed via `{model_output.get('source') or model_output.get('provider') or 'explicit evidence'}`."]
    collected = {
        "failed_nodes": [
            {
                "node_id": "node-check-wiki-health",
                "logical_operator": "ScientificWorkflowEvolver",
                "status": "inconclusive" if runtime_errors else "completed",
                "gate": "wiki_health_check",
            }
        ],
        "gate_rejection_reasons": [
            {
                "gate_id": "wiki_health_check",
                "status": "passed" if not runtime_errors else "inconclusive",
                "reasons": quality_reasons,
            }
        ],
        "ambiguous_manuals_or_prompts": []
        if model_completed
        else [
            {
                "id": "check.content-quality",
                "description": "LLM-assisted content quality checks are not deterministic without model output evidence.",
            }
        ],
        "insufficient_schemas": [],
        "poor_operator_bindings": [],
        "human_intervention_points": [],
        "runtime_errors": runtime_errors,
    }
    proposed_changes = [
        {
            "change_id": "change.manual.wiki-health-evidence",
            "category": "manual",
            "target": "wiki health check",
            "description": "Require source-attributed model/reviewer evidence before marking content quality checks complete.",
            "evidence_ids": evidence_ids,
            "review_required": True,
            "application_state": "proposed_only",
        },
        {
            "change_id": "change.gate.wiki-structure-diagnostics",
            "category": "gate",
            "target": "wiki structural gate",
            "description": "Keep missing wiki directories, missing pages, or invalid graph edges visible as explicit diagnostics.",
            "evidence_ids": evidence_ids,
            "review_required": True,
            "application_state": "proposed_only",
        },
    ]
    markdown = "\n".join(
        [
            "# Wiki Health Check",
            "",
            f"Wiki root: `{_rel(primary)}`",
            f"Markdown pages: `{len(markdown_pages)}`",
            f"Missing dirs: `{', '.join(missing_dirs) if missing_dirs else 'N/A'}`",
            f"Edge errors: `{len(edge_errors)}`",
            f"Native lint errors: `{int(lint_counts.get('error') or 0)}`",
            f"Native lint warnings: `{int(lint_counts.get('warn') or 0)}`",
            f"Native lint info: `{int(lint_counts.get('info') or 0)}`",
            "",
            "## Model Evidence",
            "",
            f"Status: `{model_output.get('status')}`",
            f"Source: `{model_output.get('source', 'N/A')}`",
            f"Answer: {model_output.get('answer', 'N/A') if model_completed else 'N/A'}",
            "",
            "## Final Quality Boundary",
            "",
            f"Status: `{final_boundary.get('status')}`",
            f"Final quality ready: `{final_boundary.get('final_quality_ready')}`",
            "",
            "## Findings JSON",
            "",
            "```json",
            json.dumps(findings, indent=2, sort_keys=True),
            "```",
            "",
        ]
    )
    _write_text_sidecar(paths["recommended_changes"], markdown)
    evidence_payload_path = _configured_output_path(
        envelope,
        "evidence_payload_path",
        _output_dir(envelope, "check_wiki_health") / "check_wiki_health.evidence.json",
        legacy_key="evidence_path",
        legacy_suffix=".json",
    )
    model_runtime_proof_artifact = _write_model_runtime_proof_manifest(
        envelope,
        action="check_wiki_health",
        native_skill="check",
        evidence_path=evidence_payload_path,
        model_output=model_output,
    )
    artifacts = [
        _artifact("recommended_changes_markdown", paths["recommended_changes"]),
        _artifact("patch_candidates_directory", paths["patch_candidates"]),
        {"type": "check_final_quality_boundary_json", "path": final_boundary_artifact},
        *lint_artifacts,
        *model_artifacts,
    ]
    if model_runtime_proof_artifact is not None:
        artifacts.append(model_runtime_proof_artifact)
    return {
        "proposal_id": f"check-wiki-health-{_slug(target)}",
        "scope": "wiki health check",
        "change_type": "gate",
        "rationale": "Local wiki structure and graph diagnostics were checked without mutating wiki state.",
        "expected_effect": "Keep wiki health gaps visible while requiring model evidence for content quality conclusions.",
        "approval_state": "proposed",
        "evidence_ids": evidence_ids,
        "collected": collected,
        "proposed_changes": proposed_changes,
        "review": {
            "human_accept_reject_required": True,
            "protected_core_edits_applied": False,
            "application_state": "proposed_only",
            "approval_ref": "N/A",
            "final_quality_boundary": final_boundary,
        },
        "recommended_changes_path": _rel(paths["recommended_changes"]),
        "patch_candidates_path": _rel(paths["patch_candidates"]),
        "artifacts": artifacts,
        "limitations": [
            "Wiki health check is structural and local only.",
            *list(final_boundary.get("limitations") or []),
            (
                "LLM-assisted content quality evidence was supplied and archived."
                if model_completed
                else "LLM-assisted content quality checks require supplied model output evidence."
            ),
        ],
    }


def _action_check_wiki_health(envelope: dict[str, Any]) -> dict[str, Any]:
    return convert_workflow_evolution(_wiki_health_raw(envelope), envelope)


def _action_refine_artifact(envelope: dict[str, Any]) -> dict[str, Any]:
    raw = _control_workflow_raw(envelope, "refine_artifact", "artifact refinement")
    evidence = convert_workflow_evolution(raw, envelope)
    if isinstance(raw.get("policy_decision"), dict):
        evidence = _attach_policy_decision(evidence, raw["policy_decision"])
