def _action_run_research_lifecycle(envelope: dict[str, Any]) -> dict[str, Any]:
    raw = _research_lifecycle_raw(envelope)
    evidence = convert_workflow_evolution(raw, envelope)
    if isinstance(raw.get("policy_decision"), dict):
        evidence = _attach_policy_decision(evidence, raw["policy_decision"])
    if isinstance(raw.get("side_effect_access_request"), dict) and isinstance(raw.get("side_effect_access_artifact"), dict):
        evidence = _attach_side_effect_access_request(
            evidence,
            raw["side_effect_access_request"],
            raw["side_effect_access_artifact"],
        )
    return evidence



def _run_visualize_tool(
    tool_path: Path,
    args: list[str],
    *,
    output_dir: Path,
    artifact_prefix: str,
) -> tuple[int, dict[str, Any], list[dict[str, str]]]:
    command = [sys.executable, str(tool_path), *args]
    timeout = int(os.environ.get("AUTOSCI_VISUALIZE_TIMEOUT_SECONDS", "20"))
    try:
        proc = subprocess.run(
            command,
            cwd=REPO_HARNESS_DIR.parent,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            check=False,
            timeout=timeout,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        proc_stdout = json.dumps({"status": "error", "detail": str(exc)}, sort_keys=True)
        stdout_path = _write_text_sidecar(output_dir / f"{artifact_prefix}_stdout.json", proc_stdout)
        stderr_path = _write_text_sidecar(output_dir / f"{artifact_prefix}_stderr.txt", str(exc))
        return 1, {"status": "failed"}, [
            {"type": f"{artifact_prefix}_stdout_json", "path": stdout_path},
            {"type": f"{artifact_prefix}_stderr", "path": stderr_path},
        ]

    stdout_path = _write_text_sidecar(
        output_dir / f"{artifact_prefix}_stdout.json",
        proc.stdout,
    )
    stderr_path = _write_text_sidecar(
        output_dir / f"{artifact_prefix}_stderr.txt",
        proc.stderr,
    )
    payload: dict[str, Any] = {}
    if proc.stdout:
        try:
            payload = json.loads(proc.stdout)
        except json.JSONDecodeError:
            payload = {"status": "non_json_stdout", "raw": proc.stdout[:512]}
    if not isinstance(payload, dict):
        payload = {}
    artifacts = [
        {"type": f"{artifact_prefix}_stdout_json", "path": stdout_path},
        {"type": f"{artifact_prefix}_stderr", "path": stderr_path},
    ]
    return proc.returncode, payload, artifacts


def _normalize_visualization_edges(raw_edges: list[dict[str, Any]], fallback: list[str]) -> list[dict[str, Any]]:
    edges: list[dict[str, Any]] = []
    for item in raw_edges:
        source = str(item.get("source") or "").strip()
        target = str(item.get("target") or "").strip()
        relation = str(item.get("relation") or "visualizes").strip() or "visualizes"
        if not source or not target:
            continue
        operation = str(item.get("operation") or "confirm").strip() or "confirm"
        if operation not in {"add", "remove", "confirm", "propose", "no_op"}:
            operation = "confirm"
        edge = {
            "source": source,
            "target": target,
            "relation": relation,
            "operation": operation,
            "evidence_ids": list(dict.fromkeys([
                *([str(itemv) for itemv in item.get("evidence_ids") if str(itemv).strip()] if isinstance(item.get("evidence_ids"), list) else []),
                *fallback,
            ])),
            "rendered": bool(item.get("rendered") or "rendered" in item) if isinstance(item.get("rendered"), bool) else False,
        }
        edges.append(edge)
    if not edges:
        edges.append({
            "source": fallback[0] if fallback else "visualize:autosci-graph",
            "target": str(raw_edges[0].get("target") if raw_edges else "autosci-graph"),
            "relation": "proposes_visualization_for",
            "operation": "propose",
            "evidence_ids": fallback,
            "rendered": False,
        })
    return edges


def _visualize_graph_artifacts(
    envelope: dict[str, Any],
    target: str,
    slug: str,
) -> tuple[dict[str, Any], list[dict[str, str]], list[str], dict[str, Any], dict[str, Any]]:
    inputs = dict(envelope.get("inputs") or {})
    wiki_root = _resolve_harness_path(inputs.get("wiki_root") or "artifacts/autosci/workspace/wiki")
    output_dir = _output_dir(envelope, "visualize_graph")
    output_dir.mkdir(parents=True, exist_ok=True)
    slug_tag = f"visualize-{slug}"
    obsidian_out = wiki_root / ".obsidian" / "graph.json"
    focus = str(inputs.get("focus") or "").strip()
    depth = int(inputs.get("depth") or 2)
    node_types = str(inputs.get("types") or "").strip()
    edge_types = str(inputs.get("edge_types") or "").strip()
    mode_all = bool(inputs.get("all"))
    obsidian_requested = bool(inputs.get("obsidian"))
    canvas_requested = bool(inputs.get("canvas"))
    canvas_filter_requested = bool(focus or node_types or edge_types)
    no_explicit_mode = not any([mode_all, obsidian_requested, canvas_requested, canvas_filter_requested])
    generate_obsidian = mode_all or obsidian_requested or no_explicit_mode
    generate_canvas = mode_all or canvas_requested or canvas_filter_requested or no_explicit_mode
    canvas_name = f"focus-{focus.replace('/', '-')}.canvas" if focus else "knowledge-map.canvas"
    obsidian_app_out = wiki_root / ".obsidian" / "app.json"
    canvas_out = wiki_root / "canvases" / canvas_name
    graph_out = output_dir / "autosci_web_graph.json"
    status_reasons: list[str] = []
    evidence_ids = [f"visualize:{slug}", slug_tag, target]

    artifacts: list[dict[str, str]] = []
    if generate_obsidian:
        return_code, _payload, obsidian_artifacts = _run_visualize_tool(
            REPO_HARNESS_DIR.parent / "tools" / "visualize.py",
            ["generate-obsidian-config", "--wiki-root", str(wiki_root), "--out", str(obsidian_out)],
            output_dir=output_dir,
            artifact_prefix="visualize_obsidian_config",
        )
        artifacts.extend(obsidian_artifacts)
        if return_code != 0:
            status_reasons.append("Obsidian graph config generation failed.")

    canvas_payload: dict[str, Any] = {}
    if generate_canvas:
        canvas_args = [
            "generate-canvas",
            "--wiki-root",
            str(wiki_root),
            "--graph-out",
            str(graph_out),
            "--out",
            str(canvas_out),
        ]
        if focus:
            canvas_args.extend(["--focus", focus])
        if depth:
            canvas_args.extend(["--depth", str(depth)])
        if node_types:
            canvas_args.extend(["--types", node_types])
        if edge_types:
            canvas_args.extend(["--edge-types", edge_types])
        _, canvas_payload, canvas_artifacts = _run_visualize_tool(
            REPO_HARNESS_DIR.parent / "tools" / "visualize.py",
            canvas_args,
            output_dir=output_dir,
            artifact_prefix="visualize_canvas",
        )
        artifacts.extend(canvas_artifacts)
        if not canvas_payload:
            status_reasons.append("AutoSci canvas generation produced no structured output.")
        elif int(canvas_payload.get("nodes") or 0) == 0 and int(canvas_payload.get("edges") or 0) == 0:
            status_reasons.append("AutoSci canvas generation produced no nodes or edges.")

    graph_payload: dict[str, Any] = {}
    graph_args = ["graph-data", "--wiki-root", str(wiki_root), "--out", str(graph_out)]
    if focus:
        graph_args.extend(["--focus", focus])
    if depth:
        graph_args.extend(["--depth", str(depth)])
    if node_types:
        graph_args.extend(["--types", node_types])
    if edge_types:
        graph_args.extend(["--edge-types", edge_types])
    code, graph_payload, graph_artifacts = _run_visualize_tool(
        REPO_HARNESS_DIR.parent / "tools" / "visualize.py",
        graph_args,
        output_dir=output_dir,
        artifact_prefix="visualize_graph_data",
    )
    artifacts.extend(graph_artifacts)
    if code != 0:
        status_reasons.append("Graph data extraction failed.")
    elif not graph_payload.get("nodes") and not graph_payload.get("edges"):
        status_reasons.append("Graph data extraction produced no nodes or edges.")

    graph_edges = graph_payload.get("edges") if isinstance(graph_payload.get("edges"), list) else []
    edges = _normalize_visualization_edges(
        [edge for edge in graph_edges if isinstance(edge, dict)],
        [f"visualize:{slug}", slug_tag, target],
    )

    rec_code, _rec_payload, rec_artifacts = _run_visualize_tool(
        REPO_HARNESS_DIR.parent / "tools" / "visualize.py",
        ["list-recommendations"],
        output_dir=output_dir,
        artifact_prefix="visualize_recommendations",
    )
    artifacts.extend(rec_artifacts)
    if rec_code != 0:
        status_reasons.append("Visualization recommendations command failed.")

    if generate_obsidian and not obsidian_out.exists():
        status_reasons.append("Obsidian config artifact was not created.")
    if generate_canvas and not canvas_out.exists():
        status_reasons.append("Canvas artifact was not created.")
    if not graph_out.exists():
        status_reasons.append("Graph data artifact was not created.")

    serve_payload: dict[str, Any] = {}
    side_effects = ["obsidian_canvas_write", "local_web_server", "graph_read"]
    policy_decision = _gate_decision(
        envelope,
        "visualize_graph",
        ["read_local", "write_artifact", "wiki_mutation", "local_command", "browser_render"],
    )
    policy_artifact = _write_policy_decision_sidecar(envelope, "visualize_graph", policy_decision)
    artifacts.append(policy_artifact)
    contract = _approval_contract(envelope, "visualize_graph", side_effects)
    native_options = inputs.get("native_options") if isinstance(inputs.get("native_options"), dict) else {}
    serve_requested = bool(inputs.get("serve_requested") or inputs.get("serve") or native_options.get("serve"))
    policy_auto_execute = serve_requested and bool(policy_decision.get("execute_side_effects"))
    if policy_auto_execute:
        contract = _apply_policy_approval_to_contract(contract, policy_decision, policy_artifact)
    serve_success = False
    execute_requested = bool(inputs.get("execute_approved_side_effect")) or policy_auto_execute
    if execute_requested and contract.get("ready_for_execution"):
        serve_args = ["--wiki-root", str(wiki_root)]
        if policy_auto_execute and not bool(inputs.get("execute_approved_side_effect")):
            serve_args.extend(["--probe-server", "--port", "0"])
        else:
            serve_args.append("--health-check")
        code, serve_payload, serve_artifacts = _run_visualize_tool(
            REPO_HARNESS_DIR.parent / "tools" / "serve.py",
            serve_args,
            output_dir=output_dir,
            artifact_prefix="visualize_web_health",
        )
        artifacts.extend(serve_artifacts)
        serve_success = (
            code == 0
            and serve_payload.get("ok") is True
            and str(serve_payload.get("status") or "") == "completed"
        )
        if not serve_success:
            status_reasons.append("Local web health check execution failed.")
    elif execute_requested:
        status_reasons.append("Local web health check was not executed because approval preflight was incomplete.")
    if serve_payload:
        serve_health_rel = _write_json_sidecar(output_dir / "visualize_web_health.json", serve_payload)
        serve_health_artifact = {"type": "visualize_web_health_json", "path": serve_health_rel}
        artifacts.append(serve_health_artifact)
        if serve_success:
            contract.setdefault("runtime_evidence", []).append({
                "path": serve_health_rel,
                "artifact_path": serve_health_rel,
                "exists": True,
                "kind": "file",
                "verifiable": True,
            })
            contract.setdefault("after_artifacts", []).append({
                "path": serve_health_rel,
                "artifact_path": serve_health_rel,
                "exists": True,
                "kind": "file",
                "verifiable": True,
            })
            for path in (graph_out, obsidian_out, canvas_out):
                if path.exists():
                    contract.setdefault("after_artifacts", []).append({
                        "path": _rel(path),
                        "artifact_path": _rel(path),
                        "exists": True,
                        "kind": "file",
                        "verifiable": True,
                    })
            contract = _refresh_approval_contract(contract)
    else:
        contract = _refresh_approval_contract(contract)
    if graph_out.exists():
        artifacts.append(_artifact("autosci_web_graph_json", graph_out))
    if generate_obsidian and obsidian_out.exists():
        artifacts.append(_artifact("obsidian_graph_config_json", obsidian_out))
    if generate_obsidian and obsidian_app_out.exists():
        artifacts.append(_artifact("obsidian_app_config_json", obsidian_app_out))
    if generate_canvas and canvas_out.exists():
        artifacts.append(_artifact("autosci_canvas_json", canvas_out))
    generated = [
        artifact["type"]
        for artifact in artifacts
        if artifact.get("type") in {
            "autosci_web_graph_json",
            "obsidian_graph_config_json",
            "obsidian_app_config_json",
            "autosci_canvas_json",
            "visualize_web_health_json",
        }
    ]
    if generated:
        log_path = _write_generic_wiki_log(
            wiki_root,
            "AutoSci Visualize",
            graph_out,
            evidence_ids,
            "Generated visualization artifacts: " + ", ".join(generated),
        )
        artifacts.append({"type": "wiki_log", "path": _rel(log_path)})
        if serve_success:
            contract.setdefault("after_artifacts", []).append({
                "path": _rel(log_path),
                "artifact_path": _rel(log_path),
                "exists": True,
                "kind": "file",
                "verifiable": True,
            })
            contract = _refresh_approval_contract(contract)
    contract_artifact = _write_approval_contract_sidecar(envelope, "visualize_graph", contract)
    artifacts.append(contract_artifact)
    if serve_success:
        evidence_payload_path = _configured_output_path(
            envelope,
            "evidence_payload_path",
            _output_dir(envelope, "visualize_graph") / "visualize_graph.evidence.json",
            legacy_key="evidence_path",
            legacy_suffix=".json",
        )
        artifacts.extend(
            _write_approved_mutation_runtime_proof_manifests(
                envelope,
                action="visualize_graph",
                native_skill="visualize",
                evidence_path=evidence_payload_path,
                applied=True,
                contract=contract,
                contract_artifact=contract_artifact,
                source_refs=[],
                mutation_refs=[str(artifact.get("path") or "") for artifact in artifacts if isinstance(artifact, dict)],
                include_wiki_mutation=False,
                source_label="approved_visualize_web_health",
                artifact_kind="visualize_web_health",
                include_provider_source=False,
            )
        )

    status = "completed" if not status_reasons else "inconclusive"
    output = {
        "edges": edges,
        "evidence_ids": evidence_ids,
        "artifacts": artifacts,
        "status": status,
        "reason_count": len(status_reasons),
        "status_reasons": status_reasons,
        "obsidian_config": _rel(obsidian_out) if generate_obsidian else "",
        "canvas": _rel(canvas_out) if generate_canvas else "",
        "graph_data": _rel(graph_out),
        "visualize_options": {
            "all": mode_all or no_explicit_mode,
            "obsidian": generate_obsidian,
            "canvas": generate_canvas,
            "focus": focus,
            "depth": depth,
            "types": node_types,
            "edge_types": edge_types,
        },
    }
    return output, artifacts, status_reasons, contract, policy_decision


def _action_visualize_graph(envelope: dict[str, Any]) -> dict[str, Any]:
    inputs = dict(envelope.get("inputs") or {})
    target = str(inputs.get("target") or inputs.get("topic") or "autosci-graph")
    slug = _slug(target)
    raw_output, artifacts, status_reasons, contract, policy_decision = _visualize_graph_artifacts(
        envelope,
        target,
        slug,
    )
    limitations = ["Visualization artifacts are generated from local wiki graph state."]
    if policy_decision.get("execute_side_effects"):
        limitations.append(
            f"Auto-approved by gate policy mode `{policy_decision.get('mode')}`; no human approval was requested."
        )
    else:
        limitations.append("Local web serving, browser opening, and screenshot capture remain approval-gated side effects.")
    if not status_reasons:
        limitations.append("All requested visualization artifacts were generated from local wiki data.")
    else:
        limitations.extend(status_reasons)
    limitations.extend(_approval_contract_limitations(contract))
    contract_artifact = _write_approval_contract_sidecar(envelope, "visualize_graph", contract)
    if contract_artifact not in artifacts:
        artifacts.append(contract_artifact)
    output = {
        "paper_id": f"visualize-{slug}",
        "source_ref": target,
        "evidence_ids": [f"visualize:{slug}"],
        "edges": raw_output["edges"],
        "artifacts": artifacts,
        "limits": status_reasons,
        "status_reasons": status_reasons,
    }
    evidence = convert_research_graph_update({
        "paper_id": f"visualize-{slug}",
        "source_ref": target,
        "evidence_ids": [f"visualize:{slug}", slug],
        "status": "completed" if not status_reasons else "inconclusive",
        "edges": raw_output["edges"],
        "artifacts": artifacts,
        "limitations": limitations,
    }, envelope)
    evidence.setdefault("outputs", {})["source_ref"] = target
    evidence.setdefault("outputs", {})["status_reasons"] = status_reasons
    evidence.setdefault("outputs", {})["visualize_options"] = raw_output.get("visualize_options") or {}
    return _attach_policy_decision(evidence, policy_decision)


