def validate_evidence_payload(payload: dict[str, Any]) -> list[str]:
    errors = []
    missing = sorted(REQUIRED_EVIDENCE_FIELDS - set(payload))
    if missing:
        errors.append(f"missing required fields: {', '.join(missing)}")
    if payload.get("status") not in {"completed", "failed", "inconclusive"}:
        errors.append("status must be completed, failed, or inconclusive")
    provenance = payload.get("provenance")
    if not isinstance(provenance, dict):
        errors.append("provenance must be an object")
    else:
        for field in ("operator_id", "implementation_package", "timestamp"):
            if not provenance.get(field):
                errors.append(f"provenance.{field} is required")
    if not isinstance(payload.get("artifacts"), list):
        errors.append("artifacts must be an array")
    if not isinstance(payload.get("limitations"), list):
        errors.append("limitations must be an array")
    return errors


def cmd_run(args: argparse.Namespace) -> int:
    if args.action not in ACTIONS:
        print(f"ERROR: unsupported action: {args.action}", file=sys.stderr)
        return 2
    envelope = load_envelope(args.envelope, action=args.action)
    if str(envelope.get("mode") or "").strip().lower() != "fixture":
        load_local_provider_env(REPO_HARNESS_DIR / ".env")
    if getattr(args, "gate_mode", None):
        envelope.setdefault("inputs", {})["gate_mode"] = str(args.gate_mode)
    evidence = ACTIONS[args.action](envelope)
    extra: dict[str, Any] = {}
    if args.action in {"ingest_paper", "prepare_paper_source"}:
        sidecar_evidence_paths = _write_phase9_foundation_sidecars(envelope, evidence)
        extra["sidecar_evidence_paths"] = sidecar_evidence_paths
        wiki_registration_artifacts = _register_ingest_paper_wiki(envelope, evidence, sidecar_evidence_paths)
        if wiki_registration_artifacts:
            extra["wiki_registration_artifacts"] = wiki_registration_artifacts
        evidence = _attach_ingest_final_source_registration_boundary(envelope, evidence, sidecar_evidence_paths)
    if args.action == "evaluate_ideas":
        sidecar_paths = [_write_phase11_idea_memory_sidecar(envelope, evidence)]
        novelty_writeback_path = _write_novelty_writeback_sidecar(envelope, evidence)
        if novelty_writeback_path:
            sidecar_paths.append(novelty_writeback_path)
            extra["novelty_writeback_path"] = novelty_writeback_path
        extra["sidecar_evidence_paths"] = sidecar_paths
    if args.action == "write_report":
        extra.update(_write_phase14_publication_sidecars(envelope, evidence))
    if args.action == "evolve_workflow":
        artifacts = evidence.get("artifacts") if isinstance(evidence.get("artifacts"), list) else []
        for artifact in artifacts:
            if isinstance(artifact, dict) and artifact.get("type") == "recommended_changes_markdown":
                extra["recommended_changes_path"] = artifact.get("path")
            if isinstance(artifact, dict) and artifact.get("type") == "patch_candidates_directory":
                extra["patch_candidates_path"] = artifact.get("path")
    result = _write_result(args.action, envelope, evidence, extra_result_fields=extra)
    print(json.dumps(result, indent=2, sort_keys=True))
    return 0


def cmd_smoke(args: argparse.Namespace) -> int:
    envelope = normalize_envelope({
        "task_id": "task-autosci-smoke",
        "sprint_id": "sprint-autosci-phase4",
        "node_id": "node-autosci-smoke",
        "mode": "fixture",
        "output_dir": "artifacts/autosci/smoke",
        "inputs": {"fixture": "tests/plugins/autosci/fixtures/sample_autosci_raw_claims.json"},
    })
    evidence = _action_extract_claims(envelope)
    result = _write_result("smoke", envelope, evidence)
    print(json.dumps(result, indent=2, sort_keys=True))
    return 0


def cmd_validate(args: argparse.Namespace) -> int:
    path = Path(args.result)
    if not path.is_absolute():
        path = HARNESS_DIR / path
    data = _load_json(path)
    payload = data.get("evidence") if isinstance(data.get("evidence"), dict) else data
    errors = validate_evidence_payload(payload)
    out = {"ok": not errors, "path": _rel(path), "errors": errors}
    print(json.dumps(out, indent=2, sort_keys=True))
    return 0 if not errors else 1


def cmd_research(args: argparse.Namespace) -> int:
    """Run the opt-in production research route through the Solar orchestrator."""

    artifact_root = Path(args.artifact_root).expanduser().resolve()
    sources = list(args.source or [])
    try:
        input_classification = classify_research_input(
            prompt=args.prompt,
            sources=sources,
            import_evidence=list(args.import_evidence or []),
            run_mode=args.run_mode,
            explicit_workflow=args.workflow,
        )
        readiness = validate_request_constraints(args.prompt, input_classification)
        if readiness.get("status") == "needs_clarification":
            result = clarification_result(
                run_id=args.run_id,
                prompt=args.prompt,
                run_mode=args.run_mode,
                classification=input_classification,
                readiness=readiness,
            )
            print(json.dumps(result, indent=2, ensure_ascii=True, sort_keys=True))
            return 0
        prepared_seed_inputs, prepared_evidence = prepare_runtime_inputs(
            prompt=args.prompt,
            sources=sources,
            import_evidence=list(args.import_evidence or []),
            run_mode=args.run_mode,
            artifact_root=artifact_root,
            run_id=args.run_id,
            classification=input_classification,
        )
    except ResearchControlPlaneError as exc:
        result = error_result(run_id=args.run_id, prompt=args.prompt, run_mode=args.run_mode, error=exc)
        print(json.dumps(result, indent=2, ensure_ascii=True, sort_keys=True))
        return 2
    aliases = {
        # Semantic aliases are explicit metadata, never import/name guessing.
        "research_synthesis": {"web_fetch": "seed_fetch"},
        "literature_synthesis": {"source_discovery": "source_discovery"},
        "scientific_lifecycle": {"source_discovery": "literature_discover"},
        "workflow_evolution": {"workflow_evolve": "workflow_evolve"},
    }
    authorization = {
        "approved_capabilities": [],
        "allow_network": bool(args.allow_network),
        "allow_live_provider": bool(args.allow_live_provider),
        "approval_ref": str(args.approval_ref or ""),
        "secret_refs": [],
    }
    try:
        production_services = production_services_from_environment(workspace_root=artifact_root)
        secret_values = dict(production_services.get("secret_values") or {})
        authorization["secret_refs"] = sorted(secret_values)
        authorization["secret_values"] = secret_values
        evidence = list(prepared_evidence)
        if not evidence:
            evidence.extend(load_evidence_references(args.import_evidence or [], artifact_root=artifact_root))
        catalog = FileWorkflowCatalog(
            harness_root=REPO_HARNESS_DIR,
            selection_path=Path(args.workflow_selection),
            entrypoint_aliases=aliases,
        )
        runtime = SolarResearchRuntime(
            artifact_root=artifact_root,
            workflow_loader=catalog.load,
            operator_resolver=default_production_resolver(
                services=production_services,
                workspace_root=artifact_root,
            ),
            authorization=authorization,
        )
        result = runtime.run(
            prompt=args.prompt,
            run_id=args.run_id,
            seed_inputs=prepared_seed_inputs,
            run_mode="import_evidence" if input_classification.input_kind == "experiment_evidence" else args.run_mode,
            explicit_workflow=args.workflow or input_classification.workflow_kind,
            supplied_evidence=evidence,
            output_language=args.output_language,
            repository_paths=list(args.repository or []),
            max_steps=args.max_steps,
        )
        result["input_classification"] = input_classification.to_dict()
        if input_classification.input_kind == "experiment_evidence" and args.run_mode != "import_evidence":
            result["requested_run_mode"] = args.run_mode
    except Exception as exc:
        result = {
            "schema": "solar_research_runtime_result.v1",
            "run_id": args.run_id,
            "prompt": args.prompt,
            "run_mode": args.run_mode,
            "input_classification": input_classification.to_dict() if "input_classification" in locals() else {},
            "final_status": "failed",
            "error_type": type(exc).__name__,
            "error": str(exc),
        }
        print(json.dumps(result, indent=2, ensure_ascii=True, sort_keys=True))
        return 2
    print(json.dumps(result, indent=2, ensure_ascii=True, sort_keys=True))
    return 0 if result.get("final_status") not in {"failed", "blocked", "cancelled"} else 2


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="autosci_bridge.py",
        epilog="actions: " + ", ".join(sorted(ACTIONS)),
    )
    sub = parser.add_subparsers(dest="cmd", required=True)
    sub.add_parser("smoke", help="Run fixture-mode smoke conversion")
    validate = sub.add_parser("validate", help="Validate a bridge result or evidence payload")
    validate.add_argument("--result", required=True)
    research = sub.add_parser("research", help="Run the Solar-owned production research orchestrator")
    research.add_argument("--prompt", required=True, help="Complete, untruncated user request")
    research.add_argument("--run-id", required=True, help="Stable research run identity")
    research.add_argument("--run-mode", choices=["execute", "resume", "import_evidence"], default="execute")
    research.add_argument("--source", action="append", help="Explicit URL, PDF, Markdown, text, or topic source")
    research.add_argument("--repository", action="append", help="Optional code file or repository path for code-evidence mapping")
    research.add_argument("--import-evidence", action="append", help="Provenance-bearing evidence path below artifact-root")
    research.add_argument("--workflow", help="Explicit workflow kind when the user requested one")
    research.add_argument("--output-language", default="", help="Requested output language")
    research.add_argument("--artifact-root", required=True, help="Writable root for Solar run state and artifacts")
    research.add_argument("--workflow-selection", default=str(REPO_HARNESS_DIR / "config" / "research-workflow-selection.v1.json"))
    research.add_argument("--max-steps", type=int, default=100)
    research.add_argument("--allow-network", action="store_true")
    research.add_argument("--allow-live-provider", action="store_true")
    research.add_argument("--approval-ref")
    run = sub.add_parser("run", help="Run one fixture-mode backend action")
    run.add_argument("--action", required=True, choices=sorted(ACTIONS))
    run.add_argument("--envelope", required=True)
    run.add_argument(
        "--gate-mode",
        choices=["strict_hitl", "safe", "parity_demo", "unsafe_native", "autosci_native"],
        help="Override AutoSci side-effect gate mode for this bridge run",
    )
    return parser


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    if args.cmd == "smoke":
        return cmd_smoke(args)
    if args.cmd == "validate":
        return cmd_validate(args)
    if args.cmd == "research":
        return cmd_research(args)
    if args.cmd == "run":
        return cmd_run(args)
    parser.print_help()
    return 1


if __name__ == "__main__":
    raise SystemExit(main())
